  v_limit  integer := LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 200);
  v_offset integer := GREATEST(COALESCE(p_page, 1) - 1, 0)
                      * LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 200);
  v_asc    boolean := COALESCE(LOWER(p_sort_dir), 'asc') <> 'desc';
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH billing_inst AS (
    SELECT DISTINCT b.institution_id AS inst_id
    FROM public.billing_student_bills b
  ),
  scope AS (
    SELECT lp.id, lp.institution_id, lp.academic_year_id, lp.program_id,
           lp.semester_id, lp.section_id, lp.gender,
           lp.lifecycle_status, lp.first_name, lp.last_name,
           lp.roll_number, lp.register_number,
           lp.accommodation_type_id,
           (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL)
             AS uses_transport
    FROM public.learners_profiles lp
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_billing_institutions
           OR lp.institution_id IN (SELECT inst_id FROM billing_inst))
      AND (p_academic_year_id IS NULL OR lp.academic_year_id = p_academic_year_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
      AND (
        p_search IS NULL OR p_search = ''
        OR lp.roll_number ILIKE '%' || p_search || '%'
        OR lp.register_number ILIKE '%' || p_search || '%'
        OR (COALESCE(lp.first_name,'') || ' ' || COALESCE(lp.last_name,''))
             ILIKE '%' || p_search || '%'
      )
  ),
  agg AS (
    SELECT s.id AS learner_id,
           COUNT(b.id)::integer AS bill_count,
           COALESCE(SUM(b.final_amount), 0)::numeric AS total_billed
    FROM scope s
    LEFT JOIN public.billing_student_bills b
           ON b.student_id = s.id
          AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
          AND b.academic_year_id = COALESCE(p_academic_year_id, s.academic_year_id)
          AND (p_billing_category_id IS NULL
               OR b.item_category_id = p_billing_category_id)
    GROUP BY s.id
  ),
  final AS (
    SELECT s.id AS learner_id,
           s.roll_number::text        AS roll_number,
           s.register_number::text    AS register_number,
           TRIM(COALESCE(s.first_name,'') || ' ' || COALESCE(s.last_name,''))
                                      AS full_name,
           s.lifecycle_status::text   AS lifecycle_status,
           NULLIF(TRIM(s.gender), '')::text AS gender,
           s.institution_id           AS institution_id,
           i.name::text               AS institution_name,
           p.program_name             AS program_name,
           CASE
             WHEN sem.semester_name IS NULL AND sec.section_name IS NULL
               THEN NULL
             WHEN sec.section_name IS NULL THEN sem.semester_name::text
             WHEN sem.semester_name IS NULL THEN sec.section_name::text
             ELSE sem.semester_name::text || ' · ' || sec.section_name::text
           END                        AS semester_section,
           s.academic_year_id         AS academic_year_id,
           ay.academic_year_name::text AS academic_year_name,
           acc.name::text             AS accommodation_type,
           s.uses_transport           AS uses_transport,
           a.bill_count               AS bill_count,
           a.total_billed             AS total_billed,
           CASE
             WHEN COALESCE(p_academic_year_id, s.academic_year_id) IS NULL
               THEN 'cannot_evaluate'
             WHEN a.bill_count > 0 THEN 'generated'
             ELSE 'not_generated'
           END                        AS coverage_state
    FROM scope s
    JOIN agg a                           ON a.learner_id = s.id
    LEFT JOIN public.institutions        i   ON i.id   = s.institution_id
    LEFT JOIN public.programs            p   ON p.id   = s.program_id
    LEFT JOIN public.semesters           sem ON sem.id = s.semester_id
    LEFT JOIN public.sections            sec ON sec.id = s.section_id
    LEFT JOIN public.academic_years      ay  ON ay.id  = s.academic_year_id
    LEFT JOIN public.accommodation_types acc ON acc.id = s.accommodation_type_id
  ),
  filtered AS (
    SELECT * FROM final f
    WHERE p_coverage_state = 'all' OR f.coverage_state = p_coverage_state
  )
  SELECT f.learner_id, f.roll_number, f.register_number, f.full_name,
         f.lifecycle_status, f.gender, f.institution_id, f.institution_name,
         f.program_name, f.semester_section,
         f.academic_year_id, f.academic_year_name,
         f.accommodation_type, f.uses_transport,
         f.bill_count, f.total_billed, f.coverage_state,
         COUNT(*) OVER ()::bigint
  FROM filtered f
  ORDER BY
    -- text columns, ascending
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'academic_year_name' THEN f.academic_year_name
         WHEN 'accommodation_type' THEN f.accommodation_type
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'gender'             THEN f.gender
         WHEN 'coverage_state'     THEN f.coverage_state
       END
     END) ASC NULLS LAST,
    -- text columns, descending
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'academic_year_name' THEN f.academic_year_name
         WHEN 'accommodation_type' THEN f.accommodation_type
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'gender'             THEN f.gender
         WHEN 'coverage_state'     THEN f.coverage_state
       END
     END) DESC NULLS LAST,
    -- numeric columns, ascending
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'bill_count'   THEN f.bill_count::numeric
         WHEN 'total_billed' THEN f.total_billed
       END
     END) ASC NULLS LAST,
    -- numeric columns, descending
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'bill_count'   THEN f.bill_count::numeric
         WHEN 'total_billed' THEN f.total_billed
       END
     END) DESC NULLS LAST,
    -- stable tiebreaker; also the default when p_sort_by is null/unrecognised
    f.institution_name NULLS LAST, f.roll_number NULLS LAST, f.full_name
  LIMIT v_limit OFFSET v_offset;
END;
$$;

REVOKE ALL ON FUNCTION public.get_billing_coverage_learners(
  uuid, uuid[], text[], uuid, text, boolean, text, integer, integer, uuid[], text, text, text, text) FROM anon;
GRANT EXECUTE ON FUNCTION public.get_billing_coverage_learners(
  uuid, uuid[], text[], uuid, text, boolean, text, integer, integer, uuid[], text, text, text, text) TO authenticated;

-- Default "Freshers" semester + section A (2026-07-27): REMOVED 2026-08-05
-- (mig 20260805112640_freshers_drop_seed_trigger). The holding pen was retired --
-- seed_freshers_semester_for_program() and its programs_seed_freshers trigger are
-- dropped. First-year admits now go straight to the program first real term,
-- identified by initial_semester on every active program (mig 20260805112546).

-- Receipt void mechanics WITHOUT authorization (mig 20260729_receipt_
-- cancellation_approval). Extracted so the direct-void RPC and the cancellation
-- APPROVAL share one implementation -- duplicating the guards is how they drift
-- apart. Not callable directly: EXECUTE is revoked from everyone.
CREATE OR REPLACE FUNCTION public._fn_exec_receipt_void(
  p_receipt_id        uuid,
  p_reason            text,
  p_cancel_request_id uuid DEFAULT NULL
)
RETURNS TABLE(receipt_number text, bill_ids uuid[])
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_receipt public.billing_receipts%ROWTYPE;
  v_items   jsonb;
  v_bills   uuid[];
BEGIN
  SELECT * INTO v_receipt FROM public.billing_receipts WHERE id = p_receipt_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Receipt % not found (already voided or deleted)', p_receipt_id;
  END IF;

  -- Refunds cascade from billing_receipts: voiding would erase the record that
  -- money went back to the learner.
  IF EXISTS (SELECT 1 FROM public.billing_refunds WHERE receipt_id = p_receipt_id) THEN
    RAISE EXCEPTION 'Cannot void: this receipt has refunds recorded against it. Reverse the refund first.';
  END IF;

  -- Invoice items cascade too, leaving an invoice with a grand_total and no lines.
  IF EXISTS (SELECT 1 FROM public.billing_invoice_items WHERE receipt_id = p_receipt_id) THEN
    RAISE EXCEPTION 'Cannot void: this receipt is attached to an invoice. Cancel the invoice first.';
  END IF;

  -- An online receipt would come back: processSuccessfulPayment dedupes on
  -- payment_reference_number, so the next webhook or late-auth sweep re-creates it.
  IF v_receipt.payment_reference_number IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.payment_transactions t
    WHERE t.status = 'success'
      AND v_receipt.payment_reference_number IN (
            t.razorpay_payment_id, t.gateway_transaction_id, t.transaction_ref
          )
  ) THEN
    RAISE EXCEPTION 'Cannot void: this receipt settles a captured online payment (%). Issue a refund instead.',
      v_receipt.payment_reference_number;
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(ri)), '[]'::jsonb),
         COALESCE(array_agg(ri.bill_id), ARRAY[]::uuid[])
    INTO v_items, v_bills
  FROM public.billing_receipt_items ri
  WHERE ri.receipt_id = p_receipt_id;

  INSERT INTO public.billing_receipts_voided (
    id, receipt_number, receipt_date, student_id, institution_id, payment_mode,
    payment_reference_number, payment_amount, payment_paid_date, payer_name,
    payer_contact, accountant_id, payment_remarks, created_by, created_at,
    updated_at, items_snapshot, voided_by, void_reason, cancel_request_id
  ) VALUES (
    v_receipt.id, v_receipt.receipt_number, v_receipt.receipt_date,
    v_receipt.student_id, v_receipt.institution_id, v_receipt.payment_mode,
    v_receipt.payment_reference_number, v_receipt.payment_amount,
    v_receipt.payment_paid_date, v_receipt.payer_name, v_receipt.payer_contact,
    v_receipt.accountant_id, v_receipt.payment_remarks, v_receipt.created_by,
    v_receipt.created_at, v_receipt.updated_at, v_items, auth.uid(),
    trim(p_reason), p_cancel_request_id
  );

  DELETE FROM public.billing_receipts WHERE id = p_receipt_id;

  -- ::text is load-bearing -- receipt_number is varchar(50) and this signature
  -- says text; without the cast Postgres rejects the call with 42804.
  RETURN QUERY SELECT v_receipt.receipt_number::text, v_bills;
END;
$function$;

REVOKE ALL ON FUNCTION public._fn_exec_receipt_void(uuid, text, uuid) FROM PUBLIC, anon, authenticated;

-- Direct void: authorization here, mechanics in the helper above. Holding
-- billing.receipts.delete bypasses the cancellation approval flow, which is why
-- that key was revoked from Accountant Assistant.
CREATE OR REPLACE FUNCTION public.fn_void_billing_receipt(
  p_receipt_id uuid,
  p_reason     text
)
RETURNS TABLE(receipt_number text, bill_ids uuid[])
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst uuid;
BEGIN
  IF p_receipt_id IS NULL THEN
    RAISE EXCEPTION 'fn_void_billing_receipt: p_receipt_id must not be NULL';
  END IF;
  IF p_reason IS NULL OR length(trim(p_reason)) < 5 THEN
    RAISE EXCEPTION 'A reason of at least 5 characters is required to void a receipt';
  END IF;

  SELECT institution_id INTO v_inst FROM public.billing_receipts WHERE id = p_receipt_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Receipt % not found (already voided or deleted)', p_receipt_id;
  END IF;

  -- NOT is_admin(): that also matches profiles.role IN ('admin','super_admin',
  -- 'administrator'), which would let a non-super-admin void a receipt outright
  -- and skip the cancellation approval flow entirely.
  IF NOT (
    is_super_admin()
    OR (user_has_permission('billing.receipts.delete') AND role_has_institution_access(v_inst))
  ) THEN
    RAISE EXCEPTION 'Only a super admin can void a receipt directly - raise a cancellation request instead';
  END IF;

  RETURN QUERY SELECT * FROM public._fn_exec_receipt_void(p_receipt_id, p_reason, NULL);
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_void_billing_receipt(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fn_void_billing_receipt(uuid, text) TO authenticated, service_role;

-- Must UNION the void archive: this is the only receipt-number function that
-- uses MAX(), so without the archive it could rewind the sequence past a voided
-- receipt's number and hand the same number out twice.
CREATE OR REPLACE FUNCTION public.reset_receipt_number_sequence_for_year()
RETURNS void
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
    current_year TEXT;
    current_max INTEGER;
BEGIN
    current_year := EXTRACT(YEAR FROM NOW())::TEXT;

    SELECT COALESCE(MAX(CAST(SUBSTRING(receipt_number FROM 10) AS INTEGER)), 0)
    INTO current_max
    FROM (
        SELECT receipt_number FROM public.billing_receipts
        UNION ALL
        SELECT receipt_number FROM public.billing_receipts_voided
    ) all_receipts
    WHERE receipt_number LIKE 'RCP-' || current_year || '-%';

    PERFORM setval('billing_receipt_number_seq', current_max + 1, false);

    RAISE NOTICE 'Receipt number sequence reset for year %. Max was: %, Starting from: %',
        current_year, current_max, current_max + 1;
END;
$function$;

-- Receipt cancellation approval RPCs (mig 20260729_receipt_cancellation_approval).
-- Accounts staff RAISE a request; an approver DECIDES it. Approval is what
-- archives the receipt and reverts the bill, via _fn_exec_receipt_void above.
-- 3. Request a cancellation.
CREATE OR REPLACE FUNCTION public.fn_request_receipt_cancellation(
  p_receipt_id uuid,
  p_reason     text
)
RETURNS TABLE(request_id uuid, request_number text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_receipt public.billing_receipts%ROWTYPE;
  v_id      uuid;
  v_number  text;
  v_role    text;
  v_name    text;
  v_email   text;
  v_super   boolean;
BEGIN
  IF p_reason IS NULL OR length(trim(p_reason)) < 5 THEN
    RAISE EXCEPTION 'A reason of at least 5 characters is required';
  END IF;

  SELECT * INTO v_receipt FROM public.billing_receipts WHERE id = p_receipt_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Receipt % not found (already cancelled or deleted)', p_receipt_id;
  END IF;

  -- Super admins may raise too (they can also approve, just not their own).
  IF NOT (
    is_super_admin()
    OR (user_has_permission('billing.receipts.cancel.request')
        AND role_has_institution_access(v_receipt.institution_id))
  ) THEN
    RAISE EXCEPTION 'Not authorized to request receipt cancellation for this institution';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.billing_receipt_cancel_requests
    WHERE receipt_id = p_receipt_id AND status = 'pending_approval'
  ) THEN
    RAISE EXCEPTION 'A cancellation request for this receipt is already awaiting approval';
  END IF;

  -- Same guards the approval will run: a request that could never be approved
  -- should fail here, not after sitting in the super admin's queue.
  IF EXISTS (SELECT 1 FROM public.billing_refunds WHERE receipt_id = p_receipt_id) THEN
    RAISE EXCEPTION 'Cannot cancel: this receipt has refunds recorded against it. Reverse the refund first.';
  END IF;
  IF EXISTS (SELECT 1 FROM public.billing_invoice_items WHERE receipt_id = p_receipt_id) THEN
    RAISE EXCEPTION 'Cannot cancel: this receipt is attached to an invoice. Cancel the invoice first.';
  END IF;
  IF v_receipt.payment_reference_number IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.payment_transactions t
    WHERE t.status = 'success'
      AND v_receipt.payment_reference_number IN (
            t.razorpay_payment_id, t.gateway_transaction_id, t.transaction_ref)
  ) THEN
    RAISE EXCEPTION 'Cannot cancel: this receipt settles a captured online payment (%). Issue a refund instead.',
      v_receipt.payment_reference_number;
  END IF;

  v_number := 'RCX-' || EXTRACT(YEAR FROM NOW())::text || '-'
              || LPAD(nextval('billing_receipt_cancel_number_seq')::text, 6, '0');

  SELECT p.full_name, p.email, COALESCE(p.is_super_admin, false)
    INTO v_name, v_email, v_super
  FROM public.profiles p WHERE p.id = auth.uid();

  SELECT cr.role_name INTO v_role
  FROM public.user_roles ur JOIN public.custom_roles cr ON cr.id = ur.role_id
  WHERE ur.user_id = auth.uid() LIMIT 1;

  INSERT INTO public.billing_receipt_cancel_requests (
    request_number, receipt_id, institution_id, student_id, receipt_snapshot,
    reason, requested_by, requested_by_name, requested_by_email, requested_by_role
  ) VALUES (
    v_number, p_receipt_id, v_receipt.institution_id, v_receipt.student_id,
    jsonb_build_object('receipt_number', v_receipt.receipt_number,
                       'payment_amount', v_receipt.payment_amount,
                       'payment_mode',   v_receipt.payment_mode,
                       'receipt_date',   v_receipt.receipt_date,
                       'payer_name',     v_receipt.payer_name),
    trim(p_reason), auth.uid(), v_name, v_email, v_role
  ) RETURNING id INTO v_id;

  INSERT INTO public.billing_receipt_cancel_request_actions (
    request_id, action_type, actor_id, actor_role_name, actor_name, actor_email,
    actor_is_super_admin, notes
  ) VALUES (v_id, 'requested', auth.uid(), v_role, v_name, v_email, v_super, trim(p_reason));

  RETURN QUERY SELECT v_id, v_number;
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_request_receipt_cancellation(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fn_request_receipt_cancellation(uuid, text) TO authenticated, service_role;

-- 4. Approve / decline.
CREATE OR REPLACE FUNCTION public.fn_act_on_receipt_cancellation(
  p_request_id uuid,
  p_action     text,
  p_notes      text DEFAULT NULL
)
RETURNS TABLE(status text, receipt_number text, message text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_req   public.billing_receipt_cancel_requests%ROWTYPE;
  v_role  text;
  v_name  text;
  v_email text;
  v_desig text;
  v_num   text;
BEGIN
  IF p_action NOT IN ('approve','decline') THEN
    RAISE EXCEPTION 'p_action must be approve or decline';
  END IF;

  SELECT * INTO v_req FROM public.billing_receipt_cancel_requests
  WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cancellation request % not found', p_request_id;
  END IF;
  IF v_req.status <> 'pending_approval' THEN
    RAISE EXCEPTION 'This request is already %', v_req.status;
  END IF;

  -- SUPER ADMIN ONLY. Deliberately NOT is_admin(), which also matches
  -- profiles.role IN ('admin','super_admin','administrator') and would let
  -- plain admins decide. Deliberately no permission-key branch either: the key
  -- is revoked everywhere and removed from the catalog, so a key check here
  -- would be a silent no-op that looks like a control.
  IF NOT is_super_admin() THEN
    RAISE EXCEPTION 'Only a super admin can decide receipt cancellation requests';
  END IF;

  -- Separation of duties still applies: a super admin who raised the request
  -- cannot wave their own through.
  IF v_req.requested_by IS NOT NULL AND v_req.requested_by = auth.uid() THEN
    RAISE EXCEPTION 'You cannot approve your own cancellation request - another super admin must act on it';
  END IF;

  SELECT p.full_name, p.email, p.designation
    INTO v_name, v_email, v_desig
  FROM public.profiles p WHERE p.id = auth.uid();

  SELECT cr.role_name INTO v_role
  FROM public.user_roles ur JOIN public.custom_roles cr ON cr.id = ur.role_id
  WHERE ur.user_id = auth.uid() LIMIT 1;

  IF p_action = 'decline' THEN
    UPDATE public.billing_receipt_cancel_requests
       SET status='declined', decided_by=auth.uid(), decided_at=now(),
           decision_notes=p_notes, decided_by_name=v_name, decided_by_email=v_email,
           decided_by_role=v_role, decided_by_designation=v_desig,
           decided_by_is_super_admin=true, updated_at=now()
     WHERE id = p_request_id;
    INSERT INTO public.billing_receipt_cancel_request_actions
      (request_id, action_type, actor_id, actor_role_name, actor_name, actor_email,
       actor_is_super_admin, notes)
      VALUES (p_request_id, 'declined', auth.uid(), v_role, v_name, v_email, true, p_notes);
    RETURN QUERY SELECT 'declined'::text,
                        (v_req.receipt_snapshot->>'receipt_number')::text,
                        'Request declined.'::text;
    RETURN;
  END IF;

  -- The receipt vanishing between request and approval is TERMINAL, so close the
  -- request instead of leaving it stuck pending. Guard failures are different:
  -- those RAISE out of the helper and roll back, because they are fixable.
  IF NOT EXISTS (SELECT 1 FROM public.billing_receipts WHERE id = v_req.receipt_id) THEN
    UPDATE public.billing_receipt_cancel_requests
       SET status='failed', decided_by=auth.uid(), decided_at=now(),
           decision_notes='Receipt no longer exists at approval time',
           decided_by_name=v_name, decided_by_email=v_email, decided_by_role=v_role,
           decided_by_designation=v_desig, decided_by_is_super_admin=true, updated_at=now()
     WHERE id = p_request_id;
    INSERT INTO public.billing_receipt_cancel_request_actions
      (request_id, action_type, actor_id, actor_role_name, actor_name, actor_email,
       actor_is_super_admin, notes)
      VALUES (p_request_id, 'failed', auth.uid(), v_role, v_name, v_email, true,
              'Receipt no longer exists at approval time');
    RETURN QUERY SELECT 'failed'::text,
                        (v_req.receipt_snapshot->>'receipt_number')::text,
                        'The receipt no longer exists - it was already voided or deleted.'::text;
    RETURN;
  END IF;

  SELECT e.receipt_number INTO v_num
  FROM public._fn_exec_receipt_void(v_req.receipt_id, v_req.reason, p_request_id) e;

  UPDATE public.billing_receipt_cancel_requests
     SET status='approved', decided_by=auth.uid(), decided_at=now(),
         decision_notes=p_notes, decided_by_name=v_name, decided_by_email=v_email,
         decided_by_role=v_role, decided_by_designation=v_desig,
         decided_by_is_super_admin=true, updated_at=now()
   WHERE id = p_request_id;
  INSERT INTO public.billing_receipt_cancel_request_actions
    (request_id, action_type, actor_id, actor_role_name, actor_name, actor_email,
     actor_is_super_admin, notes)
    VALUES (p_request_id, 'approved', auth.uid(), v_role, v_name, v_email, true, p_notes);

  RETURN QUERY SELECT 'approved'::text, v_num::text,
                      'Receipt cancelled and the bill reverted.'::text;
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_act_on_receipt_cancellation(uuid, text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fn_act_on_receipt_cancellation(uuid, text, text) TO authenticated, service_role;

-- 5. Withdraw (initiator only, while pending).
CREATE OR REPLACE FUNCTION public.fn_withdraw_receipt_cancellation(
  p_request_id uuid,
  p_notes      text DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_req   public.billing_receipt_cancel_requests%ROWTYPE;
  v_name  text;
  v_email text;
  v_super boolean;
  v_role  text;
BEGIN
  SELECT * INTO v_req FROM public.billing_receipt_cancel_requests
  WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cancellation request % not found', p_request_id;
  END IF;
  IF v_req.status <> 'pending_approval' THEN
    RAISE EXCEPTION 'This request is already %', v_req.status;
  END IF;
  IF v_req.requested_by IS DISTINCT FROM auth.uid() AND NOT (is_super_admin() OR is_admin()) THEN
    RAISE EXCEPTION 'Only the requester can withdraw this request';
  END IF;

  -- Identity SNAPSHOT, matching the request/decide RPCs. Added 20260825140000:
  -- this insert used to write actor_id only, so a withdrawn request's History
  -- showed a badge and a timestamp with nobody attached. Snapshotted rather
  -- than joined live because a profile can be renamed, have its email changed
  -- or be deactivated long after the fact.
  SELECT p.full_name, p.email, COALESCE(p.is_super_admin, false)
    INTO v_name, v_email, v_super
  FROM public.profiles p WHERE p.id = auth.uid();

  SELECT cr.role_name INTO v_role
  FROM public.user_roles ur JOIN public.custom_roles cr ON cr.id = ur.role_id
  WHERE ur.user_id = auth.uid() LIMIT 1;

  -- Deliberately touches neither the receipt nor the bill: withdrawing drops
  -- the REQUEST, it does not cancel the receipt. Only approval reverses money.
  UPDATE public.billing_receipt_cancel_requests
     SET status='withdrawn', updated_at=now() WHERE id = p_request_id;
  INSERT INTO public.billing_receipt_cancel_request_actions
    (request_id, action_type, actor_id, actor_name, actor_email,
     actor_role_name, actor_is_super_admin, notes)
    VALUES (p_request_id, 'withdrawn', auth.uid(), v_name, v_email,
            v_role, v_super, p_notes);
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_withdraw_receipt_cancellation(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fn_withdraw_receipt_cancellation(uuid, text) TO authenticated, service_role;


-- Coverage RPCs with the academic-hierarchy filters
-- (mig 20260729_billing_coverage_hierarchy_filters).
-- APPENDED, not edited in place: this file already carries several older
-- copies of both functions and is replayed top-to-bottom, so the LAST
-- definition is the effective one. The DROPs below also clear the older
-- 14-arg / 8-arg signatures, which CREATE OR REPLACE would leave behind as
-- ambiguous overloads.
DROP FUNCTION IF EXISTS public.get_billing_coverage_learners(
  uuid, uuid[], text[], uuid, text, boolean, text, integer, integer,
  uuid[], text, text, text, text);

CREATE FUNCTION public.get_billing_coverage_learners(
  p_academic_year_id uuid DEFAULT NULL::uuid,
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_billing_category_id uuid DEFAULT NULL::uuid,
  p_coverage_state text DEFAULT 'not_generated'::text,
  p_include_non_billing_institutions boolean DEFAULT false,
  p_search text DEFAULT NULL::text,
  p_page integer DEFAULT 1,
  p_page_size integer DEFAULT 50,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_sort_by text DEFAULT NULL::text,
  p_sort_dir text DEFAULT 'asc'::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid
)
RETURNS TABLE(out_learner_id uuid, out_roll_number text, out_register_number text, out_full_name text, out_lifecycle_status text, out_gender text, out_institution_id uuid, out_institution_name text, out_program_name text, out_semester_section text, out_academic_year_id uuid, out_academic_year_name text, out_accommodation_type text, out_uses_transport boolean, out_bill_count integer, out_total_billed numeric, out_coverage_state text, out_total_count bigint)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst   uuid[];
  v_limit  integer := LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 200);
  v_offset integer := GREATEST(COALESCE(p_page, 1) - 1, 0)
                      * LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 200);
  v_asc    boolean := COALESCE(LOWER(p_sort_dir), 'asc') <> 'desc';
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH billing_inst AS (
    SELECT DISTINCT b.institution_id AS inst_id
    FROM public.billing_student_bills b
  ),
  scope AS (
    SELECT lp.id, lp.institution_id, lp.academic_year_id, lp.program_id,
           lp.semester_id, lp.section_id, lp.gender,
           lp.lifecycle_status, lp.first_name, lp.last_name,
           lp.roll_number, lp.register_number,
           lp.accommodation_type_id,
           (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL)
             AS uses_transport
    FROM public.learners_profiles lp
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_billing_institutions
           OR lp.institution_id IN (SELECT inst_id FROM billing_inst))
      AND (p_academic_year_id IS NULL OR lp.academic_year_id = p_academic_year_id)
      -- Academic hierarchy. Each level is independent here rather than nested:
      -- a learner row already carries every level, so filtering on the deepest
      -- selected one is sufficient and a mid-level NULL never drops rows.
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
      AND (
        p_search IS NULL OR p_search = ''
        OR lp.roll_number ILIKE '%' || p_search || '%'
        OR lp.register_number ILIKE '%' || p_search || '%'
        OR (COALESCE(lp.first_name,'') || ' ' || COALESCE(lp.last_name,''))
             ILIKE '%' || p_search || '%'
      )
  ),
  agg AS (
    SELECT s.id AS learner_id,
           COUNT(b.id)::integer AS bill_count,
           COALESCE(SUM(b.final_amount), 0)::numeric AS total_billed
    FROM scope s
    LEFT JOIN public.billing_student_bills b
           ON b.student_id = s.id
          AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
          AND b.academic_year_id = COALESCE(p_academic_year_id, s.academic_year_id)
          AND (p_billing_category_id IS NULL
               OR b.item_category_id = p_billing_category_id)
    GROUP BY s.id
  ),
  final AS (
    SELECT s.id AS learner_id,
           s.roll_number::text        AS roll_number,
           s.register_number::text    AS register_number,
           TRIM(COALESCE(s.first_name,'') || ' ' || COALESCE(s.last_name,''))
                                      AS full_name,
           s.lifecycle_status::text   AS lifecycle_status,
           NULLIF(TRIM(s.gender), '')::text AS gender,
           s.institution_id           AS institution_id,
           i.name::text               AS institution_name,
           p.program_name             AS program_name,
           CASE
             WHEN sem.semester_name IS NULL AND sec.section_name IS NULL
               THEN NULL
             WHEN sec.section_name IS NULL THEN sem.semester_name::text
             WHEN sem.semester_name IS NULL THEN sec.section_name::text
             ELSE sem.semester_name::text || ' · ' || sec.section_name::text
           END                        AS semester_section,
           s.academic_year_id         AS academic_year_id,
           ay.academic_year_name::text AS academic_year_name,
           acc.name::text             AS accommodation_type,
           s.uses_transport           AS uses_transport,
           a.bill_count               AS bill_count,
           a.total_billed             AS total_billed,
           CASE
             WHEN COALESCE(p_academic_year_id, s.academic_year_id) IS NULL
               THEN 'cannot_evaluate'
             WHEN a.bill_count > 0 THEN 'generated'
             ELSE 'not_generated'
           END                        AS coverage_state
    FROM scope s
    JOIN agg a                           ON a.learner_id = s.id
    LEFT JOIN public.institutions        i   ON i.id   = s.institution_id
    LEFT JOIN public.programs            p   ON p.id   = s.program_id
    LEFT JOIN public.semesters           sem ON sem.id = s.semester_id
    LEFT JOIN public.sections            sec ON sec.id = s.section_id
    LEFT JOIN public.academic_years      ay  ON ay.id  = s.academic_year_id
    LEFT JOIN public.accommodation_types acc ON acc.id = s.accommodation_type_id
  ),
  filtered AS (
    SELECT * FROM final f
    WHERE p_coverage_state = 'all' OR f.coverage_state = p_coverage_state
  )
  SELECT f.learner_id, f.roll_number, f.register_number, f.full_name,
         f.lifecycle_status, f.gender, f.institution_id, f.institution_name,
         f.program_name, f.semester_section,
         f.academic_year_id, f.academic_year_name,
         f.accommodation_type, f.uses_transport,
         f.bill_count, f.total_billed, f.coverage_state,
         COUNT(*) OVER ()::bigint
  FROM filtered f
  ORDER BY
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'academic_year_name' THEN f.academic_year_name
         WHEN 'accommodation_type' THEN f.accommodation_type
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'gender'             THEN f.gender
         WHEN 'coverage_state'     THEN f.coverage_state
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'academic_year_name' THEN f.academic_year_name
         WHEN 'accommodation_type' THEN f.accommodation_type
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'gender'             THEN f.gender
         WHEN 'coverage_state'     THEN f.coverage_state
       END
     END) DESC NULLS LAST,
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'bill_count'   THEN f.bill_count::numeric
         WHEN 'total_billed' THEN f.total_billed
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'bill_count'   THEN f.bill_count::numeric
         WHEN 'total_billed' THEN f.total_billed
       END
     END) DESC NULLS LAST,
    f.institution_name NULLS LAST, f.roll_number NULLS LAST, f.full_name
  LIMIT v_limit OFFSET v_offset;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_billing_coverage_learners(
  uuid, uuid[], text[], uuid, text, boolean, text, integer, integer,
  uuid[], text, text, text, text, uuid, uuid, uuid, uuid, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_billing_coverage_learners(
  uuid, uuid[], text[], uuid, text, boolean, text, integer, integer,
  uuid[], text, text, text, text, uuid, uuid, uuid, uuid, uuid)
  TO authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Summary: the KPI cards must narrow with the table, or the counts contradict
-- the rows on screen.
-- ---------------------------------------------------------------------------
DROP FUNCTION IF EXISTS public.get_billing_coverage_summary(
  uuid, uuid[], text[], uuid, boolean, uuid[], text, text);

CREATE FUNCTION public.get_billing_coverage_summary(
  p_academic_year_id uuid DEFAULT NULL::uuid,
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_billing_category_id uuid DEFAULT NULL::uuid,
  p_include_non_billing_institutions boolean DEFAULT false,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst   uuid[];
  v_result jsonb;
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN jsonb_build_object(
      'in_scope', 0, 'generated', 0, 'not_generated', 0, 'cannot_evaluate', 0,
      'excluded_institutions', 0, 'excluded_learners', 0,
      'by_institution', '[]'::jsonb);
  END IF;

  WITH billing_inst AS (
    SELECT DISTINCT b.institution_id AS inst_id FROM public.billing_student_bills b
  ),
  all_scope AS (
    SELECT lp.id, lp.institution_id, lp.academic_year_id,
           (lp.institution_id IN (SELECT inst_id FROM billing_inst)) AS is_billing_inst
    FROM public.learners_profiles lp
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_academic_year_id IS NULL OR lp.academic_year_id = p_academic_year_id)
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
  ),
  scope AS (
    SELECT * FROM all_scope
    WHERE p_include_non_billing_institutions OR is_billing_inst
  ),
  agg AS (
    SELECT s.id, s.institution_id, s.academic_year_id,
           COUNT(b.id)::integer AS bill_count
    FROM scope s
    LEFT JOIN public.billing_student_bills b
           ON b.student_id = s.id
          AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
          AND b.academic_year_id = COALESCE(p_academic_year_id, s.academic_year_id)
          AND (p_billing_category_id IS NULL
               OR b.item_category_id = p_billing_category_id)
    GROUP BY s.id, s.institution_id, s.academic_year_id
  ),
  stated AS (
    SELECT a.institution_id,
           CASE
             WHEN COALESCE(p_academic_year_id, a.academic_year_id) IS NULL
               THEN 'cannot_evaluate'
             WHEN a.bill_count > 0 THEN 'generated'
             ELSE 'not_generated'
           END AS coverage_state
    FROM agg a
  )
  SELECT jsonb_build_object(
    'in_scope',        (SELECT COUNT(*) FROM stated),
    'generated',       (SELECT COUNT(*) FROM stated WHERE coverage_state = 'generated'),
    'not_generated',   (SELECT COUNT(*) FROM stated WHERE coverage_state = 'not_generated'),
    'cannot_evaluate', (SELECT COUNT(*) FROM stated WHERE coverage_state = 'cannot_evaluate'),
    'excluded_institutions',
      (SELECT COUNT(DISTINCT institution_id) FROM all_scope WHERE NOT is_billing_inst),
    'excluded_learners',
      (SELECT COUNT(*) FROM all_scope WHERE NOT is_billing_inst),
    'by_institution', COALESCE((
      SELECT jsonb_agg(x ORDER BY x->>'institution_name')
      FROM (
        SELECT jsonb_build_object(
                 'institution_id',   st.institution_id,
                 'institution_name', COALESCE(i.name::text, 'Unknown'),
                 'in_scope',         COUNT(*),
                 'generated',        COUNT(*) FILTER (WHERE st.coverage_state = 'generated'),
                 'not_generated',    COUNT(*) FILTER (WHERE st.coverage_state = 'not_generated')
               ) AS x
        FROM stated st
        LEFT JOIN public.institutions i ON i.id = st.institution_id
        GROUP BY st.institution_id, i.name
      ) sub
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_billing_coverage_summary(
  uuid, uuid[], text[], uuid, boolean, uuid[], text, text,
  uuid, uuid, uuid, uuid, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_billing_coverage_summary(
  uuid, uuid[], text[], uuid, boolean, uuid[], text, text,
  uuid, uuid, uuid, uuid, uuid) TO authenticated, service_role;

-- Per-learner, per-bill detail for the /billing/coverage PDF export
-- (mig 20260729_billing_coverage_learner_bills). Appended: this file is
-- replayed top-to-bottom and already carries older copies of neighbouring
-- functions, so editing in place risks clobbering them.
DROP FUNCTION IF EXISTS public.get_billing_coverage_learner_bills(
  uuid, uuid[], text[], uuid, text, boolean, text, uuid[], text, text,
  uuid, uuid, uuid, uuid, uuid, integer);

CREATE FUNCTION public.get_billing_coverage_learner_bills(
  p_academic_year_id uuid DEFAULT NULL::uuid,
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_billing_category_id uuid DEFAULT NULL::uuid,
  p_coverage_state text DEFAULT 'all'::text,
  p_include_non_billing_institutions boolean DEFAULT false,
  p_search text DEFAULT NULL::text,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_max_learners integer DEFAULT 1000
)
RETURNS TABLE(
  out_learner_id uuid,
  out_roll_number text,
  out_register_number text,
  out_full_name text,
  out_institution_name text,
  out_program_name text,
  out_semester_section text,
  out_lifecycle_status text,
  out_learner_total numeric,
  out_learner_paid numeric,
  out_learner_pending numeric,
  out_bill_id uuid,
  out_bill_description text,
  out_category_name text,
  out_bill_academic_year text,
  out_due_date date,
  out_bill_status text,
  out_total_amount numeric,
  out_paid_amount numeric,
  out_pending_amount numeric,
  out_learner_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst  uuid[];
  v_cap   integer := LEAST(GREATEST(COALESCE(p_max_learners, 1000), 1), 5000);
BEGIN
  -- Same key as the screen itself: exporting must never widen access.
  IF NOT public.user_has_permission('billing.coverage.export') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.export' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH billing_inst AS (
    SELECT DISTINCT b.institution_id AS inst_id FROM public.billing_student_bills b
  ),
  scope AS (
    SELECT lp.id, lp.institution_id, lp.academic_year_id, lp.program_id,
           lp.semester_id, lp.section_id, lp.lifecycle_status,
           lp.first_name, lp.last_name, lp.roll_number, lp.register_number
    FROM public.learners_profiles lp
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_billing_institutions
           OR lp.institution_id IN (SELECT inst_id FROM billing_inst))
      AND (p_academic_year_id IS NULL OR lp.academic_year_id = p_academic_year_id)
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
      AND (
        p_search IS NULL OR p_search = ''
        OR lp.roll_number ILIKE '%' || p_search || '%'
        OR lp.register_number ILIKE '%' || p_search || '%'
        OR (COALESCE(lp.first_name,'') || ' ' || COALESCE(lp.last_name,''))
             ILIKE '%' || p_search || '%'
      )
  ),
  -- Live bills only. 'cancelled' and 'superseded' are BOTH void states; counting
  -- either would overstate what the learner actually owes.
  live_bills AS (
    SELECT b.*
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
      AND (p_billing_category_id IS NULL OR b.item_category_id = p_billing_category_id)
      AND (p_academic_year_id IS NULL OR b.academic_year_id = p_academic_year_id)
  ),
  learner_state AS (
    SELECT s.id,
           COUNT(lb.id)::integer AS bill_count,
           COALESCE(SUM(lb.final_amount), 0)::numeric   AS total_amount,
           COALESCE(SUM(lb.final_amount - lb.balance_amount), 0)::numeric AS paid_amount,
           COALESCE(SUM(lb.balance_amount), 0)::numeric AS pending_amount
    FROM scope s
    LEFT JOIN live_bills lb ON lb.student_id = s.id
    GROUP BY s.id
  ),
  eligible AS (
    SELECT s.*, ls.bill_count, ls.total_amount, ls.paid_amount, ls.pending_amount
    FROM scope s
    JOIN learner_state ls ON ls.id = s.id
    WHERE p_coverage_state = 'all'
       OR (p_coverage_state = 'generated'     AND ls.bill_count > 0)
       OR (p_coverage_state = 'not_generated' AND ls.bill_count = 0)
  ),
  capped AS (
    SELECT e.*, i.name::text AS institution_name, p.program_name,
           CASE
             WHEN sem.semester_name IS NULL AND sec.section_name IS NULL THEN NULL
             WHEN sec.section_name IS NULL THEN sem.semester_name::text
             WHEN sem.semester_name IS NULL THEN sec.section_name::text
             ELSE sem.semester_name::text || ' · ' || sec.section_name::text
           END AS semester_section,
           COUNT(*) OVER ()::bigint AS learner_count
    FROM eligible e
    LEFT JOIN public.institutions i   ON i.id   = e.institution_id
    LEFT JOIN public.programs     p   ON p.id   = e.program_id
    LEFT JOIN public.semesters    sem ON sem.id = e.semester_id
    LEFT JOIN public.sections     sec ON sec.id = e.section_id
    -- e.id last: without a unique tiebreaker the LIMIT picks a different set
    -- of learners between runs whenever the leading keys tie.
    ORDER BY i.name NULLS LAST, e.roll_number NULLS LAST,
             e.last_name, e.first_name, e.id
    LIMIT v_cap
  )
  SELECT c.id,
         c.roll_number::text,
         c.register_number::text,
         TRIM(COALESCE(c.first_name,'') || ' ' || COALESCE(c.last_name,'')),
         c.institution_name,
         c.program_name,
         c.semester_section,
         c.lifecycle_status::text,
         c.total_amount,
         c.paid_amount,
         c.pending_amount,
         lb.id,
         lb.bill_description::text,
         cat.category_name::text,
         -- 62 bills carry no academic year; label rather than drop the row.
         COALESCE(ay.academic_year_name::text, '—'),
         lb.due_date,
         lb.status::text,
         lb.final_amount,
         (lb.final_amount - lb.balance_amount),
         lb.balance_amount,
         c.learner_count
  FROM capped c
  LEFT JOIN live_bills lb              ON lb.student_id = c.id
  LEFT JOIN public.billing_categories cat ON cat.id = lb.item_category_id
  LEFT JOIN public.academic_years ay    ON ay.id  = lb.academic_year_id
  -- LEARNER KEYS BEFORE BILL KEYS, and c.id to close the tie for good.
  -- Without them the sort fell through from roll_number straight to
  -- lb.due_date / lb.bill_description, which sorts the WHOLE institution by
  -- bill name and interleaves every learner who ties on roll number - 1,120
  -- carry a NULL one, 457 more share one inside their institution. The PDF
  -- export then printed one box per billing category per learner.
  ORDER BY c.institution_name NULLS LAST, c.roll_number NULLS LAST,
           c.last_name, c.first_name, c.id,
           lb.due_date NULLS LAST, lb.bill_description;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_billing_coverage_learner_bills(
  uuid, uuid[], text[], uuid, text, boolean, text, uuid[], text, text,
  uuid, uuid, uuid, uuid, uuid, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_billing_coverage_learner_bills(
  uuid, uuid[], text[], uuid, text, boolean, text, uuid[], text, text,
  uuid, uuid, uuid, uuid, uuid, integer) TO authenticated, service_role;

-- ================================================================================
-- SECTION: ADMISSION — REFERRAL COMMISSION GENERATOR
-- ================================================================================
-- Canonical copy of fn_generate_referral_commissions. Originally introduced by
-- migration 20260722120000_referral_rate_config_and_generator.sql (never previously
-- back-ported here). The money logic (candidate selection, rate resolution, row-by-row
-- insert, summary jsonb) is byte-for-byte identical to that migration.
-- Updated: 2026-08-02 - re-callable temp table (DROP TABLE IF EXISTS _gen)
--   ON COMMIT DROP only fires at COMMIT, so a SECOND call inside the SAME transaction
--   otherwise collides with "relation _gen already exists". The production UI is
--   unaffected (Preview and Generate are separate txns), but any batch/test caller that
--   invokes the function twice in one txn crashes. Fix: DROP TABLE IF EXISTS _gen before
--   the CREATE TEMP TABLE. Applied to prod via migration
--   20260808230500_referral_generator_temp_table_recallable.sql.
CREATE OR REPLACE FUNCTION public.fn_generate_referral_commissions(
  p_year integer,
  p_dry_run boolean DEFAULT true,
  p_consultant_ids uuid[] DEFAULT NULL,   -- NULL = all; else limit to these agencies (D27 small group)
  p_created_by uuid DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_summary jsonb; v_inserted integer := 0;
BEGIN
  -- SECURITY DEFINER bypasses RLS, so gate explicitly. A dry run computes only, but
  -- a real run writes money rows — both require an admission-edit admin.
  IF NOT (is_super_admin() OR is_admin()) THEN
    RAISE EXCEPTION 'Not authorised to generate referral commissions';
  END IF;

  -- Re-callable within a single transaction: ON COMMIT DROP only fires at COMMIT, so a
  -- second call in the same txn would otherwise collide on the existing _gen relation.
  DROP TABLE IF EXISTS _gen;

  -- candidate rows: 2025/26 CONSULTANT referrals that resolve to an active agency,
  -- have a programme, are NOT already transacted, and have a resolvable rate.
  CREATE TEMP TABLE _gen ON COMMIT DROP AS
  SELECT lp.id AS learner_profile_id, lp.institution_id, lp.program_id,
         ec.id AS consultant_id, ec.name AS consultant_name,
         (nullif(ec.bank_account_number,'') IS NOT NULL AND nullif(ec.pan_number,'') IS NOT NULL) AS payable,
         r.flat_amount AS gross,
         round(r.flat_amount * r.tds_percent/100.0, 2) AS tds,
         r.flat_amount - round(r.flat_amount * r.tds_percent/100.0, 2) AS net
    FROM learners_profiles lp
    JOIN admission_years ay ON ay.id = lp.admission_year_id AND ay.year = p_year
    JOIN education_consultants ec ON ec.id = lp.referred_by_id AND ec.status = 'active'
    CROSS JOIN LATERAL public.fn_resolve_referral_rate(p_year, lp.institution_id, lp.program_id) r
   WHERE lp.referral_type = 'consultant'
     AND lp.referred_by_id IS NOT NULL
     AND lp.program_id IS NOT NULL
     AND r.id IS NOT NULL
     AND (p_consultant_ids IS NULL OR ec.id = ANY(p_consultant_ids))
     AND NOT EXISTS (SELECT 1 FROM consultant_commission_transactions t
                      WHERE t.learner_profile_id = lp.id);

  IF NOT p_dry_run THEN
    -- Insert row-by-row, NOT as a set. The shared trigger_set_transaction_number
    -- derives the next number as MAX(existing)+1 per institution; in a single bulk
    -- INSERT every row sees the same pre-statement snapshot and collides on
    -- TXN-000001. Separate statements let each row see the prior ones. (The trigger
    -- also has a concurrency race under parallel writers — pre-existing, out of scope;
    -- generation is a single admin-run operation.)
    DECLARE rec record;
    BEGIN
      FOR rec IN SELECT * FROM _gen LOOP
        INSERT INTO consultant_commission_transactions
          (institution_id, consultant_id, learner_profile_id, transaction_type,
           commission_basis_amount, gross_amount, tds_percentage, tds_amount, other_deductions,
           net_amount, status, created_by)
        VALUES (rec.institution_id, rec.consultant_id, rec.learner_profile_id, 'referral_commission',
                rec.gross, rec.gross, NULL, rec.tds, 0, rec.net, 'pending', p_created_by);
        v_inserted := v_inserted + 1;
      END LOOP;
    END;
  END IF;

  SELECT jsonb_build_object(
    'dry_run', p_dry_run,
    'academic_year', p_year,
    'candidates', (SELECT count(*) FROM _gen),
    'payable_now', (SELECT count(*) FROM _gen WHERE payable),
    'blocked_no_bank', (SELECT count(*) FROM _gen WHERE NOT payable),
    'total_gross', COALESCE((SELECT sum(gross) FROM _gen),0),
    'total_tds',   COALESCE((SELECT sum(tds)   FROM _gen),0),
    'total_net',   COALESCE((SELECT sum(net)   FROM _gen),0),
    'rows_written', v_inserted,
    'by_agency', COALESCE((SELECT jsonb_agg(x ORDER BY (x->>'net')::numeric DESC) FROM (
        SELECT jsonb_build_object('agency',consultant_name,'referrals',count(*),
               'net',sum(net),'payable',bool_and(payable)) x
          FROM _gen GROUP BY consultant_name, consultant_id) s),'[]'::jsonb)
  ) INTO v_summary;

  RETURN v_summary;
END $$;
REVOKE EXECUTE ON FUNCTION public.fn_generate_referral_commissions(integer,boolean,uuid[],uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_generate_referral_commissions(integer,boolean,uuid[],uuid) TO authenticated;

COMMENT ON FUNCTION public.fn_generate_referral_commissions(integer,boolean,uuid[],uuid) IS
  'Generates pending commission transactions from attributed CONSULTANT referrals for a year. DRY RUN by default (writes nothing). Skips already-transacted learners and referrals with no resolvable rate. Senior Learner referrals (payroll) and learner referrals (excluded) are out of scope.';

-- ================================================================================
-- HR PAYROLL ORGANISATION (2026-08-04)
-- Source migration: 20260804090000_hr_staff_payroll_directory_rpc.sql
-- ================================================================================

-- Every ACTIVE staff member with their recorded payer, assigned or not.
-- Superset of hr_staff_without_payer(); SELF-AUTHORIZES on
-- hr.payroll.institution.view and re-applies role_has_institution_access().
CREATE OR REPLACE FUNCTION public.hr_staff_payroll_directory()
RETURNS TABLE (
  staff_uuid     uuid,
  staff_code     text,
  person_name    text,
  role_title     text,
  works_at_id    uuid,
  works_at_name  text,
  payer_org_id   uuid,
  payer_org_name text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.user_has_permission('hr.payroll.institution.view') THEN
    RAISE EXCEPTION 'hr.payroll.institution.view is required to see payroll organisations.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  SELECT s.id,
         s.staff_id::text,
         TRIM(BOTH FROM COALESCE(s.first_name, '') || ' ' || COALESCE(s.last_name, ''))::text,
         s.designation::text,
         i.id,
         i.name::text,
         o.id,
         o.name::text
    FROM public.staff s
    JOIN public.institutions i ON i.id = s.institution_id
    LEFT JOIN public.hr_staff_payroll p ON p.staff_id = s.id
    LEFT JOIN public.hr_organizations o ON o.id = p.hr_organization_id
   WHERE COALESCE(s.is_active, false)
     AND public.role_has_institution_access(s.institution_id)
   ORDER BY (p.staff_id IS NOT NULL), i.name, s.designation, 3;
END;
$function$;

REVOKE ALL ON FUNCTION public.hr_staff_payroll_directory() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.hr_staff_payroll_directory() FROM anon;
GRANT EXECUTE ON FUNCTION public.hr_staff_payroll_directory() TO authenticated;


-- ============================================================
-- Migration: 20260810140000_hostel_eligibility_admission_year_fee_anchor.sql
-- Campus Living — Category-Eligibility fee bands anchor on the ADMISSION year.
--
-- Replaces the learners_profiles.academic_year_id anchor, which (a) DRIFTS —
-- one cohort's learners sit on different profile years — and (b) reads Rs.0
-- PLACEHOLDER bills, silently matching every band whose fee_min is 0.
--
-- Fallback chain: admission-year total > 0, else the earliest academic year
-- with a total > 0, else NULL (resolver returns nothing, learner is skipped).
-- A Rs.0 year total is "no fee known", never a real fee of zero.
--
-- Measured 2026-08-04 over 695 active hostel learners: 525 resolved a room
-- category BEFORE, 426 AFTER (-104, +5), 0 category changes. All 104 dropped
-- had a BEFORE fee of exactly Rs.0.00 — every one was banded on a placeholder.
--
-- fn_learner_current_year_academic_fee (above) is KEPT for reporting only.
-- fn_learner_academic_payment_progress deliberately stays on the CURRENT year.
-- ============================================================

CREATE OR REPLACE FUNCTION public.fn_learner_admission_academic_year(p_learner_id uuid)
RETURNS uuid
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  SELECT ay.id
  FROM learners_profiles lp
  JOIN admission_years ady ON ady.id = lp.admission_year_id
  JOIN academic_years  ay  ON ay.institution_id = lp.institution_id
                          AND EXTRACT(YEAR FROM ay.start_date)::int = ady.year
  WHERE lp.id = p_learner_id
  ORDER BY ay.is_active DESC, ay.academic_year_name ASC
  LIMIT 1;
$function$;

CREATE OR REPLACE FUNCTION public.fn_learner_band_academic_fee(p_learner_id uuid)
RETURNS TABLE(academic_year_id uuid, academic_year_name text, fee numeric)
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  WITH anchor AS (
    SELECT public.fn_learner_admission_academic_year(p_learner_id) AS ay_id
  ),
  years AS (
    SELECT b.academic_year_id AS ay_id,
           ay.academic_year_name::text AS ay_name,
           ay.start_date,
           SUM(b.final_amount) AS total
    FROM billing_student_bills b
    JOIN academic_years ay ON ay.id = b.academic_year_id
    WHERE b.student_id = p_learner_id
      AND b.fee_source = 'academic'
      AND b.status NOT IN ('cancelled','superseded')
    GROUP BY b.academic_year_id, ay.academic_year_name, ay.start_date
    HAVING SUM(b.final_amount) > 0
  )
  SELECT y.ay_id, y.ay_name, y.total
  FROM years y CROSS JOIN anchor a
  ORDER BY (y.ay_id IS DISTINCT FROM a.ay_id), y.start_date ASC
  LIMIT 1;
$function$;

CREATE OR REPLACE FUNCTION public.fn_learner_admission_year_academic_fee(p_learner_id uuid)
RETURNS numeric
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  SELECT fee FROM public.fn_learner_band_academic_fee(p_learner_id);
$function$;

COMMENT ON FUNCTION public.fn_learner_current_year_academic_fee(uuid) IS
  'DEPRECATED for eligibility. Sums academic bills on learners_profiles.academic_year_id. Category-Eligibility fee bands now use fn_learner_admission_year_academic_fee. Kept for reporting/diagnostics only.';

REVOKE EXECUTE ON FUNCTION public.fn_learner_admission_academic_year(uuid)     FROM anon, PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_learner_band_academic_fee(uuid)           FROM anon, PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_learner_admission_year_academic_fee(uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_learner_admission_academic_year(uuid)     TO authenticated, service_role;
GRANT  EXECUTE ON FUNCTION public.fn_learner_band_academic_fee(uuid)           TO authenticated, service_role;
GRANT  EXECUTE ON FUNCTION public.fn_learner_admission_year_academic_fee(uuid) TO authenticated, service_role;

-- The two resolvers — one line changed in each; every campus-living consumer
-- reaches the fee through here, so nothing else needs touching.
CREATE OR REPLACE FUNCTION public.fn_hostel_learner_room_categories(p_learner_id uuid)
RETURNS TABLE(category_id uuid)
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_institution uuid; v_program uuid; v_quota uuid; v_fee numeric; v_gender text; v_gt text;
BEGIN
  SELECT lp.institution_id, lp.program_id, lp.quota_id, lp.gender
    INTO v_institution, v_program, v_quota, v_gender
  FROM learners_profiles lp WHERE lp.id = p_learner_id;

  IF v_institution IS NULL THEN RETURN; END IF;
  IF v_program IS NULL THEN RETURN; END IF;
  -- Admission-year anchored (was fn_learner_current_year_academic_fee).
  v_fee := fn_learner_admission_year_academic_fee(p_learner_id);
  IF v_fee IS NULL THEN RETURN; END IF;

  v_gt := CASE WHEN lower(v_gender) LIKE 'm%' THEN 'boys'
               WHEN lower(v_gender) LIKE 'f%' THEN 'girls' ELSE NULL END;

  RETURN QUERY
    SELECT r.category_id
    FROM fn_hostel_effective_room_categories(v_institution, v_program, v_quota, v_fee, v_gt) r;
END $function$;

CREATE OR REPLACE FUNCTION public.fn_hostel_learner_mess_categories(p_learner_id uuid)
RETURNS TABLE(category_id uuid)
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_institution uuid; v_program uuid; v_quota uuid; v_fee numeric; v_gender text; v_gt text;
BEGIN
  SELECT lp.institution_id, lp.program_id, lp.quota_id, lp.gender
    INTO v_institution, v_program, v_quota, v_gender
  FROM learners_profiles lp WHERE lp.id = p_learner_id;

  IF v_institution IS NULL THEN RETURN; END IF;
  IF v_program IS NULL THEN RETURN; END IF;
  -- Admission-year anchored (was fn_learner_current_year_academic_fee).
  v_fee := fn_learner_admission_year_academic_fee(p_learner_id);
  IF v_fee IS NULL THEN RETURN; END IF;

  v_gt := CASE WHEN lower(v_gender) LIKE 'm%' THEN 'boys'
               WHEN lower(v_gender) LIKE 'f%' THEN 'girls' ELSE NULL END;

  RETURN QUERY
    SELECT m.category_id
    FROM fn_hostel_effective_mess_categories(v_institution, v_program, v_quota, v_fee, v_gt) m;
END $function$;

GRANT EXECUTE ON FUNCTION public.fn_hostel_learner_room_categories(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_hostel_learner_mess_categories(uuid) TO authenticated;

-- ── 5. Auto-allocate candidates preview ────────────────────────────────────
--
-- DROP + CREATE because RETURNS TABLE gains columns (a return-type change that
-- CREATE OR REPLACE rejects). DROP discards grants, so they are re-issued below
-- — otherwise EXECUTE silently reverts to the PUBLIC default.
--
-- Three behavioural changes beyond the new columns:
--   a) The "profile academic year not set" PREREQUISITE is gone. The fee no
--      longer comes from that field, and fn_auto_allocate_classic already
--      COALESCEs a missing profile year to the institution's latest active one
--      when stamping the allocation — so the old gate made preview say "out"
--      for learners generate would happily place. Removing it restores
--      preview == generate. academic_year_id/_name are still RETURNED, for display.
--   b) bill_state now describes the ANCHOR, not the profile year:
--      matched = fee read from the admission year; different_year = fee read
--      from the fallback year; untagged = bills exist but none usable; none = no bills.
--   c) exclusion_reason quotes the actual band fee so an operator can go
--      straight to Settings -> Category Eligibility and add the missing band.
DROP FUNCTION IF EXISTS public.fn_auto_allocate_candidates(uuid, boolean, integer, uuid, uuid, uuid);

CREATE FUNCTION public.fn_auto_allocate_candidates(
  p_block_id uuid,
  p_strict boolean DEFAULT false,
  p_floor integer DEFAULT NULL::integer,
  p_institution_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid
)
RETURNS TABLE(
  learner_id uuid, full_name text, email text, institution_name text,
  program_name text, semester_name text, gender text,
  has_profile boolean, gender_ok boolean, not_allocated boolean,
  physical_rule_ok boolean, bed_available boolean,
  academic_year_id uuid, academic_year_name text,
  admission_academic_year_id uuid, admission_academic_year_name text,
  band_academic_year_id uuid, band_academic_year_name text, band_fee numeric,
  academic_bill_count integer, current_year_bill_count integer,
  bill_other_year_name text, current_year_fee numeric,
  resolved_room_category_id uuid, resolved_room_category_name text,
  resolved_mess_category_id uuid, resolved_mess_category_name text,
  bill_state text, stage text, verdict text, exclusion_reason text
)
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  WITH blk AS (
    SELECT hostel_type::text AS t FROM hostel_blocks WHERE id = p_block_id
  ),
  cohort AS (
    SELECT lp.id, lp.institution_id, lp.degree_id, lp.department_id,
           lp.program_id, lp.semester_id, lp.academic_year_id,
           lp.first_name, lp.last_name,
           room_elig.cats AS room_cats, mess_elig.cats AS mess_cats
    FROM learners_profiles lp
    CROSS JOIN blk
    LEFT JOIN profiles gp ON gp.learner_id = lp.id
    LEFT JOIN LATERAL (SELECT array_agg(category_id) AS cats FROM fn_hostel_learner_room_categories(lp.id)) room_elig ON true
    LEFT JOIN LATERAL (SELECT array_agg(category_id) AS cats FROM fn_hostel_learner_mess_categories(lp.id)) mess_elig ON true
    WHERE lp.accommodation_type_id IN (SELECT id FROM accommodation_types WHERE code = 'hostel')
      -- Only ACTIVE learners may be allocated a bed. Mirrors
      -- fn_hostel_unallocated_candidates (manual picker) and v_learner_hostelites.
      AND lp.lifecycle_status = 'active'
      AND lp.institution_id IN (SELECT institution_id FROM hostel_block_institutions WHERE block_id = p_block_id)
      AND (p_institution_id IS NULL OR lp.institution_id = p_institution_id)
      AND (p_program_id     IS NULL OR lp.program_id     = p_program_id)
      AND (p_semester_id    IS NULL OR lp.semester_id    = p_semester_id)
      AND (blk.t IS NULL OR blk.t NOT IN ('boys','girls')
           OR gp.gender IS NULL OR btrim(gp.gender) = ''
           OR (blk.t = 'boys'  AND lower(btrim(gp.gender)) IN ('male','m'))
           OR (blk.t = 'girls' AND lower(btrim(gp.gender)) IN ('female','f')))
      -- Skip students who already have an active or pending-approval bed.
      -- Applied here (before the LATERAL eligibility joins) so we don't burn
      -- fn_hostel_learner_room/mess_categories on students who can't be placed.
      AND NOT EXISTS (
        SELECT 1 FROM hostel_allocations ha2
        JOIN profiles pr2 ON pr2.learner_id = lp.id
        WHERE ha2.learner_id = pr2.id
          AND ha2.status IN ('active', 'pending_approval')
      )
  ),
  base AS (
    SELECT
      c.id AS learner_id,
      COALESCE(p.full_name,
               NULLIF(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''),
               p.email, '—') AS full_name,
      p.email, inst.name AS institution_name, prog.program_name, sem.semester_name,
      lower(trim(p.gender)) AS gender,
      (p.id IS NOT NULL) AS has_profile,
      c.academic_year_id, ay.academic_year_name, c.room_cats, c.mess_cats,
      adm.ay_id AS admission_academic_year_id,
      aay.academic_year_name::text AS admission_academic_year_name,
      bf.academic_year_id AS band_academic_year_id,
      bf.academic_year_name AS band_academic_year_name,
      bf.fee AS band_fee,
      c.room_cats[1] AS resolved_room_category_id,
      rc.name AS resolved_room_category_name, rc.type AS resolved_room_category_type,
      c.mess_cats[1] AS resolved_mess_category_id, mc.name AS resolved_mess_category_name,
      (SELECT count(*)::int FROM billing_student_bills b
         WHERE b.student_id = c.id AND b.fee_source = 'academic'
           AND b.status NOT IN ('cancelled','superseded')) AS academic_bill_count,
      (SELECT count(*)::int FROM billing_student_bills b
         WHERE b.student_id = c.id AND b.fee_source = 'academic'
           AND b.status NOT IN ('cancelled','superseded')
           AND b.academic_year_id = c.academic_year_id) AS current_year_bill_count,
      (SELECT ay2.academic_year_name
         FROM billing_student_bills b JOIN academic_years ay2 ON ay2.id = b.academic_year_id
        WHERE b.student_id = c.id AND b.fee_source = 'academic'
          AND b.status NOT IN ('cancelled','superseded')
          AND b.academic_year_id IS NOT NULL
          AND b.academic_year_id IS DISTINCT FROM c.academic_year_id
        ORDER BY b.created_at DESC LIMIT 1) AS bill_other_year_name,
      -- Retained purely as a diagnostic column (what the OLD rule would have
      -- read) so an operator can see a Rs.0 / missing current-year bill.
      fn_learner_current_year_academic_fee(c.id) AS current_year_fee,
      -- not_allocated is always true here (cohort CTE already filtered allocated
      -- students out), but kept for the verdict/exclusion_reason expressions below.
      true AS not_allocated,
      EXISTS (
        SELECT 1 FROM hostel_rooms rm
        JOIN hostel_categories hc ON hc.id = rm.category_id
        WHERE rm.block_id = p_block_id AND rm.room_purpose = 'student'
          AND (p_floor IS NULL OR rm.floor = p_floor)
          AND rm.category_id = ANY(c.room_cats)
          AND (hc.type IS NULL
               OR (hc.type = 'boys'  AND lower(trim(p.gender)) IN ('male','m'))
               OR (hc.type = 'girls' AND lower(trim(p.gender)) IN ('female','f')))
          AND fn_room_serves_institution(rm.id, c.institution_id)
          AND fn_learner_strictly_eligible_for_room(c.id, rm.id, p_strict)
      ) AS physical_rule_ok,
      EXISTS (
        SELECT 1 FROM hostel_rooms rm
        WHERE rm.block_id = p_block_id AND rm.room_purpose = 'student'
          AND (p_floor IS NULL OR rm.floor = p_floor)
          AND NOT (rm.category_id = ANY(c.room_cats))
          AND fn_room_serves_institution(rm.id, c.institution_id)
          AND fn_learner_strictly_eligible_for_room(c.id, rm.id, p_strict)
      ) AS physical_ok_other_category,
      EXISTS (
        SELECT 1 FROM hostel_beds bd JOIN hostel_rooms r ON r.id = bd.room_id
        JOIN hostel_categories hc ON hc.id = r.category_id
        WHERE r.block_id = p_block_id AND r.room_purpose = 'student'
          AND bd.status = 'available'
          AND (p_floor IS NULL OR r.floor = p_floor)
          AND r.category_id = ANY(c.room_cats)
          AND (hc.type IS NULL
               OR (hc.type = 'boys'  AND lower(trim(p.gender)) IN ('male','m'))
               OR (hc.type = 'girls' AND lower(trim(p.gender)) IN ('female','f')))
          AND fn_room_serves_institution(r.id, c.institution_id)
          AND NOT EXISTS (SELECT 1 FROM hostel_allocations a
                          WHERE a.bed_id = bd.id AND a.status IN ('active','pending_approval'))
          AND fn_learner_strictly_eligible_for_room(c.id, r.id, p_strict)
      ) AS bed_available
    FROM cohort c
    LEFT JOIN profiles p       ON p.learner_id = c.id
    LEFT JOIN institutions inst ON inst.id = c.institution_id
    LEFT JOIN programs prog     ON prog.id = c.program_id
    LEFT JOIN semesters sem     ON sem.id = c.semester_id
    LEFT JOIN academic_years ay ON ay.id = c.academic_year_id
    LEFT JOIN LATERAL (SELECT fn_learner_admission_academic_year(c.id) AS ay_id) adm ON true
    LEFT JOIN academic_years aay ON aay.id = adm.ay_id
    LEFT JOIN LATERAL fn_learner_band_academic_fee(c.id) bf ON true
    LEFT JOIN hostel_categories rc ON rc.id = c.room_cats[1]
    LEFT JOIN mess_categories   mc ON mc.id = c.mess_cats[1]
  ),
  scored AS (
    SELECT b.*,
      (b.resolved_room_category_type IS NULL
        OR (b.resolved_room_category_type = 'boys'  AND b.gender IN ('male','m'))
        OR (b.resolved_room_category_type = 'girls' AND b.gender IN ('female','f'))) AS gender_ok
    FROM base b
  )
  SELECT
    s.learner_id, s.full_name, s.email, s.institution_name, s.program_name, s.semester_name,
    s.gender, s.has_profile, s.gender_ok, s.not_allocated, s.physical_rule_ok, s.bed_available,
    s.academic_year_id, s.academic_year_name,
    s.admission_academic_year_id, s.admission_academic_year_name,
    s.band_academic_year_id, s.band_academic_year_name, s.band_fee,
    s.academic_bill_count, s.current_year_bill_count, s.bill_other_year_name, s.current_year_fee,
    s.resolved_room_category_id, s.resolved_room_category_name,
    s.resolved_mess_category_id, s.resolved_mess_category_name,
    CASE
      WHEN s.band_fee IS NOT NULL
       AND s.band_academic_year_id IS NOT DISTINCT FROM s.admission_academic_year_id THEN 'matched'
      WHEN s.band_fee IS NOT NULL          THEN 'different_year'
      WHEN s.academic_bill_count > 0       THEN 'untagged'
      ELSE 'none'
    END AS bill_state,
    CASE
      WHEN s.band_fee  IS NULL THEN 'prerequisite'
      WHEN s.room_cats IS NULL THEN 'prerequisite'
      WHEN NOT s.has_profile OR NOT s.gender_ok OR NOT s.physical_rule_ok OR NOT s.bed_available
                               THEN 'eligibility'
      ELSE 'ok'
    END AS stage,
    CASE
      WHEN s.band_fee  IS NULL THEN 'out'
      WHEN s.room_cats IS NULL THEN 'out'
      WHEN NOT s.has_profile OR NOT s.gender_ok OR NOT s.physical_rule_ok OR NOT s.bed_available
                               THEN 'out'
      ELSE 'in'
    END AS verdict,
    CASE
      WHEN s.band_fee IS NULL THEN
        CASE
          WHEN s.academic_bill_count = 0 THEN
            'No academic bill for this student — nothing to read a fee band from'
          ELSE
            'Academic bills exist but none is usable: either untagged to an academic year, or the tagged year totals ₹0'
        END
      WHEN s.room_cats IS NULL THEN
        'No Category-Eligibility band covers ₹'
        || to_char(s.band_fee, 'FM999,999,999')
        || ' (read from ' || COALESCE(s.band_academic_year_name, 'their admission year') || ')'
        || ' for this program / quota — add or widen a band'
      WHEN NOT s.has_profile   THEN 'No login profile'
      WHEN NOT s.gender_ok     THEN 'Gender does not match the resolved room category'
      WHEN NOT s.physical_rule_ok AND s.physical_ok_other_category THEN
        'Rooms they may occupy in this block are a different room category than their eligible '
        || COALESCE(s.resolved_room_category_name, 'category')
        || ' — fix the reservation rooms or the Category-Eligibility band'
      WHEN NOT s.physical_rule_ok THEN
        CASE WHEN p_strict
          THEN 'No physical-room rule in this block reserves a room for this cohort (strict mode)'
          ELSE 'No room they can occupy in their category — rooms here are reserved for other cohorts, or this cohort''s reserved rooms are in another block'
        END
      WHEN NOT s.bed_available THEN 'Their category rooms are full — no free bed'
      ELSE NULL
    END AS exclusion_reason
  FROM scored s
  ORDER BY s.full_name;
$function$;

REVOKE EXECUTE ON FUNCTION public.fn_auto_allocate_candidates(uuid, boolean, integer, uuid, uuid, uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_auto_allocate_candidates(uuid, boolean, integer, uuid, uuid, uuid) TO authenticated, service_role;


-- ── 6. Settings -> Category Eligibility "Sync categories" dry-run ──────────
--
-- DROP + CREATE: current_year_fee is replaced by band_fee + band_academic_year_name.
DROP FUNCTION IF EXISTS public.fn_preview_hostel_fee_categories(uuid);

CREATE FUNCTION public.fn_preview_hostel_fee_categories(p_institution uuid DEFAULT NULL::uuid)
RETURNS TABLE(
  learner_id uuid, learner_name text, roll_number text, institution_name text,
  program_name text, semester_name text, quota_name text, gender text,
  band_fee numeric, band_academic_year_name text,
  has_academic_bill boolean, is_allocated boolean, reason text,
  current_room text, new_room text, current_mess text, new_mess text, will_change boolean
)
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  r RECORD;
  v_gender_type text; v_fee numeric; v_fee_year text; v_has_bill boolean; v_allocated boolean;
  v_room uuid; v_mess uuid; v_new_room uuid; v_new_mess uuid; v_reason text;
BEGIN
  IF auth.uid() IS NOT NULL
     AND NOT user_has_permission('campus_living.settings.edit') THEN
    RAISE EXCEPTION 'Not authorized to preview learner category sync'
      USING ERRCODE = '42501';
  END IF;

  FOR r IN
    SELECT lp.id AS lid,
           NULLIF(trim(concat_ws(' ', lp.first_name, lp.last_name)), '') AS lname,
           lp.roll_number AS lroll, lp.gender AS lgender,
           lp.hostel_category_id AS cur_room_id, lp.mess_category_id AS cur_mess_id,
           i.name AS inst_name, p.program_name AS prog_name,
           s.semester_name AS sem_name, q.name AS q_name
    FROM learners_profiles lp
    JOIN accommodation_types acc ON acc.id = lp.accommodation_type_id AND acc.code = 'hostel'
    LEFT JOIN institutions i ON i.id = lp.institution_id
    LEFT JOIN programs p ON p.id = lp.program_id
    LEFT JOIN semesters s ON s.id = lp.semester_id
    LEFT JOIN quotas q ON q.id = lp.quota_id
    WHERE lp.lifecycle_status = 'active'
      AND (p_institution IS NULL OR lp.institution_id = p_institution)
    ORDER BY i.name, p.program_name, lname
  LOOP
    v_gender_type := CASE WHEN lower(r.lgender) LIKE 'm%' THEN 'boys'
                          WHEN lower(r.lgender) LIKE 'f%' THEN 'girls' ELSE NULL END;
    v_has_bill := EXISTS (
      SELECT 1 FROM billing_student_bills b
      WHERE b.student_id = r.lid AND b.fee_source = 'academic'
        AND b.status NOT IN ('cancelled','superseded'));

    -- Admission-year anchored fee + the year it was read from.
    v_fee := NULL; v_fee_year := NULL;
    SELECT bf.fee, bf.academic_year_name INTO v_fee, v_fee_year
    FROM fn_learner_band_academic_fee(r.lid) bf;

    v_allocated := EXISTS (
      SELECT 1 FROM hostel_allocations ha
      JOIN profiles pr ON pr.id = ha.learner_id
      WHERE pr.learner_id = r.lid AND ha.status = 'active');

    v_room := NULL; v_mess := NULL;

    IF v_has_bill THEN
      SELECT gv.id INTO v_room
      FROM fn_hostel_learner_room_categories(r.lid) rr
      JOIN hostel_categories bc ON bc.id = rr.category_id
      JOIN hostel_categories gv ON gv.name = bc.name
                               AND gv.type = v_gender_type AND gv.is_active
      LIMIT 1;

      SELECT gv.id INTO v_mess
      FROM fn_hostel_learner_mess_categories(r.lid) mm
      JOIN mess_categories bc ON bc.id = mm.category_id
      JOIN mess_categories gv ON gv.name = bc.name
                             AND gv.type = v_gender_type AND gv.is_active
      LIMIT 1;

      IF v_room IS NOT NULL OR v_mess IS NOT NULL THEN
        v_reason := 'band_match';
      ELSIF v_fee IS NULL THEN
        v_reason := 'classic_default_fee_unknown';
      ELSE
        v_reason := 'classic_default_no_band';
      END IF;

      IF v_room IS NULL AND v_gender_type IS NOT NULL THEN
        SELECT hc.id INTO v_room FROM hostel_categories hc
        WHERE hc.name = 'Classic Room' AND hc.type = v_gender_type AND hc.is_active
        ORDER BY hc.sort_order LIMIT 1;
      END IF;
      IF v_mess IS NULL AND v_gender_type IS NOT NULL THEN
        SELECT mc.id INTO v_mess FROM mess_categories mc
        WHERE mc.name = 'Classic' AND mc.type = v_gender_type AND mc.is_active
        ORDER BY mc.sort_order LIMIT 1;
      END IF;
    ELSE
      v_reason := 'no_academic_bill';
    END IF;

    v_new_room := CASE WHEN v_allocated THEN r.cur_room_id
                       ELSE COALESCE(v_room, r.cur_room_id) END;
    v_new_mess := COALESCE(v_mess, r.cur_mess_id);

    learner_id              := r.lid;
    learner_name            := r.lname;
    roll_number             := r.lroll;
    institution_name        := r.inst_name;
    program_name            := r.prog_name;
    semester_name           := r.sem_name;
    quota_name              := r.q_name;
    gender                  := r.lgender;
    band_fee                := v_fee;
    band_academic_year_name := v_fee_year;
    has_academic_bill       := v_has_bill;
    is_allocated            := v_allocated;
    reason                  := v_reason;
    current_room            := (SELECT hc.name FROM hostel_categories hc WHERE hc.id = r.cur_room_id);
    new_room                := (SELECT hc.name FROM hostel_categories hc WHERE hc.id = v_new_room);
    current_mess            := (SELECT mc.name FROM mess_categories mc WHERE mc.id = r.cur_mess_id);
    new_mess                := (SELECT mc.name FROM mess_categories mc WHERE mc.id = v_new_mess);
    will_change             := (v_new_room IS DISTINCT FROM r.cur_room_id)
                            OR (v_new_mess IS DISTINCT FROM r.cur_mess_id);
    RETURN NEXT;
  END LOOP;
END
$function$;

REVOKE EXECUTE ON FUNCTION public.fn_preview_hostel_fee_categories(uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_preview_hostel_fee_categories(uuid) TO authenticated, service_role;


-- ── 7. "Why was this learner placed here?" explain dialog ──────────────────
--
-- Returns jsonb, so a plain CREATE OR REPLACE (no grant loss). Changes:
--   a) academic_fee is now the admission-year anchored fee; the anchor year and
--      the year actually read are both surfaced.
--   b) FIXED a pre-existing drift: this function tested `v_fee < e.fee_max`
--      (exclusive) while fn_hostel_effective_room_categories has used
--      `p_fee <= e.fee_max` (inclusive) since 20260724130000. A learner sitting
--      exactly on a band's upper bound was shown fee_ok=false here while the
--      resolver had matched them — the dialog contradicted the allocation.
--   c) bills[].counted now flags the bill(s) the band fee was actually read
--      from, instead of the profile-academic-year ones.
CREATE OR REPLACE FUNCTION public.fn_explain_allocation(p_allocation_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_profile uuid; v_room uuid; v_block uuid; v_floor int; v_room_cat uuid;
  v_room_number text; v_status text; v_room_cat_name text; v_room_cat_type text;
  v_lp uuid; v_inst uuid; v_degree uuid; v_dept uuid; v_program uuid; v_semester uuid; v_ay uuid;
  v_quota uuid; v_gender text;
  v_inst_name text; v_degree_name text; v_dept_name text; v_program_name text;
  v_semester_name text; v_quota_name text;
  v_room_cats uuid[]; v_mess_cats uuid[];
  v_resolved_room_name text; v_resolved_mess_name text;
  v_fee numeric; v_ay_name text;
  v_adm_ay uuid; v_adm_ay_name text; v_band_ay uuid; v_band_ay_name text;
  v_has_covering boolean; v_matched boolean; v_rules jsonb;
  v_pinned boolean; v_pinned_blocks text; v_pinned_rules jsonb;
  v_serves boolean; v_cur_bill int; v_acad_bill int;
  v_elig_rules jsonb; v_bills jsonb;
BEGIN
  SELECT a.learner_id, a.room_id, a.status, r.room_number, r.block_id, r.floor, r.category_id
    INTO v_profile, v_room, v_status, v_room_number, v_block, v_floor, v_room_cat
    FROM hostel_allocations a LEFT JOIN hostel_rooms r ON r.id = a.room_id
    WHERE a.id = p_allocation_id;
  IF v_profile IS NULL THEN RETURN jsonb_build_object('error','allocation_not_found'); END IF;

  SELECT lp.id, lp.institution_id, lp.degree_id, lp.department_id, lp.program_id, lp.semester_id,
         lp.academic_year_id, lp.quota_id
    INTO v_lp, v_inst, v_degree, v_dept, v_program, v_semester, v_ay, v_quota
    FROM profiles p JOIN learners_profiles lp ON lp.id = p.learner_id
    WHERE p.id = v_profile;
  SELECT lower(trim(gender)) INTO v_gender FROM profiles WHERE id = v_profile;
  SELECT name, type INTO v_room_cat_name, v_room_cat_type FROM hostel_categories WHERE id = v_room_cat;

  SELECT name INTO v_inst_name FROM institutions WHERE id = v_inst;
  SELECT degree_name INTO v_degree_name FROM degrees WHERE id = v_degree;
  SELECT department_name INTO v_dept_name FROM departments WHERE id = v_dept;
  SELECT program_name INTO v_program_name FROM programs WHERE id = v_program;
  SELECT semester_name INTO v_semester_name FROM semesters WHERE id = v_semester;
  SELECT name INTO v_quota_name FROM quotas WHERE id = v_quota;

  SELECT array_agg(category_id) INTO v_room_cats FROM fn_hostel_learner_room_categories(v_lp);
  SELECT array_agg(category_id) INTO v_mess_cats FROM fn_hostel_learner_mess_categories(v_lp);
  SELECT name INTO v_resolved_room_name FROM hostel_categories WHERE id = v_room_cats[1];
  SELECT name INTO v_resolved_mess_name FROM mess_categories WHERE id = v_mess_cats[1];

  -- Admission-year anchored fee + provenance.
  v_adm_ay := fn_learner_admission_academic_year(v_lp);
  SELECT academic_year_name INTO v_adm_ay_name FROM academic_years WHERE id = v_adm_ay;
  SELECT bf.academic_year_id, bf.academic_year_name, bf.fee
    INTO v_band_ay, v_band_ay_name, v_fee
    FROM fn_learner_band_academic_fee(v_lp) bf;

  SELECT academic_year_name INTO v_ay_name FROM academic_years WHERE id = v_ay;
  v_serves := fn_room_serves_institution(v_room, v_inst);

  WITH rules AS (
    SELECT e.*,
           COALESCE(e.program_id IS NULL OR e.program_id = v_program, false) AS program_ok,
           COALESCE(e.quota_ids IS NULL OR v_quota = ANY(e.quota_ids), false) AS quota_ok,
           (v_fee IS NOT NULL
              AND (e.fee_min IS NULL OR v_fee >= e.fee_min)
              -- Inclusive upper bound — mirrors fn_hostel_effective_room_categories
              -- since 20260724130000. Was `<`, which contradicted the resolver.
              AND (e.fee_max IS NULL OR v_fee <= e.fee_max)) AS fee_ok,
           ( (e.program_id IS NOT NULL)::int * 4
           + (e.quota_ids  IS NOT NULL)::int * 2
           + ((e.fee_min IS NOT NULL OR e.fee_max IS NOT NULL))::int ) AS specificity
    FROM hostel_program_eligibility e
    WHERE e.institution_id = v_inst AND e.is_active
  ),
  room_winner AS (
    SELECT program_id, quota_ids, fee_min, fee_max FROM rules
    WHERE room_category_id IS NOT NULL AND program_ok AND quota_ok AND fee_ok
    ORDER BY specificity DESC, (COALESCE(fee_max, 9.9e14::numeric) - COALESCE(fee_min, 0)) ASC
    LIMIT 1
  ),
  mess_winner AS (
    SELECT program_id, quota_ids, fee_min, fee_max FROM rules
    WHERE mess_category_id IS NOT NULL AND program_ok AND quota_ok AND fee_ok
    ORDER BY specificity DESC, (COALESCE(fee_max, 9.9e14::numeric) - COALESCE(fee_min, 0)) ASC
    LIMIT 1
  )
  SELECT jsonb_agg(jsonb_build_object(
      'program', (SELECT program_name FROM programs WHERE id = r.program_id),
      'quota',   (SELECT string_agg(name, ', ' ORDER BY name) FROM quotas WHERE id = ANY(r.quota_ids)),
      'fee_min', r.fee_min,
      'fee_max', r.fee_max,
      'room_category', (SELECT name FROM hostel_categories WHERE id = r.room_category_id),
      'mess_category', (SELECT name FROM mess_categories  WHERE id = r.mess_category_id),
      'program_ok', r.program_ok,
      'quota_ok',   r.quota_ok,
      'fee_ok',     r.fee_ok,
      'matched',    (r.program_ok AND r.quota_ok AND r.fee_ok),
      'selected_room', (r.room_category_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM room_winner w
        WHERE r.program_id IS NOT DISTINCT FROM w.program_id
          AND r.quota_ids  IS NOT DISTINCT FROM w.quota_ids
          AND r.fee_min    IS NOT DISTINCT FROM w.fee_min
          AND r.fee_max    IS NOT DISTINCT FROM w.fee_max)),
      'selected_mess', (r.mess_category_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM mess_winner w
        WHERE r.program_id IS NOT DISTINCT FROM w.program_id
          AND r.quota_ids  IS NOT DISTINCT FROM w.quota_ids
          AND r.fee_min    IS NOT DISTINCT FROM w.fee_min
          AND r.fee_max    IS NOT DISTINCT FROM w.fee_max))
    ) ORDER BY (r.program_ok AND r.quota_ok AND r.fee_ok) DESC, r.specificity DESC,
               r.fee_min ASC NULLS FIRST)
  INTO v_elig_rules
  FROM rules r;

  SELECT jsonb_agg(jsonb_build_object(
      'description', b.bill_description,
      'amount', b.final_amount,
      'status', b.status,
      'due_date', b.due_date,
      'academic_year', (SELECT academic_year_name FROM academic_years WHERE id = b.academic_year_id),
      -- 'counted' = this bill fed the band fee (i.e. it sits in the anchor year).
      'counted', (COALESCE(b.status NOT IN ('cancelled','superseded'), false)
                  AND b.academic_year_id IS NOT NULL
                  AND b.academic_year_id IS NOT DISTINCT FROM v_band_ay)
    ) ORDER BY b.due_date DESC)
  INTO v_bills
  FROM billing_student_bills b
  WHERE b.student_id = v_lp AND b.fee_source = 'academic';

  WITH covering AS (
    SELECT r.* FROM hostel_room_eligibility_rules r
    WHERE r.is_active AND r.block_id = v_block
      AND CASE
            WHEN EXISTS (SELECT 1 FROM hostel_room_eligibility_rule_rooms rr WHERE rr.rule_id=r.id)
              THEN EXISTS (SELECT 1 FROM hostel_room_eligibility_rule_rooms rr WHERE rr.rule_id=r.id AND rr.room_id=v_room)
            ELSE (r.floor IS NULL OR r.floor = v_floor)
          END
  )
  SELECT
    EXISTS (SELECT 1 FROM covering),
    EXISTS (SELECT 1 FROM covering c WHERE c.institution_id=v_inst
              AND (c.degree_id     IS NULL OR c.degree_id     = v_degree)
              AND (c.department_id IS NULL OR c.department_id = v_dept)
              AND (c.program_id    IS NULL OR c.program_id    = v_program)
              AND (cardinality(c.semester_ids) = 0 OR v_semester = ANY(c.semester_ids))),
    (SELECT jsonb_agg(jsonb_build_object(
       'rule_name', COALESCE(NULLIF(btrim(c.rule_name),''),'(unnamed rule)'),
       'floor', c.floor,
       'matched', COALESCE((c.institution_id=v_inst
              AND (c.degree_id     IS NULL OR c.degree_id     = v_degree)
              AND (c.department_id IS NULL OR c.department_id = v_dept)
              AND (c.program_id    IS NULL OR c.program_id    = v_program)
              AND (cardinality(c.semester_ids) = 0 OR v_semester = ANY(c.semester_ids))), false),
       'cohort', NULLIF(concat_ws(' · ',
         (SELECT degree_name     FROM degrees     WHERE id=c.degree_id),
         (SELECT department_name FROM departments WHERE id=c.department_id),
         (SELECT program_name    FROM programs    WHERE id=c.program_id),
         (SELECT string_agg(s.semester_name, ', ' ORDER BY array_position(c.semester_ids, s.id))
            FROM semesters s WHERE s.id = ANY(c.semester_ids))),''),
       'institution',    (SELECT name FROM institutions WHERE id=c.institution_id),
       'institution_ok', COALESCE(c.institution_id = v_inst, false),
       'degree',         (SELECT degree_name FROM degrees WHERE id=c.degree_id),
       'degree_ok',      COALESCE((c.degree_id IS NULL OR c.degree_id = v_degree), false),
       'department',     (SELECT department_name FROM departments WHERE id=c.department_id),
       'department_ok',  COALESCE((c.department_id IS NULL OR c.department_id = v_dept), false),
       'program',        (SELECT program_name FROM programs WHERE id=c.program_id),
       'program_ok',     COALESCE((c.program_id IS NULL OR c.program_id = v_program), false),
       'semester',       (SELECT string_agg(s.semester_name, ', ' ORDER BY array_position(c.semester_ids, s.id))
                            FROM semesters s WHERE s.id = ANY(c.semester_ids)),
       'semester_ok',    COALESCE((cardinality(c.semester_ids) = 0 OR v_semester = ANY(c.semester_ids)), false)
     ) ORDER BY c.rule_name) FROM covering c)
  INTO v_has_covering, v_matched, v_rules;

  SELECT EXISTS (
    SELECT 1 FROM hostel_room_eligibility_rules r
    WHERE r.is_active
      AND r.institution_id = v_inst
      AND (r.degree_id     IS NULL OR r.degree_id     = v_degree)
      AND (r.department_id IS NULL OR r.department_id = v_dept)
      AND (r.program_id    IS NULL OR r.program_id    = v_program)
      AND (cardinality(r.semester_ids) = 0 OR v_semester = ANY(r.semester_ids))
  ),
  (SELECT string_agg(DISTINCT hb.name, ', ')
     FROM hostel_room_eligibility_rules r
     JOIN hostel_blocks hb ON hb.id = r.block_id
     WHERE r.is_active
       AND r.institution_id = v_inst
       AND (r.degree_id     IS NULL OR r.degree_id     = v_degree)
       AND (r.department_id IS NULL OR r.department_id = v_dept)
       AND (r.program_id    IS NULL OR r.program_id    = v_program)
       AND (cardinality(r.semester_ids) = 0 OR v_semester = ANY(r.semester_ids)))
  INTO v_pinned, v_pinned_blocks;

  SELECT jsonb_agg(jsonb_build_object(
      'block', hb.name,
      'rule_name', COALESCE(NULLIF(btrim(r.rule_name),''),'(unnamed rule)'),
      'floor', r.floor,
      'rooms', (SELECT count(*)::int FROM hostel_room_eligibility_rule_rooms rr WHERE rr.rule_id=r.id),
      'institution', (SELECT name FROM institutions WHERE id=r.institution_id),
      'degree',      (SELECT degree_name FROM degrees WHERE id=r.degree_id),
      'department',  (SELECT department_name FROM departments WHERE id=r.department_id),
      'program',     (SELECT program_name FROM programs WHERE id=r.program_id),
      'semester',    (SELECT string_agg(s.semester_name, ', ' ORDER BY array_position(r.semester_ids, s.id))
                        FROM semesters s WHERE s.id = ANY(r.semester_ids)),
      'covers_allocated_room', (r.block_id = v_block)
    ) ORDER BY hb.name)
  INTO v_pinned_rules
  FROM hostel_room_eligibility_rules r
  JOIN hostel_blocks hb ON hb.id = r.block_id
  WHERE r.is_active
    AND r.institution_id = v_inst
    AND (r.degree_id     IS NULL OR r.degree_id     = v_degree)
    AND (r.department_id IS NULL OR r.department_id = v_dept)
    AND (r.program_id    IS NULL OR r.program_id    = v_program)
    AND (cardinality(r.semester_ids) = 0 OR v_semester = ANY(r.semester_ids));

  SELECT count(*)::int INTO v_acad_bill FROM billing_student_bills b
    WHERE b.student_id=v_lp AND b.fee_source='academic' AND b.status NOT IN ('cancelled','superseded');
  SELECT count(*)::int INTO v_cur_bill FROM billing_student_bills b
    WHERE b.student_id=v_lp AND b.fee_source='academic' AND b.status NOT IN ('cancelled','superseded')
      AND b.academic_year_id=v_band_ay;

  RETURN jsonb_build_object(
    'allocation_id', p_allocation_id, 'room_number', v_room_number, 'status', v_status,
    'learner', jsonb_build_object(
      'institution', v_inst_name,
      'degree', v_degree_name,
      'department', v_dept_name,
      'program', v_program_name,
      'semester', v_semester_name,
      'quota', v_quota_name,
      'academic_year', v_ay_name,
      'admission_academic_year', v_adm_ay_name,
      'fee_academic_year', v_band_ay_name,
      'academic_fee', v_fee,
      'gender', v_gender
    ),
    'eligibility_rules', COALESCE(v_elig_rules, '[]'::jsonb),
    'category', jsonb_build_object(
      'allocated_room_category', v_room_cat_name,
      'resolved_room_category', v_resolved_room_name,
      'room_category_matched', (v_room_cat = ANY(COALESCE(v_room_cats,'{}'::uuid[]))),
      'resolved_mess_category', v_resolved_mess_name,
      'academic_year', v_ay_name,
      'admission_academic_year', v_adm_ay_name,
      'fee_academic_year', v_band_ay_name,
      'academic_fee', v_fee,
      'gender', v_gender,
      'gender_ok', (v_room_cat_type IS NULL
                    OR (v_room_cat_type='boys'  AND v_gender IN ('male','m'))
                    OR (v_room_cat_type='girls' AND v_gender IN ('female','f')))
    ),
    'physical', jsonb_build_object(
      'institution_served', v_serves,
      'is_rule_covered', v_has_covering,
      'rule_matched', v_matched,
      'open_room', NOT v_has_covering,
      'pinned_elsewhere', (v_pinned AND NOT v_matched),
      'pinned_blocks', v_pinned_blocks,
      'pinned_rules', COALESCE(v_pinned_rules, '[]'::jsonb),
      'access_ok', (v_matched OR (NOT v_has_covering AND NOT v_pinned)),
      'covering_rules', COALESCE(v_rules, '[]'::jsonb)
    ),
    'bill', jsonb_build_object('current_year_bills', v_cur_bill, 'academic_bills', v_acad_bill),
    'bills', COALESCE(v_bills, '[]'::jsonb)
  );
END $function$;

REVOKE EXECUTE ON FUNCTION public.fn_explain_allocation(uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_explain_allocation(uuid) TO authenticated, service_role;


-- ============================================================
-- Migration: 20260810150000_auto_allocate_hostel_type_scope.sql
-- Auto-Allocate is scoped by hostel TYPE, not block/floor. The physical-room
-- rules already decide the block (702/703 hostellers pinned by a rule; girls
-- blocks 100% rule-covered), and hostel_years has one is_current row — so the
-- Block, Floor and Hostel Year pickers were all removed from the page.
-- ONE batch now spans every block of the type (block_id NULL).
-- ============================================================
-- ── 1. Capacity summary for the chosen type ────────────────────────────────
DROP FUNCTION IF EXISTS public.fn_auto_allocate_preview(uuid, integer);

CREATE FUNCTION public.fn_auto_allocate_preview(
  p_hostel_type text,
  p_institution_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid
)
RETURNS TABLE(cohort_eligible integer, no_profile integer, already_allocated integer,
              available_beds integer, rules_set boolean)
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  WITH blocks AS (
    SELECT id FROM hostel_blocks WHERE hostel_type::text = p_hostel_type
  ),
  cohort AS (
    SELECT lp.id, lp.institution_id,
           (SELECT array_agg(category_id) FROM fn_hostel_learner_room_categories(lp.id)) AS room_cats
    FROM learners_profiles lp
    LEFT JOIN profiles gp ON gp.learner_id = lp.id
    WHERE lp.accommodation_type_id IN (SELECT id FROM accommodation_types WHERE code='hostel')
      -- Only ACTIVE learners may be allocated a bed. Keep in lockstep with
      -- fn_auto_allocate_candidates / fn_auto_allocate_classic.
      AND lp.lifecycle_status = 'active'
      AND lp.institution_id IN (
            SELECT bi.institution_id FROM hostel_block_institutions bi
            WHERE bi.block_id IN (SELECT id FROM blocks))
      AND (p_institution_id IS NULL OR lp.institution_id = p_institution_id)
      AND (p_program_id     IS NULL OR lp.program_id     = p_program_id)
      AND (p_semester_id    IS NULL OR lp.semester_id    = p_semester_id)
      -- NULL / blank gender is kept so data-incomplete learners still surface
      -- (and so the no_profile counter below still sees them).
      AND (gp.gender IS NULL OR btrim(gp.gender) = ''
           OR (p_hostel_type = 'boys'  AND lower(btrim(gp.gender)) IN ('male','m'))
           OR (p_hostel_type = 'girls' AND lower(btrim(gp.gender)) IN ('female','f')))
  )
  SELECT
    (SELECT count(*)::int FROM cohort c JOIN profiles p ON p.learner_id=c.id
       WHERE c.room_cats IS NOT NULL
         AND NOT EXISTS (SELECT 1 FROM hostel_allocations a WHERE a.learner_id=p.id AND a.status IN ('active','pending_approval'))),
    (SELECT count(*)::int FROM cohort c WHERE c.room_cats IS NOT NULL AND NOT EXISTS (SELECT 1 FROM profiles p WHERE p.learner_id=c.id)),
    (SELECT count(*)::int FROM cohort c JOIN profiles p ON p.learner_id=c.id
       WHERE c.room_cats IS NOT NULL AND EXISTS (SELECT 1 FROM hostel_allocations a WHERE a.learner_id=p.id AND a.status IN ('active','pending_approval'))),
    (SELECT count(*)::int FROM hostel_beds b JOIN hostel_rooms r ON r.id=b.room_id
       WHERE r.block_id IN (SELECT id FROM blocks) AND r.room_purpose='student' AND b.status='available'
         AND NOT EXISTS (SELECT 1 FROM hostel_allocations a WHERE a.bed_id=b.id AND a.status IN ('active','pending_approval'))),
    EXISTS (SELECT 1 FROM hostel_room_eligibility_rules WHERE block_id IN (SELECT id FROM blocks) AND is_active);
$function$;

REVOKE EXECUTE ON FUNCTION public.fn_auto_allocate_preview(text, uuid, uuid, uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_auto_allocate_preview(text, uuid, uuid, uuid) TO authenticated, service_role;


-- ── 2. Per-learner candidate verdicts for the chosen type ──────────────────
DROP FUNCTION IF EXISTS public.fn_auto_allocate_candidates(uuid, boolean, integer, uuid, uuid, uuid);

CREATE FUNCTION public.fn_auto_allocate_candidates(
  p_hostel_type text,
  p_strict boolean DEFAULT true,
  p_institution_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid
)
RETURNS TABLE(
  learner_id uuid, full_name text, email text, institution_name text,
  program_name text, semester_name text, gender text,
  has_profile boolean, gender_ok boolean, not_allocated boolean,
  physical_rule_ok boolean, bed_available boolean, target_block_name text,
  academic_year_id uuid, academic_year_name text,
  admission_academic_year_id uuid, admission_academic_year_name text,
  band_academic_year_id uuid, band_academic_year_name text, band_fee numeric,
  academic_bill_count integer, current_year_bill_count integer,
  bill_other_year_name text, current_year_fee numeric,
  resolved_room_category_id uuid, resolved_room_category_name text,
  resolved_mess_category_id uuid, resolved_mess_category_name text,
  bill_state text, stage text, verdict text, exclusion_reason text
)
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  WITH blocks AS (
    SELECT id FROM hostel_blocks WHERE hostel_type::text = p_hostel_type
  ),
  cohort AS (
    SELECT lp.id, lp.institution_id, lp.degree_id, lp.department_id,
           lp.program_id, lp.semester_id, lp.academic_year_id,
           lp.first_name, lp.last_name,
           room_elig.cats AS room_cats, mess_elig.cats AS mess_cats
    FROM learners_profiles lp
    LEFT JOIN profiles gp ON gp.learner_id = lp.id
    LEFT JOIN LATERAL (SELECT array_agg(category_id) AS cats FROM fn_hostel_learner_room_categories(lp.id)) room_elig ON true
    LEFT JOIN LATERAL (SELECT array_agg(category_id) AS cats FROM fn_hostel_learner_mess_categories(lp.id)) mess_elig ON true
    WHERE lp.accommodation_type_id IN (SELECT id FROM accommodation_types WHERE code = 'hostel')
      AND lp.lifecycle_status = 'active'
      AND lp.institution_id IN (
            SELECT bi.institution_id FROM hostel_block_institutions bi
            WHERE bi.block_id IN (SELECT id FROM blocks))
      AND (p_institution_id IS NULL OR lp.institution_id = p_institution_id)
      AND (p_program_id     IS NULL OR lp.program_id     = p_program_id)
      AND (p_semester_id    IS NULL OR lp.semester_id    = p_semester_id)
      AND (gp.gender IS NULL OR btrim(gp.gender) = ''
           OR (p_hostel_type = 'boys'  AND lower(btrim(gp.gender)) IN ('male','m'))
           OR (p_hostel_type = 'girls' AND lower(btrim(gp.gender)) IN ('female','f')))
      AND NOT EXISTS (
        SELECT 1 FROM hostel_allocations ha2
        JOIN profiles pr2 ON pr2.learner_id = lp.id
        WHERE ha2.learner_id = pr2.id
          AND ha2.status IN ('active', 'pending_approval')
      )
  ),
  base AS (
    SELECT
      c.id AS learner_id,
      COALESCE(p.full_name,
               NULLIF(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''),
               p.email, '—') AS full_name,
      p.email, inst.name AS institution_name, prog.program_name, sem.semester_name,
      lower(trim(p.gender)) AS gender,
      (p.id IS NOT NULL) AS has_profile,
      c.academic_year_id, ay.academic_year_name, c.room_cats, c.mess_cats,
      adm.ay_id AS admission_academic_year_id,
      aay.academic_year_name::text AS admission_academic_year_name,
      bf.academic_year_id AS band_academic_year_id,
      bf.academic_year_name AS band_academic_year_name,
      bf.fee AS band_fee,
      c.room_cats[1] AS resolved_room_category_id,
      rc.name AS resolved_room_category_name, rc.type AS resolved_room_category_type,
      c.mess_cats[1] AS resolved_mess_category_id, mc.name AS resolved_mess_category_name,
      (SELECT count(*)::int FROM billing_student_bills b
         WHERE b.student_id = c.id AND b.fee_source = 'academic'
           AND b.status NOT IN ('cancelled','superseded')) AS academic_bill_count,
      (SELECT count(*)::int FROM billing_student_bills b
         WHERE b.student_id = c.id AND b.fee_source = 'academic'
           AND b.status NOT IN ('cancelled','superseded')
           AND b.academic_year_id = c.academic_year_id) AS current_year_bill_count,
      (SELECT ay2.academic_year_name
         FROM billing_student_bills b JOIN academic_years ay2 ON ay2.id = b.academic_year_id
        WHERE b.student_id = c.id AND b.fee_source = 'academic'
          AND b.status NOT IN ('cancelled','superseded')
          AND b.academic_year_id IS NOT NULL
          AND b.academic_year_id IS DISTINCT FROM c.academic_year_id
        ORDER BY b.created_at DESC LIMIT 1) AS bill_other_year_name,
      -- Diagnostic only: what the OLD current-year rule would have read.
      fn_learner_current_year_academic_fee(c.id) AS current_year_fee,
      true AS not_allocated,
      -- Can they enter ANY room of their resolved category, in any block of this
      -- type that serves their institution? (Was: any room of one chosen block.)
      EXISTS (
        SELECT 1 FROM hostel_rooms rm
        JOIN hostel_categories hc ON hc.id = rm.category_id
        WHERE rm.block_id IN (SELECT id FROM blocks) AND rm.room_purpose = 'student'
          AND rm.category_id = ANY(c.room_cats)
          AND (hc.type IS NULL
               OR (hc.type = 'boys'  AND lower(trim(p.gender)) IN ('male','m'))
               OR (hc.type = 'girls' AND lower(trim(p.gender)) IN ('female','f')))
          AND fn_room_serves_institution(rm.id, c.institution_id)
          AND fn_learner_strictly_eligible_for_room(c.id, rm.id, p_strict)
      ) AS physical_rule_ok,
      EXISTS (
        SELECT 1 FROM hostel_rooms rm
        WHERE rm.block_id IN (SELECT id FROM blocks) AND rm.room_purpose = 'student'
          AND NOT (rm.category_id = ANY(c.room_cats))
          AND fn_room_serves_institution(rm.id, c.institution_id)
          AND fn_learner_strictly_eligible_for_room(c.id, rm.id, p_strict)
      ) AS physical_ok_other_category,
      -- tgt is the bed fn_auto_allocate_classic would actually give them:
      -- SAME ordering, so target_block_name is a real prediction, not a guess.
      (tgt.block_name IS NOT NULL) AS bed_available,
      tgt.block_name AS target_block_name
    FROM cohort c
    LEFT JOIN profiles p       ON p.learner_id = c.id
    LEFT JOIN institutions inst ON inst.id = c.institution_id
    LEFT JOIN programs prog     ON prog.id = c.program_id
    LEFT JOIN semesters sem     ON sem.id = c.semester_id
    LEFT JOIN academic_years ay ON ay.id = c.academic_year_id
    LEFT JOIN LATERAL (SELECT fn_learner_admission_academic_year(c.id) AS ay_id) adm ON true
    LEFT JOIN academic_years aay ON aay.id = adm.ay_id
    LEFT JOIN LATERAL fn_learner_band_academic_fee(c.id) bf ON true
    LEFT JOIN hostel_categories rc ON rc.id = c.room_cats[1]
    LEFT JOIN mess_categories   mc ON mc.id = c.mess_cats[1]
    LEFT JOIN LATERAL (
      SELECT hb.name AS block_name
      FROM hostel_beds bd
      JOIN hostel_rooms r  ON r.id = bd.room_id
      JOIN hostel_blocks hb ON hb.id = r.block_id
      JOIN hostel_categories hc ON hc.id = r.category_id
      WHERE hb.hostel_type::text = p_hostel_type
        AND r.room_purpose = 'student'
        AND bd.status = 'available'
        AND r.category_id = ANY(c.room_cats)
        AND (hc.type IS NULL
             OR (hc.type = 'boys'  AND lower(trim(p.gender)) IN ('male','m'))
             OR (hc.type = 'girls' AND lower(trim(p.gender)) IN ('female','f')))
        AND fn_room_serves_institution(r.id, c.institution_id)
        AND NOT EXISTS (SELECT 1 FROM hostel_allocations a
                        WHERE a.bed_id = bd.id AND a.status IN ('active','pending_approval'))
        AND fn_learner_strictly_eligible_for_room(c.id, r.id, p_strict)
      ORDER BY array_position(c.room_cats, r.category_id), hb.name, r.floor, r.room_number, bd.bed_number
      LIMIT 1
    ) tgt ON true
  ),
  scored AS (
    SELECT b.*,
      (b.resolved_room_category_type IS NULL
        OR (b.resolved_room_category_type = 'boys'  AND b.gender IN ('male','m'))
        OR (b.resolved_room_category_type = 'girls' AND b.gender IN ('female','f'))) AS gender_ok
    FROM base b
  )
  SELECT
    s.learner_id, s.full_name, s.email, s.institution_name, s.program_name, s.semester_name,
    s.gender, s.has_profile, s.gender_ok, s.not_allocated, s.physical_rule_ok,
    s.bed_available, s.target_block_name,
    s.academic_year_id, s.academic_year_name,
    s.admission_academic_year_id, s.admission_academic_year_name,
    s.band_academic_year_id, s.band_academic_year_name, s.band_fee,
    s.academic_bill_count, s.current_year_bill_count, s.bill_other_year_name, s.current_year_fee,
    s.resolved_room_category_id, s.resolved_room_category_name,
    s.resolved_mess_category_id, s.resolved_mess_category_name,
    CASE
      WHEN s.band_fee IS NOT NULL
       AND s.band_academic_year_id IS NOT DISTINCT FROM s.admission_academic_year_id THEN 'matched'
      WHEN s.band_fee IS NOT NULL          THEN 'different_year'
      WHEN s.academic_bill_count > 0       THEN 'untagged'
      ELSE 'none'
    END AS bill_state,
    CASE
      WHEN s.band_fee  IS NULL THEN 'prerequisite'
      WHEN s.room_cats IS NULL THEN 'prerequisite'
      WHEN NOT s.has_profile OR NOT s.gender_ok OR NOT s.physical_rule_ok OR NOT s.bed_available
                               THEN 'eligibility'
      ELSE 'ok'
    END AS stage,
    CASE
      WHEN s.band_fee  IS NULL THEN 'out'
      WHEN s.room_cats IS NULL THEN 'out'
      WHEN NOT s.has_profile OR NOT s.gender_ok OR NOT s.physical_rule_ok OR NOT s.bed_available
                               THEN 'out'
      ELSE 'in'
    END AS verdict,
    CASE
      WHEN s.band_fee IS NULL THEN
        CASE
          WHEN s.academic_bill_count = 0 THEN
            'No academic bill for this student — nothing to read a fee band from'
          ELSE
            'Academic bills exist but none is usable: either untagged to an academic year, or the tagged year totals ₹0'
        END
      WHEN s.room_cats IS NULL THEN
        'No Category-Eligibility band covers ₹'
        || to_char(s.band_fee, 'FM999,999,999')
        || ' (read from ' || COALESCE(s.band_academic_year_name, 'their admission year') || ')'
        || ' for this program / quota — add or widen a band'
      WHEN NOT s.has_profile   THEN 'No login profile'
      WHEN NOT s.gender_ok     THEN 'Gender does not match the resolved room category'
      WHEN NOT s.physical_rule_ok AND s.physical_ok_other_category THEN
        'Rooms they may occupy are a different room category than their eligible '
        || COALESCE(s.resolved_room_category_name, 'category')
        || ' — fix the reservation rooms or the Category-Eligibility band'
      WHEN NOT s.physical_rule_ok THEN
        CASE WHEN p_strict
          THEN 'No physical-room rule reserves a room for this cohort in any ' || p_hostel_type || ' block (strict mode)'
          ELSE 'No room they can occupy in their category — every room is reserved for other cohorts'
        END
      WHEN NOT s.bed_available THEN 'Their category rooms are full — no free bed in any ' || p_hostel_type || ' block'
      ELSE NULL
    END AS exclusion_reason
  FROM scored s
  ORDER BY s.full_name;
$function$;

REVOKE EXECUTE ON FUNCTION public.fn_auto_allocate_candidates(text, boolean, uuid, uuid, uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_auto_allocate_candidates(text, boolean, uuid, uuid, uuid) TO authenticated, service_role;


-- ── 3. Generate — one batch spanning every block of the type ───────────────
DROP FUNCTION IF EXISTS public.fn_auto_allocate_classic(uuid, uuid, boolean, integer, uuid, uuid, uuid);

CREATE FUNCTION public.fn_auto_allocate_classic(
  p_hostel_type text,
  p_hostel_year_id uuid DEFAULT NULL::uuid,
  p_strict boolean DEFAULT true,
  p_institution_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_batch uuid; v_tier uuid; v_actor uuid := auth.uid();
  v_alloc int := 0; v_skip int := 0;
  v_year uuid; v_ay uuid;
  cand record; v_bed uuid; v_room uuid; v_block uuid; v_mess uuid;
BEGIN
  IF NOT (is_super_admin() OR is_admin() OR user_has_permission('campus_living.allocations.create')) THEN
    RAISE EXCEPTION 'Not authorized to run auto-allocation';
  END IF;

  IF p_hostel_type IS NULL OR p_hostel_type NOT IN ('boys','girls') THEN
    RAISE EXCEPTION 'Hostel type must be boys or girls';
  END IF;

  -- hostel_years carries exactly one is_current row; the picker was noise.
  v_year := COALESCE(p_hostel_year_id, (SELECT id FROM hostel_years WHERE is_current LIMIT 1));
  IF v_year IS NULL THEN
    RAISE EXCEPTION 'No current hostel year is set — mark one under Campus Living → Settings → Hostel Years';
  END IF;

  SELECT id INTO v_tier FROM hostel_tier_policy WHERE tier_key='standard' AND institution_id IS NULL AND is_active LIMIT 1;
  IF v_tier IS NULL THEN SELECT id INTO v_tier FROM hostel_tier_policy WHERE tier_key='standard' AND is_active LIMIT 1; END IF;
  IF v_tier IS NULL THEN RAISE EXCEPTION 'No standard tier policy found'; END IF;

  -- block_id NULL: this batch spans every block of the type. Each allocation
  -- row still records the block it landed in.
  INSERT INTO hostel_allocation_batches (block_id, category_id, hostel_year_id, status, created_by)
  VALUES (NULL, NULL, v_year, 'pending_approval', v_actor)
  RETURNING id INTO v_batch;

  FOR cand IN
    SELECT lp.id AS lp_id, p.id AS profile_id, lp.semester_id AS sem_id,
           lp.academic_year_id AS ay_id, lp.institution_id AS inst,
           lower(trim(p.gender)) AS gender,
           room_elig.cats AS room_cats, mess_elig.cats AS mess_cats
    FROM learners_profiles lp
    JOIN profiles p ON p.learner_id = lp.id
    JOIN institutions inst_t ON inst_t.id = lp.institution_id
    LEFT JOIN LATERAL (SELECT array_agg(category_id) AS cats FROM fn_hostel_learner_room_categories(lp.id)) room_elig ON true
    LEFT JOIN LATERAL (SELECT array_agg(category_id) AS cats FROM fn_hostel_learner_mess_categories(lp.id)) mess_elig ON true
    -- Is this learner's institution served by ANY block of the type, and is it
    -- the primary institution of one? bool_or over zero rows => NULL => filtered.
    LEFT JOIN LATERAL (
      SELECT bool_or(hbi.is_primary) AS is_primary
      FROM hostel_block_institutions hbi
      JOIN hostel_blocks hb ON hb.id = hbi.block_id
      WHERE hb.hostel_type::text = p_hostel_type
        AND hbi.institution_id = lp.institution_id
    ) prim ON true
    LEFT JOIN LATERAL (
      SELECT min(array_position(r.semester_ids, lp.semester_id)) AS rank
      FROM hostel_room_eligibility_rules r
      JOIN hostel_blocks hb ON hb.id = r.block_id
      WHERE r.is_active
        AND hb.hostel_type::text = p_hostel_type
        AND r.institution_id = lp.institution_id
        AND (r.degree_id     IS NULL OR r.degree_id     = lp.degree_id)
        AND (r.department_id IS NULL OR r.department_id = lp.department_id)
        AND (r.program_id    IS NULL OR r.program_id    = lp.program_id)
        AND cardinality(r.semester_ids) > 1
        AND lp.semester_id = ANY(r.semester_ids)
    ) sem_fill ON true
    WHERE lp.accommodation_type_id IN (SELECT id FROM accommodation_types WHERE code = 'hostel')
      AND lp.lifecycle_status = 'active'
      AND room_elig.cats IS NOT NULL
      AND prim.is_primary IS NOT NULL
      -- Cohort-level gender filter, mirroring fn_auto_allocate_candidates so
      -- preview == generate (bed-level hostel_categories.type still applies).
      AND (p.gender IS NULL OR btrim(p.gender) = ''
           OR (p_hostel_type = 'boys'  AND lower(btrim(p.gender)) IN ('male','m'))
           OR (p_hostel_type = 'girls' AND lower(btrim(p.gender)) IN ('female','f')))
      AND NOT EXISTS (SELECT 1 FROM hostel_allocations a WHERE a.learner_id=p.id AND a.status IN ('active','pending_approval'))
      AND (p_institution_id IS NULL OR lp.institution_id = p_institution_id)
      AND (p_program_id     IS NULL OR lp.program_id     = p_program_id)
      AND (p_semester_id    IS NULL OR lp.semester_id    = p_semester_id)
    ORDER BY COALESCE(sem_fill.rank, 1),
             prim.is_primary DESC,
             lower(coalesce(inst_t.name,'')),
             lower(coalesce(lp.first_name,'')), lower(coalesce(lp.last_name,'')), lp.id
  LOOP
    v_ay := COALESCE(cand.ay_id, (SELECT id FROM academic_years WHERE institution_id=cand.inst AND is_active ORDER BY start_date DESC LIMIT 1));
    IF v_ay IS NULL THEN v_skip := v_skip + 1; CONTINUE; END IF;

    v_bed := NULL; v_room := NULL; v_block := NULL;
    -- Same ORDER BY as fn_auto_allocate_candidates' target_block_name lateral.
    SELECT b.id, r.id, r.block_id INTO v_bed, v_room, v_block
    FROM hostel_beds b
    JOIN hostel_rooms r ON r.id=b.room_id
    JOIN hostel_blocks hb ON hb.id = r.block_id
    JOIN hostel_categories hc ON hc.id = r.category_id
    WHERE hb.hostel_type::text = p_hostel_type
      AND r.room_purpose='student' AND b.status='available'
      AND r.category_id = ANY(cand.room_cats)
      AND (hc.type IS NULL
           OR (hc.type='boys'  AND cand.gender IN ('male','m'))
           OR (hc.type='girls' AND cand.gender IN ('female','f')))
      AND fn_room_serves_institution(r.id, cand.inst)
      AND NOT EXISTS (SELECT 1 FROM hostel_allocations a WHERE a.bed_id=b.id AND a.status IN ('active','pending_approval'))
      AND fn_learner_strictly_eligible_for_room(cand.lp_id, r.id, p_strict)
    ORDER BY array_position(cand.room_cats, r.category_id), hb.name, r.floor, r.room_number, b.bed_number
    LIMIT 1;

    IF v_bed IS NULL THEN v_skip := v_skip + 1; CONTINUE; END IF;

    INSERT INTO hostel_allocations (
      institution_id, learner_id, block_id, room_id, bed_id, academic_year_id, semester_id,
      allocation_type, allocation_date, status,
      emergency_contact_name, emergency_contact_phone, emergency_contact_relation,
      tier_id, batch_id, allocated_by, warden_id
    ) VALUES (
      cand.inst, cand.profile_id, v_block, v_room, v_bed, v_ay, cand.sem_id,
      'fresh', CURRENT_DATE, 'pending_approval', '', '', '',
      v_tier, v_batch, v_actor,
      (SELECT user_id FROM user_block_access WHERE block_id=v_block AND revoked_at IS NULL LIMIT 1)
    );

    v_mess := CASE WHEN cand.mess_cats IS NOT NULL THEN cand.mess_cats[1] ELSE NULL END;
    UPDATE learners_profiles
      SET hostel_category_id = (SELECT category_id FROM hostel_rooms WHERE id = v_room),
          mess_category_id   = COALESCE(v_mess, mess_category_id),
          updated_at = now()
      WHERE id = cand.lp_id;

    v_alloc := v_alloc + 1;
  END LOOP;

  UPDATE hostel_allocation_batches
    SET allocated_count = v_alloc, skipped_count = v_skip,
        notes = format('%s allocated across all %s blocks (%s physical mode; rules-driven category + mess; block and room decided by the physical-room rules). %s skipped (no free bed they can occupy / reserved rooms hold no space for them / gender / no academic year). Strict: learners with no rule-resolved room category are excluded. Cohort: lifecycle_status = active only.',
                       v_alloc, p_hostel_type,
                       CASE WHEN p_strict THEN 'STRICT — only cohorts matching a physical rule' ELSE 'open — rule-free rooms shared' END,
                       v_skip)
    WHERE id = v_batch;

  RETURN v_batch;
END $function$;

REVOKE EXECUTE ON FUNCTION public.fn_auto_allocate_classic(text, uuid, boolean, uuid, uuid, uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_auto_allocate_classic(text, uuid, boolean, uuid, uuid, uuid) TO authenticated, service_role;


-- ============================================================
-- Migration: 20260810160000_auto_allocate_signature_cache.sql
-- PERF FIX. Sweeping every block of a hostel type made
-- fn_auto_allocate_candidates take 30,061ms, past the authenticated
-- role statement_timeout of 8s -> PostgREST 57014 -> the Preview button
-- silently showed nothing. fn_learner_strictly_eligible_for_room reads only
-- (institution, degree, department, program, semester) off the learner, so
-- eligibility is now evaluated once per distinct cohort SIGNATURE (410 girls
-- -> 38 signatures) instead of once per learner-room. 30,061ms -> 1,027ms,
-- with 0 diffs in physical_rule_ok / bed_available / category / fee over all
-- 292 boys candidates. fn_auto_allocate_classic gets the same treatment via
-- ON COMMIT DROP temp tables (its loop had the identical cost).
-- ============================================================
-- ── 1. Preview: per-learner verdicts ───────────────────────────────────────
DROP FUNCTION IF EXISTS public.fn_auto_allocate_candidates(text, boolean, uuid, uuid, uuid);

CREATE FUNCTION public.fn_auto_allocate_candidates(
  p_hostel_type text,
  p_strict boolean DEFAULT true,
  p_institution_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid
)
RETURNS TABLE(
  learner_id uuid, full_name text, email text, institution_name text,
  program_name text, semester_name text, gender text,
  has_profile boolean, gender_ok boolean, not_allocated boolean,
  physical_rule_ok boolean, bed_available boolean, target_block_name text,
  academic_year_id uuid, academic_year_name text,
  admission_academic_year_id uuid, admission_academic_year_name text,
  band_academic_year_id uuid, band_academic_year_name text, band_fee numeric,
  academic_bill_count integer, current_year_bill_count integer,
  bill_other_year_name text, current_year_fee numeric,
  resolved_room_category_id uuid, resolved_room_category_name text,
  resolved_mess_category_id uuid, resolved_mess_category_name text,
  bill_state text, stage text, verdict text, exclusion_reason text
)
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  WITH blocks AS MATERIALIZED (
    SELECT id, name FROM hostel_blocks WHERE hostel_type::text = p_hostel_type
  ),
  scope_rooms AS MATERIALIZED (
    SELECT r.id, r.block_id, b.name AS block_name, r.floor, r.room_number,
           r.category_id, hc.type AS cat_type
    FROM hostel_rooms r
    JOIN blocks b ON b.id = r.block_id
    LEFT JOIN hostel_categories hc ON hc.id = r.category_id
    WHERE r.room_purpose = 'student'
  ),
  raw_cohort AS MATERIALIZED (
    SELECT lp.id, lp.institution_id, lp.degree_id, lp.department_id,
           lp.program_id, lp.semester_id, lp.academic_year_id, lp.quota_id,
           lp.first_name, lp.last_name,
           CASE WHEN lower(lp.gender) LIKE 'm%' THEN 'boys'
                WHEN lower(lp.gender) LIKE 'f%' THEN 'girls' END AS lp_gender_type
    FROM learners_profiles lp
    LEFT JOIN profiles gp ON gp.learner_id = lp.id
    WHERE lp.accommodation_type_id IN (SELECT id FROM accommodation_types WHERE code = 'hostel')
      AND lp.lifecycle_status = 'active'
      AND lp.institution_id IN (
            SELECT bi.institution_id FROM hostel_block_institutions bi
            WHERE bi.block_id IN (SELECT id FROM blocks))
      AND (p_institution_id IS NULL OR lp.institution_id = p_institution_id)
      AND (p_program_id     IS NULL OR lp.program_id     = p_program_id)
      AND (p_semester_id    IS NULL OR lp.semester_id    = p_semester_id)
      AND (gp.gender IS NULL OR btrim(gp.gender) = ''
           OR (p_hostel_type = 'boys'  AND lower(btrim(gp.gender)) IN ('male','m'))
           OR (p_hostel_type = 'girls' AND lower(btrim(gp.gender)) IN ('female','f')))
      AND NOT EXISTS (
        SELECT 1 FROM hostel_allocations ha2
        JOIN profiles pr2 ON pr2.learner_id = lp.id
        WHERE ha2.learner_id = pr2.id
          AND ha2.status IN ('active', 'pending_approval')
      )
  ),
  sigs AS MATERIALIZED (
    SELECT institution_id, degree_id, department_id, program_id, semester_id,
           (array_agg(id))[1] AS rep
    FROM raw_cohort
    GROUP BY 1,2,3,4,5
  ),
  sig_rooms AS MATERIALIZED (
    SELECT s.rep, sr.id AS room_id, sr.category_id, sr.cat_type,
           sr.block_name, sr.floor, sr.room_number
    FROM sigs s
    CROSS JOIN scope_rooms sr
    WHERE fn_room_serves_institution(sr.id, s.institution_id)
      AND fn_learner_strictly_eligible_for_room(s.rep, sr.id, p_strict)
  ),
  free_beds AS MATERIALIZED (
    SELECT bd.id, bd.room_id, bd.bed_number
    FROM hostel_beds bd
    JOIN scope_rooms sr ON sr.id = bd.room_id
    WHERE bd.status = 'available'
      AND NOT EXISTS (SELECT 1 FROM hostel_allocations a
                      WHERE a.bed_id = bd.id AND a.status IN ('active','pending_approval'))
  ),
  fee AS MATERIALIZED (
    SELECT c.id, adm.ay_id AS adm_ay,
           bf.academic_year_id AS band_ay, bf.academic_year_name AS band_ay_name, bf.fee
    FROM raw_cohort c
    LEFT JOIN LATERAL (SELECT fn_learner_admission_academic_year(c.id) AS ay_id) adm ON true
    LEFT JOIN LATERAL fn_learner_band_academic_fee(c.id) bf ON true
  ),
  cats AS MATERIALIZED (
    SELECT c.id,
      CASE WHEN c.institution_id IS NOT NULL AND c.program_id IS NOT NULL AND f.fee IS NOT NULL
           THEN (SELECT array_agg(category_id) FROM fn_hostel_effective_room_categories(
                   c.institution_id, c.program_id, c.quota_id, f.fee, c.lp_gender_type)) END AS room_cats,
      CASE WHEN c.institution_id IS NOT NULL AND c.program_id IS NOT NULL AND f.fee IS NOT NULL
           THEN (SELECT array_agg(category_id) FROM fn_hostel_effective_mess_categories(
                   c.institution_id, c.program_id, c.quota_id, f.fee, c.lp_gender_type)) END AS mess_cats
    FROM raw_cohort c JOIN fee f ON f.id = c.id
  ),
  base AS (
    SELECT
      c.id AS learner_id,
      COALESCE(p.full_name,
               NULLIF(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''),
               p.email, '—') AS full_name,
      p.email, inst.name AS institution_name, prog.program_name, sem.semester_name,
      lower(trim(p.gender)) AS gender,
      (p.id IS NOT NULL) AS has_profile,
      c.academic_year_id, ay.academic_year_name,
      ct.room_cats, ct.mess_cats,
      f.adm_ay AS admission_academic_year_id,
      aay.academic_year_name::text AS admission_academic_year_name,
      f.band_ay AS band_academic_year_id,
      f.band_ay_name AS band_academic_year_name,
      f.fee AS band_fee,
      ct.room_cats[1] AS resolved_room_category_id,
      rc.name AS resolved_room_category_name, rc.type AS resolved_room_category_type,
      ct.mess_cats[1] AS resolved_mess_category_id, mc.name AS resolved_mess_category_name,
      (SELECT count(*)::int FROM billing_student_bills b
         WHERE b.student_id = c.id AND b.fee_source = 'academic'
           AND b.status NOT IN ('cancelled','superseded')) AS academic_bill_count,
      (SELECT count(*)::int FROM billing_student_bills b
         WHERE b.student_id = c.id AND b.fee_source = 'academic'
           AND b.status NOT IN ('cancelled','superseded')
           AND b.academic_year_id = c.academic_year_id) AS current_year_bill_count,
      (SELECT ay2.academic_year_name
         FROM billing_student_bills b JOIN academic_years ay2 ON ay2.id = b.academic_year_id
        WHERE b.student_id = c.id AND b.fee_source = 'academic'
          AND b.status NOT IN ('cancelled','superseded')
          AND b.academic_year_id IS NOT NULL
          AND b.academic_year_id IS DISTINCT FROM c.academic_year_id
        ORDER BY b.created_at DESC LIMIT 1) AS bill_other_year_name,
      fn_learner_current_year_academic_fee(c.id) AS current_year_fee,
      true AS not_allocated,
      EXISTS (
        SELECT 1 FROM sig_rooms sr
        WHERE sr.rep = s.rep
          AND sr.category_id = ANY(ct.room_cats)
          AND (sr.cat_type IS NULL
               OR (sr.cat_type = 'boys'  AND lower(trim(p.gender)) IN ('male','m'))
               OR (sr.cat_type = 'girls' AND lower(trim(p.gender)) IN ('female','f')))
      ) AS physical_rule_ok,
      EXISTS (
        SELECT 1 FROM sig_rooms sr
        WHERE sr.rep = s.rep
          AND NOT (sr.category_id = ANY(ct.room_cats))
      ) AS physical_ok_other_category,
      (tgt.block_name IS NOT NULL) AS bed_available,
      tgt.block_name AS target_block_name
    FROM raw_cohort c
    JOIN cats ct ON ct.id = c.id
    JOIN fee  f  ON f.id  = c.id
    JOIN sigs s  ON s.institution_id IS NOT DISTINCT FROM c.institution_id
                AND s.degree_id      IS NOT DISTINCT FROM c.degree_id
                AND s.department_id  IS NOT DISTINCT FROM c.department_id
                AND s.program_id     IS NOT DISTINCT FROM c.program_id
                AND s.semester_id    IS NOT DISTINCT FROM c.semester_id
    LEFT JOIN profiles p        ON p.learner_id = c.id
    LEFT JOIN institutions inst ON inst.id = c.institution_id
    LEFT JOIN programs prog     ON prog.id = c.program_id
    LEFT JOIN semesters sem     ON sem.id = c.semester_id
    LEFT JOIN academic_years ay ON ay.id = c.academic_year_id
    LEFT JOIN academic_years aay ON aay.id = f.adm_ay
    LEFT JOIN hostel_categories rc ON rc.id = ct.room_cats[1]
    LEFT JOIN mess_categories   mc ON mc.id = ct.mess_cats[1]
    LEFT JOIN LATERAL (
      SELECT sr.block_name
      FROM sig_rooms sr
      JOIN free_beds bd ON bd.room_id = sr.room_id
      WHERE sr.rep = s.rep
        AND sr.category_id = ANY(ct.room_cats)
        AND (sr.cat_type IS NULL
             OR (sr.cat_type = 'boys'  AND lower(trim(p.gender)) IN ('male','m'))
             OR (sr.cat_type = 'girls' AND lower(trim(p.gender)) IN ('female','f')))
      ORDER BY array_position(ct.room_cats, sr.category_id),
               sr.block_name, sr.floor, sr.room_number, bd.bed_number
      LIMIT 1
    ) tgt ON true
  ),
  scored AS (
    SELECT b.*,
      (b.resolved_room_category_type IS NULL
        OR (b.resolved_room_category_type = 'boys'  AND b.gender IN ('male','m'))
        OR (b.resolved_room_category_type = 'girls' AND b.gender IN ('female','f'))) AS gender_ok
    FROM base b
  )
  SELECT
    s.learner_id, s.full_name, s.email, s.institution_name, s.program_name, s.semester_name,
    s.gender, s.has_profile, s.gender_ok, s.not_allocated, s.physical_rule_ok,
    s.bed_available, s.target_block_name,
    s.academic_year_id, s.academic_year_name,
    s.admission_academic_year_id, s.admission_academic_year_name,
    s.band_academic_year_id, s.band_academic_year_name, s.band_fee,
    s.academic_bill_count, s.current_year_bill_count, s.bill_other_year_name, s.current_year_fee,
    s.resolved_room_category_id, s.resolved_room_category_name,
    s.resolved_mess_category_id, s.resolved_mess_category_name,
    CASE
      WHEN s.band_fee IS NOT NULL
       AND s.band_academic_year_id IS NOT DISTINCT FROM s.admission_academic_year_id THEN 'matched'
      WHEN s.band_fee IS NOT NULL          THEN 'different_year'
      WHEN s.academic_bill_count > 0       THEN 'untagged'
      ELSE 'none'
    END AS bill_state,
    CASE
      WHEN s.band_fee  IS NULL THEN 'prerequisite'
      WHEN s.room_cats IS NULL THEN 'prerequisite'
      WHEN NOT s.has_profile OR NOT s.gender_ok OR NOT s.physical_rule_ok OR NOT s.bed_available
                               THEN 'eligibility'
      ELSE 'ok'
    END AS stage,
    CASE
      WHEN s.band_fee  IS NULL THEN 'out'
      WHEN s.room_cats IS NULL THEN 'out'
      WHEN NOT s.has_profile OR NOT s.gender_ok OR NOT s.physical_rule_ok OR NOT s.bed_available
                               THEN 'out'
      ELSE 'in'
    END AS verdict,
    CASE
      WHEN s.band_fee IS NULL THEN
        CASE
          WHEN s.academic_bill_count = 0 THEN
            'No academic bill for this student — nothing to read a fee band from'
          ELSE
            'Academic bills exist but none is usable: either untagged to an academic year, or the tagged year totals ₹0'
        END
      WHEN s.room_cats IS NULL THEN
        'No Category-Eligibility band covers ₹'
        || to_char(s.band_fee, 'FM999,999,999')
        || ' (read from ' || COALESCE(s.band_academic_year_name, 'their admission year') || ')'
        || ' for this program / quota — add or widen a band'
      WHEN NOT s.has_profile   THEN 'No login profile'
      WHEN NOT s.gender_ok     THEN 'Gender does not match the resolved room category'
      WHEN NOT s.physical_rule_ok AND s.physical_ok_other_category THEN
        'Rooms they may occupy are a different room category than their eligible '
        || COALESCE(s.resolved_room_category_name, 'category')
        || ' — fix the reservation rooms or the Category-Eligibility band'
      WHEN NOT s.physical_rule_ok THEN
        CASE WHEN p_strict
          THEN 'No physical-room rule reserves a room for this cohort in any ' || p_hostel_type || ' block (strict mode)'
          ELSE 'No room they can occupy in their category — every room is reserved for other cohorts'
        END
      WHEN NOT s.bed_available THEN 'Their category rooms are full — no free bed in any ' || p_hostel_type || ' block'
      ELSE NULL
    END AS exclusion_reason
  FROM scored s
  ORDER BY s.full_name;
$function$;

REVOKE EXECUTE ON FUNCTION public.fn_auto_allocate_candidates(text, boolean, uuid, uuid, uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_auto_allocate_candidates(text, boolean, uuid, uuid, uuid) TO authenticated, service_role;


-- ── 2. Generate: same signature cache, via ON COMMIT DROP temp tables ───────
--
-- Signature unchanged, so CREATE OR REPLACE (no grant loss). The loop used to
-- run a bed search with ORDER BY over every bed x the plpgsql predicate, once
-- per learner — the same cost that broke the preview, and it would have blown
-- the 8s timeout on Generate too. Now the (signature, room) eligibility map is
-- built once up front; only BED AVAILABILITY is re-checked per iteration,
-- because earlier learners in the same run consume beds.
CREATE OR REPLACE FUNCTION public.fn_auto_allocate_classic(
  p_hostel_type text,
  p_hostel_year_id uuid DEFAULT NULL::uuid,
  p_strict boolean DEFAULT true,
  p_institution_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_batch uuid; v_tier uuid; v_actor uuid := auth.uid();
  v_alloc int := 0; v_skip int := 0;
  v_year uuid; v_ay uuid;
  cand record; v_bed uuid; v_room uuid; v_block uuid; v_mess uuid;
BEGIN
  IF NOT (is_super_admin() OR is_admin() OR user_has_permission('campus_living.allocations.create')) THEN
    RAISE EXCEPTION 'Not authorized to run auto-allocation';
  END IF;

  IF p_hostel_type IS NULL OR p_hostel_type NOT IN ('boys','girls') THEN
    RAISE EXCEPTION 'Hostel type must be boys or girls';
  END IF;

  v_year := COALESCE(p_hostel_year_id, (SELECT id FROM hostel_years WHERE is_current LIMIT 1));
  IF v_year IS NULL THEN
    RAISE EXCEPTION 'No current hostel year is set — mark one under Campus Living → Settings → Hostel Years';
  END IF;

  SELECT id INTO v_tier FROM hostel_tier_policy WHERE tier_key='standard' AND institution_id IS NULL AND is_active LIMIT 1;
  IF v_tier IS NULL THEN SELECT id INTO v_tier FROM hostel_tier_policy WHERE tier_key='standard' AND is_active LIMIT 1; END IF;
  IF v_tier IS NULL THEN RAISE EXCEPTION 'No standard tier policy found'; END IF;

  CREATE TEMP TABLE _aa_cand ON COMMIT DROP AS
    SELECT lp.id AS lp_id, p.id AS profile_id, lp.semester_id AS sem_id,
           lp.academic_year_id AS ay_id, lp.institution_id AS inst,
           lp.degree_id, lp.department_id, lp.program_id,
           lower(trim(p.gender)) AS gender,
           room_elig.cats AS room_cats, mess_elig.cats AS mess_cats,
           COALESCE(sem_fill.rank, 1) AS fill_rank,
           prim.is_primary,
           lower(coalesce(inst_t.name,'')) AS inst_name,
           lower(coalesce(lp.first_name,'')) AS fname,
           lower(coalesce(lp.last_name,''))  AS lname
    FROM learners_profiles lp
    JOIN profiles p ON p.learner_id = lp.id
    JOIN institutions inst_t ON inst_t.id = lp.institution_id
    LEFT JOIN LATERAL (SELECT array_agg(category_id) AS cats FROM fn_hostel_learner_room_categories(lp.id)) room_elig ON true
    LEFT JOIN LATERAL (SELECT array_agg(category_id) AS cats FROM fn_hostel_learner_mess_categories(lp.id)) mess_elig ON true
    LEFT JOIN LATERAL (
      SELECT bool_or(hbi.is_primary) AS is_primary
      FROM hostel_block_institutions hbi
      JOIN hostel_blocks hb ON hb.id = hbi.block_id
      WHERE hb.hostel_type::text = p_hostel_type
        AND hbi.institution_id = lp.institution_id
    ) prim ON true
    LEFT JOIN LATERAL (
      SELECT min(array_position(r.semester_ids, lp.semester_id)) AS rank
      FROM hostel_room_eligibility_rules r
      JOIN hostel_blocks hb ON hb.id = r.block_id
      WHERE r.is_active
        AND hb.hostel_type::text = p_hostel_type
        AND r.institution_id = lp.institution_id
        AND (r.degree_id     IS NULL OR r.degree_id     = lp.degree_id)
        AND (r.department_id IS NULL OR r.department_id = lp.department_id)
        AND (r.program_id    IS NULL OR r.program_id    = lp.program_id)
        AND cardinality(r.semester_ids) > 1
        AND lp.semester_id = ANY(r.semester_ids)
    ) sem_fill ON true
    WHERE lp.accommodation_type_id IN (SELECT id FROM accommodation_types WHERE code = 'hostel')
      AND lp.lifecycle_status = 'active'
      AND room_elig.cats IS NOT NULL
      AND prim.is_primary IS NOT NULL
      AND (p.gender IS NULL OR btrim(p.gender) = ''
           OR (p_hostel_type = 'boys'  AND lower(btrim(p.gender)) IN ('male','m'))
           OR (p_hostel_type = 'girls' AND lower(btrim(p.gender)) IN ('female','f')))
      AND NOT EXISTS (SELECT 1 FROM hostel_allocations a WHERE a.learner_id=p.id AND a.status IN ('active','pending_approval'))
      AND (p_institution_id IS NULL OR lp.institution_id = p_institution_id)
      AND (p_program_id     IS NULL OR lp.program_id     = p_program_id)
      AND (p_semester_id    IS NULL OR lp.semester_id    = p_semester_id);

  CREATE TEMP TABLE _aa_sig_rooms ON COMMIT DROP AS
    SELECT s.inst, s.degree_id, s.department_id, s.program_id, s.sem_id,
           r.id AS room_id, r.category_id, r.block_id, r.floor, r.room_number,
           hb.name AS block_name, hc.type AS cat_type
    FROM (SELECT DISTINCT inst, degree_id, department_id, program_id, sem_id,
                 (array_agg(lp_id))[1] AS rep
          FROM _aa_cand GROUP BY inst, degree_id, department_id, program_id, sem_id) s
    CROSS JOIN LATERAL (
      SELECT r.* FROM hostel_rooms r
      JOIN hostel_blocks hb2 ON hb2.id = r.block_id
      WHERE hb2.hostel_type::text = p_hostel_type AND r.room_purpose = 'student'
    ) r
    JOIN hostel_blocks hb ON hb.id = r.block_id
    LEFT JOIN hostel_categories hc ON hc.id = r.category_id
    WHERE fn_room_serves_institution(r.id, s.inst)
      AND fn_learner_strictly_eligible_for_room(s.rep, r.id, p_strict);

  CREATE INDEX ON _aa_sig_rooms (inst, degree_id, department_id, program_id, sem_id);

  INSERT INTO hostel_allocation_batches (block_id, category_id, hostel_year_id, status, created_by)
  VALUES (NULL, NULL, v_year, 'pending_approval', v_actor)
  RETURNING id INTO v_batch;

  FOR cand IN
    SELECT * FROM _aa_cand
    ORDER BY fill_rank, is_primary DESC, inst_name, fname, lname, lp_id
  LOOP
    v_ay := COALESCE(cand.ay_id, (SELECT id FROM academic_years WHERE institution_id=cand.inst AND is_active ORDER BY start_date DESC LIMIT 1));
    IF v_ay IS NULL THEN v_skip := v_skip + 1; CONTINUE; END IF;

    v_bed := NULL; v_room := NULL; v_block := NULL;
    SELECT b.id, sr.room_id, sr.block_id INTO v_bed, v_room, v_block
    FROM _aa_sig_rooms sr
    JOIN hostel_beds b ON b.room_id = sr.room_id AND b.status = 'available'
    WHERE sr.inst           IS NOT DISTINCT FROM cand.inst
      AND sr.degree_id      IS NOT DISTINCT FROM cand.degree_id
      AND sr.department_id  IS NOT DISTINCT FROM cand.department_id
      AND sr.program_id     IS NOT DISTINCT FROM cand.program_id
      AND sr.sem_id         IS NOT DISTINCT FROM cand.sem_id
      AND sr.category_id = ANY(cand.room_cats)
      AND (sr.cat_type IS NULL
           OR (sr.cat_type='boys'  AND cand.gender IN ('male','m'))
           OR (sr.cat_type='girls' AND cand.gender IN ('female','f')))
      AND NOT EXISTS (SELECT 1 FROM hostel_allocations a WHERE a.bed_id=b.id AND a.status IN ('active','pending_approval'))
    ORDER BY array_position(cand.room_cats, sr.category_id), sr.block_name, sr.floor, sr.room_number, b.bed_number
    LIMIT 1;

    IF v_bed IS NULL THEN v_skip := v_skip + 1; CONTINUE; END IF;

    INSERT INTO hostel_allocations (
      institution_id, learner_id, block_id, room_id, bed_id, academic_year_id, semester_id,
      allocation_type, allocation_date, status,
      emergency_contact_name, emergency_contact_phone, emergency_contact_relation,
      tier_id, batch_id, allocated_by, warden_id
    ) VALUES (
      cand.inst, cand.profile_id, v_block, v_room, v_bed, v_ay, cand.sem_id,
      'fresh', CURRENT_DATE, 'pending_approval', '', '', '',
      v_tier, v_batch, v_actor,
      (SELECT user_id FROM user_block_access WHERE block_id=v_block AND revoked_at IS NULL LIMIT 1)
    );

    v_mess := CASE WHEN cand.mess_cats IS NOT NULL THEN cand.mess_cats[1] ELSE NULL END;
    UPDATE learners_profiles
      SET hostel_category_id = (SELECT category_id FROM hostel_rooms WHERE id = v_room),
          mess_category_id   = COALESCE(v_mess, mess_category_id),
          updated_at = now()
      WHERE id = cand.lp_id;

    v_alloc := v_alloc + 1;
  END LOOP;

  UPDATE hostel_allocation_batches
    SET allocated_count = v_alloc, skipped_count = v_skip,
        notes = format('%s allocated across all %s blocks (%s physical mode; rules-driven category + mess; block and room decided by the physical-room rules). %s skipped (no free bed they can occupy / reserved rooms hold no space for them / gender / no academic year). Strict: learners with no rule-resolved room category are excluded. Cohort: lifecycle_status = active only.',
                       v_alloc, p_hostel_type,
                       CASE WHEN p_strict THEN 'STRICT — only cohorts matching a physical rule' ELSE 'open — rule-free rooms shared' END,
                       v_skip)
    WHERE id = v_batch;

  RETURN v_batch;
END $function$;

REVOKE EXECUTE ON FUNCTION public.fn_auto_allocate_classic(text, uuid, boolean, uuid, uuid, uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_auto_allocate_classic(text, uuid, boolean, uuid, uuid, uuid) TO authenticated, service_role;


-- =====================================================================
-- hr_shift_timings — resolver, coverage and atomic week-save RPCs
-- Added 2026-08-06. Source of truth:
--   supabase/migrations/20260806090000_create_hr_shift_timings.sql
--   supabase/migrations/20260806090100_hr_shift_timings_functions.sql
--   supabase/migrations/20260806090400_hr_shift_timings_save_week.sql
-- Plan: docs/superpowers/plans/2026-08-06-hr-shift-timings.md
--
-- Replaced the legacy hr_shift_templates / hr_shift_assignments /
-- hr_shift_swap_requests module, dropped 2026-08-06 (all three were empty).
-- Those tables were never mirrored into supabase/setup, so there is nothing
-- to remove here.
-- =====================================================================

CREATE OR REPLACE FUNCTION public.fn_resolve_shift_timing(p_staff_id uuid, p_date date)
 RETURNS TABLE(timing_id uuid, institution_id uuid, staff_scope text, employment_category_id uuid, applicable_gender text, day_of_week smallint, is_working_day boolean, first_half_start time without time zone, first_half_end time without time zone, second_half_start time without time zone, second_half_end time without time zone, grace_minutes integer, grace_deadline time without time zone, matched_by text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_institution_id uuid;
  v_category_id    uuid;
  v_is_teaching    boolean;
  v_gender         text;
  v_pattern_id     uuid;
  v_dow            smallint;
  v_second_sat     boolean;
BEGIN
  IF NOT (
       public.is_super_admin()
    OR public.is_admin()
    OR EXISTS (SELECT 1 FROM public.staff s
                WHERE s.id = p_staff_id AND s.profile_id = auth.uid())
    OR (public.user_has_permission('hr.shift_timings.view')
        AND EXISTS (SELECT 1 FROM public.staff s
                     WHERE s.id = p_staff_id
                       AND public.role_has_institution_access(s.institution_id)))
  ) THEN
    RAISE EXCEPTION 'Not authorized to resolve shift timing for this staff member'
      USING ERRCODE = '42501';
  END IF;

  SELECT s.institution_id, s.category_id, ec.is_teaching, s.gender
    INTO v_institution_id, v_category_id, v_is_teaching, v_gender
  FROM public.staff s
  JOIN public.employment_categories ec ON ec.id = s.category_id
  WHERE s.id = p_staff_id;

  IF v_institution_id IS NULL THEN RETURN; END IF;

  v_pattern_id := public.fn_staff_work_pattern_id(p_staff_id, p_date);
  v_dow        := EXTRACT(ISODOW FROM p_date)::smallint;
  v_second_sat := (v_dow = 6 AND EXTRACT(DAY FROM p_date) BETWEEN 8 AND 14);

  RETURN QUERY
  SELECT
    t.id,
    t.institution_id,
    t.staff_scope,
    t.employment_category_id,
    t.applicable_gender,
    t.day_of_week,
    CASE WHEN (v_second_sat AND t.second_saturday_holiday) THEN false ELSE t.is_working_day END,
    CASE WHEN (v_second_sat AND t.second_saturday_holiday) THEN NULL ELSE t.first_half_start  END,
    CASE WHEN (v_second_sat AND t.second_saturday_holiday) THEN NULL ELSE t.first_half_end    END,
    CASE WHEN (v_second_sat AND t.second_saturday_holiday) THEN NULL ELSE t.second_half_start END,
    CASE WHEN (v_second_sat AND t.second_saturday_holiday) THEN NULL ELSE t.second_half_end   END,
    t.grace_minutes,
    -- The FIRST SESSION of the day: the morning when there is one, the lone
    -- afternoon on a second-half-only day. Grace applies to whichever it is.
    CASE WHEN (v_second_sat AND t.second_saturday_holiday) OR NOT t.is_working_day THEN NULL
         ELSE (COALESCE(t.first_half_start, t.second_half_start)
               + make_interval(mins => t.grace_minutes))::time END,
    CASE WHEN (v_second_sat AND t.second_saturday_holiday) THEN 'second_saturday_holiday'
         ELSE t.staff_scope END
  FROM public.fn_shift_timing_pick(
         v_institution_id, v_category_id, v_is_teaching, v_gender, v_dow, p_date, v_pattern_id) t;
END;
$function$;

COMMENT ON FUNCTION public.fn_resolve_shift_timing(uuid, date) IS
  'Resolve the applicable hr_shift_timings row for a staff member on a date. Most-specific-wins (category > teaching/non_teaching), effective-dated, and folds in the second-Saturday rule. Self-authorizing.';

REVOKE ALL ON FUNCTION public.fn_resolve_shift_timing(uuid, date) FROM anon;
GRANT EXECUTE ON FUNCTION public.fn_resolve_shift_timing(uuid, date) TO authenticated;

-- ---------------------------------------------------------------------
-- fn_shift_timing_coverage(institution, date)
-- One row per employment category actually present in that institution,
-- with the timing it resolves to. A NULL resolved_timing_id means those
-- staff have NO timing on that date.
--
-- Exists because the data is legitimately uneven — Main Office is 114/114
-- non-teaching, both schools are 100% teaching — so the UI must be able to
-- tell "correctly empty" from "misconfigured".
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_shift_timing_coverage(p_institution_id uuid, p_date date)
 RETURNS TABLE(employment_category_id uuid, category_name text, is_teaching boolean, staff_gender text, staff_count bigint, resolved_timing_id uuid, resolved_via text, resolved_gender text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_dow smallint;
BEGIN
  IF NOT (
       public.is_super_admin()
    OR public.is_admin()
    OR ((public.user_has_permission('hr.shift_timings.view')
         OR public.user_has_permission('hr.shift_timings.manage'))
        AND public.role_has_institution_access(p_institution_id))
  ) THEN
    RAISE EXCEPTION 'Not authorized to view shift timing coverage for this institution'
      USING ERRCODE = '42501';
  END IF;

  v_dow := EXTRACT(ISODOW FROM p_date)::smallint;

  RETURN QUERY
  WITH cats AS (
    SELECT ec.id AS cat_id,
           ec.category_name AS cat_name,
           ec.is_teaching AS cat_is_teaching,
           s.gender AS cat_gender,
           count(s.id) AS cat_staff_count
    FROM public.staff s
    JOIN public.employment_categories ec ON ec.id = s.category_id
    WHERE s.institution_id = p_institution_id
      AND public.fn_staff_work_pattern_id(s.id, p_date) IS NULL
    GROUP BY ec.id, ec.category_name, ec.is_teaching, s.gender
  )
  SELECT c.cat_id, c.cat_name, c.cat_is_teaching, c.cat_gender, c.cat_staff_count,
         t.id, t.staff_scope, t.applicable_gender
  FROM cats c
  LEFT JOIN LATERAL public.fn_shift_timing_pick(
    p_institution_id, c.cat_id, c.cat_is_teaching, c.cat_gender, v_dow, p_date) t ON true
  ORDER BY c.cat_staff_count DESC, c.cat_name, c.cat_gender;
END;
$function$;

COMMENT ON FUNCTION public.fn_shift_timing_coverage(uuid, date) IS
  'Per-employment-category shift timing coverage for an institution on a date. NULL resolved_timing_id = staff with no timing. Self-authorizing.';

REVOKE ALL ON FUNCTION public.fn_shift_timing_coverage(uuid, date) FROM anon;
GRANT EXECUTE ON FUNCTION public.fn_shift_timing_coverage(uuid, date) TO authenticated;

DROP FUNCTION IF EXISTS public.fn_save_shift_timing_week(uuid, text, uuid, date, jsonb, text);

CREATE FUNCTION public.fn_save_shift_timing_week(
  p_institution_id         uuid,
  p_staff_scope            text,
  p_employment_category_id uuid,
  p_effective_from         date,
  p_days                   jsonb,
  p_applicable_gender      text DEFAULT 'all',
  p_work_pattern_id        uuid DEFAULT NULL
)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_day      record;
  v_current  public.hr_shift_timings%ROWTYPE;
  v_written  integer := 0;
  v_actor    uuid := auth.uid();
  v_pattern_inst uuid;
BEGIN
  IF NOT (
       public.is_super_admin()
    OR public.is_admin()
    OR (public.user_has_permission('hr.shift_timings.manage')
        AND public.role_has_institution_access(p_institution_id))
  ) THEN
    RAISE EXCEPTION 'Not authorized to configure shift timings for this institution'
      USING ERRCODE = '42501';
  END IF;

  IF p_staff_scope NOT IN ('teaching','non_teaching','category','work_pattern') THEN
    RAISE EXCEPTION 'Invalid staff_scope: %', p_staff_scope USING ERRCODE = '22023';
  END IF;

  IF p_applicable_gender NOT IN ('all','male','female','bigender') THEN
    RAISE EXCEPTION 'Invalid applicable_gender: %', p_applicable_gender USING ERRCODE = '22023';
  END IF;

  IF (p_staff_scope = 'category') <> (p_employment_category_id IS NOT NULL) THEN
    RAISE EXCEPTION 'staff_scope=category requires an employment_category_id, and vice versa'
      USING ERRCODE = '22023';
  END IF;

  IF (p_staff_scope = 'work_pattern') <> (p_work_pattern_id IS NOT NULL) THEN
    RAISE EXCEPTION 'staff_scope=work_pattern requires a work_pattern_id, and vice versa'
      USING ERRCODE = '22023';
  END IF;

  IF p_staff_scope = 'work_pattern' THEN
    IF p_applicable_gender <> 'all' THEN
      RAISE EXCEPTION 'A work pattern''s week applies to everyone on it; applicable_gender must be ''all'''
        USING ERRCODE = '22023';
    END IF;
    SELECT institution_id INTO v_pattern_inst FROM public.hr_work_patterns WHERE id = p_work_pattern_id;
    IF v_pattern_inst IS NULL THEN
      RAISE EXCEPTION 'Work pattern % not found', p_work_pattern_id USING ERRCODE = 'P0002';
    END IF;
    IF v_pattern_inst <> p_institution_id THEN
      RAISE EXCEPTION 'Work pattern belongs to a different institution' USING ERRCODE = '22023';
    END IF;
  END IF;

  FOR v_day IN
    SELECT *
    FROM jsonb_to_recordset(p_days) AS d(
      day_of_week smallint,
      is_working_day boolean,
      first_half_start time,
      first_half_end time,
      second_half_start time,
      second_half_end time,
      grace_minutes integer,
      second_saturday_holiday boolean
    )
  LOOP
    SELECT * INTO v_current
    FROM public.hr_shift_timings t
    WHERE t.institution_id = p_institution_id
      AND t.staff_scope    = p_staff_scope
      AND t.applicable_gender = p_applicable_gender
      AND t.day_of_week    = v_day.day_of_week
      AND t.employment_category_id IS NOT DISTINCT FROM p_employment_category_id
      AND t.work_pattern_id        IS NOT DISTINCT FROM p_work_pattern_id
      AND t.effective_until IS NULL
      AND t.is_active;

    IF NOT FOUND THEN
      INSERT INTO public.hr_shift_timings (
        institution_id, staff_scope, employment_category_id, work_pattern_id, applicable_gender, day_of_week,
        is_working_day, first_half_start, first_half_end,
        second_half_start, second_half_end,
        grace_minutes, second_saturday_holiday, effective_from,
        created_by, updated_by
      ) VALUES (
        p_institution_id, p_staff_scope, p_employment_category_id, p_work_pattern_id, p_applicable_gender, v_day.day_of_week,
        v_day.is_working_day, v_day.first_half_start, v_day.first_half_end,
        v_day.second_half_start, v_day.second_half_end,
        COALESCE(v_day.grace_minutes, 0), COALESCE(v_day.second_saturday_holiday, false),
        p_effective_from, v_actor, v_actor
      );

    ELSIF p_effective_from <= v_current.effective_from THEN
      UPDATE public.hr_shift_timings h
         SET is_active  = false,
             updated_by = v_actor
       WHERE h.institution_id = p_institution_id
         AND h.staff_scope    = p_staff_scope
         AND h.applicable_gender = p_applicable_gender
         AND h.day_of_week    = v_day.day_of_week
         AND h.employment_category_id IS NOT DISTINCT FROM p_employment_category_id
         AND h.work_pattern_id        IS NOT DISTINCT FROM p_work_pattern_id
         AND h.id <> v_current.id
         AND h.is_active
         AND h.effective_from >= p_effective_from;

      UPDATE public.hr_shift_timings h
         SET effective_until = p_effective_from,
             updated_by      = v_actor
       WHERE h.institution_id = p_institution_id
         AND h.staff_scope    = p_staff_scope
         AND h.applicable_gender = p_applicable_gender
         AND h.day_of_week    = v_day.day_of_week
         AND h.employment_category_id IS NOT DISTINCT FROM p_employment_category_id
         AND h.work_pattern_id        IS NOT DISTINCT FROM p_work_pattern_id
         AND h.id <> v_current.id
         AND h.is_active
         AND h.effective_from < p_effective_from
         AND (h.effective_until IS NULL OR h.effective_until > p_effective_from);

      UPDATE public.hr_shift_timings
         SET is_working_day          = v_day.is_working_day,
             first_half_start        = v_day.first_half_start,
             first_half_end          = v_day.first_half_end,
             second_half_start       = v_day.second_half_start,
             second_half_end         = v_day.second_half_end,
             grace_minutes           = COALESCE(v_day.grace_minutes, 0),
             second_saturday_holiday = COALESCE(v_day.second_saturday_holiday, false),
             effective_from          = p_effective_from,
             updated_by              = v_actor
       WHERE id = v_current.id;

    ELSE
      UPDATE public.hr_shift_timings
         SET effective_until = p_effective_from,
             updated_by      = v_actor
       WHERE id = v_current.id;

      INSERT INTO public.hr_shift_timings (
        institution_id, staff_scope, employment_category_id, work_pattern_id, applicable_gender, day_of_week,
        is_working_day, first_half_start, first_half_end,
        second_half_start, second_half_end,
        grace_minutes, second_saturday_holiday, effective_from,
        created_by, updated_by
      ) VALUES (
        p_institution_id, p_staff_scope, p_employment_category_id, p_work_pattern_id, p_applicable_gender, v_day.day_of_week,
        v_day.is_working_day, v_day.first_half_start, v_day.first_half_end,
        v_day.second_half_start, v_day.second_half_end,
        COALESCE(v_day.grace_minutes, 0), COALESCE(v_day.second_saturday_holiday, false),
        p_effective_from, v_actor, v_actor
      );
    END IF;

    v_written := v_written + 1;
  END LOOP;

  RETURN v_written;
END;
$function$;

COMMENT ON FUNCTION public.fn_save_shift_timing_week(uuid, text, uuid, date, jsonb, text, uuid) IS
  'Save one scope''s week (teaching / non_teaching / category / work_pattern × gender) effective from a date. A pattern week is always gender ''all''. Closes the previous rows at that date, or rewrites them when backdating.';

REVOKE ALL ON FUNCTION public.fn_save_shift_timing_week(uuid, text, uuid, date, jsonb, text, uuid) FROM anon;
GRANT EXECUTE ON FUNCTION public.fn_save_shift_timing_week(uuid, text, uuid, date, jsonb, text, uuid) TO authenticated;

-- ============================================================================
-- Updated: 2026-08-15 (migration 20260815020000_reservation_is_move_in.sql)
-- Director rule 2026-08-07: a reservation IS the move-in. fn_cl_expire_upgrade_holds
-- now CONFIRMS lapsed payment-window holds (bed kept, bill kept as fee dues,
-- category kept) instead of expiring/releasing/cancelling; fn_cl_process_upgrade_holds
-- gains an idempotency guard against the cron having confirmed the move first.
-- These supersede the copies of both functions earlier in this file.
-- ============================================================================
-- ============ 1. Expiry cron: lapsed payment window ⇒ CONFIRM the move ======
-- (live body 2026-08-07 was the expire/release/cancel/revert CTE; replaced)

CREATE OR REPLACE FUNCTION public.fn_cl_expire_upgrade_holds()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row RECORD; v_lp uuid; v_alloc uuid; v_count int := 0;
BEGIN
  -- Director's rule (2026-08-07): a reservation IS the move-in. When the
  -- payment window (hold_expires_at) lapses the move is CONFIRMED, never
  -- undone: the held bed is not released, the upgrade bill is not cancelled,
  -- the category is not reverted. The unpaid bill simply remains part of the
  -- learner's fee dues. Nobody is moved out for non-payment.
  FOR v_row IN
    SELECT w.id, w.learner_id, w.target_hostel_category_id,
           w.held_room_id, w.held_bed_id
    FROM hostel_waitlist w
    WHERE w.entry_kind='upgrade' AND w.status='waiting'
      AND w.hold_expires_at IS NOT NULL AND w.hold_expires_at < now()
    ORDER BY w.created_at
  LOOP
    BEGIN
      SELECT lp.id INTO v_lp
        FROM profiles p JOIN learners_profiles lp ON lp.id = p.learner_id
       WHERE p.id = v_row.learner_id;
      IF v_lp IS NULL THEN
        RAISE WARNING 'fn_cl_expire_upgrade_holds: no learners_profile for % (waitlist %)',
          v_row.learner_id, v_row.id;
        CONTINUE;
      END IF;

      IF v_row.held_bed_id IS NOT NULL THEN
        -- Room hold (pre-change transition rows): complete the move onto the
        -- held bed. _cl_execute_room_upgrade vacates the old allocation with
        -- check_out_date stamped in the same statement (the partial-index
        -- contract of hostel_allocations_room_bed_active_uidx, PR #2890),
        -- links the existing upgrade bill instead of re-billing, and marks
        -- this waitlist row 'allocated'.
        SELECT a.id INTO v_alloc FROM hostel_allocations a
         WHERE a.learner_id = v_row.learner_id AND a.status = 'active'
           AND a.room_id = v_row.held_room_id AND a.bed_id = v_row.held_bed_id
         LIMIT 1;
        IF v_alloc IS NOT NULL THEN
          -- Already living on the held bed — just stamp the confirmation.
          UPDATE hostel_waitlist
             SET status='allocated', allocated_allocation_id=v_alloc,
                 held_room_id=NULL, held_bed_id=NULL, hold_expires_at=NULL, updated_at=now()
           WHERE id = v_row.id;
        ELSIF EXISTS (SELECT 1 FROM hostel_allocations
                       WHERE learner_id = v_row.learner_id AND status = 'active') THEN
          PERFORM public._cl_execute_room_upgrade(v_row.learner_id, v_lp,
            v_row.target_hostel_category_id, v_row.held_room_id, v_row.held_bed_id, true);
        ELSE
          PERFORM public._cl_execute_first_booking(v_row.learner_id, v_lp,
            v_row.target_hostel_category_id, v_row.held_room_id, v_row.held_bed_id, true);
        END IF;
      ELSE
        -- Category-only hold: the optimistic flip at reserve time IS the
        -- move-in. Make it permanent — the same statements the paid-confirm
        -- branch of fn_cl_process_upgrade_holds runs. The bill stays as dues.
        UPDATE learners_profiles
           SET hostel_category_id = v_row.target_hostel_category_id,
               pending_hostel_category_id = NULL, updated_at=now()
         WHERE id = v_lp;
        UPDATE hostel_waitlist SET status='allocated', updated_at=now() WHERE id = v_row.id;
      END IF;

      v_count := v_count + 1;
    EXCEPTION WHEN OTHERS THEN
      -- e.g. a transition row whose held bed was given away before this rule
      -- shipped ("Held bed is no longer reserved"): the row stays 'waiting',
      -- a warning surfaces, the next run retries. fn_cl_admin_cancel_upgrade
      -- remains the manual resolution tool for those.
      RAISE WARNING 'fn_cl_expire_upgrade_holds: % (waitlist %)', SQLERRM, v_row.id;
    END;
  END LOOP;

  RETURN v_count;
END $function$;

-- Service-role only (hourly cron); same ACL the live function carries.
REVOKE EXECUTE ON FUNCTION public.fn_cl_expire_upgrade_holds() FROM anon, authenticated, PUBLIC;

-- ============ 2. Payment-confirm path: idempotent against the cron ==========
-- (live body 2026-08-07 reproduced VERBATIM; the ONLY change is the guard at
-- the top of the held-bed loop plus its v_existing_alloc declaration)

CREATE OR REPLACE FUNCTION public.fn_cl_process_upgrade_holds(p_student_lp uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
-- Events Hub — delete gate (2026-08-06)
-- See supabase/migrations/20260806_events_delete_permission_gate.sql
-- ============================================================================

-- What deleting an event would cascade away. SECURITY DEFINER because both
-- child tables are RLS-gated: a caller who cannot see the registrations would
-- otherwise count 0 and be told the delete is safe — a false negative on the
-- one check that exists to prevent data loss. Self-authorizes for the same
-- reason: callable by `authenticated` is not the same as authorized.
CREATE OR REPLACE FUNCTION public.fn_event_delete_blockers(p_event_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $fn$
DECLARE
  v_institution_id uuid;
  v_found          boolean;
  v_registrations  integer;
  v_payments       integer;
  v_induction      integer;
BEGIN
  SELECT e.institution_id, true
    INTO v_institution_id, v_found
    FROM public.events e
   WHERE e.id = p_event_id;

  IF NOT COALESCE(v_found, false) THEN
    RAISE EXCEPTION 'Event % not found', p_event_id USING ERRCODE = 'P0002';
  END IF;

  IF NOT (
    public.user_has_permission('events.delete')
    AND public.role_has_institution_access(v_institution_id)
  ) THEN
    RAISE EXCEPTION 'Not authorized to delete this event' USING ERRCODE = '42501';
  END IF;

  SELECT count(*) INTO v_registrations
    FROM public.events_registrations r WHERE r.event_id = p_event_id;

  SELECT count(*) INTO v_payments
    FROM public.event_payment_transactions t WHERE t.event_id = p_event_id;

  -- Induction learners (migration 20260818090000). An induction never writes
  -- events_registrations - freshers arrive through fn_induction_auto_enroll -
  -- so without this arm every induction reported 'safe to delete' while holding
  -- hundreds of learners across 13 cascading induction_* tables.
  SELECT count(*) INTO v_induction
    FROM public.induction_enrollment ie WHERE ie.event_id = p_event_id;

  RETURN jsonb_build_object(
    'registrations',      v_registrations,
    'payments',           v_payments,
    'induction_learners', v_induction,
    'blocked',            (v_registrations > 0 OR v_payments > 0 OR v_induction > 0)
  );
END;
$fn$;

COMMENT ON FUNCTION public.fn_event_delete_blockers(uuid) IS
  'Events Hub delete pre-check. Returns {registrations, payments, induction_learners, blocked} past RLS; self-authorizes on events.delete + institution access.';

REVOKE ALL ON FUNCTION public.fn_event_delete_blockers(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fn_event_delete_blockers(uuid) FROM anon;
GRANT EXECUTE ON FUNCTION public.fn_event_delete_blockers(uuid) TO authenticated;

-- Trigger body for trg_events_block_delete_with_dependents (see 04_triggers.sql).
-- SECURITY DEFINER for the same reason as above: an RLS-filtered count here
-- would return 0 for the very callers this exists to stop, and the guard would
-- pass while destroying rows it could not see.
CREATE OR REPLACE FUNCTION public.fn_events_block_delete_with_dependents()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $fn$
DECLARE
  v_registrations integer;
  v_payments      integer;
  v_induction     integer;
BEGIN
  SELECT count(*) INTO v_registrations
    FROM public.events_registrations r WHERE r.event_id = OLD.id;

  SELECT count(*) INTO v_payments
    FROM public.event_payment_transactions t WHERE t.event_id = OLD.id;

  SELECT count(*) INTO v_induction
    FROM public.induction_enrollment ie WHERE ie.event_id = OLD.id;

  IF v_registrations > 0 OR v_payments > 0 THEN
    RAISE EXCEPTION
      'Cannot delete event "%": % registration(s) and % payment transaction(s) would be permanently destroyed by ON DELETE CASCADE. Remove or refund them first, or move the event to Draft to take it out of circulation.',
      OLD.name, v_registrations, v_payments
      USING ERRCODE = 'P0001';
  END IF;

  -- Separate arm, separate message (migration 20260818090000): an induction has
  -- 0 registrations and 0 payments by construction, so folding it into the
  -- clause above would refuse the delete while naming two counts that are zero.
  IF v_induction > 0 THEN
    RAISE EXCEPTION
      'Cannot delete induction "%": % enrolled learner(s) - along with their batches, attendance, feedback and completion records - would be permanently destroyed by ON DELETE CASCADE. Remove the enrolment first, or move the induction to Draft to take it out of circulation.',
      OLD.name, v_induction
      USING ERRCODE = 'P0001';
  END IF;

  RETURN OLD;
END;
$fn$;

COMMENT ON FUNCTION public.fn_events_block_delete_with_dependents() IS
  'Refuses DELETE on an event holding registrations, payment transactions, or enrolled induction learners - those cascade away irreversibly. Enforced here so PostgREST cannot bypass it.';

-- No EXECUTE grants: a trigger function must not be reachable at /rest/v1/rpc/.
-- Postgres checks EXECUTE at CREATE TRIGGER time, not at fire time, so this does
-- not disarm the guard.
REVOKE ALL ON FUNCTION public.fn_events_block_delete_with_dependents() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fn_events_block_delete_with_dependents() FROM anon;
REVOKE ALL ON FUNCTION public.fn_events_block_delete_with_dependents() FROM authenticated;


-- ============================================================================
-- Campus Living: upgrade-fee DISCOUNTS (migration 20260807120000)
-- Supersedes the earlier definitions above. Every upgrade read site now bills
-- and displays hostel_category_upgrade_fees.net_amount (payable after discount)
-- instead of .amount (gross), and the option loaders additionally return
-- upgrade_fee_original + upgrade_discount so the UI can strike through the gross.
-- ============================================================================
-- 2) Billing helper — record gross in total, net in final ---------------------
-- p_upgrade_amount stays the NET payable (all four callers already treat it as
-- "what the learner owes", and update_bill_balance_on_amount_change derives
-- balance + status from final_amount alone). p_gross_amount is additive: when
-- given, total_amount carries the pre-discount figure so the bill itself
-- evidences the concession.
--
-- DROP first, not CREATE OR REPLACE: adding a defaulted parameter to an existing
-- function creates a second OVERLOAD rather than replacing it, and the 5-arg
-- calls would then be ambiguous.
DROP FUNCTION IF EXISTS public._cl_apply_upgrade_fee_bill(uuid, uuid, text, numeric, text);

CREATE OR REPLACE FUNCTION public._cl_apply_upgrade_fee_bill(
  p_learner_lp uuid, p_hostel_year_id uuid, p_kind text,
  p_upgrade_amount numeric, p_description text,
  p_gross_amount numeric DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
DECLARE
  v_inst uuid; v_ay uuid; v_bcat uuid; v_bill_id uuid; v_gross numeric;
  v_existing RECORD; v_paid numeric; v_new_final numeric; v_new_balance numeric; v_new_status text;
BEGIN
  IF p_upgrade_amount IS NULL OR p_upgrade_amount <= 0 THEN
    RETURN jsonb_build_object('action','none','new_amount',COALESCE(p_upgrade_amount,0),
                              'billed',0,'bill_id',NULL,'old_bill_id',NULL);
  END IF;
  -- Gross can never sit BELOW the payable, or total_amount < final_amount.
  v_gross := GREATEST(COALESCE(p_gross_amount, p_upgrade_amount), p_upgrade_amount);

  SELECT institution_id, academic_year_id INTO v_inst, v_ay FROM learners_profiles WHERE id = p_learner_lp;
  v_ay := COALESCE(v_ay, (SELECT id FROM academic_years WHERE institution_id = v_inst AND is_active ORDER BY start_date DESC LIMIT 1));
  v_bcat := public._cl_ensure_upgrade_billing_category(p_kind);

  SELECT id, final_amount, balance_amount, total_amount, bill_description
    INTO v_existing
    FROM billing_student_bills
   WHERE student_id = p_learner_lp AND hostel_year_id = p_hostel_year_id AND item_category_id = v_bcat
     AND fee_source = 'hostel_category' AND status NOT IN ('cancelled','superseded')
   ORDER BY created_at DESC LIMIT 1;

  IF v_existing.id IS NOT NULL THEN
    v_paid := COALESCE(v_existing.final_amount,0) - COALESCE(v_existing.balance_amount,0);
    v_new_final := COALESCE(v_existing.final_amount,0) + p_upgrade_amount;
    v_new_balance := v_new_final - v_paid;
    v_new_status := CASE WHEN v_paid <= 0 THEN 'unpaid'
                         WHEN v_paid >= v_new_final THEN 'paid'
                         ELSE 'partially_paid' END;
    UPDATE billing_student_bills
       SET final_amount = v_new_final,
           -- total accumulates the GROSS so the discount stays visible on the bill
           total_amount = COALESCE(total_amount,0) + v_gross,
           unit_amount = v_new_final, quantity = 1,
           balance_amount = v_new_balance, status = v_new_status,
           bill_description = left(
             CASE WHEN COALESCE(v_existing.bill_description,'') = '' THEN p_description
                  ELSE v_existing.bill_description || ' + ' || p_description END, 500),
           updated_at = now()
     WHERE id = v_existing.id;
    RETURN jsonb_build_object('action','accumulated','new_amount',v_new_final,
                              'billed',p_upgrade_amount,'gross',v_gross,
                              'discount',v_gross - p_upgrade_amount,
                              'bill_id',v_existing.id,'old_bill_id',v_existing.id);
  END IF;

  INSERT INTO billing_student_bills (
    student_id, institution_id, academic_year_id, item_category_id, hostel_year_id, fee_source,
    bill_description, due_date, quantity, unit_amount, total_amount, final_amount, balance_amount, status
  ) VALUES (
    p_learner_lp, v_inst, v_ay, v_bcat, p_hostel_year_id, 'hostel_category',
    p_description, now() + interval '30 day', 1, p_upgrade_amount, v_gross,
    p_upgrade_amount, p_upgrade_amount, 'unpaid'
  ) RETURNING id INTO v_bill_id;
  RETURN jsonb_build_object('action','created','new_amount',p_upgrade_amount,
                            'billed',p_upgrade_amount,'gross',v_gross,
                            'discount',v_gross - p_upgrade_amount,
                            'bill_id',v_bill_id,'old_bill_id',NULL);
END $function$;

-- DROP discards grants (EXECUTE reverts to PUBLIC) — restore the original ACL.
REVOKE EXECUTE ON FUNCTION public._cl_apply_upgrade_fee_bill(uuid,uuid,text,numeric,text,numeric) FROM PUBLIC, anon;
GRANT  EXECUTE ON FUNCTION public._cl_apply_upgrade_fee_bill(uuid,uuid,text,numeric,text,numeric) TO authenticated, service_role;

-- 3) Resident option loaders — bill net, expose gross + discount for the UI ----
DROP FUNCTION IF EXISTS public.fn_my_upgrade_room_categories();
CREATE OR REPLACE FUNCTION public.fn_my_upgrade_room_categories()
RETURNS TABLE(category_id uuid, name text, type text, allocation_mode text,
              current_year_fee numeric, upgrade_fee numeric, available_beds integer,
              threshold_pct numeric, paid_pct numeric, meets_threshold boolean,
              hold_days integer, upgrade_fee_original numeric, upgrade_discount numeric)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_lp uuid := get_my_learner_id();
  v_year uuid; v_cur_cat uuid; v_cur_fee numeric := 0; v_gender text; v_paid_pct numeric;
BEGIN
  IF v_lp IS NULL OR NOT user_is_hosteler() THEN RETURN; END IF;
  SELECT id INTO v_year FROM hostel_years WHERE is_current LIMIT 1;
  IF v_year IS NULL THEN RETURN; END IF;
  SELECT hostel_category_id INTO v_cur_cat FROM learners_profiles WHERE id = v_lp;
  SELECT lower(trim(COALESCE(pr.gender, lp.gender))) INTO v_gender
    FROM profiles pr LEFT JOIN learners_profiles lp ON lp.id = pr.learner_id
   WHERE pr.id = auth.uid();
  SELECT COALESCE(amount,0) INTO v_cur_fee FROM hostel_fees
    WHERE hostel_category_id = v_cur_cat AND hostel_year_id = v_year AND mess_category_id IS NULL AND is_active LIMIT 1;
  SELECT pp.paid_pct INTO v_paid_pct FROM fn_learner_academic_payment_progress(v_lp) pp;

  RETURN QUERY
  SELECT c.id, c.name, c.type, c.allocation_mode, hf.amount,
         COALESCE(
           (SELECT uf.net_amount FROM hostel_category_upgrade_fees uf
            WHERE uf.hostel_year_id = v_year AND uf.is_active
              AND uf.from_hostel_category_id = v_cur_cat AND uf.to_hostel_category_id = c.id LIMIT 1),
           hf.amount - v_cur_fee
         ) AS upgrade_fee,
         (SELECT count(*)::int FROM fn_my_room_options(c.id)),
         c.upgrade_threshold_pct,
         v_paid_pct,
         (c.upgrade_threshold_pct IS NULL
          OR (v_paid_pct IS NOT NULL AND v_paid_pct >= c.upgrade_threshold_pct)),
         c.upgrade_hold_days,
         COALESCE(
           (SELECT uf.amount FROM hostel_category_upgrade_fees uf
            WHERE uf.hostel_year_id = v_year AND uf.is_active
              AND uf.from_hostel_category_id = v_cur_cat AND uf.to_hostel_category_id = c.id LIMIT 1),
           hf.amount - v_cur_fee
         ) AS upgrade_fee_original,
         COALESCE(
           (SELECT uf.amount - uf.net_amount FROM hostel_category_upgrade_fees uf
            WHERE uf.hostel_year_id = v_year AND uf.is_active
              AND uf.from_hostel_category_id = v_cur_cat AND uf.to_hostel_category_id = c.id LIMIT 1),
           0
         ) AS upgrade_discount
  FROM hostel_categories c
  JOIN hostel_fees hf
    ON hf.hostel_category_id = c.id AND hf.hostel_year_id = v_year AND hf.mess_category_id IS NULL AND hf.is_active
  WHERE c.is_active
    AND ((v_gender IN ('male','m')   AND c.type='boys')
         OR (v_gender IN ('female','f') AND c.type='girls'))
    AND c.id <> COALESCE(v_cur_cat, '00000000-0000-0000-0000-000000000000'::uuid)
    AND hf.amount > v_cur_fee
    AND (NOT c.requires_explicit_upgrade
         OR EXISTS (SELECT 1 FROM hostel_category_upgrade_fees uf2
                    WHERE uf2.hostel_year_id = v_year AND uf2.is_active
                      AND uf2.from_hostel_category_id = v_cur_cat
                      AND uf2.to_hostel_category_id = c.id))
  ORDER BY hf.amount;
END $function$;

REVOKE EXECUTE ON FUNCTION public.fn_my_upgrade_room_categories() FROM PUBLIC, anon;
GRANT  EXECUTE ON FUNCTION public.fn_my_upgrade_room_categories() TO authenticated, service_role;

DROP FUNCTION IF EXISTS public.fn_my_upgrade_mess_categories();
CREATE OR REPLACE FUNCTION public.fn_my_upgrade_mess_categories()
RETURNS TABLE(mess_category_id uuid, name text, current_year_fee numeric, upgrade_fee numeric,
              upgrade_fee_original numeric, upgrade_discount numeric)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_lp uuid := get_my_learner_id();
  v_year uuid; v_cur_mess uuid; v_cur_fee numeric := 0; v_gender text;
BEGIN
  IF v_lp IS NULL OR NOT user_is_hosteler() THEN RETURN; END IF;
  SELECT id INTO v_year FROM hostel_years WHERE is_current LIMIT 1;
  IF v_year IS NULL THEN RETURN; END IF;
  SELECT lp.mess_category_id INTO v_cur_mess FROM learners_profiles lp WHERE lp.id = v_lp;
  SELECT lower(trim(COALESCE(pr.gender, lp.gender))) INTO v_gender
    FROM profiles pr LEFT JOIN learners_profiles lp ON lp.id = pr.learner_id
   WHERE pr.id = auth.uid();
  SELECT COALESCE(hf.amount,0) INTO v_cur_fee FROM hostel_fees hf
    WHERE hf.mess_category_id = v_cur_mess AND hf.hostel_year_id = v_year AND hf.is_active LIMIT 1;

  RETURN QUERY
  SELECT m.id, m.name, hf.amount,
         COALESCE(
           (SELECT uf.net_amount FROM hostel_category_upgrade_fees uf
            WHERE uf.hostel_year_id = v_year AND uf.is_active
              AND uf.from_mess_category_id = v_cur_mess AND uf.to_mess_category_id = m.id LIMIT 1),
           hf.amount - v_cur_fee
         ) AS upgrade_fee,
         COALESCE(
           (SELECT uf.amount FROM hostel_category_upgrade_fees uf
            WHERE uf.hostel_year_id = v_year AND uf.is_active
              AND uf.from_mess_category_id = v_cur_mess AND uf.to_mess_category_id = m.id LIMIT 1),
           hf.amount - v_cur_fee
         ) AS upgrade_fee_original,
         COALESCE(
           (SELECT uf.amount - uf.net_amount FROM hostel_category_upgrade_fees uf
            WHERE uf.hostel_year_id = v_year AND uf.is_active
              AND uf.from_mess_category_id = v_cur_mess AND uf.to_mess_category_id = m.id LIMIT 1),
           0
         ) AS upgrade_discount
  FROM mess_categories m
  JOIN hostel_fees hf
    ON hf.mess_category_id = m.id AND hf.hostel_year_id = v_year AND hf.is_active
  WHERE m.is_active
    AND ((v_gender IN ('male','m')   AND m.type='boys')
         OR (v_gender IN ('female','f') AND m.type='girls'))
    AND m.id <> COALESCE(v_cur_mess, '00000000-0000-0000-0000-000000000000'::uuid)
    AND hf.amount > v_cur_fee
  ORDER BY hf.amount;
END $function$;

REVOKE EXECUTE ON FUNCTION public.fn_my_upgrade_mess_categories() FROM PUBLIC, anon;
GRANT  EXECUTE ON FUNCTION public.fn_my_upgrade_mess_categories() TO authenticated, service_role;

-- 4) Admin option loader ------------------------------------------------------
DROP FUNCTION IF EXISTS public.fn_cl_admin_room_upgrade_options(uuid);
CREATE OR REPLACE FUNCTION public.fn_cl_admin_room_upgrade_options(p_learner_id uuid)
RETURNS TABLE(category_id uuid, name text, type text, allocation_mode text,
              current_year_fee numeric, upgrade_fee numeric, available_beds integer,
              threshold_pct numeric, paid_pct numeric, meets_threshold boolean,
              hold_days integer, upgrade_fee_original numeric, upgrade_discount numeric)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE v_inst uuid; v_year uuid; v_cur_cat uuid; v_cur_fee numeric := 0; v_gender text; v_paid_pct numeric; v_profile uuid;
BEGIN
  IF NOT public.user_has_permission('campus_living.upgrades.manage') THEN
    RAISE EXCEPTION 'permission denied: campus_living.upgrades.manage' USING ERRCODE='42501';
  END IF;
  SELECT institution_id INTO v_inst FROM learners_profiles WHERE id = p_learner_id;
  IF v_inst IS NULL THEN RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.get_user_accessible_institutions(auth.uid()) g WHERE g.institution_id = v_inst) THEN
    RAISE EXCEPTION 'You do not have access to this learner''s institution' USING ERRCODE='42501';
  END IF;
  SELECT id INTO v_year FROM hostel_years WHERE is_current LIMIT 1;
  IF v_year IS NULL THEN RETURN; END IF;
  SELECT hostel_category_id INTO v_cur_cat FROM learners_profiles WHERE id = p_learner_id;
  SELECT p.id INTO v_profile FROM profiles p WHERE p.learner_id = p_learner_id;
  SELECT lower(trim(COALESCE(pr.gender, lp.gender))) INTO v_gender
    FROM learners_profiles lp LEFT JOIN profiles pr ON pr.learner_id = lp.id WHERE lp.id = p_learner_id;
  SELECT COALESCE(amount,0) INTO v_cur_fee FROM hostel_fees
    WHERE hostel_category_id = v_cur_cat AND hostel_year_id = v_year AND mess_category_id IS NULL AND is_active LIMIT 1;
  SELECT pp.paid_pct INTO v_paid_pct FROM fn_learner_academic_payment_progress(p_learner_id) pp;

  RETURN QUERY
  SELECT c.id, c.name, c.type, c.allocation_mode, hf.amount,
         COALESCE(
           (SELECT uf.net_amount FROM hostel_category_upgrade_fees uf
            WHERE uf.hostel_year_id = v_year AND uf.is_active
              AND uf.from_hostel_category_id = v_cur_cat AND uf.to_hostel_category_id = c.id LIMIT 1),
           hf.amount - v_cur_fee) AS upgrade_fee,
         (SELECT count(*)::int FROM _cl_room_options(v_profile, p_learner_id, c.id)),
         c.upgrade_threshold_pct,
         v_paid_pct,
         (c.upgrade_threshold_pct IS NULL OR (v_paid_pct IS NOT NULL AND v_paid_pct >= c.upgrade_threshold_pct)),
         c.upgrade_hold_days,
         COALESCE(
           (SELECT uf.amount FROM hostel_category_upgrade_fees uf
            WHERE uf.hostel_year_id = v_year AND uf.is_active
              AND uf.from_hostel_category_id = v_cur_cat AND uf.to_hostel_category_id = c.id LIMIT 1),
           hf.amount - v_cur_fee) AS upgrade_fee_original,
         COALESCE(
           (SELECT uf.amount - uf.net_amount FROM hostel_category_upgrade_fees uf
            WHERE uf.hostel_year_id = v_year AND uf.is_active
              AND uf.from_hostel_category_id = v_cur_cat AND uf.to_hostel_category_id = c.id LIMIT 1),
           0) AS upgrade_discount
  FROM hostel_categories c
  JOIN hostel_fees hf ON hf.hostel_category_id = c.id AND hf.hostel_year_id = v_year AND hf.mess_category_id IS NULL AND hf.is_active
  WHERE c.is_active AND c.allocation_mode = 'manual'
    AND ((v_gender IN ('male','m') AND c.type='boys') OR (v_gender IN ('female','f') AND c.type='girls'))
    AND c.id <> COALESCE(v_cur_cat, '00000000-0000-0000-0000-000000000000'::uuid)
    AND hf.amount > v_cur_fee
  ORDER BY hf.amount;
END $function$;

REVOKE EXECUTE ON FUNCTION public.fn_cl_admin_room_upgrade_options(uuid) FROM PUBLIC, anon;
GRANT  EXECUTE ON FUNCTION public.fn_cl_admin_room_upgrade_options(uuid) TO authenticated, service_role;

-- 5) Admin evaluators — jsonb, so no signature change (no DROP, grants intact) -
CREATE OR REPLACE FUNCTION public._cl_admin_eval_room_upgrade(p_lp uuid, p_target_category_id uuid)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_year uuid; v_gender text; v_gtype text;
  v_cur_cat uuid; v_cur_name text; v_cur_fee numeric := 0;
  v_t_name text; v_t_type text; v_t_mode text; v_t_active boolean; v_t_thr numeric;
  v_new_fee numeric; v_upg numeric; v_gross numeric; v_paid numeric; v_meets boolean;
BEGIN
  SELECT id INTO v_year FROM hostel_years WHERE is_current LIMIT 1;
  IF v_year IS NULL THEN RETURN jsonb_build_object('eligible', false, 'reason', 'No current hostel year configured'); END IF;

  SELECT lower(trim(COALESCE(pr.gender, lp.gender))) INTO v_gender
    FROM learners_profiles lp LEFT JOIN profiles pr ON pr.learner_id = lp.id WHERE lp.id = p_lp;
  v_gtype := CASE WHEN v_gender IN ('male','m') THEN 'boys'
                  WHEN v_gender IN ('female','f') THEN 'girls' ELSE NULL END;

  SELECT name, type, allocation_mode, is_active, upgrade_threshold_pct
    INTO v_t_name, v_t_type, v_t_mode, v_t_active, v_t_thr
    FROM hostel_categories WHERE id = p_target_category_id;
  IF v_t_name IS NULL OR NOT v_t_active THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Target category not found or inactive');
  END IF;
  IF v_t_mode IS DISTINCT FROM 'auto' THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Manual category -- upgrade this learner individually with a room selection',
      'target_category_id', p_target_category_id, 'target_category_name', v_t_name);
  END IF;
  IF v_gtype IS NULL OR v_t_type IS DISTINCT FROM v_gtype THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Category does not match learner gender',
      'target_category_id', p_target_category_id, 'target_category_name', v_t_name);
  END IF;

  SELECT amount INTO v_new_fee FROM hostel_fees
    WHERE hostel_category_id = p_target_category_id AND hostel_year_id = v_year AND mess_category_id IS NULL AND is_active LIMIT 1;
  IF v_new_fee IS NULL THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Target has no published fee for the current hostel year',
      'target_category_id', p_target_category_id, 'target_category_name', v_t_name);
  END IF;

  SELECT hostel_category_id INTO v_cur_cat FROM learners_profiles WHERE id = p_lp;
  SELECT name INTO v_cur_name FROM hostel_categories WHERE id = v_cur_cat;
  SELECT COALESCE(amount,0) INTO v_cur_fee FROM hostel_fees
    WHERE hostel_category_id = v_cur_cat AND hostel_year_id = v_year AND mess_category_id IS NULL AND is_active LIMIT 1;

  IF v_cur_cat = p_target_category_id THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Already on this category',
      'current_category_id', v_cur_cat, 'current_category_name', v_cur_name,
      'target_category_id', p_target_category_id, 'target_category_name', v_t_name);
  END IF;
  IF v_new_fee <= v_cur_fee THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Not an upgrade (target fee <= current fee)',
      'current_category_id', v_cur_cat, 'current_category_name', v_cur_name,
      'target_category_id', p_target_category_id, 'target_category_name', v_t_name);
  END IF;

  SELECT uf.net_amount, uf.amount INTO v_upg, v_gross FROM hostel_category_upgrade_fees uf
    WHERE uf.hostel_year_id = v_year AND uf.is_active
      AND uf.from_hostel_category_id = v_cur_cat AND uf.to_hostel_category_id = p_target_category_id LIMIT 1;
  IF v_upg IS NULL THEN
    v_upg := v_new_fee - v_cur_fee;
    v_gross := v_upg;
  END IF;

  SELECT pp.paid_pct INTO v_paid FROM fn_learner_academic_payment_progress(p_lp) pp;
  v_meets := (v_t_thr IS NULL) OR (v_paid IS NOT NULL AND v_paid >= v_t_thr);

  RETURN jsonb_build_object(
    'eligible', true, 'reason', NULL,
    'current_category_id', v_cur_cat, 'current_category_name', v_cur_name,
    'target_category_id', p_target_category_id, 'target_category_name', v_t_name,
    'current_fee', v_cur_fee, 'target_fee', v_new_fee, 'upgrade_fee', v_upg,
    'upgrade_fee_original', v_gross, 'upgrade_discount', v_gross - v_upg,
    'threshold_pct', v_t_thr, 'paid_pct', v_paid, 'meets_threshold', v_meets);
END $function$;

CREATE OR REPLACE FUNCTION public._cl_admin_eval_mess_upgrade(p_lp uuid, p_target_mess_id uuid)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_year uuid; v_gender text; v_gtype text;
  v_cur uuid; v_cur_name text; v_cur_fee numeric := 0;
  v_t_name text; v_t_type text; v_t_active boolean; v_new_fee numeric; v_upg numeric; v_gross numeric;
BEGIN
  SELECT id INTO v_year FROM hostel_years WHERE is_current LIMIT 1;
  IF v_year IS NULL THEN RETURN jsonb_build_object('eligible', false, 'reason', 'No current hostel year configured'); END IF;

  SELECT lower(trim(COALESCE(pr.gender, lp.gender))) INTO v_gender
    FROM learners_profiles lp LEFT JOIN profiles pr ON pr.learner_id = lp.id WHERE lp.id = p_lp;
  v_gtype := CASE WHEN v_gender IN ('male','m') THEN 'boys'
                  WHEN v_gender IN ('female','f') THEN 'girls' ELSE NULL END;

  SELECT name, type, is_active INTO v_t_name, v_t_type, v_t_active FROM mess_categories WHERE id = p_target_mess_id;
  IF v_t_name IS NULL OR NOT v_t_active THEN RETURN jsonb_build_object('eligible', false, 'reason', 'Target mess category not found or inactive'); END IF;
  IF v_gtype IS NULL OR v_t_type IS DISTINCT FROM v_gtype THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Mess category does not match learner gender',
      'target_category_id', p_target_mess_id, 'target_category_name', v_t_name);
  END IF;

  SELECT amount INTO v_new_fee FROM hostel_fees WHERE mess_category_id = p_target_mess_id AND hostel_year_id = v_year AND is_active LIMIT 1;
  IF v_new_fee IS NULL THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Target has no published fee for the current hostel year',
      'target_category_id', p_target_mess_id, 'target_category_name', v_t_name);
  END IF;

  SELECT mess_category_id INTO v_cur FROM learners_profiles WHERE id = p_lp;
  SELECT name INTO v_cur_name FROM mess_categories WHERE id = v_cur;
  SELECT COALESCE(amount,0) INTO v_cur_fee FROM hostel_fees WHERE mess_category_id = v_cur AND hostel_year_id = v_year AND is_active LIMIT 1;

  IF v_cur = p_target_mess_id THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Already on this mess category',
      'current_category_id', v_cur, 'current_category_name', v_cur_name,
      'target_category_id', p_target_mess_id, 'target_category_name', v_t_name);
  END IF;
  IF v_new_fee <= v_cur_fee THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Not an upgrade (target fee <= current fee)',
      'current_category_id', v_cur, 'current_category_name', v_cur_name,
      'target_category_id', p_target_mess_id, 'target_category_name', v_t_name);
  END IF;

  SELECT uf.net_amount, uf.amount INTO v_upg, v_gross FROM hostel_category_upgrade_fees uf
    WHERE uf.hostel_year_id = v_year AND uf.is_active
      AND uf.from_mess_category_id = v_cur AND uf.to_mess_category_id = p_target_mess_id LIMIT 1;
  IF v_upg IS NULL THEN
    v_upg := v_new_fee - v_cur_fee;
    v_gross := v_upg;
  END IF;

  RETURN jsonb_build_object('eligible', true, 'reason', NULL,
    'current_category_id', v_cur, 'current_category_name', v_cur_name,
    'target_category_id', p_target_mess_id, 'target_category_name', v_t_name,
    'current_fee', v_cur_fee, 'target_fee', v_new_fee, 'upgrade_fee', v_upg,
    'upgrade_fee_original', v_gross, 'upgrade_discount', v_gross - v_upg);
END $function$;

-- 6) Billing paths — charge net, stamp gross on the bill ----------------------
CREATE OR REPLACE FUNCTION public._cl_execute_room_upgrade(p_profile uuid, p_lp uuid, p_new_category_id uuid, p_room_id uuid, p_bed_id uuid, p_from_hold boolean DEFAULT false)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_year uuid; v_cur_cat uuid; v_cur_fee numeric := 0; v_new_fee numeric;
  v_new_name text; v_cur_name text; v_upgrade_fee numeric; v_gross numeric;
  v_bed_status text; v_old RECORD; v_new_alloc uuid; v_bill jsonb; v_linked_bill uuid;
BEGIN
  SELECT id INTO v_year FROM hostel_years WHERE is_current LIMIT 1;
  IF v_year IS NULL THEN RAISE EXCEPTION 'No current hostel year configured'; END IF;

  SELECT amount INTO v_new_fee FROM hostel_fees
    WHERE hostel_category_id = p_new_category_id AND hostel_year_id = v_year AND mess_category_id IS NULL AND is_active LIMIT 1;
  IF v_new_fee IS NULL THEN RAISE EXCEPTION 'Selected category has no published fee for the current hostel year'; END IF;
  SELECT name INTO v_new_name FROM hostel_categories WHERE id = p_new_category_id;

  SELECT hostel_category_id INTO v_cur_cat FROM learners_profiles WHERE id = p_lp;
  SELECT name INTO v_cur_name FROM hostel_categories WHERE id = v_cur_cat;
  SELECT COALESCE(amount,0) INTO v_cur_fee FROM hostel_fees
    WHERE hostel_category_id = v_cur_cat AND hostel_year_id = v_year AND mess_category_id IS NULL AND is_active LIMIT 1;
  IF v_new_fee < v_cur_fee THEN RAISE EXCEPTION 'Downgrades are not allowed (new fee < current fee)'; END IF;

  IF NOT pg_try_advisory_xact_lock(hashtext(p_bed_id::text)) THEN
    RAISE EXCEPTION 'Another resident is claiming this bed. Try again.';
  END IF;
  SELECT status INTO v_bed_status FROM hostel_beds WHERE id = p_bed_id AND room_id = p_room_id;
  IF p_from_hold THEN
    IF v_bed_status IS DISTINCT FROM 'reserved' THEN RAISE EXCEPTION 'Held bed is no longer reserved'; END IF;
  ELSE
    IF v_bed_status IS DISTINCT FROM 'available' THEN RAISE EXCEPTION 'That bed is no longer available'; END IF;
  END IF;

  SELECT id, bed_id, tier_id, academic_year_id, semester_id, institution_id, batch_id,
         emergency_contact_name, emergency_contact_phone, emergency_contact_relation
    INTO v_old
    FROM hostel_allocations
    WHERE learner_id = p_profile AND status = 'active'
    ORDER BY allocation_date DESC LIMIT 1;
  IF v_old.id IS NULL THEN RAISE EXCEPTION 'No active allocation to upgrade from'; END IF;

  -- 2026-08-06: check_out_date is what hostel_allocations_room_bed_active_uidx
  -- reads. Without it the vacated row keeps reserving (room_id, bed_id) and the
  -- old bed can never be re-used, even though hostel_beds says 'available'.
  UPDATE hostel_allocations SET status='vacated', actual_vacate_date=CURRENT_DATE,
         check_out_date=CURRENT_DATE, updated_at=now()
    WHERE id = v_old.id;
  UPDATE hostel_beds SET status='available', current_occupant_id=NULL WHERE id = v_old.bed_id;

  INSERT INTO hostel_allocations (
    institution_id, learner_id, block_id, room_id, bed_id, academic_year_id, semester_id,
    allocation_type, allocation_date, status,
    emergency_contact_name, emergency_contact_phone, emergency_contact_relation,
    tier_id, allocated_by, batch_id
  )
  SELECT v_old.institution_id, p_profile, r.block_id, p_room_id, p_bed_id,
         v_old.academic_year_id, v_old.semester_id, 'transfer', CURRENT_DATE, 'active',
         v_old.emergency_contact_name, v_old.emergency_contact_phone, v_old.emergency_contact_relation,
         v_old.tier_id, p_profile, v_old.batch_id
  FROM hostel_rooms r WHERE r.id = p_room_id
  RETURNING id INTO v_new_alloc;
  UPDATE hostel_beds SET status='occupied', current_occupant_id=p_profile WHERE id = p_bed_id;

  UPDATE learners_profiles SET hostel_category_id = p_new_category_id, pending_hostel_category_id = NULL, updated_at=now() WHERE id = p_lp;

  SELECT upgrade_bill_id INTO v_linked_bill FROM hostel_waitlist
   WHERE learner_id = p_profile AND entry_kind='upgrade'
     AND target_hostel_category_id = p_new_category_id AND status='waiting'
     AND upgrade_bill_id IS NOT NULL
   LIMIT 1;
  IF v_linked_bill IS NULL THEN
    SELECT uf.net_amount, uf.amount INTO v_upgrade_fee, v_gross FROM hostel_category_upgrade_fees uf
      WHERE uf.hostel_year_id = v_year AND uf.is_active
        AND uf.from_hostel_category_id = v_cur_cat AND uf.to_hostel_category_id = p_new_category_id LIMIT 1;
    IF v_upgrade_fee IS NULL THEN
      v_upgrade_fee := v_new_fee - v_cur_fee;
      v_gross := v_upgrade_fee;
    END IF;
    v_bill := public._cl_apply_upgrade_fee_bill(p_lp, v_year, 'hostel', v_upgrade_fee,
                format('Hostel room upgrade: %s -> %s%s', COALESCE(v_cur_name,'-'), v_new_name,
                       CASE WHEN v_gross > v_upgrade_fee
                            THEN format(' (discount Rs.%s)', trim(to_char(v_gross - v_upgrade_fee, 'FM999999990.99')))
                            ELSE '' END),
                v_gross);
  ELSE
    v_upgrade_fee := NULL;
    v_bill := jsonb_build_object('action','linked','bill_id',v_linked_bill);
  END IF;

  UPDATE hostel_waitlist
     SET status='allocated', allocated_allocation_id=v_new_alloc,
         held_room_id=NULL, held_bed_id=NULL, hold_expires_at=NULL, updated_at=now()
   WHERE learner_id = p_profile AND entry_kind='upgrade'
     AND target_hostel_category_id = p_new_category_id AND status='waiting';

  RETURN jsonb_build_object('success', true, 'state', 'upgraded',
    'old_allocation_id', v_old.id, 'new_allocation_id', v_new_alloc, 'new_bed_id', p_bed_id,
    'old_category_id', v_cur_cat, 'new_category_id', p_new_category_id,
    'old_fee', v_cur_fee, 'new_fee', v_new_fee, 'upgrade_fee', v_upgrade_fee,
    'upgrade_fee_original', v_gross, 'bill', v_bill);
END $function$;

CREATE OR REPLACE FUNCTION public._cl_upgrade_category_only(p_profile uuid, p_lp uuid, p_new_category_id uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_year uuid; v_cur_cat uuid; v_cur_fee numeric := 0; v_new_fee numeric;
  v_cur_name text; v_new_name text; v_upgrade_fee numeric; v_gross numeric; v_hold_days int;
  v_inst uuid; v_ay uuid; v_bill jsonb; v_bill_id uuid; v_wl uuid;
BEGIN
  SELECT id INTO v_year FROM hostel_years WHERE is_current LIMIT 1;
  IF v_year IS NULL THEN RAISE EXCEPTION 'No current hostel year configured'; END IF;

  SELECT amount INTO v_new_fee FROM hostel_fees
    WHERE hostel_category_id = p_new_category_id AND hostel_year_id = v_year AND mess_category_id IS NULL AND is_active LIMIT 1;
  IF v_new_fee IS NULL THEN RAISE EXCEPTION 'Selected category has no published fee for the current hostel year'; END IF;
  SELECT name, upgrade_hold_days INTO v_new_name, v_hold_days FROM hostel_categories WHERE id = p_new_category_id;

  SELECT hostel_category_id, institution_id, academic_year_id INTO v_cur_cat, v_inst, v_ay
    FROM learners_profiles WHERE id = p_lp;
  SELECT name INTO v_cur_name FROM hostel_categories WHERE id = v_cur_cat;
  SELECT COALESCE(amount,0) INTO v_cur_fee FROM hostel_fees
    WHERE hostel_category_id = v_cur_cat AND hostel_year_id = v_year AND mess_category_id IS NULL AND is_active LIMIT 1;
  IF v_cur_cat IS NOT NULL AND v_new_fee < v_cur_fee THEN
    RAISE EXCEPTION 'Downgrades are not allowed (new fee < current fee)';
  END IF;

  SELECT uf.net_amount, uf.amount INTO v_upgrade_fee, v_gross FROM hostel_category_upgrade_fees uf
    WHERE uf.hostel_year_id = v_year AND uf.is_active
      AND uf.from_hostel_category_id = v_cur_cat AND uf.to_hostel_category_id = p_new_category_id LIMIT 1;
  IF v_upgrade_fee IS NULL THEN
    v_upgrade_fee := v_new_fee - v_cur_fee;
    v_gross := v_upgrade_fee;
  END IF;

  -- Fully-discounted (or free) upgrade: flip the category now, bill nothing.
  IF COALESCE(v_upgrade_fee,0) <= 0 THEN
    UPDATE learners_profiles SET hostel_category_id = p_new_category_id, pending_hostel_category_id = NULL, updated_at=now() WHERE id = p_lp;
    RETURN jsonb_build_object('success', true, 'state', 'upgraded',
      'old_category_id', v_cur_cat, 'new_category_id', p_new_category_id, 'upgrade_fee', 0,
      'upgrade_fee_original', v_gross, 'upgrade_discount', COALESCE(v_gross,0));
  END IF;

  v_ay := COALESCE(v_ay, (SELECT id FROM academic_years WHERE institution_id=v_inst AND is_active ORDER BY start_date DESC LIMIT 1));
  IF v_ay IS NULL THEN RAISE EXCEPTION 'No academic year configured'; END IF;

  UPDATE billing_student_bills bb SET status='cancelled', updated_at=now()
    FROM hostel_waitlist w
   WHERE w.learner_id=p_profile AND w.entry_kind='upgrade' AND w.status='waiting'
     AND w.held_bed_id IS NULL AND w.target_hostel_category_id <> p_new_category_id
     AND w.upgrade_bill_id = bb.id AND bb.status='unpaid'
     AND NOT EXISTS (SELECT 1 FROM billing_receipt_items ri WHERE ri.bill_id=bb.id);
  UPDATE hostel_waitlist SET status='declined', updated_at=now()
   WHERE learner_id=p_profile AND entry_kind='upgrade' AND status='waiting'
     AND held_bed_id IS NULL AND target_hostel_category_id <> p_new_category_id;

  SELECT id, upgrade_bill_id INTO v_wl, v_bill_id FROM hostel_waitlist
    WHERE learner_id=p_profile AND entry_kind='upgrade' AND status='waiting'
      AND held_bed_id IS NULL AND target_hostel_category_id = p_new_category_id LIMIT 1;
  IF v_bill_id IS NOT NULL THEN
    UPDATE hostel_waitlist SET from_hostel_category_id = COALESCE(from_hostel_category_id, v_cur_cat), updated_at=now() WHERE id = v_wl;
    UPDATE learners_profiles SET hostel_category_id = p_new_category_id, pending_hostel_category_id = NULL, updated_at=now() WHERE id = p_lp;
    RETURN jsonb_build_object('success', true, 'state', 'pending_payment', 'waitlist_id', v_wl,
      'upgrade_bill_id', v_bill_id, 'upgrade_fee', v_upgrade_fee, 'upgrade_fee_original', v_gross,
      'old_category_id', v_cur_cat, 'new_category_id', p_new_category_id);
  END IF;

  v_bill := public._cl_apply_upgrade_fee_bill(p_lp, v_year, 'hostel', v_upgrade_fee,
              format('Hostel category upgrade: %s -> %s%s', COALESCE(v_cur_name,'-'), v_new_name,
                     CASE WHEN v_gross > v_upgrade_fee
                          THEN format(' (discount Rs.%s)', trim(to_char(v_gross - v_upgrade_fee, 'FM999999990.99')))
                          ELSE '' END),
              v_gross);
  v_bill_id := (v_bill->>'bill_id')::uuid;

  UPDATE billing_student_bills
     SET due_date = now() + make_interval(days => COALESCE(v_hold_days, 30))
   WHERE id = v_bill_id;

  IF v_wl IS NOT NULL THEN
    UPDATE hostel_waitlist SET upgrade_bill_id=v_bill_id,
      hold_expires_at = now() + make_interval(days => COALESCE(v_hold_days, 5)), updated_at=now() WHERE id=v_wl;
  ELSE
    INSERT INTO hostel_waitlist (institution_id, learner_id, academic_year_id, status, entry_kind,
      target_hostel_category_id, held_room_id, held_bed_id, hold_expires_at, upgrade_bill_id)
    VALUES (v_inst, p_profile, v_ay, 'waiting', 'upgrade',
      p_new_category_id, NULL, NULL, now() + make_interval(days => COALESCE(v_hold_days, 5)), v_bill_id) RETURNING id INTO v_wl;
  END IF;

  UPDATE hostel_waitlist SET from_hostel_category_id = COALESCE(from_hostel_category_id, v_cur_cat), updated_at=now() WHERE id = v_wl;
  UPDATE learners_profiles SET hostel_category_id = p_new_category_id, pending_hostel_category_id = NULL, updated_at=now() WHERE id = p_lp;

  RETURN jsonb_build_object('success', true, 'state', 'pending_payment', 'waitlist_id', v_wl,
    'upgrade_bill_id', v_bill_id, 'upgrade_fee', v_upgrade_fee, 'upgrade_fee_original', v_gross,
    'old_category_id', v_cur_cat, 'new_category_id', p_new_category_id,
    'old_fee', v_cur_fee, 'new_fee', v_new_fee);
END $function$;

CREATE OR REPLACE FUNCTION public._cl_upgrade_mess_category(p_lp uuid, p_new_mess_category_id uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_year uuid; v_cur_mess uuid; v_cur_fee numeric := 0; v_new_fee numeric;
  v_new_name text; v_cur_name text; v_upgrade_fee numeric; v_gross numeric; v_bill jsonb;
BEGIN
  SELECT id INTO v_year FROM hostel_years WHERE is_current LIMIT 1;
  IF v_year IS NULL THEN RAISE EXCEPTION 'No current hostel year configured'; END IF;

  SELECT amount INTO v_new_fee FROM hostel_fees
    WHERE mess_category_id = p_new_mess_category_id AND hostel_year_id = v_year AND is_active LIMIT 1;
  IF v_new_fee IS NULL THEN RAISE EXCEPTION 'Selected mess category has no published fee for the current hostel year'; END IF;
  SELECT name INTO v_new_name FROM mess_categories WHERE id = p_new_mess_category_id;

  SELECT lp.mess_category_id INTO v_cur_mess FROM learners_profiles lp WHERE lp.id = p_lp;
  SELECT name INTO v_cur_name FROM mess_categories WHERE id = v_cur_mess;
  SELECT COALESCE(hf.amount,0) INTO v_cur_fee FROM hostel_fees hf
    WHERE hf.mess_category_id = v_cur_mess AND hf.hostel_year_id = v_year AND hf.is_active LIMIT 1;
  IF v_new_fee < v_cur_fee THEN RAISE EXCEPTION 'Downgrades are not allowed (new fee < current fee)'; END IF;

  UPDATE learners_profiles SET mess_category_id = p_new_mess_category_id, updated_at=now() WHERE id = p_lp;

  SELECT uf.net_amount, uf.amount INTO v_upgrade_fee, v_gross FROM hostel_category_upgrade_fees uf
    WHERE uf.hostel_year_id = v_year AND uf.is_active
      AND uf.from_mess_category_id = v_cur_mess AND uf.to_mess_category_id = p_new_mess_category_id LIMIT 1;
  IF v_upgrade_fee IS NULL THEN
    v_upgrade_fee := v_new_fee - v_cur_fee;
    v_gross := v_upgrade_fee;
  END IF;
  v_bill := public._cl_apply_upgrade_fee_bill(p_lp, v_year, 'mess', v_upgrade_fee,
              format('Mess upgrade: %s -> %s%s', COALESCE(v_cur_name,'-'), v_new_name,
                     CASE WHEN v_gross > v_upgrade_fee
                          THEN format(' (discount Rs.%s)', trim(to_char(v_gross - v_upgrade_fee, 'FM999999990.99')))
                          ELSE '' END),
              v_gross);

  RETURN jsonb_build_object('success', true, 'old_category_id', v_cur_mess,
    'new_category_id', p_new_mess_category_id, 'old_fee', v_cur_fee, 'new_fee', v_new_fee,
    'upgrade_fee', v_upgrade_fee, 'upgrade_fee_original', v_gross,
    'upgrade_discount', v_gross - v_upgrade_fee, 'bill', v_bill);
END $function$;

CREATE OR REPLACE FUNCTION public.fn_cl_process_upgrade_holds(p_student_lp uuid)
RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_profile uuid; v_row RECORD; v_gate jsonb; v_count int := 0;
  v_has_alloc boolean; v_year uuid; v_cur_cat uuid; v_cur_fee numeric;
  v_new_fee numeric; v_cur_name text; v_new_name text;
  v_upgrade_fee numeric; v_bill jsonb; v_bill_id uuid;
  v_upgrade_fee numeric; v_gross numeric; v_bill jsonb; v_bill_id uuid;
  v_bill_amount numeric; v_bill_paid numeric; v_bill_status text;
  v_existing_alloc uuid;
BEGIN
  SELECT id INTO v_profile FROM profiles WHERE learner_id = p_student_lp;
  IF v_profile IS NULL THEN RETURN 0; END IF;
  SELECT id INTO v_year FROM hostel_years WHERE is_current LIMIT 1;

  FOR v_row IN
    SELECT id, target_hostel_category_id, held_room_id, held_bed_id, upgrade_bill_id
    FROM hostel_waitlist
    WHERE learner_id = v_profile AND entry_kind='upgrade' AND status='waiting'
      AND held_bed_id IS NOT NULL AND hold_expires_at > now()
    ORDER BY created_at
  LOOP
    BEGIN
      -- 2026-08-15: idempotency — if the learner already lives on the held
      -- bed (the expiry cron confirms lapsed reservations as move-ins now),
      -- stamp the row instead of double-allocating. The partial unique index
      -- hostel_allocations_room_bed_active_uidx would refuse the duplicate
      -- INSERT, and that error must not be the control flow.
      SELECT id INTO v_existing_alloc FROM hostel_allocations
       WHERE learner_id = v_profile AND status = 'active'
         AND room_id = v_row.held_room_id AND bed_id = v_row.held_bed_id
       LIMIT 1;
      IF v_existing_alloc IS NOT NULL THEN
        UPDATE hostel_waitlist
           SET status='allocated', allocated_allocation_id=v_existing_alloc,
               held_room_id=NULL, held_bed_id=NULL, hold_expires_at=NULL, updated_at=now()
         WHERE id = v_row.id;
        v_count := v_count + 1; CONTINUE;
      END IF;
      v_gate := public._cl_upgrade_threshold_check(p_student_lp, v_row.target_hostel_category_id);
      IF NOT (v_gate->>'meets')::boolean THEN CONTINUE; END IF;
      v_has_alloc := EXISTS (SELECT 1 FROM hostel_allocations WHERE learner_id = v_profile AND status='active');
      IF NOT v_has_alloc THEN
        PERFORM public._cl_execute_first_booking(v_profile, p_student_lp, v_row.target_hostel_category_id,
          v_row.held_room_id, v_row.held_bed_id, true);
        v_count := v_count + 1; CONTINUE;
      END IF;
      v_bill_id := v_row.upgrade_bill_id;
      IF v_bill_id IS NOT NULL THEN
        SELECT final_amount, status INTO v_bill_amount, v_bill_status FROM billing_student_bills WHERE id = v_bill_id;
        IF v_bill_amount IS NULL OR v_bill_status IN ('cancelled','superseded') THEN v_bill_id := NULL; END IF;
      END IF;
      IF v_bill_id IS NULL THEN
        SELECT hostel_category_id INTO v_cur_cat FROM learners_profiles WHERE id = p_student_lp;
        SELECT COALESCE(amount,0) INTO v_cur_fee FROM hostel_fees
          WHERE hostel_category_id = v_cur_cat AND hostel_year_id = v_year AND mess_category_id IS NULL AND is_active LIMIT 1;
        SELECT amount INTO v_new_fee FROM hostel_fees
          WHERE hostel_category_id = v_row.target_hostel_category_id AND hostel_year_id = v_year AND mess_category_id IS NULL AND is_active LIMIT 1;
        SELECT amount INTO v_upgrade_fee FROM hostel_category_upgrade_fees
          WHERE hostel_year_id = v_year AND is_active
            AND from_hostel_category_id = v_cur_cat AND to_hostel_category_id = v_row.target_hostel_category_id LIMIT 1;
        v_upgrade_fee := COALESCE(v_upgrade_fee, COALESCE(v_new_fee,0) - COALESCE(v_cur_fee,0));
        SELECT uf.net_amount, uf.amount INTO v_upgrade_fee, v_gross FROM hostel_category_upgrade_fees uf
          WHERE uf.hostel_year_id = v_year AND uf.is_active
            AND uf.from_hostel_category_id = v_cur_cat AND uf.to_hostel_category_id = v_row.target_hostel_category_id LIMIT 1;
        IF v_upgrade_fee IS NULL THEN
          v_upgrade_fee := COALESCE(v_new_fee,0) - COALESCE(v_cur_fee,0);
          v_gross := v_upgrade_fee;
        END IF;
        -- Fully-discounted: no bill to wait on, move the resident in now.
        IF COALESCE(v_upgrade_fee, 0) <= 0 THEN
          PERFORM public._cl_execute_room_upgrade(v_profile, p_student_lp, v_row.target_hostel_category_id,
            v_row.held_room_id, v_row.held_bed_id, true);
          v_count := v_count + 1; CONTINUE;
        END IF;
        SELECT name INTO v_cur_name FROM hostel_categories WHERE id = v_cur_cat;
        SELECT name INTO v_new_name FROM hostel_categories WHERE id = v_row.target_hostel_category_id;
        v_bill := public._cl_apply_upgrade_fee_bill(p_student_lp, v_year, 'hostel', v_upgrade_fee,
                    format('Hostel room upgrade: %s → %s', COALESCE(v_cur_name,'—'), v_new_name));
                    format('Hostel room upgrade: %s -> %s%s', COALESCE(v_cur_name,'-'), v_new_name,
                           CASE WHEN v_gross > v_upgrade_fee
                                THEN format(' (discount Rs.%s)', trim(to_char(v_gross - v_upgrade_fee, 'FM999999990.99')))
                                ELSE '' END),
                    v_gross);
        UPDATE hostel_waitlist SET upgrade_bill_id = (v_bill->>'bill_id')::uuid, updated_at=now() WHERE id = v_row.id;
        CONTINUE;
      END IF;
      SELECT COALESCE(SUM(ri.amount_paid),0) INTO v_bill_paid FROM billing_receipt_items ri WHERE ri.bill_id = v_bill_id;
      IF v_bill_paid >= v_bill_amount THEN
        PERFORM public._cl_execute_room_upgrade(v_profile, p_student_lp, v_row.target_hostel_category_id,
          v_row.held_room_id, v_row.held_bed_id, true);
        v_count := v_count + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'fn_cl_process_upgrade_holds (room): % (waitlist %)', SQLERRM, v_row.id;
    END;
  END LOOP;

  FOR v_row IN
    SELECT id, target_hostel_category_id, upgrade_bill_id
    FROM hostel_waitlist
    WHERE learner_id = v_profile AND entry_kind='upgrade' AND status='waiting'
      AND held_bed_id IS NULL AND upgrade_bill_id IS NOT NULL
    ORDER BY created_at
  LOOP
    BEGIN
      v_gate := public._cl_upgrade_threshold_check(p_student_lp, v_row.target_hostel_category_id);
      IF NOT (v_gate->>'meets')::boolean THEN CONTINUE; END IF;
      SELECT final_amount, status INTO v_bill_amount, v_bill_status FROM billing_student_bills WHERE id = v_row.upgrade_bill_id;
      IF v_bill_amount IS NULL OR v_bill_status IN ('cancelled','superseded') THEN CONTINUE; END IF;
      SELECT COALESCE(SUM(ri.amount_paid),0) INTO v_bill_paid FROM billing_receipt_items ri WHERE ri.bill_id = v_row.upgrade_bill_id;
      IF v_bill_paid >= v_bill_amount THEN
        UPDATE learners_profiles SET hostel_category_id = v_row.target_hostel_category_id, pending_hostel_category_id = NULL, updated_at=now() WHERE id = p_student_lp;
        UPDATE hostel_waitlist SET status='allocated', updated_at=now() WHERE id = v_row.id;
        v_count := v_count + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'fn_cl_process_upgrade_holds (category): % (waitlist %)', SQLERRM, v_row.id;
    END;
  END LOOP;

  RETURN v_count;
END $function$;

-- Service-role only (fired by the receipt-item trigger, which is SECURITY
-- DEFINER itself); same ACL the live function carries.
REVOKE EXECUTE ON FUNCTION public.fn_cl_process_upgrade_holds(uuid) FROM anon, authenticated, PUBLIC;

-- =============================================================================
-- LATE PAYMENT CHARGE MECHANISM (2026-08-07)
-- Source: supabase/migrations/20260815010000_late_charge_mechanism.sql
-- (FILE ONLY — apply is Director-gated). Four SECURITY DEFINER functions,
-- byte-identical to the migration. The mechanism is OFF by default
-- (billing.late_charge.enabled = false in platform_policies).
-- =============================================================================
-- -----------------------------------------------------------------------------
-- 4a. fn_late_charge_preview — read-only, per-bill "what would be charged
--     today". Powers the admin dry-run page AND the warning preview (who would
--     be messaged). WRITES NOTHING; works while the master switch is OFF —
--     that is the point of a preview.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_late_charge_preview()
RETURNS TABLE (
  bill_id uuid,
  student_id uuid,
  learner_name text,
  institution_id uuid,
  bill_description text,
  due_date date,
  months_overdue integer,
  balance_amount numeric,
  would_charge numeric,
  total_would_owe numeric
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_is_admin boolean;
  v_rate numeric;
  v_compounding boolean;
  v_grace integer;
  v_factor numeric;
BEGIN
  v_is_admin := is_super_admin() OR is_admin();
  IF NOT (v_is_admin OR user_has_permission('billing.late_charges.view')) THEN
    RAISE EXCEPTION 'insufficient privilege: billing.late_charges.view required'
      USING ERRCODE = '42501';
  END IF;

  -- STABLE body: read policies through STABLE fn_get_policy (NOT the
  -- instrumented fn_get_policy_bool, which is VOLATILE on production).
  v_rate        := COALESCE((fn_get_policy('billing.late_charge.rate_percent_per_month'))::numeric, 10);
  v_compounding := COALESCE((fn_get_policy('billing.late_charge.compounding'))::boolean, true);
  v_grace       := COALESCE((fn_get_policy('billing.late_charge.grace_days'))::int, 0);
  v_factor      := 1 + v_rate / 100.0;

  RETURN QUERY
  WITH eligible AS (
    SELECT
      b.id            AS e_bill_id,
      b.student_id    AS e_student_id,
      b.institution_id AS e_institution_id,
      b.bill_description AS e_description,
      b.due_date      AS e_due_date,
      b.balance_amount AS e_balance,
      -- First overdue day is the day AFTER due_date (+ grace). Month 1's charge
      -- applies from that first day — "starts the day a bill goes overdue".
      (b.due_date + v_grace + 1) AS e_overdue_start,
      CASE
        WHEN current_date < (b.due_date + v_grace + 1) THEN 0
        ELSE 12 * EXTRACT(YEAR FROM age(current_date, (b.due_date + v_grace + 1)))::int
           + EXTRACT(MONTH FROM age(current_date, (b.due_date + v_grace + 1)))::int
           + 1
      END AS e_months
    FROM billing_student_bills b
    WHERE b.status IN ('unpaid', 'partially_paid')
      AND b.balance_amount > 0
      AND b.due_date + v_grace < current_date
      -- Never accrue on penalty bills themselves: the compounding formula
      -- already carries month-on-month growth; charging the charge would
      -- double-count it.
      AND NOT EXISTS (
        SELECT 1 FROM billing_categories bc
        WHERE bc.id = b.item_category_id AND bc.kind = 'penalty'
      )
      AND (v_is_admin OR role_has_institution_access(b.institution_id))
  )
  SELECT
    e.e_bill_id,
    e.e_student_id,
    TRIM(lp.first_name || ' ' || COALESCE(lp.last_name, '')),
    e.e_institution_id,
    e.e_description,
    e.e_due_date,
    e.e_months,
    e.e_balance,
    CASE WHEN v_compounding
      THEN ROUND(e.e_balance * (POWER(v_factor, e.e_months) - 1), 2)
      ELSE ROUND(e.e_balance * (v_rate / 100.0) * e.e_months, 2)
    END,
    CASE WHEN v_compounding
      THEN ROUND(e.e_balance * POWER(v_factor, e.e_months), 2)
      ELSE ROUND(e.e_balance * (1 + (v_rate / 100.0) * e.e_months), 2)
    END
  FROM eligible e
  LEFT JOIN learners_profiles lp ON lp.id = e.e_student_id
  WHERE e.e_months >= 1
  ORDER BY 9 DESC;  -- largest would_charge first
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_late_charge_preview() FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_late_charge_preview() TO authenticated;

-- -----------------------------------------------------------------------------
-- 4b. fn_late_charge_derivation — the month-by-month explanation of ONE bill's
--     late charge. Callable by admins (view permission + institution scope)
--     AND by the learner who owns the bill.
--
--     Computed on the bill's CURRENT outstanding balance for ALL months —
--     payments reduce every month's base, which is deliberately favourable to
--     families: paying part of a bill shrinks the whole charge history, never
--     just the months after the payment.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_late_charge_derivation(p_bill_id uuid)
RETURNS TABLE (
  month_number integer,
  period_start date,
  period_end date,
  opening_base numeric,
  rate_percent numeric,
  month_charge numeric,
  cumulative_charge numeric
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_is_admin boolean;
  v_allowed boolean;
  v_rate numeric;
  v_compounding boolean;
  v_grace integer;
  v_factor numeric;
  v_balance numeric;
  v_overdue_start date;
  v_months integer;
BEGIN
  v_is_admin := is_super_admin() OR is_admin();

  SELECT b.balance_amount,
         (v_is_admin
          OR (user_has_permission('billing.late_charges.view')
              AND role_has_institution_access(b.institution_id))
          -- The learner who owns the bill — same two linkages as the live
          -- bills RLS (profiles.learner_id OR the email join), and only for
          -- categories the learner is allowed to see.
          OR (
            b.student_id IN (
              SELECT lp.id
              FROM learners_profiles lp
              JOIN profiles p ON p.id = auth.uid()
              WHERE lp.id = p.learner_id
                 OR p.email IN (lp.student_email, lp.college_email)
            )
            AND (
              b.item_category_id IS NULL
              OR EXISTS (
                SELECT 1 FROM billing_categories bc
                WHERE bc.id = b.item_category_id AND bc.visible_to_learners
              )
            )
          ))
    INTO v_balance, v_allowed
  FROM billing_student_bills b
  WHERE b.id = p_bill_id
    AND b.status IN ('unpaid', 'partially_paid')
    AND b.balance_amount > 0
    AND NOT EXISTS (
      SELECT 1 FROM billing_categories bc
      WHERE bc.id = b.item_category_id AND bc.kind = 'penalty'
    );

  -- Unknown bill, settled bill, penalty bill, or no right to see it:
  -- return no rows rather than leaking that the bill exists.
  IF v_balance IS NULL OR NOT COALESCE(v_allowed, false) THEN
    RETURN;
  END IF;

  v_rate        := COALESCE((fn_get_policy('billing.late_charge.rate_percent_per_month'))::numeric, 10);
  v_compounding := COALESCE((fn_get_policy('billing.late_charge.compounding'))::boolean, true);
  v_grace       := COALESCE((fn_get_policy('billing.late_charge.grace_days'))::int, 0);
  v_factor      := 1 + v_rate / 100.0;

  SELECT b.due_date + v_grace + 1 INTO v_overdue_start
  FROM billing_student_bills b WHERE b.id = p_bill_id;

  IF current_date < v_overdue_start THEN
    RETURN;  -- not overdue yet (grace window) — no months, no charge
  END IF;

  v_months := 12 * EXTRACT(YEAR FROM age(current_date, v_overdue_start))::int
            + EXTRACT(MONTH FROM age(current_date, v_overdue_start))::int
            + 1;

  RETURN QUERY
  SELECT
    gs.k,
    (v_overdue_start + make_interval(months => gs.k - 1))::date,
    ((v_overdue_start + make_interval(months => gs.k))::date - 1),
    CASE WHEN v_compounding
      THEN ROUND(v_balance * POWER(v_factor, gs.k - 1), 2)
      ELSE v_balance
    END,
    v_rate,
    CASE WHEN v_compounding
      THEN ROUND(v_balance * (POWER(v_factor, gs.k) - POWER(v_factor, gs.k - 1)), 2)
      ELSE ROUND(v_balance * (v_rate / 100.0), 2)
    END,
    CASE WHEN v_compounding
      THEN ROUND(v_balance * (POWER(v_factor, gs.k) - 1), 2)
      ELSE ROUND(v_balance * (v_rate / 100.0) * gs.k, 2)
    END
  FROM generate_series(1, v_months) gs(k);
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_late_charge_derivation(uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_late_charge_derivation(uuid) TO authenticated;

-- -----------------------------------------------------------------------------
-- 4c. fn_late_charge_accrue — the ONLY writer. Idempotent on
--     UNIQUE (bill_id, period_start). Dry-run by default; the live path is
--     quadruple-gated: caller privilege + master switch + effective_from set
--     + effective_from reached. Defense in depth — even a live call with the
--     switch off RAISEs.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_late_charge_accrue(p_dry_run boolean DEFAULT true)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_rate numeric;
  v_compounding boolean;
  v_grace integer;
  v_factor numeric;
  v_effective_raw text;
  v_effective date;
  v_penalty_cat uuid;
  v_bills bigint := 0;
  v_rows bigint := 0;
  v_total numeric := 0;
  v_inserted bigint := 0;
  v_penalty_bills bigint := 0;
  r RECORD;
  v_new_bill uuid;
BEGIN
  -- Caller gate: the cron route (service role), a super admin, or a holder of
  -- billing.late_charges.manage. Inside SECURITY DEFINER current_user is the
  -- owner for everyone, so the PostgREST end-user signal is auth.role() and the
  -- direct-SQL signal (Director via Management API / psql) is session_user not
  -- being the PostgREST 'authenticator' pool role.
  IF NOT (
    COALESCE(auth.role(), '') = 'service_role'
    OR session_user <> 'authenticator'
    OR is_super_admin()
    OR user_has_permission('billing.late_charges.manage')
  ) THEN
    RAISE EXCEPTION 'insufficient privilege: billing.late_charges.manage required'
      USING ERRCODE = '42501';
  END IF;

  -- Master switch — spec-mandated fn_get_policy_bool read (VOLATILE is fine
  -- here, this function is VOLATILE).
  IF NOT fn_get_policy_bool('billing.late_charge.enabled', false) THEN
    RAISE EXCEPTION 'late-payment charge is disabled (billing.late_charge.enabled = false) — nothing accrued';
  END IF;

  v_effective_raw := NULLIF(TRIM(fn_get_policy_text('billing.late_charge.effective_from', '')), '');
  IF v_effective_raw IS NULL THEN
    RAISE EXCEPTION 'billing.late_charge.effective_from is not set — the Director must set the start date before any accrual';
  END IF;
  v_effective := v_effective_raw::date;
  IF current_date < v_effective THEN
    RAISE EXCEPTION 'late-payment charge takes effect % — refusing to accrue before then', v_effective;
  END IF;

  SELECT id INTO v_penalty_cat
  FROM billing_categories
  WHERE kind = 'penalty'::billing_category_kind AND is_active
  ORDER BY created_at
  LIMIT 1;
  IF v_penalty_cat IS NULL THEN
    RAISE EXCEPTION 'no active penalty billing category found';
  END IF;

  v_rate        := fn_get_policy_int('billing.late_charge.rate_percent_per_month', 10);
  v_compounding := fn_get_policy_bool('billing.late_charge.compounding', true);
  v_grace       := fn_get_policy_int('billing.late_charge.grace_days', 0);
  v_factor      := 1 + v_rate / 100.0;

  -- Everything that WOULD be inserted today: each eligible overdue bill ×
  -- each monthly period since it went overdue, minus periods already ledgered.
  -- DROP first: a dry-run and a live call in the SAME transaction would
  -- otherwise collide on the temp table.
  DROP TABLE IF EXISTS _late_charge_candidates;
  CREATE TEMP TABLE _late_charge_candidates ON COMMIT DROP AS
  WITH eligible AS (
    SELECT
      b.id AS bill_id,
      b.student_id,
      b.institution_id,
      b.academic_year_id,
      b.bill_description,
      b.balance_amount,
      (b.due_date + v_grace + 1) AS overdue_start,
      12 * EXTRACT(YEAR FROM age(current_date, (b.due_date + v_grace + 1)))::int
        + EXTRACT(MONTH FROM age(current_date, (b.due_date + v_grace + 1)))::int
        + 1 AS months_overdue
    FROM billing_student_bills b
    WHERE b.status IN ('unpaid', 'partially_paid')
      AND b.balance_amount > 0
      AND b.due_date + v_grace < current_date
      AND NOT EXISTS (
        SELECT 1 FROM billing_categories bc
        WHERE bc.id = b.item_category_id AND bc.kind = 'penalty'
      )
  ),
  periods AS (
    SELECT
      e.*,
      gs.k,
      (e.overdue_start + make_interval(months => gs.k - 1))::date AS period_start,
      ((e.overdue_start + make_interval(months => gs.k))::date - 1) AS period_end,
      CASE WHEN v_compounding
        THEN ROUND(e.balance_amount * POWER(v_factor, gs.k - 1), 2)
        ELSE e.balance_amount
      END AS base_amount,
      CASE WHEN v_compounding
        THEN ROUND(e.balance_amount * (POWER(v_factor, gs.k) - POWER(v_factor, gs.k - 1)), 2)
        ELSE ROUND(e.balance_amount * (v_rate / 100.0), 2)
      END AS charge_amount
    FROM eligible e
    CROSS JOIN LATERAL generate_series(1, e.months_overdue) gs(k)
  )
  SELECT p.*
  FROM periods p
  WHERE NOT EXISTS (
    SELECT 1 FROM billing_late_charges c
    WHERE c.bill_id = p.bill_id AND c.period_start = p.period_start
  );

  SELECT COUNT(DISTINCT bill_id), COUNT(*), COALESCE(SUM(charge_amount), 0)
    INTO v_bills, v_rows, v_total
  FROM _late_charge_candidates;

  IF p_dry_run THEN
    RETURN jsonb_build_object(
      'dry_run', true,
      'bills_examined', v_bills,
      'charge_rows_would_insert', v_rows,
      'total_charge', v_total
    );
  END IF;

  -- LIVE PATH. Conflict target matches uq_billing_late_charges_bill_period
  -- exactly (bill_id, period_start) — the idempotency contract.
  INSERT INTO billing_late_charges
    (bill_id, student_id, institution_id, period_start, period_end,
     base_amount, charge_amount, status)
  SELECT bill_id, student_id, institution_id, period_start, period_end,
         base_amount, charge_amount, 'pending'
  FROM _late_charge_candidates
  ON CONFLICT (bill_id, period_start) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  -- Bill every pending, un-billed charge row through the penalty category.
  FOR r IN
    SELECT c.id, c.bill_id, c.student_id, c.institution_id, c.period_start,
           c.period_end, c.charge_amount, b.bill_description, b.academic_year_id
    FROM billing_late_charges c
    JOIN billing_student_bills b ON b.id = c.bill_id
    WHERE c.status = 'pending' AND c.penalty_bill_id IS NULL
  LOOP
    INSERT INTO billing_student_bills
      (student_id, institution_id, item_category_id, bill_description, due_date,
       quantity, unit_amount, total_amount, tax_amount, final_amount,
       balance_amount, status, academic_year_id)
    VALUES
      (r.student_id, r.institution_id, v_penalty_cat,
       'Late payment charge — ' || r.bill_description
         || ' (' || to_char(r.period_start, 'DD Mon YYYY')
         || ' to ' || to_char(r.period_end, 'DD Mon YYYY') || ')',
       current_date, 1, r.charge_amount, r.charge_amount, 0, r.charge_amount,
       r.charge_amount, 'unpaid', r.academic_year_id)
    RETURNING id INTO v_new_bill;

    UPDATE billing_late_charges
       SET status = 'charged', penalty_bill_id = v_new_bill, updated_at = now()
     WHERE id = r.id;

    v_penalty_bills := v_penalty_bills + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'dry_run', false,
    'bills_examined', v_bills,
    'charge_rows_inserted', v_inserted,
    'penalty_bills_created', v_penalty_bills,
    'total_charge', v_total
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_late_charge_accrue(boolean) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_late_charge_accrue(boolean) TO authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 4d. fn_late_charge_waive — Director-only in practice: requires
--     billing.late_charges.waive, which this PR grants to NO role, so only the
--     super-admin bypass (the Director) can call it today. Always records the
--     approver and the reason; cancels the linked penalty bill if one exists.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_late_charge_waive(p_late_charge_id uuid, p_reason text)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_row billing_late_charges%ROWTYPE;
  v_penalty_cancelled boolean := false;
BEGIN
  IF NOT (is_super_admin() OR user_has_permission('billing.late_charges.waive')) THEN
    RAISE EXCEPTION 'insufficient privilege: billing.late_charges.waive required'
      USING ERRCODE = '42501';
  END IF;

  IF NULLIF(TRIM(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'a waiver reason is required — waivers are always recorded with who and why';
  END IF;

  UPDATE billing_late_charges
     SET status = 'waived',
         waived_by = auth.uid(),
         waived_at = now(),
         waiver_reason = TRIM(p_reason),
         updated_at = now()
   WHERE id = p_late_charge_id
     AND status <> 'waived'
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'late charge % not found or already waived', p_late_charge_id;
  END IF;

  -- Cancel the linked penalty bill unless it has already been fully paid —
  -- a paid penalty needs a refund decision, which is a human call, not this
  -- function's.
  IF v_row.penalty_bill_id IS NOT NULL THEN
    UPDATE billing_student_bills
       SET status = 'cancelled', balance_amount = 0, updated_at = now()
     WHERE id = v_row.penalty_bill_id
       AND status IN ('unpaid', 'partially_paid');
    v_penalty_cancelled := FOUND;
  END IF;

  RETURN jsonb_build_object(
    'waived', true,
    'late_charge_id', v_row.id,
    'waived_by', v_row.waived_by,
    'waived_at', v_row.waived_at,
    'penalty_bill_id', v_row.penalty_bill_id,
    'penalty_bill_cancelled', v_penalty_cancelled
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_late_charge_waive(uuid, text) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_late_charge_waive(uuid, text) TO authenticated;

-- ============================================================================
-- Campus Living: curated upgrade ladder + "Plus" self-pick tiers
-- (migrations 20260807140000 / 20260807150000 / 20260807160000)
-- Supersedes the earlier definitions above.
--  * room/bed loaders resolve COALESCE(room_source_category_id, id), so a
--    stockless tier (Deluxe Plus) sells from its source pool (Deluxe).
--  * the allocation sync trigger no longer demotes a self-pick resident back
--    to the category of the room they occupy.
--  * the admin option loader + evaluator honour requires_explicit_upgrade,
--    so the office cannot execute an edge the resident never sees.
-- ============================================================================
-- 2) Room/bed loaders resolve the source category -----------------------------
-- All three keep their signatures, so CREATE OR REPLACE is safe (no DROP => grants
-- and dependent plpgsql callers are untouched).

CREATE OR REPLACE FUNCTION public.fn_my_room_options(p_category_id uuid)
RETURNS TABLE(bed_id uuid, room_id uuid, room_number text, floor integer, block_name text, bed_number text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE v_lp uuid := get_my_learner_id(); v_inst uuid; v_gender text; v_src uuid;
BEGIN
  IF v_lp IS NULL THEN RETURN; END IF;
  -- A "Plus" tier has no rooms of its own; resolve to the pool it sells from.
  SELECT COALESCE(room_source_category_id, id) INTO v_src
    FROM hostel_categories WHERE id = p_category_id;
  IF v_src IS NULL THEN RETURN; END IF;
  SELECT institution_id INTO v_inst FROM learners_profiles WHERE id=v_lp;
  SELECT lower(trim(gender)) INTO v_gender FROM profiles WHERE profiles.id = auth.uid();
  RETURN QUERY
  SELECT b.id, r.id, r.room_number, r.floor, bl.name, b.bed_number
  FROM hostel_beds b
  JOIN hostel_rooms r ON r.id=b.room_id
  JOIN hostel_blocks bl ON bl.id=r.block_id
  WHERE r.category_id=v_src AND r.room_purpose='student' AND b.status='available'
    AND (bl.hostel_type::text='mixed'
         OR (v_gender IN ('male','m')   AND bl.hostel_type::text='boys')
         OR (v_gender IN ('female','f') AND bl.hostel_type::text='girls'))
    AND fn_room_serves_institution(r.id, v_inst)
    AND NOT EXISTS (SELECT 1 FROM hostel_allocations a WHERE a.bed_id=b.id AND a.status IN ('active','pending_approval'))
    AND fn_learner_eligible_for_room(v_lp, r.id)
  ORDER BY bl.name, r.floor, r.room_number, b.bed_number;
END $function$;

CREATE OR REPLACE FUNCTION public.fn_my_upgrade_room_options(p_category_id uuid)
RETURNS TABLE(room_id uuid, room_number text, floor integer, block_name text, capacity integer, occupied_beds integer, available_beds integer)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE v_lp uuid := get_my_learner_id(); v_inst uuid; v_gender text; v_src uuid;
BEGIN
  IF v_lp IS NULL THEN RETURN; END IF;
  SELECT COALESCE(room_source_category_id, id) INTO v_src
    FROM hostel_categories WHERE id = p_category_id;
  IF v_src IS NULL THEN RETURN; END IF;
  SELECT institution_id INTO v_inst FROM learners_profiles WHERE id = v_lp;
  SELECT lower(trim(gender)) INTO v_gender FROM profiles WHERE profiles.id = auth.uid();
  RETURN QUERY
  SELECT r.id, r.room_number, r.floor, bl.name,
         COALESCE(r.actual_capacity, r.capacity)::int,
         GREATEST(COALESCE(r.actual_capacity, r.capacity)::int - av.free, 0),
         av.free
  FROM hostel_rooms r
  JOIN hostel_blocks bl ON bl.id = r.block_id
  CROSS JOIN LATERAL (
    SELECT count(*)::int AS free
    FROM hostel_beds b
    WHERE b.room_id = r.id AND b.status = 'available'
      AND NOT EXISTS (
        SELECT 1 FROM hostel_allocations a
        WHERE a.bed_id = b.id AND a.status IN ('active','pending_approval')
      )
  ) av
  WHERE r.category_id = v_src AND r.room_purpose = 'student'
    AND (bl.hostel_type::text = 'mixed'
         OR (v_gender IN ('male','m')   AND bl.hostel_type::text = 'boys')
         OR (v_gender IN ('female','f') AND bl.hostel_type::text = 'girls'))
    AND fn_room_serves_institution(r.id, v_inst)
    AND fn_learner_eligible_for_room(v_lp, r.id)
    AND av.free > 0
  ORDER BY bl.name, r.floor, r.room_number;
END $function$;

CREATE OR REPLACE FUNCTION public._cl_room_options(p_profile uuid, p_lp uuid, p_category_id uuid)
RETURNS TABLE(bed_id uuid, room_id uuid, room_number text, floor integer, block_name text, bed_number text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE v_inst uuid; v_gender text; v_src uuid;
BEGIN
  IF p_lp IS NULL THEN RETURN; END IF;
  SELECT COALESCE(room_source_category_id, id) INTO v_src
    FROM hostel_categories WHERE id = p_category_id;
  IF v_src IS NULL THEN RETURN; END IF;
  SELECT institution_id INTO v_inst FROM learners_profiles WHERE id = p_lp;
  SELECT lower(trim(COALESCE(pr.gender, lp.gender))) INTO v_gender
    FROM learners_profiles lp LEFT JOIN profiles pr ON pr.id = p_profile WHERE lp.id = p_lp;
  RETURN QUERY
  SELECT b.id, r.id, r.room_number, r.floor, bl.name, b.bed_number
  FROM hostel_beds b
  JOIN hostel_rooms r ON r.id = b.room_id
  JOIN hostel_blocks bl ON bl.id = r.block_id
  WHERE r.category_id = v_src AND r.room_purpose = 'student' AND b.status = 'available'
    AND (bl.hostel_type::text = 'mixed'
         OR (v_gender IN ('male','m')   AND bl.hostel_type::text = 'boys')
         OR (v_gender IN ('female','f') AND bl.hostel_type::text = 'girls'))
    AND fn_room_serves_institution(r.id, v_inst)
    AND NOT EXISTS (SELECT 1 FROM hostel_allocations a WHERE a.bed_id = b.id AND a.status IN ('active','pending_approval'))
    AND fn_learner_eligible_for_room(p_lp, r.id)
  ORDER BY bl.name, r.floor, r.room_number, b.bed_number;
END $function$;

-- 3) Stop the allocation trigger reverting a self-pick upgrade ----------------
-- This trigger unconditionally did:
--     hostel_category_id = (SELECT category_id FROM hostel_rooms WHERE id = NEW.room_id)
-- A Deluxe Plus resident LIVES IN A DELUXE ROOM, so every re-activation of their
-- allocation silently demoted them back to Deluxe — voiding the add-on they paid
-- for. Now it only re-syncs when the room genuinely belongs to a different tier
-- than the one the resident is on. For every category with room_source_category_id
-- NULL the source resolves to its own id, so the old behaviour is preserved
-- exactly (including an office room-transfer across tiers, which still re-syncs).
CREATE OR REPLACE FUNCTION public._on_allocation_sync_learner_categories()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_lp uuid; v_mess uuid; v_room_cat uuid; v_cur_src uuid;
BEGIN
  -- Never block an allocation write over category syncing.
  BEGIN
    SELECT learner_id INTO v_lp FROM profiles WHERE id = NEW.learner_id;
    IF v_lp IS NULL THEN RETURN NEW; END IF;
    SELECT mc.category_id INTO v_mess
    FROM fn_hostel_learner_mess_categories(v_lp) mc
    LIMIT 1;

    SELECT category_id INTO v_room_cat FROM hostel_rooms WHERE id = NEW.room_id;
    SELECT COALESCE(hc.room_source_category_id, hc.id) INTO v_cur_src
      FROM learners_profiles lp
      JOIN hostel_categories hc ON hc.id = lp.hostel_category_id
     WHERE lp.id = v_lp;

    UPDATE learners_profiles
       SET hostel_category_id = CASE
             WHEN v_cur_src IS NOT DISTINCT FROM v_room_cat THEN hostel_category_id
             ELSE v_room_cat
           END,
           mess_category_id   = COALESCE(mess_category_id, v_mess),
           updated_at = now()
     WHERE id = v_lp;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '_on_allocation_sync_learner_categories: %', SQLERRM;
  END;
  RETURN NEW;
END $function$;


CREATE OR REPLACE FUNCTION public.fn_cl_admin_room_upgrade_options(p_learner_id uuid)
RETURNS TABLE(category_id uuid, name text, type text, allocation_mode text,
              current_year_fee numeric, upgrade_fee numeric, available_beds integer,
              threshold_pct numeric, paid_pct numeric, meets_threshold boolean,
              hold_days integer, upgrade_fee_original numeric, upgrade_discount numeric)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE v_inst uuid; v_year uuid; v_cur_cat uuid; v_cur_fee numeric := 0; v_gender text; v_paid_pct numeric; v_profile uuid;
BEGIN
  IF NOT public.user_has_permission('campus_living.upgrades.manage') THEN
    RAISE EXCEPTION 'permission denied: campus_living.upgrades.manage' USING ERRCODE='42501';
  END IF;
  SELECT institution_id INTO v_inst FROM learners_profiles WHERE id = p_learner_id;
  IF v_inst IS NULL THEN RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.get_user_accessible_institutions(auth.uid()) g WHERE g.institution_id = v_inst) THEN
    RAISE EXCEPTION 'You do not have access to this learner''s institution' USING ERRCODE='42501';
  END IF;
  SELECT id INTO v_year FROM hostel_years WHERE is_current LIMIT 1;
  IF v_year IS NULL THEN RETURN; END IF;
  SELECT hostel_category_id INTO v_cur_cat FROM learners_profiles WHERE id = p_learner_id;
  SELECT p.id INTO v_profile FROM profiles p WHERE p.learner_id = p_learner_id;
  SELECT lower(trim(COALESCE(pr.gender, lp.gender))) INTO v_gender
    FROM learners_profiles lp LEFT JOIN profiles pr ON pr.learner_id = lp.id WHERE lp.id = p_learner_id;
  SELECT COALESCE(amount,0) INTO v_cur_fee FROM hostel_fees
    WHERE hostel_category_id = v_cur_cat AND hostel_year_id = v_year AND mess_category_id IS NULL AND is_active LIMIT 1;
  SELECT pp.paid_pct INTO v_paid_pct FROM fn_learner_academic_payment_progress(p_learner_id) pp;

  RETURN QUERY
  SELECT c.id, c.name, c.type, c.allocation_mode, hf.amount,
         COALESCE(
           (SELECT uf.net_amount FROM hostel_category_upgrade_fees uf
            WHERE uf.hostel_year_id = v_year AND uf.is_active
              AND uf.from_hostel_category_id = v_cur_cat AND uf.to_hostel_category_id = c.id LIMIT 1),
           hf.amount - v_cur_fee) AS upgrade_fee,
         (SELECT count(*)::int FROM _cl_room_options(v_profile, p_learner_id, c.id)),
         c.upgrade_threshold_pct,
         v_paid_pct,
         (c.upgrade_threshold_pct IS NULL OR (v_paid_pct IS NOT NULL AND v_paid_pct >= c.upgrade_threshold_pct)),
         c.upgrade_hold_days,
         COALESCE(
           (SELECT uf.amount FROM hostel_category_upgrade_fees uf
            WHERE uf.hostel_year_id = v_year AND uf.is_active
              AND uf.from_hostel_category_id = v_cur_cat AND uf.to_hostel_category_id = c.id LIMIT 1),
           hf.amount - v_cur_fee) AS upgrade_fee_original,
         COALESCE(
           (SELECT uf.amount - uf.net_amount FROM hostel_category_upgrade_fees uf
            WHERE uf.hostel_year_id = v_year AND uf.is_active
              AND uf.from_hostel_category_id = v_cur_cat AND uf.to_hostel_category_id = c.id LIMIT 1),
           0) AS upgrade_discount
  FROM hostel_categories c
  JOIN hostel_fees hf ON hf.hostel_category_id = c.id AND hf.hostel_year_id = v_year AND hf.mess_category_id IS NULL AND hf.is_active
  WHERE c.is_active AND c.allocation_mode = 'manual'
    AND ((v_gender IN ('male','m') AND c.type='boys') OR (v_gender IN ('female','f') AND c.type='girls'))
    AND c.id <> COALESCE(v_cur_cat, '00000000-0000-0000-0000-000000000000'::uuid)
    AND hf.amount > v_cur_fee
    -- Same curated-ladder gate the resident sees.
    AND (NOT c.requires_explicit_upgrade
         OR EXISTS (SELECT 1 FROM hostel_category_upgrade_fees uf2
                    WHERE uf2.hostel_year_id = v_year AND uf2.is_active
                      AND uf2.from_hostel_category_id = v_cur_cat
                      AND uf2.to_hostel_category_id = c.id))
  ORDER BY hf.amount;
END $function$;

-- Bulk / single admin upgrade evaluator: refuse an unconfigured pair outright.
CREATE OR REPLACE FUNCTION public._cl_admin_eval_room_upgrade(p_lp uuid, p_target_category_id uuid)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_year uuid; v_gender text; v_gtype text;
  v_cur_cat uuid; v_cur_name text; v_cur_fee numeric := 0;
  v_t_name text; v_t_type text; v_t_mode text; v_t_active boolean; v_t_thr numeric;
  v_t_explicit boolean;
  v_new_fee numeric; v_upg numeric; v_gross numeric; v_paid numeric; v_meets boolean;
BEGIN
  SELECT id INTO v_year FROM hostel_years WHERE is_current LIMIT 1;
  IF v_year IS NULL THEN RETURN jsonb_build_object('eligible', false, 'reason', 'No current hostel year configured'); END IF;

  SELECT lower(trim(COALESCE(pr.gender, lp.gender))) INTO v_gender
    FROM learners_profiles lp LEFT JOIN profiles pr ON pr.learner_id = lp.id WHERE lp.id = p_lp;
  v_gtype := CASE WHEN v_gender IN ('male','m') THEN 'boys'
                  WHEN v_gender IN ('female','f') THEN 'girls' ELSE NULL END;

  SELECT name, type, allocation_mode, is_active, upgrade_threshold_pct, requires_explicit_upgrade
    INTO v_t_name, v_t_type, v_t_mode, v_t_active, v_t_thr, v_t_explicit
    FROM hostel_categories WHERE id = p_target_category_id;
  IF v_t_name IS NULL OR NOT v_t_active THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Target category not found or inactive');
  END IF;
  IF v_t_mode IS DISTINCT FROM 'auto' THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Manual category -- upgrade this learner individually with a room selection',
      'target_category_id', p_target_category_id, 'target_category_name', v_t_name);
  END IF;
  IF v_gtype IS NULL OR v_t_type IS DISTINCT FROM v_gtype THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Category does not match learner gender',
      'target_category_id', p_target_category_id, 'target_category_name', v_t_name);
  END IF;

  SELECT amount INTO v_new_fee FROM hostel_fees
    WHERE hostel_category_id = p_target_category_id AND hostel_year_id = v_year AND mess_category_id IS NULL AND is_active LIMIT 1;
  IF v_new_fee IS NULL THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Target has no published fee for the current hostel year',
      'target_category_id', p_target_category_id, 'target_category_name', v_t_name);
  END IF;

  SELECT hostel_category_id INTO v_cur_cat FROM learners_profiles WHERE id = p_lp;
  SELECT name INTO v_cur_name FROM hostel_categories WHERE id = v_cur_cat;
  SELECT COALESCE(amount,0) INTO v_cur_fee FROM hostel_fees
    WHERE hostel_category_id = v_cur_cat AND hostel_year_id = v_year AND mess_category_id IS NULL AND is_active LIMIT 1;

  IF v_cur_cat = p_target_category_id THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Already on this category',
      'current_category_id', v_cur_cat, 'current_category_name', v_cur_name,
      'target_category_id', p_target_category_id, 'target_category_name', v_t_name);
  END IF;
  IF v_new_fee <= v_cur_fee THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Not an upgrade (target fee <= current fee)',
      'current_category_id', v_cur_cat, 'current_category_name', v_cur_name,
      'target_category_id', p_target_category_id, 'target_category_name', v_t_name);
  END IF;

  SELECT uf.net_amount, uf.amount INTO v_upg, v_gross FROM hostel_category_upgrade_fees uf
    WHERE uf.hostel_year_id = v_year AND uf.is_active
      AND uf.from_hostel_category_id = v_cur_cat AND uf.to_hostel_category_id = p_target_category_id LIMIT 1;

  -- Curated ladder: an explicit-only target is reachable ONLY from a configured source.
  IF COALESCE(v_t_explicit, false) AND v_upg IS NULL THEN
    RETURN jsonb_build_object('eligible', false,
      'reason', format('No configured upgrade path from %s to %s (Campus Living > Settings > Fee Config > Upgrade Fee)',
                       COALESCE(v_cur_name,'-'), v_t_name),
      'current_category_id', v_cur_cat, 'current_category_name', v_cur_name,
      'target_category_id', p_target_category_id, 'target_category_name', v_t_name);
  END IF;

  IF v_upg IS NULL THEN
    v_upg := v_new_fee - v_cur_fee;
    v_gross := v_upg;
  END IF;

  SELECT pp.paid_pct INTO v_paid FROM fn_learner_academic_payment_progress(p_lp) pp;
  v_meets := (v_t_thr IS NULL) OR (v_paid IS NOT NULL AND v_paid >= v_t_thr);

  RETURN jsonb_build_object(
    'eligible', true, 'reason', NULL,
    'current_category_id', v_cur_cat, 'current_category_name', v_cur_name,
    'target_category_id', p_target_category_id, 'target_category_name', v_t_name,
    'current_fee', v_cur_fee, 'target_fee', v_new_fee, 'upgrade_fee', v_upg,
    'upgrade_fee_original', v_gross, 'upgrade_discount', v_gross - v_upg,
    'threshold_pct', v_t_thr, 'paid_pct', v_paid, 'meets_threshold', v_meets);
END $function$;


-- ============================================================================
-- Campus Living: per-pair skip_room_eligibility (migration 20260807170000)
-- Supersedes the three room/bed loaders above. A configured upgrade pair may
-- now ignore hostel_room_eligibility_rules (Deluxe -> Deluxe Plus,
-- Premium -> Premium + AC). fn_room_serves_institution, gender and bed
-- availability are still enforced.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.fn_my_room_options(p_category_id uuid)
RETURNS TABLE(bed_id uuid, room_id uuid, room_number text, floor integer, block_name text, bed_number text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_lp uuid := get_my_learner_id();
  v_inst uuid; v_gender text; v_src uuid; v_cur_cat uuid; v_year uuid; v_skip boolean := false;
BEGIN
  IF v_lp IS NULL THEN RETURN; END IF;
  -- A "Plus" tier has no rooms of its own; resolve to the pool it sells from.
  SELECT COALESCE(room_source_category_id, id) INTO v_src
    FROM hostel_categories WHERE id = p_category_id;
  IF v_src IS NULL THEN RETURN; END IF;
  SELECT institution_id, hostel_category_id INTO v_inst, v_cur_cat FROM learners_profiles WHERE id=v_lp;
  SELECT lower(trim(COALESCE(pr.gender, lp.gender))) INTO v_gender
    FROM profiles pr LEFT JOIN learners_profiles lp ON lp.id = pr.learner_id
   WHERE pr.id = auth.uid();
  SELECT id INTO v_year FROM hostel_years WHERE is_current LIMIT 1;
  SELECT COALESCE(bool_or(uf.skip_room_eligibility), false) INTO v_skip
    FROM hostel_category_upgrade_fees uf
   WHERE uf.hostel_year_id = v_year AND uf.is_active
     AND uf.from_hostel_category_id = v_cur_cat
     AND uf.to_hostel_category_id   = p_category_id;
  RETURN QUERY
  SELECT b.id, r.id, r.room_number, r.floor, bl.name, b.bed_number
  FROM hostel_beds b
  JOIN hostel_rooms r ON r.id=b.room_id
  JOIN hostel_blocks bl ON bl.id=r.block_id
  WHERE r.category_id=v_src AND r.room_purpose='student' AND b.status='available'
    AND (bl.hostel_type::text='mixed'
         OR (v_gender IN ('male','m')   AND bl.hostel_type::text='boys')
         OR (v_gender IN ('female','f') AND bl.hostel_type::text='girls'))
    AND fn_room_serves_institution(r.id, v_inst)
    AND NOT EXISTS (SELECT 1 FROM hostel_allocations a WHERE a.bed_id=b.id AND a.status IN ('active','pending_approval'))
    AND (v_skip OR fn_learner_eligible_for_room(v_lp, r.id))
  ORDER BY bl.name, r.floor, r.room_number, b.bed_number;
END $function$;

CREATE OR REPLACE FUNCTION public.fn_my_upgrade_room_options(p_category_id uuid)
RETURNS TABLE(room_id uuid, room_number text, floor integer, block_name text, capacity integer, occupied_beds integer, available_beds integer)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_lp uuid := get_my_learner_id();
  v_inst uuid; v_gender text; v_src uuid; v_cur_cat uuid; v_year uuid; v_skip boolean := false;
BEGIN
  IF v_lp IS NULL THEN RETURN; END IF;
  SELECT COALESCE(room_source_category_id, id) INTO v_src
    FROM hostel_categories WHERE id = p_category_id;
  IF v_src IS NULL THEN RETURN; END IF;
  SELECT institution_id, hostel_category_id INTO v_inst, v_cur_cat FROM learners_profiles WHERE id = v_lp;
  SELECT lower(trim(COALESCE(pr.gender, lp.gender))) INTO v_gender
    FROM profiles pr LEFT JOIN learners_profiles lp ON lp.id = pr.learner_id
   WHERE pr.id = auth.uid();
  SELECT id INTO v_year FROM hostel_years WHERE is_current LIMIT 1;
  SELECT COALESCE(bool_or(uf.skip_room_eligibility), false) INTO v_skip
    FROM hostel_category_upgrade_fees uf
   WHERE uf.hostel_year_id = v_year AND uf.is_active
     AND uf.from_hostel_category_id = v_cur_cat
     AND uf.to_hostel_category_id   = p_category_id;
  RETURN QUERY
  SELECT r.id, r.room_number, r.floor, bl.name,
         COALESCE(r.actual_capacity, r.capacity)::int,
         GREATEST(COALESCE(r.actual_capacity, r.capacity)::int - av.free, 0),
         av.free
  FROM hostel_rooms r
  JOIN hostel_blocks bl ON bl.id = r.block_id
  CROSS JOIN LATERAL (
    SELECT count(*)::int AS free
    FROM hostel_beds b
    WHERE b.room_id = r.id AND b.status = 'available'
      AND NOT EXISTS (
        SELECT 1 FROM hostel_allocations a
        WHERE a.bed_id = b.id AND a.status IN ('active','pending_approval')
      )
  ) av
  WHERE r.category_id = v_src AND r.room_purpose = 'student'
    AND (bl.hostel_type::text = 'mixed'
         OR (v_gender IN ('male','m')   AND bl.hostel_type::text = 'boys')
         OR (v_gender IN ('female','f') AND bl.hostel_type::text = 'girls'))
    AND fn_room_serves_institution(r.id, v_inst)
    AND (v_skip OR fn_learner_eligible_for_room(v_lp, r.id))
    AND av.free > 0
  ORDER BY bl.name, r.floor, r.room_number;
END $function$;

CREATE OR REPLACE FUNCTION public._cl_room_options(p_profile uuid, p_lp uuid, p_category_id uuid)
RETURNS TABLE(bed_id uuid, room_id uuid, room_number text, floor integer, block_name text, bed_number text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_inst uuid; v_gender text; v_src uuid; v_cur_cat uuid; v_year uuid; v_skip boolean := false;
BEGIN
  IF p_lp IS NULL THEN RETURN; END IF;
  SELECT COALESCE(room_source_category_id, id) INTO v_src
    FROM hostel_categories WHERE id = p_category_id;
  IF v_src IS NULL THEN RETURN; END IF;
  SELECT institution_id, hostel_category_id INTO v_inst, v_cur_cat FROM learners_profiles WHERE id = p_lp;
  SELECT lower(trim(COALESCE(pr.gender, lp.gender))) INTO v_gender
    FROM learners_profiles lp LEFT JOIN profiles pr ON pr.id = p_profile WHERE lp.id = p_lp;
  SELECT id INTO v_year FROM hostel_years WHERE is_current LIMIT 1;
  SELECT COALESCE(bool_or(uf.skip_room_eligibility), false) INTO v_skip
    FROM hostel_category_upgrade_fees uf
   WHERE uf.hostel_year_id = v_year AND uf.is_active
     AND uf.from_hostel_category_id = v_cur_cat
     AND uf.to_hostel_category_id   = p_category_id;
  RETURN QUERY
  SELECT b.id, r.id, r.room_number, r.floor, bl.name, b.bed_number
  FROM hostel_beds b
  JOIN hostel_rooms r ON r.id = b.room_id
  JOIN hostel_blocks bl ON bl.id = r.block_id
  WHERE r.category_id = v_src AND r.room_purpose = 'student' AND b.status = 'available'
    AND (bl.hostel_type::text = 'mixed'
         OR (v_gender IN ('male','m')   AND bl.hostel_type::text = 'boys')
         OR (v_gender IN ('female','f') AND bl.hostel_type::text = 'girls'))
    AND fn_room_serves_institution(r.id, v_inst)
    AND NOT EXISTS (SELECT 1 FROM hostel_allocations a WHERE a.bed_id = b.id AND a.status IN ('active','pending_approval'))
    AND (v_skip OR fn_learner_eligible_for_room(p_lp, r.id))
  ORDER BY bl.name, r.floor, r.room_number, b.bed_number;
END $function$;


-- ============================================================================
-- Campus Living: ONE-TIME self-service room change (migration 20260807180000)
-- Same category, different room. No category change, no bill. The allowance is
-- recorded on the new allocation as metadata->>'self_room_change', so the
-- audit trail IS the counter. Gated by hostel_categories.allow_self_room_change.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.fn_my_room_change_status()
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_lp uuid := get_my_learner_id(); v_profile uuid := auth.uid();
  v_cat uuid; v_cat_name text; v_allow boolean := false;
  v_alloc RECORD; v_used boolean := false; v_rooms int := 0;
BEGIN
  IF v_lp IS NULL OR v_profile IS NULL OR NOT user_is_hosteler() THEN
    RETURN jsonb_build_object('allowed', false, 'used', false, 'reason', 'not_resident');
  END IF;

  SELECT hostel_category_id INTO v_cat FROM learners_profiles WHERE id = v_lp;
  SELECT name, allow_self_room_change INTO v_cat_name, v_allow
    FROM hostel_categories WHERE id = v_cat;
  IF NOT COALESCE(v_allow, false) THEN
    RETURN jsonb_build_object('allowed', false, 'used', false,
      'reason', 'category_not_eligible', 'category_name', v_cat_name);
  END IF;

  SELECT ha.id, ha.room_id, ha.bed_id, ha.academic_year_id,
         r.room_number, r.floor, bl.name AS block_name, bd.bed_number
    INTO v_alloc
    FROM hostel_allocations ha
    JOIN hostel_rooms  r  ON r.id  = ha.room_id
    JOIN hostel_blocks bl ON bl.id = r.block_id
    JOIN hostel_beds   bd ON bd.id = ha.bed_id
   WHERE ha.learner_id = v_profile AND ha.status = 'active'
   ORDER BY ha.allocation_date DESC LIMIT 1;
  IF v_alloc.id IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'used', false,
      'reason', 'no_allocation', 'category_name', v_cat_name);
  END IF;

  -- The audit trail is the counter: one tagged allocation per academic year.
  v_used := EXISTS (
    SELECT 1 FROM hostel_allocations ha
     WHERE ha.learner_id = v_profile
       AND ha.academic_year_id = v_alloc.academic_year_id
       AND ha.metadata->>'self_room_change' = 'true');

  SELECT count(DISTINCT o.room_id) INTO v_rooms
    FROM _cl_room_options(v_profile, v_lp, v_cat) o
   WHERE o.room_id <> v_alloc.room_id;

  RETURN jsonb_build_object(
    'allowed', (NOT v_used AND v_rooms > 0),
    'used', v_used,
    'reason', CASE WHEN v_used THEN 'already_used'
                   WHEN v_rooms = 0 THEN 'no_rooms'
                   ELSE NULL END,
    'category_name', v_cat_name,
    'available_rooms', v_rooms,
    'current_room_number', v_alloc.room_number,
    'current_block_name', v_alloc.block_name,
    'current_bed_number', v_alloc.bed_number,
    'current_floor', v_alloc.floor);
END $function$;

REVOKE EXECUTE ON FUNCTION public.fn_my_room_change_status() FROM PUBLIC, anon;
GRANT  EXECUTE ON FUNCTION public.fn_my_room_change_status() TO authenticated, service_role;

-- 3) Options — same category only, current room excluded ----------------------
-- Delegates to fn_my_upgrade_room_options so the gender / institution / eligibility /
-- availability rules stay defined in exactly ONE place. auth.uid() survives the nested
-- SECURITY DEFINER call (it reads session JWT claims, not the executing role).
CREATE OR REPLACE FUNCTION public.fn_my_room_change_options()
RETURNS TABLE(room_id uuid, room_number text, floor integer, block_name text,
              capacity integer, occupied_beds integer, available_beds integer)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_lp uuid := get_my_learner_id(); v_profile uuid := auth.uid();
  v_cat uuid; v_cur_room uuid; v_allow boolean := false; v_ay uuid;
BEGIN
  IF v_lp IS NULL OR v_profile IS NULL OR NOT user_is_hosteler() THEN RETURN; END IF;
  SELECT hostel_category_id INTO v_cat FROM learners_profiles WHERE id = v_lp;
  SELECT allow_self_room_change INTO v_allow FROM hostel_categories WHERE id = v_cat;
  IF NOT COALESCE(v_allow, false) THEN RETURN; END IF;

  SELECT ha.room_id, ha.academic_year_id INTO v_cur_room, v_ay
    FROM hostel_allocations ha
   WHERE ha.learner_id = v_profile AND ha.status = 'active'
   ORDER BY ha.allocation_date DESC LIMIT 1;
  IF v_cur_room IS NULL THEN RETURN; END IF;

  -- Do not enumerate rooms once the single allowance is spent.
  IF EXISTS (SELECT 1 FROM hostel_allocations ha
              WHERE ha.learner_id = v_profile AND ha.academic_year_id = v_ay
                AND ha.metadata->>'self_room_change' = 'true') THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT o.room_id, o.room_number, o.floor, o.block_name,
         o.capacity, o.occupied_beds, o.available_beds
  FROM fn_my_upgrade_room_options(v_cat) o
  WHERE o.room_id <> v_cur_room;
END $function$;

REVOKE EXECUTE ON FUNCTION public.fn_my_room_change_options() FROM PUBLIC, anon;
GRANT  EXECUTE ON FUNCTION public.fn_my_room_change_options() TO authenticated, service_role;

-- 4) Execute — vacate the old bed, occupy the new one, spend the allowance -----
CREATE OR REPLACE FUNCTION public.fn_self_change_room(p_room_id uuid, p_bed_id uuid DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_lp uuid := get_my_learner_id(); v_profile uuid := auth.uid();
  v_cat uuid; v_allow boolean := false; v_old RECORD; v_new_alloc uuid;
  v_bed_status text; v_new_room RECORD;
BEGIN
  IF v_lp IS NULL OR v_profile IS NULL OR NOT user_is_hosteler() THEN
    RAISE EXCEPTION 'Only a hostel resident can change their room';
  END IF;

  SELECT hostel_category_id INTO v_cat FROM learners_profiles WHERE id = v_lp;
  SELECT allow_self_room_change INTO v_allow FROM hostel_categories WHERE id = v_cat;
  IF NOT COALESCE(v_allow, false) THEN
    RAISE EXCEPTION 'Room change is not available for your category';
  END IF;

  SELECT ha.id, ha.room_id, ha.bed_id, ha.tier_id, ha.academic_year_id, ha.semester_id,
         ha.institution_id, ha.batch_id, ha.emergency_contact_name,
         ha.emergency_contact_phone, ha.emergency_contact_relation
    INTO v_old
    FROM hostel_allocations ha
   WHERE ha.learner_id = v_profile AND ha.status = 'active'
   ORDER BY ha.allocation_date DESC LIMIT 1;
  IF v_old.id IS NULL THEN RAISE EXCEPTION 'You have no active allocation to change'; END IF;

  IF EXISTS (SELECT 1 FROM hostel_allocations ha
              WHERE ha.learner_id = v_profile AND ha.academic_year_id = v_old.academic_year_id
                AND ha.metadata->>'self_room_change' = 'true') THEN
    RAISE EXCEPTION 'You have already used your one room change for this academic year';
  END IF;

  IF p_room_id = v_old.room_id THEN
    RAISE EXCEPTION 'That is already your room. Pick a different one.';
  END IF;

  -- Same-category guard. _cl_room_options is scoped to v_cat, so a room outside the
  -- resident's own category can never validate below — this only makes the failure loud.
  SELECT r.id, r.room_number, r.block_id, r.category_id INTO v_new_room
    FROM hostel_rooms r WHERE r.id = p_room_id;
  IF v_new_room.id IS NULL
     OR v_new_room.category_id IS DISTINCT FROM
        (SELECT COALESCE(room_source_category_id, id) FROM hostel_categories WHERE id = v_cat) THEN
    RAISE EXCEPTION 'You can only move to another room in your own category';
  END IF;

  IF p_bed_id IS NULL THEN
    SELECT o.bed_id INTO p_bed_id
      FROM _cl_room_options(v_profile, v_lp, v_cat) o
     WHERE o.room_id = p_room_id ORDER BY o.bed_number LIMIT 1;
    IF p_bed_id IS NULL THEN RAISE EXCEPTION 'No available bed left in that room. Pick another room.'; END IF;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM _cl_room_options(v_profile, v_lp, v_cat) o
                  WHERE o.bed_id = p_bed_id AND o.room_id = p_room_id) THEN
    RAISE EXCEPTION 'That room/bed is not an available option for you';
  END IF;

  IF NOT pg_try_advisory_xact_lock(hashtext(p_bed_id::text)) THEN
    RAISE EXCEPTION 'Another resident is claiming this bed. Try again.';
  END IF;
  SELECT status INTO v_bed_status FROM hostel_beds WHERE id = p_bed_id AND room_id = p_room_id;
  IF v_bed_status IS DISTINCT FROM 'available' THEN
    RAISE EXCEPTION 'That bed is no longer available';
  END IF;

  -- 2026-08-06: check_out_date is what hostel_allocations_room_bed_active_uidx reads.
  -- Without it the vacated row keeps reserving (room_id, bed_id) and the old bed can
  -- never be re-used, even though hostel_beds says 'available'.
  UPDATE hostel_allocations
     SET status='vacated', actual_vacate_date=CURRENT_DATE,
         check_out_date=CURRENT_DATE, updated_at=now()
   WHERE id = v_old.id;
  UPDATE hostel_beds SET status='available', current_occupant_id=NULL WHERE id = v_old.bed_id;

-- Reserved-bed allocation guard (mig 20260815040001_reserved_bed_guard.sql —
-- FILE ONLY, apply is Director-gated). Director's rule, 2026-08-07: a bed
-- held for one learner's confirmed upgrade hold (hostel_beds.status=
-- 'reserved', hostel_waitlist.held_bed_id) must never reach a different
-- learner. SECURITY DEFINER is load-bearing — a plain trigger would run
-- under the INSERTing learner's own RLS, which may hide every OTHER
-- learner's hostel_waitlist row, and the guard would silently pass. See the
-- migration file for the full 13-function audit this backstops.
CREATE OR REPLACE FUNCTION public._on_allocation_guard_reserved_bed()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_bed_status   bed_status_enum;
  v_hold_learner uuid;
BEGIN
  SELECT status INTO v_bed_status FROM hostel_beds WHERE id = NEW.bed_id;

  IF v_bed_status = 'reserved' THEN
    -- The learner whose ACTIVE waiting hold points at this exact bed
    -- (entry_kind='upgrade' AND status='waiting'). The functions that
    -- execute a hold flip this row to 'allocated' AFTER the INSERT into
    -- hostel_allocations, so at this BEFORE-trigger's evaluation time the
    -- holder's own row still reads 'waiting' — her own execution passes.
    SELECT learner_id INTO v_hold_learner
      FROM hostel_waitlist
      WHERE held_bed_id = NEW.bed_id
        AND entry_kind = 'upgrade'
        AND status = 'waiting'
      ORDER BY updated_at DESC
      LIMIT 1;

    -- No live hold at all (stale 'reserved') refuses too, for anyone —
    -- v_hold_learner is NULL, and NULL IS DISTINCT FROM any learner_id.
    IF v_hold_learner IS DISTINCT FROM NEW.learner_id THEN
      RAISE EXCEPTION 'This bed is reserved for another learner''s confirmed upgrade'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;

-- No GRANT TO authenticated on purpose: no legitimate direct caller, only
-- the trigger in 04_triggers.sql. Asserted anyway per the CLAUDE.md
-- "every CREATE OR REPLACE of a SECDEF fn re-asserts REVOKE" rule.
REVOKE EXECUTE ON FUNCTION public._on_allocation_guard_reserved_bed() FROM anon, PUBLIC;

-- Updated: 2026-08-07 — fn_cl_admin_allocate_bed SUPERSEDES the earlier definition above.
-- Source: supabase/migrations/20260815040001_reserved_bed_guard.sql. Adds the reserved-bed
-- pre-check so the admin allocate RPC refuses a bed held for another learner with a plain
-- message (the BEFORE INSERT trigger enforces the same invariant independently).

-- ============ 2. fn_cl_admin_allocate_bed — close the one genuine gap ======
-- Rebuilt VERBATIM from the live pg_get_functiondef dump (2026-08-07 ~09:40
-- IST, 96 lines). Only the bed-status check block is new (+9 lines); every
-- other line, including the authorization check, the fresh-only guard, the
-- institution-access mirror and the tier-policy fallback, is unchanged.

CREATE OR REPLACE FUNCTION public.fn_cl_admin_allocate_bed(p_learner_profile_id uuid, p_room_id uuid, p_bed_id uuid, p_mess_category_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_room       hostel_rooms%ROWTYPE;
  v_bed        hostel_beds%ROWTYPE;
  v_profile    uuid;
  v_inst       uuid;
  v_sem        uuid;
  v_ay         uuid;
  v_tier       uuid;
  v_block      uuid;
  v_mapped     boolean;
  v_accessible boolean;
  v_alloc_id   uuid;
BEGIN
  IF NOT (is_super_admin() OR user_has_permission('campus_living.upgrades.manage')) THEN
    RAISE EXCEPTION 'Not authorized to allocate hostel rooms' USING ERRCODE = '42501';
  END IF;

  -- learners_profiles → institution / semester / academic year (mirror auto-allocate fallback)
  SELECT lp.institution_id, lp.semester_id,
         COALESCE(lp.academic_year_id,
           (SELECT id FROM academic_years
             WHERE institution_id = lp.institution_id AND is_active
             ORDER BY start_date DESC LIMIT 1))
    INTO v_inst, v_sem, v_ay
  FROM learners_profiles lp WHERE lp.id = p_learner_profile_id;
  IF v_inst IS NULL THEN RAISE EXCEPTION 'Learner % not found', p_learner_profile_id USING ERRCODE = 'P0002'; END IF;
  IF v_ay IS NULL THEN RAISE EXCEPTION 'No academic year resolved for this learner' USING ERRCODE = 'P0001'; END IF;

  -- bridge to the profiles.id key hostel_allocations uses
  SELECT id INTO v_profile FROM profiles WHERE learner_id = p_learner_profile_id LIMIT 1;
  IF v_profile IS NULL THEN RAISE EXCEPTION 'No profile bridges learner %', p_learner_profile_id USING ERRCODE = 'P0002'; END IF;

  -- fresh-only
  IF EXISTS (SELECT 1 FROM hostel_allocations a
             WHERE a.learner_id = v_profile AND a.status IN ('active','pending_approval') AND a.check_out_date IS NULL) THEN
    RAISE EXCEPTION 'Learner already has an active allocation — use Change room/bed instead' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO v_room FROM hostel_rooms WHERE id = p_room_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Room % not found', p_room_id USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO v_bed FROM hostel_beds WHERE id = p_bed_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Bed % not found', p_bed_id USING ERRCODE = 'P0002'; END IF;
  IF v_bed.room_id <> p_room_id THEN RAISE EXCEPTION 'Bed does not belong to the selected room' USING ERRCODE = 'P0001'; END IF;

  -- 2026-08-15: a bed reserved for another learner's confirmed upgrade hold
  -- must never be handed to a fresh allocation here. This path is
  -- fresh-only (checked above), and a learner with zero prior allocations
  -- cannot legitimately be the holder of a reserved bed's upgrade hold — so
  -- requiring 'available' costs no real path. trg_allocation_guard_reserved_bed
  -- on hostel_allocations is the backstop for every writer; this explicit
  -- check exists only so the admin UI gets a clean refusal here instead of a
  -- raw trigger exception.
  IF v_bed.status = 'reserved' THEN
    RAISE EXCEPTION 'This bed is reserved for another learner''s confirmed upgrade' USING ERRCODE = 'P0001';
  END IF;

  v_block := v_room.block_id;

  -- institution access (mirror fn_cl_admin_transfer_allocation)
  SELECT EXISTS (SELECT 1 FROM hostel_block_institutions WHERE block_id = v_block) INTO v_mapped;
  IF v_mapped THEN
    SELECT EXISTS (
      SELECT 1 FROM hostel_block_institutions hbi
      WHERE hbi.block_id = v_block
        AND hbi.institution_id IN (SELECT institution_id FROM get_user_accessible_institutions(auth.uid()))
    ) INTO v_accessible;
    IF NOT v_accessible THEN RAISE EXCEPTION 'No access to the target block''s institution' USING ERRCODE = '42501'; END IF;
  END IF;

  -- bed must be free (dedup on allocation existence, matching auto-allocate)
  IF EXISTS (SELECT 1 FROM hostel_allocations a
             WHERE a.bed_id = p_bed_id AND a.status IN ('active','pending_approval') AND a.check_out_date IS NULL) THEN
    RAISE EXCEPTION 'The selected bed is already occupied' USING ERRCODE = '23505';
  END IF;

  -- standard tier policy (mirror auto-allocate)
  SELECT id INTO v_tier FROM hostel_tier_policy WHERE tier_key='standard' AND institution_id IS NULL AND is_active LIMIT 1;
  IF v_tier IS NULL THEN SELECT id INTO v_tier FROM hostel_tier_policy WHERE tier_key='standard' AND is_active LIMIT 1; END IF;
  IF v_tier IS NULL THEN RAISE EXCEPTION 'No standard tier policy found' USING ERRCODE = 'P0001'; END IF;

  INSERT INTO hostel_allocations (
    institution_id, learner_id, block_id, room_id, bed_id, academic_year_id, semester_id,
    allocation_type, allocation_date, status,
    emergency_contact_name, emergency_contact_phone, emergency_contact_relation,
    tier_id, allocated_by, batch_id, metadata
  ) VALUES (
    v_old.institution_id, v_profile, v_new_room.block_id, p_room_id, p_bed_id,
    v_old.academic_year_id, v_old.semester_id, 'transfer', CURRENT_DATE, 'active',
    v_old.emergency_contact_name, v_old.emergency_contact_phone, v_old.emergency_contact_relation,
    v_old.tier_id, v_profile, v_old.batch_id,
    jsonb_build_object('self_room_change', true,
                       'from_room_id', v_old.room_id,
                       'from_bed_id',  v_old.bed_id,
                       'changed_at',   to_jsonb(now()))
  ) RETURNING id INTO v_new_alloc;
  UPDATE hostel_beds SET status='occupied', current_occupant_id=v_profile WHERE id = p_bed_id;

  RETURN jsonb_build_object('success', true,
    'old_allocation_id', v_old.id, 'new_allocation_id', v_new_alloc,
    'old_room_id', v_old.room_id, 'new_room_id', p_room_id,
    'new_bed_id', p_bed_id, 'new_room_number', v_new_room.room_number);
END $function$;

REVOKE EXECUTE ON FUNCTION public.fn_self_change_room(uuid, uuid) FROM PUBLIC, anon;
GRANT  EXECUTE ON FUNCTION public.fn_self_change_room(uuid, uuid) TO authenticated, service_role;

-- ── Room deletion (2026-08-07) ──────────────────────────────────────────────
-- hostel_allocations_room_id_fkey is NO ACTION, so a bare DELETE on
-- hostel_rooms raises 23503 for any room that has EVER been allocated — even
-- when v_hostel_room_occupancy reports zero residents. This RPC takes the
-- room's own history with it and blocks only on records that outlive a room.
CREATE OR REPLACE FUNCTION public.fn_delete_hostel_room(p_room_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_block_id    uuid;
  v_room_number text;
  v_occupants   integer;
  v_deposits    integer;
  v_vacate_reqs integer;
  v_open_maint  integer;
  v_allocs      integer;
  v_maint       integer;
  v_cleaning    integer;
BEGIN
  SELECT block_id, room_number
    INTO v_block_id, v_room_number
  FROM hostel_rooms
  WHERE id = p_room_id;

  IF v_block_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'not_found',
      'message', 'This room no longer exists.'
    );
  END IF;

  -- SECURITY DEFINER bypasses RLS, so re-assert hostel_rooms_delete_permission.
  IF NOT (
    is_super_admin()
    OR is_admin()
    OR (
      user_has_permission('campus_living.rooms.delete')
      AND (fn_user_can_access_room(p_room_id) OR role_has_block_access(v_block_id))
    )
  ) THEN
    RAISE EXCEPTION 'Not authorized to delete room %', v_room_number
      USING ERRCODE = '42501';
  END IF;

  -- Mirrors v_hostel_room_occupancy.active_residents (check_out_date IS NULL),
  -- deliberately NOT status = 'active' — if the two drift, the operator would
  -- see "available" and still be refused.
  SELECT count(*) INTO v_occupants
  FROM hostel_allocations
  WHERE room_id = p_room_id
    AND check_out_date IS NULL;

  IF v_occupants > 0 THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'active_residents', 'count', v_occupants,
      'message', format(
        'Room %s still has %s resident%s. Move them out before deleting the room.',
        v_room_number, v_occupants, CASE WHEN v_occupants = 1 THEN '' ELSE 's' END)
    );
  END IF;

  SELECT count(*) INTO v_deposits
  FROM hostel_deposits d
  JOIN hostel_allocations a ON a.id = d.allocation_id
  WHERE a.room_id = p_room_id;

  IF v_deposits > 0 THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'has_deposits', 'count', v_deposits,
      'message', format(
        'Room %s has %s deposit record%s from past stays. Settle or reassign them before deleting the room.',
        v_room_number, v_deposits, CASE WHEN v_deposits = 1 THEN '' ELSE 's' END)
    );
  END IF;

  SELECT count(*) INTO v_vacate_reqs
  FROM hostel_vacate_requests v
  JOIN hostel_allocations a ON a.id = v.allocation_id
  WHERE a.room_id = p_room_id;

  IF v_vacate_reqs > 0 THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'has_vacate_requests', 'count', v_vacate_reqs,
      'message', format(
        'Room %s has %s vacate request%s on file. Close them before deleting the room.',
        v_room_number, v_vacate_reqs, CASE WHEN v_vacate_reqs = 1 THEN '' ELSE 's' END)
    );
  END IF;

  SELECT count(*) INTO v_open_maint
  FROM hostel_maintenance_requests
  WHERE room_id = p_room_id
    AND status NOT IN ('resolved', 'closed');

  IF v_open_maint > 0 THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'open_maintenance', 'count', v_open_maint,
      'message', format(
        'Room %s has %s open maintenance request%s. Close them before deleting the room.',
        v_room_number, v_open_maint, CASE WHEN v_open_maint = 1 THEN '' ELSE 's' END)
    );
  END IF;

  DELETE FROM hostel_cleaning_bookings WHERE room_id = p_room_id;
  GET DIAGNOSTICS v_cleaning = ROW_COUNT;

  DELETE FROM hostel_maintenance_requests WHERE room_id = p_room_id;
  GET DIAGNOSTICS v_maint = ROW_COUNT;

  DELETE FROM hostel_allocations WHERE room_id = p_room_id;
  GET DIAGNOSTICS v_allocs = ROW_COUNT;

  DELETE FROM hostel_rooms WHERE id = p_room_id;

  RETURN jsonb_build_object(
    'ok', true,
    'room_number', v_room_number,
    'purged_allocations', v_allocs,
    'purged_maintenance', v_maint,
    'purged_cleaning', v_cleaning
  );
END;
$function$;

REVOKE ALL   ON FUNCTION public.fn_delete_hostel_room(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fn_delete_hostel_room(uuid) TO authenticated;

-- Updated: 2026-08-07 - Late-payment charge: "waive whole bill" in one action
-- Source: supabase/migrations/20260815030001_late_charge_waive_bill.sql
-- NOT APPLIED — FILE ONLY, apply is Director-gated. Director decision
-- (edge-case interview, 2026-08-07): a bigger brush alongside
-- fn_late_charge_waive (kept untouched, unchanged above) — one action that
-- forgives every late charge on a single bill. Each row is waived by
-- PERFORM-ing fn_late_charge_waive itself, so the two waivers can never
-- drift apart in behaviour.
-- -----------------------------------------------------------------------------
-- fn_late_charge_waive_bill — waive EVERY not-yet-waived late charge on one
-- bill. Loops fn_late_charge_waive per row (behaviour identical by
-- construction: approver + reason recorded, linked penalty bill cancelled
-- unless already paid). Returns a summary the admin page can show.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_late_charge_waive_bill(p_bill_id uuid, p_reason text)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_charge RECORD;
  v_result jsonb;
  v_rows_waived integer := 0;
  v_penalty_cancelled integer := 0;
  v_total numeric := 0;
BEGIN
  -- Same caller gate as fn_late_charge_waive.
  IF NOT (is_super_admin() OR user_has_permission('billing.late_charges.waive')) THEN
    RAISE EXCEPTION 'insufficient privilege: billing.late_charges.waive required'
      USING ERRCODE = '42501';
  END IF;

  IF NULLIF(TRIM(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'a waiver reason is required — waivers are always recorded with who and why';
  END IF;

  -- Every not-yet-waived charge on this one bill, oldest month first. Each is
  -- waived through fn_late_charge_waive so status/waived_by/waived_at/
  -- waiver_reason and the penalty-bill cancellation are exactly the
  -- single-month behaviour, row by row.
  FOR v_charge IN
    SELECT id, charge_amount
    FROM billing_late_charges
    WHERE bill_id = p_bill_id
      AND status <> 'waived'
    ORDER BY period_start
  LOOP
    v_result := fn_late_charge_waive(v_charge.id, p_reason);
    v_rows_waived := v_rows_waived + 1;
    v_total := v_total + v_charge.charge_amount;
    IF COALESCE((v_result ->> 'penalty_bill_cancelled')::boolean, false) THEN
      v_penalty_cancelled := v_penalty_cancelled + 1;
    END IF;
  END LOOP;

  IF v_rows_waived = 0 THEN
    RAISE EXCEPTION 'bill % has no late charges left to waive', p_bill_id;
  END IF;

  RETURN jsonb_build_object(
    'bill_id', p_bill_id,
    'rows_waived', v_rows_waived,
    'penalty_bills_cancelled', v_penalty_cancelled,
    'total_amount_waived', v_total
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_late_charge_waive_bill(uuid, text) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_late_charge_waive_bill(uuid, text) TO authenticated;

    tier_id, allocated_by
  ) VALUES (
    v_inst, v_profile, v_block, p_room_id, p_bed_id, v_ay, v_sem,
    'fresh', CURRENT_DATE, 'active', '', '', '',
    v_tier, auth.uid()
  ) RETURNING id INTO v_alloc_id;

  -- occupy the bed (immediate-active per design decision)
  UPDATE hostel_beds SET status='occupied', current_occupant_id=v_profile, updated_at=now() WHERE id = p_bed_id;

  -- room category is synced by trg_allocation_sync_learner_categories; honor an explicit mess pick
  IF p_mess_category_id IS NOT NULL THEN
    UPDATE learners_profiles SET mess_category_id = p_mess_category_id, updated_at = now() WHERE id = p_learner_profile_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'allocation_id', v_alloc_id,
                            'room_id', p_room_id, 'bed_id', p_bed_id, 'block_id', v_block);
END;
$function$;

REVOKE EXECUTE ON FUNCTION public.fn_cl_admin_allocate_bed(uuid,uuid,uuid,uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_cl_admin_allocate_bed(uuid,uuid,uuid,uuid) TO authenticated;

-- ===========================================================================
-- 20260808120000_billing_coverage_target_academic_year.sql
-- ===========================================================================
-- ============================================================================
-- Bill Coverage: measure against a real target academic year, not the learner's
-- ============================================================================
-- BUG (reported 2026-08-08, /billing/coverage): learners whose bill HAD been
-- generated were listed as "Not generated". Example 23DT05 PRIYADHARSHINI A —
-- profile academic year 2025-2026, live ₹1,40,000 "3 Year Tuition Fee" bill
-- stamped 2026-2027. The report showed her as a gap.
--
-- ROOT CAUSE. Both list and summary decided coverage with:
--
--     AND b.academic_year_id = COALESCE(p_academic_year_id, s.academic_year_id)
--                                                           ^^^^^^^^^^^^^^^^^^
-- With no year selected (the page's default) the fallback was the LEARNER'S OWN
-- profile year, so a bill only counted if it happened to carry the same year the
-- learner's profile was sitting on. Those are two independent columns:
--   * learners_profiles.academic_year_id  — the year the learner is in
--   * billing_student_bills.academic_year_id — the year the bill was raised for
-- They only agreed by accident. fn_billing_bill_default_academic_year() copies
-- the learner's year onto a bill ONLY when the bill's year is NULL, so any run
-- that stamps an explicit year (bulk-create-bills-service.ts passes the operator's
-- chosen year) breaks the assumption. Bill generation moved to 2026-2027 while
-- learner profiles still read 2025-2026, and 167 learners went false-negative.
--
-- The same lesson is already recorded in billing-receipt-service.ts:983 —
-- "Academic year lives ON the bill, not on the learner" — measured 2026-07-31 at
-- 1,774 of 6,598 outstanding bills (26.9%) carrying a year that differs from
-- their learner's. Receipts and the schedule page were fixed then; these three
-- coverage RPCs, written 2026-07-25, were not.
--
-- FIX. p_academic_year_id now means ONE thing: the year whose coverage we are
-- measuring. When it is null we resolve the institution's CURRENT academic year
-- by date, never the learner's own. Two consequences, both deliberate:
--
--  1. The learner-scope predicate `lp.academic_year_id = p_academic_year_id` is
--     REMOVED. It made the control do double duty — picking 2026-2027 at Allied
--     Health narrowed the population to the 79 learners whose profile had already
--     rolled over, hiding the 206 who had not, i.e. exactly the learners most
--     likely to be missing a bill. A coverage report must not let its target year
--     shrink the population it is auditing.
--  2. 190 learners flip from "generated" to "not generated". They are real gaps
--     the old rule concealed: a lagging profile year plus a bill for that lagging
--     year read as covered. Verified — each has bills only in 2025-2026 and none
--     for 2026-2027. Measured against 5,440 in-scope learners: 83 false negatives
--     cleared, 190 hidden true gaps surfaced, cannot_evaluate 16 -> 0.
-- ============================================================================

-- ── Target-year resolution ──────────────────────────────────────────────────
-- Greatest start_date <= today, per institution. Deliberately NOT end_date
-- BETWEEN: the Jun 1 -> Mar 31 convention leaves Apr-May covered by no row, and
-- a BETWEEN would return nothing for those two months. "Most recently started"
-- keeps Apr-May on the session that is finishing, which is what accounts mean.
--
-- is_active IS TRUE is load-bearing, not decoration. JKKN Dental carries
-- duplicate rows on the same start_date — '2026-2027' alongside an inactive
-- '2026-2027 Additional 2' (and four rows on 2025-06-01). Without the flag the
-- ORDER BY picks arbitrarily and could resolve every Dental learner against an
-- empty "Additional" year, flagging the whole college as unbilled. The name
-- tiebreak keeps it deterministic if two rows are ever active at once — the
-- canonical '2026-2027' sorts before '2026-2027 Additional 2'.
--
-- SECURITY INVOKER on purpose: it is only ever called from inside the SECURITY
-- DEFINER coverage RPCs (so it already runs as the owner and sees every row),
-- and EXECUTE is withheld from authenticated so it is not independently callable.
CREATE OR REPLACE FUNCTION public.fn_billing_coverage_target_years()
RETURNS TABLE(institution_id uuid, target_ay_id uuid, target_ay_name text)
LANGUAGE sql
STABLE
SET search_path TO 'public'
AS $function$
  SELECT DISTINCT ON (ay.institution_id)
         ay.institution_id,
         ay.id,
         ay.academic_year_name::text
  FROM public.academic_years ay
  WHERE ay.is_active IS TRUE
    AND ay.start_date <= CURRENT_DATE
  ORDER BY ay.institution_id, ay.start_date DESC, ay.academic_year_name ASC;
$function$;

REVOKE ALL ON FUNCTION public.fn_billing_coverage_target_years()
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_billing_coverage_target_years()
  TO service_role;

-- ── Learner list ────────────────────────────────────────────────────────────
-- DROP + CREATE, not CREATE OR REPLACE: out_target_academic_year_name is a new
-- RETURNS TABLE column and Postgres cannot replace a function whose output type
-- changed. DROP discards the ACL, so the grants below are mandatory, not tidy-up.
DROP FUNCTION IF EXISTS public.get_billing_coverage_learners(
  uuid, uuid[], text[], uuid, text, boolean, text, integer, integer,
  uuid[], text, text, text, text, uuid, uuid, uuid, uuid, uuid);

CREATE FUNCTION public.get_billing_coverage_learners(
  p_academic_year_id uuid DEFAULT NULL,
  p_institution_ids uuid[] DEFAULT NULL,
  p_lifecycle_statuses text[] DEFAULT ARRAY['active','reserved','admitted','account'],
  p_billing_category_id uuid DEFAULT NULL,
  p_coverage_state text DEFAULT 'not_generated',
  p_include_non_billing_institutions boolean DEFAULT false,
  p_search text DEFAULT NULL,
  p_page integer DEFAULT 1,
  p_page_size integer DEFAULT 50,
  p_accommodation_type_ids uuid[] DEFAULT NULL,
  p_transport text DEFAULT 'any',
  p_gender text DEFAULT NULL,
  p_sort_by text DEFAULT NULL,
  p_sort_dir text DEFAULT 'asc',
  p_degree_id uuid DEFAULT NULL,
  p_department_id uuid DEFAULT NULL,
  p_program_id uuid DEFAULT NULL,
  p_semester_id uuid DEFAULT NULL,
  p_section_id uuid DEFAULT NULL
)
RETURNS TABLE(
  out_learner_id uuid,
  out_roll_number text,
  out_register_number text,
  out_full_name text,
  out_lifecycle_status text,
  out_gender text,
  out_institution_id uuid,
  out_institution_name text,
  out_program_name text,
  out_semester_section text,
  out_academic_year_id uuid,
  out_academic_year_name text,
  out_accommodation_type text,
  out_uses_transport boolean,
  out_bill_count integer,
  out_total_billed numeric,
  out_coverage_state text,
  out_target_academic_year_name text,
  out_total_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst   uuid[];
  v_limit  integer := LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 200);
  v_offset integer := GREATEST(COALESCE(p_page, 1) - 1, 0)
                      * LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 200);
  v_asc    boolean := COALESCE(LOWER(p_sort_dir), 'asc') <> 'desc';
  -- Name of an explicitly picked year, so the reported target reflects the
  -- caller's choice rather than the institution's current year.
  v_picked_ay_name text;
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN;
  END IF;

  SELECT ay.academic_year_name::text INTO v_picked_ay_name
  FROM public.academic_years ay WHERE ay.id = p_academic_year_id;

  RETURN QUERY
  WITH target_year AS MATERIALIZED (
    SELECT t.institution_id, t.target_ay_id, t.target_ay_name
    FROM public.fn_billing_coverage_target_years() t
  ),
  billing_inst AS (
    -- ALL-TIME test, deliberately not scoped to p_academic_year_id. An
    -- institution that billed last year and has generated nothing this year is
    -- the case this report exists to catch; scoping here would hide it.
    SELECT DISTINCT b.institution_id AS inst_id
    FROM public.billing_student_bills b
  ),
  scope AS (
    -- NOTE: no lp.academic_year_id predicate. p_academic_year_id selects the
    -- year being MEASURED, never the learners being measured — see header.
    SELECT lp.id, lp.institution_id, lp.academic_year_id, lp.program_id,
           lp.semester_id, lp.section_id, lp.gender,
           lp.lifecycle_status, lp.first_name, lp.last_name,
           lp.roll_number, lp.register_number,
           lp.accommodation_type_id,
           (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL)
             AS uses_transport
    FROM public.learners_profiles lp
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_billing_institutions
           OR lp.institution_id IN (SELECT inst_id FROM billing_inst))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
      AND (
        p_search IS NULL OR p_search = ''
        OR lp.roll_number ILIKE '%' || p_search || '%'
        OR lp.register_number ILIKE '%' || p_search || '%'
        OR (COALESCE(lp.first_name,'') || ' ' || COALESCE(lp.last_name,''))
             ILIKE '%' || p_search || '%'
      )
  ),
  agg AS (
    SELECT s.id AS learner_id,
           ty.target_ay_id,
           ty.target_ay_name,
           COUNT(b.id)::integer AS bill_count,
           COALESCE(SUM(b.final_amount), 0)::numeric AS total_billed
    FROM scope s
    LEFT JOIN target_year ty ON ty.institution_id = s.institution_id
    LEFT JOIN public.billing_student_bills b
           ON b.student_id = s.id
          -- A cancelled or superseded bill is not coverage: no live bill exists.
          AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
          -- The bill's OWN year against the target year. Was s.academic_year_id.
          AND b.academic_year_id = COALESCE(p_academic_year_id, ty.target_ay_id)
          AND (p_billing_category_id IS NULL
               OR b.item_category_id = p_billing_category_id)
    GROUP BY s.id, ty.target_ay_id, ty.target_ay_name
  ),
  final AS (
    SELECT s.id AS learner_id,
           s.roll_number::text        AS roll_number,
           s.register_number::text    AS register_number,
           TRIM(COALESCE(s.first_name,'') || ' ' || COALESCE(s.last_name,''))
                                      AS full_name,
           s.lifecycle_status::text   AS lifecycle_status,
           NULLIF(TRIM(s.gender), '')::text AS gender,
           s.institution_id           AS institution_id,
           i.name::text               AS institution_name,
           p.program_name             AS program_name,
           CASE
             WHEN sem.semester_name IS NULL AND sec.section_name IS NULL
               THEN NULL
             WHEN sec.section_name IS NULL THEN sem.semester_name::text
             WHEN sem.semester_name IS NULL THEN sec.section_name::text
             ELSE sem.semester_name::text || ' · ' || sec.section_name::text
           END                        AS semester_section,
           -- The learner's OWN year, shown for context. It is no longer what
           -- coverage is measured against; target_academic_year_name is.
           s.academic_year_id         AS academic_year_id,
           ay.academic_year_name::text AS academic_year_name,
           acc.name::text             AS accommodation_type,
           s.uses_transport           AS uses_transport,
           a.bill_count               AS bill_count,
           a.total_billed             AS total_billed,
           CASE
             -- Only when NO year can be resolved at all: an institution with no
             -- active year that has started yet. Never a mere mismatch.
             WHEN COALESCE(p_academic_year_id, a.target_ay_id) IS NULL
               THEN 'cannot_evaluate'
             WHEN a.bill_count > 0 THEN 'generated'
             ELSE 'not_generated'
           END                        AS coverage_state,
           COALESCE(v_picked_ay_name, a.target_ay_name)
                                      AS target_academic_year_name
    FROM scope s
    JOIN agg a                           ON a.learner_id = s.id
    LEFT JOIN public.institutions        i   ON i.id   = s.institution_id
    LEFT JOIN public.programs            p   ON p.id   = s.program_id
    LEFT JOIN public.semesters           sem ON sem.id = s.semester_id
    LEFT JOIN public.sections            sec ON sec.id = s.section_id
    LEFT JOIN public.academic_years      ay  ON ay.id  = s.academic_year_id
    LEFT JOIN public.accommodation_types acc ON acc.id = s.accommodation_type_id
  ),
  filtered AS (
    SELECT * FROM final f
    WHERE p_coverage_state = 'all' OR f.coverage_state = p_coverage_state
  )
  SELECT f.learner_id, f.roll_number, f.register_number, f.full_name,
         f.lifecycle_status, f.gender, f.institution_id, f.institution_name,
         f.program_name, f.semester_section,
         f.academic_year_id, f.academic_year_name,
         f.accommodation_type, f.uses_transport,
         f.bill_count, f.total_billed, f.coverage_state,
         f.target_academic_year_name,
         COUNT(*) OVER ()::bigint
  FROM filtered f
  ORDER BY
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'academic_year_name' THEN f.academic_year_name
         WHEN 'accommodation_type' THEN f.accommodation_type
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'gender'             THEN f.gender
         WHEN 'coverage_state'     THEN f.coverage_state
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'academic_year_name' THEN f.academic_year_name
         WHEN 'accommodation_type' THEN f.accommodation_type
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'gender'             THEN f.gender
         WHEN 'coverage_state'     THEN f.coverage_state
       END
     END) DESC NULLS LAST,
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'bill_count'   THEN f.bill_count::numeric
         WHEN 'total_billed' THEN f.total_billed
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'bill_count'   THEN f.bill_count::numeric
         WHEN 'total_billed' THEN f.total_billed
       END
     END) DESC NULLS LAST,
    f.institution_name NULLS LAST, f.roll_number NULLS LAST, f.full_name
  LIMIT v_limit OFFSET v_offset;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_billing_coverage_learners(
  uuid, uuid[], text[], uuid, text, boolean, text, integer, integer,
  uuid[], text, text, text, text, uuid, uuid, uuid, uuid, uuid)
  FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_billing_coverage_learners(
  uuid, uuid[], text[], uuid, text, boolean, text, integer, integer,
  uuid[], text, text, text, text, uuid, uuid, uuid, uuid, uuid)
  TO authenticated, service_role;

-- ── Summary (KPI cards) ─────────────────────────────────────────────────────
-- Must move with the list. The cards counting one population while the table
-- shows another is the failure mode the shared baseParams() in
-- bill-coverage-service.ts already guards against on the filter side.
CREATE OR REPLACE FUNCTION public.get_billing_coverage_summary(
  p_academic_year_id uuid DEFAULT NULL,
  p_institution_ids uuid[] DEFAULT NULL,
  p_lifecycle_statuses text[] DEFAULT ARRAY['active','reserved','admitted','account'],
  p_billing_category_id uuid DEFAULT NULL,
  p_include_non_billing_institutions boolean DEFAULT false,
  p_accommodation_type_ids uuid[] DEFAULT NULL,
  p_transport text DEFAULT 'any',
  p_gender text DEFAULT NULL,
  p_degree_id uuid DEFAULT NULL,
  p_department_id uuid DEFAULT NULL,
  p_program_id uuid DEFAULT NULL,
  p_semester_id uuid DEFAULT NULL,
  p_section_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst   uuid[];
  v_result jsonb;
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN jsonb_build_object(
      'in_scope', 0, 'generated', 0, 'not_generated', 0, 'cannot_evaluate', 0,
      'excluded_institutions', 0, 'excluded_learners', 0,
      'by_institution', '[]'::jsonb);
  END IF;

  WITH target_year AS MATERIALIZED (
    SELECT t.institution_id, t.target_ay_id
    FROM public.fn_billing_coverage_target_years() t
  ),
  billing_inst AS (
    SELECT DISTINCT b.institution_id AS inst_id FROM public.billing_student_bills b
  ),
  all_scope AS (
    -- No lp.academic_year_id predicate — see the list RPC above.
    SELECT lp.id, lp.institution_id,
           (lp.institution_id IN (SELECT inst_id FROM billing_inst)) AS is_billing_inst
    FROM public.learners_profiles lp
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
  ),
  scope AS (
    SELECT * FROM all_scope
    WHERE p_include_non_billing_institutions OR is_billing_inst
  ),
  agg AS (
    SELECT s.id, s.institution_id, ty.target_ay_id,
           COUNT(b.id)::integer AS bill_count
    FROM scope s
    LEFT JOIN target_year ty ON ty.institution_id = s.institution_id
    LEFT JOIN public.billing_student_bills b
           ON b.student_id = s.id
          AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
          AND b.academic_year_id = COALESCE(p_academic_year_id, ty.target_ay_id)
          AND (p_billing_category_id IS NULL
               OR b.item_category_id = p_billing_category_id)
    GROUP BY s.id, s.institution_id, ty.target_ay_id
  ),
  stated AS (
    SELECT a.institution_id,
           CASE
             WHEN COALESCE(p_academic_year_id, a.target_ay_id) IS NULL
               THEN 'cannot_evaluate'
             WHEN a.bill_count > 0 THEN 'generated'
             ELSE 'not_generated'
           END AS coverage_state
    FROM agg a
  )
  SELECT jsonb_build_object(
    'in_scope',        (SELECT COUNT(*) FROM stated),
    'generated',       (SELECT COUNT(*) FROM stated WHERE coverage_state = 'generated'),
    'not_generated',   (SELECT COUNT(*) FROM stated WHERE coverage_state = 'not_generated'),
    'cannot_evaluate', (SELECT COUNT(*) FROM stated WHERE coverage_state = 'cannot_evaluate'),
    'excluded_institutions',
      (SELECT COUNT(DISTINCT institution_id) FROM all_scope WHERE NOT is_billing_inst),
    'excluded_learners',
      (SELECT COUNT(*) FROM all_scope WHERE NOT is_billing_inst),
    'by_institution', COALESCE((
      SELECT jsonb_agg(x ORDER BY x->>'institution_name')
      FROM (
        SELECT jsonb_build_object(
                 'institution_id',   st.institution_id,
                 'institution_name', COALESCE(i.name::text, 'Unknown'),
                 'in_scope',         COUNT(*),
                 'generated',        COUNT(*) FILTER (WHERE st.coverage_state = 'generated'),
                 'not_generated',    COUNT(*) FILTER (WHERE st.coverage_state = 'not_generated')
               ) AS x
        FROM stated st
        LEFT JOIN public.institutions i ON i.id = st.institution_id
        GROUP BY st.institution_id, i.name
      ) sub
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$function$;

-- ── PDF export ──────────────────────────────────────────────────────────────
-- This one had the OPPOSITE bug: `p_academic_year_id IS NULL OR ...` meant an
-- unfiltered export counted bills from ANY year, so the same learner read
-- "Not generated" in the table and "generated" in the PDF. Aligned to the same
-- target year so the three RPCs finally agree.
CREATE OR REPLACE FUNCTION public.get_billing_coverage_learner_bills(
  p_academic_year_id uuid DEFAULT NULL,
  p_institution_ids uuid[] DEFAULT NULL,
  p_lifecycle_statuses text[] DEFAULT ARRAY['active','reserved','admitted','account'],
  p_billing_category_id uuid DEFAULT NULL,
  p_coverage_state text DEFAULT 'all',
  p_include_non_billing_institutions boolean DEFAULT false,
  p_search text DEFAULT NULL,
  p_accommodation_type_ids uuid[] DEFAULT NULL,
  p_transport text DEFAULT 'any',
  p_gender text DEFAULT NULL,
  p_degree_id uuid DEFAULT NULL,
  p_department_id uuid DEFAULT NULL,
  p_program_id uuid DEFAULT NULL,
  p_semester_id uuid DEFAULT NULL,
  p_section_id uuid DEFAULT NULL,
  p_max_learners integer DEFAULT 1000
)
RETURNS TABLE(
  out_learner_id uuid, out_roll_number text, out_register_number text,
  out_full_name text, out_institution_name text, out_program_name text,
  out_semester_section text, out_lifecycle_status text,
  out_learner_total numeric, out_learner_paid numeric, out_learner_pending numeric,
  out_bill_id uuid, out_bill_description text, out_category_name text,
  out_bill_academic_year text, out_due_date date, out_bill_status text,
  out_total_amount numeric, out_paid_amount numeric, out_pending_amount numeric,
  out_learner_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst  uuid[];
  v_cap   integer := LEAST(GREATEST(COALESCE(p_max_learners, 1000), 1), 5000);
BEGIN
  IF NOT public.user_has_permission('billing.coverage.export') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.export' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH target_year AS MATERIALIZED (
    SELECT t.institution_id, t.target_ay_id
    FROM public.fn_billing_coverage_target_years() t
  ),
  billing_inst AS (
    SELECT DISTINCT b.institution_id AS inst_id FROM public.billing_student_bills b
  ),
  scope AS (
    -- No lp.academic_year_id predicate — see the list RPC above.
    SELECT lp.id, lp.institution_id, lp.academic_year_id, lp.program_id,
           lp.semester_id, lp.section_id, lp.lifecycle_status,
           lp.first_name, lp.last_name, lp.roll_number, lp.register_number
    FROM public.learners_profiles lp
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_billing_institutions
           OR lp.institution_id IN (SELECT inst_id FROM billing_inst))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
      AND (
        p_search IS NULL OR p_search = ''
        OR lp.roll_number ILIKE '%' || p_search || '%'
        OR lp.register_number ILIKE '%' || p_search || '%'
        OR (COALESCE(lp.first_name,'') || ' ' || COALESCE(lp.last_name,''))
             ILIKE '%' || p_search || '%'
      )
  ),
  live_bills AS (
    SELECT b.*
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    LEFT JOIN target_year ty ON ty.institution_id = s.institution_id
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
      AND (p_billing_category_id IS NULL OR b.item_category_id = p_billing_category_id)
      AND b.academic_year_id = COALESCE(p_academic_year_id, ty.target_ay_id)
  ),
  learner_state AS (
    SELECT s.id,
           COUNT(lb.id)::integer AS bill_count,
           COALESCE(SUM(lb.final_amount), 0)::numeric   AS total_amount,
           COALESCE(SUM(lb.final_amount - lb.balance_amount), 0)::numeric AS paid_amount,
           COALESCE(SUM(lb.balance_amount), 0)::numeric AS pending_amount
    FROM scope s
    LEFT JOIN live_bills lb ON lb.student_id = s.id
    GROUP BY s.id
  ),
  eligible AS (
    SELECT s.*, ls.bill_count, ls.total_amount, ls.paid_amount, ls.pending_amount
    FROM scope s
    JOIN learner_state ls ON ls.id = s.id
    WHERE p_coverage_state = 'all'
       OR (p_coverage_state = 'generated'     AND ls.bill_count > 0)
       OR (p_coverage_state = 'not_generated' AND ls.bill_count = 0)
  ),
  capped AS (
    SELECT e.*, i.name::text AS institution_name, p.program_name,
           CASE
             WHEN sem.semester_name IS NULL AND sec.section_name IS NULL THEN NULL
             WHEN sec.section_name IS NULL THEN sem.semester_name::text
             WHEN sem.semester_name IS NULL THEN sec.section_name::text
             ELSE sem.semester_name::text || ' · ' || sec.section_name::text
           END AS semester_section,
           COUNT(*) OVER ()::bigint AS learner_count
    FROM eligible e
    LEFT JOIN public.institutions i   ON i.id   = e.institution_id
    LEFT JOIN public.programs     p   ON p.id   = e.program_id
    LEFT JOIN public.semesters    sem ON sem.id = e.semester_id
    LEFT JOIN public.sections     sec ON sec.id = e.section_id
    ORDER BY i.name NULLS LAST, e.roll_number NULLS LAST, e.last_name, e.first_name
    LIMIT v_cap
  )
  SELECT c.id,
         c.roll_number::text,
         c.register_number::text,
         TRIM(COALESCE(c.first_name,'') || ' ' || COALESCE(c.last_name,'')),
         c.institution_name,
         c.program_name,
         c.semester_section,
         c.lifecycle_status::text,
         c.total_amount,
         c.paid_amount,
         c.pending_amount,
         lb.id,
         lb.bill_description::text,
         cat.category_name::text,
         -- 59 live bills carry no academic year; label rather than drop the row.
         COALESCE(ay.academic_year_name::text, '—'),
         lb.due_date,
         lb.status::text,
         lb.final_amount,
         (lb.final_amount - lb.balance_amount),
         lb.balance_amount,
         c.learner_count
  FROM capped c
  LEFT JOIN live_bills lb              ON lb.student_id = c.id
  LEFT JOIN public.billing_categories cat ON cat.id = lb.item_category_id
  LEFT JOIN public.academic_years ay    ON ay.id  = lb.academic_year_id
  ORDER BY c.institution_name NULLS LAST, c.roll_number NULLS LAST,
           lb.due_date NULLS LAST, lb.bill_description;
END;
$function$;


-- ================================================================================
-- Updated: 2026-08-09 - Notification expiry for self-obsoleting cron rows.
-- ✅ APPLIED TO PRODUCTION 2026-08-10 via migration 20260816040000 (hand-applied,
--    Director-gated, recorded in supabase_migrations.schema_migrations). The
--    bodies in this section are now the ones RUNNING on prod — verified by
--    catalog read: fn_create_dashboard_work_item pronargs=9 with p_expires_hours.
--    ⚠️ This section carries Director-gated changes (it revives
--    fn_generate_super_admin_daily_digest). Do NOT paste it wholesale to
--    "restore" functions without checking what is already live — the migration
--    that owns it is gated for a reason; this reference copy is not.
-- Mirrors supabase/migrations/20260816040000_notification_expiry_director_categories.sql
-- (that file carries the full rationale and the category-by-category decision on
-- what is expired vs deliberately left in the badge as un-actioned work).
--
-- These FIVE definitions SUPERSEDE the earlier copies above in this file.
-- (fn_generate_hr_command_center_brief_items was added in review 2026-08-09:
--  the backfill cleared its rows but its generator still emitted unexpiring
--  ones, so the backlog would have simply rebuilt.)
-- fn_create_dashboard_work_item gains a ninth parameter, p_expires_hours, which
-- DEFAULTS TO NULL so every existing eight-argument caller is unchanged.
--
-- ############################################################################
-- ##  ORDERING WARNING -- fn_generate_super_admin_daily_digest              ##
-- ############################################################################
-- HISTORICAL, resolved 2026-08-10: the copy below WAS ahead of production until
-- migration 20260816040000 was hand-applied, and is now the body running there.
-- Before that, production carried a dead `se.event_type` reference
-- (public.startup_events has no such column) which raised 42703 and killed the
-- whole digest -- the newest 'digest:%' notification on prod was dated
-- 2026-05-08 although the cron had fired daily
-- since. That one line is DELETED here, marked `2026-08-09 REVIVAL`, precisely
-- so this file does not freeze the bug and silently revert whoever fixes it
-- first: CREATE OR REPLACE does not validate a plpgsql body, so re-applying an
-- older copy after this one restores the dead reference with no error at all.
-- Do NOT re-add `se.event_type`, and do not apply an older copy of that function
-- after this file. Same warning sits on section 2 below and in
-- supabase/migrations/20260816040000_notification_expiry_director_categories.sql.
-- ================================================================================

-- --------------------------------------------------------------------------------
-- 1. fn_create_dashboard_work_item --- add opt-in p_expires_hours (DEFAULT NULL)
-- --------------------------------------------------------------------------------
-- DROP first: CREATE OR REPLACE cannot change a function's argument list, and
-- leaving the 8-arg version in place alongside a 9-arg one would make every
-- existing 8-argument call ambiguous.
DROP FUNCTION IF EXISTS public.fn_create_dashboard_work_item(text,text,text,text,jsonb,uuid,text,integer);

CREATE OR REPLACE FUNCTION public.fn_create_dashboard_work_item(p_category text, p_priority text, p_title text, p_body text, p_action_config jsonb, p_target_user uuid, p_idempotency_key text, p_deadline_hours integer DEFAULT 48,
-- 2026-08-09 expiry: NEW, opt-in. NULL (the default) reproduces today's
-- behaviour exactly for all twelve existing callers.
 p_expires_hours integer DEFAULT NULL)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_notif_id UUID;
BEGIN
  IF EXISTS (SELECT 1 FROM notifications WHERE idempotency_key = p_idempotency_key) THEN
    RETURN 0;
  END IF;
  INSERT INTO notifications (
    id, title, body, category, kind, priority, requires_acknowledgment,
    acknowledgment_deadline_hours, action_type, action_config, idempotency_key,
    created_by, targeting, created_at, updated_at,
    is_layer_0,
    -- 2026-08-09 expiry: honoured by liveNotificationOrFilter() in the bell /
    -- inbox / rollup read path. NULL = never expires (unchanged default).
    expires_at
  ) VALUES (
    -- 2026-04-23 decoupling: requires_acknowledgment=FALSE so work items don't
    -- trigger the Mandatory Acknowledgment blocking modal. Queue filter uses
    -- category only.
    -- 2026-04-24 split: kind='work_item' keeps these out of /admin/notifications
    -- (which filters to kind='announcement'). Work items surface via dashboard
    -- widgets + super-admin digest instead.
    -- Wave B.4 (2026-04-29): is_layer_0 is the new dedicated Attention Bar
    -- Layer 0 signal. Setting it for urgent priorities makes the bar's
    -- split-rendering path eligible to surface this work item, without
    -- coupling to the gate's ack semantics.
    gen_random_uuid(), p_title, p_body, p_category, 'work_item', p_priority, FALSE,
    p_deadline_hours, 'open_url', p_action_config, p_idempotency_key,
    p_target_user, jsonb_build_object('type','user','user_ids', jsonb_build_array(p_target_user)),
    NOW(), NOW(),
    (p_priority = 'urgent'),
    CASE WHEN p_expires_hours IS NULL THEN NULL
         ELSE NOW() + make_interval(hours => p_expires_hours) END
  ) RETURNING id INTO v_notif_id;
  INSERT INTO user_notifications (id, notification_id, user_id, created_at)
  VALUES (gen_random_uuid(), v_notif_id, p_target_user, NOW());
  RETURN 1;
END
$function$;

-- Production ACL for this function is postgres + service_role only (verified
-- 2026-08-09). Re-assert it after the DROP; the explicit anon revoke is required
-- because Supabase's ALTER DEFAULT PRIVILEGES grants EXECUTE on every new
-- function to anon and to authenticated.
REVOKE ALL ON FUNCTION public.fn_create_dashboard_work_item(text,text,text,text,jsonb,uuid,text,integer,integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_create_dashboard_work_item(text,text,text,text,jsonb,uuid,text,integer,integer) TO service_role;

-- --------------------------------------------------------------------------------
-- 2. fn_generate_super_admin_daily_digest --- 36h TTL on all seven digest rows
--    + the one-line REVIVAL of a function dead on prod since 2026-05-08
-- --------------------------------------------------------------------------------
-- Every call site in this function builds a row titled 'Daily digest --- N ...'
-- under the key 'digest:<user>:<category>:<YYYY-MM-DD>'. All seven are the same
-- shape and all seven already declare a 24h acknowledgment deadline.
--
-- ############################################################################
-- ##  HISTORICAL (resolved 2026-08-10) -- THIS BODY *IS* NOW THE ONE ON PROD ##
-- ############################################################################
-- As of 2026-08-10 this corrected body was applied to production, so the warning
-- below is history rather than a live hazard. It is kept because the failure it
-- describes is subtle and worth not re-introducing: CREATE OR REPLACE does not
-- validate a plpgsql body, so re-applying an OLDER copy of this function would
-- silently restore the dead reference with no error at all. Do NOT re-add
-- `se.event_type`. (Verified on prod 2026-08-10: the only remaining mentions of
-- event_type in this function are the comments recording its removal.)
--
-- The pre-2026-08-10 production body carried a dead column reference,
-- `se.event_type`, in the
-- Category 5 (dashboard:ai_pulse) block. public.startup_events has no such
-- column (information_schema, 2026-08-09), so the statement raises 42703 the
-- moment the loop reaches its first super-admin -- which aborts the whole call
-- and rolls back every digest row the earlier categories built. That is why the
-- newest 'digest:%' notification on prod is dated 2026-05-08 while the cron
-- (vercel.json '3 3 * * *') has fired every day since.
--
-- MEASURED, production, BEGIN..ROLLBACK, 2026-08-09 (prod re-verified unchanged
-- afterwards -- 8-arg signature intact, digest row count still 687):
--   * body EXACTLY as it stands on prod  -> ERROR 42703 'column se.event_type
--     does not exist', PL/pgSQL line 207.
--   * same body with the dead disjunct removed -> returns 129 (rows it would
--     have created), no error.
--
-- Shipping the prod body verbatim would have frozen that bug into two files. A
-- later PR that fixes it, applied BEFORE this one, would then be silently
-- reverted -- CREATE OR REPLACE does not validate a plpgsql body, so the dead
-- reference would come back with no error and the digest would die again.
-- So the fix is CARRIED here rather than copied around, marked `2026-08-09
-- REVIVAL`. It is a one-line deletion: the two surviving disjuncts
-- (config->>'kind' and config->'ai_pulse') already express the same intent.
--
-- IF YOU ARE THE OTHER PR: this file already contains the fix. Do not apply an
-- older copy of fn_generate_super_admin_daily_digest after this one, and do not
-- re-add `se.event_type`. The same warning sits above the same function in
-- supabase/setup/02_functions.sql.
--
-- CONSEQUENCE OF APPLYING THIS DEFINITION: the super-admin daily digest starts
-- producing rows again every day -- 129 for the day measured 2026-08-09, and
-- 46-49/day over its last eight days alive (2026-05-01..2026-05-08), all
-- with a 36h TTL. That is the intended repair, but it is a behaviour change on
-- top of the TTL work and the Director should be told it is in the same apply.
CREATE OR REPLACE FUNCTION public.fn_generate_super_admin_daily_digest()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_created INT := 0;
  v_user RECORD;
  v_today TEXT := TO_CHAR(CURRENT_DATE, 'YYYY-MM-DD');
  v_key TEXT;
  v_total INT;
  v_breakdown TEXT;
  v_body TEXT;
  v_emit_escalation BOOLEAN;
  v_emit_rescue BOOLEAN;
  v_emit_approval BOOLEAN;
  v_emit_anomaly BOOLEAN;
  v_last_cycle_id       UUID;
  v_enrolled_teams      INT;
  v_engaged_teams       INT;
  v_engagement_pct      NUMERIC(5,1);
  v_anomaly_count       INT;
  v_gold_count          INT;
  v_red_flag_depts      TEXT;
  v_red_flag_count      INT;
  v_quiz_pass_threshold INT;
  v_escalation_t2_pct   NUMERIC(5,1);
  v_ai_pulse_active     BOOLEAN;
  v_ai_pulse_parts      TEXT[];
BEGIN
  FOR v_user IN
    SELECT id, role, is_super_admin
    FROM profiles
    WHERE is_super_admin = TRUE
       OR role IN ('ceo','cao','cbo','executive_admin_officer','registrar',
                   'hr_admin','system_admin','admission_counselor','expo_counselor',
                   'admission_staff','accountant_assistant')
  LOOP
    v_emit_escalation := v_user.is_super_admin
                      OR v_user.role IN ('ceo','cbo','accountant_assistant');
    v_emit_rescue     := v_user.is_super_admin
                      OR v_user.role IN ('cbo','admission_counselor','expo_counselor','admission_staff');
    v_emit_approval   := v_user.is_super_admin
                      OR v_user.role IN ('ceo','cao','executive_admin_officer','registrar','hr_admin');
    v_emit_anomaly    := v_user.is_super_admin
                      OR v_user.role IN ('cao','registrar','system_admin');

    -- Category 1: dashboard:escalation
    IF v_emit_escalation THEN
      WITH counts AS (
        SELECT REPLACE(REPLACE(i.name, 'JKKN College of ', ''), 'JKKN ', '') AS inst, COUNT(*) AS cnt
        FROM billing_invoices bi
        JOIN institutions i ON bi.institution_id = i.id
        WHERE bi.due_date < CURRENT_DATE - INTERVAL '30 days' AND bi.grand_total > 0
          AND COALESCE((SELECT SUM(br.payment_amount) FROM billing_receipts br
                        WHERE br.student_id = bi.student_id
                          AND br.receipt_date >= bi.billing_period_from), 0) < bi.grand_total
        GROUP BY i.id, i.name
      )
      SELECT COALESCE(SUM(cnt), 0),
             STRING_AGG(inst || ': ' || cnt, ', ' ORDER BY cnt DESC)
      INTO v_total, v_breakdown FROM counts;
      IF v_total > 0 THEN
        v_key := 'digest:' || v_user.id::text || ':dashboard:escalation:' || v_today;
        v_body := v_total || ' overdue invoice(s). ' || COALESCE(v_breakdown, '') || '.';
        v_created := v_created + fn_create_dashboard_work_item(
          'dashboard:escalation', 'high',
          'Daily digest — ' || v_total || ' overdue invoice(s)',
          v_body,
          jsonb_build_object('url', '/admin/notifications?category=dashboard%3Aescalation',
            'digest', true, 'total', v_total),
          v_user.id, v_key, 24,
          36); -- 2026-08-09 expiry: 36h, 1.5x the daily cycle
      END IF;
    END IF;

    -- Category 2: dashboard:rescue
    IF v_emit_rescue THEN
      WITH counts AS (
        SELECT REPLACE(REPLACE(i.name, 'JKKN College of ', ''), 'JKKN ', '') AS inst, COUNT(*) AS cnt
        FROM admission_leads al
        JOIN institutions i ON al.institution_id = i.id
        WHERE COALESCE(al.last_activity_at, al.created_at) < NOW() - INTERVAL '24 hours'
          AND COALESCE(al.last_activity_at, al.created_at) > NOW() - INTERVAL '30 days'
        GROUP BY i.id, i.name
      )
      SELECT COALESCE(SUM(cnt), 0),
             STRING_AGG(inst || ': ' || cnt, ', ' ORDER BY cnt DESC)
      INTO v_total, v_breakdown FROM counts;
      IF v_total > 0 THEN
        v_key := 'digest:' || v_user.id::text || ':dashboard:rescue:' || v_today;
        v_body := v_total || ' stale lead(s). ' || COALESCE(v_breakdown, '') || '.';
        v_created := v_created + fn_create_dashboard_work_item(
          'dashboard:rescue', 'normal',
          'Daily digest — ' || v_total || ' stale lead(s)',
          v_body,
          jsonb_build_object('url', '/admission/leads?stale_min_days=30',
            'digest', true, 'total', v_total),
          v_user.id, v_key, 24,
          36); -- 2026-08-09 expiry: 36h, 1.5x the daily cycle
      END IF;
    END IF;

    -- Category 3: dashboard:approval
    IF v_emit_approval THEN
      WITH leave_counts AS (
        SELECT 'leaves' AS src, COUNT(*) AS cnt
        FROM hr_leave_applications la
        WHERE la.status = 'pending' AND la.created_at < NOW() - INTERVAL '48 hours'
          AND la.created_at > NOW() - INTERVAL '30 days' AND la.superseded_by IS NULL
      ),
      recruit_counts AS (
        SELECT 'recruitment' AS src, COUNT(*) AS cnt
        FROM hr_recruitment_candidates
        WHERE status = 'pending_approval' AND submitted_at < NOW() - INTERVAL '24 hours'
          AND submitted_at > NOW() - INTERVAL '90 days'
      ),
      sr_counts AS (
        SELECT 'service_requests' AS src, COUNT(*) AS cnt
        FROM service_requests sr
        WHERE sr.status::text IN ('submitted','in_review','returned')
          AND COALESCE(sr.submitted_at, sr.created_at) < NOW() - INTERVAL '24 hours'
          AND COALESCE(sr.submitted_at, sr.created_at) > NOW() - INTERVAL '180 days'
      ),
      all_counts AS (
        SELECT src, cnt FROM leave_counts WHERE cnt > 0
        UNION ALL SELECT src, cnt FROM recruit_counts WHERE cnt > 0
        UNION ALL SELECT src, cnt FROM sr_counts WHERE cnt > 0
      )
      SELECT COALESCE(SUM(cnt), 0),
             STRING_AGG(src || ': ' || cnt, ', ' ORDER BY cnt DESC)
      INTO v_total, v_breakdown FROM all_counts;
      IF v_total > 0 THEN
        v_key := 'digest:' || v_user.id::text || ':dashboard:approval:' || v_today;
        v_body := v_total || ' approval(s) pending. ' || COALESCE(v_breakdown, '') || '.';
        v_created := v_created + fn_create_dashboard_work_item(
          'dashboard:approval', 'normal',
          'Daily digest — ' || v_total || ' approval(s) pending',
          v_body,
          jsonb_build_object('url', '/admin/notifications?category=dashboard%3Aapproval',
            'digest', true, 'total', v_total),
          v_user.id, v_key, 24,
          36); -- 2026-08-09 expiry: 36h, 1.5x the daily cycle
      END IF;
    END IF;

    -- Category 4: dashboard:anomaly
    IF v_emit_anomaly THEN
      WITH attn AS (
        SELECT 'unmarked_attendance' AS src, COUNT(*) AS cnt
        FROM timetables t
        WHERE t.is_active = TRUE AND t.start_date <= CURRENT_DATE
          AND (t.end_date IS NULL OR t.end_date >= CURRENT_DATE)
          AND NOT EXISTS (SELECT 1 FROM student_attendance sa
            WHERE sa.timetable_id = t.id AND sa.attendance_date = CURRENT_DATE)
          AND EXISTS (SELECT 1 FROM student_attendance sa2
            WHERE sa2.timetable_id = t.id
              AND sa2.attendance_date BETWEEN CURRENT_DATE - INTERVAL '14 days' AND CURRENT_DATE - INTERVAL '1 day')
      ),
      bugs AS (
        SELECT 'untriaged_bugs' AS src, COUNT(*) AS cnt
        FROM bug_reports
        WHERE status = 'new'
          AND created_at < NOW() - INTERVAL '72 hours'
          AND created_at > NOW() - INTERVAL '180 days'
          AND COALESCE(metadata->'triage'->>'tag', '')
            NOT IN ('not_a_bug','duplicate','content_only','obsolete','feature_request')
      ),
      all_anomaly AS (
        SELECT src, cnt FROM attn WHERE cnt > 0
        UNION ALL SELECT src, cnt FROM bugs WHERE cnt > 0
      )
      SELECT COALESCE(SUM(cnt), 0),
             STRING_AGG(src || ': ' || cnt, ', ' ORDER BY cnt DESC)
      INTO v_total, v_breakdown FROM all_anomaly;
      IF v_total > 0 THEN
        v_key := 'digest:' || v_user.id::text || ':dashboard:anomaly:' || v_today;
        v_body := v_total || ' anomaly signal(s). ' || COALESCE(v_breakdown, '') || '.';
        v_created := v_created + fn_create_dashboard_work_item(
          'dashboard:anomaly', 'normal',
          'Daily digest — ' || v_total || ' anomaly signal(s)',
          v_body,
          jsonb_build_object('url', '/academic/attendance/dashboard',
            'digest', true, 'total', v_total),
          v_user.id, v_key, 24,
          36); -- 2026-08-09 expiry: 36h, 1.5x the daily cycle
      END IF;
    END IF;

    -- Category 5: dashboard:ai_pulse (super_admin only)
    IF v_user.is_super_admin THEN
      v_ai_pulse_active := EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = 'public'
          AND table_name = 'ai_pulse_policies'
      );

      IF NOT v_ai_pulse_active THEN
        v_key := 'digest:' || v_user.id::text || ':dashboard:ai_pulse:pending:' || v_today;
        v_created := v_created + fn_create_dashboard_work_item(
          'dashboard:ai_pulse', 'low',
          'AI Pulse — module not yet active',
          'AI Pulse Wave A.1 (PR #644) has not merged yet. No cycle data available.',
          jsonb_build_object('url', '/ai-pulse', 'digest', true, 'active', false,
            'reason', 'No AI Pulse cycle data yet'),
          v_user.id, v_key, 24,
          36); -- 2026-08-09 expiry: 36h, 1.5x the daily cycle
        CONTINUE;
      END IF;

      SELECT se.id INTO v_last_cycle_id
      FROM startup_events se
      -- 2026-08-09 REVIVAL: `se.event_type = 'ai_pulse'` removed from this
      -- disjunction. startup_events has no event_type column, so the prod body
      -- raised 42703 here and killed the whole digest (last row 2026-05-08).
      -- The two remaining disjuncts carry the same intent. Do NOT re-add it.
      WHERE (
              (se.config->>'kind') = 'ai_pulse'
           OR (se.config->'ai_pulse') IS NOT NULL
        )
        AND se.status IN ('closed', 'completed')
      ORDER BY se.end_date DESC NULLS LAST, se.created_at DESC
      LIMIT 1;

      IF v_last_cycle_id IS NULL THEN
        v_key := 'digest:' || v_user.id::text || ':dashboard:ai_pulse:no_cycle:' || v_today;
        v_created := v_created + fn_create_dashboard_work_item(
          'dashboard:ai_pulse', 'low',
          'AI Pulse — no completed cycle yet',
          'AI Pulse module is active but no cycle has reached "completed" status yet.',
          jsonb_build_object('url', '/ai-pulse/admin/cycles', 'digest', true,
            'active', true, 'reason', 'No completed AI Pulse cycle found'),
          v_user.id, v_key, 24,
          36); -- 2026-08-09 expiry: 36h, 1.5x the daily cycle
        CONTINUE;
      END IF;

      -- 2026-08-09 COMMENT FIX: the note that stood here claimed this block
      -- "queries policy_key/value" while the real columns are
      -- config_key/value_jsonb, and would "silently fail at runtime". Both halves
      -- were wrong. Verified on production 2026-08-09: ai_pulse_policies HAS
      -- config_key, value_jsonb and is_active, which is exactly what the two
      -- SELECTs below use -- so the code is correct; and an undefined column
      -- would raise 42703, not fail silently. The note was carried in from the
      -- captured body and caused a review panel to raise a false HIGH, so it is
      -- deleted rather than reproduced. No executable line changed here.
      SELECT COALESCE(
        (SELECT (value_jsonb->>'value')::int
         FROM ai_pulse_policies
         WHERE config_key = 'quiz_pass_threshold_live'
           AND is_active = TRUE
         LIMIT 1),
        60
      ) INTO v_quiz_pass_threshold;

      SELECT COALESCE(
        (SELECT (value_jsonb->>'value')::numeric
         FROM ai_pulse_policies
         WHERE config_key = 'escalation_t2_percent'
           AND is_active = TRUE
         LIMIT 1),
        100
      ) INTO v_escalation_t2_pct;

      SELECT COALESCE(COUNT(*), 0) INTO v_enrolled_teams
      FROM event_registrations er
      WHERE er.event_id = v_last_cycle_id
        AND er.status != 'disqualified';

      SELECT COALESCE(COUNT(DISTINCT eta.registration_id), 0) INTO v_engaged_teams
      FROM event_team_attendance eta
      WHERE eta.event_id = v_last_cycle_id
        AND (
          (eta.day_type = 'live_session'
           AND (eta.engagement_signals->>'quiz_score')::int >= v_quiz_pass_threshold)
          OR
          (eta.day_type = 'async_makeup'
           AND (eta.engagement_signals->>'async_passed')::boolean IS TRUE)
        );

      v_engagement_pct := CASE
        WHEN v_enrolled_teams = 0 THEN 0
        ELSE ROUND((v_engaged_teams::numeric / v_enrolled_teams::numeric) * 100, 1)
      END;

      SELECT COALESCE(COUNT(*), 0) INTO v_anomaly_count
      FROM ai_pulse_anomaly_flags apaf
      WHERE (apaf.review_outcome IS NULL OR apaf.review_outcome = 'pending')
        AND apaf.created_at > NOW() - INTERVAL '7 days';

      SELECT COALESCE(COUNT(*), 0) INTO v_gold_count
      FROM event_submissions es
      WHERE es.event_id = v_last_cycle_id
        AND es.proof_urls IS NOT NULL
        AND jsonb_array_length(es.proof_urls) > 0;

      v_red_flag_count := 0;
      v_red_flag_depts := NULL;

      SELECT
        COUNT(*) AS dept_count,
        STRING_AGG(
          REPLACE(REPLACE(i.name, 'JKKN College of ', ''), 'JKKN ', '')
            || ': ' || missed_teams || '/' || total_teams || ' missed',
          '; '
          ORDER BY (missed_teams::numeric / NULLIF(total_teams,0)) DESC
        )
      INTO v_red_flag_count, v_red_flag_depts
      FROM (
        SELECT
          er.institution_id,
          COUNT(*) AS total_teams,
          COUNT(*) FILTER (WHERE NOT EXISTS (
            SELECT 1 FROM event_submissions es
            WHERE es.event_id = v_last_cycle_id
              AND es.registration_id = er.id
          )) AS missed_teams
        FROM event_registrations er
        WHERE er.event_id = v_last_cycle_id
          AND er.status != 'disqualified'
        GROUP BY er.institution_id
        HAVING COUNT(*) > 0
      ) dept_stats
      JOIN institutions i ON i.id = dept_stats.institution_id
      WHERE dept_stats.total_teams > 0
        AND (dept_stats.missed_teams::numeric / dept_stats.total_teams::numeric) * 100
            >= v_escalation_t2_pct;

      v_ai_pulse_parts := ARRAY[]::TEXT[];

      v_ai_pulse_parts := v_ai_pulse_parts || (
        'Engagement: ' || v_engaged_teams || '/' || v_enrolled_teams
        || ' teams (' || v_engagement_pct || '%)'
      );

      IF v_red_flag_count > 0 THEN
        v_ai_pulse_parts := v_ai_pulse_parts || (
          'Red-flag institutions (' || v_red_flag_count || '): ' || COALESCE(v_red_flag_depts, '')
        );
      END IF;

      IF v_anomaly_count > 0 THEN
        v_ai_pulse_parts := v_ai_pulse_parts || (
          v_anomaly_count || ' unreviewed anomaly flag(s) this week'
        );
      END IF;

      IF v_gold_count > 0 THEN
        v_ai_pulse_parts := v_ai_pulse_parts || (
          v_gold_count || ' Gold Standard candidate(s) this cycle'
        );
      END IF;

      v_body := ARRAY_TO_STRING(v_ai_pulse_parts, '. ') || '.';

      DECLARE
        v_pulse_priority TEXT := CASE
          WHEN v_engagement_pct < 70 OR v_red_flag_count > 0 THEN 'high'
          ELSE 'normal'
        END;
      BEGIN
        v_key := 'digest:' || v_user.id::text || ':dashboard:ai_pulse:' || v_today;
        v_created := v_created + fn_create_dashboard_work_item(
          'dashboard:ai_pulse', v_pulse_priority,
          'AI Pulse digest — ' || v_engagement_pct || '% engaged (' || v_enrolled_teams || ' teams)',
          v_body,
          jsonb_build_object(
            'url', '/ai-pulse/admin/cycles', 'digest', true, 'active', true,
            'cycle_id', v_last_cycle_id, 'enrolled_teams', v_enrolled_teams,
            'engaged_teams', v_engaged_teams, 'engagement_pct', v_engagement_pct,
            'anomaly_flag_count', v_anomaly_count, 'gold_standard_count', v_gold_count,
            'red_flag_institution_count', v_red_flag_count
          ),
          v_user.id, v_key, 24,
          36); -- 2026-08-09 expiry: 36h, 1.5x the daily cycle
      END;
    END IF;
  END LOOP;
  RETURN v_created;
END $function$;


-- CREATE OR REPLACE preserves existing grants, but assert them anyway: Supabase's
-- ALTER DEFAULT PRIVILEGES grants EXECUTE on new functions to anon AND to
-- authenticated, so an explicit revoke is the only thing keeping this cron-only
-- generator off the public anon key. Production ACL verified 2026-08-09:
-- postgres + service_role only.
REVOKE EXECUTE ON FUNCTION public.fn_generate_super_admin_daily_digest() FROM anon, PUBLIC, authenticated;
GRANT  EXECUTE ON FUNCTION public.fn_generate_super_admin_daily_digest() TO service_role;

-- --------------------------------------------------------------------------------
-- 3. fn_generate_unmarked_attendance_items --- 36h TTL, config-overridable
-- --------------------------------------------------------------------------------
-- 'Attendance not marked today --- X' is scoped to CURRENT_DATE and re-keyed daily
-- ('unmarked_attendance:<timetable>:<date>:<user>'). The generator already
-- declares "ttl_hours": 8; expires_hours is a separate, more generous key so the
-- existing acknowledgment deadline is not disturbed.
--
-- HONEST SCOPE OF THIS ONE (review, 2026-08-09). Unlike the other three, this
-- row is NOT a restatement: the key embeds the DATE, so 'timetable T was unmarked
-- on date D' is announced EXACTLY ONCE and tomorrow's row is a different fact.
-- It therefore does NOT satisfy the "same fact re-announced daily" rule this
-- migration otherwise applies, and the justification has to stand on its own:
--   * the row's own text is 'not marked TODAY ... as of 11am' -- a claim that is
--     literally false 36 hours later, and its action URL
--     (/academic/attendance/dashboard?timetable=<id>) carries no date, so an old
--     copy cannot even navigate you to the day it is about;
--   * the durable record of the gap is the ABSENCE of student_attendance rows,
--     not the notification;
--   * after the TTL the row is still fully visible at /notifications/admin --
--     only the bell/inbox read path applies liveNotificationOrFilter().
-- The cost, stated plainly: past days' unmarked sessions become invisible in the
-- bell, and the only live query, fn_aqs_attendance_unmarked_periods_today, is
-- CURRENT_DATE-only, so there is no other in-app surface for history.
-- It is therefore REVERSIBLE WITHOUT A DEPLOY: set the generator config key
-- unmarked_attendance.expires_hours to 0 and rows stop expiring (0 maps to NULL
-- below). The 42,772 historical rows of this category are a separate question,
-- and it was decided by the Director on 2026-08-09, not by code: expire them,
-- accepting that afterwards they are visible nowhere in the product but
-- /notifications/admin. The backfill migration
-- 20260816040100_backfill_expire_stale_notification_digests.sql carries that
-- decision and its full wording.
CREATE OR REPLACE FUNCTION public.fn_generate_unmarked_attendance_items()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_created INT := 0; v_tt RECORD; v_target RECORD; v_key TEXT;
  -- Wave B.2: config-driven constants
  v_cfg JSONB;
  v_category TEXT;
  v_time_gate_ist_hour INT;
  v_batch_limit_outer INT;
  v_batch_limit_inner INT;
  v_target_roles TEXT[];
  v_exclude_super_admin BOOLEAN;
  v_priority TEXT;
  v_ttl_hours INT;
  v_expires_hours INT; -- 2026-08-09 expiry
  v_learning_window_days INT;
  v_prioritize_emails TEXT[];
BEGIN
  v_cfg := fn_get_generator_config('unmarked_attendance', '{
    "category": "dashboard:anomaly",
    "time_gate_ist_hour": 11,
    "batch_limit_outer": 100,
    "batch_limit_inner": 50,
    "target_roles": ["director","principal","hod","admin"],
    "exclude_super_admin": true,
    "priority": "normal",
    "ttl_hours": 8,
    "expires_hours": 36,
    "learning_window_days": 14,
    "prioritize_emails": ["director@jkkn.ac.in"]
  }'::jsonb);

  v_category             := COALESCE(v_cfg->>'category', 'dashboard:anomaly');
  v_time_gate_ist_hour   := COALESCE((v_cfg->>'time_gate_ist_hour')::INT, 11);
  v_batch_limit_outer    := COALESCE((v_cfg->>'batch_limit_outer')::INT, 100);
  v_batch_limit_inner    := COALESCE((v_cfg->>'batch_limit_inner')::INT, 50);
  v_target_roles         := COALESCE(
                              ARRAY(SELECT jsonb_array_elements_text(v_cfg->'target_roles')),
                              ARRAY['director','principal','hod','admin']
                            );
  v_exclude_super_admin  := COALESCE((v_cfg->>'exclude_super_admin')::BOOLEAN, true);
  v_priority             := COALESCE(v_cfg->>'priority', 'normal');
  v_ttl_hours            := COALESCE((v_cfg->>'ttl_hours')::INT, 8);
  -- 2026-08-09 expiry: 36h = 1.5x the daily re-emit cycle. 0 (or any value <= 0)
  -- is the OFF switch: it maps to NULL = never expires, so the TTL can be
  -- withdrawn from generator config with no deploy. Without this mapping a 0 in
  -- config would mean "expire instantly", the opposite of what an operator
  -- typing 0 intends.
  v_expires_hours        := COALESCE((v_cfg->>'expires_hours')::INT, 36);
  IF v_expires_hours IS NOT NULL AND v_expires_hours <= 0 THEN
    v_expires_hours := NULL;
  END IF;
  v_learning_window_days := COALESCE((v_cfg->>'learning_window_days')::INT, 14);
  v_prioritize_emails    := COALESCE(
                              ARRAY(SELECT jsonb_array_elements_text(v_cfg->'prioritize_emails')),
                              ARRAY['director@jkkn.ac.in']
                            );

  IF EXTRACT(HOUR FROM (NOW() AT TIME ZONE 'Asia/Kolkata')) < v_time_gate_ist_hour THEN
    RETURN 0;
  END IF;

  FOR v_tt IN
    SELECT t.id, t.institution_id, t.section_id, t.timetable_name
    FROM timetables t
    WHERE t.is_active = TRUE AND t.start_date <= CURRENT_DATE
      AND (t.end_date IS NULL OR t.end_date >= CURRENT_DATE)
      AND NOT EXISTS (SELECT 1 FROM student_attendance sa
        WHERE sa.timetable_id = t.id AND sa.attendance_date = CURRENT_DATE)
      AND EXISTS (SELECT 1 FROM student_attendance sa2
        WHERE sa2.timetable_id = t.id
          AND sa2.attendance_date BETWEEN
            CURRENT_DATE - make_interval(days => v_learning_window_days)
            AND CURRENT_DATE - INTERVAL '1 day')
    LIMIT v_batch_limit_outer
  LOOP
    v_key := 'unmarked_attendance:' || v_tt.id::text || ':' || CURRENT_DATE::text;
    -- 2026-04-23 targeting fix: (a) LIMIT 50 was LIMIT 5 — cut director off;
    -- (b) no DISTINCT so ORDER BY by email works; (c) prioritize by email
    -- because director's profile.role='super_admin', NOT 'director'.
    -- Updated: 2026-04-24 - Exclude super_admin from per-item fanout.
    FOR v_target IN
      SELECT p.id AS uid, p.email, p.institution_id AS p_inst
      FROM profiles p
      WHERE p.institution_id = v_tt.institution_id
        AND (NOT v_exclude_super_admin OR p.is_super_admin = FALSE)
        AND p.role = ANY(v_target_roles)
      ORDER BY
        CASE WHEN p.email = ANY(v_prioritize_emails) THEN 0
             WHEN p.institution_id = v_tt.institution_id THEN 1
             ELSE 2 END,
        p.id
      LIMIT v_batch_limit_inner
    LOOP
      v_created := v_created + fn_create_dashboard_work_item(
        v_category, v_priority,
        'Attendance not marked today — ' || COALESCE(v_tt.timetable_name, 'Section timetable'),
        'No attendance rows for this timetable today as of ' || v_time_gate_ist_hour::text || 'am. Faculty may need a nudge.',
        jsonb_build_object('timetable_id', v_tt.id, 'section_id', v_tt.section_id,
          'url', '/academic/attendance/dashboard?timetable=' || v_tt.id::text),
        v_target.uid, v_key || ':' || v_target.uid::text, v_ttl_hours,
        v_expires_hours); -- 2026-08-09 expiry
    END LOOP;
  END LOOP;
  RETURN v_created;
END $function$;


-- Cron-only generator; anon/authenticated explicitly locked out (see above).
REVOKE EXECUTE ON FUNCTION public.fn_generate_unmarked_attendance_items() FROM anon, PUBLIC, authenticated;
GRANT  EXECUTE ON FUNCTION public.fn_generate_unmarked_attendance_items() TO service_role;

-- --------------------------------------------------------------------------------
-- 4. fn_accreditation_narrative_reminders --- 36h TTL on both daily nudges
-- --------------------------------------------------------------------------------
-- Both branches key on ':<YYYY-MM-DD>', so the same narrative is re-announced
-- every day it stays stuck. Measured 2026-08-09: 187 unread rows for the
-- Director, 46 distinct narratives behind them. Expiring yesterday's copy leaves
-- today's copy live and leaves /accreditation/naac/narratives untouched.
CREATE OR REPLACE FUNCTION public.fn_accreditation_narrative_reminders(p_nudge_days integer DEFAULT 3, p_escalate_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sys uuid;
  v_today text := to_char(now() AT TIME ZONE 'Asia/Kolkata', 'YYYY-MM-DD');
  v_nudged int := 0;
  v_escalated int := 0;
BEGIN
  SELECT id INTO v_sys FROM public.profiles WHERE is_super_admin = true ORDER BY created_at NULLS LAST LIMIT 1;
  IF v_sys IS NULL THEN RAISE EXCEPTION 'no system identity for notifications.created_by'; END IF;

  -- 1) NUDGE the owner of an actionable draft stuck > p_nudge_days -------------
  WITH stuck AS (
    SELECT n.id, n.owner_user_id AS uid, n.metric_code,
           'accred_narr_nudge:'||n.id::text||':'||v_today AS ik
    FROM public.accreditation_metric_narratives n
    WHERE n.owner_user_id IS NOT NULL
      AND ( (n.status = 'ai_drafted' AND n.grounding_verdict = 'grounded')
            OR n.status = 'revision_requested' )
      AND n.updated_at < now() - make_interval(days => GREATEST(0, p_nudge_days))
  ),
  created AS (
    INSERT INTO public.notifications
      -- 2026-08-09 expiry: expires_at added; 36h = 1.5x the daily re-emit cycle.
      (id, title, body, url, icon, priority, category, kind, idempotency_key, targeting, created_by, created_at, updated_at, expires_at)
    SELECT gen_random_uuid(),
      'NAAC narrative awaiting your review',
      'An AI-drafted NAAC narrative for metric '||s.metric_code||' is waiting for you to review and okay it.',
      '/accreditation/naac/narratives/'||s.id::text, 'FileText', 'normal', 'accreditation', 'work_item',
      s.ik, jsonb_build_object('type','user','user_ids', jsonb_build_array(s.uid)), v_sys, now(), now(),
      now() + interval '36 hours'
    FROM stuck s
    WHERE NOT EXISTS (SELECT 1 FROM public.notifications x WHERE x.idempotency_key = s.ik)
    RETURNING id, (targeting->'user_ids'->>0)::uuid AS uid
  ),
  fan AS (
    INSERT INTO public.user_notifications (id, notification_id, user_id, created_at)
    SELECT gen_random_uuid(), c.id, c.uid, now() FROM created c
    RETURNING 1
  )
  SELECT count(*) INTO v_nudged FROM fan;

  -- 2) ESCALATE a draft stuck > p_escalate_days to super-admin oversight -------
  WITH stuck2 AS (
    SELECT n.id, n.metric_code,
           'accred_narr_esc:'||n.id::text||':'||v_today AS ik
    FROM public.accreditation_metric_narratives n
    WHERE n.status IN ('ai_drafted','owner_okayed','principal_approved','revision_requested')
      AND ( n.status <> 'ai_drafted' OR n.grounding_verdict = 'grounded' )
      AND n.updated_at < now() - make_interval(days => GREATEST(1, p_escalate_days))
  ),
  created2 AS (
    INSERT INTO public.notifications
      -- 2026-08-09 expiry: expires_at added; 36h = 1.5x the daily re-emit cycle.
      (id, title, body, url, icon, priority, category, kind, idempotency_key, targeting, created_by, created_at, updated_at, expires_at)
    SELECT gen_random_uuid(),
      'Overdue NAAC narrative needs attention',
      'A NAAC narrative for metric '||s.metric_code||' has been waiting more than '||p_escalate_days||' days for review.',
      '/accreditation/naac/narratives/'||s.id::text, 'AlertTriangle', 'high', 'accreditation', 'work_item',
      s.ik, jsonb_build_object('type','role','roles', jsonb_build_array('super_admin')), v_sys, now(), now(),
      now() + interval '36 hours'
    FROM stuck2 s
    WHERE NOT EXISTS (SELECT 1 FROM public.notifications x WHERE x.idempotency_key = s.ik)
    RETURNING id
  ),
  fan2 AS (
    INSERT INTO public.user_notifications (id, notification_id, user_id, created_at)
    SELECT gen_random_uuid(), c.id, p.id, now()
    FROM created2 c CROSS JOIN public.profiles p WHERE p.is_super_admin = true
    RETURNING 1
  )
  SELECT count(*) INTO v_escalated FROM fan2;

  RETURN jsonb_build_object('nudged', v_nudged, 'escalated', v_escalated);
END; $function$;

-- Cron-only generator; anon/authenticated explicitly locked out (see above).
REVOKE EXECUTE ON FUNCTION public.fn_accreditation_narrative_reminders(integer, integer) FROM anon, PUBLIC, authenticated;
GRANT  EXECUTE ON FUNCTION public.fn_accreditation_narrative_reminders(integer, integer) TO service_role;

-- --------------------------------------------------------------------------------
-- 5. fn_generate_hr_command_center_brief_items --- 36h TTL on the daily HR brief
-- --------------------------------------------------------------------------------
-- Added 2026-08-09 in review: the first cut of this migration backfilled
-- dashboard:hr_brief but left its generator alone, so 34 of the Director's 35
-- rows would have lapsed and then ~1 unexpiring row per recipient per day would
-- have started accruing again (860 rows since 2026-04-28, newest today). Same
-- shape as the digest: key is 'hr_brief:<user>:<YYYY-MM-DD>', body is a snapshot
-- of TODAY's pending-leave / recruitment / holiday counts, re-emitted every day
-- by the hourly /api/cron/dashboard-work-items sweep. 36h = 1.5x that daily
-- re-key: it absorbs a late run, not a fully skipped day (36h < the 48h gap a
-- skipped day creates), which is a bounded at-most-12h under-count of the badge.
--
-- Body captured VERBATIM from production pg_get_functiondef 2026-08-09; the only
-- edit is the ninth argument on the fn_create_dashboard_work_item call.
CREATE OR REPLACE FUNCTION public.fn_generate_hr_command_center_brief_items()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_created INT := 0;
  v_user RECORD;
  v_today TEXT := TO_CHAR(CURRENT_DATE, 'YYYY-MM-DD');
  v_key TEXT;
  v_pending_leaves INT;
  v_active_recruitment INT;
  v_todays_holidays INT;
  v_staff_on_leave INT;
  v_total INT;
  v_priority TEXT;
  v_title TEXT;
  v_body TEXT;
  v_signal_parts TEXT[];
BEGIN
  -- Aggregate metrics ONCE (institution-wide, same as previous version)
  SELECT COUNT(*) INTO v_pending_leaves
  FROM hr_leave_applications la
  WHERE la.status = 'pending'
    AND la.created_at < NOW() - INTERVAL '24 hours'
    AND la.created_at > NOW() - INTERVAL '30 days'
    AND la.superseded_by IS NULL;

  SELECT COUNT(*) INTO v_active_recruitment
  FROM hr_recruitment_candidates
  WHERE status IN ('pending_approval', 'in_process', 'submitted')
    AND COALESCE(submitted_at, created_at) > NOW() - INTERVAL '30 days';

  SELECT COUNT(*) INTO v_todays_holidays
  FROM institution_leaves
  WHERE CURRENT_DATE BETWEEN start_date AND end_date
    AND status IN ('approved', 'active');

  SELECT COUNT(*) INTO v_staff_on_leave
  FROM hr_leave_applications
  WHERE status = 'approved'
    AND CURRENT_DATE BETWEEN start_date AND end_date
    AND superseded_by IS NULL;

  v_total := v_pending_leaves + v_active_recruitment + v_todays_holidays + v_staff_on_leave;

  IF v_total = 0 THEN
    RETURN 0;
  END IF;

  v_signal_parts := ARRAY[]::TEXT[];
  IF v_pending_leaves > 0 THEN
    v_signal_parts := v_signal_parts || (v_pending_leaves || ' pending leave(s)');
  END IF;
  IF v_active_recruitment > 0 THEN
    v_signal_parts := v_signal_parts || (v_active_recruitment || ' active recruitment');
  END IF;
  IF v_todays_holidays > 0 THEN
    v_signal_parts := v_signal_parts || (v_todays_holidays || ' holiday today');
  END IF;
  IF v_staff_on_leave > 0 THEN
    v_signal_parts := v_signal_parts || (v_staff_on_leave || ' staff on leave today');
  END IF;

  v_priority := CASE
    WHEN v_pending_leaves >= 5 OR v_todays_holidays > 0 THEN 'high'
    ELSE 'normal'
  END;

  v_title := 'HR brief — ' || array_to_string(v_signal_parts, ', ');
  v_body := 'Daily HR Command Center summary: ' || array_to_string(v_signal_parts, ', ') || '. Open /hr for full breakdown across institutions.';

  -- Fan out via config-driven recipient set
  FOR v_user IN SELECT user_id FROM get_digest_recipients('hr_command_brief')
  LOOP
    v_key := 'hr_brief:' || v_user.user_id::text || ':' || v_today;

    v_created := v_created + fn_create_dashboard_work_item(
      'dashboard:hr_brief',
      v_priority,
      v_title,
      v_body,
      jsonb_build_object(
        'url', '/hr',
        'digest', true,
        'pending_leaves', v_pending_leaves,
        'active_recruitment', v_active_recruitment,
        'todays_holidays', v_todays_holidays,
        'staff_on_leave', v_staff_on_leave,
        'total', v_total
      ),
      v_user.user_id,
      v_key,
      20,
      36); -- 2026-08-09 expiry: 36h, 1.5x the daily re-key
  END LOOP;

  RETURN v_created;
END
$function$;

-- Updated: 2026-08-17 - the `authenticated` grant flagged for follow-up above is
-- now REVOKED (migration 20260817030000). The caller sweep it asked for was done:
-- the only caller is the service-role cron app/api/cron/dashboard-work-items,
-- which reaches this function through fn_generate_all_dashboard_work_items --
-- SECURITY DEFINER, owner postgres -- so EXECUTE is checked against postgres and
-- the cron is unaffected. No .rpc() call exists under app/, lib/, components/ or
-- hooks/. The grant was harmful, not merely untidy: the brief is idempotency-keyed
-- per user per day, so any logged-in caller could burn the key and SUPPRESS the
-- real scheduled brief. anon/PUBLIC stay explicitly revoked -- Supabase's
-- ALTER DEFAULT PRIVILEGES would otherwise hand anon EXECUTE.
REVOKE EXECUTE ON FUNCTION public.fn_generate_hr_command_center_brief_items() FROM authenticated, anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_generate_hr_command_center_brief_items() TO service_role;

-- Campus Living — Settle Then Bill (Director 2026-08-09)
-- Added: 2026-08-09 (migration 20260815060000_hostel_settle_then_bill.sql —
-- FILE ONLY, apply is Director-gated). A hostel room is NOT billed at
-- move-in: a settle window lets the room fill (5 days, restarting on each
-- joiner, capped 20 days from first open, short-circuited when the room is
-- full), then every resident is billed at the occupancy that exists at that
-- moment. A later joiner produces CREDITS, never a refund or a bill rewrite.
-- The whole mechanism is OFF by default (hostel.settle_bill.enabled = false
-- in platform_policies).

-- 3b. fn_settle_can_manage — the authorization gate for everything below.
--
--     A SECURITY DEFINER function bypasses RLS, so the table policies above
--     protect nothing once these functions are granted. Without an explicit
--     guard inside each one, any logged-in learner in any tenant could call
--     fn_settle_bill_close('<any room uuid>', false) and bill a whole room, or
--     fn_settle_late_join_credit and mint credit rows. Each writer therefore
--     re-checks permission AND institution access for itself.
--
--     auth.uid() IS NULL means there is no user session — that is the cron on
--     the service-role client. It cannot be anon: anon holds EXECUTE on nothing
--     in this file and is revoked explicitly, with an apply-time assert.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_settle_can_manage(
  p_room_id    uuid,
  p_permission text DEFAULT 'campus_living.fees.config'
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_institution_id uuid;
BEGIN
  -- The cron bypass is deliberately NARROW. "No resolvable auth.uid()" alone is
  -- too broad: a token missing `sub`, a psql session holding EXECUTE, pg_cron,
  -- or a nested SECURITY DEFINER that reset request.jwt.claims would all land
  -- here and get unconditional cross-tenant write. The session role must ALSO
  -- name itself. If the deployed cron runtime reports some other role this gate
  -- refuses it — which is the correct direction to be wrong in: the mechanism
  -- is OFF and unwired, so a too-tight gate surfaces in the first dry run,
  -- whereas a too-loose one is a silent cross-tenant billing hole. Widen it
  -- deliberately after observing the real role, never pre-emptively.
  IF auth.uid() IS NULL THEN
    RETURN COALESCE(
             (NULLIF(current_setting('request.jwt.claims', true), '')::jsonb)->>'role',
             ''
           ) = 'service_role'
        OR COALESCE(current_setting('role', true), '') = 'service_role';
  END IF;

  IF is_super_admin() OR is_admin() THEN
    RETURN true;
  END IF;

  SELECT r.institution_id INTO v_institution_id
  FROM hostel_rooms r WHERE r.id = p_room_id;

  IF v_institution_id IS NULL THEN
    RETURN false;
  END IF;

  RETURN user_has_permission(p_permission)
     AND role_has_institution_access(v_institution_id);
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_settle_can_manage(uuid, text) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_settle_can_manage(uuid, text) TO authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 3c. fn_settle_current_hostel_year — deterministic, and refuses rather than
--     guessing. A NULL hostel_year_id on a bill would make the dedup key
--     against campus_living_generate_hostel_year_bills never match (NULL = NULL
--     is not true), which is a DOUBLE-BILL, so callers must refuse instead.
--     ORDER BY is load-bearing: LIMIT 1 with no ordering is whatever the
--     planner returns first.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_settle_current_hostel_year()
RETURNS uuid
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT hy.id
  FROM hostel_years hy
  WHERE hy.is_current AND hy.is_active
  ORDER BY hy.start_date DESC, hy.id
  LIMIT 1;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_settle_current_hostel_year() FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_settle_current_hostel_year() TO authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 4. fn_settle_room_annual_cost — the one place the room's annual cost is read.
--    Private helper. It exists so the rate lookup is not written three times
--    across open/close/credit and cannot drift between them.
--    Mirrors computeFeeBreakdown's inputs: per-bed annual rate × capacity, plus
--    the room's AC annual cost. Splitting by occupants is the caller's job.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_settle_room_annual_cost(
  p_room_id        uuid,
  p_hostel_year_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_capacity    int;
  v_category_id uuid;
  v_per_bed     numeric := 0;
  v_amount      numeric;
  v_frequency   text;
  v_ac_annual   numeric := 0;
  v_ac_tonnage  numeric := 0;
  v_ac_permonth numeric := 0;
  v_ac_config   jsonb;
BEGIN
  SELECT r.capacity, r.category_id INTO v_capacity, v_category_id
  FROM hostel_rooms r WHERE r.id = p_room_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('found', false, 'reason', 'room_not_found');
  END IF;

  IF v_category_id IS NULL THEN
    -- No category = no per-bed rate. Refuse rather than bill ₹0 silently.
    RETURN jsonb_build_object('found', false, 'reason', 'room_has_no_category',
                              'capacity', v_capacity);
  END IF;

  SELECT hf.amount, hf.frequency INTO v_amount, v_frequency
  FROM hostel_fees hf
  WHERE hf.hostel_category_id = v_category_id
    AND hf.hostel_year_id     = p_hostel_year_id
    AND hf.is_active
  LIMIT 1;

  IF v_amount IS NULL THEN
    RETURN jsonb_build_object('found', false, 'reason', 'no_active_fee_row',
                              'capacity', v_capacity, 'category_id', v_category_id);
  END IF;

  -- annualize() from hostel-fee-compute-service.ts.
  v_per_bed := CASE v_frequency
                 WHEN 'monthly'  THEN v_amount * 12
                 WHEN 'semester' THEN v_amount * 2
                 ELSE v_amount
               END;

  SELECT v.effective_config INTO v_ac_config
  FROM v_room_effective_billable_amenities v
  WHERE v.room_id = p_room_id AND v.code = 'air_conditioner'
  LIMIT 1;

  IF v_ac_config IS NOT NULL THEN
    v_ac_tonnage  := GREATEST(0, COALESCE((v_ac_config->>'tonnage')::numeric, 0));
    v_ac_permonth := GREATEST(0, COALESCE((v_ac_config->>'base_inr_per_month_24h')::numeric, 0));
    v_ac_annual   := v_ac_tonnage * v_ac_permonth * 12;
  END IF;

  -- The two AC primitives are returned alongside the product so the TS caller
  -- can feed computeFeeBreakdown its REAL inputs and check parity, rather than
  -- reverse-engineering them from the product.
  RETURN jsonb_build_object(
    'found',                true,
    'capacity',             GREATEST(1, COALESCE(v_capacity, 1)),
    'category_id',          v_category_id,
    'per_bed_annual_rate',  v_per_bed,
    'base_room_annual',     v_per_bed * GREATEST(1, COALESCE(v_capacity, 1)),
    'ac_room_annual',       v_ac_annual,
    'ac_tonnage',           v_ac_tonnage,
    'ac_base_inr_per_month_24h', v_ac_permonth
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_settle_room_annual_cost(uuid, uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_settle_room_annual_cost(uuid, uuid) TO authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 5. fn_settle_window_open — open, or restart, the room's settle window.
--    Rule 1 + 2 + 3. Called when a learner is allocated to the room.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_settle_window_open(p_room_id uuid, p_hostel_year_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_year_id  uuid;
  v_window   public.hostel_room_settle_windows%ROWTYPE;
  v_win_days int;
  v_outer    int;
  v_deadline timestamptz;
BEGIN
  -- Master switch. While off, no window is ever created, so switching it on
  -- later starts from a clean slate rather than a backlog of stale deadlines.
  IF NOT fn_get_policy_bool('hostel.settle_bill.enabled', false) THEN
    RETURN jsonb_build_object('action', 'disabled', 'room_id', p_room_id);
  END IF;

  -- Category opt-in. A room with no category can never be priced by
  -- fn_settle_room_annual_cost either, so it is excluded here too.
  IF NOT EXISTS (
    SELECT 1
    FROM hostel_rooms r
    JOIN hostel_categories hc ON hc.id = r.category_id
    WHERE r.id = p_room_id
      AND hc.settle_billing_enabled
  ) THEN
    RETURN jsonb_build_object('action', 'not_eligible', 'room_id', p_room_id);
  END IF;

  -- Opening/restarting a window delays billing, so it is gated too — but on the
  -- permission the people who actually allocate rooms hold, not the fees one.
  IF NOT (fn_settle_can_manage(p_room_id, 'campus_living.allocations.create')
          OR fn_settle_can_manage(p_room_id, 'campus_living.fees.config')) THEN
    RAISE EXCEPTION 'permission denied: campus_living.allocations.create or campus_living.fees.config on this room'
      USING ERRCODE = '42501';
  END IF;

  v_year_id := COALESCE(p_hostel_year_id, fn_settle_current_hostel_year());

  -- A room already billed for this year must NOT get a second window — that
  -- would bill everyone twice. This is the late-join credit path instead.
  SELECT * INTO v_window
  FROM hostel_room_settle_windows w
  WHERE w.room_id = p_room_id
    AND COALESCE(w.hostel_year_id, '00000000-0000-0000-0000-000000000000'::uuid)
        = COALESCE(v_year_id, '00000000-0000-0000-0000-000000000000'::uuid)
    AND w.status = 'billed'
  ORDER BY w.billed_at DESC NULLS LAST
  LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'action',    'already_billed_late_join',
      'room_id',   p_room_id,
      'window_id', v_window.id,
      'note',      'Room already billed — run fn_settle_late_join_credit.');
  END IF;

  v_win_days := GREATEST(0, fn_get_policy_int('hostel.settle_bill.window_days', 5));
  v_outer    := GREATEST(0, fn_get_policy_int('hostel.settle_bill.outer_limit_days', 20));

  SELECT * INTO v_window
  FROM hostel_room_settle_windows w
  WHERE w.room_id = p_room_id
    AND COALESCE(w.hostel_year_id, '00000000-0000-0000-0000-000000000000'::uuid)
        = COALESCE(v_year_id, '00000000-0000-0000-0000-000000000000'::uuid)
    AND w.status = 'open'
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO hostel_room_settle_windows
      (room_id, hostel_year_id, opened_at, restart_count,
       current_deadline, hard_deadline, status)
    VALUES
      (p_room_id, v_year_id, now(), 0,
       now() + make_interval(days => v_win_days),
       now() + make_interval(days => v_outer),
       'open')
    RETURNING * INTO v_window;

    RETURN jsonb_build_object(
      'action',           'opened',
      'room_id',          p_room_id,
      'window_id',        v_window.id,
      'restart_count',    v_window.restart_count,
      'current_deadline', v_window.current_deadline,
      'hard_deadline',    v_window.hard_deadline);
  END IF;

  -- Restart: push the deadline out, but never past the hard limit.
  v_deadline := LEAST(now() + make_interval(days => v_win_days), v_window.hard_deadline);

  UPDATE hostel_room_settle_windows
     SET restart_count    = restart_count + 1,
         current_deadline = v_deadline
   WHERE id = v_window.id
  RETURNING * INTO v_window;

  RETURN jsonb_build_object(
    'action',           'restarted',
    'room_id',          p_room_id,
    'window_id',        v_window.id,
    'restart_count',    v_window.restart_count,
    'current_deadline', v_window.current_deadline,
    'hard_deadline',    v_window.hard_deadline,
    'capped_at_hard_deadline', v_deadline = v_window.hard_deadline);
END;
$function$;

REVOKE EXECUTE ON FUNCTION public.fn_settle_window_open(uuid, uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_settle_window_open(uuid, uuid) TO authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 6. fn_settle_window_due — read-only. Which windows should close right now?
--    Rule 3 + 4 + 5. Occupancy comes from the canonical view, not a recount.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_settle_window_due()
 RETURNS TABLE(window_id uuid, room_id uuid, hostel_year_id uuid, reason text, active_occupants integer, capacity integer, opened_at timestamp with time zone, current_deadline timestamp with time zone, hard_deadline timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    w.id,
    w.room_id,
    w.hostel_year_id,
    -- 'room_full' is tested FIRST: rule 4 says a full room bills immediately
    -- because nothing more can change the price.
    CASE
      WHEN occ.capacity > 0 AND occ.active_residents >= occ.capacity THEN 'room_full'
      WHEN now() >= w.hard_deadline                                  THEN 'outer_limit'
      ELSE                                                                'window_elapsed'
    END,
    occ.active_residents,
    occ.capacity,
    w.opened_at,
    w.current_deadline,
    w.hard_deadline
  FROM hostel_room_settle_windows w
  JOIN v_hostel_room_occupancy occ ON occ.room_id = w.room_id
  WHERE w.status = 'open'
    AND (
      now() >= w.current_deadline
      OR now() >= w.hard_deadline
      OR (occ.capacity > 0 AND occ.active_residents >= occ.capacity)
    )
    -- Category opt-in, re-checked at close time. Switching a category off must
    -- STOP billing it, not let one last sweep through on windows already open.
    AND EXISTS (
      SELECT 1
      FROM hostel_rooms r
      JOIN hostel_categories hc ON hc.id = r.category_id
      WHERE r.id = w.room_id
        AND hc.settle_billing_enabled
    )
    -- Scoped: SECURITY DEFINER bypasses RLS, so without this the list would
    -- leak every institution's rooms to any authenticated caller.
    AND fn_settle_can_manage(w.room_id, 'campus_living.fees.view')
  ORDER BY w.current_deadline;
$function$;

REVOKE EXECUTE ON FUNCTION public.fn_settle_window_due() FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_settle_window_due() TO authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 6b. fn_settle_late_join_due — read-only. Which BILLED rooms owe a credit?
--
--     Rule 6 lives in a state fn_settle_window_due can never return: that
--     function filters status='open', but a late join only matters once the
--     window is 'billed'. Driving the credit pass off the close list would mean
--     no sweep ever issues a credit. This is that missing list.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_settle_late_join_due()
RETURNS TABLE (
  window_id            uuid,
  room_id              uuid,
  hostel_year_id       uuid,
  billed_at            timestamptz,
  occupants_at_billing int,
  uncredited_joiners   int
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT w.id, w.room_id, w.hostel_year_id, w.billed_at, w.occupants_at_billing,
         COUNT(al.id)::int
  FROM hostel_room_settle_windows w
  JOIN hostel_allocations al
    ON al.room_id = w.room_id
   AND al.check_out_date IS NULL
   AND al.created_at > w.billed_at
   AND NOT (al.id = ANY (w.credited_allocation_ids))
  WHERE w.status = 'billed'
    AND fn_settle_can_manage(w.room_id, 'campus_living.fees.view')
  GROUP BY w.id, w.room_id, w.hostel_year_id, w.billed_at, w.occupants_at_billing
  ORDER BY w.billed_at;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_settle_late_join_due() FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_settle_late_join_due() TO authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 7. fn_settle_bill_close — the biller. Rule 5.
--    Dry-run returns what WOULD be billed and writes nothing.
--    Live path bills every resident at the occupancy that exists right now.
--    Idempotent: a window already 'billed' is skipped, never billed twice.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_settle_bill_close(p_room_id uuid, p_dry_run boolean DEFAULT true, p_window_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_window     public.hostel_room_settle_windows%ROWTYPE;
  v_year_id    uuid;
  v_cost       jsonb;
  v_capacity   int;
  v_occupants  int;
  v_due_days   int;
  v_base_share numeric;
  v_ac_share   numeric;
  v_settled    numeric;
  v_per_bed    numeric;
  v_share      numeric;
  v_category   uuid;   -- hostel_categories.id — the ROOM's category
  v_bill_cat   uuid;   -- billing_categories.id — the revenue head
  v_lines      jsonb := '[]'::jsonb;
  v_billed     int := 0;
  v_skipped    int := 0;
  a            record;
  v_lp_id      uuid;
  v_inst_id    uuid;
  v_exists     boolean;
BEGIN
  -- Defense in depth: even a hand-made live call is refused while the master
  -- switch is off. The switch gates MONEY, not the practice run — a dry run
  -- writes nothing, so it must work while the mechanism is off.
  IF NOT p_dry_run AND NOT fn_get_policy_bool('hostel.settle_bill.enabled', false) THEN
    RAISE EXCEPTION 'settle-then-bill is disabled (platform policy hostel.settle_bill.enabled = false)'
      USING ERRCODE = '42501';
  END IF;

  IF NOT fn_settle_can_manage(p_room_id, 'campus_living.fees.config') THEN
    RAISE EXCEPTION 'permission denied: campus_living.fees.config on this room'
      USING ERRCODE = '42501';
  END IF;

  -- Bill the window the caller was handed, not "the oldest open one on this
  -- room". The unique index is per (room, hostel year), so a room with open
  -- windows in two hostel years would otherwise be billed against the wrong
  -- year — wrong rate, wrong dedup key — and the window that actually came due
  -- would be left open.
  SELECT * INTO v_window
  FROM hostel_room_settle_windows w
  WHERE w.room_id = p_room_id
    AND w.status = 'open'
    AND (p_window_id IS NULL OR w.id = p_window_id)
  ORDER BY w.opened_at
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    SELECT * INTO v_window
    FROM hostel_room_settle_windows w
    WHERE w.room_id = p_room_id AND w.status = 'billed'
    ORDER BY w.billed_at DESC NULLS LAST
    LIMIT 1;

    IF FOUND THEN
      RETURN jsonb_build_object('status', 'already_billed', 'room_id', p_room_id,
                                'window_id', v_window.id, 'billed_at', v_window.billed_at,
                                'occupants_at_billing', v_window.occupants_at_billing);
    END IF;
    RETURN jsonb_build_object('status', 'no_open_window', 'room_id', p_room_id);
  END IF;

  v_year_id := COALESCE(v_window.hostel_year_id, fn_settle_current_hostel_year());

  IF v_year_id IS NULL THEN
    RETURN jsonb_build_object('status', 'no_hostel_year', 'room_id', p_room_id,
                              'window_id', v_window.id);
  END IF;

  -- The revenue head must exist before anything is priced. Writing a NULL
  -- item_category_id would produce an unidentifiable bill that the dedup guard
  -- below could never match again, so refuse instead and leave the window open.
  v_bill_cat := fn_settle_billing_category();
  IF v_bill_cat IS NULL THEN
    RETURN jsonb_build_object('status', 'no_billing_category', 'room_id', p_room_id,
                              'window_id', v_window.id,
                              'reason', 'billing_categories row "Hostel Empty Bed Settlement" is missing or inactive');
  END IF;

  v_cost := fn_settle_room_annual_cost(p_room_id, v_year_id);
  IF NOT (v_cost->>'found')::boolean THEN
    -- Missing rate config: leave the window OPEN so an admin can fix the
    -- configuration and the room bills on the next sweep. Never bill ₹0.
    RETURN jsonb_build_object('status', 'no_rate', 'room_id', p_room_id,
                              'window_id', v_window.id, 'reason', v_cost->>'reason');
  END IF;

  v_capacity := (v_cost->>'capacity')::int;
  v_category := (v_cost->>'category_id')::uuid;
  v_per_bed  := (v_cost->>'per_bed_annual_rate')::numeric;

  -- Occupancy exactly as v_hostel_room_occupancy defines it.
  SELECT COUNT(*)::int INTO v_occupants
  FROM hostel_allocations al
  WHERE al.room_id = p_room_id AND al.check_out_date IS NULL;

  IF v_occupants = 0 THEN
    -- Everyone left before the window closed. There is nobody to bill; close it
    -- as cancelled so the sweep stops returning it forever.
    IF NOT p_dry_run THEN
      UPDATE hostel_room_settle_windows SET status = 'cancelled' WHERE id = v_window.id;
    END IF;
    RETURN jsonb_build_object('status', 'no_occupants', 'room_id', p_room_id,
                              'window_id', v_window.id, 'dry_run', p_dry_run);
  END IF;

  -- computeFeeBreakdown parity: each term rounded separately, then summed.
  v_base_share := round((v_cost->>'base_room_annual')::numeric / v_occupants);
  v_ac_share   := round((v_cost->>'ac_room_annual')::numeric   / v_occupants);
  v_settled    := v_base_share + v_ac_share;

  -- THE INCREMENT. She already carries one bed at the per-bed rate (admission
  -- fee structure + upgrade differential), so only the empty beds are new
  -- money. At full occupancy settled_share = per_bed exactly and this is 0.
  v_share := GREATEST(0, v_settled - v_per_bed);

  v_due_days := GREATEST(0, fn_get_policy_int('hostel.settle_bill.bill_due_days', 5));

  IF v_share <= 0 THEN
    -- Room is full (or the rate makes the empty beds free). Nothing is owed;
    -- close the window so the sweep stops returning it.
    IF NOT p_dry_run THEN
      UPDATE hostel_room_settle_windows
         SET status = 'billed', billed_at = now(), occupants_at_billing = v_occupants
       WHERE id = v_window.id;
    END IF;
    RETURN jsonb_build_object(
      'status',              'closed',
      'dry_run',             p_dry_run,
      'room_id',             p_room_id,
      'window_id',           v_window.id,
      'hostel_year_id',      v_year_id,
      'capacity',            v_capacity,
      'active_occupants',    v_occupants,
      'per_bed_annual_rate', v_per_bed,
      'base_room_annual',    (v_cost->>'base_room_annual')::numeric,
      'ac_room_annual',      (v_cost->>'ac_room_annual')::numeric,
      'ac_tonnage',          (v_cost->>'ac_tonnage')::numeric,
      'ac_base_inr_per_month_24h', (v_cost->>'ac_base_inr_per_month_24h')::numeric,
      'base_share',          v_base_share,
      'ac_share',            v_ac_share,
      'settled_share',       v_settled,
      'share_per_resident',  0,
      'due_date',            (now() + make_interval(days => v_due_days))::date,
      'billed_count',        0,
      'skipped_count',       0,
      'reason',              'nothing_to_settle',
      'lines',               '[]'::jsonb);
  END IF;

  FOR a IN
    SELECT al.id AS allocation_id, al.learner_id
    FROM hostel_allocations al
    WHERE al.room_id = p_room_id AND al.check_out_date IS NULL
    ORDER BY al.check_in_date, al.id
  LOOP
    -- profiles(id) -> learners_profiles(id). Non-learner residents cannot be
    -- billed through the learner billing tables; they are reported, not billed.
    v_lp_id := NULL;
    IF a.learner_id IS NOT NULL THEN
      SELECT p.learner_id INTO v_lp_id FROM profiles p WHERE p.id = a.learner_id;
    END IF;

    IF v_lp_id IS NULL THEN
      v_skipped := v_skipped + 1;
      v_lines := v_lines || jsonb_build_object(
        'allocation_id', a.allocation_id, 'profile_id', a.learner_id,
        'action', 'skipped', 'reason', 'not_a_learner', 'amount', 0);
      CONTINUE;
    END IF;

    SELECT lp.institution_id INTO v_inst_id
    FROM learners_profiles lp WHERE lp.id = v_lp_id;

    -- A learner on a FLAT PACKAGE is not settle-billable at all: her hostel fee
    -- is one bundled package price that does not divide by occupancy. Detected
    -- by asking the canonical resolver rather than re-deriving its
    -- package-matching rules.
    SELECT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(
             COALESCE(campus_living_resolve_hostel_fee(v_lp_id, v_year_id), '[]'::jsonb)
           ) AS itm
      WHERE itm->>'fee_source' = 'hostel_package'
    ) INTO v_exists;

    IF v_exists THEN
      v_skipped := v_skipped + 1;
      v_lines := v_lines || jsonb_build_object(
        'allocation_id', a.allocation_id, 'learner_id', v_lp_id,
        'action', 'skipped', 'reason', 'flat_package', 'amount', 0);
      CONTINUE;
    END IF;

    -- Dedup on the SETTLEMENT head, in its own id domain. The previous version
    -- compared a hostel_categories.id against item_category_id
    -- (billing_categories.id) and so was always false — it could not see its own
    -- prior bills. It also matched fee_source 'academic', which would now skip
    -- every learner holding an upgrade differential, i.e. everyone in a premium
    -- room. Scoped tightly to what THIS function writes.
    SELECT EXISTS (
      SELECT 1 FROM billing_student_bills b
      WHERE b.student_id       = v_lp_id
        AND b.hostel_year_id   = v_year_id
        AND b.item_category_id = v_bill_cat
        AND b.fee_source       = 'hostel_category'
        AND b.status NOT IN ('cancelled','superseded')
    ) INTO v_exists;

    IF v_exists THEN
      v_skipped := v_skipped + 1;
      v_lines := v_lines || jsonb_build_object(
        'allocation_id', a.allocation_id, 'learner_id', v_lp_id,
        'action', 'skipped', 'reason', 'already_billed', 'amount', 0);
      CONTINUE;
    END IF;

    IF NOT p_dry_run THEN
      INSERT INTO billing_student_bills
        (student_id, institution_id, item_category_id, hostel_year_id, fee_source,
         bill_description, due_date, quantity, unit_amount, total_amount,
         final_amount, balance_amount, status)
      VALUES
        (v_lp_id, v_inst_id, v_bill_cat, v_year_id, 'hostel_category',
         'Hostel empty-bed settlement: ' || (v_capacity - v_occupants)
           || ' of ' || v_capacity || ' beds empty at ' || v_occupants || ' occupant'
           || CASE WHEN v_occupants = 1 THEN '' ELSE 's' END,
         (now() + make_interval(days => v_due_days))::date,
         1, v_share, v_share, v_share, v_share, 'unpaid');
    END IF;

    v_billed := v_billed + 1;
    v_lines := v_lines || jsonb_build_object(
      'allocation_id', a.allocation_id, 'learner_id', v_lp_id,
      'action', CASE WHEN p_dry_run THEN 'would_bill' ELSE 'billed' END,
      'amount', v_share);
  END LOOP;

  IF NOT p_dry_run THEN
    UPDATE hostel_room_settle_windows
       SET status = 'billed', billed_at = now(), occupants_at_billing = v_occupants
     WHERE id = v_window.id;
  END IF;

  RETURN jsonb_build_object(
    'status',              'closed',
    'dry_run',             p_dry_run,
    'room_id',             p_room_id,
    'window_id',           v_window.id,
    'hostel_year_id',      v_year_id,
    'capacity',            v_capacity,
    'active_occupants',    v_occupants,
    'hostel_category_id',  v_category,
    'billing_category_id', v_bill_cat,
    'per_bed_annual_rate', v_per_bed,
    'base_room_annual',    (v_cost->>'base_room_annual')::numeric,
    'ac_room_annual',      (v_cost->>'ac_room_annual')::numeric,
    'ac_tonnage',          (v_cost->>'ac_tonnage')::numeric,
    'ac_base_inr_per_month_24h', (v_cost->>'ac_base_inr_per_month_24h')::numeric,
    'base_share',          v_base_share,
    'ac_share',            v_ac_share,
    -- settled_share is what she would owe for the room in total at this
    -- occupancy; share_per_resident is what is actually BILLED, i.e. the empty
    -- beds only. The TS parity gate re-derives the first and subtracts the
    -- per-bed rate to reach the second.
    'settled_share',       v_settled,
    'share_per_resident',  v_share,
    'due_date',            (now() + make_interval(days => v_due_days))::date,
    'billed_count',        v_billed,
    'skipped_count',       v_skipped,
    'lines',               v_lines);
END;
$function$;

REVOKE EXECUTE ON FUNCTION public.fn_settle_bill_close(uuid, boolean, uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_settle_bill_close(uuid, boolean, uuid) TO authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 8. fn_settle_late_join_credit — rule 6.
--    A learner joined a room that was ALREADY billed. Every resident who was
--    billed gets the difference between the old share and the new share, for
--    the months remaining from the month of joining, as a CREDIT. Never a
--    refund, never a bill rewrite.
--
--    IDEMPOTENCY is recorded EXPLICITLY, on the window's
--    credited_allocation_ids array — not inferred from the existence of credit
--    rows. Inferring it was wrong: any round that writes zero rows (the credit
--    rounds to 0, every co-resident is unbilled) would be re-processed forever
--    while the denominator had already moved on, double-crediting the same
--    occupancy step. The joiner's allocation id is still stamped on
--    student_credit_balances.source_event_id for the audit trail; it is no
--    longer the guard. (A partial unique index was considered and rejected: the
--    admission fee-change writer shares source='fee_structure_change' and can
--    emit more than one row per (learner, event).)
--
--    DENOMINATORS COME FROM LIVE COUNTS. Walking up from a stored
--    occupants_at_billing ignores anyone who checked out after billing: a room
--    that lost one resident and gained one is unchanged in size and owes no
--    credit at all, but a stored-count walk would pay one out and over-state
--    every later step. So the walk ends at the CURRENT active-occupant count
--    and steps back one per uncredited joiner.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_settle_late_join_credit(p_room_id uuid, p_dry_run boolean DEFAULT true, p_window_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_window       public.hostel_room_settle_windows%ROWTYPE;
  v_year_id      uuid;
  v_year_end     date;
  v_cost         jsonb;
  v_bill_cat     uuid;
  v_base         numeric;
  v_ac           numeric;
  v_n_billed     int;
  v_n_before     int;
  v_n_after      int;
  v_live         int;
  v_entitlement  numeric := 0;
  v_already      numeric;
  v_processed    uuid[] := '{}'::uuid[];
  v_share_before numeric;
  v_share_after  numeric;
  v_delta        numeric;
  v_remaining    int;
  v_credit       numeric;
  v_events       jsonb := '[]'::jsonb;
  v_credits      jsonb;
  v_written      int := 0;
  j              record;
  r              record;
  v_lp_id        uuid;
BEGIN
  IF NOT p_dry_run AND NOT fn_get_policy_bool('hostel.settle_bill.enabled', false) THEN
    RAISE EXCEPTION 'settle-then-bill is disabled (platform policy hostel.settle_bill.enabled = false)'
      USING ERRCODE = '42501';
  END IF;

  IF NOT fn_settle_can_manage(p_room_id, 'campus_living.fees.config') THEN
    RAISE EXCEPTION 'permission denied: campus_living.fees.config on this room'
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_window
  FROM hostel_room_settle_windows w
  WHERE w.room_id = p_room_id
    AND w.status = 'billed'
    AND (p_window_id IS NULL OR w.id = p_window_id)
  ORDER BY w.billed_at DESC NULLS LAST
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'no_billed_window', 'room_id', p_room_id);
  END IF;

  v_year_id := COALESCE(v_window.hostel_year_id, fn_settle_current_hostel_year());
  SELECT hy.end_date INTO v_year_end FROM hostel_years hy WHERE hy.id = v_year_id;
  IF v_year_end IS NULL THEN
    RETURN jsonb_build_object('status', 'no_hostel_year', 'room_id', p_room_id,
                              'window_id', v_window.id);
  END IF;

  v_bill_cat := fn_settle_billing_category();
  IF v_bill_cat IS NULL THEN
    RETURN jsonb_build_object('status', 'no_billing_category', 'room_id', p_room_id,
                              'window_id', v_window.id);
  END IF;

  v_cost := fn_settle_room_annual_cost(p_room_id, v_year_id);
  IF NOT (v_cost->>'found')::boolean THEN
    RETURN jsonb_build_object('status', 'no_rate', 'room_id', p_room_id,
                              'window_id', v_window.id, 'reason', v_cost->>'reason');
  END IF;
  v_base := (v_cost->>'base_room_annual')::numeric;
  v_ac   := (v_cost->>'ac_room_annual')::numeric;

  SELECT COUNT(*)::int INTO v_live
  FROM hostel_allocations al
  WHERE al.room_id = p_room_id AND al.check_out_date IS NULL;

  v_n_billed := GREATEST(1, COALESCE(v_window.occupants_at_billing, 1));

  FOR j IN
    SELECT al.id AS allocation_id,
           COALESCE(al.check_in_date, al.created_at::date) AS join_date,
           al.created_at,
           NOT (al.id = ANY (v_window.credited_allocation_ids)) AS is_new
    FROM hostel_allocations al
    WHERE al.room_id = p_room_id
      AND al.check_out_date IS NULL
      AND al.created_at > v_window.billed_at
    ORDER BY al.created_at, al.id
  LOOP
    SELECT COUNT(*)::int INTO v_n_after
    FROM hostel_allocations al
    WHERE al.room_id = p_room_id
      AND al.created_at <= j.created_at
      AND (al.check_out_date IS NULL OR al.check_out_date > j.created_at::date);

    v_n_after  := GREATEST(1, v_n_after);
    v_n_before := GREATEST(v_n_billed, v_n_after - 1);
    v_n_after  := GREATEST(v_n_billed, v_n_after);

    v_share_before := round(v_base / v_n_before) + round(v_ac / v_n_before);
    v_share_after  := round(v_base / v_n_after)  + round(v_ac / v_n_after);
    v_delta        := GREATEST(0, v_share_before - v_share_after);

    v_remaining := (
      (EXTRACT(YEAR FROM v_year_end)::int * 12 + EXTRACT(MONTH FROM v_year_end)::int)
      - (EXTRACT(YEAR FROM j.join_date)::int * 12 + EXTRACT(MONTH FROM j.join_date)::int)
    ) + 1;
    v_remaining := GREATEST(0, LEAST(12, v_remaining));

    v_entitlement := v_entitlement + round(v_delta * v_remaining / 12.0);

    IF j.is_new THEN
      v_processed := v_processed || j.allocation_id;
    END IF;

    v_events := v_events || jsonb_build_object(
      'joiner_allocation_id', j.allocation_id,
      'joined_on',            j.join_date,
      'newly_processed',      j.is_new,
      'occupants_before',     v_n_before,
      'occupants_after',      v_n_after,
      'share_before',         v_share_before,
      'share_after',          v_share_after,
      'delta_annual',         v_delta,
      'remaining_months',     v_remaining,
      'contribution',         round(v_delta * v_remaining / 12.0));
  END LOOP;

  v_credits := '[]'::jsonb;

  IF v_entitlement > 0 THEN
    FOR r IN
      SELECT al.id AS allocation_id, al.learner_id
      FROM hostel_allocations al
      WHERE al.room_id = p_room_id
        AND al.check_out_date IS NULL
        AND al.created_at <= v_window.billed_at
      ORDER BY al.check_in_date, al.id
    LOOP
      v_lp_id := NULL;
      IF r.learner_id IS NOT NULL THEN
        SELECT p.learner_id INTO v_lp_id FROM profiles p WHERE p.id = r.learner_id;
      END IF;
      CONTINUE WHEN v_lp_id IS NULL;

      -- Only residents who actually hold a settlement bill for this room can be
      -- credited against it. Compared on the settlement head, in its own id
      -- domain — the previous predicate used the hostel category id and so was
      -- never true, silently skipping every resident.
      CONTINUE WHEN NOT EXISTS (
        SELECT 1 FROM billing_student_bills b
        WHERE b.student_id       = v_lp_id
          AND b.hostel_year_id   = v_year_id
          AND b.item_category_id = v_bill_cat
          AND b.fee_source       = 'hostel_category'
          AND b.status NOT IN ('cancelled','superseded')
      );

      SELECT COALESCE(SUM(scb.amount), 0) INTO v_already
      FROM student_credit_balances scb
      WHERE scb.student_id = v_lp_id
        AND scb.source     = 'fee_structure_change'
        AND scb.source_event_id = ANY (v_window.credited_allocation_ids || v_processed);

      v_credit := GREATEST(0, v_entitlement - v_already);
      CONTINUE WHEN v_credit <= 0;

      IF NOT p_dry_run THEN
        INSERT INTO student_credit_balances
          (student_id, amount, source, source_event_id, is_consumed, notes)
        VALUES
          (v_lp_id, v_credit, 'fee_structure_change',
           COALESCE(v_processed[1], v_window.id), false,
           'Campus living settle-then-bill late join: billed at ' || v_n_billed
           || ' occupant(s), room now holds ' || v_live
           || '. Entitlement Rs ' || v_entitlement || ' less Rs ' || v_already
           || ' already credited = Rs ' || v_credit || '.');
        v_written := v_written + 1;
      END IF;

      v_credits := v_credits || jsonb_build_object(
        'learner_id', v_lp_id, 'allocation_id', r.allocation_id,
        'already_credited', v_already, 'amount', v_credit);
    END LOOP;
  END IF;

  IF NOT p_dry_run AND array_length(v_processed, 1) IS NOT NULL THEN
    UPDATE hostel_room_settle_windows
       SET credited_allocation_ids = credited_allocation_ids || v_processed
     WHERE id = v_window.id;
  END IF;

  RETURN jsonb_build_object(
    'status',         'ok',
    'dry_run',        p_dry_run,
    'room_id',        p_room_id,
    'window_id',      v_window.id,
    'hostel_year_id', v_year_id,
    'billed_at',      v_window.billed_at,
    'occupants_at_billing', v_n_billed,
    'active_occupants',     v_live,
    'entitlement_per_resident', v_entitlement,
    'credits',        v_credits,
    'hostel_year_end_date', v_year_end,
    'capacity',            (v_cost->>'capacity')::int,
    'per_bed_annual_rate', (v_cost->>'per_bed_annual_rate')::numeric,
    'base_room_annual',    v_base,
    'ac_room_annual',      v_ac,
    'ac_tonnage',          (v_cost->>'ac_tonnage')::numeric,
    'ac_base_inr_per_month_24h', (v_cost->>'ac_base_inr_per_month_24h')::numeric,
    'events',         v_events,
    'events_processed', COALESCE(array_length(v_processed, 1), 0),
    'credits_written', v_written);
END;
$function$;

REVOKE EXECUTE ON FUNCTION public.fn_settle_late_join_credit(uuid, boolean, uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_settle_late_join_credit(uuid, boolean, uuid) TO authenticated, service_role;


-- ============================================================================
-- Campus Living — settle-then-bill: start the clock on every move-in.
-- Added: 2026-08-10 (migration 20260815070000_settle_window_trigger_and_scope.sql
--        — FILE ONLY, apply is Director-gated)
--
-- Trigger body for trg_allocation_settle_arrival_insert / _update (04_triggers.sql).
-- Director 2026-08-10: ARRIVALS ONLY. A learner joining a room starts or
-- restarts that room's settle clock; a learner LEAVING never touches a clock,
-- because a departure must not postpone the remaining residents' bills. A
-- learner who moves from room A to room B leaves A's clock alone and starts or
-- restarts B's — she is only ever billed for where she ends up.
--
-- SECURITY DEFINER is load-bearing: a plain trigger runs under the writer's own
-- RLS, and RLS denial is silent (0 rows, no error), so the window lookup inside
-- fn_settle_window_open would read nothing and the clock would silently fail to
-- restart for exactly the callers whose RLS is narrowest.
--
-- The EXCEPTION block is load-bearing too: fn_settle_window_open RAISEs 42501
-- when the writer holds no campus-living permission, and the whole settle
-- schema may be absent on an environment where the engine migration has not
-- been applied. An AFTER trigger that raises ABORTS THE INSERT — a learner
-- would fail to get a bed because a billing window could not be opened.
-- Placing a learner in a bed outranks opening a billing window.
--
-- The hostel year is resolved INSIDE fn_settle_window_open (it COALESCEs a NULL
-- to fn_settle_current_hostel_year()); one resolver means the trigger can never
-- disagree with the close and credit paths about which year a window belongs to.
-- ============================================================================
CREATE OR REPLACE FUNCTION public._on_allocation_settle_arrival()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
BEGIN
  -- Arrival-only is enforced by the triggers' WHEN clauses; by the time this
  -- body runs, NEW is an active occupancy of a room it was not already
  -- actively occupying.
  BEGIN
    PERFORM fn_settle_window_open(NEW.room_id);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING
      '[campus-living] settle window not opened for room % (allocation %): % [%]',
      NEW.room_id, NEW.id, SQLERRM, SQLSTATE;
  END;

  RETURN NULL;  -- AFTER trigger: the return value is ignored.
END;
$function$;

-- No GRANT TO authenticated on purpose: no legitimate direct caller, only the
-- two triggers. Revoked anyway per the CLAUDE.md rule and the CI gate.
REVOKE EXECUTE ON FUNCTION public._on_allocation_settle_arrival() FROM anon, PUBLIC;

COMMENT ON FUNCTION public._on_allocation_settle_arrival() IS
  'Starts or restarts a room''s settle window when a learner ARRIVES in it '
  '(Director 2026-08-10). Departures never touch a clock. Failures are warned '
  'and swallowed — placing a learner in a bed outranks opening a billing '
  'window. Inert while hostel.settle_bill.enabled is false.';

-- ============================================================================
-- fn_settle_can_manage — 2026-08-10: SUPERSEDES THE DEFINITION ABOVE.
-- (migration 20260815070000_settle_window_trigger_and_scope.sql — FILE ONLY,
--  apply is Director-gated)
--
-- The definition above returns true on `is_super_admin() OR is_admin()` BEFORE
-- it reads the room's institution, so any admin-flagged person could bill rooms
-- in a college that is not theirs — and because every settle writer and both
-- settle read lists route through this one function, that branch was the
-- engine's entire cross-tenant surface. 45 lines before, 56 after; the only
-- behavioural change is that a PLAIN is_admin() must now also satisfy
-- role_has_institution_access() on the room's institution. is_super_admin()
-- keeps unconditional reach (platform owner), including on a room that does
-- not exist, so its answer is byte-for-byte what it was. The service_role cron
-- bypass is unchanged — it was deliberately narrowed in PR #2954 and its
-- reasoning is reproduced verbatim below.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.fn_settle_can_manage(
  p_room_id    uuid,
  p_permission text DEFAULT 'campus_living.fees.config'
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_institution_id uuid;
BEGIN
  -- The cron bypass is deliberately NARROW. "No resolvable auth.uid()" alone is
  -- too broad: a token missing `sub`, a psql session holding EXECUTE, pg_cron,
  -- or a nested SECURITY DEFINER that reset request.jwt.claims would all land
  -- here and get unconditional cross-tenant write. The session role must ALSO
  -- name itself. If the deployed cron runtime reports some other role this gate
  -- refuses it — which is the correct direction to be wrong in: the mechanism
  -- is OFF and unwired, so a too-tight gate surfaces in the first dry run,
  -- whereas a too-loose one is a silent cross-tenant billing hole. Widen it
  -- deliberately after observing the real role, never pre-emptively.
  IF auth.uid() IS NULL THEN
    RETURN COALESCE(
             (NULLIF(current_setting('request.jwt.claims', true), '')::jsonb)->>'role',
             ''
           ) = 'service_role'
        OR COALESCE(current_setting('role', true), '') = 'service_role';
  END IF;

  -- 2026-08-10: the room's institution is resolved BEFORE the admin branch.
  -- It used to be read after it, which is precisely why the admin branch could
  -- not be scoped.
  SELECT r.institution_id INTO v_institution_id
  FROM hostel_rooms r WHERE r.id = p_room_id;

  -- Platform owner: unconditional, and above the NULL-room test so a super
  -- admin's answer is byte-for-byte what it was before this change.
  IF is_super_admin() THEN
    RETURN true;
  END IF;

  IF v_institution_id IS NULL THEN
    RETURN false;
  END IF;

  -- 2026-08-10: a plain admin is an admin OF SOMEWHERE. Scoped to the room's
  -- institution, exactly like the permission path below.
  IF is_admin() THEN
    RETURN role_has_institution_access(v_institution_id);
  END IF;

  RETURN user_has_permission(p_permission)
     AND role_has_institution_access(v_institution_id);
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_settle_can_manage(uuid, text) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_settle_can_manage(uuid, text) TO authenticated, service_role;


-- ============================================================================
-- Updated: 2026-08-02 - Added fn_link_referral_referrer + fn_list_unlinked_consultant_referrals (unlinked referral linking)
-- Powers the admission "Unlinked Referrals" cleanup screen. 39 of the 2026-27
-- consultant-type referrals have referral_type='consultant' but referred_by_id
-- IS NULL, so fn_generate_referral_commissions silently skips them. These two
-- SECURITY DEFINER RPCs let an admission admin attach the correct
-- education_consultant WRITE-ONCE (never overwrite an existing link) and list
-- the unlinked rows with any pre-existing lead-sync attribution surfaced so the
-- UI can warn on a conflict before committing. Mirrors the migration
-- supabase/migrations/20260818010000_referral_link_referrer_rpc.sql.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_link_referral_referrer(
  p_learner_profile_id uuid,
  p_consultant_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_ref_type text;
  v_current  uuid;
  v_rows     int;
  v_conflict uuid;
BEGIN
  -- gate: admission-edit admins only (same gate as fn_enrich_referral_import_batch)
  IF NOT (is_super_admin() OR is_admin() OR user_has_permission('admission.leads.edit')) THEN
    RAISE EXCEPTION 'Not authorised to link referrals';
  END IF;

  IF p_consultant_id IS NULL OR NOT EXISTS (
       SELECT 1 FROM education_consultants WHERE id = p_consultant_id AND status = 'active') THEN
    RETURN jsonb_build_object('success', false, 'error', 'consultant_not_found_or_inactive');
  END IF;

  SELECT referral_type, referred_by_id INTO v_ref_type, v_current
    FROM learners_profiles WHERE id = p_learner_profile_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'learner_not_found');
  END IF;
  IF v_ref_type IS DISTINCT FROM 'consultant' THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_a_consultant_referral');
  END IF;
  IF v_current IS NOT NULL THEN
    -- write-once: already linked; refuse rather than overwrite (would delete prior attribution)
    RETURN jsonb_build_object('success', false, 'error', 'already_linked',
                              'referred_by_id', v_current);
  END IF;

  -- report (do not block) an existing attribution to a DIFFERENT consultant
  SELECT consultant_id INTO v_conflict
    FROM consultant_lead_attributions
   WHERE learner_profile_id = p_learner_profile_id
     AND consultant_id <> p_consultant_id
   LIMIT 1;

  -- atomic write-once set
  UPDATE learners_profiles
     SET referred_by_id = p_consultant_id
   WHERE id = p_learner_profile_id
     AND referred_by_id IS NULL
     AND referral_type = 'consultant';
  GET DIAGNOSTICS v_rows = ROW_COUNT;

  IF v_rows = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'link_race_lost');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'learner_profile_id', p_learner_profile_id,
    'consultant_id', p_consultant_id,
    'had_conflicting_attribution', v_conflict IS NOT NULL,
    'conflicting_consultant_id', v_conflict
  );
END;
$function$;

REVOKE EXECUTE ON FUNCTION public.fn_link_referral_referrer(uuid, uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_link_referral_referrer(uuid, uuid) TO authenticated;


-- Read side: list the unlinked consultant-type referrals for a year, with any pre-existing
-- attribution surfaced so the UI can warn on a conflict before linking.
CREATE OR REPLACE FUNCTION public.fn_list_unlinked_consultant_referrals(p_year integer)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT (is_super_admin() OR is_admin()
          OR user_has_permission('admission.leads.view')
          OR user_has_permission('admission.leads.edit')) THEN
    RAISE EXCEPTION 'Not authorised to view unlinked referrals';
  END IF;

  SELECT COALESCE(jsonb_agg(r ORDER BY r->>'learner_name'), '[]'::jsonb) INTO v
  FROM (
    SELECT jsonb_build_object(
      'learner_profile_id', lp.id,
      'learner_name', nullif(trim(coalesce(lp.first_name,'') || ' ' || coalesce(lp.last_name,'')), ''),
      'referred_by_name', lp.referred_by_name,
      'program_id', lp.program_id,
      'program_name', pr.program_name,
      'institution_id', lp.institution_id,
      'institution_name', ins.name,
      'existing_attribution_consultant_id', ca.consultant_id,
      'existing_attribution_consultant_name', ec.name
    ) AS r
    FROM learners_profiles lp
    JOIN admission_years ay  ON ay.id  = lp.admission_year_id AND ay.year = p_year
    LEFT JOIN programs pr     ON pr.id  = lp.program_id
    LEFT JOIN institutions ins ON ins.id = lp.institution_id
    LEFT JOIN LATERAL (
      SELECT a.consultant_id FROM consultant_lead_attributions a
       WHERE a.learner_profile_id = lp.id LIMIT 1
    ) ca ON true
    LEFT JOIN education_consultants ec ON ec.id = ca.consultant_id
    WHERE lp.referral_type = 'consultant'
      AND lp.referred_by_id IS NULL
  ) s;

  RETURN v;
END;
$function$;

REVOKE EXECUTE ON FUNCTION public.fn_list_unlinked_consultant_referrals(integer) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_list_unlinked_consultant_referrals(integer) TO authenticated;

-- =====================================================
-- HR ACADEMIC YEARS (2026-08-10)
-- =====================================================
-- Defaults hr_leave_applications.hr_academic_year_id from start_date. Possible
-- only because HR years are group-wide and non-overlapping, so exactly one year
-- contains any given day -- the per-institution predecessor could not do this.
CREATE OR REPLACE FUNCTION public.hr_trig_default_hr_academic_year()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF NEW.hr_academic_year_id IS NULL THEN
    -- Aliased: unqualified start_date/end_date would sit next to NEW.start_date
    -- and read ambiguously.
    SELECT y.id INTO NEW.hr_academic_year_id
    FROM public.hr_academic_years y
    WHERE y.is_active AND NEW.start_date BETWEEN y.start_date AND y.end_date;
  END IF;
  RETURN NEW;
END $function$;

-- ============================================================================
-- fn_activate_learner_from_onboarding (2026-08-10)
-- ----------------------------------------------------------------------------
-- Onboarding activation: admitted -> active once the four required fields are
-- set. Refuses 'reserved' outright (that status is payment-gated and only
-- evaluate_learner_status_after_payment may promote it). SECURITY DEFINER
-- because learners_profile_status_history has RLS with a SELECT policy and NO
-- INSERT policy, so the audit row is unwritable from a client session — DEFINER
-- is used to reach that table, NEVER to widen who may act, which is why the
-- authorisation block below re-applies learners_profiles_update_policy by hand.
-- The caller must still provision the login via POST /api/learners/complete-onboarding;
-- sync_learner_status_to_profile only flips is_active on an EXISTING profiles row.
-- Source of truth: supabase/migrations/20260810070549_activate_learner_from_onboarding_mirror_update_rls.sql
-- ============================================================================
CREATE OR REPLACE FUNCTION public.fn_activate_learner_from_onboarding(p_learner_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
DECLARE
  v_status lifecycle_status; v_email text; v_ay uuid; v_sem uuid; v_sec uuid;
  v_institution uuid;
  v_paid_pct numeric; v_threshold numeric; v_actor uuid := auth.uid(); v_updated integer := 0;
BEGIN
  SELECT lp.lifecycle_status, lp.college_email, lp.academic_year_id, lp.semester_id,
         lp.section_id, lp.institution_id
    INTO v_status, v_email, v_ay, v_sem, v_sec, v_institution
  FROM public.learners_profiles lp WHERE lp.id = p_learner_id;

  IF v_status IS NULL THEN
    RETURN jsonb_build_object('activated', false, 'reason', 'not_found', 'message', 'Learner not found.');
  END IF;

  -- Byte-for-byte learners_profiles_update_policy. Gating on
  -- 'learners.onboarding.edit' instead would be WEAKER, not stronger: that key
  -- is granted to 68 roles here, Student and Parent among them.
  IF NOT (
    COALESCE(is_super_admin(), false)
    OR COALESCE(is_admin(), false)
    OR (
      role_has_institution_access(v_institution)
      AND (
        COALESCE(user_has_permission('learners.admissions.edit'::text), false)
        OR COALESCE(user_has_permission('learners.profiles.edit'::text), false)
        OR COALESCE(user_has_permission('learners.edit'::text), false)
      )
    )
  ) THEN
    RETURN jsonb_build_object('activated', false, 'reason', 'forbidden',
      'message', 'You do not have permission to activate this learner.');
  END IF;

  IF v_status::text = 'active' THEN
    RETURN jsonb_build_object('activated', false, 'reason', 'already_active', 'message', 'Learner is already active.');
  END IF;
  IF v_status::text <> 'admitted' THEN
    RETURN jsonb_build_object('activated', false, 'reason', 'status_not_admitted',
      'current_status', v_status::text,
      'message', format('Only admitted learners can be activated (this learner is %s). Reserved learners activate once their fees clear the threshold.', v_status::text));
  END IF;
  IF v_email IS NULL OR btrim(v_email) = '' OR v_ay IS NULL OR v_sem IS NULL OR v_sec IS NULL THEN
    RETURN jsonb_build_object('activated', false, 'reason', 'incomplete_profile',
      'message', 'College Email, Academic Year, Semester and Section must all be set.');
  END IF;
  IF lower(v_email) NOT LIKE '%@jkkn.ac.in' THEN
    RETURN jsonb_build_object('activated', false, 'reason', 'invalid_college_email',
      'message', 'College Email must be on the @jkkn.ac.in domain.');
  END IF;

  -- Recorded, NOT enforced: admission_statuses.active threshold is 60, but the
  -- pre-existing Quick Complete path activates on the four fields alone.
  SELECT v.paid_pct INTO v_paid_pct FROM public.vw_learner_payment_progress v WHERE v.learner_id = p_learner_id;
  v_paid_pct := COALESCE(v_paid_pct, 0);
  SELECT s.fee_paid_threshold_percent INTO v_threshold FROM public.admission_statuses s
  WHERE s.scope = 'learner' AND s.code = 'active' AND s.is_active = true LIMIT 1;

  UPDATE public.learners_profiles
     SET lifecycle_status = 'active'::lifecycle_status, is_profile_complete = true,
         updated_at = now(), updated_by = v_actor
   WHERE id = p_learner_id AND lifecycle_status::text = 'admitted';
  GET DIAGNOSTICS v_updated = ROW_COUNT;

  IF v_updated = 0 THEN
    RETURN jsonb_build_object('activated', false, 'reason', 'concurrent_change',
      'message', 'Learner status changed while activating. Refresh and retry.');
  END IF;

  INSERT INTO public.learners_profile_status_history
    (learner_id, from_status, to_status, reason_code, paid_pct_at_change,
     threshold_at_change, changed_by, metadata)
  VALUES
    (p_learner_id, 'admitted'::lifecycle_status, 'active'::lifecycle_status,
     'onboarding_activation', v_paid_pct, v_threshold, v_actor,
     jsonb_build_object('source', 'fn_activate_learner_from_onboarding',
       'threshold_enforced', false,
       'met_configured_threshold', (v_threshold IS NULL OR v_paid_pct >= v_threshold)));

  RETURN jsonb_build_object('activated', true, 'learner_id', p_learner_id,
    'paid_pct', v_paid_pct, 'threshold', v_threshold,
    'met_configured_threshold', (v_threshold IS NULL OR v_paid_pct >= v_threshold),
    'message', 'Learner activated.');
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_activate_learner_from_onboarding(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_activate_learner_from_onboarding(uuid) TO authenticated;


-- ============================================================================
-- Auto-Allocate (CURRENT) — supersedes the p_block_id-era definitions of
-- fn_auto_allocate_classic / fn_auto_allocate_candidates earlier in this file
-- (~L15182 / ~L15303), which are stale by several migrations: the signatures
-- moved from a single p_block_id to a p_hostel_type sweep across every block of
-- a type, and now carry p_allow_overflow. Appended rather than edited in place,
-- matching how the current fn_auto_allocate_preview(text, uuid, uuid, uuid) was
-- mirrored (~L26109) — later definitions win on replay, as in migration order.
--
-- Source: supabase/migrations/20260810200000_auto_allocate_category_overflow_unruled_rooms.sql
--   Category eligibility is absolute; physical-room rules are a preference.
--   tier 1 = rooms the learner's own rule covers; tier 2 = rooms NO rule covers
--   (p_allow_overflow); rooms reserved for another cohort are never used.
-- Carries forward 20260810190000 (gender resolved from the learner master
-- record when the login shadow is blank; NULL-safe gender_ok) and 20260810160000
-- (per-cohort-signature eligibility cache that keeps this inside the 8s
-- statement_timeout).
-- ============================================================================

DROP FUNCTION IF EXISTS public.fn_auto_allocate_candidates(text, boolean, uuid, uuid, uuid);
DROP FUNCTION IF EXISTS public.fn_auto_allocate_candidates(text, boolean, uuid, uuid, uuid, boolean);

CREATE FUNCTION public.fn_auto_allocate_candidates(
  p_hostel_type text,
  p_strict boolean DEFAULT true,
  p_institution_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_allow_overflow boolean DEFAULT true
)
RETURNS TABLE(
  learner_id uuid, full_name text, email text, institution_name text,
  program_name text, semester_name text, gender text,
  has_profile boolean, gender_ok boolean, not_allocated boolean,
  physical_rule_ok boolean, overflow_room_ok boolean, placement_tier text,
  bed_available boolean, target_block_name text,
  academic_year_id uuid, academic_year_name text,
  admission_academic_year_id uuid, admission_academic_year_name text,
  band_academic_year_id uuid, band_academic_year_name text, band_fee numeric,
  academic_bill_count integer, current_year_bill_count integer,
  bill_other_year_name text, current_year_fee numeric,
  resolved_room_category_id uuid, resolved_room_category_name text,
  resolved_mess_category_id uuid, resolved_mess_category_name text,
  bill_state text, stage text, verdict text, exclusion_reason text
)
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  WITH blocks AS MATERIALIZED (
    SELECT id, name FROM hostel_blocks WHERE hostel_type::text = p_hostel_type
  ),
  scope_rooms AS MATERIALIZED (
    SELECT r.id, r.block_id, b.name AS block_name, r.floor, r.room_number,
           r.category_id, hc.type AS cat_type
    FROM hostel_rooms r
    JOIN blocks b ON b.id = r.block_id
    LEFT JOIN hostel_categories hc ON hc.id = r.category_id
    WHERE r.room_purpose = 'student'
  ),
  raw_cohort AS MATERIALIZED (
    SELECT lp.id, lp.institution_id, lp.degree_id, lp.department_id,
           lp.program_id, lp.semester_id, lp.academic_year_id, lp.quota_id,
           lp.first_name, lp.last_name,
           CASE WHEN lower(lp.gender) LIKE 'm%' THEN 'boys'
                WHEN lower(lp.gender) LIKE 'f%' THEN 'girls' END AS lp_gender_type,
           -- The one place gender is resolved. profiles.gender (the login
           -- shadow) is still read first; learners_profiles — the master record
           -- the rest of this function already trusts for lp_gender_type — only
           -- fills a blank. NULLIF, not COALESCE alone: '' is not NULL, so
           -- without it an empty-string shadow would still win over a perfectly
           -- good master value. Everything downstream reads this alias, so the
           -- category resolver and the gender/room checks can no longer
           -- disagree about the same learner.
           lower(btrim(COALESCE(NULLIF(btrim(gp.gender), ''), lp.gender))) AS eff_gender
    FROM learners_profiles lp
    LEFT JOIN profiles gp ON gp.learner_id = lp.id
    WHERE lp.accommodation_type_id IN (SELECT id FROM accommodation_types WHERE code = 'hostel')
      AND lp.lifecycle_status = 'active'
      AND lp.institution_id IN (
            SELECT bi.institution_id FROM hostel_block_institutions bi
            WHERE bi.block_id IN (SELECT id FROM blocks))
      AND (p_institution_id IS NULL OR lp.institution_id = p_institution_id)
      AND (p_program_id     IS NULL OR lp.program_id     = p_program_id)
      AND (p_semester_id    IS NULL OR lp.semester_id    = p_semester_id)
      -- Same resolution as eff_gender above, inlined because a SELECT alias is
      -- not visible in WHERE. Reading the shadow alone put a learner with a
      -- blank profiles.gender into the permissive "unknown" branch, so they
      -- appeared in BOTH the boys and the girls preview; resolved against the
      -- master record they now appear in exactly one. The unknown branch is
      -- kept for a learner with NO gender anywhere — they must still surface,
      -- and get told so, rather than silently vanish from every run.
      AND (COALESCE(NULLIF(btrim(gp.gender), ''), NULLIF(btrim(lp.gender), '')) IS NULL
           OR (p_hostel_type = 'boys'
               AND lower(btrim(COALESCE(NULLIF(btrim(gp.gender), ''), lp.gender))) IN ('male','m'))
           OR (p_hostel_type = 'girls'
               AND lower(btrim(COALESCE(NULLIF(btrim(gp.gender), ''), lp.gender))) IN ('female','f')))
      AND NOT EXISTS (
        SELECT 1 FROM hostel_allocations ha2
        JOIN profiles pr2 ON pr2.learner_id = lp.id
        WHERE ha2.learner_id = pr2.id
          AND ha2.status IN ('active', 'pending_approval')
      )
  ),
  -- ── Overflow tier 2: rooms NO active rule covers ─────────────────────────
  -- "Unreserved" is a property of the ROOM ALONE — it does not depend on the
  -- learner — so this is evaluated ONCE per run, not per learner. That is what
  -- keeps the 8s statement_timeout safe: it adds no per-learner plpgsql calls,
  -- which is the exact cost the signature cache exists to avoid.
  --
  -- The CASE below is a verbatim copy of v_has_covering inside
  -- fn_learner_strictly_eligible_for_room. It MUST stay identical: if the two
  -- drift, a room could be "unreserved" here and "reserved" there, and the
  -- overflow would hand out a bed the predicate says belongs to someone else.
  unruled_rooms AS MATERIALIZED (
    SELECT sr.id AS room_id, sr.category_id, sr.cat_type,
           sr.block_name, sr.floor, sr.room_number
    FROM scope_rooms sr
    WHERE NOT EXISTS (
      SELECT 1 FROM hostel_room_eligibility_rules re
      WHERE re.is_active AND re.block_id = sr.block_id
        AND CASE
              WHEN EXISTS (SELECT 1 FROM hostel_room_eligibility_rule_rooms rr
                           WHERE rr.rule_id = re.id)
                THEN EXISTS (SELECT 1 FROM hostel_room_eligibility_rule_rooms rr
                             WHERE rr.rule_id = re.id AND rr.room_id = sr.id)
              ELSE (re.floor IS NULL OR re.floor = sr.floor)
            END
    )
  ),
  -- Institution access is still a HARD gate on the overflow tier: an unreserved
  -- room is only reachable by institutions the block actually serves. Costed
  -- per (distinct institution x unreserved room) — a handful of institutions,
  -- not per learner.
  overflow_rooms AS MATERIALIZED (
    SELECT i.institution_id, ur.room_id, ur.category_id, ur.cat_type,
           ur.block_name, ur.floor, ur.room_number
    FROM (SELECT DISTINCT institution_id FROM raw_cohort) i
    CROSS JOIN unruled_rooms ur
    WHERE p_allow_overflow
      AND fn_room_serves_institution(ur.room_id, i.institution_id)
  ),
  sigs AS MATERIALIZED (
    SELECT institution_id, degree_id, department_id, program_id, semester_id,
           (array_agg(id))[1] AS rep
    FROM raw_cohort
    GROUP BY 1,2,3,4,5
  ),
  sig_rooms AS MATERIALIZED (
    SELECT s.rep, sr.id AS room_id, sr.category_id, sr.cat_type,
           sr.block_name, sr.floor, sr.room_number
    FROM sigs s
    CROSS JOIN scope_rooms sr
    WHERE fn_room_serves_institution(sr.id, s.institution_id)
      AND fn_learner_strictly_eligible_for_room(s.rep, sr.id, p_strict)
  ),
  free_beds AS MATERIALIZED (
    SELECT bd.id, bd.room_id, bd.bed_number
    FROM hostel_beds bd
    JOIN scope_rooms sr ON sr.id = bd.room_id
    WHERE bd.status = 'available'
      AND NOT EXISTS (SELECT 1 FROM hostel_allocations a
                      WHERE a.bed_id = bd.id AND a.status IN ('active','pending_approval'))
  ),
  fee AS MATERIALIZED (
    SELECT c.id, adm.ay_id AS adm_ay,
           bf.academic_year_id AS band_ay, bf.academic_year_name AS band_ay_name, bf.fee
    FROM raw_cohort c
    LEFT JOIN LATERAL (SELECT fn_learner_admission_academic_year(c.id) AS ay_id) adm ON true
    LEFT JOIN LATERAL fn_learner_band_academic_fee(c.id) bf ON true
  ),
  cats AS MATERIALIZED (
    SELECT c.id,
      CASE WHEN c.institution_id IS NOT NULL AND c.program_id IS NOT NULL AND f.fee IS NOT NULL
           THEN (SELECT array_agg(category_id) FROM fn_hostel_effective_room_categories(
                   c.institution_id, c.program_id, c.quota_id, f.fee, c.lp_gender_type)) END AS room_cats,
      CASE WHEN c.institution_id IS NOT NULL AND c.program_id IS NOT NULL AND f.fee IS NOT NULL
           THEN (SELECT array_agg(category_id) FROM fn_hostel_effective_mess_categories(
                   c.institution_id, c.program_id, c.quota_id, f.fee, c.lp_gender_type)) END AS mess_cats
    FROM raw_cohort c JOIN fee f ON f.id = c.id
  ),
  base AS (
    SELECT
      c.id AS learner_id,
      COALESCE(p.full_name,
               NULLIF(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''),
               p.email, '—') AS full_name,
      p.email, inst.name AS institution_name, prog.program_name, sem.semester_name,
      -- Was lower(trim(p.gender)) — the login shadow. Now the resolved value.
      c.eff_gender AS gender,
      (p.id IS NOT NULL) AS has_profile,
      c.academic_year_id, ay.academic_year_name,
      ct.room_cats, ct.mess_cats,
      f.adm_ay AS admission_academic_year_id,
      aay.academic_year_name::text AS admission_academic_year_name,
      f.band_ay AS band_academic_year_id,
      f.band_ay_name AS band_academic_year_name,
      f.fee AS band_fee,
      ct.room_cats[1] AS resolved_room_category_id,
      rc.name AS resolved_room_category_name, rc.type AS resolved_room_category_type,
      ct.mess_cats[1] AS resolved_mess_category_id, mc.name AS resolved_mess_category_name,
      (SELECT count(*)::int FROM billing_student_bills b
         WHERE b.student_id = c.id AND b.fee_source = 'academic'
           AND b.status NOT IN ('cancelled','superseded')) AS academic_bill_count,
      (SELECT count(*)::int FROM billing_student_bills b
         WHERE b.student_id = c.id AND b.fee_source = 'academic'
           AND b.status NOT IN ('cancelled','superseded')
           AND b.academic_year_id = c.academic_year_id) AS current_year_bill_count,
      (SELECT ay2.academic_year_name
         FROM billing_student_bills b JOIN academic_years ay2 ON ay2.id = b.academic_year_id
        WHERE b.student_id = c.id AND b.fee_source = 'academic'
          AND b.status NOT IN ('cancelled','superseded')
          AND b.academic_year_id IS NOT NULL
          AND b.academic_year_id IS DISTINCT FROM c.academic_year_id
        ORDER BY b.created_at DESC LIMIT 1) AS bill_other_year_name,
      fn_learner_current_year_academic_fee(c.id) AS current_year_fee,
      true AS not_allocated,
      EXISTS (
        SELECT 1 FROM sig_rooms sr
        WHERE sr.rep = s.rep
          AND sr.category_id = ANY(ct.room_cats)
          AND (sr.cat_type IS NULL
               OR (sr.cat_type = 'boys'  AND c.eff_gender IN ('male','m'))
               OR (sr.cat_type = 'girls' AND c.eff_gender IN ('female','f')))
      ) AS physical_rule_ok,
      EXISTS (
        SELECT 1 FROM sig_rooms sr
        WHERE sr.rep = s.rep
          AND NOT (sr.category_id = ANY(ct.room_cats))
      ) AS physical_ok_other_category,
      -- Tier 2 reachability, independent of whether a BED is free there. Kept
      -- separate from physical_rule_ok so the preview can still say truthfully
      -- whether a RULE covers them; the verdict below accepts either.
      -- overflow_rooms is already empty when p_allow_overflow is false, so this
      -- needs no extra guard.
      EXISTS (
        SELECT 1 FROM overflow_rooms orm
        WHERE orm.institution_id = c.institution_id
          AND orm.category_id = ANY(ct.room_cats)
          AND (orm.cat_type IS NULL
               OR (orm.cat_type = 'boys'  AND c.eff_gender IN ('male','m'))
               OR (orm.cat_type = 'girls' AND c.eff_gender IN ('female','f')))
      ) AS overflow_room_ok,
      (tgt.block_name IS NOT NULL) AS bed_available,
      tgt.block_name AS target_block_name,
      CASE tgt.tier WHEN 1 THEN 'rule' WHEN 2 THEN 'overflow' END AS placement_tier
    FROM raw_cohort c
    JOIN cats ct ON ct.id = c.id
    JOIN fee  f  ON f.id  = c.id
    JOIN sigs s  ON s.institution_id IS NOT DISTINCT FROM c.institution_id
                AND s.degree_id      IS NOT DISTINCT FROM c.degree_id
                AND s.department_id  IS NOT DISTINCT FROM c.department_id
                AND s.program_id     IS NOT DISTINCT FROM c.program_id
                AND s.semester_id    IS NOT DISTINCT FROM c.semester_id
    LEFT JOIN profiles p        ON p.learner_id = c.id
    LEFT JOIN institutions inst ON inst.id = c.institution_id
    LEFT JOIN programs prog     ON prog.id = c.program_id
    LEFT JOIN semesters sem     ON sem.id = c.semester_id
    LEFT JOIN academic_years ay ON ay.id = c.academic_year_id
    LEFT JOIN academic_years aay ON aay.id = f.adm_ay
    LEFT JOIN hostel_categories rc ON rc.id = ct.room_cats[1]
    LEFT JOIN mess_categories   mc ON mc.id = ct.mess_cats[1]
    -- Predicted bed across BOTH tiers, in one ordered pass. Same ORDER BY as
    -- fn_auto_allocate_classic, so this stays a real prediction.
    -- Category priority sits above tier on purpose (see header): entitlement
    -- first, then prefer a reserved room over an unreserved one within that
    -- category. With p_allow_overflow = false the UNION's second leg is empty
    -- and the sort degenerates to the previous ORDER BY exactly.
    LEFT JOIN LATERAL (
      SELECT x.block_name, x.tier
      FROM (
        SELECT sr.room_id, sr.category_id, sr.cat_type,
               sr.block_name, sr.floor, sr.room_number, 1 AS tier
        FROM sig_rooms sr
        WHERE sr.rep = s.rep
        UNION ALL
        SELECT orm.room_id, orm.category_id, orm.cat_type,
               orm.block_name, orm.floor, orm.room_number, 2
        FROM overflow_rooms orm
        WHERE orm.institution_id = c.institution_id
      ) x
      JOIN free_beds bd ON bd.room_id = x.room_id
      WHERE x.category_id = ANY(ct.room_cats)
        AND (x.cat_type IS NULL
             OR (x.cat_type = 'boys'  AND c.eff_gender IN ('male','m'))
             OR (x.cat_type = 'girls' AND c.eff_gender IN ('female','f')))
      ORDER BY array_position(ct.room_cats, x.category_id), x.tier,
               x.block_name, x.floor, x.room_number, bd.bed_number
      LIMIT 1
    ) tgt ON true
  ),
  scored AS (
    SELECT b.*,
      -- NULL-safe. Without the leading IS NOT NULL guard, an absent gender made
      -- this `false OR NULL OR false` = NULL, and every downstream
      -- `NOT gender_ok` test silently stopped matching (NOT NULL is NULL, and a
      -- CASE/WHERE needs true) — so the row fell through to the physical-room
      -- branch and blamed a room rule for a missing gender. Now it is a plain
      -- false and the dedicated branch below reports the real cause.
      (b.gender IS NOT NULL
        AND (b.resolved_room_category_type IS NULL
          OR (b.resolved_room_category_type = 'boys'  AND b.gender IN ('male','m'))
          OR (b.resolved_room_category_type = 'girls' AND b.gender IN ('female','f')))) AS gender_ok
    FROM base b
  )
  SELECT
    s.learner_id, s.full_name, s.email, s.institution_name, s.program_name, s.semester_name,
    s.gender, s.has_profile, s.gender_ok, s.not_allocated, s.physical_rule_ok,
    s.overflow_room_ok, s.placement_tier,
    s.bed_available, s.target_block_name,
    s.academic_year_id, s.academic_year_name,
    s.admission_academic_year_id, s.admission_academic_year_name,
    s.band_academic_year_id, s.band_academic_year_name, s.band_fee,
    s.academic_bill_count, s.current_year_bill_count, s.bill_other_year_name, s.current_year_fee,
    s.resolved_room_category_id, s.resolved_room_category_name,
    s.resolved_mess_category_id, s.resolved_mess_category_name,
    CASE
      WHEN s.band_fee IS NOT NULL
       AND s.band_academic_year_id IS NOT DISTINCT FROM s.admission_academic_year_id THEN 'matched'
      WHEN s.band_fee IS NOT NULL          THEN 'different_year'
      WHEN s.academic_bill_count > 0       THEN 'untagged'
      ELSE 'none'
    END AS bill_state,
    CASE
      WHEN s.band_fee  IS NULL THEN 'prerequisite'
      WHEN s.room_cats IS NULL THEN 'prerequisite'
      -- Reachability is now "a rule covers a room of their category OR an
      -- unreserved one exists", not "a rule covers one".
      WHEN NOT s.has_profile OR NOT s.gender_ok
        OR NOT (s.physical_rule_ok OR s.overflow_room_ok) OR NOT s.bed_available
                               THEN 'eligibility'
      ELSE 'ok'
    END AS stage,
    CASE
      WHEN s.band_fee  IS NULL THEN 'out'
      WHEN s.room_cats IS NULL THEN 'out'
      WHEN NOT s.has_profile OR NOT s.gender_ok
        OR NOT (s.physical_rule_ok OR s.overflow_room_ok) OR NOT s.bed_available
                               THEN 'out'
      ELSE 'in'
    END AS verdict,
    CASE
      WHEN s.band_fee IS NULL THEN
        CASE
          WHEN s.academic_bill_count = 0 THEN
            'No academic bill for this student — nothing to read a fee band from'
          ELSE
            'Academic bills exist but none is usable: either untagged to an academic year, or the tagged year totals ₹0'
        END
      WHEN s.room_cats IS NULL THEN
        'No Category-Eligibility band covers ₹'
        || to_char(s.band_fee, 'FM999,999,999')
        || ' (read from ' || COALESCE(s.band_academic_year_name, 'their admission year') || ')'
        || ' for this program / quota — add or widen a band'
      WHEN NOT s.has_profile   THEN 'No login profile'
      -- Ordered BEFORE the generic gender_ok branch: "not set" and "set but
      -- wrong" are different operator actions (fill the field vs fix the
      -- category), and this case previously reached neither branch at all.
      WHEN s.gender IS NULL    THEN
        'Gender is not set on this learner — set it on the learner profile, then re-run the preview'
      WHEN NOT s.gender_ok     THEN 'Gender does not match the resolved room category'
      WHEN NOT (s.physical_rule_ok OR s.overflow_room_ok) AND s.physical_ok_other_category THEN
        'Rooms they may occupy are a different room category than their eligible '
        || COALESCE(s.resolved_room_category_name, 'category')
        || ' — fix the reservation rooms or the Category-Eligibility band'
      WHEN NOT (s.physical_rule_ok OR s.overflow_room_ok) THEN
        CASE WHEN p_strict
          THEN 'No physical-room rule reserves a room for this cohort in any ' || p_hostel_type || ' block (strict mode)'
          ELSE 'No room they can occupy in their category — every room is reserved for other cohorts'
        END
      -- Rooms of their category ARE reachable, but every bed in them is taken.
      -- The two phrasings are materially different advice: with overflow on,
      -- the category is genuinely exhausted and the answer is more rooms or a
      -- re-band; with it off, unreserved rooms simply were not considered.
      WHEN NOT s.bed_available THEN
        CASE WHEN p_allow_overflow
          THEN COALESCE(s.resolved_room_category_name, 'Their category')
               || ' is exhausted in every ' || p_hostel_type
               || ' block — no free bed in any '
               || COALESCE(s.resolved_room_category_name, 'eligible')
               || ' room, reserved or unreserved'
          ELSE 'Their category rooms are full — no free bed in any ' || p_hostel_type
               || ' block (overflow is off, so unreserved rooms of their category were not considered)'
        END
      ELSE NULL
    END AS exclusion_reason
  FROM scored s
  ORDER BY s.full_name;
$function$;

-- Re-issued: DROP FUNCTION above discarded the previous grants.
REVOKE EXECUTE ON FUNCTION public.fn_auto_allocate_candidates(text, boolean, uuid, uuid, uuid, boolean) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_auto_allocate_candidates(text, boolean, uuid, uuid, uuid, boolean) TO authenticated, service_role;


-- ── 2. Generate: same signature cache, via ON COMMIT DROP temp tables ───────
--
-- The signature DOES change here (p_allow_overflow), so this is DROP + CREATE
-- and the grants are re-issued below. The loop used to run a bed search with
-- ORDER BY over every bed x the plpgsql predicate, once per learner — the same
-- cost that broke the preview, and it would have blown the 8s timeout on
-- Generate too. Now the (signature, room) eligibility map and the unreserved-
-- room map are both built once up front; only BED AVAILABILITY is re-checked
-- per iteration, because earlier learners in the same run consume beds.
DROP FUNCTION IF EXISTS public.fn_auto_allocate_classic(text, uuid, boolean, uuid, uuid, uuid);
DROP FUNCTION IF EXISTS public.fn_auto_allocate_classic(text, uuid, boolean, uuid, uuid, uuid, boolean);

CREATE FUNCTION public.fn_auto_allocate_classic(
  p_hostel_type text,
  p_hostel_year_id uuid DEFAULT NULL::uuid,
  p_strict boolean DEFAULT true,
  p_institution_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_allow_overflow boolean DEFAULT true
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_batch uuid; v_tier uuid; v_actor uuid := auth.uid();
  v_alloc int := 0; v_skip int := 0; v_overflow int := 0; v_placed_tier int;
  v_year uuid; v_ay uuid;
  cand record; v_bed uuid; v_room uuid; v_block uuid; v_mess uuid;
BEGIN
  IF NOT (is_super_admin() OR is_admin() OR user_has_permission('campus_living.allocations.create')) THEN
    RAISE EXCEPTION 'Not authorized to run auto-allocation';
  END IF;

  IF p_hostel_type IS NULL OR p_hostel_type NOT IN ('boys','girls') THEN
    RAISE EXCEPTION 'Hostel type must be boys or girls';
  END IF;

  v_year := COALESCE(p_hostel_year_id, (SELECT id FROM hostel_years WHERE is_current LIMIT 1));
  IF v_year IS NULL THEN
    RAISE EXCEPTION 'No current hostel year is set — mark one under Campus Living → Settings → Hostel Years';
  END IF;

  SELECT id INTO v_tier FROM hostel_tier_policy WHERE tier_key='standard' AND institution_id IS NULL AND is_active LIMIT 1;
  IF v_tier IS NULL THEN SELECT id INTO v_tier FROM hostel_tier_policy WHERE tier_key='standard' AND is_active LIMIT 1; END IF;
  IF v_tier IS NULL THEN RAISE EXCEPTION 'No standard tier policy found'; END IF;

  CREATE TEMP TABLE _aa_cand ON COMMIT DROP AS
    SELECT lp.id AS lp_id, p.id AS profile_id, lp.semester_id AS sem_id,
           lp.academic_year_id AS ay_id, lp.institution_id AS inst,
           lp.degree_id, lp.department_id, lp.program_id,
           -- Login shadow first, master record fills a blank — byte-identical
           -- resolution to eff_gender in the preview above. These two MUST
           -- agree: if the allocator read a different column than the preview,
           -- a learner shown as "In" would be silently skipped by the run.
           lower(btrim(COALESCE(NULLIF(btrim(p.gender), ''), lp.gender))) AS gender,
           room_elig.cats AS room_cats, mess_elig.cats AS mess_cats,
           COALESCE(sem_fill.rank, 1) AS fill_rank,
           prim.is_primary,
           lower(coalesce(inst_t.name,'')) AS inst_name,
           lower(coalesce(lp.first_name,'')) AS fname,
           lower(coalesce(lp.last_name,''))  AS lname
    FROM learners_profiles lp
    JOIN profiles p ON p.learner_id = lp.id
    JOIN institutions inst_t ON inst_t.id = lp.institution_id
    LEFT JOIN LATERAL (SELECT array_agg(category_id) AS cats FROM fn_hostel_learner_room_categories(lp.id)) room_elig ON true
    LEFT JOIN LATERAL (SELECT array_agg(category_id) AS cats FROM fn_hostel_learner_mess_categories(lp.id)) mess_elig ON true
    LEFT JOIN LATERAL (
      SELECT bool_or(hbi.is_primary) AS is_primary
      FROM hostel_block_institutions hbi
      JOIN hostel_blocks hb ON hb.id = hbi.block_id
      WHERE hb.hostel_type::text = p_hostel_type
        AND hbi.institution_id = lp.institution_id
    ) prim ON true
    LEFT JOIN LATERAL (
      SELECT min(array_position(r.semester_ids, lp.semester_id)) AS rank
      FROM hostel_room_eligibility_rules r
      JOIN hostel_blocks hb ON hb.id = r.block_id
      WHERE r.is_active
        AND hb.hostel_type::text = p_hostel_type
        AND r.institution_id = lp.institution_id
        AND (r.degree_id     IS NULL OR r.degree_id     = lp.degree_id)
        AND (r.department_id IS NULL OR r.department_id = lp.department_id)
        AND (r.program_id    IS NULL OR r.program_id    = lp.program_id)
        AND cardinality(r.semester_ids) > 1
        AND lp.semester_id = ANY(r.semester_ids)
    ) sem_fill ON true
    WHERE lp.accommodation_type_id IN (SELECT id FROM accommodation_types WHERE code = 'hostel')
      AND lp.lifecycle_status = 'active'
      AND room_elig.cats IS NOT NULL
      AND prim.is_primary IS NOT NULL
      AND (COALESCE(NULLIF(btrim(p.gender), ''), NULLIF(btrim(lp.gender), '')) IS NULL
           OR (p_hostel_type = 'boys'
               AND lower(btrim(COALESCE(NULLIF(btrim(p.gender), ''), lp.gender))) IN ('male','m'))
           OR (p_hostel_type = 'girls'
               AND lower(btrim(COALESCE(NULLIF(btrim(p.gender), ''), lp.gender))) IN ('female','f')))
      AND NOT EXISTS (SELECT 1 FROM hostel_allocations a WHERE a.learner_id=p.id AND a.status IN ('active','pending_approval'))
      AND (p_institution_id IS NULL OR lp.institution_id = p_institution_id)
      AND (p_program_id     IS NULL OR lp.program_id     = p_program_id)
      AND (p_semester_id    IS NULL OR lp.semester_id    = p_semester_id);

  CREATE TEMP TABLE _aa_sig_rooms ON COMMIT DROP AS
    SELECT s.inst, s.degree_id, s.department_id, s.program_id, s.sem_id,
           r.id AS room_id, r.category_id, r.block_id, r.floor, r.room_number,
           hb.name AS block_name, hc.type AS cat_type
    FROM (SELECT DISTINCT inst, degree_id, department_id, program_id, sem_id,
                 (array_agg(lp_id))[1] AS rep
          FROM _aa_cand GROUP BY inst, degree_id, department_id, program_id, sem_id) s
    CROSS JOIN LATERAL (
      SELECT r.* FROM hostel_rooms r
      JOIN hostel_blocks hb2 ON hb2.id = r.block_id
      WHERE hb2.hostel_type::text = p_hostel_type AND r.room_purpose = 'student'
    ) r
    JOIN hostel_blocks hb ON hb.id = r.block_id
    LEFT JOIN hostel_categories hc ON hc.id = r.category_id
    WHERE fn_room_serves_institution(r.id, s.inst)
      AND fn_learner_strictly_eligible_for_room(s.rep, r.id, p_strict);

  CREATE INDEX ON _aa_sig_rooms (inst, degree_id, department_id, program_id, sem_id);

  -- Overflow tier 2: rooms NO active rule covers, per institution in the run.
  -- Empty when p_allow_overflow is false, which makes the UNION in the bed
  -- search below collapse to exactly the previous single-tier query.
  -- The NOT EXISTS is the same v_has_covering copy used by the preview RPC and
  -- fn_learner_strictly_eligible_for_room — see the header note.
  CREATE TEMP TABLE _aa_overflow_rooms ON COMMIT DROP AS
    SELECT i.inst, r.id AS room_id, r.category_id, r.block_id, r.floor, r.room_number,
           hb.name AS block_name, hc.type AS cat_type
    FROM (SELECT DISTINCT inst FROM _aa_cand) i
    CROSS JOIN LATERAL (
      SELECT r.* FROM hostel_rooms r
      JOIN hostel_blocks hb2 ON hb2.id = r.block_id
      WHERE hb2.hostel_type::text = p_hostel_type AND r.room_purpose = 'student'
    ) r
    JOIN hostel_blocks hb ON hb.id = r.block_id
    LEFT JOIN hostel_categories hc ON hc.id = r.category_id
    WHERE p_allow_overflow
      AND fn_room_serves_institution(r.id, i.inst)
      AND NOT EXISTS (
        SELECT 1 FROM hostel_room_eligibility_rules re
        WHERE re.is_active AND re.block_id = r.block_id
          AND CASE
                WHEN EXISTS (SELECT 1 FROM hostel_room_eligibility_rule_rooms rr
                             WHERE rr.rule_id = re.id)
                  THEN EXISTS (SELECT 1 FROM hostel_room_eligibility_rule_rooms rr
                               WHERE rr.rule_id = re.id AND rr.room_id = r.id)
                ELSE (re.floor IS NULL OR re.floor = r.floor)
              END
      );

  CREATE INDEX ON _aa_overflow_rooms (inst);

  INSERT INTO hostel_allocation_batches (block_id, category_id, hostel_year_id, status, created_by)
  VALUES (NULL, NULL, v_year, 'pending_approval', v_actor)
  RETURNING id INTO v_batch;

  FOR cand IN
    SELECT * FROM _aa_cand
    ORDER BY fill_rank, is_primary DESC, inst_name, fname, lname, lp_id
  LOOP
    v_ay := COALESCE(cand.ay_id, (SELECT id FROM academic_years WHERE institution_id=cand.inst AND is_active ORDER BY start_date DESC LIMIT 1));
    IF v_ay IS NULL THEN v_skip := v_skip + 1; CONTINUE; END IF;

    v_bed := NULL; v_room := NULL; v_block := NULL; v_placed_tier := NULL;
    -- Two tiers in one ordered pass. Same ORDER BY as the preview RPC, so
    -- Preview == Generate. Bed availability is re-checked per iteration because
    -- earlier learners in this same run consume beds.
    SELECT b.id, x.room_id, x.block_id, x.tier
      INTO v_bed, v_room, v_block, v_placed_tier
    FROM (
      SELECT sr.room_id, sr.category_id, sr.block_id, sr.block_name,
             sr.floor, sr.room_number, sr.cat_type, 1 AS tier
      FROM _aa_sig_rooms sr
      WHERE sr.inst           IS NOT DISTINCT FROM cand.inst
        AND sr.degree_id      IS NOT DISTINCT FROM cand.degree_id
        AND sr.department_id  IS NOT DISTINCT FROM cand.department_id
        AND sr.program_id     IS NOT DISTINCT FROM cand.program_id
        AND sr.sem_id         IS NOT DISTINCT FROM cand.sem_id
      UNION ALL
      SELECT o.room_id, o.category_id, o.block_id, o.block_name,
             o.floor, o.room_number, o.cat_type, 2
      FROM _aa_overflow_rooms o
      WHERE o.inst IS NOT DISTINCT FROM cand.inst
    ) x
    JOIN hostel_beds b ON b.room_id = x.room_id AND b.status = 'available'
    WHERE x.category_id = ANY(cand.room_cats)
      AND (x.cat_type IS NULL
           OR (x.cat_type='boys'  AND cand.gender IN ('male','m'))
           OR (x.cat_type='girls' AND cand.gender IN ('female','f')))
      AND NOT EXISTS (SELECT 1 FROM hostel_allocations a WHERE a.bed_id=b.id AND a.status IN ('active','pending_approval'))
    ORDER BY array_position(cand.room_cats, x.category_id), x.tier,
             x.block_name, x.floor, x.room_number, b.bed_number
    LIMIT 1;

    IF v_bed IS NULL THEN v_skip := v_skip + 1; CONTINUE; END IF;
    IF v_placed_tier = 2 THEN v_overflow := v_overflow + 1; END IF;

    INSERT INTO hostel_allocations (
      institution_id, learner_id, block_id, room_id, bed_id, academic_year_id, semester_id,
      allocation_type, allocation_date, status,
      emergency_contact_name, emergency_contact_phone, emergency_contact_relation,
      tier_id, batch_id, allocated_by, warden_id
    ) VALUES (
      cand.inst, cand.profile_id, v_block, v_room, v_bed, v_ay, cand.sem_id,
      'fresh', CURRENT_DATE, 'pending_approval', '', '', '',
      v_tier, v_batch, v_actor,
      (SELECT user_id FROM user_block_access WHERE block_id=v_block AND revoked_at IS NULL LIMIT 1)
    );

    v_mess := CASE WHEN cand.mess_cats IS NOT NULL THEN cand.mess_cats[1] ELSE NULL END;
    UPDATE learners_profiles
      SET hostel_category_id = (SELECT category_id FROM hostel_rooms WHERE id = v_room),
          mess_category_id   = COALESCE(v_mess, mess_category_id),
          updated_at = now()
      WHERE id = cand.lp_id;

    v_alloc := v_alloc + 1;
  END LOOP;

  UPDATE hostel_allocation_batches
    SET allocated_count = v_alloc, skipped_count = v_skip,
        notes = format('%s allocated across all %s blocks (%s physical mode; rules-driven category + mess; block and room decided by the physical-room rules). %s of them overflowed into UNRESERVED rooms of their own category because every room reserved for their cohort was full (%s). %s skipped (no free bed they can occupy / reserved rooms hold no space for them / gender / no academic year). Strict: learners with no rule-resolved room category are excluded. Cohort: lifecycle_status = active only.',
                       v_alloc, p_hostel_type,
                       CASE WHEN p_strict THEN 'STRICT — only cohorts matching a physical rule' ELSE 'open — rule-free rooms shared' END,
                       v_overflow,
                       CASE WHEN p_allow_overflow THEN 'overflow ON; category never changed, no other cohort''s reserved room used' ELSE 'overflow OFF' END,
                       v_skip)
    WHERE id = v_batch;

  RETURN v_batch;
END $function$;

-- Re-issued: DROP FUNCTION above discarded the previous grants.
REVOKE EXECUTE ON FUNCTION public.fn_auto_allocate_classic(text, uuid, boolean, uuid, uuid, uuid, boolean) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_auto_allocate_classic(text, uuid, boolean, uuid, uuid, uuid, boolean) TO authenticated, service_role;


-- ============================================================================
-- Gender resolution (CURRENT) — supersedes the earlier definitions of
-- fn_auto_allocate_preview (~L15490 / ~L26109), fn_hostel_unallocated_candidates
-- and fn_validate_hostel_allocation_gender elsewhere in this file.
--
-- Source: supabase/migrations/20260810220000_gender_resolution_trigger_and_readiness_functions.sql
--   learners_profiles.gender is the master record; profiles.gender is the login
--   shadow and may be blank. Every reader resolves it the SAME way:
--       lower(btrim(COALESCE(NULLIF(btrim(profiles.gender),''), lp.gender)))
--   The BEFORE INSERT trigger on hostel_allocations previously read the shadow
--   alone and aborted whole auto-allocation batches with 23514 for a learner the
--   engine had correctly selected.
-- ============================================================================


-- ── 1. The blocker: allocation gender validation ────────────────────────────
CREATE OR REPLACE FUNCTION public.fn_validate_hostel_allocation_gender()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_block_type hostel_type_enum;
    v_learner_gender text;
    v_learner_name text;
    v_block_name text;
BEGIN
    SELECT b.hostel_type, b.name
      INTO v_block_type, v_block_name
      FROM hostel_blocks b WHERE b.id = NEW.block_id;

    -- Byte-identical resolution to fn_auto_allocate_candidates /
    -- fn_auto_allocate_classic: login shadow first, learners_profiles master
    -- fills a blank. These MUST agree — if the engine places from one column and
    -- this trigger validates from another, a learner the preview shows as "In"
    -- aborts the entire batch on INSERT.
    -- NEW.learner_id is a profiles.id, so the master record is reached via
    -- profiles.learner_id (the two id spaces are disjoint).
    SELECT lower(btrim(COALESCE(NULLIF(btrim(p.gender), ''), lp.gender))),
           COALESCE(p.full_name, p.email, NEW.learner_id::text)
      INTO v_learner_gender, v_learner_name
      FROM profiles p
      LEFT JOIN learners_profiles lp ON lp.id = p.learner_id
     WHERE p.id = NEW.learner_id;

    -- Gender must be resolvable from EITHER record.
    IF v_learner_gender IS NULL OR v_learner_gender = '' THEN
        RAISE EXCEPTION 'Cannot allocate learner % (%) — gender is not set on either the login profile or the learner record',
            v_learner_name, NEW.learner_id
            USING ERRCODE = 'check_violation';
    END IF;

    IF v_block_type = 'boys' AND v_learner_gender NOT IN ('male','m') THEN
        RAISE EXCEPTION 'Cannot allocate % (gender=%) to boys-only block %',
            v_learner_name, v_learner_gender, v_block_name
            USING ERRCODE = 'check_violation';
    END IF;

    IF v_block_type = 'girls' AND v_learner_gender NOT IN ('female','f') THEN
        RAISE EXCEPTION 'Cannot allocate % (gender=%) to girls-only block %',
            v_learner_name, v_learner_gender, v_block_name
            USING ERRCODE = 'check_violation';
    END IF;

    -- mixed, staff, international, married, working_women, medical: no gender check
    RETURN NEW;
END;
$function$;

-- ── 2. Not Allocated tab: the false "Gender not set" ────────────────────────
-- p_institution_id keeps its DEFAULT NULL: CREATE OR REPLACE cannot remove an
-- existing parameter default (42P13), and callers rely on the no-arg form.
CREATE OR REPLACE FUNCTION public.fn_hostel_unallocated_candidates(p_institution_id uuid DEFAULT NULL::uuid)
RETURNS TABLE(learner_id uuid, first_name text, last_name text, full_name text, email text,
  gender text, institution_id uuid, institution_name text, program_name text, semester_name text,
  academic_year_id uuid, academic_year_name text, has_profile boolean, gender_set boolean,
  academic_year_set boolean, room_category_resolved boolean, mess_category_resolved boolean,
  resolved_room_category_name text, resolved_mess_category_name text, bill_state text,
  readiness text, missing_items text[])
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  WITH candidates AS (
    SELECT
      lp.id,
      lp.first_name,
      lp.last_name,
      lp.gender AS lp_gender,   -- master record, for the resolution below
      lp.institution_id,
      lp.program_id,
      lp.semester_id,
      lp.academic_year_id,
      room_elig.cats AS room_cats,
      mess_elig.cats AS mess_cats
    FROM learners_profiles lp
    LEFT JOIN LATERAL (
      SELECT array_agg(category_id) AS cats
      FROM fn_hostel_learner_room_categories(lp.id)
    ) room_elig ON true
    LEFT JOIN LATERAL (
      SELECT array_agg(category_id) AS cats
      FROM fn_hostel_learner_mess_categories(lp.id)
    ) mess_elig ON true
    WHERE lp.accommodation_type_id IN (
            SELECT id FROM accommodation_types WHERE code = 'hostel'
          )
      AND lp.lifecycle_status = 'active'
      AND (p_institution_id IS NULL OR lp.institution_id = p_institution_id)
      AND NOT EXISTS (
        SELECT 1
        FROM hostel_allocations ha2
        JOIN profiles pr2 ON pr2.learner_id = lp.id
        WHERE ha2.learner_id = pr2.id
          AND ha2.status IN ('active', 'pending_approval')
      )
  ),
  enriched AS (
    SELECT
      c.id                                                          AS learner_id,
      c.first_name,
      c.last_name,
      COALESCE(
        p.full_name,
        NULLIF(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''),
        p.email
      )                                                             AS full_name,
      p.email,
      -- Same resolution as the allocation engine: shadow first, master fills a
      -- blank. Previously read profiles.gender alone, so a learner with a blank
      -- shadow was reported "Gender not set" on the Not Allocated tab even
      -- though learners_profiles held a perfectly good value.
      lower(btrim(COALESCE(NULLIF(btrim(p.gender), ''), c.lp_gender)))  AS gender,
      c.institution_id,
      inst.name                                                     AS institution_name,
      prog.program_name,
      sem.semester_name,
      c.academic_year_id,
      ay.academic_year_name,
      (p.id IS NOT NULL)                                            AS has_profile,
      (COALESCE(NULLIF(btrim(p.gender), ''), NULLIF(btrim(c.lp_gender), '')) IS NOT NULL) AS gender_set,
      (c.academic_year_id IS NOT NULL)                              AS academic_year_set,
      (c.room_cats IS NOT NULL)                                     AS room_category_resolved,
      (c.mess_cats IS NOT NULL)                                     AS mess_category_resolved,
      rc.name                                                       AS resolved_room_category_name,
      mc.name                                                       AS resolved_mess_category_name,
      CASE
        WHEN c.academic_year_id IS NULL THEN 'none'
        WHEN (
          SELECT count(*) FROM billing_student_bills b
          WHERE b.student_id = c.id
            AND b.fee_source = 'academic'
            AND b.status NOT IN ('cancelled','superseded')
            AND b.academic_year_id = c.academic_year_id
        ) > 0 THEN 'matched'
        WHEN EXISTS (
          SELECT 1 FROM billing_student_bills b
          WHERE b.student_id = c.id
            AND b.fee_source = 'academic'
            AND b.status NOT IN ('cancelled','superseded')
            AND b.academic_year_id IS NOT NULL
            AND b.academic_year_id IS DISTINCT FROM c.academic_year_id
        ) THEN 'different_year'
        WHEN EXISTS (
          SELECT 1 FROM billing_student_bills b
          WHERE b.student_id = c.id
            AND b.fee_source = 'academic'
            AND b.status NOT IN ('cancelled','superseded')
        ) THEN 'untagged'
        ELSE 'none'
      END                                                           AS bill_state,
      c.room_cats,
      c.mess_cats
    FROM candidates c
    LEFT JOIN profiles       p    ON p.learner_id   = c.id
    LEFT JOIN institutions   inst ON inst.id         = c.institution_id
    LEFT JOIN programs       prog ON prog.id         = c.program_id
    LEFT JOIN semesters      sem  ON sem.id          = c.semester_id
    LEFT JOIN academic_years ay   ON ay.id           = c.academic_year_id
    LEFT JOIN hostel_categories rc ON rc.id          = c.room_cats[1]
    LEFT JOIN mess_categories   mc ON mc.id          = c.mess_cats[1]
  )
  SELECT
    e.learner_id,
    e.first_name,
    e.last_name,
    e.full_name,
    e.email,
    e.gender,
    e.institution_id,
    e.institution_name,
    e.program_name,
    e.semester_name,
    e.academic_year_id,
    e.academic_year_name,
    e.has_profile,
    e.gender_set,
    e.academic_year_set,
    e.room_category_resolved,
    e.mess_category_resolved,
    e.resolved_room_category_name,
    e.resolved_mess_category_name,
    e.bill_state,
    CASE
      WHEN e.has_profile
        AND e.gender_set
        AND e.academic_year_set
        AND e.room_category_resolved
        AND e.bill_state = 'matched'
      THEN 'ready'
      ELSE 'incomplete'
    END                                                             AS readiness,
    ARRAY_REMOVE(ARRAY[
      CASE WHEN NOT e.has_profile             THEN 'No login profile'                         END,
      CASE WHEN NOT e.gender_set              THEN 'Gender not set'                           END,
      CASE WHEN NOT e.academic_year_set       THEN 'Academic year not set'                    END,
      CASE WHEN NOT e.room_category_resolved  THEN 'No room-category eligibility rule'        END,
      CASE WHEN e.bill_state = 'none'         THEN 'No academic bill generated'               END,
      CASE WHEN e.bill_state = 'different_year' THEN 'Bill tagged to a different academic year' END,
      CASE WHEN e.bill_state = 'untagged'     THEN 'Academic bill not year-tagged'            END
    ], NULL)                                                        AS missing_items
  FROM enriched e
  ORDER BY
    (CASE
       WHEN e.has_profile AND e.gender_set AND e.academic_year_set
            AND e.room_category_resolved AND e.bill_state = 'matched'
       THEN 0 ELSE 1
     END),
    e.full_name;
$function$;

-- ── 3. Aggregate preview cards ──────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.fn_auto_allocate_preview(
  p_hostel_type text,
  p_institution_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid
)
RETURNS TABLE(cohort_eligible integer, no_profile integer, already_allocated integer,
  available_beds integer, rules_set boolean)
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  WITH blocks AS (
    SELECT id FROM hostel_blocks WHERE hostel_type::text = p_hostel_type
  ),
  cohort AS (
    SELECT lp.id, lp.institution_id,
           (SELECT array_agg(category_id) FROM fn_hostel_learner_room_categories(lp.id)) AS room_cats
    FROM learners_profiles lp
    LEFT JOIN profiles gp ON gp.learner_id = lp.id
    WHERE lp.accommodation_type_id IN (SELECT id FROM accommodation_types WHERE code='hostel')
      AND lp.lifecycle_status = 'active'
      AND lp.institution_id IN (
            SELECT bi.institution_id FROM hostel_block_institutions bi
            WHERE bi.block_id IN (SELECT id FROM blocks))
      AND (p_institution_id IS NULL OR lp.institution_id = p_institution_id)
      AND (p_program_id     IS NULL OR lp.program_id     = p_program_id)
      AND (p_semester_id    IS NULL OR lp.semester_id    = p_semester_id)
      -- Same resolution as the candidate RPC. Previously read gp.gender alone,
      -- so a blank shadow fell into the permissive "unknown" branch and the
      -- learner was counted in BOTH the boys and the girls aggregate.
      AND (COALESCE(NULLIF(btrim(gp.gender), ''), NULLIF(btrim(lp.gender), '')) IS NULL
           OR (p_hostel_type = 'boys'
               AND lower(btrim(COALESCE(NULLIF(btrim(gp.gender), ''), lp.gender))) IN ('male','m'))
           OR (p_hostel_type = 'girls'
               AND lower(btrim(COALESCE(NULLIF(btrim(gp.gender), ''), lp.gender))) IN ('female','f')))
  )
  SELECT
    (SELECT count(*)::int FROM cohort c JOIN profiles p ON p.learner_id=c.id
       WHERE c.room_cats IS NOT NULL
         AND NOT EXISTS (SELECT 1 FROM hostel_allocations a WHERE a.learner_id=p.id AND a.status IN ('active','pending_approval'))),
    (SELECT count(*)::int FROM cohort c WHERE c.room_cats IS NOT NULL AND NOT EXISTS (SELECT 1 FROM profiles p WHERE p.learner_id=c.id)),
    (SELECT count(*)::int FROM cohort c JOIN profiles p ON p.learner_id=c.id
       WHERE c.room_cats IS NOT NULL AND EXISTS (SELECT 1 FROM hostel_allocations a WHERE a.learner_id=p.id AND a.status IN ('active','pending_approval'))),
    (SELECT count(*)::int FROM hostel_beds b JOIN hostel_rooms r ON r.id=b.room_id
       WHERE r.block_id IN (SELECT id FROM blocks) AND r.room_purpose='student' AND b.status='available'
         AND NOT EXISTS (SELECT 1 FROM hostel_allocations a WHERE a.bed_id=b.id AND a.status IN ('active','pending_approval'))),
    EXISTS (SELECT 1 FROM hostel_room_eligibility_rules WHERE block_id IN (SELECT id FROM blocks) AND is_active);
$function$;

-- CREATE OR REPLACE keeps existing grants (no signature change), so none are
-- re-issued here. The trigger fn is not directly executable by clients.



-- ============================================================================
-- fn_auto_allocate_candidates (CURRENT) — supersedes the copy appended above.
-- Source: supabase/migrations/20260810230000_fix_false_category_exhausted_message.sql
--
-- Only change vs that copy: the "no free bed" exclusion message. bed_available
-- means "no free bed in a room THIS learner can reach", NOT "the category is
-- exhausted" — reporting it as the latter was false while 17 free Classic beds
-- sat in Girls Hostel A, each reserved for a different cohort. `base` gains an
-- internal column category_free_beds_anywhere (not in RETURNS TABLE, so the
-- signature and grants are unchanged) and the branch splits on it.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_auto_allocate_candidates(
  p_hostel_type text,
  p_strict boolean DEFAULT true,
  p_institution_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_allow_overflow boolean DEFAULT true
)
RETURNS TABLE(
  learner_id uuid, full_name text, email text, institution_name text,
  program_name text, semester_name text, gender text,
  has_profile boolean, gender_ok boolean, not_allocated boolean,
  physical_rule_ok boolean, overflow_room_ok boolean, placement_tier text,
  bed_available boolean, target_block_name text,
  academic_year_id uuid, academic_year_name text,
  admission_academic_year_id uuid, admission_academic_year_name text,
  band_academic_year_id uuid, band_academic_year_name text, band_fee numeric,
  academic_bill_count integer, current_year_bill_count integer,
  bill_other_year_name text, current_year_fee numeric,
  resolved_room_category_id uuid, resolved_room_category_name text,
  resolved_mess_category_id uuid, resolved_mess_category_name text,
  bill_state text, stage text, verdict text, exclusion_reason text
)
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  WITH blocks AS MATERIALIZED (
    SELECT id, name FROM hostel_blocks WHERE hostel_type::text = p_hostel_type
  ),
  scope_rooms AS MATERIALIZED (
    SELECT r.id, r.block_id, b.name AS block_name, r.floor, r.room_number,
           r.category_id, hc.type AS cat_type
    FROM hostel_rooms r
    JOIN blocks b ON b.id = r.block_id
    LEFT JOIN hostel_categories hc ON hc.id = r.category_id
    WHERE r.room_purpose = 'student'
  ),
  raw_cohort AS MATERIALIZED (
    SELECT lp.id, lp.institution_id, lp.degree_id, lp.department_id,
           lp.program_id, lp.semester_id, lp.academic_year_id, lp.quota_id,
           lp.first_name, lp.last_name,
           CASE WHEN lower(lp.gender) LIKE 'm%' THEN 'boys'
                WHEN lower(lp.gender) LIKE 'f%' THEN 'girls' END AS lp_gender_type,
           -- The one place gender is resolved. profiles.gender (the login
           -- shadow) is still read first; learners_profiles — the master record
           -- the rest of this function already trusts for lp_gender_type — only
           -- fills a blank. NULLIF, not COALESCE alone: '' is not NULL, so
           -- without it an empty-string shadow would still win over a perfectly
           -- good master value. Everything downstream reads this alias, so the
           -- category resolver and the gender/room checks can no longer
           -- disagree about the same learner.
           lower(btrim(COALESCE(NULLIF(btrim(gp.gender), ''), lp.gender))) AS eff_gender
    FROM learners_profiles lp
    LEFT JOIN profiles gp ON gp.learner_id = lp.id
    WHERE lp.accommodation_type_id IN (SELECT id FROM accommodation_types WHERE code = 'hostel')
      AND lp.lifecycle_status = 'active'
      AND lp.institution_id IN (
            SELECT bi.institution_id FROM hostel_block_institutions bi
            WHERE bi.block_id IN (SELECT id FROM blocks))
      AND (p_institution_id IS NULL OR lp.institution_id = p_institution_id)
      AND (p_program_id     IS NULL OR lp.program_id     = p_program_id)
      AND (p_semester_id    IS NULL OR lp.semester_id    = p_semester_id)
      -- Same resolution as eff_gender above, inlined because a SELECT alias is
      -- not visible in WHERE. Reading the shadow alone put a learner with a
      -- blank profiles.gender into the permissive "unknown" branch, so they
      -- appeared in BOTH the boys and the girls preview; resolved against the
      -- master record they now appear in exactly one. The unknown branch is
      -- kept for a learner with NO gender anywhere — they must still surface,
      -- and get told so, rather than silently vanish from every run.
      AND (COALESCE(NULLIF(btrim(gp.gender), ''), NULLIF(btrim(lp.gender), '')) IS NULL
           OR (p_hostel_type = 'boys'
               AND lower(btrim(COALESCE(NULLIF(btrim(gp.gender), ''), lp.gender))) IN ('male','m'))
           OR (p_hostel_type = 'girls'
               AND lower(btrim(COALESCE(NULLIF(btrim(gp.gender), ''), lp.gender))) IN ('female','f')))
      AND NOT EXISTS (
        SELECT 1 FROM hostel_allocations ha2
        JOIN profiles pr2 ON pr2.learner_id = lp.id
        WHERE ha2.learner_id = pr2.id
          AND ha2.status IN ('active', 'pending_approval')
      )
  ),
  -- ── Overflow tier 2: rooms NO active rule covers ─────────────────────────
  -- "Unreserved" is a property of the ROOM ALONE — it does not depend on the
  -- learner — so this is evaluated ONCE per run, not per learner. That is what
  -- keeps the 8s statement_timeout safe: it adds no per-learner plpgsql calls,
  -- which is the exact cost the signature cache exists to avoid.
  --
  -- The CASE below is a verbatim copy of v_has_covering inside
  -- fn_learner_strictly_eligible_for_room. It MUST stay identical: if the two
  -- drift, a room could be "unreserved" here and "reserved" there, and the
  -- overflow would hand out a bed the predicate says belongs to someone else.
  unruled_rooms AS MATERIALIZED (
    SELECT sr.id AS room_id, sr.category_id, sr.cat_type,
           sr.block_name, sr.floor, sr.room_number
    FROM scope_rooms sr
    WHERE NOT EXISTS (
      SELECT 1 FROM hostel_room_eligibility_rules re
      WHERE re.is_active AND re.block_id = sr.block_id
        AND CASE
              WHEN EXISTS (SELECT 1 FROM hostel_room_eligibility_rule_rooms rr
                           WHERE rr.rule_id = re.id)
                THEN EXISTS (SELECT 1 FROM hostel_room_eligibility_rule_rooms rr
                             WHERE rr.rule_id = re.id AND rr.room_id = sr.id)
              ELSE (re.floor IS NULL OR re.floor = sr.floor)
            END
    )
  ),
  -- Institution access is still a HARD gate on the overflow tier: an unreserved
  -- room is only reachable by institutions the block actually serves. Costed
  -- per (distinct institution x unreserved room) — a handful of institutions,
  -- not per learner.
  overflow_rooms AS MATERIALIZED (
    SELECT i.institution_id, ur.room_id, ur.category_id, ur.cat_type,
           ur.block_name, ur.floor, ur.room_number
    FROM (SELECT DISTINCT institution_id FROM raw_cohort) i
    CROSS JOIN unruled_rooms ur
    WHERE p_allow_overflow
      AND fn_room_serves_institution(ur.room_id, i.institution_id)
  ),
  sigs AS MATERIALIZED (
    SELECT institution_id, degree_id, department_id, program_id, semester_id,
           (array_agg(id))[1] AS rep
    FROM raw_cohort
    GROUP BY 1,2,3,4,5
  ),
  sig_rooms AS MATERIALIZED (
    SELECT s.rep, sr.id AS room_id, sr.category_id, sr.cat_type,
           sr.block_name, sr.floor, sr.room_number
    FROM sigs s
    CROSS JOIN scope_rooms sr
    WHERE fn_room_serves_institution(sr.id, s.institution_id)
      AND fn_learner_strictly_eligible_for_room(s.rep, sr.id, p_strict)
  ),
  free_beds AS MATERIALIZED (
    SELECT bd.id, bd.room_id, bd.bed_number
    FROM hostel_beds bd
    JOIN scope_rooms sr ON sr.id = bd.room_id
    WHERE bd.status = 'available'
      AND NOT EXISTS (SELECT 1 FROM hostel_allocations a
                      WHERE a.bed_id = bd.id AND a.status IN ('active','pending_approval'))
  ),
  fee AS MATERIALIZED (
    SELECT c.id, adm.ay_id AS adm_ay,
           bf.academic_year_id AS band_ay, bf.academic_year_name AS band_ay_name, bf.fee
    FROM raw_cohort c
    LEFT JOIN LATERAL (SELECT fn_learner_admission_academic_year(c.id) AS ay_id) adm ON true
    LEFT JOIN LATERAL fn_learner_band_academic_fee(c.id) bf ON true
  ),
  cats AS MATERIALIZED (
    SELECT c.id,
      CASE WHEN c.institution_id IS NOT NULL AND c.program_id IS NOT NULL AND f.fee IS NOT NULL
           THEN (SELECT array_agg(category_id) FROM fn_hostel_effective_room_categories(
                   c.institution_id, c.program_id, c.quota_id, f.fee, c.lp_gender_type)) END AS room_cats,
      CASE WHEN c.institution_id IS NOT NULL AND c.program_id IS NOT NULL AND f.fee IS NOT NULL
           THEN (SELECT array_agg(category_id) FROM fn_hostel_effective_mess_categories(
                   c.institution_id, c.program_id, c.quota_id, f.fee, c.lp_gender_type)) END AS mess_cats
    FROM raw_cohort c JOIN fee f ON f.id = c.id
  ),
  base AS (
    SELECT
      c.id AS learner_id,
      COALESCE(p.full_name,
               NULLIF(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''),
               p.email, '—') AS full_name,
      p.email, inst.name AS institution_name, prog.program_name, sem.semester_name,
      -- Was lower(trim(p.gender)) — the login shadow. Now the resolved value.
      c.eff_gender AS gender,
      (p.id IS NOT NULL) AS has_profile,
      c.academic_year_id, ay.academic_year_name,
      ct.room_cats, ct.mess_cats,
      f.adm_ay AS admission_academic_year_id,
      aay.academic_year_name::text AS admission_academic_year_name,
      f.band_ay AS band_academic_year_id,
      f.band_ay_name AS band_academic_year_name,
      f.fee AS band_fee,
      ct.room_cats[1] AS resolved_room_category_id,
      rc.name AS resolved_room_category_name, rc.type AS resolved_room_category_type,
      ct.mess_cats[1] AS resolved_mess_category_id, mc.name AS resolved_mess_category_name,
      (SELECT count(*)::int FROM billing_student_bills b
         WHERE b.student_id = c.id AND b.fee_source = 'academic'
           AND b.status NOT IN ('cancelled','superseded')) AS academic_bill_count,
      (SELECT count(*)::int FROM billing_student_bills b
         WHERE b.student_id = c.id AND b.fee_source = 'academic'
           AND b.status NOT IN ('cancelled','superseded')
           AND b.academic_year_id = c.academic_year_id) AS current_year_bill_count,
      (SELECT ay2.academic_year_name
         FROM billing_student_bills b JOIN academic_years ay2 ON ay2.id = b.academic_year_id
        WHERE b.student_id = c.id AND b.fee_source = 'academic'
          AND b.status NOT IN ('cancelled','superseded')
          AND b.academic_year_id IS NOT NULL
          AND b.academic_year_id IS DISTINCT FROM c.academic_year_id
        ORDER BY b.created_at DESC LIMIT 1) AS bill_other_year_name,
      fn_learner_current_year_academic_fee(c.id) AS current_year_fee,
      true AS not_allocated,
      EXISTS (
        SELECT 1 FROM sig_rooms sr
        WHERE sr.rep = s.rep
          AND sr.category_id = ANY(ct.room_cats)
          AND (sr.cat_type IS NULL
               OR (sr.cat_type = 'boys'  AND c.eff_gender IN ('male','m'))
               OR (sr.cat_type = 'girls' AND c.eff_gender IN ('female','f')))
      ) AS physical_rule_ok,
      EXISTS (
        SELECT 1 FROM sig_rooms sr
        WHERE sr.rep = s.rep
          AND NOT (sr.category_id = ANY(ct.room_cats))
      ) AS physical_ok_other_category,
      -- Free beds of an eligible category that exist ANYWHERE in this hostel
      -- type, ignoring whether this learner may reach them. Internal to `base`
      -- (not in RETURNS TABLE), so adding it does not change the signature.
      -- Needed because bed_available answers a NARROWER question — "is there a
      -- free bed in a room THIS learner can reach" — and the exclusion message
      -- must not report that as "the category is exhausted".
      (SELECT count(*)::int
         FROM free_beds bd2
         JOIN scope_rooms sr2 ON sr2.id = bd2.room_id
        WHERE sr2.category_id = ANY(ct.room_cats)
          AND (sr2.cat_type IS NULL
               OR (sr2.cat_type = 'boys'  AND c.eff_gender IN ('male','m'))
               OR (sr2.cat_type = 'girls' AND c.eff_gender IN ('female','f')))
      ) AS category_free_beds_anywhere,
      -- Tier 2 reachability, independent of whether a BED is free there. Kept
      -- separate from physical_rule_ok so the preview can still say truthfully
      -- whether a RULE covers them; the verdict below accepts either.
      -- overflow_rooms is already empty when p_allow_overflow is false, so this
      -- needs no extra guard.
      EXISTS (
        SELECT 1 FROM overflow_rooms orm
        WHERE orm.institution_id = c.institution_id
          AND orm.category_id = ANY(ct.room_cats)
          AND (orm.cat_type IS NULL
               OR (orm.cat_type = 'boys'  AND c.eff_gender IN ('male','m'))
               OR (orm.cat_type = 'girls' AND c.eff_gender IN ('female','f')))
      ) AS overflow_room_ok,
      (tgt.block_name IS NOT NULL) AS bed_available,
      tgt.block_name AS target_block_name,
      CASE tgt.tier WHEN 1 THEN 'rule' WHEN 2 THEN 'overflow' END AS placement_tier
    FROM raw_cohort c
    JOIN cats ct ON ct.id = c.id
    JOIN fee  f  ON f.id  = c.id
    JOIN sigs s  ON s.institution_id IS NOT DISTINCT FROM c.institution_id
                AND s.degree_id      IS NOT DISTINCT FROM c.degree_id
                AND s.department_id  IS NOT DISTINCT FROM c.department_id
                AND s.program_id     IS NOT DISTINCT FROM c.program_id
                AND s.semester_id    IS NOT DISTINCT FROM c.semester_id
    LEFT JOIN profiles p        ON p.learner_id = c.id
    LEFT JOIN institutions inst ON inst.id = c.institution_id
    LEFT JOIN programs prog     ON prog.id = c.program_id
    LEFT JOIN semesters sem     ON sem.id = c.semester_id
    LEFT JOIN academic_years ay ON ay.id = c.academic_year_id
    LEFT JOIN academic_years aay ON aay.id = f.adm_ay
    LEFT JOIN hostel_categories rc ON rc.id = ct.room_cats[1]
    LEFT JOIN mess_categories   mc ON mc.id = ct.mess_cats[1]
    -- Predicted bed across BOTH tiers, in one ordered pass. Same ORDER BY as
    -- fn_auto_allocate_classic, so this stays a real prediction.
    -- Category priority sits above tier on purpose (see header): entitlement
    -- first, then prefer a reserved room over an unreserved one within that
    -- category. With p_allow_overflow = false the UNION's second leg is empty
    -- and the sort degenerates to the previous ORDER BY exactly.
    LEFT JOIN LATERAL (
      SELECT x.block_name, x.tier
      FROM (
        SELECT sr.room_id, sr.category_id, sr.cat_type,
               sr.block_name, sr.floor, sr.room_number, 1 AS tier
        FROM sig_rooms sr
        WHERE sr.rep = s.rep
        UNION ALL
        SELECT orm.room_id, orm.category_id, orm.cat_type,
               orm.block_name, orm.floor, orm.room_number, 2
        FROM overflow_rooms orm
        WHERE orm.institution_id = c.institution_id
      ) x
      JOIN free_beds bd ON bd.room_id = x.room_id
      WHERE x.category_id = ANY(ct.room_cats)
        AND (x.cat_type IS NULL
             OR (x.cat_type = 'boys'  AND c.eff_gender IN ('male','m'))
             OR (x.cat_type = 'girls' AND c.eff_gender IN ('female','f')))
      ORDER BY array_position(ct.room_cats, x.category_id), x.tier,
               x.block_name, x.floor, x.room_number, bd.bed_number
      LIMIT 1
    ) tgt ON true
  ),
  scored AS (
    SELECT b.*,
      -- NULL-safe. Without the leading IS NOT NULL guard, an absent gender made
      -- this `false OR NULL OR false` = NULL, and every downstream
      -- `NOT gender_ok` test silently stopped matching (NOT NULL is NULL, and a
      -- CASE/WHERE needs true) — so the row fell through to the physical-room
      -- branch and blamed a room rule for a missing gender. Now it is a plain
      -- false and the dedicated branch below reports the real cause.
      (b.gender IS NOT NULL
        AND (b.resolved_room_category_type IS NULL
          OR (b.resolved_room_category_type = 'boys'  AND b.gender IN ('male','m'))
          OR (b.resolved_room_category_type = 'girls' AND b.gender IN ('female','f')))) AS gender_ok
    FROM base b
  )
  SELECT
    s.learner_id, s.full_name, s.email, s.institution_name, s.program_name, s.semester_name,
    s.gender, s.has_profile, s.gender_ok, s.not_allocated, s.physical_rule_ok,
    s.overflow_room_ok, s.placement_tier,
    s.bed_available, s.target_block_name,
    s.academic_year_id, s.academic_year_name,
    s.admission_academic_year_id, s.admission_academic_year_name,
    s.band_academic_year_id, s.band_academic_year_name, s.band_fee,
    s.academic_bill_count, s.current_year_bill_count, s.bill_other_year_name, s.current_year_fee,
    s.resolved_room_category_id, s.resolved_room_category_name,
    s.resolved_mess_category_id, s.resolved_mess_category_name,
    CASE
      WHEN s.band_fee IS NOT NULL
       AND s.band_academic_year_id IS NOT DISTINCT FROM s.admission_academic_year_id THEN 'matched'
      WHEN s.band_fee IS NOT NULL          THEN 'different_year'
      WHEN s.academic_bill_count > 0       THEN 'untagged'
      ELSE 'none'
    END AS bill_state,
    CASE
      WHEN s.band_fee  IS NULL THEN 'prerequisite'
      WHEN s.room_cats IS NULL THEN 'prerequisite'
      -- Reachability is now "a rule covers a room of their category OR an
      -- unreserved one exists", not "a rule covers one".
      WHEN NOT s.has_profile OR NOT s.gender_ok
        OR NOT (s.physical_rule_ok OR s.overflow_room_ok) OR NOT s.bed_available
                               THEN 'eligibility'
      ELSE 'ok'
    END AS stage,
    CASE
      WHEN s.band_fee  IS NULL THEN 'out'
      WHEN s.room_cats IS NULL THEN 'out'
      WHEN NOT s.has_profile OR NOT s.gender_ok
        OR NOT (s.physical_rule_ok OR s.overflow_room_ok) OR NOT s.bed_available
                               THEN 'out'
      ELSE 'in'
    END AS verdict,
    CASE
      WHEN s.band_fee IS NULL THEN
        CASE
          WHEN s.academic_bill_count = 0 THEN
            'No academic bill for this student — nothing to read a fee band from'
          ELSE
            'Academic bills exist but none is usable: either untagged to an academic year, or the tagged year totals ₹0'
        END
      WHEN s.room_cats IS NULL THEN
        'No Category-Eligibility band covers ₹'
        || to_char(s.band_fee, 'FM999,999,999')
        || ' (read from ' || COALESCE(s.band_academic_year_name, 'their admission year') || ')'
        || ' for this program / quota — add or widen a band'
      WHEN NOT s.has_profile   THEN 'No login profile'
      -- Ordered BEFORE the generic gender_ok branch: "not set" and "set but
      -- wrong" are different operator actions (fill the field vs fix the
      -- category), and this case previously reached neither branch at all.
      WHEN s.gender IS NULL    THEN
        'Gender is not set on this learner — set it on the learner profile, then re-run the preview'
      WHEN NOT s.gender_ok     THEN 'Gender does not match the resolved room category'
      WHEN NOT (s.physical_rule_ok OR s.overflow_room_ok) AND s.physical_ok_other_category THEN
        'Rooms they may occupy are a different room category than their eligible '
        || COALESCE(s.resolved_room_category_name, 'category')
        || ' — fix the reservation rooms or the Category-Eligibility band'
      WHEN NOT (s.physical_rule_ok OR s.overflow_room_ok) THEN
        CASE WHEN p_strict
          THEN 'No physical-room rule reserves a room for this cohort in any ' || p_hostel_type || ' block (strict mode)'
          ELSE 'No room they can occupy in their category — every room is reserved for other cohorts'
        END
      -- No free bed in a room THIS learner can reach. Two very different causes,
      -- and conflating them is what made the previous wording false: it claimed
      -- the category was exhausted while 17 free Classic beds sat in Girls
      -- Hostel A, every one of them reserved for a different cohort. That sent
      -- the operator looking for beds instead of at the rules.
      WHEN NOT s.bed_available THEN
        CASE
          -- Beds of their category DO exist — they just cannot reach any.
          WHEN s.category_free_beds_anywhere > 0 THEN
            COALESCE(s.resolved_room_category_name, 'Their category')
            || ': ' || s.category_free_beds_anywhere::text
            || ' free bed' || CASE WHEN s.category_free_beds_anywhere = 1 THEN '' ELSE 's' END
            || ' exist in the ' || p_hostel_type || ' blocks, but every one is in a room'
            || ' reserved for another cohort'
            || CASE WHEN p_allow_overflow
                 THEN ' and no unreserved room of this category exists — add this cohort'
                      || ' to a physical-room rule that covers one of those rooms'
                 ELSE ' (overflow is off, so unreserved rooms were not considered)'
               END
          -- Genuinely none left anywhere in this hostel type.
          ELSE
            COALESCE(s.resolved_room_category_name, 'Their category')
            || ' is exhausted in every ' || p_hostel_type
            || ' block — no free bed in any '
            || COALESCE(s.resolved_room_category_name, 'eligible')
            || ' room, reserved or unreserved'
        END
      ELSE NULL
    END AS exclusion_reason
  FROM scored s
  ORDER BY s.full_name;
$function$;

-- ============================================================================
-- Bill Coverage: expose Total Paid alongside Total Billed
-- ============================================================================
-- REQUEST (2026-08-11, /billing/coverage): the XLS/CSV export carries "Total
-- Billed" but no "Total Paid", so a coverage sheet cannot be reconciled without
-- pulling a second report. The column did not exist to export — the list RPC's
-- RETURNS TABLE only ever produced out_bill_count and out_total_billed.
--
-- PAID IS NOT REDEFINED HERE. get_billing_coverage_learner_bills (the PDF
-- export, migration 20260729) already settled the arithmetic:
--
--     paid = SUM(final_amount - balance_amount)
--
-- over the SAME live-bill set the coverage verdict itself is computed from —
-- status NOT IN ('cancelled','superseded'), the bill's OWN academic_year_id
-- equal to the target year, and the optional category filter. Deriving paid any
-- other way here (e.g. from receipts, or over all years) would let the XLS and
-- the PDF report different figures for the same learner on the same filters,
-- which is the failure mode 20260808120000 was written to end.
--
-- COALESCE on balance_amount is deliberate. The column is nullable with DEFAULT
-- 0; a NULL would make `final_amount - balance_amount` NULL, SUM would skip that
-- bill, and total_paid would silently understate while total_billed still
-- counted it. Zero live bills are NULL today (13,425 checked 2026-08-11) — the
-- guard is there so that stays true by construction rather than by luck.
--
-- 'total_paid' also joins the sort whitelist. A header the RPC does not
-- recognise falls through to the default order while the UI still draws a sort
-- arrow, so a sortable column MUST be added in both places or it lies.
-- ============================================================================

-- ── Learner list ────────────────────────────────────────────────────────────
-- DROP + CREATE, not CREATE OR REPLACE: out_total_paid is a new RETURNS TABLE
-- column and Postgres cannot replace a function whose output type changed.
-- DROP discards the ACL, so the grants at the bottom are mandatory, not
-- tidy-up — without them EXECUTE reverts to the PUBLIC default.
DROP FUNCTION IF EXISTS public.get_billing_coverage_learners(
  uuid, uuid[], text[], uuid, text, boolean, text, integer, integer,
  uuid[], text, text, text, text, uuid, uuid, uuid, uuid, uuid);

CREATE FUNCTION public.get_billing_coverage_learners(
  p_academic_year_id uuid DEFAULT NULL,
  p_institution_ids uuid[] DEFAULT NULL,
  p_lifecycle_statuses text[] DEFAULT ARRAY['active','reserved','admitted','account'],
  p_billing_category_id uuid DEFAULT NULL,
  p_coverage_state text DEFAULT 'not_generated',
  p_include_non_billing_institutions boolean DEFAULT false,
  p_search text DEFAULT NULL,
  p_page integer DEFAULT 1,
  p_page_size integer DEFAULT 50,
  p_accommodation_type_ids uuid[] DEFAULT NULL,
  p_transport text DEFAULT 'any',
  p_gender text DEFAULT NULL,
  p_sort_by text DEFAULT NULL,
  p_sort_dir text DEFAULT 'asc',
  p_degree_id uuid DEFAULT NULL,
  p_department_id uuid DEFAULT NULL,
  p_program_id uuid DEFAULT NULL,
  p_semester_id uuid DEFAULT NULL,
  p_section_id uuid DEFAULT NULL
)
RETURNS TABLE(
  out_learner_id uuid,
  out_roll_number text,
  out_register_number text,
  out_full_name text,
  out_lifecycle_status text,
  out_gender text,
  out_institution_id uuid,
  out_institution_name text,
  out_program_name text,
  out_semester_section text,
  out_academic_year_id uuid,
  out_academic_year_name text,
  out_accommodation_type text,
  out_uses_transport boolean,
  out_bill_count integer,
  out_total_billed numeric,
  out_total_paid numeric,
  out_coverage_state text,
  out_target_academic_year_name text,
  out_total_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst   uuid[];
  v_limit  integer := LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 200);
  v_offset integer := GREATEST(COALESCE(p_page, 1) - 1, 0)
                      * LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 200);
  v_asc    boolean := COALESCE(LOWER(p_sort_dir), 'asc') <> 'desc';
  -- Name of an explicitly picked year, so the reported target reflects the
  -- caller's choice rather than the institution's current year.
  v_picked_ay_name text;
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN;
  END IF;

REVOKE EXECUTE ON FUNCTION public.fn_audit_admission_lead_source() FROM anon, PUBLIC;

-- ============================================================================
-- Bill Coverage: expose Total Paid alongside Total Billed
-- ============================================================================
-- REQUEST (2026-08-11, /billing/coverage): the XLS/CSV export carries "Total
-- Billed" but no "Total Paid", so a coverage sheet cannot be reconciled without
-- pulling a second report. The column did not exist to export — the list RPC's
-- RETURNS TABLE only ever produced out_bill_count and out_total_billed.
--
-- PAID IS NOT REDEFINED HERE. get_billing_coverage_learner_bills (the PDF
-- export, migration 20260729) already settled the arithmetic:
--
--     paid = SUM(final_amount - balance_amount)
--
-- over the SAME live-bill set the coverage verdict itself is computed from —
-- status NOT IN ('cancelled','superseded'), the bill's OWN academic_year_id
-- equal to the target year, and the optional category filter. Deriving paid any
-- other way here (e.g. from receipts, or over all years) would let the XLS and
-- the PDF report different figures for the same learner on the same filters,
-- which is the failure mode 20260808120000 was written to end.
--
-- COALESCE on balance_amount is deliberate. The column is nullable with DEFAULT
-- 0; a NULL would make `final_amount - balance_amount` NULL, SUM would skip that
-- bill, and total_paid would silently understate while total_billed still
-- counted it. Zero live bills are NULL today (13,425 checked 2026-08-11) — the
-- guard is there so that stays true by construction rather than by luck.
--
-- 'total_paid' also joins the sort whitelist. A header the RPC does not
-- recognise falls through to the default order while the UI still draws a sort
-- arrow, so a sortable column MUST be added in both places or it lies.
-- ============================================================================

-- ── Learner list ────────────────────────────────────────────────────────────
-- DROP + CREATE, not CREATE OR REPLACE: out_total_paid is a new RETURNS TABLE
-- column and Postgres cannot replace a function whose output type changed.
-- DROP discards the ACL, so the grants at the bottom are mandatory, not
-- tidy-up — without them EXECUTE reverts to the PUBLIC default.
DROP FUNCTION IF EXISTS public.get_billing_coverage_learners(
  uuid, uuid[], text[], uuid, text, boolean, text, integer, integer,
  uuid[], text, text, text, text, uuid, uuid, uuid, uuid, uuid);

CREATE FUNCTION public.get_billing_coverage_learners(
  p_academic_year_id uuid DEFAULT NULL,
  p_institution_ids uuid[] DEFAULT NULL,
  p_lifecycle_statuses text[] DEFAULT ARRAY['active','reserved','admitted','account'],
  p_billing_category_id uuid DEFAULT NULL,
  p_coverage_state text DEFAULT 'not_generated',
  p_include_non_billing_institutions boolean DEFAULT false,
  p_search text DEFAULT NULL,
  p_page integer DEFAULT 1,
  p_page_size integer DEFAULT 50,
  p_accommodation_type_ids uuid[] DEFAULT NULL,
  p_transport text DEFAULT 'any',
  p_gender text DEFAULT NULL,
  p_sort_by text DEFAULT NULL,
  p_sort_dir text DEFAULT 'asc',
  p_degree_id uuid DEFAULT NULL,
  p_department_id uuid DEFAULT NULL,
  p_program_id uuid DEFAULT NULL,
  p_semester_id uuid DEFAULT NULL,
  p_section_id uuid DEFAULT NULL
)
RETURNS TABLE(
  out_learner_id uuid,
  out_roll_number text,
  out_register_number text,
  out_full_name text,
  out_lifecycle_status text,
  out_gender text,
  out_institution_id uuid,
  out_institution_name text,
  out_program_name text,
  out_semester_section text,
  out_academic_year_id uuid,
  out_academic_year_name text,
  out_accommodation_type text,
  out_uses_transport boolean,
  out_bill_count integer,
  out_total_billed numeric,
  out_total_paid numeric,
  out_coverage_state text,
  out_target_academic_year_name text,
  out_total_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst   uuid[];
  v_limit  integer := LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 200);
  v_offset integer := GREATEST(COALESCE(p_page, 1) - 1, 0)
                      * LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 200);
  v_asc    boolean := COALESCE(LOWER(p_sort_dir), 'asc') <> 'desc';
  -- Name of an explicitly picked year, so the reported target reflects the
  -- caller's choice rather than the institution's current year.
  v_picked_ay_name text;
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN;
  END IF;

  SELECT ay.academic_year_name::text INTO v_picked_ay_name
  FROM public.academic_years ay WHERE ay.id = p_academic_year_id;

  RETURN QUERY
  WITH target_year AS MATERIALIZED (
    SELECT t.institution_id, t.target_ay_id, t.target_ay_name
    FROM public.fn_billing_coverage_target_years() t
  ),
  billing_inst AS (
    -- ALL-TIME test, deliberately not scoped to p_academic_year_id. An
    -- institution that billed last year and has generated nothing this year is
    -- the case this report exists to catch; scoping here would hide it.
    SELECT DISTINCT b.institution_id AS inst_id
    FROM public.billing_student_bills b
  ),
  scope AS (
    -- NOTE: no lp.academic_year_id predicate. p_academic_year_id selects the
    -- year being MEASURED, never the learners being measured — see
    -- 20260808120000_billing_coverage_target_academic_year.sql.
    SELECT lp.id, lp.institution_id, lp.academic_year_id, lp.program_id,
           lp.semester_id, lp.section_id, lp.gender,
           lp.lifecycle_status, lp.first_name, lp.last_name,
           lp.roll_number, lp.register_number,
           lp.accommodation_type_id,
           (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL)
             AS uses_transport
    FROM public.learners_profiles lp
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_billing_institutions
           OR lp.institution_id IN (SELECT inst_id FROM billing_inst))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
      AND (
        p_search IS NULL OR p_search = ''
        OR lp.roll_number ILIKE '%' || p_search || '%'
        OR lp.register_number ILIKE '%' || p_search || '%'
        OR (COALESCE(lp.first_name,'') || ' ' || COALESCE(lp.last_name,''))
             ILIKE '%' || p_search || '%'
      )
  ),
  agg AS (
    SELECT s.id AS learner_id,
           ty.target_ay_id,
           ty.target_ay_name,
           COUNT(b.id)::integer AS bill_count,
           COALESCE(SUM(b.final_amount), 0)::numeric AS total_billed,
           -- Same expression as get_billing_coverage_learner_bills, over the
           -- same join — the XLS and the PDF must never disagree. A learner
           -- with no live bill sums to NULL and lands on 0, matching the 0 they
           -- already show for total_billed.
           COALESCE(
             SUM(b.final_amount - COALESCE(b.balance_amount, 0)), 0
           )::numeric AS total_paid
    FROM scope s
    LEFT JOIN target_year ty ON ty.institution_id = s.institution_id
    LEFT JOIN public.billing_student_bills b
           ON b.student_id = s.id
          -- A cancelled or superseded bill is not coverage: no live bill exists.
          AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
          -- The bill's OWN year against the target year. Was s.academic_year_id.
          AND b.academic_year_id = COALESCE(p_academic_year_id, ty.target_ay_id)
          AND (p_billing_category_id IS NULL
               OR b.item_category_id = p_billing_category_id)
    GROUP BY s.id, ty.target_ay_id, ty.target_ay_name
  ),
  final AS (
    SELECT s.id AS learner_id,
           s.roll_number::text        AS roll_number,
           s.register_number::text    AS register_number,
           TRIM(COALESCE(s.first_name,'') || ' ' || COALESCE(s.last_name,''))
                                      AS full_name,
           s.lifecycle_status::text   AS lifecycle_status,
           NULLIF(TRIM(s.gender), '')::text AS gender,
           s.institution_id           AS institution_id,
           i.name::text               AS institution_name,
           p.program_name             AS program_name,
           CASE
             WHEN sem.semester_name IS NULL AND sec.section_name IS NULL
               THEN NULL
             WHEN sec.section_name IS NULL THEN sem.semester_name::text
             WHEN sem.semester_name IS NULL THEN sec.section_name::text
             ELSE sem.semester_name::text || ' · ' || sec.section_name::text
           END                        AS semester_section,
           -- The learner's OWN year, shown for context. It is no longer what
           -- coverage is measured against; target_academic_year_name is.
           s.academic_year_id         AS academic_year_id,
           ay.academic_year_name::text AS academic_year_name,
           acc.name::text             AS accommodation_type,
           s.uses_transport           AS uses_transport,
           a.bill_count               AS bill_count,
           a.total_billed             AS total_billed,
           a.total_paid               AS total_paid,
           CASE
             -- Only when NO year can be resolved at all: an institution with no
             -- active year that has started yet. Never a mere mismatch.
             WHEN COALESCE(p_academic_year_id, a.target_ay_id) IS NULL
               THEN 'cannot_evaluate'
             WHEN a.bill_count > 0 THEN 'generated'
             ELSE 'not_generated'
           END                        AS coverage_state,
           COALESCE(v_picked_ay_name, a.target_ay_name)
                                      AS target_academic_year_name
    FROM scope s
    JOIN agg a                           ON a.learner_id = s.id
    LEFT JOIN public.institutions        i   ON i.id   = s.institution_id
    LEFT JOIN public.programs            p   ON p.id   = s.program_id
    LEFT JOIN public.semesters           sem ON sem.id = s.semester_id
    LEFT JOIN public.sections            sec ON sec.id = s.section_id
    LEFT JOIN public.academic_years      ay  ON ay.id  = s.academic_year_id
    LEFT JOIN public.accommodation_types acc ON acc.id = s.accommodation_type_id
  ),
  filtered AS (
    SELECT * FROM final f
    WHERE p_coverage_state = 'all' OR f.coverage_state = p_coverage_state
  )
  SELECT f.learner_id, f.roll_number, f.register_number, f.full_name,
         f.lifecycle_status, f.gender, f.institution_id, f.institution_name,
         f.program_name, f.semester_section,
         f.academic_year_id, f.academic_year_name,
         f.accommodation_type, f.uses_transport,
         f.bill_count, f.total_billed, f.total_paid, f.coverage_state,
         f.target_academic_year_name,
         COUNT(*) OVER ()::bigint
  FROM filtered f
  ORDER BY
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'academic_year_name' THEN f.academic_year_name
         WHEN 'accommodation_type' THEN f.accommodation_type
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'gender'             THEN f.gender
         WHEN 'coverage_state'     THEN f.coverage_state
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'academic_year_name' THEN f.academic_year_name
         WHEN 'accommodation_type' THEN f.accommodation_type
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'gender'             THEN f.gender
         WHEN 'coverage_state'     THEN f.coverage_state
       END
     END) DESC NULLS LAST,
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'bill_count'   THEN f.bill_count::numeric
         WHEN 'total_billed' THEN f.total_billed
         WHEN 'total_paid'   THEN f.total_paid
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'bill_count'   THEN f.bill_count::numeric
         WHEN 'total_billed' THEN f.total_billed
         WHEN 'total_paid'   THEN f.total_paid
       END
     END) DESC NULLS LAST,
    f.institution_name NULLS LAST, f.roll_number NULLS LAST, f.full_name
  LIMIT v_limit OFFSET v_offset;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_billing_coverage_learners(
  uuid, uuid[], text[], uuid, text, boolean, text, integer, integer,
  uuid[], text, text, text, text, uuid, uuid, uuid, uuid, uuid)
  FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_billing_coverage_learners(
  uuid, uuid[], text[], uuid, text, boolean, text, integer, integer,
  uuid[], text, text, text, text, uuid, uuid, uuid, uuid, uuid)
  TO authenticated, service_role;


-- =====================================================================
-- Added: 2026-08-06 - admission_leads source/referral audit trail
-- Mirror of migration 20260818020000_admission_lead_source_audit.sql
-- (ALREADY APPLIED TO PROD 2026-08-06 via hand-run SQL).
-- SECURITY DEFINER; only inserts an audit row when a watched field actually
-- changes, so the trigger can never block a legitimate lead update.
-- Table -> setup/01_tables.sql; trigger -> setup/04_triggers.sql.
-- =====================================================================
CREATE OR REPLACE FUNCTION public.fn_audit_admission_lead_source()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
BEGIN
  IF NEW.source IS DISTINCT FROM OLD.source THEN
    INSERT INTO public.admission_lead_source_audit(lead_id,learner_profile_id,changed_field,old_value,new_value,changed_by)
    VALUES (NEW.id,NEW.learner_profile_id,'source',OLD.source::text,NEW.source::text,auth.uid());
  END IF;
  IF NEW.source_detail IS DISTINCT FROM OLD.source_detail THEN
    INSERT INTO public.admission_lead_source_audit(lead_id,learner_profile_id,changed_field,old_value,new_value,changed_by)
    VALUES (NEW.id,NEW.learner_profile_id,'source_detail',OLD.source_detail,NEW.source_detail,auth.uid());
  END IF;
  IF NEW.referral_type IS DISTINCT FROM OLD.referral_type THEN
    INSERT INTO public.admission_lead_source_audit(lead_id,learner_profile_id,changed_field,old_value,new_value,changed_by)
    VALUES (NEW.id,NEW.learner_profile_id,'referral_type',OLD.referral_type,NEW.referral_type,auth.uid());
  END IF;
  IF NEW.referred_by_id IS DISTINCT FROM OLD.referred_by_id THEN
    INSERT INTO public.admission_lead_source_audit(lead_id,learner_profile_id,changed_field,old_value,new_value,changed_by)
    VALUES (NEW.id,NEW.learner_profile_id,'referred_by_id',OLD.referred_by_id::text,NEW.referred_by_id::text,auth.uid());
  END IF;
  IF NEW.referred_by_name IS DISTINCT FROM OLD.referred_by_name THEN
    INSERT INTO public.admission_lead_source_audit(lead_id,learner_profile_id,changed_field,old_value,new_value,changed_by)
    VALUES (NEW.id,NEW.learner_profile_id,'referred_by_name',OLD.referred_by_name,NEW.referred_by_name,auth.uid());
  END IF;
  RETURN NEW;
END $function$;

REVOKE EXECUTE ON FUNCTION public.fn_audit_admission_lead_source() FROM anon, PUBLIC;


-- ═══════════════════════════════════════════════════════════════════════════
-- Added: 2026-08-10 — Referral review worklist (read-only).
-- Mirror of supabase/migrations/20260818050000_referral_review_worklist_rpc.sql
-- ═══════════════════════════════════════════════════════════════════════════
-- ─────────────────────────────────────────────────────────────────────────────
-- Referral review worklist — ONE read RPC behind the /admission/consultants/
-- review-worklist screen. Created 2026-08-10.
--
-- WHY THIS EXISTS
--   Three populations of 2026-27 consultant credits were found by audit and have
--   never had a home in the UI. They are findings, not accusations, and none of
--   them is payable today: referral_rate_config holds no active 2026 rate and
--   consultant_commission_transactions has never held a row, so
--   fn_generate_referral_commissions resolves no rate and writes nothing. This
--   RPC exists so the Director can LOOK at all three on one screen BEFORE any
--   rate is switched on — the moment a rate is set, these rows stop being
--   curiosities and start being money.
--
--   A. walkin_credited    — the enquiry (admission_leads) is recorded as
--                           source='walk_in' yet an agency is credited on it.
--                           A walk-in CAN be genuinely agency-referred (the
--                           person walks in because an agency sent them), so
--                           this is a data-controls question about how the two
--                           fields are captured, never a claim about anyone.
--                           `days_after_enquiry` is carried through because it
--                           is the whole diagnostic: 0 means the agency was
--                           entered at enquiry creation, not attached later.
--   B. unlinked           — learners_profiles.referral_type='consultant' with
--                           referred_by_id IS NULL. The generator's candidate
--                           set requires referred_by_id IS NOT NULL, so these
--                           are skipped in silence and whoever is owed is never
--                           recorded. The LINKING screen is a separate change
--                           (PR #2793, /admission/consultants/unlinked-referrals);
--                           this RPC only counts and lists them.
--   C. no_enquiry_trail   — a credit with no admission_leads row behind it at
--                           all. Defined here by the ABSENCE of an enquiry, not
--                           by referral_source — 'auto_sync_learner' is what the
--                           2026-27 rows happen to carry, and hardcoding it
--                           would hide a trail-less credit that arrives by some
--                           other route later. referral_source is returned as
--                           data so the screen can still show it.
--
-- WHAT IT IS NOT
--   Read-only, and STABLE so that is structurally enforced rather than merely
--   promised: a STABLE function cannot write. No approve, no verify, no rate,
--   no commission, no payment. Nothing here changes a single row.
--
-- Year scoping matches fn_generate_referral_commissions exactly — the join to
-- admission_years (p_year 2026 = the 2026-27 intake). Any other definition of
-- "this year" would list a different population from the one the generator will
-- actually act on, which is the specific thing this screen must not do.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.fn_referral_review_worklist(p_year integer)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_walkin   jsonb;
  v_unlinked jsonb;
  v_orphan   jsonb;
BEGIN
  -- SECURITY DEFINER bypasses RLS, so the gate is explicit. Read-only screen →
  -- the read permission of the enquiry desk that owns this data.
  IF NOT (is_super_admin() OR is_admin() OR user_has_permission('admission.leads.view')) THEN
    RAISE EXCEPTION 'Not authorised to view the referral review worklist';
  END IF;

  -- A. Agency credited on an enquiry recorded as a walk-in.
  SELECT COALESCE(jsonb_agg(x ORDER BY x_created_at DESC), '[]'::jsonb)
    INTO v_walkin
  FROM (
    SELECT
      a.created_at AS x_created_at,
      jsonb_build_object(
        'attribution_id',      a.id,
        'learner_profile_id',  lp.id,
        'admission_lead_id',   al.id,
        'learner_name',        COALESCE(NULLIF(btrim(concat_ws(' ', lp.first_name, lp.last_name)), ''),
                                        NULLIF(btrim(al.full_name), '')),
        'programme',           pr.program_name,
        'institution',         inst.name,
        'agency_name',         ec.name,
        'credit_created_at',   a.created_at,
        'is_verified',         COALESCE(a.is_verified, false),
        'verified_by_name',    vp.full_name,
        'enquiry_source',      al.source::text,
        'enquiry_created_at',  al.created_at,
        'referral_source',     a.referral_source,
        -- 0 = the agency was on the enquiry the day it was created.
        'days_after_enquiry',  CASE
                                 WHEN al.created_at IS NULL OR a.created_at IS NULL THEN NULL
                                 ELSE floor(EXTRACT(EPOCH FROM (a.created_at - al.created_at)) / 86400)::int
                               END
      ) AS x
    FROM public.consultant_lead_attributions a
    JOIN public.admission_leads       al   ON al.id   = a.admission_id
    JOIN public.education_consultants ec   ON ec.id   = a.consultant_id
    LEFT JOIN public.learners_profiles lp  ON lp.id   = COALESCE(a.learner_profile_id, al.learner_profile_id)
    LEFT JOIN public.admission_years   ay  ON ay.id   = COALESCE(lp.admission_year_id, al.admission_year_id)
    LEFT JOIN public.programs          pr  ON pr.id   = lp.program_id
    LEFT JOIN public.institutions      inst ON inst.id = COALESCE(lp.institution_id, al.institution_id)
    LEFT JOIN public.profiles          vp  ON vp.id   = a.verified_by
    WHERE al.source::text = 'walk_in'
      AND ay.year = p_year
  ) s;

  -- B. referral_type says consultant, but no agency is linked, so the generator
  --    silently skips the row and nobody owed is ever recorded.
  SELECT COALESCE(jsonb_agg(x ORDER BY x_created_at DESC), '[]'::jsonb)
    INTO v_unlinked
  FROM (
    SELECT
      lp.created_at AS x_created_at,
      jsonb_build_object(
        'attribution_id',      NULL,
        'learner_profile_id',  lp.id,
        'admission_lead_id',   al.id,
        'learner_name',        NULLIF(btrim(concat_ws(' ', lp.first_name, lp.last_name)), ''),
        'programme',           pr.program_name,
        'institution',         inst.name,
        -- No agency is linked — this is the free-text name that was typed, when
        -- one was. NULL here means not even a name survives.
        'agency_name',         NULLIF(btrim(lp.referred_by_name), ''),
        'credit_created_at',   lp.created_at,
        'is_verified',         NULL,
        'verified_by_name',    NULL,
        'enquiry_source',      al.source::text,
        'enquiry_created_at',  al.created_at,
        'referral_source',     NULL,
        'days_after_enquiry',  NULL
      ) AS x
    FROM public.learners_profiles lp
    JOIN public.admission_years ay   ON ay.id   = lp.admission_year_id
    LEFT JOIN public.admission_leads al  ON al.learner_profile_id = lp.id
    LEFT JOIN public.programs        pr  ON pr.id   = lp.program_id
    LEFT JOIN public.institutions    inst ON inst.id = lp.institution_id
    WHERE ay.year = p_year
      AND lp.referral_type   = 'consultant'
      AND lp.referred_by_id IS NULL
  ) s;

  -- C. A credit with no enquiry behind it at all.
  SELECT COALESCE(jsonb_agg(x ORDER BY x_created_at DESC), '[]'::jsonb)
    INTO v_orphan
  FROM (
    SELECT
      a.created_at AS x_created_at,
      jsonb_build_object(
        'attribution_id',      a.id,
        'learner_profile_id',  lp.id,
        'admission_lead_id',   NULL,
        'learner_name',        NULLIF(btrim(concat_ws(' ', lp.first_name, lp.last_name)), ''),
        'programme',           pr.program_name,
        'institution',         inst.name,
        'agency_name',         ec.name,
        'credit_created_at',   a.created_at,
        'is_verified',         COALESCE(a.is_verified, false),
        'verified_by_name',    vp.full_name,
        'enquiry_source',      NULL,
        'enquiry_created_at',  NULL,
        'referral_source',     a.referral_source,
        'days_after_enquiry',  NULL
      ) AS x
    FROM public.consultant_lead_attributions a
    JOIN public.education_consultants ec   ON ec.id   = a.consultant_id
    JOIN public.learners_profiles     lp   ON lp.id   = a.learner_profile_id
    JOIN public.admission_years       ay   ON ay.id   = lp.admission_year_id
    LEFT JOIN public.programs         pr   ON pr.id   = lp.program_id
    LEFT JOIN public.institutions     inst ON inst.id = lp.institution_id
    LEFT JOIN public.profiles         vp   ON vp.id   = a.verified_by
    WHERE ay.year = p_year
      AND a.admission_id IS NULL
      AND NOT EXISTS (
            SELECT 1 FROM public.admission_leads al2
             WHERE al2.learner_profile_id = a.learner_profile_id)
  ) s;

  RETURN jsonb_build_object(
    'academic_year',        p_year,
    'generated_at',         now(),
    'walkin_credited',      v_walkin,
    'unlinked',             v_unlinked,
    'no_enquiry_trail',     v_orphan,
    'counts', jsonb_build_object(
      'walkin_credited',  jsonb_array_length(v_walkin),
      'unlinked',         jsonb_array_length(v_unlinked),
      'no_enquiry_trail', jsonb_array_length(v_orphan)
    ),
    -- The money position, read live rather than asserted in prose, so the
    -- screen's "nothing here is payable" banner can never go stale.
    'money_position', jsonb_build_object(
      'active_rate_count',
        (SELECT count(*) FROM public.referral_rate_config
          WHERE academic_year = p_year AND is_active),
      'commission_row_count',
        (SELECT count(*) FROM public.consultant_commission_transactions)
    )
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_referral_review_worklist(integer) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_referral_review_worklist(integer) TO authenticated;

COMMENT ON FUNCTION public.fn_referral_review_worklist(integer) IS
  'Read-only review worklist for consultant credits in an intake year: agency credited on a walk-in enquiry, referral_type=consultant with no agency linked, and credits with no enquiry behind them. STABLE, so it cannot write. Gated on admission.leads.view (or admin). Year scoping matches fn_generate_referral_commissions.';
-- ============================================================================
-- 2026-08-11 — Auto-Allocate: one shared planner; deterministic category
-- priority. Supersedes every fn_auto_allocate_* definition above (those carry
-- the retired block-scoped signatures). Mirrored from:
--   20260811150000_hostel_room_categories_deterministic_priority.sql
--   20260811150200_auto_allocate_shared_planner.sql
--   20260811150300_auto_allocate_candidates_reads_the_plan.sql
-- ============================================================================

-- ============================================================================
-- Campus Living — Category entitlement must come back in a DETERMINISTIC,
-- cheapest-first order (2026-08-11)
-- ============================================================================
--
-- fn_hostel_effective_room_categories returns EVERY eligibility row that shares
-- the winning (program_id, quota_ids, fee_min, fee_max) tuple, so a cohort can
-- legitimately hold more than one room category. Its final SELECT had no
-- ORDER BY, so the array built by
--
--     array_agg(category_id) FROM fn_hostel_effective_room_categories(...)
--
-- came back in whatever order the planner produced.
--
-- That array is NOT just a set. Both engine functions sort candidate beds with
--
--     ORDER BY array_position(cand.room_cats, x.category_id), tier, ...
--
-- and the 20260810200000 header describes room_cats as "priority-ordered
-- entitlement". It never was — the ordering was accidental. Today it cannot
-- bite: measured on 2026-08-11, 693 of 696 active hostel learners resolve to
-- exactly ONE category and 3 to none, so every array has at most one element
-- and this change is a provable no-op.
--
-- It stops being a no-op in the very next migration, which grants the Nursing
-- and B.Pharm girls a SECOND category (Deluxe) alongside Classic so they can be
-- housed in Girls Hostel B / C. Without a defined order those learners could be
-- sent to a ₹35,000 Deluxe bed while a ₹27,500 Classic bed they are entitled to
-- sits free — and the preview and the allocator could even disagree with each
-- other, because each evaluates the array in its own plan.
--
-- ORDER: hostel_categories.sort_order (Classic 1 → Deluxe 2 → Premium 3 →
-- Premium Plus 4 → Premium+AC 5), i.e. cheapest entitled room first, then name
-- as a stable tiebreak. Filling the base category before spilling upward is
-- both the cheaper outcome for the learner and the one that preserves premium
-- inventory.
--
-- DISTINCT: two rows of the winning tuple can map onto the SAME effective
-- category once the gender-sibling remap runs (a 'both' row carrying the boys
-- category and a 'girls' row carrying the girls one both resolve to the girls
-- category). A duplicate would make array_position ambiguous. No such pair
-- exists today; the guard is here so adding one later cannot corrupt priority.
--
-- Signature, volatility, security and search_path are unchanged, so this is a
-- plain CREATE OR REPLACE: the EXECUTE grants to authenticated / service_role
-- survive and no second overload is created.
--
-- fn_hostel_effective_mess_categories is deliberately NOT touched. It has the
-- same shape, but mess entitlement is never intersected with physical rooms and
-- nothing sorts by array_position over mess_cats — only mess_cats[1] is read.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_hostel_effective_room_categories(
  p_institution uuid,
  p_program uuid,
  p_quota uuid,
  p_fee numeric,
  p_gender text DEFAULT NULL::text
)
RETURNS TABLE(category_id uuid)
LANGUAGE sql
STABLE
SET search_path TO 'public'
AS $function$
  WITH candidates AS (
    SELECT e.room_category_id AS cat,
           e.program_id, e.quota_ids, e.fee_min, e.fee_max,
           ( (e.program_id IS NOT NULL)::int * 4
           + (e.quota_ids  IS NOT NULL)::int * 2
           + ((e.fee_min IS NOT NULL OR e.fee_max IS NOT NULL))::int * 1 ) AS specificity
    FROM hostel_program_eligibility e
    WHERE e.institution_id = p_institution
      AND e.is_active
      AND e.room_category_id IS NOT NULL
      AND (p_gender IS NULL OR e.hostel_type = 'both' OR e.hostel_type = p_gender)
      AND (e.program_id = p_program OR e.program_id IS NULL)
      AND (e.quota_ids IS NULL OR p_quota = ANY(e.quota_ids))
      AND (e.fee_min IS NULL OR p_fee >= e.fee_min)
      AND (e.fee_max IS NULL OR p_fee <= e.fee_max)
  ),
  winner AS (
    SELECT program_id, quota_ids, fee_min, fee_max
    FROM candidates
    ORDER BY specificity DESC,
             (COALESCE(fee_max, 9.9e14::numeric) - COALESCE(fee_min, 0)) ASC
    LIMIT 1
  ),
  -- Unchanged resolution, lifted into its own CTE so the result can be ordered
  -- by the category it actually resolves to rather than the one it started as.
  effective AS (
    SELECT COALESCE(
             CASE WHEN p_gender IS NOT NULL AND oc.type IS NOT NULL AND oc.type <> p_gender
                  THEN (SELECT sib.id FROM hostel_categories sib
                         WHERE sib.name = oc.name AND sib.type = p_gender LIMIT 1)
                  ELSE NULL END,
             c.cat) AS cat_id
    FROM candidates c JOIN winner w
      ON c.program_id IS NOT DISTINCT FROM w.program_id
     AND c.quota_ids  IS NOT DISTINCT FROM w.quota_ids
     AND c.fee_min    IS NOT DISTINCT FROM w.fee_min
     AND c.fee_max    IS NOT DISTINCT FROM w.fee_max
    LEFT JOIN hostel_categories oc ON oc.id = c.cat
  ),
  ranked AS (
    SELECT DISTINCT e.cat_id, hc.sort_order, hc.name
    FROM effective e
    JOIN hostel_categories hc ON hc.id = e.cat_id
  )
  SELECT r.cat_id
  FROM ranked r
  ORDER BY r.sort_order NULLS LAST, r.name;
$function$;


-- ============================================================================
-- Campus Living — Auto-Allocate: ONE planner, two consumers. The preview now
-- rations beds instead of counting reachability (2026-08-11)
-- ============================================================================
--
-- ── THE BUG ─────────────────────────────────────────────────────────────────
-- Reported: the girls preview showed 32 eligible / 13 excluded, and Generate
-- produced a batch of TWO.
--
-- Measured, batch 06fb2396-0792-45ee-b370-46a10674ba5e: exactly 2 allocations,
-- both BSC (Nursing), both in Room 5 of Girls Hostel A. Room 5 held 2 free
-- beds. All 32 "eligible" learners were Nursing girls pointing at THOSE SAME
-- TWO BEDS.
--
-- CAUSE. fn_auto_allocate_candidates computed
--
--     (tgt.block_name IS NOT NULL) AS bed_available
--
-- from a LEFT JOIN LATERAL (... ORDER BY ... LIMIT 1) against the `free_beds`
-- CTE — a snapshot taken once for the whole query. It is a PER-LEARNER
-- existence test: "is there a free bed in a room this learner can reach". It
-- never marks a bed as consumed, so N learners sharing one cohort all report
-- true off the same single bed.
--
-- fn_auto_allocate_classic runs that identical query inside a FOR ... LOOP, and
-- each INSERT removes the bed from the pool through
-- NOT EXISTS (... status IN ('active','pending_approval')). It answers a
-- different question: "is one still left when this learner's turn comes".
--
-- So `verdict = 'in'` never meant "will be placed". It meant "is not blocked by
-- category, gender, fee band or room rules" — and the operator read the count
-- as a placement forecast, which is exactly how it reads on the page.
--
-- This is the SECOND time the gap has been diagnosed (20260810210000 recorded
-- "42 flipped to in against 3 reachable beds") and the first time it is fixed
-- rather than documented.
--
-- ── THE FIX: delete one of the two implementations ─────────────────────────
-- The preview did not merely *approximate* the allocator — it carried a
-- hand-copied replica of its ORDER BY, kept in step by a comment reading "Same
-- ORDER BY as fn_auto_allocate_classic, so this stays a real prediction". Every
-- regression in this engine's history is a copy that drifted from its original
-- (v_has_covering, the gender resolution sweep, the strict predicate).
--
-- fn_auto_allocate_plan now owns the decision ENTIRELY: it builds the candidate
-- set, resolves the reachable rooms for both tiers, walks candidates in the
-- allocator's order and hands each the best bed NOT ALREADY TAKEN BY AN EARLIER
-- CANDIDATE IN THE SAME RUN. It returns one row per candidate — plan_bed_id
-- NULL for anyone it could not place.
--
--     fn_auto_allocate_classic     loops the plan and writes it
--     fn_auto_allocate_candidates  joins the plan and displays it
--
-- Neither one decides anything any more, so `verdict = 'in'` is now literally
-- "the planner assigned this learner bed X", and the preview count equals the
-- batch size by construction rather than by vigilance.
--
-- Within-run consumption is tracked in a temp table (_aap_taken) rather than by
-- re-querying hostel_allocations, because the planner writes nothing.
--
-- ── SECOND FIX: learners with no block for their gender were INVISIBLE ──────
-- raw_cohort filtered on
--
--     lp.institution_id IN (SELECT bi.institution_id FROM hostel_block_institutions ...)
--
-- inside the WHERE clause, so a learner whose college is linked to no block of
-- that hostel type was dropped from the result entirely — counted as neither
-- eligible nor excluded, and invisible on the page. Found on ABINAYA
-- (8aa1e1e0-…), JKKN College of Arts and Science (Aided), the 44th unallocated
-- girl: the preview reported 43 candidates and she was not one of them.
--
-- The filter becomes a reported flag (block_access_ok) with its own exclusion
-- branch. `sigs` still excludes those learners, so the expensive per-signature
-- CROSS JOIN against fn_learner_strictly_eligible_for_room does not grow; the
-- join from base to sigs is now LEFT, which leaves s.rep NULL and correctly
-- yields physical_rule_ok = false for them.
--
-- ── VOLATILITY ─────────────────────────────────────────────────────────────
-- The planner creates temp tables, so it is VOLATILE, and a STABLE function may
-- not sensibly call it — fn_auto_allocate_candidates therefore becomes VOLATILE
-- too. PostgREST already reaches both through POST /rpc (supabase-js .rpc()),
-- so no client change is required. Neither signature changes, so both are plain
-- CREATE OR REPLACE and the EXECUTE grants survive.
--
-- fn_auto_allocate_plan is granted to NOBODY: both callers are SECURITY DEFINER
-- owned by postgres and reach it as the owner. It bypasses the authorization
-- check in fn_auto_allocate_classic, so EXECUTE is revoked from PUBLIC, anon
-- and authenticated explicitly.
--
-- ── NOT FIXED HERE, REPORTED ───────────────────────────────────────────────
-- fn_auto_allocate_candidates is SECURITY DEFINER, granted to `authenticated`,
-- and carries NO authorization check of its own (fn_auto_allocate_classic
-- does). Any logged-in user can therefore list every unallocated learner's
-- name, email, gender, fee band and bill state. Gating it is a one-line change
-- but 67 of 89 active roles already hold campus_living.allocations.view, so the
-- real remedy is de-granting that key — an RBAC job with its own blast radius,
-- deliberately not bundled into an allocation fix.
-- ============================================================================


-- ── 1. The planner — the single source of placement truth ──────────────────
-- Output columns are prefixed plan_ so that none of them can collide with a
-- column name inside the bodies below; an ambiguous bare reference in plpgsql
-- is a runtime error, not a compile-time one.
CREATE OR REPLACE FUNCTION public.fn_auto_allocate_plan(
  p_hostel_type text,
  p_strict boolean DEFAULT true,
  p_institution_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_allow_overflow boolean DEFAULT true
)
RETURNS TABLE(
  plan_seq integer,
  plan_lp_id uuid,
  plan_profile_id uuid,
  plan_institution_id uuid,
  plan_semester_id uuid,
  plan_academic_year_id uuid,
  plan_bed_id uuid,
  plan_room_id uuid,
  plan_block_id uuid,
  plan_block_name text,
  plan_room_category_id uuid,
  plan_mess_category_id uuid,
  plan_tier integer
)
LANGUAGE plpgsql
VOLATILE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  cand record;
  v_bed uuid; v_room uuid; v_block uuid; v_bname text; v_cat uuid;
  v_tier int; v_ay uuid; v_seq int := 0;
BEGIN
  IF p_hostel_type IS NULL OR p_hostel_type NOT IN ('boys','girls') THEN
    RAISE EXCEPTION 'Hostel type must be boys or girls';
  END IF;

  -- Both consumers may run in one transaction; ON COMMIT DROP alone would then
  -- collide on the second call.
  DROP TABLE IF EXISTS _aap_pool;
  DROP TABLE IF EXISTS _aap_cand;
  DROP TABLE IF EXISTS _aap_sig_rooms;
  DROP TABLE IF EXISTS _aap_overflow_rooms;
  DROP TABLE IF EXISTS _aap_taken;

  -- Stage 1: the cheap, index-friendly predicates only. Splitting this out of
  -- fn_auto_allocate_classic's single-WHERE candidate build is a pure
  -- performance change — one WHERE clause is order-independent, so the result
  -- set is identical — but it stops the four LATERALs in stage 2, two of which
  -- recompute a learner's academic fee from scratch, from being evaluated for
  -- every hostel learner of this gender instead of only the handful who still
  -- need a bed. Measured on the girls run: 1,894 ms -> 399 ms, same 43 rows and
  -- the same 43 beds. Generate carried this cost too and gets the same win.
  CREATE TEMP TABLE _aap_pool ON COMMIT DROP AS
    SELECT lp.id AS lp_id, p.id AS profile_id, lp.semester_id AS sem_id,
           lp.academic_year_id AS ay_id, lp.institution_id AS inst,
           lp.degree_id, lp.department_id, lp.program_id,
           lower(btrim(COALESCE(NULLIF(btrim(p.gender), ''), lp.gender))) AS gender,
           lower(coalesce(inst_t.name,'')) AS inst_name,
           lower(coalesce(lp.first_name,'')) AS fname,
           lower(coalesce(lp.last_name,''))  AS lname
    FROM learners_profiles lp
    JOIN profiles p ON p.learner_id = lp.id
    JOIN institutions inst_t ON inst_t.id = lp.institution_id
    WHERE lp.accommodation_type_id IN (SELECT id FROM accommodation_types WHERE code = 'hostel')
      AND lp.lifecycle_status = 'active'
      AND (COALESCE(NULLIF(btrim(p.gender), ''), NULLIF(btrim(lp.gender), '')) IS NULL
           OR (p_hostel_type = 'boys'
               AND lower(btrim(COALESCE(NULLIF(btrim(p.gender), ''), lp.gender))) IN ('male','m'))
           OR (p_hostel_type = 'girls'
               AND lower(btrim(COALESCE(NULLIF(btrim(p.gender), ''), lp.gender))) IN ('female','f')))
      AND NOT EXISTS (SELECT 1 FROM hostel_allocations a WHERE a.learner_id=p.id AND a.status IN ('active','pending_approval'))
      AND (p_institution_id IS NULL OR lp.institution_id = p_institution_id)
      AND (p_program_id     IS NULL OR lp.program_id     = p_program_id)
      AND (p_semester_id    IS NULL OR lp.semester_id    = p_semester_id);

  -- Stage 2: the expensive per-learner resolutions, over the narrow pool.
  CREATE TEMP TABLE _aap_cand ON COMMIT DROP AS
    SELECT c.lp_id, c.profile_id, c.sem_id, c.ay_id, c.inst,
           c.degree_id, c.department_id, c.program_id, c.gender,
           room_elig.cats AS room_cats, mess_elig.cats AS mess_cats,
           COALESCE(sem_fill.rank, 1) AS fill_rank,
           prim.is_primary,
           c.inst_name, c.fname, c.lname
    FROM _aap_pool c
    LEFT JOIN LATERAL (SELECT array_agg(category_id) AS cats FROM fn_hostel_learner_room_categories(c.lp_id)) room_elig ON true
    LEFT JOIN LATERAL (SELECT array_agg(category_id) AS cats FROM fn_hostel_learner_mess_categories(c.lp_id)) mess_elig ON true
    LEFT JOIN LATERAL (
      SELECT bool_or(hbi.is_primary) AS is_primary
      FROM hostel_block_institutions hbi
      JOIN hostel_blocks hb ON hb.id = hbi.block_id
      WHERE hb.hostel_type::text = p_hostel_type
        AND hbi.institution_id = c.inst
    ) prim ON true
    LEFT JOIN LATERAL (
      SELECT min(array_position(r.semester_ids, c.sem_id)) AS rank
      FROM hostel_room_eligibility_rules r
      JOIN hostel_blocks hb ON hb.id = r.block_id
      WHERE r.is_active
        AND hb.hostel_type::text = p_hostel_type
        AND r.institution_id = c.inst
        AND (r.degree_id     IS NULL OR r.degree_id     = c.degree_id)
        AND (r.department_id IS NULL OR r.department_id = c.department_id)
        AND (r.program_id    IS NULL OR r.program_id    = c.program_id)
        AND cardinality(r.semester_ids) > 1
        AND c.sem_id = ANY(r.semester_ids)
    ) sem_fill ON true
    WHERE room_elig.cats IS NOT NULL
      AND prim.is_primary IS NOT NULL;

  -- Tier 1: rooms the cohort's own physical rule covers. The predicate reads
  -- only the 5-tuple off the learner, so it is evaluated once per distinct
  -- signature rather than once per learner (see 20260810160000).
  CREATE TEMP TABLE _aap_sig_rooms ON COMMIT DROP AS
    SELECT s.inst, s.degree_id, s.department_id, s.program_id, s.sem_id,
           r.id AS room_id, r.category_id, r.block_id, r.floor, r.room_number,
           hb.name AS block_name, hc.type AS cat_type
    FROM (SELECT DISTINCT c.inst, c.degree_id, c.department_id, c.program_id, c.sem_id,
                 (array_agg(c.lp_id))[1] AS rep
          FROM _aap_cand c
          GROUP BY c.inst, c.degree_id, c.department_id, c.program_id, c.sem_id) s
    CROSS JOIN LATERAL (
      SELECT r.* FROM hostel_rooms r
      JOIN hostel_blocks hb2 ON hb2.id = r.block_id
      WHERE hb2.hostel_type::text = p_hostel_type AND r.room_purpose = 'student'
    ) r
    JOIN hostel_blocks hb ON hb.id = r.block_id
    LEFT JOIN hostel_categories hc ON hc.id = r.category_id
    WHERE fn_room_serves_institution(r.id, s.inst)
      AND fn_learner_strictly_eligible_for_room(s.rep, r.id, p_strict);

  CREATE INDEX ON _aap_sig_rooms (inst, degree_id, department_id, program_id, sem_id);

  -- Tier 2: rooms NO active rule covers. The CASE is a verbatim copy of
  -- v_has_covering in fn_learner_strictly_eligible_for_room and MUST stay
  -- identical — if they drift, overflow hands out a bed the predicate says
  -- belongs to another cohort.
  CREATE TEMP TABLE _aap_overflow_rooms ON COMMIT DROP AS
    SELECT i.inst, r.id AS room_id, r.category_id, r.block_id, r.floor, r.room_number,
           hb.name AS block_name, hc.type AS cat_type
    FROM (SELECT DISTINCT c.inst FROM _aap_cand c) i
    CROSS JOIN LATERAL (
      SELECT r.* FROM hostel_rooms r
      JOIN hostel_blocks hb2 ON hb2.id = r.block_id
      WHERE hb2.hostel_type::text = p_hostel_type AND r.room_purpose = 'student'
    ) r
    JOIN hostel_blocks hb ON hb.id = r.block_id
    LEFT JOIN hostel_categories hc ON hc.id = r.category_id
    WHERE p_allow_overflow
      AND fn_room_serves_institution(r.id, i.inst)
      AND NOT EXISTS (
        SELECT 1 FROM hostel_room_eligibility_rules re
        WHERE re.is_active AND re.block_id = r.block_id
          AND CASE
                WHEN EXISTS (SELECT 1 FROM hostel_room_eligibility_rule_rooms rr
                             WHERE rr.rule_id = re.id)
                  THEN EXISTS (SELECT 1 FROM hostel_room_eligibility_rule_rooms rr
                               WHERE rr.rule_id = re.id AND rr.room_id = r.id)
                ELSE (re.floor IS NULL OR re.floor = r.floor)
              END
      );

  CREATE INDEX ON _aap_overflow_rooms (inst);

  -- The whole point of this function: beds consumed EARLIER IN THIS RUN.
  CREATE TEMP TABLE _aap_taken (bed_id uuid PRIMARY KEY) ON COMMIT DROP;

  FOR cand IN
    SELECT c.* FROM _aap_cand c
    ORDER BY c.fill_rank, c.is_primary DESC, c.inst_name, c.fname, c.lname, c.lp_id
  LOOP
    v_seq := v_seq + 1;
    v_bed := NULL; v_room := NULL; v_block := NULL;
    v_bname := NULL; v_cat := NULL; v_tier := NULL;

    v_ay := COALESCE(cand.ay_id,
                     (SELECT id FROM academic_years
                       WHERE institution_id = cand.inst AND is_active
                       ORDER BY start_date DESC LIMIT 1));

    -- No academic year is a hard skip in the allocator; report it as unplaced
    -- rather than handing back a bed the writer would refuse.
    IF v_ay IS NOT NULL THEN
      SELECT b.id, x.room_id, x.block_id, x.block_name, x.category_id, x.tier
        INTO v_bed, v_room, v_block, v_bname, v_cat, v_tier
      FROM (
        SELECT sr.room_id, sr.category_id, sr.block_id, sr.block_name,
               sr.floor, sr.room_number, sr.cat_type, 1 AS tier
        FROM _aap_sig_rooms sr
        WHERE sr.inst           IS NOT DISTINCT FROM cand.inst
          AND sr.degree_id      IS NOT DISTINCT FROM cand.degree_id
          AND sr.department_id  IS NOT DISTINCT FROM cand.department_id
          AND sr.program_id     IS NOT DISTINCT FROM cand.program_id
          AND sr.sem_id         IS NOT DISTINCT FROM cand.sem_id
        UNION ALL
        SELECT o.room_id, o.category_id, o.block_id, o.block_name,
               o.floor, o.room_number, o.cat_type, 2
        FROM _aap_overflow_rooms o
        WHERE o.inst IS NOT DISTINCT FROM cand.inst
      ) x
      JOIN hostel_beds b ON b.room_id = x.room_id AND b.status = 'available'
      WHERE x.category_id = ANY(cand.room_cats)
        AND (x.cat_type IS NULL
             OR (x.cat_type='boys'  AND cand.gender IN ('male','m'))
             OR (x.cat_type='girls' AND cand.gender IN ('female','f')))
        AND NOT EXISTS (SELECT 1 FROM hostel_allocations a
                        WHERE a.bed_id = b.id AND a.status IN ('active','pending_approval'))
        AND NOT EXISTS (SELECT 1 FROM _aap_taken t WHERE t.bed_id = b.id)
      ORDER BY array_position(cand.room_cats, x.category_id), x.tier,
               x.block_name, x.floor, x.room_number, b.bed_number
      LIMIT 1;
    END IF;

    IF v_bed IS NOT NULL THEN
      INSERT INTO _aap_taken(bed_id) VALUES (v_bed);
    END IF;

    plan_seq              := v_seq;
    plan_lp_id            := cand.lp_id;
    plan_profile_id       := cand.profile_id;
    plan_institution_id   := cand.inst;
    plan_semester_id      := cand.sem_id;
    plan_academic_year_id := v_ay;
    plan_bed_id           := v_bed;
    plan_room_id          := v_room;
    plan_block_id         := v_block;
    plan_block_name       := v_bname;
    plan_room_category_id := v_cat;
    plan_mess_category_id := CASE WHEN cand.mess_cats IS NOT NULL THEN cand.mess_cats[1] END;
    plan_tier             := v_tier;
    RETURN NEXT;
  END LOOP;
END
$function$;

REVOKE ALL ON FUNCTION public.fn_auto_allocate_plan(text, boolean, uuid, uuid, uuid, boolean) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fn_auto_allocate_plan(text, boolean, uuid, uuid, uuid, boolean) FROM anon;
REVOKE ALL ON FUNCTION public.fn_auto_allocate_plan(text, boolean, uuid, uuid, uuid, boolean) FROM authenticated;


-- ── 2. The allocator now only WRITES the plan ──────────────────────────────
-- Authorization, the hostel-year guard and the tier-policy lookup are unchanged
-- and still run before anything is planned. Signature unchanged.
CREATE OR REPLACE FUNCTION public.fn_auto_allocate_classic(
  p_hostel_type text,
  p_hostel_year_id uuid DEFAULT NULL::uuid,
  p_strict boolean DEFAULT true,
  p_institution_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_allow_overflow boolean DEFAULT true
)
RETURNS uuid
LANGUAGE plpgsql
VOLATILE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_batch uuid; v_tier uuid; v_actor uuid := auth.uid();
  v_alloc int := 0; v_skip int := 0; v_overflow int := 0;
  v_year uuid; v_mess uuid; pl record;
BEGIN
  IF NOT (is_super_admin() OR is_admin() OR user_has_permission('campus_living.allocations.create')) THEN
    RAISE EXCEPTION 'Not authorized to run auto-allocation';
  END IF;

  IF p_hostel_type IS NULL OR p_hostel_type NOT IN ('boys','girls') THEN
    RAISE EXCEPTION 'Hostel type must be boys or girls';
  END IF;

  v_year := COALESCE(p_hostel_year_id, (SELECT id FROM hostel_years WHERE is_current LIMIT 1));
  IF v_year IS NULL THEN
    RAISE EXCEPTION 'No current hostel year is set — mark one under Campus Living → Settings → Hostel Years';
  END IF;

  SELECT id INTO v_tier FROM hostel_tier_policy WHERE tier_key='standard' AND institution_id IS NULL AND is_active LIMIT 1;
  IF v_tier IS NULL THEN SELECT id INTO v_tier FROM hostel_tier_policy WHERE tier_key='standard' AND is_active LIMIT 1; END IF;
  IF v_tier IS NULL THEN RAISE EXCEPTION 'No standard tier policy found'; END IF;

  INSERT INTO hostel_allocation_batches (block_id, category_id, hostel_year_id, status, created_by)
  VALUES (NULL, NULL, v_year, 'pending_approval', v_actor)
  RETURNING id INTO v_batch;

  FOR pl IN
    SELECT * FROM fn_auto_allocate_plan(
      p_hostel_type, p_strict, p_institution_id, p_program_id, p_semester_id, p_allow_overflow)
  LOOP
    IF pl.plan_bed_id IS NULL THEN v_skip := v_skip + 1; CONTINUE; END IF;
    IF pl.plan_tier = 2 THEN v_overflow := v_overflow + 1; END IF;

    INSERT INTO hostel_allocations (
      institution_id, learner_id, block_id, room_id, bed_id, academic_year_id, semester_id,
      allocation_type, allocation_date, status,
      emergency_contact_name, emergency_contact_phone, emergency_contact_relation,
      tier_id, batch_id, allocated_by, warden_id
    ) VALUES (
      pl.plan_institution_id, pl.plan_profile_id, pl.plan_block_id, pl.plan_room_id, pl.plan_bed_id,
      pl.plan_academic_year_id, pl.plan_semester_id,
      'fresh', CURRENT_DATE, 'pending_approval', '', '', '',
      v_tier, v_batch, v_actor,
      (SELECT user_id FROM user_block_access WHERE block_id = pl.plan_block_id AND revoked_at IS NULL LIMIT 1)
    );

    v_mess := pl.plan_mess_category_id;
    UPDATE learners_profiles
      SET hostel_category_id = pl.plan_room_category_id,
          mess_category_id   = COALESCE(v_mess, mess_category_id),
          updated_at = now()
      WHERE id = pl.plan_lp_id;

    v_alloc := v_alloc + 1;
  END LOOP;

  UPDATE hostel_allocation_batches
    SET allocated_count = v_alloc, skipped_count = v_skip,
        notes = format('%s allocated across all %s blocks (%s physical mode; rules-driven category + mess; block and room decided by the physical-room rules). %s of them overflowed into UNRESERVED rooms of their own category because every room reserved for their cohort was full (%s). %s skipped (no free bed they can occupy / reserved rooms hold no space for them / gender / no academic year). Strict: learners with no rule-resolved room category are excluded. Cohort: lifecycle_status = active only.',
                       v_alloc, p_hostel_type,
                       CASE WHEN p_strict THEN 'STRICT — only cohorts matching a physical rule' ELSE 'open — rule-free rooms shared' END,
                       v_overflow,
                       CASE WHEN p_allow_overflow THEN 'overflow ON; category never changed, no other cohort''s reserved room used' ELSE 'overflow OFF' END,
                       v_skip)
    WHERE id = v_batch;

  RETURN v_batch;
END
$function$;


-- ============================================================================
-- Campus Living — the preview now REPORTS the plan instead of predicting it
-- (2026-08-11). Companion to 20260811150200.
-- ============================================================================
--
-- Two changes, no signature change (plain CREATE OR REPLACE, grants survive):
--
-- 1. bed_available / target_block_name / placement_tier come from
--    fn_auto_allocate_plan, which walks candidates in the allocator's order and
--    consumes beds as it goes. The old LEFT JOIN LATERAL over the static
--    `free_beds` snapshot answered a per-learner reachability question and let
--    32 learners claim the same 2 beds — see the header of 20260811150200 for
--    the measured incident. `verdict = 'in'` now means "the planner assigned
--    this learner a bed", so the preview count IS the batch size.
--
--    The `tgt` LATERAL is deleted rather than fixed. It was a hand-copy of the
--    allocator's ORDER BY kept in step by a comment; deleting it removes the
--    drift surface entirely.
--
-- 2. A learner whose institution is linked to NO block of this hostel type is
--    no longer silently dropped. That filter lived in raw_cohort's WHERE
--    clause, so such a learner was counted as neither eligible nor excluded and
--    never appeared on the page at all. It is now the reported flag
--    block_access_ok with its own exclusion branch.
--
--    `sigs` keeps the filter, so the expensive per-signature CROSS JOIN against
--    fn_learner_strictly_eligible_for_room does not grow by a single row. The
--    base→sigs join becomes LEFT, leaving s.rep NULL for those learners, which
--    is exactly the value that makes physical_rule_ok resolve to false.
--
--    Found on ABINAYA (8aa1e1e0-…), JKKN College of Arts and Science (Aided) —
--    the 44th unallocated girl, while the preview reported 43 candidates. She
--    carries three independent blockers (no block link, no
--    hostel_program_eligibility row for her college, and no usable academic
--    bill so fn_learner_band_academic_fee returns NULL). The reason ladder
--    reports the FIRST one — the missing fee band — which is correct: fixing
--    the block link alone would not place her.
--
-- `free_beds` is retained: category_free_beds_anywhere still needs it to tell
-- "beds exist but are reserved for other cohorts" apart from real exhaustion.
-- `overflow_rooms` is retained: overflow_room_ok still reports tier-2
-- reachability independently of whether a bed was actually won.
--
-- VOLATILE, not STABLE: the planner creates temp tables. PostgREST already
-- POSTs to this RPC via supabase-js .rpc(), so no client change is needed.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_auto_allocate_candidates(
  p_hostel_type text,
  p_strict boolean DEFAULT true,
  p_institution_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_allow_overflow boolean DEFAULT true
)
RETURNS TABLE(
  learner_id uuid, full_name text, email text, institution_name text,
  program_name text, semester_name text, gender text,
  has_profile boolean, gender_ok boolean, not_allocated boolean,
  physical_rule_ok boolean, overflow_room_ok boolean, placement_tier text,
  bed_available boolean, target_block_name text,
  academic_year_id uuid, academic_year_name text,
  admission_academic_year_id uuid, admission_academic_year_name text,
  band_academic_year_id uuid, band_academic_year_name text, band_fee numeric,
  academic_bill_count integer, current_year_bill_count integer,
  bill_other_year_name text, current_year_fee numeric,
  resolved_room_category_id uuid, resolved_room_category_name text,
  resolved_mess_category_id uuid, resolved_mess_category_name text,
  bill_state text, stage text, verdict text, exclusion_reason text
)
LANGUAGE sql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  WITH blocks AS MATERIALIZED (
    SELECT id, name FROM hostel_blocks WHERE hostel_type::text = p_hostel_type
  ),
  scope_rooms AS MATERIALIZED (
    SELECT r.id, r.block_id, b.name AS block_name, r.floor, r.room_number,
           r.category_id, hc.type AS cat_type
    FROM hostel_rooms r
    JOIN blocks b ON b.id = r.block_id
    LEFT JOIN hostel_categories hc ON hc.id = r.category_id
    WHERE r.room_purpose = 'student'
  ),
  -- The institution/block filter that used to live here is now the reported
  -- flag block_access_ok in `base`. Dropping a learner from the result set is
  -- never an acceptable way to say "this learner cannot be placed".
  raw_cohort AS MATERIALIZED (
    SELECT lp.id, lp.institution_id, lp.degree_id, lp.department_id,
           lp.program_id, lp.semester_id, lp.academic_year_id, lp.quota_id,
           lp.first_name, lp.last_name,
           CASE WHEN lower(lp.gender) LIKE 'm%' THEN 'boys'
                WHEN lower(lp.gender) LIKE 'f%' THEN 'girls' END AS lp_gender_type,
           lower(btrim(COALESCE(NULLIF(btrim(gp.gender), ''), lp.gender))) AS eff_gender
    FROM learners_profiles lp
    LEFT JOIN profiles gp ON gp.learner_id = lp.id
    WHERE lp.accommodation_type_id IN (SELECT id FROM accommodation_types WHERE code = 'hostel')
      AND lp.lifecycle_status = 'active'
      AND (p_institution_id IS NULL OR lp.institution_id = p_institution_id)
      AND (p_program_id     IS NULL OR lp.program_id     = p_program_id)
      AND (p_semester_id    IS NULL OR lp.semester_id    = p_semester_id)
      AND (COALESCE(NULLIF(btrim(gp.gender), ''), NULLIF(btrim(lp.gender), '')) IS NULL
           OR (p_hostel_type = 'boys'
               AND lower(btrim(COALESCE(NULLIF(btrim(gp.gender), ''), lp.gender))) IN ('male','m'))
           OR (p_hostel_type = 'girls'
               AND lower(btrim(COALESCE(NULLIF(btrim(gp.gender), ''), lp.gender))) IN ('female','f')))
      AND NOT EXISTS (
        SELECT 1 FROM hostel_allocations ha2
        JOIN profiles pr2 ON pr2.learner_id = lp.id
        WHERE ha2.learner_id = pr2.id
          AND ha2.status IN ('active', 'pending_approval')
      )
  ),
  -- The placement decision itself. One row per candidate the planner saw;
  -- plan_bed_id IS NULL means it could not seat them.
  placement AS MATERIALIZED (
    SELECT pl.plan_lp_id, pl.plan_bed_id, pl.plan_block_name, pl.plan_tier
    FROM fn_auto_allocate_plan(
           p_hostel_type, p_strict, p_institution_id,
           p_program_id, p_semester_id, p_allow_overflow) pl
  ),
  unruled_rooms AS MATERIALIZED (
    SELECT sr.id AS room_id, sr.category_id, sr.cat_type,
           sr.block_name, sr.floor, sr.room_number
    FROM scope_rooms sr
    WHERE NOT EXISTS (
      SELECT 1 FROM hostel_room_eligibility_rules re
      WHERE re.is_active AND re.block_id = sr.block_id
        AND CASE
              WHEN EXISTS (SELECT 1 FROM hostel_room_eligibility_rule_rooms rr
                           WHERE rr.rule_id = re.id)
                THEN EXISTS (SELECT 1 FROM hostel_room_eligibility_rule_rooms rr
                             WHERE rr.rule_id = re.id AND rr.room_id = sr.id)
              ELSE (re.floor IS NULL OR re.floor = sr.floor)
            END
    )
  ),
  overflow_rooms AS MATERIALIZED (
    SELECT i.institution_id, ur.room_id, ur.category_id, ur.cat_type,
           ur.block_name, ur.floor, ur.room_number
    FROM (SELECT DISTINCT institution_id FROM raw_cohort) i
    CROSS JOIN unruled_rooms ur
    WHERE p_allow_overflow
      AND fn_room_serves_institution(ur.room_id, i.institution_id)
  ),
  -- Still gated on block access: a learner whose college uses no block of this
  -- type can reach no room, so adding her signature would only cost two
  -- plpgsql predicate calls per room to prove it.
  sigs AS MATERIALIZED (
    SELECT rc.institution_id, rc.degree_id, rc.department_id, rc.program_id,
           rc.semester_id, (array_agg(rc.id))[1] AS rep
    FROM raw_cohort rc
    WHERE EXISTS (SELECT 1 FROM hostel_block_institutions bi
                  WHERE bi.institution_id = rc.institution_id
                    AND bi.block_id IN (SELECT id FROM blocks))
    GROUP BY 1,2,3,4,5
  ),
  sig_rooms AS MATERIALIZED (
    SELECT s.rep, sr.id AS room_id, sr.category_id, sr.cat_type,
           sr.block_name, sr.floor, sr.room_number
    FROM sigs s
    CROSS JOIN scope_rooms sr
    WHERE fn_room_serves_institution(sr.id, s.institution_id)
      AND fn_learner_strictly_eligible_for_room(s.rep, sr.id, p_strict)
  ),
  free_beds AS MATERIALIZED (
    SELECT bd.id, bd.room_id, bd.bed_number
    FROM hostel_beds bd
    JOIN scope_rooms sr ON sr.id = bd.room_id
    WHERE bd.status = 'available'
      AND NOT EXISTS (SELECT 1 FROM hostel_allocations a
                      WHERE a.bed_id = bd.id AND a.status IN ('active','pending_approval'))
  ),
  fee AS MATERIALIZED (
    SELECT c.id, adm.ay_id AS adm_ay,
           bf.academic_year_id AS band_ay, bf.academic_year_name AS band_ay_name, bf.fee
    FROM raw_cohort c
    LEFT JOIN LATERAL (SELECT fn_learner_admission_academic_year(c.id) AS ay_id) adm ON true
    LEFT JOIN LATERAL fn_learner_band_academic_fee(c.id) bf ON true
  ),
  cats AS MATERIALIZED (
    SELECT c.id,
      CASE WHEN c.institution_id IS NOT NULL AND c.program_id IS NOT NULL AND f.fee IS NOT NULL
           THEN (SELECT array_agg(category_id) FROM fn_hostel_effective_room_categories(
                   c.institution_id, c.program_id, c.quota_id, f.fee, c.lp_gender_type)) END AS room_cats,
      CASE WHEN c.institution_id IS NOT NULL AND c.program_id IS NOT NULL AND f.fee IS NOT NULL
           THEN (SELECT array_agg(category_id) FROM fn_hostel_effective_mess_categories(
                   c.institution_id, c.program_id, c.quota_id, f.fee, c.lp_gender_type)) END AS mess_cats
    FROM raw_cohort c JOIN fee f ON f.id = c.id
  ),
  base AS (
    SELECT
      c.id AS learner_id,
      COALESCE(p.full_name,
               NULLIF(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''),
               p.email, '—') AS full_name,
      p.email, inst.name AS institution_name, prog.program_name, sem.semester_name,
      c.eff_gender AS gender,
      (p.id IS NOT NULL) AS has_profile,
      c.academic_year_id, ay.academic_year_name,
      ct.room_cats, ct.mess_cats,
      f.adm_ay AS admission_academic_year_id,
      aay.academic_year_name::text AS admission_academic_year_name,
      f.band_ay AS band_academic_year_id,
      f.band_ay_name AS band_academic_year_name,
      f.fee AS band_fee,
      ct.room_cats[1] AS resolved_room_category_id,
      rc.name AS resolved_room_category_name, rc.type AS resolved_room_category_type,
      ct.mess_cats[1] AS resolved_mess_category_id, mc.name AS resolved_mess_category_name,
      (SELECT count(*)::int FROM billing_student_bills b
         WHERE b.student_id = c.id AND b.fee_source = 'academic'
           AND b.status NOT IN ('cancelled','superseded')) AS academic_bill_count,
      (SELECT count(*)::int FROM billing_student_bills b
         WHERE b.student_id = c.id AND b.fee_source = 'academic'
           AND b.status NOT IN ('cancelled','superseded')
           AND b.academic_year_id = c.academic_year_id) AS current_year_bill_count,
      (SELECT ay2.academic_year_name
         FROM billing_student_bills b JOIN academic_years ay2 ON ay2.id = b.academic_year_id
        WHERE b.student_id = c.id AND b.fee_source = 'academic'
          AND b.status NOT IN ('cancelled','superseded')
          AND b.academic_year_id IS NOT NULL
          AND b.academic_year_id IS DISTINCT FROM c.academic_year_id
        ORDER BY b.created_at DESC LIMIT 1) AS bill_other_year_name,
      fn_learner_current_year_academic_fee(c.id) AS current_year_fee,
      true AS not_allocated,
      -- Does this learner's college use ANY block of this hostel type? Was a
      -- silent WHERE-clause filter; now reported so she can be seen and fixed.
      EXISTS (SELECT 1 FROM hostel_block_institutions bi
              WHERE bi.institution_id = c.institution_id
                AND bi.block_id IN (SELECT id FROM blocks)) AS block_access_ok,
      EXISTS (
        SELECT 1 FROM sig_rooms sr
        WHERE sr.rep = s.rep
          AND sr.category_id = ANY(ct.room_cats)
          AND (sr.cat_type IS NULL
               OR (sr.cat_type = 'boys'  AND c.eff_gender IN ('male','m'))
               OR (sr.cat_type = 'girls' AND c.eff_gender IN ('female','f')))
      ) AS physical_rule_ok,
      EXISTS (
        SELECT 1 FROM sig_rooms sr
        WHERE sr.rep = s.rep
          AND NOT (sr.category_id = ANY(ct.room_cats))
      ) AS physical_ok_other_category,
      (SELECT count(*)::int
         FROM free_beds bd2
         JOIN scope_rooms sr2 ON sr2.id = bd2.room_id
        WHERE sr2.category_id = ANY(ct.room_cats)
          AND (sr2.cat_type IS NULL
               OR (sr2.cat_type = 'boys'  AND c.eff_gender IN ('male','m'))
               OR (sr2.cat_type = 'girls' AND c.eff_gender IN ('female','f')))
      ) AS category_free_beds_anywhere,
      EXISTS (
        SELECT 1 FROM overflow_rooms orm
        WHERE orm.institution_id = c.institution_id
          AND orm.category_id = ANY(ct.room_cats)
          AND (orm.cat_type IS NULL
               OR (orm.cat_type = 'boys'  AND c.eff_gender IN ('male','m'))
               OR (orm.cat_type = 'girls' AND c.eff_gender IN ('female','f')))
      ) AS overflow_room_ok,
      -- THE placement answer, taken from the planner that Generate also runs.
      (pl.plan_bed_id IS NOT NULL) AS bed_available,
      pl.plan_block_name AS target_block_name,
      CASE pl.plan_tier WHEN 1 THEN 'rule' WHEN 2 THEN 'overflow' END AS placement_tier
    FROM raw_cohort c
    JOIN cats ct ON ct.id = c.id
    JOIN fee  f  ON f.id  = c.id
    LEFT JOIN sigs s ON s.institution_id IS NOT DISTINCT FROM c.institution_id
                    AND s.degree_id      IS NOT DISTINCT FROM c.degree_id
                    AND s.department_id  IS NOT DISTINCT FROM c.department_id
                    AND s.program_id     IS NOT DISTINCT FROM c.program_id
                    AND s.semester_id    IS NOT DISTINCT FROM c.semester_id
    LEFT JOIN placement pl      ON pl.plan_lp_id = c.id
    LEFT JOIN profiles p        ON p.learner_id = c.id
    LEFT JOIN institutions inst ON inst.id = c.institution_id
    LEFT JOIN programs prog     ON prog.id = c.program_id
    LEFT JOIN semesters sem     ON sem.id = c.semester_id
    LEFT JOIN academic_years ay ON ay.id = c.academic_year_id
    LEFT JOIN academic_years aay ON aay.id = f.adm_ay
    LEFT JOIN hostel_categories rc ON rc.id = ct.room_cats[1]
    LEFT JOIN mess_categories   mc ON mc.id = ct.mess_cats[1]
  ),
  scored AS (
    SELECT b.*,
      (b.gender IS NOT NULL
        AND (b.resolved_room_category_type IS NULL
          OR (b.resolved_room_category_type = 'boys'  AND b.gender IN ('male','m'))
          OR (b.resolved_room_category_type = 'girls' AND b.gender IN ('female','f')))) AS gender_ok
    FROM base b
  )
  SELECT
    s.learner_id, s.full_name, s.email, s.institution_name, s.program_name, s.semester_name,
    s.gender, s.has_profile, s.gender_ok, s.not_allocated, s.physical_rule_ok,
    s.overflow_room_ok, s.placement_tier,
    s.bed_available, s.target_block_name,
    s.academic_year_id, s.academic_year_name,
    s.admission_academic_year_id, s.admission_academic_year_name,
    s.band_academic_year_id, s.band_academic_year_name, s.band_fee,
    s.academic_bill_count, s.current_year_bill_count, s.bill_other_year_name, s.current_year_fee,
    s.resolved_room_category_id, s.resolved_room_category_name,
    s.resolved_mess_category_id, s.resolved_mess_category_name,
    CASE
      WHEN s.band_fee IS NOT NULL
       AND s.band_academic_year_id IS NOT DISTINCT FROM s.admission_academic_year_id THEN 'matched'
      WHEN s.band_fee IS NOT NULL          THEN 'different_year'
      WHEN s.academic_bill_count > 0       THEN 'untagged'
      ELSE 'none'
    END AS bill_state,
    CASE
      WHEN s.band_fee  IS NULL THEN 'prerequisite'
      WHEN s.room_cats IS NULL THEN 'prerequisite'
      WHEN NOT s.has_profile OR NOT s.gender_ok OR NOT s.block_access_ok
        OR NOT (s.physical_rule_ok OR s.overflow_room_ok) OR NOT s.bed_available
                               THEN 'eligibility'
      ELSE 'ok'
    END AS stage,
    CASE
      WHEN s.band_fee  IS NULL THEN 'out'
      WHEN s.room_cats IS NULL THEN 'out'
      WHEN NOT s.has_profile OR NOT s.gender_ok OR NOT s.block_access_ok
        OR NOT (s.physical_rule_ok OR s.overflow_room_ok) OR NOT s.bed_available
                               THEN 'out'
      ELSE 'in'
    END AS verdict,
    CASE
      WHEN s.band_fee IS NULL THEN
        CASE
          WHEN s.academic_bill_count = 0 THEN
            'No academic bill for this student — nothing to read a fee band from'
          ELSE
            'Academic bills exist but none is usable: either untagged to an academic year, or the tagged year totals ₹0'
        END
      WHEN s.room_cats IS NULL THEN
        'No Category-Eligibility band covers ₹'
        || to_char(s.band_fee, 'FM999,999,999')
        || ' (read from ' || COALESCE(s.band_academic_year_name, 'their admission year') || ')'
        || ' for this program / quota — add or widen a band'
      WHEN NOT s.has_profile   THEN 'No login profile'
      WHEN s.gender IS NULL    THEN
        'Gender is not set on this learner — set it on the learner profile, then re-run the preview'
      WHEN NOT s.gender_ok     THEN 'Gender does not match the resolved room category'
      -- Ahead of the room-rule branches: without a block for their college no
      -- rule could ever reach them, so "add a room rule" would be wrong advice.
      WHEN NOT s.block_access_ok THEN
        COALESCE(s.institution_name, 'This learner''s institution')
        || ' is not linked to any ' || p_hostel_type || ' block — link it under'
        || ' Campus Living → Blocks → Institutions before this learner can be placed'
      WHEN NOT (s.physical_rule_ok OR s.overflow_room_ok) AND s.physical_ok_other_category THEN
        'Rooms they may occupy are a different room category than their eligible '
        || COALESCE(s.resolved_room_category_name, 'category')
        || ' — fix the reservation rooms or the Category-Eligibility band'
      WHEN NOT (s.physical_rule_ok OR s.overflow_room_ok) THEN
        CASE WHEN p_strict
          THEN 'No physical-room rule reserves a room for this cohort in any ' || p_hostel_type || ' block (strict mode)'
          ELSE 'No room they can occupy in their category — every room is reserved for other cohorts'
        END
      -- Reachable, but the planner ran out of beds before reaching them. This
      -- branch used to be unreachable-by-contention: bed_available was a
      -- per-learner test, so a cohort of 32 competing for 2 beds all reported
      -- true and 30 of them were skipped by Generate with no explanation here.
      WHEN NOT s.bed_available THEN
        CASE
          WHEN s.category_free_beds_anywhere > 0 THEN
            COALESCE(s.resolved_room_category_name, 'Their category')
            || ': ' || s.category_free_beds_anywhere::text
            || ' free bed' || CASE WHEN s.category_free_beds_anywhere = 1 THEN '' ELSE 's' END
            || ' exist in the ' || p_hostel_type || ' blocks, but none is left for this learner'
            || ' — every one is either reserved for another cohort or already taken by an'
            || ' earlier learner in this same run'
            || CASE WHEN p_allow_overflow
                 THEN '. Add this cohort to a physical-room rule that covers free rooms,'
                      || ' or free more beds in the rooms they already reach'
                 ELSE ' (overflow is off, so unreserved rooms were not considered)'
               END
          ELSE
            COALESCE(s.resolved_room_category_name, 'Their category')
            || ' is exhausted in every ' || p_hostel_type
            || ' block — no free bed in any '
            || COALESCE(s.resolved_room_category_name, 'eligible')
            || ' room, reserved or unreserved'
        END
      ELSE NULL
    END AS exclusion_reason
  FROM scored s
  ORDER BY s.full_name;
$function$;

-- ============================================================================
-- Learner lifecycle auto-promotion: repair the trigger plumbing
-- ============================================================================
-- BUG (reported 2026-08-11): the accounts team records payments, but learners
-- stay in 'reserved'. Measured on the live database: 870 learners in 'reserved',
-- of whom 82 already clear the 30% `admitted` threshold, plus 16 in 'account'
-- that already satisfy the Stage A gate. 98 learners stranded.
--
-- The thresholds themselves are fine — admission_statuses carries admitted=30%
-- and reserved.auto_promote_when_universal_paid=true, and the history table
-- records 1,008 auto_universal_paid and 120 auto_threshold promotions, the most
-- recent today. evaluate_learner_status_after_payment works. What is broken is
-- WHEN it gets called and WHAT IT CAN SEE when it is.
--
-- ── RC1: partial payments never re-evaluate (73 of the 82) ──────────────────
-- fn_evaluate_status_after_bill_paid guarded on
--     IF NEW.status = 'paid' AND COALESCE(OLD.status,'') <> 'paid'
-- An instalment leaves the bill 'partially_paid', so the guard rejects it.
-- Tuition is paid in instalments, so the threshold crossing almost always
-- happens on exactly the event the system ignored. Example AUG26CA114: 87.47%
-- paid (tuition ₹34,000 with ₹1,800 outstanding) and still 'reserved'.
--
-- ── RC2: the receipt-item trigger read pre-payment state (structural) ───────
-- Postgres fires row triggers in ALPHABETICAL ORDER BY TRIGGER NAME. On
-- billing_receipt_items AFTER INSERT that was:
--     trg_cl_upgrade_holds_after_payment
--     trg_evaluate_status_after_payment      <- evaluated the learner
--     trigger_update_bill_status_on_payment  <- only NOW wrote the bill
-- 'trg_' sorts before 'trigger_' ('g' < 'i'), so the evaluation ran BEFORE
-- update_bill_status() wrote the new balance onto the bill. And
-- evaluate_learner_status_after_payment reads the BILL (final_amount -
-- balance_amount, via vw_learner_payment_progress), not the receipt. That call
-- could never see the payment that triggered it — a no-op by construction.
--
-- Net effect of RC1+RC2: the only evaluation that could see fresh data was the
-- bill-side one, and its guard rejected every payment that was not a full
-- settlement. Both failed silently and in the safe direction (stale data can
-- only UNDER-report progress), so nothing ever errored and no history row was
-- written. From the accounts desk everything looked like it worked.
--
-- ── RC3: a BEFORE-trigger function registered as AFTER (latent) ────────────
-- update_bill_balance_on_amount_change() assigns NEW.status / NEW.balance_amount
-- / NEW.payment_date and returns NEW — textbook BEFORE-trigger code — but was
-- registered AFTER UPDATE, where the return value and every NEW mutation are
-- discarded. Editing a bill's final_amount (discount, waiver, correction) did
-- not recompute its balance or status.
--
-- Measured live damage: ZERO. Every live bill's balance_amount already equals
-- final_amount - receipts, except 4 OVERPAID bills (₹355,000 received against
-- ₹350,000 billed twice; ₹24,000 against ₹12,000; and one bill reduced to ₹0
-- after ₹160,000 was received). Those four read status='paid', balance=0, which
-- is the CORRECT presentation — update_bill_status() clamps to zero in its
-- `v_total_paid >= v_bill_amount` branch, and writing the arithmetic balance
-- (-5,000) would push paid_pct above 100%. So there is nothing to repair here;
-- the overpayments are a refund/credit matter, tracked separately. This trigger
-- is corrected as a latent fix so the next amount edit behaves.
--
-- ── RC4: zero-amount bills could never satisfy the Stage A gate (latent) ────
-- The gate counted a bill as satisfied on `status='paid' OR (final-balance)>0`.
-- A ₹0 bill left 'unpaid' satisfies neither and blocks Stage A forever. 60 such
-- live bills exist across 37 learners; none currently sit on an application_fee
-- / university_fee category for an account/reserved learner, so nothing is
-- blocked today — but ₹0 bills have stranded people here before (the 2026-07-25
-- bulk run), so the gate is hardened rather than left to luck.
--
-- paid_pct is NOT redefined. It stays "percent of the learner's entire non-
-- application-fee bill book", confirmed as intended 2026-08-11. The 788
-- 'reserved' learners under 30% are correctly waiting, not stuck.
-- ============================================================================

-- ── RC1 + RC2: one evaluation point, on the bill, that sees fresh data ──────
-- The bill is where the truth lives: update_bill_status() writes both status and
-- balance_amount on EVERY receipt-item insert, so an AFTER UPDATE trigger on
-- those two columns fires for every payment — full or partial — and reads a row
-- that already reflects the payment.
CREATE OR REPLACE FUNCTION public.fn_evaluate_status_after_bill_paid()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  -- Any movement in the bill's PAID POSITION, not just a full settlement.
  -- Was `NEW.status = 'paid' AND OLD.status <> 'paid'`, which ignored every
  -- instalment — the payments that actually carry a learner across 30%.
  IF NEW.balance_amount IS DISTINCT FROM OLD.balance_amount
     OR NEW.status IS DISTINCT FROM OLD.status THEN
    BEGIN
      PERFORM public.evaluate_learner_status_after_payment(NEW.student_id);
    EXCEPTION WHEN OTHERS THEN
      -- Swallowing is deliberate: a status-evaluation failure must never roll
      -- back a payment. WARNING rather than NOTICE so it actually reaches the
      -- Postgres log and is visible to get_logs — a silent third failure mode
      -- is what let RC1/RC2 hide for months.
      RAISE WARNING 'evaluate_learner_status_after_payment failed for learner %: %',
        NEW.student_id, SQLERRM;
    END;
  END IF;
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS trg_evaluate_status_after_bill_paid
  ON public.billing_student_bills;

CREATE TRIGGER trg_evaluate_status_after_bill_paid
  AFTER UPDATE OF status, balance_amount ON public.billing_student_bills
  FOR EACH ROW EXECUTE FUNCTION public.fn_evaluate_status_after_bill_paid();

-- RC2: remove the structurally-stale receipt-side evaluation. It is not merely
-- redundant now — it never worked, because it always ran one trigger too early
-- to see its own payment. The bill-side trigger above covers every receipt.
DROP TRIGGER IF EXISTS trg_evaluate_status_after_payment
  ON public.billing_receipt_items;
DROP FUNCTION IF EXISTS public._on_receipt_item_evaluate_status();

-- ── RC3: BEFORE, so the NEW mutations survive ──────────────────────────────
DROP TRIGGER IF EXISTS trigger_update_bill_balance_on_amount_change
  ON public.billing_student_bills;

CREATE TRIGGER trigger_update_bill_balance_on_amount_change
  BEFORE UPDATE ON public.billing_student_bills
  FOR EACH ROW EXECUTE FUNCTION public.update_bill_balance_on_amount_change();

-- No data repair accompanies RC3 — see the header. Every live bill's balance is
-- already correct; the only divergences are clamped overpayments, which must
-- stay clamped.

-- ── RC4: a fully-waived (₹0, nothing outstanding) gate bill counts as met ───
-- Only the Stage A gate expression changes; every other line is the 2026-05-17
-- function verbatim. CREATE OR REPLACE keeps the signature, so grants survive.
CREATE OR REPLACE FUNCTION public.evaluate_learner_status_after_payment(p_learner_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_current_status        lifecycle_status;
  v_paid_pct              numeric;
  v_app_paid              boolean;
  v_universals_paid       boolean;
  v_gate_bills            integer := 0;
  v_gate_paid             integer := 0;
  v_threshold             numeric;
  v_target_code           text;
  v_updated               integer := 0;
  v_universal_target      text;
  v_promoted_to_universal boolean := false;
  v_promoted_to_threshold boolean := false;
BEGIN
  SELECT lp.lifecycle_status INTO v_current_status
  FROM public.learners_profiles lp WHERE lp.id = p_learner_id;

  IF v_current_status IS NULL THEN
    RETURN jsonb_build_object('learner_id', p_learner_id, 'updated', false, 'reason', 'not_found');
  END IF;

  -- Promotion only. This function never demotes, so it is safe to call on any
  -- learner at any time — which is what makes the nightly sweep and the manual
  -- re-evaluate action safe.
  IF v_current_status::text NOT IN ('account', 'reserved') THEN
    RETURN jsonb_build_object('learner_id', p_learner_id, 'updated', false,
      'reason', 'no_op_for_status', 'current_status', v_current_status::text);
  END IF;

  SELECT v.paid_pct INTO v_paid_pct
  FROM public.vw_learner_payment_progress v
  WHERE v.learner_id = p_learner_id;
  v_paid_pct := COALESCE(v_paid_pct, 0);

  -- Stage A gate (-> reserved): every EXISTING application_fee + university_fee
  -- bill must have AT LEAST A PARTIAL PAYMENT (paid_amount > 0, or fully paid /
  -- waived-to-zero), with at least one such bill present.
  SELECT
    count(*) FILTER (WHERE bc.kind IN ('application_fee','university_fee')),
    count(*) FILTER (WHERE bc.kind IN ('application_fee','university_fee')
        AND (b.status::text = 'paid'
             OR (b.final_amount - COALESCE(b.balance_amount, b.final_amount)) > 0
             -- A ₹0 bill with nothing outstanding is settled by definition.
             -- Without this it satisfies neither branch above and blocks the
             -- gate forever, however much the learner pays elsewhere.
             OR (b.final_amount = 0 AND COALESCE(b.balance_amount, 0) = 0))),
    COALESCE(bool_or(bc.kind = 'application_fee' AND b.status::text = 'paid'), false),
    COALESCE(bool_and(b.status::text = 'paid') FILTER (WHERE bc.kind = 'university_fee'), false)
  INTO v_gate_bills, v_gate_paid, v_app_paid, v_universals_paid
  FROM public.billing_student_bills b
  JOIN public.billing_categories bc ON bc.id = b.item_category_id
  WHERE b.student_id = p_learner_id
    AND b.status::text <> 'superseded';

  IF v_current_status::text = 'account' AND v_gate_bills > 0 AND v_gate_paid = v_gate_bills THEN
    SELECT s.code INTO v_universal_target
    FROM public.admission_statuses s
    WHERE s.scope = 'learner'
      AND s.is_active = true
      AND s.auto_promote_when_universal_paid = true
    LIMIT 1;

    IF v_universal_target IS NOT NULL THEN
      UPDATE public.learners_profiles
         SET lifecycle_status = v_universal_target::lifecycle_status
       WHERE id = p_learner_id
         AND lifecycle_status::text = 'account';

      GET DIAGNOSTICS v_updated = ROW_COUNT;

      IF v_updated > 0 THEN
        INSERT INTO public.learners_profile_status_history
          (learner_id, from_status, to_status, reason_code, paid_pct_at_change,
           threshold_at_change, changed_by, metadata)
        VALUES
          (p_learner_id, 'account'::lifecycle_status, v_universal_target::lifecycle_status,
           'auto_universal_paid', v_paid_pct, NULL, NULL,
           jsonb_build_object('rpc', 'evaluate_learner_status_after_payment',
                              'application_fee_paid', v_app_paid,
                              'university_fee_paid', v_universals_paid,
                              'gate_bills', v_gate_bills,
                              'gate_paid', v_gate_paid,
                              'gate_rule', 'partial'));
        v_current_status := v_universal_target::lifecycle_status;
        v_promoted_to_universal := true;
      END IF;
    END IF;
  END IF;

  -- Stage B (-> admitted). gates_login = false deliberately excludes 'active'
  -- (60%): granting a login is never automatic. auto_promote_when_universal_paid
  -- = false excludes 'reserved', which Stage A owns.
  IF v_current_status::text IN ('account', 'reserved') THEN
    SELECT s.code, s.fee_paid_threshold_percent
      INTO v_target_code, v_threshold
    FROM public.admission_statuses s
    WHERE s.scope = 'learner'
      AND s.is_active = true
      AND s.fee_paid_threshold_percent IS NOT NULL
      AND s.gates_login = false
      AND s.auto_promote_when_universal_paid = false
      AND v_paid_pct >= s.fee_paid_threshold_percent
    ORDER BY s.fee_paid_threshold_percent DESC
    LIMIT 1;

    IF v_target_code IS NOT NULL THEN
      UPDATE public.learners_profiles
         SET lifecycle_status = v_target_code::lifecycle_status
       WHERE id = p_learner_id
         AND lifecycle_status::text IN ('account', 'reserved');

      GET DIAGNOSTICS v_updated = ROW_COUNT;

      IF v_updated > 0 THEN
        INSERT INTO public.learners_profile_status_history
          (learner_id, from_status, to_status, reason_code, paid_pct_at_change,
           threshold_at_change, changed_by, metadata)
        VALUES
          (p_learner_id, v_current_status, v_target_code::lifecycle_status,
           'auto_threshold', v_paid_pct, v_threshold, NULL,
           jsonb_build_object('rpc', 'evaluate_learner_status_after_payment',
                              'cascaded_from_universal', v_promoted_to_universal));
        v_promoted_to_threshold := true;
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'learner_id', p_learner_id,
    'updated', (v_promoted_to_universal OR v_promoted_to_threshold),
    'promoted_to_universal', v_promoted_to_universal,
    'promoted_to_threshold', v_promoted_to_threshold,
    'final_status', v_current_status::text,
    'paid_pct', v_paid_pct,
    'application_fee_paid', v_app_paid,
    'university_fee_paid', v_universals_paid,
    'gate_bills', v_gate_bills,
    'gate_paid', v_gate_paid,
    'threshold', v_threshold
  );
END;
$function$;

-- ============================================================================
-- profiles.is_active must mirror the app's login allow-list, not a subset of it
-- ============================================================================
-- BLOCKER found while fixing the billing auto-promotion pipeline (see
-- 20260811140000_fix_learner_status_auto_promotion.sql). That migration makes
-- partial payments promote learners again — and every promotion fires
-- sync_learner_status_to_profile, which was still deciding login access with:
--
--     should_be_active := (NEW.lifecycle_status IN ('active','graduated'));
--
-- The application grants restricted (induction-only) access to five MORE
-- statuses. lib/constants/induction-access.ts:
--
--     INDUCTION_ELIGIBLE_LIFECYCLE_STATUSES =
--       ['admitted','reserved','enquiry_submitted','enquiry','account']
--
-- and proxy.ts:492 rejects `profile.is_active === false` — redirecting to
-- /unauthorized?reason=inactive AND CLEARING THE AUTH COOKIES — at line 492,
-- before the student lifecycle gate at line 544 ever runs. A learner whose
-- is_active was flipped false never reaches the induction-tier check that would
-- have let them in.
--
-- So promoting a learner reserved -> admitted REVOKED their My Induction login.
--
-- THIS HAS ALREADY HAPPENED. Measured 2026-08-11:
--     reserved   336 enabled /  0 disabled
--     admitted    13 enabled / 15 DISABLED   <- the fingerprint
--     account      1 enabled /  0 disabled
-- The 15 are learners the 120 working auto_threshold promotions carried into
-- 'admitted'; the trigger took their induction access on the way through. The
-- 'reserved' cohort is untouched only because the billing bug meant they were
-- never promoted a second time. Repairing billing without this would have
-- multiplied 15 into 77.
--
-- This is the SAME DRIFT as 20260623150000_graduated_learners_keep_profile_active
-- (which restored 761 locked-out graduated learners), one status-set later. The
-- allow-list lives in four places and only this one was left behind —
-- auto_link_profile_to_approved_learner already carries the full list, which is
-- why access depends on whether a learner's profile was created before or after
-- their promotion.
--
-- Statuses deliberately still BLOCKED: pending, approved, rejected, waitlisted,
-- inactive, withdrawal_pending, exited, alumni.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.sync_learner_status_to_profile()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  existing_profile_id UUID;
  should_be_active BOOLEAN;
BEGIN
  -- Only sync if lifecycle_status changed
  IF OLD.lifecycle_status IS DISTINCT FROM NEW.lifecycle_status THEN

    -- MUST mirror the application's login gates. Two tiers, one flag:
    --   'active' / 'graduated'            -> full portal access
    --   the INDUCTION_ELIGIBLE_* statuses -> restricted, My Induction only
    -- is_active only decides whether the request survives proxy.ts:492 at all;
    -- WHICH pages they then reach is StudentValidationService's accessTier.
    -- Keep this list identical to lib/constants/induction-access.ts and to
    -- auto_link_profile_to_approved_learner, or login depends on the order a
    -- learner's profile and promotion happened to occur in.
    should_be_active := (NEW.lifecycle_status IN (
      'active', 'graduated',
      'admitted', 'reserved', 'enquiry_submitted', 'enquiry', 'account'
    ));

    -- Find profile by learner_id
    SELECT id INTO existing_profile_id
    FROM profiles
    WHERE learner_id = NEW.id
    LIMIT 1;

    IF existing_profile_id IS NOT NULL THEN
      -- Update is_active status
      UPDATE profiles
      SET
        is_active = should_be_active,
        updated_at = NOW()
      WHERE id = existing_profile_id;

      RAISE NOTICE 'Synced profile % is_active to % for learner % (lifecycle_status: % -> %)',
        existing_profile_id, should_be_active, NEW.id, OLD.lifecycle_status, NEW.lifecycle_status;
    ELSE
      RAISE NOTICE 'No profile found for learner % to sync lifecycle_status change', NEW.id;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;

-- ── Repair the learners this already locked out ────────────────────────────
-- Same remedy 20260623150000 applied to graduated learners. Scoped to the
-- induction-eligible statuses only: a disabled profile on any OTHER status was
-- disabled on purpose and must stay that way.
UPDATE public.profiles pr
   SET is_active = true,
       updated_at = NOW()
  FROM public.learners_profiles lp
 WHERE lp.id = pr.learner_id
   AND pr.is_active IS FALSE
   AND lp.lifecycle_status::text IN (
         'admitted', 'reserved', 'enquiry_submitted', 'enquiry', 'account'
       );

-- ============================================================================
-- Safety net: a bounded, re-runnable sweep over stranded learner statuses
-- ============================================================================
-- 20260811140000 repaired the payment triggers and 20260811160000 backfilled the
-- 100 learners they had already stranded. This is the third leg: something that
-- notices if the pipeline ever silently stops again.
--
-- That is not hypothetical. The bug this replaces went unnoticed for months
-- precisely because it failed in the SAFE direction — stale reads can only
-- under-report progress, so nothing errored, no history row was written, and the
-- payment itself always succeeded. The only visible symptom was a number on a
-- report that nobody was diffing. A sweep that promotes 0 learners every night
-- and suddenly promotes 40 is the alarm this system never had.
--
-- Runs IN THE DATABASE rather than as N round trips from the route: the caller
-- gets one call and one summary, and the ~950 evaluations stay next to the data.
--
-- SAFE TO RE-RUN AND SAFE TO OVER-RUN. evaluate_learner_status_after_payment
-- only ever promotes — it returns 'no_op_for_status' outside ('account',
-- 'reserved') and re-asserts the from-status in every UPDATE's WHERE clause.
-- A learner it cannot promote costs one indexed lookup.
--
-- NOT granted to `authenticated`: this is an operator/cron entry point. The
-- single-learner path (the admin "Re-evaluate" action) calls
-- evaluate_learner_status_after_payment directly, which authenticated already
-- holds and which is gated in the service layer.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_sweep_learner_status_promotions(
  p_max_learners integer DEFAULT 5000
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  r             record;
  v_result      jsonb;
  v_seen        integer := 0;
  v_to_reserved integer := 0;
  v_to_admitted integer := 0;
  v_cap         integer := LEAST(GREATEST(COALESCE(p_max_learners, 5000), 1), 20000);
BEGIN
  FOR r IN
    SELECT lp.id
    FROM public.learners_profiles lp
    -- The only two statuses the evaluator can act on. Scoping here rather than
    -- letting it no-op keeps the sweep proportional to the backlog, not to the
    -- 6,000-row learner table.
    WHERE lp.lifecycle_status::text IN ('account', 'reserved')
    ORDER BY lp.id
    LIMIT v_cap
  LOOP
    v_result := public.evaluate_learner_status_after_payment(r.id);
    v_seen := v_seen + 1;

    IF (v_result ->> 'promoted_to_universal')::boolean THEN
      v_to_reserved := v_to_reserved + 1;
    END IF;
    IF (v_result ->> 'promoted_to_threshold')::boolean THEN
      v_to_admitted := v_to_admitted + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'evaluated', v_seen,
    'promoted_to_reserved', v_to_reserved,
    'promoted_to_admitted', v_to_admitted,
    -- Non-zero on a healthy night means a payment slipped past the triggers.
    -- Treat a sustained non-zero as a regression, not as routine catch-up.
    'promoted_total', v_to_reserved + v_to_admitted,
    'capped', (v_seen = v_cap)
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_sweep_learner_status_promotions(integer)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_sweep_learner_status_promotions(integer)
  TO service_role;


-- Updated: 2026-08-10 - Referral attribution + quota audit on the LEARNER record.
-- Writes one referral_attribution_audit row per watched field that actually
-- changed on a learners_profiles UPDATE. Trigger declaration lives in
-- 04_triggers.sql; migration
-- supabase/migrations/20260818030000_extend_referral_source_audit.sql
-- — FILE ONLY, NOT APPLIED.
--
-- SECURITY DEFINER for two reasons: the people who edit a learner's referral
-- hold no INSERT on the audit table (nobody does), and an audit row must not be
-- subject to the writer's own RLS. Running as the owner is what makes the trail
-- both unforgeable and unavoidable.
--
-- 🔴 IT MUST NEVER BLOCK A LEGITIMATE UPDATE. Every error is downgraded to a
-- WARNING and the update proceeds. The trade is explicit: a lost audit row is
-- recoverable by asking; a blocked admission is not.
--
-- The distinctness test runs FIRST, outside the exception block. A plpgsql
-- EXCEPTION block opens a subtransaction on every entry, and bulk learner edits
-- mention these columns thousands of rows at a time while changing almost none
-- of them — returning early keeps that cost off the common path.
--
-- 🔴 Purely additive. learners_profiles already carries
-- trg_sync_learner_referral_to_attribution, which DELETES the prior
-- consultant_lead_attributions row when referred_by_id changes. This function
-- touches nothing but its own table and returns NEW unmodified, so it cannot
-- interfere with that trigger whichever order the two fire in.
CREATE OR REPLACE FUNCTION public.fn_audit_learner_referral_attribution()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_actor uuid;
BEGIN
  -- Nothing actually moved: leave without opening a subtransaction. `UPDATE OF`
  -- fires whenever a watched column is MENTIONED, not only when it changes.
  IF NOT (
       OLD.referral_type      IS DISTINCT FROM NEW.referral_type
    OR OLD.referred_by_id     IS DISTINCT FROM NEW.referred_by_id
    OR OLD.referred_by_name   IS DISTINCT FROM NEW.referred_by_name
    OR OLD.quota_id           IS DISTINCT FROM NEW.quota_id
    OR OLD.counseling_applied IS DISTINCT FROM NEW.counseling_applied
  ) THEN
    RETURN NEW;
  END IF;

  BEGIN
    -- Inside the guard as well: with no JWT this is simply NULL, but a
    -- malformed claim would raise, and losing the row is the correct outcome
    -- there — never failing the learner's update.
    v_actor := auth.uid();

    INSERT INTO public.referral_attribution_audit
      (learner_profile_id, changed_field, old_value, new_value, changed_by)
    SELECT NEW.id, f.field, f.old_value, f.new_value, v_actor
    -- Every value is cast to text EXPLICITLY, including the two columns that
    -- are already text: a VALUES list resolves one common type per column, and
    -- because the handler swallows errors, a future type change on
    -- referral_type would turn the whole trail into a silent no-op rather than
    -- a visible failure. The redundant casts remove that dependency for free.
    FROM (
      VALUES
        ('referral_type',      OLD.referral_type::text,      NEW.referral_type::text),
        ('referred_by_id',     OLD.referred_by_id::text,     NEW.referred_by_id::text),
        ('referred_by_name',   OLD.referred_by_name::text,   NEW.referred_by_name::text),
        ('quota_id',           OLD.quota_id::text,           NEW.quota_id::text),
        ('counseling_applied', OLD.counseling_applied::text, NEW.counseling_applied::text)
    ) AS f(field, old_value, new_value)
    WHERE f.old_value IS DISTINCT FROM f.new_value;

  EXCEPTION WHEN OTHERS THEN
    -- Visible in the Postgres log, invisible to the person saving the form.
    RAISE WARNING 'fn_audit_learner_referral_attribution: audit write skipped for learner_profile_id=% (%: %)',
      NEW.id, SQLSTATE, SQLERRM;
  END;

  RETURN NEW;
END;
$function$;

-- Supabase default privileges hand EXECUTE on every new function to anon, which
-- is a separate grant from PUBLIC and survives a REVOKE FROM PUBLIC alone.
REVOKE EXECUTE ON FUNCTION public.fn_audit_learner_referral_attribution() FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_audit_learner_referral_attribution() TO authenticated;


-- Updated: 2026-08-10 - Referral integrity: reconciliation + pair scoring functions.
-- fn_reconcile_referral_session  : compares one agency's own submitted list against
--   the credits the platform holds for it, writes the three-way bucket onto every
--   claim row, returns a jsonb count summary.
-- fn_recompute_referral_pair_score : recomputes a (team member, agency) score from
--   reconciliation outcomes. NEVER freezes and never lifts a freeze.
-- fn_set_referral_pair_freeze    : the human act — administrator only, reason
--   mandatory, records who and why.
-- All three are SECURITY DEFINER with an explicit in-body gate (DEFINER bypasses
-- RLS) and an explicit anon revoke. None of them create, approve or pay a
-- commission. Source migration:
-- supabase/migrations/20260818040000_referral_reconciliation_and_pair_scoring.sql
-- (FILE ONLY, NOT APPLIED).

CREATE OR REPLACE FUNCTION public.fn_reconcile_referral_session(p_session_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_consultant_id uuid;
  v_year          integer;
  v_summary       jsonb;
BEGIN
  -- SECURITY DEFINER bypasses RLS, so the gate has to be explicit here.
  IF NOT (is_super_admin() OR is_admin()
          OR user_has_permission('admission.consultants.commissions.manage')) THEN
    RAISE EXCEPTION 'Not authorised to reconcile referral sessions';
  END IF;

  SELECT consultant_id, academic_year
    INTO v_consultant_id, v_year
    FROM public.referral_reconciliation_sessions
   WHERE id = p_session_id;

  IF v_consultant_id IS NULL THEN
    RAISE EXCEPTION 'Reconciliation session % not found', p_session_id;
  END IF;

  -- (a) Every learner the platform currently credits to this agency for this year.
  CREATE TEMP TABLE _credited ON COMMIT DROP AS
  SELECT lp.id AS learner_id,
         btrim(coalesce(lp.first_name, '') || ' ' || coalesce(lp.last_name, '')) AS learner_name,
         right(regexp_replace(coalesce(lp.student_mobile, ''), '[^0-9]', '', 'g'), 10) AS phone10
    FROM public.learners_profiles lp
    JOIN public.admission_years ay ON ay.id = lp.admission_year_id AND ay.year = v_year
   WHERE lp.referral_type = 'consultant'
     AND lp.referred_by_id = v_consultant_id;

  -- (b) Every learner of that intake year, for resolving the agency's claims.
  CREATE TEMP TABLE _pool ON COMMIT DROP AS
  SELECT lp.id AS learner_id,
         lower(btrim(coalesce(lp.first_name, '') || ' ' || coalesce(lp.last_name, ''))) AS name_key,
         right(regexp_replace(coalesce(lp.student_mobile, ''), '[^0-9]', '', 'g'), 10) AS phone10
    FROM public.learners_profiles lp
    JOIN public.admission_years ay ON ay.id = lp.admission_year_id AND ay.year = v_year;

  -- (c) Resolve each row the Registrar typed to a learner, phone first then name.
  --     Both keys are required to be UNAMBIGUOUS in the pool. Two learners of the
  --     same intake can share a name, and UPDATE ... FROM would silently pick one
  --     of them at random; an ambiguous key is not a match, it is a question for a
  --     person, so it is left unmatched instead of guessed.
  UPDATE public.referral_reconciliation_claims c
     SET matched_learner_id = m.learner_id,
         match_confidence   = m.confidence,
         updated_at         = now()
    FROM (
      SELECT DISTINCT ON (claim_id) claim_id, learner_id, confidence
        FROM (
          SELECT c2.id AS claim_id, p.learner_id, 'phone'::text AS confidence, 1 AS rank
            FROM public.referral_reconciliation_claims c2
            JOIN _pool p
              ON p.phone10 <> ''
             AND p.phone10 = right(regexp_replace(coalesce(c2.claimed_phone, ''), '[^0-9]', '', 'g'), 10)
           WHERE c2.session_id = p_session_id AND c2.source = 'agency'
             AND (SELECT count(*) FROM _pool q WHERE q.phone10 = p.phone10) = 1
           UNION ALL
          SELECT c3.id, p.learner_id, 'name', 2
            FROM public.referral_reconciliation_claims c3
            JOIN _pool p
              ON p.name_key <> ''
             AND p.name_key = lower(btrim(coalesce(c3.claimed_name, '')))
           WHERE c3.session_id = p_session_id AND c3.source = 'agency'
             AND (SELECT count(*) FROM _pool q WHERE q.name_key = p.name_key) = 1
        ) cand
       ORDER BY claim_id, rank          -- a phone hit always beats a name hit
    ) m
   WHERE c.id = m.claim_id;

  -- A claim that resolved to nothing is recorded as such rather than left blank,
  -- so "not matched" is a stated outcome and not an unfinished run.
  UPDATE public.referral_reconciliation_claims
     SET match_confidence = 'none', updated_at = now()
   WHERE session_id = p_session_id
     AND source = 'agency'
     AND matched_learner_id IS NULL;

  -- (d) Bucket the agency's own rows.
  UPDATE public.referral_reconciliation_claims c
     SET bucket = CASE
                    WHEN c.matched_learner_id IS NOT NULL
                     AND EXISTS (SELECT 1 FROM _credited cr WHERE cr.learner_id = c.matched_learner_id)
                    THEN 'agreed'
                    ELSE 'claimed_not_credited'
                  END,
         updated_at = now()
   WHERE c.session_id = p_session_id
     AND c.source = 'agency';

  -- (e) Rebuild the credited-but-unclaimed rows. Only 'system' rows are replaced;
  --     anything a person typed or marked survives a re-run untouched.
  DELETE FROM public.referral_reconciliation_claims
   WHERE session_id = p_session_id AND source = 'system';

  INSERT INTO public.referral_reconciliation_claims
    (session_id, claimed_name, claimed_phone, matched_learner_id, match_confidence, bucket, source)
  SELECT p_session_id, NULLIF(cr.learner_name, ''), NULLIF(cr.phone10, ''),
         cr.learner_id, 'phone', 'credited_not_claimed', 'system'
    FROM _credited cr
   WHERE NOT EXISTS (
     SELECT 1 FROM public.referral_reconciliation_claims c
      WHERE c.session_id = p_session_id
        AND c.source = 'agency'
        AND c.matched_learner_id = cr.learner_id
   );

  SELECT jsonb_build_object(
    'session_id',           p_session_id,
    'consultant_id',        v_consultant_id,
    'academic_year',        v_year,
    'credited_by_platform', (SELECT count(*) FROM _credited),
    'claimed_by_agency',    (SELECT count(*) FROM public.referral_reconciliation_claims
                              WHERE session_id = p_session_id AND source = 'agency'),
    'agreed',               (SELECT count(*) FROM public.referral_reconciliation_claims
                              WHERE session_id = p_session_id AND bucket = 'agreed'),
    'credited_not_claimed', (SELECT count(*) FROM public.referral_reconciliation_claims
                              WHERE session_id = p_session_id AND bucket = 'credited_not_claimed'),
    'claimed_not_credited', (SELECT count(*) FROM public.referral_reconciliation_claims
                              WHERE session_id = p_session_id AND bucket = 'claimed_not_credited'),
    'unmatched_claims',     (SELECT count(*) FROM public.referral_reconciliation_claims
                              WHERE session_id = p_session_id AND source = 'agency'
                                AND matched_learner_id IS NULL)
  ) INTO v_summary;

  RETURN v_summary;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_reconcile_referral_session(uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_reconcile_referral_session(uuid) TO authenticated;

COMMENT ON FUNCTION public.fn_reconcile_referral_session(uuid) IS
  'Compares one agency''s own submitted list against the credits the platform holds for that agency and intake year, writes the three-way bucket onto every claim row, and returns a jsonb count summary. Writes nothing outside the reconciliation tables — it never creates, approves or pays a commission.';

-- ─────────────────────────────────────────────────────────────────────────────
-- 5. Pair score — recompute from reconciliation outcomes
--
--    A credit is attributed to the team member who verified the attribution, and
--    where nothing was verified, to whoever created the learner record. That
--    fallback matters: a credit nobody verified is exactly the shape this loop is
--    looking for, so it must not fall out of the count.
--
--    NEVER auto-freezes. Raising a risk level is a measurement; stopping money is
--    a decision, and a decision needs a person's name on it.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.fn_recompute_referral_pair_score(
  p_team_member_id uuid,
  p_consultant_id  uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_total     integer := 0;
  v_confirmed integer := 0;
  v_disputed  integer := 0;
  v_risk      text;
BEGIN
  IF NOT (is_super_admin() OR is_admin()
          OR user_has_permission('admission.consultants.commissions.manage')) THEN
    RAISE EXCEPTION 'Not authorised to recompute referral pair scores';
  END IF;

  WITH pair_credits AS (
    -- every credit this agency holds that traces back to this team member
    SELECT lp.id AS learner_id
      FROM public.learners_profiles lp
      LEFT JOIN LATERAL (
        SELECT cla.verified_by
          FROM public.consultant_lead_attributions cla
         WHERE cla.learner_profile_id = lp.id
           AND cla.consultant_id = p_consultant_id
           AND cla.verified_by IS NOT NULL
         ORDER BY cla.verified_at DESC NULLS LAST
         LIMIT 1
      ) v ON true
     WHERE lp.referral_type = 'consultant'
       AND lp.referred_by_id = p_consultant_id
       AND COALESCE(v.verified_by, lp.created_by) = p_team_member_id
  ),
  outcomes AS (
    -- The most recent reconciliation verdict recorded for each of those credits.
    -- One LATERAL, not two scalar subqueries: bucket and evidence_status must come
    -- from the SAME claim row, and two independent ORDER BY ... LIMIT 1 can break a
    -- tie differently and pair a bucket with another row's evidence.
    SELECT pc.learner_id, v.bucket, v.evidence_status
      FROM pair_credits pc
      LEFT JOIN LATERAL (
        SELECT c.bucket, c.evidence_status
          FROM public.referral_reconciliation_claims c
          JOIN public.referral_reconciliation_sessions s ON s.id = c.session_id
         WHERE c.matched_learner_id = pc.learner_id
           AND s.consultant_id = p_consultant_id
         ORDER BY s.conducted_at DESC, c.updated_at DESC, c.id DESC
         LIMIT 1
      ) v ON true
  )
  SELECT count(*),
         count(*) FILTER (
           WHERE bucket = 'agreed'
             AND evidence_status IS DISTINCT FROM 'agency_does_not_recognise'),
         count(*) FILTER (
           WHERE bucket = 'credited_not_claimed'
              OR evidence_status = 'agency_does_not_recognise')
    INTO v_total, v_confirmed, v_disputed
    FROM outcomes;

  -- Thresholds are deliberately blunt and readable. 'red' also fires on the ratio
  -- so a small agency with 3 credits and 2 disputed is not hidden behind a count.
  v_risk := CASE
              WHEN v_disputed >= 4 THEN 'red'
              WHEN v_total > 0 AND v_disputed::numeric > (v_total::numeric / 3.0) THEN 'red'
              WHEN v_disputed >= 2 THEN 'watch'
              ELSE 'normal'
            END;

  INSERT INTO public.referral_pair_scores AS s
    (team_member_id, consultant_id, credits_total, credits_confirmed, credits_disputed,
     risk_level, updated_at)
  VALUES
    (p_team_member_id, p_consultant_id, v_total, v_confirmed, v_disputed, v_risk, now())
  ON CONFLICT ON CONSTRAINT referral_pair_scores_pair_unique DO UPDATE
    SET credits_total     = EXCLUDED.credits_total,
        credits_confirmed = EXCLUDED.credits_confirmed,
        credits_disputed  = EXCLUDED.credits_disputed,
        risk_level        = EXCLUDED.risk_level,
        updated_at        = now();
    -- frozen / frozen_at / frozen_by / frozen_reason are intentionally absent from
    -- this SET list. Recomputing evidence must never lift or apply a human freeze.

  RETURN jsonb_build_object(
    'team_member_id',    p_team_member_id,
    'consultant_id',     p_consultant_id,
    'credits_total',     v_total,
    'credits_confirmed', v_confirmed,
    'credits_disputed',  v_disputed,
    'risk_level',        v_risk
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_recompute_referral_pair_score(uuid, uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_recompute_referral_pair_score(uuid, uuid) TO authenticated;

COMMENT ON FUNCTION public.fn_recompute_referral_pair_score(uuid, uuid) IS
  'Recomputes the (team member, agency) pair score from reconciliation outcomes and sets risk_level normal/watch/red. Never freezes and never lifts a freeze — freezing is a human act performed through fn_set_referral_pair_freeze.';

-- ─────────────────────────────────────────────────────────────────────────────
-- 6. Freeze / unfreeze — the human act, admin-only, always with a reason
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.fn_set_referral_pair_freeze(
  p_team_member_id uuid,
  p_consultant_id  uuid,
  p_frozen         boolean,
  p_reason         text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE v_row public.referral_pair_scores;
BEGIN
  IF NOT (is_super_admin() OR is_admin()) THEN
    RAISE EXCEPTION 'Only an administrator can freeze or unfreeze a referral pair';
  END IF;

  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'A reason is required to freeze or unfreeze a referral pair';
  END IF;

  INSERT INTO public.referral_pair_scores AS s
    (team_member_id, consultant_id, frozen, frozen_at, frozen_by, frozen_reason, updated_at)
  VALUES
    (p_team_member_id, p_consultant_id, p_frozen,
     CASE WHEN p_frozen THEN now() ELSE NULL END,
     auth.uid(), btrim(p_reason), now())
  ON CONFLICT ON CONSTRAINT referral_pair_scores_pair_unique DO UPDATE
    SET frozen        = EXCLUDED.frozen,
        frozen_at     = EXCLUDED.frozen_at,
        frozen_by     = EXCLUDED.frozen_by,
        frozen_reason = EXCLUDED.frozen_reason,
        updated_at    = now()
  RETURNING s.* INTO v_row;

  RETURN jsonb_build_object(
    'team_member_id', v_row.team_member_id,
    'consultant_id',  v_row.consultant_id,
    'frozen',         v_row.frozen,
    'frozen_at',      v_row.frozen_at,
    'frozen_by',      v_row.frozen_by,
    'frozen_reason',  v_row.frozen_reason,
    'risk_level',     v_row.risk_level
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_set_referral_pair_freeze(uuid, uuid, boolean, text) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_set_referral_pair_freeze(uuid, uuid, boolean, text) TO authenticated;

COMMENT ON FUNCTION public.fn_set_referral_pair_freeze(uuid, uuid, boolean, text) IS
  'Records an administrator freezing or unfreezing a (team member, agency) pair, with who and why. The flag is recorded and displayed only — no generator or payout path reads it yet.';

-- =====================================================================
-- Updated: 2026-08-10 - JKKN permanent identity: issuer, duplicate guard,
-- universal resolver (the three SECURITY DEFINER RPCs).
-- Migration: supabase/migrations/20260817050000_jkkn_identity_rpcs.sql
-- FILE ONLY / NOT APPLIED to production as of 2026-08-10.
-- =====================================================================
-- The two IMMUTABLE check-digit functions (fn_jkkn_id_check_digit,
-- fn_jkkn_id_validate) are declared in 01_tables.sql, not here: a CHECK
-- constraint on jkkn_identities calls fn_jkkn_id_validate, and 01_tables
-- runs before this file. See the note there.

-- ---------------------------------------------------------------------
-- 1. fn_issue_jkkn_id — allocate one permanent number
-- ---------------------------------------------------------------------
-- WHY RANDOM, NOT SEQUENTIAL
-- A sequential number publishes two things JKKN does not intend to
-- publish, on every ID card, forever: how many people the cluster has
-- taken in, and who joined before whom. 100000-000012 tells a stranger
-- they are looking at the twelfth person ever registered. Random
-- allocation over the 900,000-number space costs one retry loop and
-- leaks neither.
--
-- Collision maths: with even 50,000 numbers issued, a fresh draw
-- collides with probability 0.056, so eight attempts fail together about
-- once in 10^10 draws. The loop is bounded at 20 and raises rather than
-- spinning.
-- ---------------------------------------------------------------------
-- Corrected 2026-08-13: widened to a 4-argument signature to issue a
-- third person_kind, 'external_participant', anchored on a profile
-- rather than a learner/staff row. This is a DROP + CREATE, not a bare
-- CREATE OR REPLACE: a defaulted 4th parameter alongside the old 3-arg
-- signature would create an OVERLOAD, and a 3-argument call would then
-- match both and fail with 42725 "function is not unique". The old
-- signature is gone, so the REVOKE/GRANT below is re-issued against the
-- new one. Mirrors migration 20260813100500_jkkn_identity_external_participant.sql.
-- Split 2026-08-27 (migration 20260827110000): the random-draw insert loop
-- moved into fn_jkkn_allocate, a PRIVATE allocator shared by fn_issue_jkkn_id
-- and the auto-issue triggers below. It carries no permission gate of its own;
-- EXECUTE is revoked from every client role, so it is only reachable through
-- its SECURITY DEFINER callers, each of which owns authorisation.
-- p_issued_by NULL means "issued by the system" (a trigger).
CREATE OR REPLACE FUNCTION public.fn_jkkn_allocate(
  p_person_kind        text,
  p_learner_profile_id uuid,
  p_team_member_id     uuid,
  p_profile_id         uuid,
  p_issued_by          uuid
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_attempt   int;
  v_six       text;
  v_candidate text;
  v_id        uuid;
  v_existing  text;
BEGIN
  -- One person, one number, for life. Refuse a second — the whole design
  -- rests on a learner who returns as a team member keeping the number they
  -- already have. (The partial unique indexes enforce this too; this check
  -- exists to fail with a sentence a human can act on.)
  SELECT jkkn_id INTO v_existing
    FROM public.jkkn_identities
   WHERE (p_learner_profile_id IS NOT NULL AND learner_profile_id = p_learner_profile_id)
      OR (p_team_member_id     IS NOT NULL AND team_member_id     = p_team_member_id)
      OR (p_profile_id         IS NOT NULL AND profile_id         = p_profile_id)
   LIMIT 1;

  IF v_existing IS NOT NULL THEN
    RAISE EXCEPTION 'This person already holds JKKN ID %. A person is issued one number for life; to record a new capacity, update person_kind on the existing row.', btrim(v_existing)
      USING ERRCODE = '23505';
  END IF;

  FOR v_attempt IN 1..20 LOOP
    -- 100000..999999 inclusive: random() is [0,1), so floor(random()*900000)
    -- is 0..899999.
    v_six       := (100000 + floor(random() * 900000))::int::text;
    v_candidate := v_six || '-' || public.fn_jkkn_id_check_digit(v_six);

    INSERT INTO public.jkkn_identities (
      jkkn_id, person_kind, learner_profile_id, team_member_id, profile_id, issued_by
    )
    VALUES (
      v_candidate, p_person_kind, p_learner_profile_id, p_team_member_id, p_profile_id, p_issued_by
    )
    ON CONFLICT (jkkn_id) DO NOTHING
    RETURNING id INTO v_id;

    -- ON CONFLICT covers only a number collision. A one-person-one-number
    -- violation is a different unique index and is left to raise.
    IF v_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'ok',          true,
        'identity_id', v_id,
        'jkkn_id',     v_candidate,
        'person_kind', p_person_kind,
        'attempts',    v_attempt
      );
    END IF;
  END LOOP;

  RAISE EXCEPTION 'Could not find an unused JKKN ID in 20 attempts. The 900,000-number pool is close to exhausted or something is wrong.'
    USING ERRCODE = '53400';
END;
$fn$;

COMMENT ON FUNCTION public.fn_jkkn_allocate(text, uuid, uuid, uuid, uuid) IS
  'PRIVATE allocator behind fn_issue_jkkn_id and the auto-issue triggers. Draws a random unused JKKN ID and inserts the register row. Carries no permission gate of its own — EXECUTE is revoked from every client role; its callers own authorisation.';

REVOKE ALL ON FUNCTION public.fn_jkkn_allocate(text, uuid, uuid, uuid, uuid) FROM anon, authenticated, PUBLIC;

DROP FUNCTION IF EXISTS public.fn_issue_jkkn_id(text, uuid, uuid);

CREATE OR REPLACE FUNCTION public.fn_issue_jkkn_id(
  p_person_kind        text,
  p_learner_profile_id uuid DEFAULT NULL,
  p_team_member_id     uuid DEFAULT NULL,
  p_profile_id         uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
BEGIN
  -- Two gates, not one. The general power to mint a permanent number for
  -- a learner or a team member stays on users.jkkn_id.issue, which is
  -- also the key on the jkkn_identities INSERT/UPDATE policies — so it
  -- remains the only way to write that table by hand.
  --
  -- An external_participant identity is different in kind. It is never
  -- issued on its own: it exists only as one step inside
  -- fn_course_approve_application, which has already established that the
  -- caller may decide this application. Requiring the global key there
  -- meant a Course Coordinator who could approve got 42501 at the last
  -- step, and the only way to unblock them was to grant the global key —
  -- which would also let them mint and rewrite identities for any learner
  -- or team member straight through PostgREST.
  --
  -- IS NOT DISTINCT FROM, not `=`: with `=`, a NULL p_person_kind makes
  -- that term NULL, the OR chain evaluates to NULL, and plpgsql treats
  -- IF NULL as false — the gate would pass silently. This form fails
  -- closed.
  IF NOT (
    COALESCE(public.is_super_admin(), false)
    OR public.is_admin()
    OR public.user_has_permission('users.jkkn_id.issue')
    OR (
      p_person_kind IS NOT DISTINCT FROM 'external_participant'
      AND public.user_has_permission('courses.applications.decide')
    )
  ) THEN
    RAISE EXCEPTION 'Not authorised to issue a JKKN ID'
      USING ERRCODE = '42501';
  END IF;

  IF p_person_kind IS NULL
     OR p_person_kind NOT IN ('learner','team_member','both','external_participant','associate') THEN
    RAISE EXCEPTION 'person_kind must be learner, team_member, both, external_participant or associate (got %)', p_person_kind
      USING ERRCODE = '22023';
  END IF;

  -- The link shape must match the kind, and the person must actually
  -- exist. The table tolerates an orphaned link (a person record can be
  -- removed years later and the number must survive); issuance does not.
  IF p_person_kind IN ('learner', 'both') THEN
    IF p_learner_profile_id IS NULL THEN
      RAISE EXCEPTION 'A % identity needs a learner profile', p_person_kind
        USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.learners_profiles WHERE id = p_learner_profile_id) THEN
      RAISE EXCEPTION 'No learner profile %', p_learner_profile_id
        USING ERRCODE = '23503';
    END IF;
  ELSIF p_learner_profile_id IS NOT NULL THEN
    RAISE EXCEPTION 'A % identity must not carry a learner profile', p_person_kind
      USING ERRCODE = '22023';
  END IF;

  IF p_person_kind IN ('team_member', 'both') THEN
    IF p_team_member_id IS NULL THEN
      RAISE EXCEPTION 'A % identity needs a team member', p_person_kind
        USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.staff WHERE id = p_team_member_id) THEN
      RAISE EXCEPTION 'No team member %', p_team_member_id
        USING ERRCODE = '23503';
    END IF;
  ELSIF p_team_member_id IS NOT NULL THEN
    RAISE EXCEPTION 'A % identity must not carry a team member', p_person_kind
      USING ERRCODE = '22023';
  END IF;

  -- Profile-anchored kinds: external_participant (Course Events, 2026-08-13)
  -- and associate (2026-08-27).
  IF p_person_kind IN ('external_participant', 'associate') THEN
    IF p_profile_id IS NULL THEN
      RAISE EXCEPTION 'A % identity needs a profile', p_person_kind
        USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_profile_id) THEN
      RAISE EXCEPTION 'No profile %', p_profile_id
        USING ERRCODE = '23503';
    END IF;
  ELSIF p_profile_id IS NOT NULL THEN
    RAISE EXCEPTION 'Only an external_participant or associate identity is issued against a profile'
      USING ERRCODE = '22023';
  END IF;

  RETURN public.fn_jkkn_allocate(
    p_person_kind, p_learner_profile_id, p_team_member_id, p_profile_id, auth.uid()
  );
END;
$fn$;

COMMENT ON FUNCTION public.fn_issue_jkkn_id(text, uuid, uuid, uuid) IS
  'Issues ONE permanent JKKN ID to a person who does not already hold one. Kinds: learner, team_member, both, external_participant (Course Events, 2026-08-13), associate (profile-only internal users, 2026-08-27). Gated on users.jkkn_id.issue, EXCEPT the external_participant kind, which also accepts courses.applications.decide. Allocation itself lives in fn_jkkn_allocate; auto-issuance triggers call that allocator directly.';

-- DROP FUNCTION discarded the ACL. Restore it.
REVOKE EXECUTE ON FUNCTION public.fn_issue_jkkn_id(text, uuid, uuid, uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_issue_jkkn_id(text, uuid, uuid, uuid) TO authenticated;

-- ---------------------------------------------------------------------
-- Course Events — role grants and the Course Participant role
-- Added: 2026-08-13. Mirrors migration
-- 20260813100600_course_permissions_and_role.sql. A key declared in
-- lib/constants/permissions.ts grants nothing until it is written into a
-- role's custom_roles.permissions JSONB — this seeds that for a
-- from-scratch rebuild.
-- ---------------------------------------------------------------------
UPDATE public.custom_roles
   SET permissions = permissions || jsonb_build_object(
         'courses.view',                 true,
         'courses.create',               true,
         'courses.edit',                 true,
         'courses.packages.manage',      true,
         'courses.forms.manage',         true,
         'courses.sessions.manage',      true,
         'courses.applications.view',    true,
         'courses.applications.decide',  true,
         'courses.enrollments.manage',   true,
         'courses.billing.view',         true,
         'courses.billing.manage',       true,
         'courses.attendance.mark',      true,
         'courses.certificates.issue',   true,
         -- Approval issues a permanent JKKN ID, so the deciding role
         -- needs the issuer's own gate too. Granted here rather than by
         -- widening fn_issue_jkkn_id, which stays admin-gated.
         'users.jkkn_id.issue',          true
       ),
       updated_at = now()
 WHERE role_key = ANY (ARRAY['administrator','coo']);

-- courses.delete is deliberately NOT bundled above. It cascades packages,
-- sessions, forms, applications and enrollments; grant it from Role
-- Management deliberately, per role. Super admins pass via
-- user_has_permission()'s own bypass.

-- Exactly ONE key. This role is assigned to every externally provisioned
-- participant, so anything added here is granted to every outside person
-- holding a login. institution_scope='own' — the CHECK constraint on
-- custom_roles admits only 'all'/'own'; 'own' is functionally inert here
-- because role_has_institution_access() special-cases only scope='all',
-- and every other branch fails for an external participant whose
-- profile has institution_id NULL.
INSERT INTO public.custom_roles
  (role_key, role_name, description, is_system_role, is_active,
   institution_scope, permissions, module_scopes)
VALUES
  ('course_participant',
   'Course Participant',
   'A person enrolled on a paid course. Sees only their own enrollment, bills and receipts, and is confined to the /my-courses portal. Assigned automatically at application approval.',
   true, true, 'own',
   jsonb_build_object('courses.participant.self', true),
   '{}'::jsonb)
ON CONFLICT (role_key) DO UPDATE
   SET permissions = jsonb_build_object('courses.participant.self', true),
       institution_scope = 'own',
       is_active   = true,
       updated_at  = now();

-- ---------------------------------------------------------------------
-- 2. fn_check_duplicate_person — the guard, called BEFORE creating anyone
-- ---------------------------------------------------------------------
-- NEVER AUTO-MERGES, AND CANNOT BE MADE TO. Twins share a surname and a
-- date of birth, and often a household phone. An automatic merge on that
-- evidence fuses two real learners into one record, and un-fusing them
-- afterwards means unpicking marks, fees, attendance and hostel rows that
-- have all been written against the survivor. This function returns
-- findings and a verdict; a human decides.
--
-- Verdicts:
--   block   — an exact Aadhaar match. Same person, near certainly.
--   review  — same name + date of birth, or the same personal mobile.
--             A human looks. Frequently a sibling or a genuine namesake.
--   clear   — nothing matched on the evidence that could be checked.
--
-- AADHAAR IS NOT STORED ANYWHERE IN MyJKKN TODAY. Neither
-- learners_profiles nor staff has such a column, and no alias type carries
-- one. So the 'block' branch is wired but structurally dark: when an
-- Aadhaar is supplied, the result says aadhaar_checked = false with a
-- reason, rather than reporting "no duplicate" — a producer that could not
-- check must say so, not return silence that reads like a clean result.
-- Whether JKKN should hold Aadhaar at all is a Director decision with real
-- compliance weight, and is deliberately not made here.
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_check_duplicate_person(
  p_aadhaar    text DEFAULT NULL,
  p_first_name text DEFAULT NULL,
  p_last_name  text DEFAULT NULL,
  p_dob        date DEFAULT NULL,
  p_phone      text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_first    text := lower(btrim(coalesce(p_first_name, '')));
  v_last     text := lower(btrim(coalesce(p_last_name, '')));
  v_phone    text := right(regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g'), 10);
  v_findings jsonb := '[]'::jsonb;
  v_verdict  text  := 'clear';
  v_aadhaar_checked boolean := false;
  v_aadhaar_note    text;
BEGIN
  IF NOT (
    COALESCE(public.is_super_admin(), false)
    OR public.is_admin()
    OR public.user_has_permission('users.jkkn_id.view')
  ) THEN
    RAISE EXCEPTION 'Not authorised to run the duplicate check'
      USING ERRCODE = '42501';
  END IF;

  IF btrim(coalesce(p_aadhaar, '')) <> '' THEN
    v_aadhaar_note := 'An Aadhaar number was supplied but MyJKKN stores no Aadhaar, on any table. This dimension could NOT be checked — treat it as unknown, not as clear.';
  END IF;

  IF length(v_phone) < 10 THEN
    v_phone := NULL;
  END IF;

  -- Same name + date of birth (learners).
  IF v_first <> '' AND p_dob IS NOT NULL THEN
    SELECT v_findings || COALESCE(jsonb_agg(f), '[]'::jsonb) INTO v_findings
    FROM (
      SELECT jsonb_build_object(
               'matched_on',  'name_and_dob',
               'person_kind', 'learner',
               'person_id',   lp.id,
               'full_name',   btrim(lp.first_name || ' ' || coalesce(lp.last_name, '')),
               'date_of_birth', lp.date_of_birth,
               'status',      lp.lifecycle_status::text,
               'roll_number', lp.roll_number,
               'jkkn_id',     btrim(ji.jkkn_id)
             ) AS f
        FROM public.learners_profiles lp
        LEFT JOIN public.jkkn_identities ji ON ji.learner_profile_id = lp.id
       WHERE lower(btrim(lp.first_name)) = v_first
         AND (v_last = '' OR lower(btrim(coalesce(lp.last_name, ''))) = v_last)
         -- date_of_birth is TEXT on learners_profiles, so cast defensively:
         -- a malformed value must not abort the whole guard.
         AND CASE
               WHEN lp.date_of_birth ~ '^\d{4}-\d{2}-\d{2}'
                 THEN substr(lp.date_of_birth, 1, 10)::date
             END = p_dob
       LIMIT 25
    ) s;

    SELECT v_findings || COALESCE(jsonb_agg(f), '[]'::jsonb) INTO v_findings
    FROM (
      SELECT jsonb_build_object(
               'matched_on',  'name_and_dob',
               'person_kind', 'team_member',
               'person_id',   st.id,
               'full_name',   btrim(st.first_name || ' ' || coalesce(st.last_name, '')),
               'date_of_birth', st.date_of_birth::text,
               'status',      CASE WHEN st.is_active THEN 'active' ELSE 'inactive' END,
               'team_code',   st.staff_id,
               'jkkn_id',     btrim(ji.jkkn_id)
             ) AS f
        FROM public.staff st
        LEFT JOIN public.jkkn_identities ji ON ji.team_member_id = st.id
       WHERE lower(btrim(st.first_name)) = v_first
         AND (v_last = '' OR lower(btrim(coalesce(st.last_name, ''))) = v_last)
         AND st.date_of_birth = p_dob
       LIMIT 25
    ) s;
  END IF;

  -- Same personal mobile. Deliberately NOT father_mobile / mother_mobile:
  -- siblings share a parent's number as a matter of course, so matching on
  -- those would push every second learner into review and the review queue
  -- would stop being read.
  IF v_phone IS NOT NULL THEN
    SELECT v_findings || COALESCE(jsonb_agg(f), '[]'::jsonb) INTO v_findings
    FROM (
      SELECT jsonb_build_object(
               'matched_on',  'phone',
               'person_kind', 'learner',
               'person_id',   lp.id,
               'full_name',   btrim(lp.first_name || ' ' || coalesce(lp.last_name, '')),
               'phone',       lp.student_mobile,
               'status',      lp.lifecycle_status::text,
               'roll_number', lp.roll_number,
               'jkkn_id',     btrim(ji.jkkn_id)
             ) AS f
        FROM public.learners_profiles lp
        LEFT JOIN public.jkkn_identities ji ON ji.learner_profile_id = lp.id
       WHERE right(regexp_replace(coalesce(lp.student_mobile, ''), '[^0-9]', '', 'g'), 10) = v_phone
       LIMIT 25
    ) s;

    SELECT v_findings || COALESCE(jsonb_agg(f), '[]'::jsonb) INTO v_findings
    FROM (
      SELECT jsonb_build_object(
               'matched_on',  'phone',
               'person_kind', 'team_member',
               'person_id',   st.id,
               'full_name',   btrim(st.first_name || ' ' || coalesce(st.last_name, '')),
               'phone',       st.phone,
               'status',      CASE WHEN st.is_active THEN 'active' ELSE 'inactive' END,
               'team_code',   st.staff_id,
               'jkkn_id',     btrim(ji.jkkn_id)
             ) AS f
        FROM public.staff st
        LEFT JOIN public.jkkn_identities ji ON ji.team_member_id = st.id
       WHERE right(regexp_replace(coalesce(st.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone
       LIMIT 25
    ) s;
  END IF;

  IF jsonb_array_length(v_findings) > 0 THEN
    v_verdict := 'review';
  END IF;

  RETURN jsonb_build_object(
    'verdict',         v_verdict,
    'auto_merge',      false,
    'auto_merge_note', 'This guard never merges. Twins share a name and a birth date; merging on that evidence fuses two real people into one record.',
    'aadhaar_checked', v_aadhaar_checked,
    'aadhaar_note',    v_aadhaar_note,
    'checked',         jsonb_build_object(
                         'name_and_dob', (v_first <> '' AND p_dob IS NOT NULL),
                         'phone',        (v_phone IS NOT NULL)
                       ),
    'findings',        v_findings
  );
END;
$fn$;

COMMENT ON FUNCTION public.fn_check_duplicate_person(text, text, text, date, text) IS
  'Duplicate guard, run BEFORE a person is created. Returns a verdict plus the evidence behind it. NEVER merges anything and never will: twins share a name and a date of birth. Aadhaar is reported as unchecked because MyJKKN stores none.';

REVOKE EXECUTE ON FUNCTION public.fn_check_duplicate_person(text, text, text, date, text) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_check_duplicate_person(text, text, text, date, text) TO authenticated;

-- ---------------------------------------------------------------------
-- 3. fn_resolve_person — the universal resolver
-- ---------------------------------------------------------------------
-- Accepts whatever a human has in front of them: a JKKN ID, a roll
-- number, a Team Code, a university register number, an application
-- number, a name fragment, a phone or an email.
--
-- A JKKN ID is check-digit validated FIRST. A mistyped number is rejected
-- outright rather than searched for, because searching for it would
-- return nothing and "nothing" reads identically to "this person does not
-- exist" — which is the wrong answer to a typo.
--
-- SCOPE: this is SECURITY DEFINER, so it reads past RLS. It therefore
-- re-imposes the caller's own institution scope with
-- role_has_institution_access(), and says so in the payload
-- (scope_note) — a search box that silently hides half the cluster
-- teaches its user that people do not exist.
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_resolve_person(p_query text)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_q        text := btrim(coalesce(p_query, ''));
  v_lower    text;
  v_digits   text;
  v_phone    text;
  v_all      boolean;
  v_results  jsonb;
BEGIN
  IF NOT (
    COALESCE(public.is_super_admin(), false)
    OR public.is_admin()
    OR public.user_has_permission('users.jkkn_id.view')
  ) THEN
    RAISE EXCEPTION 'Not authorised to look people up'
      USING ERRCODE = '42501';
  END IF;

  v_all := COALESCE(public.is_super_admin(), false) OR public.is_admin();

  IF length(v_q) < 2 THEN
    RETURN jsonb_build_object(
      'query', v_q, 'ok', true, 'results', '[]'::jsonb,
      'note', 'Type at least two characters.'
    );
  END IF;

  v_lower  := lower(v_q);
  v_digits := regexp_replace(v_q, '[^0-9]', '', 'g');
  v_phone  := CASE WHEN length(v_digits) >= 10 THEN right(v_digits, 10) END;

  -- A JKKN ID that fails its check digit is a typo, and is reported as one.
  IF v_q ~ '^[0-9]{6}-[0-9]$' AND NOT public.fn_jkkn_id_validate(v_q) THEN
    RETURN jsonb_build_object(
      'query',   v_q,
      'ok',      false,
      'error',   'invalid_check_digit',
      'message', 'That is not a valid JKKN ID — the check digit does not match, so at least one digit is wrong. Read it again from the card rather than searching for it.',
      'results', '[]'::jsonb
    );
  END IF;

  WITH learner_hits AS (
    SELECT
      lp.id,
      CASE
        WHEN ji.jkkn_id IS NOT NULL AND btrim(ji.jkkn_id) = v_q         THEN 'jkkn_id'
        WHEN lower(btrim(coalesce(lp.roll_number, '')))      = v_lower   THEN 'roll_number'
        WHEN lower(btrim(coalesce(lp.register_number, '')))  = v_lower   THEN 'register_number'
        WHEN lower(btrim(coalesce(lp.application_id, '')))   = v_lower   THEN 'application_number'
        WHEN lower(btrim(coalesce(lp.neet_roll_number, ''))) = v_lower   THEN 'neet_roll'
        WHEN v_phone IS NOT NULL
             AND right(regexp_replace(coalesce(lp.student_mobile, ''), '[^0-9]', '', 'g'), 10) = v_phone
                                                                        THEN 'phone'
        WHEN lower(coalesce(lp.student_email, '')) = v_lower
          OR lower(coalesce(lp.college_email, '')) = v_lower             THEN 'email'
        WHEN EXISTS (
               SELECT 1 FROM public.jkkn_identity_aliases al
                WHERE al.jkkn_identity_id = ji.id
                  AND lower(btrim(al.alias_value)) = v_lower
             )                                                          THEN 'alias'
        ELSE 'name'
      END AS matched_on,
      lp.first_name, lp.last_name, lp.student_photo_url, lp.institution_id,
      -- Updated: 2026-08-14 (migration 20260819010000) — was lp.admission_year,
      -- which does not exist on learners_profiles and made every call raise
      -- 42703. The cohort lives behind admission_year_id.
      lp.program_id, ay.year AS admission_year, lp.lifecycle_status, lp.roll_number,
      lp.register_number, lp.application_id, ji.jkkn_id
    FROM public.learners_profiles lp
    LEFT JOIN public.jkkn_identities ji ON ji.learner_profile_id = lp.id
    -- LEFT, not inner: admission_year_id is nullable, and a learner whose
    -- cohort was never filled in must still be findable by name or roll
    -- number. They come back with a null admission_year, not absent.
    LEFT JOIN public.admission_years ay ON ay.id = lp.admission_year_id
    -- EXISTS, not a LEFT JOIN: two alias types can carry the same value
    -- (a roll number that is also a legacy number), and a join would then
    -- return the same person twice.
    WHERE (v_all OR public.role_has_institution_access(lp.institution_id))
      AND (
           (ji.jkkn_id IS NOT NULL AND btrim(ji.jkkn_id) = v_q)
        OR EXISTS (
             SELECT 1 FROM public.jkkn_identity_aliases al
              WHERE al.jkkn_identity_id = ji.id
                AND lower(btrim(al.alias_value)) = v_lower
           )
        OR lower(btrim(coalesce(lp.roll_number, '')))      = v_lower
        OR lower(btrim(coalesce(lp.register_number, '')))  = v_lower
        OR lower(btrim(coalesce(lp.application_id, '')))   = v_lower
        OR lower(btrim(coalesce(lp.neet_roll_number, ''))) = v_lower
        OR lower(coalesce(lp.student_email, ''))           = v_lower
        OR lower(coalesce(lp.college_email, ''))           = v_lower
        OR (v_phone IS NOT NULL
            AND right(regexp_replace(coalesce(lp.student_mobile, ''), '[^0-9]', '', 'g'), 10) = v_phone)
        OR lower(btrim(lp.first_name || ' ' || coalesce(lp.last_name, ''))) LIKE '%' || v_lower || '%'
      )
    LIMIT 25
  ),
  team_hits AS (
    SELECT
      st.id,
      CASE
        WHEN ji.jkkn_id IS NOT NULL AND btrim(ji.jkkn_id) = v_q      THEN 'jkkn_id'
        WHEN lower(btrim(coalesce(st.staff_id, '')))       = v_lower  THEN 'team_code'
        WHEN v_phone IS NOT NULL
             AND right(regexp_replace(coalesce(st.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone
                                                                      THEN 'phone'
        WHEN lower(coalesce(st.email, ''))             = v_lower
          OR lower(coalesce(st.institution_email, '')) = v_lower       THEN 'email'
        WHEN EXISTS (
               SELECT 1 FROM public.jkkn_identity_aliases al
                WHERE al.jkkn_identity_id = ji.id
                  AND lower(btrim(al.alias_value)) = v_lower
             )                                                        THEN 'alias'
        ELSE 'name'
      END AS matched_on,
      st.first_name, st.last_name, st.profile_picture, st.institution_id,
      st.designation, st.is_active, st.staff_id, ji.jkkn_id
    FROM public.staff st
    LEFT JOIN public.jkkn_identities ji ON ji.team_member_id = st.id
    WHERE (v_all OR public.role_has_institution_access(st.institution_id))
      AND (
           (ji.jkkn_id IS NOT NULL AND btrim(ji.jkkn_id) = v_q)
        OR EXISTS (
             SELECT 1 FROM public.jkkn_identity_aliases al
              WHERE al.jkkn_identity_id = ji.id
                AND lower(btrim(al.alias_value)) = v_lower
           )
        OR lower(btrim(coalesce(st.staff_id, ''))) = v_lower
        OR lower(coalesce(st.email, ''))             = v_lower
        OR lower(coalesce(st.institution_email, '')) = v_lower
        OR (v_phone IS NOT NULL
            AND right(regexp_replace(coalesce(st.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone)
        OR lower(btrim(st.first_name || ' ' || coalesce(st.last_name, ''))) LIKE '%' || v_lower || '%'
      )
    LIMIT 25
  ),
  -- Added 2026-08-27: profile-anchored identities (associates and external
  -- participants). INNER join to jkkn_identities on purpose — a profile is
  -- only findable here once it holds a register row, so a name search does
  -- not flood with every account in the cluster.
  associate_hits AS (
    SELECT
      p.id,
      CASE
        WHEN btrim(ji.jkkn_id) = v_q                  THEN 'jkkn_id'
        WHEN lower(coalesce(p.email, '')) = v_lower   THEN 'email'
        WHEN EXISTS (
               SELECT 1 FROM public.jkkn_identity_aliases al
                WHERE al.jkkn_identity_id = ji.id
                  AND lower(btrim(al.alias_value)) = v_lower
             )                                        THEN 'alias'
        ELSE 'name'
      END AS matched_on,
      p.full_name, p.avatar_url, p.institution_id,
      ji.person_kind, ji.jkkn_id
    FROM public.profiles p
    JOIN public.jkkn_identities ji ON ji.profile_id = p.id
    WHERE ji.person_kind IN ('associate', 'external_participant')
      AND (v_all OR public.role_has_institution_access(p.institution_id))
      AND (
           btrim(ji.jkkn_id) = v_q
        OR EXISTS (
             SELECT 1 FROM public.jkkn_identity_aliases al
              WHERE al.jkkn_identity_id = ji.id
                AND lower(btrim(al.alias_value)) = v_lower
           )
        OR lower(coalesce(p.email, '')) = v_lower
        OR lower(coalesce(p.full_name, '')) LIKE '%' || v_lower || '%'
      )
    LIMIT 25
  ),
  merged AS (
    SELECT jsonb_build_object(
             'person_kind',      'learner',
             'person_id',        lh.id,
             'matched_on',       lh.matched_on,
             'full_name',        btrim(lh.first_name || ' ' || coalesce(lh.last_name, '')),
             'photo_url',        lh.student_photo_url,
             'institution_name', i.name,
             'programme',        pr.program_name,
             'admission_year',   lh.admission_year,
             'status',           lh.lifecycle_status::text,
             'jkkn_id',          btrim(lh.jkkn_id),
             'roll_number',      lh.roll_number,
             'register_number',  lh.register_number,
             'application_number', lh.application_id
           ) AS row_json
      FROM learner_hits lh
      LEFT JOIN public.institutions i ON i.id = lh.institution_id
      LEFT JOIN public.programs    pr ON pr.id = lh.program_id
    UNION ALL
    SELECT jsonb_build_object(
             'person_kind',      'team_member',
             'person_id',        th.id,
             'matched_on',       th.matched_on,
             'full_name',        btrim(th.first_name || ' ' || coalesce(th.last_name, '')),
             'photo_url',        th.profile_picture,
             'institution_name', i.name,
             'programme',        th.designation,
             'admission_year',   NULL,
             'status',           CASE WHEN th.is_active THEN 'active' ELSE 'inactive' END,
             'jkkn_id',          btrim(th.jkkn_id),
             'team_code',        th.staff_id
           ) AS row_json
      FROM team_hits th
      LEFT JOIN public.institutions i ON i.id = th.institution_id
    UNION ALL
    SELECT jsonb_build_object(
             'person_kind',      ah.person_kind,
             'person_id',        ah.id,
             'matched_on',       ah.matched_on,
             'full_name',        coalesce(btrim(ah.full_name), 'Name unavailable'),
             'photo_url',        ah.avatar_url,
             'institution_name', i.name,
             'programme',        NULL,
             'admission_year',   NULL,
             'status',           NULL,
             'jkkn_id',          btrim(ah.jkkn_id)
           ) AS row_json
      FROM associate_hits ah
      LEFT JOIN public.institutions i ON i.id = ah.institution_id
  )
  SELECT COALESCE(jsonb_agg(row_json), '[]'::jsonb) INTO v_results FROM merged;

  RETURN jsonb_build_object(
    'query',      v_q,
    'ok',         true,
    'results',    v_results,
    'count',      jsonb_array_length(v_results),
    'scope_note', CASE
                    WHEN v_all THEN 'Searched every institution.'
                    ELSE 'Searched only the institutions your role can see. Someone you cannot find here may exist elsewhere in the cluster.'
                  END
  );
END;
$fn$;

COMMENT ON FUNCTION public.fn_resolve_person(text) IS
  'Universal person lookup: JKKN ID, roll number, Team Code, register number, application number, name fragment, phone or email. Validates a JKKN ID check digit before searching so a typo is reported as a typo instead of as an absent person. Institution-scoped to the caller and says so in scope_note. Reads the admission year through learners_profiles.admission_year_id -> admission_years.year. Third branch (2026-08-27) surfaces profile-anchored identities: associates and external participants.';

REVOKE EXECUTE ON FUNCTION public.fn_resolve_person(text) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_resolve_person(text) TO authenticated;

-- ---------------------------------------------------------------------
-- 4. Auto-issue trigger functions (2026-08-27)
-- ---------------------------------------------------------------------
-- Mirrors migration 20260827110000_jkkn_id_associate_kind_and_auto_issue.sql.
-- The register originally shipped for deliberate one-at-a-time issuance; on
-- 2026-08-27 issuance was switched on and AUTOMATED — a recorded design
-- shift. The triggers carry NO permission gate on purpose: the write that
-- fires them (an admission, a hire, a role grant) is itself the authorised
-- act. All three are SECURITY DEFINER (their guard reads must see the whole
-- register regardless of the session) and fail-soft (EXCEPTION → WARNING,
-- never a failed parent write). The matching CREATE TRIGGER statements live
-- in 04_triggers.sql.
--
-- THE ONE UNRECOVERABLE ERROR is one person holding two numbers (rows can
-- only be retired, never deleted). The learner and staff triggers therefore
-- run the same overlap rule as scripts/backfill-jkkn-ids.ts before minting:
-- an exact normalised-email match against the other kind UPGRADES the
-- existing row to person_kind='both'; an ambiguous match (2+) skips with a
-- WARNING for a human to resolve.

-- 4a. Learner reaches admitted/active.
CREATE OR REPLACE FUNCTION public.tg_jkkn_auto_issue_learner()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_emails   text[];
  v_match_id uuid;
  v_matches  int;
BEGIN
  -- Already holds a number (retired still counts as held — the remedy for a
  -- retired identity is a human decision, not a fresh mint).
  IF EXISTS (SELECT 1 FROM public.jkkn_identities WHERE learner_profile_id = NEW.id) THEN
    RETURN NULL;
  END IF;

  -- The two-numbers guard: does a TEAM-MEMBER identity already exist for this
  -- same human? Exact normalised email match, nothing weaker (phone can be a
  -- parent; name+DOB can be twins).
  v_emails := ARRAY(
    SELECT lower(btrim(e)) FROM unnest(ARRAY[NEW.student_email, NEW.college_email]) AS e
     WHERE e IS NOT NULL AND btrim(e) <> ''
  );

  IF array_length(v_emails, 1) IS NOT NULL THEN
    SELECT count(*), min(ji.id::text)::uuid
      INTO v_matches, v_match_id
      FROM public.jkkn_identities ji
      JOIN public.staff st ON st.id = ji.team_member_id
     WHERE ji.learner_profile_id IS NULL
       AND (lower(btrim(coalesce(st.institution_email, ''))) = ANY (v_emails)
         OR lower(btrim(coalesce(st.email, '')))             = ANY (v_emails));

    IF v_matches = 1 THEN
      UPDATE public.jkkn_identities
         SET learner_profile_id = NEW.id, person_kind = 'both'
       WHERE id = v_match_id;
      RETURN NULL;
    ELSIF v_matches > 1 THEN
      RAISE WARNING '[jkkn auto-issue] learner % matches % team-member identities by email — skipped, needs a human', NEW.id, v_matches;
      RETURN NULL;
    END IF;
  END IF;

  PERFORM public.fn_jkkn_allocate('learner', NEW.id, NULL, NULL, NULL);
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[jkkn auto-issue] learner % failed: %', NEW.id, SQLERRM;
  RETURN NULL;
END;
$fn$;

REVOKE ALL ON FUNCTION public.tg_jkkn_auto_issue_learner() FROM anon, authenticated, PUBLIC;

-- 4b. Team member created active, or activated.
CREATE OR REPLACE FUNCTION public.tg_jkkn_auto_issue_team_member()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_emails   text[];
  v_match_id uuid;
  v_matches  int;
BEGIN
  IF EXISTS (SELECT 1 FROM public.jkkn_identities WHERE team_member_id = NEW.id) THEN
    RETURN NULL;
  END IF;

  -- Mirror of the learner guard: an existing LEARNER identity for the same
  -- email is upgraded to 'both', never joined by a second number.
  v_emails := ARRAY(
    SELECT lower(btrim(e)) FROM unnest(ARRAY[NEW.institution_email, NEW.email]) AS e
     WHERE e IS NOT NULL AND btrim(e) <> ''
  );

  IF array_length(v_emails, 1) IS NOT NULL THEN
    SELECT count(*), min(ji.id::text)::uuid
      INTO v_matches, v_match_id
      FROM public.jkkn_identities ji
      JOIN public.learners_profiles lp ON lp.id = ji.learner_profile_id
     WHERE ji.team_member_id IS NULL
       AND (lower(btrim(coalesce(lp.student_email, ''))) = ANY (v_emails)
         OR lower(btrim(coalesce(lp.college_email, ''))) = ANY (v_emails));

    IF v_matches = 1 THEN
      UPDATE public.jkkn_identities
         SET team_member_id = NEW.id, person_kind = 'both'
       WHERE id = v_match_id;
      RETURN NULL;
    ELSIF v_matches > 1 THEN
      RAISE WARNING '[jkkn auto-issue] team member % matches % learner identities by email — skipped, needs a human', NEW.id, v_matches;
      RETURN NULL;
    END IF;
  END IF;

  PERFORM public.fn_jkkn_allocate('team_member', NULL, NEW.id, NULL, NULL);
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[jkkn auto-issue] team member % failed: %', NEW.id, SQLERRM;
  RETURN NULL;
END;
$fn$;

REVOKE ALL ON FUNCTION public.tg_jkkn_auto_issue_team_member() FROM anon, authenticated, PUBLIC;

-- 4c. Custom role granted to a profile-only user → 'associate'.
CREATE OR REPLACE FUNCTION public.tg_jkkn_auto_issue_associate()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_profile record;
BEGIN
  SELECT id, email, learner_id INTO v_profile
    FROM public.profiles WHERE id = NEW.user_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- The learner and team-member lanes own issuance for their people: a
  -- learner-linked profile is issued at admission, and a profile whose email
  -- belongs to a staff row is issued at hire/activation (even if that staff
  -- row is inactive today).
  IF v_profile.learner_id IS NOT NULL THEN
    RETURN NULL;
  END IF;
  IF v_profile.email IS NOT NULL AND btrim(v_profile.email) <> '' AND EXISTS (
    SELECT 1 FROM public.staff st
     WHERE lower(btrim(coalesce(st.institution_email, ''))) = lower(btrim(v_profile.email))
        OR lower(btrim(coalesce(st.email, '')))             = lower(btrim(v_profile.email))
  ) THEN
    RETURN NULL;
  END IF;

  IF EXISTS (SELECT 1 FROM public.jkkn_identities WHERE profile_id = v_profile.id) THEN
    RETURN NULL;
  END IF;

  PERFORM public.fn_jkkn_allocate('associate', NULL, NULL, v_profile.id, NULL);
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[jkkn auto-issue] associate (profile %) failed: %', NEW.user_id, SQLERRM;
  RETURN NULL;
END;
$fn$;

REVOKE ALL ON FUNCTION public.tg_jkkn_auto_issue_associate() FROM anon, authenticated, PUBLIC;

-- ---------------------------------------------------------------------
-- 5. fn_jkkn_directory — paginated, filterable person directory (2026-08-27)
-- ---------------------------------------------------------------------
-- Mirrors migration 20260827120000_jkkn_directory_rpc.sql. Backs the
-- default browsable table on /users/jkkn-id: one kind per call
-- (learner | team_member | associate), gated on users.jkkn_id.view like
-- fn_resolve_person, institution-scoped for non-admins. Sort keys are
-- whitelisted, the limit clamps to 1..100, and the page clamps to the
-- last page so narrowing a filter mid-list never blanks the table.
CREATE OR REPLACE FUNCTION public.fn_jkkn_directory(
  p_kind           text DEFAULT 'learner',
  p_institution_id uuid DEFAULT NULL,
  p_status         text DEFAULT NULL,
  p_issued         text DEFAULT NULL,   -- 'issued' | 'not_issued' | NULL = any
  p_admission_year int  DEFAULT NULL,   -- learners only
  p_search         text DEFAULT NULL,
  p_sort_by        text DEFAULT 'name',
  p_sort_order     text DEFAULT 'asc',
  p_page           int  DEFAULT 1,
  p_limit          int  DEFAULT 25
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_all    boolean;
  v_q      text := lower(btrim(coalesce(p_search, '')));
  v_sort   text;
  v_desc   boolean := lower(coalesce(p_sort_order, 'asc')) = 'desc';
  v_limit  int := LEAST(GREATEST(coalesce(p_limit, 25), 1), 100);
  v_total  bigint;
  v_pages  int;
  v_page   int;
  v_rows   jsonb;
BEGIN
  -- Gate + scope: identical to fn_resolve_person.
  IF NOT (
    COALESCE(public.is_super_admin(), false)
    OR public.is_admin()
    OR public.user_has_permission('users.jkkn_id.view')
  ) THEN
    RAISE EXCEPTION 'Not authorised to look people up'
      USING ERRCODE = '42501';
  END IF;

  v_all := COALESCE(public.is_super_admin(), false) OR public.is_admin();

  IF p_kind IS NULL OR p_kind NOT IN ('learner', 'team_member', 'associate') THEN
    RAISE EXCEPTION 'kind must be learner, team_member or associate (got %)', p_kind
      USING ERRCODE = '22023';
  END IF;

  -- Sort whitelist. Anything unknown falls back to name rather than erroring —
  -- a stale bookmark should degrade, not 400.
  v_sort := CASE
    WHEN p_sort_by IN ('name', 'jkkn_id', 'code', 'status', 'admission_year') THEN p_sort_by
    ELSE 'name'
  END;

  IF p_kind = 'learner' THEN
    SELECT count(*) INTO v_total
      FROM public.learners_profiles lp
      LEFT JOIN public.jkkn_identities ji ON ji.learner_profile_id = lp.id
      LEFT JOIN public.admission_years ay ON ay.id = lp.admission_year_id
     WHERE (v_all OR public.role_has_institution_access(lp.institution_id))
       AND (p_institution_id IS NULL OR lp.institution_id = p_institution_id)
       AND (p_status IS NULL OR lp.lifecycle_status::text = p_status)
       AND (p_admission_year IS NULL OR ay.year = p_admission_year)
       AND (p_issued IS NULL
            OR (p_issued = 'issued'     AND ji.jkkn_id IS NOT NULL)
            OR (p_issued = 'not_issued' AND ji.jkkn_id IS NULL))
       AND (v_q = ''
            OR lower(btrim(lp.first_name || ' ' || coalesce(lp.last_name, ''))) LIKE '%' || v_q || '%'
            OR lower(btrim(coalesce(lp.roll_number, '')))     LIKE '%' || v_q || '%'
            OR lower(btrim(coalesce(lp.register_number, ''))) LIKE '%' || v_q || '%'
            OR btrim(coalesce(ji.jkkn_id, '')) = btrim(coalesce(p_search, '')));

    v_pages := GREATEST(1, CEIL(v_total::numeric / v_limit)::int);
    v_page  := LEAST(GREATEST(coalesce(p_page, 1), 1), v_pages);

    SELECT COALESCE(jsonb_agg(row_json), '[]'::jsonb) INTO v_rows FROM (
      SELECT jsonb_build_object(
               'id',               lp.id,
               'kind',             'learner',
               'name',             btrim(lp.first_name || ' ' || coalesce(lp.last_name, '')),
               'photo_url',        lp.student_photo_url,
               'email',            NULL,
               'jkkn_id',          btrim(ji.jkkn_id),
               'roll_number',      lp.roll_number,
               'register_number',  lp.register_number,
               'team_code',        NULL,
               'designation',      NULL,
               'program',          pr.program_name,
               'institution_name', i.name,
               'admission_year',   ay.year,
               'status',           lp.lifecycle_status::text
             ) AS row_json
        FROM public.learners_profiles lp
        LEFT JOIN public.jkkn_identities ji ON ji.learner_profile_id = lp.id
        LEFT JOIN public.admission_years ay ON ay.id = lp.admission_year_id
        LEFT JOIN public.institutions    i  ON i.id  = lp.institution_id
        LEFT JOIN public.programs        pr ON pr.id = lp.program_id
       WHERE (v_all OR public.role_has_institution_access(lp.institution_id))
         AND (p_institution_id IS NULL OR lp.institution_id = p_institution_id)
         AND (p_status IS NULL OR lp.lifecycle_status::text = p_status)
         AND (p_admission_year IS NULL OR ay.year = p_admission_year)
         AND (p_issued IS NULL
              OR (p_issued = 'issued'     AND ji.jkkn_id IS NOT NULL)
              OR (p_issued = 'not_issued' AND ji.jkkn_id IS NULL))
         AND (v_q = ''
              OR lower(btrim(lp.first_name || ' ' || coalesce(lp.last_name, ''))) LIKE '%' || v_q || '%'
              OR lower(btrim(coalesce(lp.roll_number, '')))     LIKE '%' || v_q || '%'
              OR lower(btrim(coalesce(lp.register_number, ''))) LIKE '%' || v_q || '%'
              OR btrim(coalesce(ji.jkkn_id, '')) = btrim(coalesce(p_search, '')))
       ORDER BY
         (CASE WHEN NOT v_desc THEN
            CASE v_sort
              WHEN 'name'           THEN lower(btrim(lp.first_name || ' ' || coalesce(lp.last_name, '')))
              WHEN 'jkkn_id'        THEN btrim(ji.jkkn_id)
              WHEN 'code'           THEN lower(btrim(coalesce(lp.roll_number, '')))
              WHEN 'status'         THEN lp.lifecycle_status::text
              WHEN 'admission_year' THEN lpad(coalesce(ay.year, 0)::text, 6, '0')
            END
          END) ASC NULLS LAST,
         (CASE WHEN v_desc THEN
            CASE v_sort
              WHEN 'name'           THEN lower(btrim(lp.first_name || ' ' || coalesce(lp.last_name, '')))
              WHEN 'jkkn_id'        THEN btrim(ji.jkkn_id)
              WHEN 'code'           THEN lower(btrim(coalesce(lp.roll_number, '')))
              WHEN 'status'         THEN lp.lifecycle_status::text
              WHEN 'admission_year' THEN lpad(coalesce(ay.year, 0)::text, 6, '0')
            END
          END) DESC NULLS LAST,
         lp.id
       LIMIT v_limit OFFSET (v_page - 1) * v_limit
    ) page_rows;

  ELSIF p_kind = 'team_member' THEN
    SELECT count(*) INTO v_total
      FROM public.staff st
      LEFT JOIN public.jkkn_identities ji ON ji.team_member_id = st.id
     WHERE (v_all OR public.role_has_institution_access(st.institution_id))
       AND (p_institution_id IS NULL OR st.institution_id = p_institution_id)
       AND (p_status IS NULL
            OR (p_status = 'active'   AND st.is_active IS TRUE)
            OR (p_status = 'inactive' AND st.is_active IS NOT TRUE))
       AND (p_issued IS NULL
            OR (p_issued = 'issued'     AND ji.jkkn_id IS NOT NULL)
            OR (p_issued = 'not_issued' AND ji.jkkn_id IS NULL))
       AND (v_q = ''
            OR lower(btrim(st.first_name || ' ' || coalesce(st.last_name, ''))) LIKE '%' || v_q || '%'
            OR lower(btrim(coalesce(st.staff_id, ''))) LIKE '%' || v_q || '%'
            OR lower(coalesce(st.email, ''))             LIKE '%' || v_q || '%'
            OR lower(coalesce(st.institution_email, '')) LIKE '%' || v_q || '%'
            OR btrim(coalesce(ji.jkkn_id, '')) = btrim(coalesce(p_search, '')));

    v_pages := GREATEST(1, CEIL(v_total::numeric / v_limit)::int);
    v_page  := LEAST(GREATEST(coalesce(p_page, 1), 1), v_pages);

    SELECT COALESCE(jsonb_agg(row_json), '[]'::jsonb) INTO v_rows FROM (
      SELECT jsonb_build_object(
               'id',               st.id,
               'kind',             'team_member',
               'name',             btrim(st.first_name || ' ' || coalesce(st.last_name, '')),
               'photo_url',        st.profile_picture,
               'email',            coalesce(st.institution_email, st.email),
               'jkkn_id',          btrim(ji.jkkn_id),
               'roll_number',      NULL,
               'register_number',  NULL,
               'team_code',        st.staff_id,
               'designation',      st.designation,
               'program',          NULL,
               'institution_name', i.name,
               'admission_year',   NULL,
               'status',           CASE WHEN st.is_active THEN 'active' ELSE 'inactive' END
             ) AS row_json
        FROM public.staff st
        LEFT JOIN public.jkkn_identities ji ON ji.team_member_id = st.id
        LEFT JOIN public.institutions    i  ON i.id = st.institution_id
       WHERE (v_all OR public.role_has_institution_access(st.institution_id))
         AND (p_institution_id IS NULL OR st.institution_id = p_institution_id)
         AND (p_status IS NULL
              OR (p_status = 'active'   AND st.is_active IS TRUE)
              OR (p_status = 'inactive' AND st.is_active IS NOT TRUE))
         AND (p_issued IS NULL
              OR (p_issued = 'issued'     AND ji.jkkn_id IS NOT NULL)
              OR (p_issued = 'not_issued' AND ji.jkkn_id IS NULL))
         AND (v_q = ''
              OR lower(btrim(st.first_name || ' ' || coalesce(st.last_name, ''))) LIKE '%' || v_q || '%'
              OR lower(btrim(coalesce(st.staff_id, ''))) LIKE '%' || v_q || '%'
              OR lower(coalesce(st.email, ''))             LIKE '%' || v_q || '%'
              OR lower(coalesce(st.institution_email, '')) LIKE '%' || v_q || '%'
              OR btrim(coalesce(ji.jkkn_id, '')) = btrim(coalesce(p_search, '')))
       ORDER BY
         (CASE WHEN NOT v_desc THEN
            CASE v_sort
              WHEN 'name'    THEN lower(btrim(st.first_name || ' ' || coalesce(st.last_name, '')))
              WHEN 'jkkn_id' THEN btrim(ji.jkkn_id)
              WHEN 'code'    THEN lower(btrim(coalesce(st.staff_id, '')))
              WHEN 'status'  THEN CASE WHEN st.is_active THEN 'active' ELSE 'inactive' END
              ELSE lower(btrim(st.first_name || ' ' || coalesce(st.last_name, '')))
            END
          END) ASC NULLS LAST,
         (CASE WHEN v_desc THEN
            CASE v_sort
              WHEN 'name'    THEN lower(btrim(st.first_name || ' ' || coalesce(st.last_name, '')))
              WHEN 'jkkn_id' THEN btrim(ji.jkkn_id)
              WHEN 'code'    THEN lower(btrim(coalesce(st.staff_id, '')))
              WHEN 'status'  THEN CASE WHEN st.is_active THEN 'active' ELSE 'inactive' END
              ELSE lower(btrim(st.first_name || ' ' || coalesce(st.last_name, '')))
            END
          END) DESC NULLS LAST,
         st.id
       LIMIT v_limit OFFSET (v_page - 1) * v_limit
    ) page_rows;

  ELSE
    -- Associates and external participants exist in the directory only through
    -- the register (INNER join), so the 'not_issued' filter is empty here by
    -- construction.
    SELECT count(*) INTO v_total
      FROM public.profiles p
      JOIN public.jkkn_identities ji ON ji.profile_id = p.id
     WHERE ji.person_kind IN ('associate', 'external_participant')
       AND (v_all OR public.role_has_institution_access(p.institution_id))
       AND (p_institution_id IS NULL OR p.institution_id = p_institution_id)
       AND (p_issued IS NULL OR p_issued = 'issued')
       AND (v_q = ''
            OR lower(coalesce(p.full_name, '')) LIKE '%' || v_q || '%'
            OR lower(coalesce(p.email, ''))     LIKE '%' || v_q || '%'
            OR btrim(ji.jkkn_id) = btrim(coalesce(p_search, '')));

    v_pages := GREATEST(1, CEIL(v_total::numeric / v_limit)::int);
    v_page  := LEAST(GREATEST(coalesce(p_page, 1), 1), v_pages);

    SELECT COALESCE(jsonb_agg(row_json), '[]'::jsonb) INTO v_rows FROM (
      SELECT jsonb_build_object(
               'id',               p.id,
               'kind',             ji.person_kind,
               'name',             coalesce(btrim(p.full_name), 'Name unavailable'),
               'photo_url',        p.avatar_url,
               'email',            p.email,
               'jkkn_id',          btrim(ji.jkkn_id),
               'roll_number',      NULL,
               'register_number',  NULL,
               'team_code',        NULL,
               'designation',      NULL,
               'program',          NULL,
               'institution_name', i.name,
               'admission_year',   NULL,
               'status',           NULL
             ) AS row_json
        FROM public.profiles p
        JOIN public.jkkn_identities ji ON ji.profile_id = p.id
        LEFT JOIN public.institutions i ON i.id = p.institution_id
       WHERE ji.person_kind IN ('associate', 'external_participant')
         AND (v_all OR public.role_has_institution_access(p.institution_id))
         AND (p_institution_id IS NULL OR p.institution_id = p_institution_id)
         AND (p_issued IS NULL OR p_issued = 'issued')
         AND (v_q = ''
              OR lower(coalesce(p.full_name, '')) LIKE '%' || v_q || '%'
              OR lower(coalesce(p.email, ''))     LIKE '%' || v_q || '%'
              OR btrim(ji.jkkn_id) = btrim(coalesce(p_search, '')))
       ORDER BY
         (CASE WHEN NOT v_desc THEN
            CASE v_sort
              WHEN 'jkkn_id' THEN btrim(ji.jkkn_id)
              ELSE lower(coalesce(p.full_name, ''))
            END
          END) ASC NULLS LAST,
         (CASE WHEN v_desc THEN
            CASE v_sort
              WHEN 'jkkn_id' THEN btrim(ji.jkkn_id)
              ELSE lower(coalesce(p.full_name, ''))
            END
          END) DESC NULLS LAST,
         p.id
       LIMIT v_limit OFFSET (v_page - 1) * v_limit
    ) page_rows;
  END IF;

  RETURN jsonb_build_object(
    'ok',          true,
    'rows',        v_rows,
    'total',       v_total,
    'page',        v_page,
    'limit',       v_limit,
    'total_pages', v_pages
  );
END;
$fn$;

COMMENT ON FUNCTION public.fn_jkkn_directory(text, uuid, text, text, int, text, text, text, int, int) IS
  'Paginated, filterable person directory behind /users/jkkn-id. One kind per call (learner | team_member | associate). Gated on users.jkkn_id.view like fn_resolve_person; non-admins are institution-scoped via role_has_institution_access. Sort keys whitelisted, limit clamped to 100, page clamped to the last page.';

REVOKE EXECUTE ON FUNCTION public.fn_jkkn_directory(text, uuid, text, text, int, text, text, text, int, int) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_jkkn_directory(text, uuid, text, text, int, text, text, text, int, int) TO authenticated;

-- ---------------------------------------------------------------------
-- 6. fn_jkkn_stats + fn_jkkn_issue_manual (2026-08-27)
-- ---------------------------------------------------------------------
-- Mirrors migration 20260827150000_jkkn_stats_and_manual_issue.sql.
-- Stats: kind-wise issued/pending for the /users/jkkn-id analytics cards
-- (gated on users.jkkn_id.view; learner/team/associate counts scoped for
-- non-admins; learners.review = the phone-overlap withheld set).
-- Manual issue: the "Issue ID" button, gated on users.jkkn_id.issue,
-- carrying the SAME email guard as the auto-issue triggers — an exact
-- match to an unlinked other-kind identity LINKS it (person_kind='both')
-- rather than minting a duplicate; ambiguous matches raise.
CREATE OR REPLACE FUNCTION public.fn_jkkn_stats()
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_all       boolean;
  v_learners  jsonb;
  v_team      jsonb;
  v_assoc     jsonb;
  v_register  jsonb;
BEGIN
  IF NOT (
    COALESCE(public.is_super_admin(), false)
    OR public.is_admin()
    OR public.user_has_permission('users.jkkn_id.view')
  ) THEN
    RAISE EXCEPTION 'Not authorised to look people up'
      USING ERRCODE = '42501';
  END IF;

  v_all := COALESCE(public.is_super_admin(), false) OR public.is_admin();

  SELECT jsonb_build_object(
           'eligible', count(*),
           'issued',   count(*) FILTER (WHERE ji.id IS NOT NULL),
           'pending',  count(*) FILTER (WHERE ji.id IS NULL),
           'review',   count(*) FILTER (WHERE ji.id IS NULL AND EXISTS (
             SELECT 1
               FROM public.jkkn_identities j2
               JOIN public.staff st ON st.id = j2.team_member_id
              WHERE j2.learner_profile_id IS NULL
                AND right(regexp_replace(coalesce(st.phone, ''), '[^0-9]', '', 'g'), 10)
                    = NULLIF(right(regexp_replace(coalesce(lp.student_mobile, ''), '[^0-9]', '', 'g'), 10), '')
           ))
         )
    INTO v_learners
    FROM public.learners_profiles lp
    LEFT JOIN public.jkkn_identities ji ON ji.learner_profile_id = lp.id
   WHERE lp.lifecycle_status::text IN ('reserved', 'account', 'admitted', 'active', 'graduated', 'alumni')
     AND (v_all OR public.role_has_institution_access(lp.institution_id));

  SELECT jsonb_build_object(
           'eligible', count(*),
           'issued',   count(*) FILTER (WHERE ji.id IS NOT NULL),
           'pending',  count(*) FILTER (WHERE ji.id IS NULL)
         )
    INTO v_team
    FROM public.staff st
    LEFT JOIN public.jkkn_identities ji ON ji.team_member_id = st.id
   WHERE st.is_active IS TRUE
     AND (v_all OR public.role_has_institution_access(st.institution_id));

  -- Associates: custom-role holders who are neither learner-linked nor
  -- matched by email to any staff row (those belong to the other lanes).
  SELECT jsonb_build_object(
           'eligible', count(*),
           'issued',   count(*) FILTER (WHERE ji.id IS NOT NULL),
           'pending',  count(*) FILTER (WHERE ji.id IS NULL)
         )
    INTO v_assoc
    FROM (SELECT DISTINCT ur.user_id FROM public.user_roles ur) ur
    JOIN public.profiles p ON p.id = ur.user_id
    LEFT JOIN public.jkkn_identities ji ON ji.profile_id = p.id
   WHERE p.learner_id IS NULL
     AND NOT EXISTS (
       SELECT 1 FROM public.staff st
        WHERE NULLIF(lower(btrim(coalesce(p.email, ''))), '') IS NOT NULL
          AND (lower(btrim(coalesce(st.institution_email, ''))) = lower(btrim(p.email))
            OR lower(btrim(coalesce(st.email, '')))             = lower(btrim(p.email)))
     )
     AND (v_all OR public.role_has_institution_access(p.institution_id));

  SELECT jsonb_build_object(
           'total',                 count(*),
           'both',                  count(*) FILTER (WHERE person_kind = 'both'),
           'external_participants', count(*) FILTER (WHERE person_kind = 'external_participant'),
           'retired',               count(*) FILTER (WHERE retired_at IS NOT NULL)
         )
    INTO v_register
    FROM public.jkkn_identities;

  RETURN jsonb_build_object(
    'ok',           true,
    'learners',     v_learners,
    'team_members', v_team,
    'associates',   v_assoc,
    'register',     v_register
  );
END;
$fn$;

COMMENT ON FUNCTION public.fn_jkkn_stats() IS
  'Kind-wise issued/pending counts for the /users/jkkn-id analytics cards. Gated on users.jkkn_id.view; learner/team/associate counts are institution-scoped for non-admins; register totals are global. learners.review = unissued learners phone-matching an unlinked team-member identity (the withheld human-review set).';

REVOKE EXECUTE ON FUNCTION public.fn_jkkn_stats() FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_jkkn_stats() TO authenticated;

CREATE OR REPLACE FUNCTION public.fn_jkkn_issue_manual(
  p_kind   text,
  p_ref_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_existing text;
  v_emails   text[];
  v_matches  int;
  v_match_id uuid;
  v_number   text;
  v_result   jsonb;
BEGIN
  IF NOT (
    COALESCE(public.is_super_admin(), false)
    OR public.is_admin()
    OR public.user_has_permission('users.jkkn_id.issue')
  ) THEN
    RAISE EXCEPTION 'Not authorised to issue a JKKN ID'
      USING ERRCODE = '42501';
  END IF;

  IF p_kind IS NULL OR p_kind NOT IN ('learner', 'team_member', 'associate') THEN
    RAISE EXCEPTION 'kind must be learner, team_member or associate (got %)', p_kind
      USING ERRCODE = '22023';
  END IF;
  IF p_ref_id IS NULL THEN
    RAISE EXCEPTION 'p_ref_id is required' USING ERRCODE = '22023';
  END IF;

  IF p_kind = 'learner' THEN
    IF NOT EXISTS (SELECT 1 FROM public.learners_profiles WHERE id = p_ref_id) THEN
      RAISE EXCEPTION 'No learner profile %', p_ref_id USING ERRCODE = '23503';
    END IF;

    SELECT btrim(jkkn_id) INTO v_existing
      FROM public.jkkn_identities WHERE learner_profile_id = p_ref_id LIMIT 1;
    IF v_existing IS NOT NULL THEN
      RETURN jsonb_build_object('ok', true, 'action', 'already_held', 'jkkn_id', v_existing);
    END IF;

    SELECT ARRAY(
             SELECT lower(btrim(e))
               FROM unnest(ARRAY[lp.student_email, lp.college_email]) AS e
              WHERE e IS NOT NULL AND btrim(e) <> ''
           )
      INTO v_emails
      FROM public.learners_profiles lp WHERE lp.id = p_ref_id;

    v_matches := 0; v_match_id := NULL;
    IF array_length(v_emails, 1) IS NOT NULL THEN
      SELECT count(*), min(ji.id::text)::uuid INTO v_matches, v_match_id
        FROM public.jkkn_identities ji
        JOIN public.staff st ON st.id = ji.team_member_id
       WHERE ji.learner_profile_id IS NULL
         AND (lower(btrim(coalesce(st.institution_email, ''))) = ANY (v_emails)
           OR lower(btrim(coalesce(st.email, '')))             = ANY (v_emails));
    END IF;

    IF v_matches = 1 THEN
      UPDATE public.jkkn_identities
         SET learner_profile_id = p_ref_id, person_kind = 'both'
       WHERE id = v_match_id
       RETURNING btrim(jkkn_id) INTO v_number;
      RETURN jsonb_build_object('ok', true, 'action', 'linked_existing', 'jkkn_id', v_number);
    ELSIF v_matches > 1 THEN
      RAISE EXCEPTION 'This learner''s email matches % existing team-member identities — resolve which one is the same person before issuing.', v_matches
        USING ERRCODE = '23505';
    END IF;

    v_result := public.fn_jkkn_allocate('learner', p_ref_id, NULL, NULL, auth.uid());

  ELSIF p_kind = 'team_member' THEN
    IF NOT EXISTS (SELECT 1 FROM public.staff WHERE id = p_ref_id) THEN
      RAISE EXCEPTION 'No team member %', p_ref_id USING ERRCODE = '23503';
    END IF;

    SELECT btrim(jkkn_id) INTO v_existing
      FROM public.jkkn_identities WHERE team_member_id = p_ref_id LIMIT 1;
    IF v_existing IS NOT NULL THEN
      RETURN jsonb_build_object('ok', true, 'action', 'already_held', 'jkkn_id', v_existing);
    END IF;

    SELECT ARRAY(
             SELECT lower(btrim(e))
               FROM unnest(ARRAY[st.institution_email, st.email]) AS e
              WHERE e IS NOT NULL AND btrim(e) <> ''
           )
      INTO v_emails
      FROM public.staff st WHERE st.id = p_ref_id;

    v_matches := 0; v_match_id := NULL;
    IF array_length(v_emails, 1) IS NOT NULL THEN
      SELECT count(*), min(ji.id::text)::uuid INTO v_matches, v_match_id
        FROM public.jkkn_identities ji
        JOIN public.learners_profiles lp ON lp.id = ji.learner_profile_id
       WHERE ji.team_member_id IS NULL
         AND (lower(btrim(coalesce(lp.student_email, ''))) = ANY (v_emails)
           OR lower(btrim(coalesce(lp.college_email, ''))) = ANY (v_emails));
    END IF;

    IF v_matches = 1 THEN
      UPDATE public.jkkn_identities
         SET team_member_id = p_ref_id, person_kind = 'both'
       WHERE id = v_match_id
       RETURNING btrim(jkkn_id) INTO v_number;
      RETURN jsonb_build_object('ok', true, 'action', 'linked_existing', 'jkkn_id', v_number);
    ELSIF v_matches > 1 THEN
      RAISE EXCEPTION 'This team member''s email matches % existing learner identities — resolve which one is the same person before issuing.', v_matches
        USING ERRCODE = '23505';
    END IF;

    v_result := public.fn_jkkn_allocate('team_member', NULL, p_ref_id, NULL, auth.uid());

  ELSE
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_ref_id) THEN
      RAISE EXCEPTION 'No profile %', p_ref_id USING ERRCODE = '23503';
    END IF;

    SELECT btrim(jkkn_id) INTO v_existing
      FROM public.jkkn_identities WHERE profile_id = p_ref_id LIMIT 1;
    IF v_existing IS NOT NULL THEN
      RETURN jsonb_build_object('ok', true, 'action', 'already_held', 'jkkn_id', v_existing);
    END IF;

    v_result := public.fn_jkkn_allocate('associate', NULL, NULL, p_ref_id, auth.uid());
  END IF;

  RETURN jsonb_build_object('ok', true, 'action', 'issued', 'jkkn_id', v_result->>'jkkn_id');
END;
$fn$;

COMMENT ON FUNCTION public.fn_jkkn_issue_manual(text, uuid) IS
  'Manual "Issue ID" behind /users/jkkn-id, gated on users.jkkn_id.issue. Applies the same email guard as the auto-issue triggers: an exact match to an unlinked identity of the other kind LINKS that row (person_kind=both) and returns its number instead of minting a duplicate; an ambiguous match raises. issued_by = the caller.';

REVOKE EXECUTE ON FUNCTION public.fn_jkkn_issue_manual(text, uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_jkkn_issue_manual(text, uuid) TO authenticated;

-- ---------------------------------------------------------------------
-- 7. fn_jkkn_id_of — the number (and nothing else) for one person (2026-08-27)
-- ---------------------------------------------------------------------
-- Mirrors migration 20260827160000_jkkn_id_of_lookup.sql. Open to ALL
-- authenticated users on purpose: it returns only the card-printed,
-- non-secret number for a row id the caller already reached through a
-- detail page's own authorisation (learner profile / staff / user
-- management pages, whose viewers usually lack users.jkkn_id.view).
-- Rich person lookups stay behind that key. Retired identities → NULL.
CREATE OR REPLACE FUNCTION public.fn_jkkn_id_of(
  p_kind   text,
  p_ref_id uuid
)
RETURNS text
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_id      text;
  v_profile record;
BEGIN
  IF p_ref_id IS NULL OR p_kind IS NULL OR p_kind NOT IN ('learner', 'team_member', 'profile') THEN
    RETURN NULL;
  END IF;

  IF p_kind = 'learner' THEN
    SELECT btrim(jkkn_id) INTO v_id
      FROM public.jkkn_identities
     WHERE learner_profile_id = p_ref_id AND retired_at IS NULL
     LIMIT 1;
    RETURN v_id;
  END IF;

  IF p_kind = 'team_member' THEN
    SELECT btrim(jkkn_id) INTO v_id
      FROM public.jkkn_identities
     WHERE team_member_id = p_ref_id AND retired_at IS NULL
     LIMIT 1;
    RETURN v_id;
  END IF;

  -- 'profile': a user-management row can be a learner, a team member or a
  -- profile-anchored associate — resolve through the same bridges the ID-card
  -- renderer uses (profiles.learner_id; profiles.email == staff email).
  SELECT id, email, learner_id INTO v_profile
    FROM public.profiles WHERE id = p_ref_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT btrim(jkkn_id) INTO v_id
    FROM public.jkkn_identities
   WHERE profile_id = v_profile.id AND retired_at IS NULL
   LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  IF v_profile.learner_id IS NOT NULL THEN
    SELECT btrim(jkkn_id) INTO v_id
      FROM public.jkkn_identities
     WHERE learner_profile_id = v_profile.learner_id AND retired_at IS NULL
     LIMIT 1;
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  END IF;

  IF v_profile.email IS NOT NULL AND btrim(v_profile.email) <> '' THEN
    SELECT btrim(ji.jkkn_id) INTO v_id
      FROM public.jkkn_identities ji
      JOIN public.staff st ON st.id = ji.team_member_id
     WHERE ji.retired_at IS NULL
       AND (lower(btrim(coalesce(st.institution_email, ''))) = lower(btrim(v_profile.email))
         OR lower(btrim(coalesce(st.email, '')))             = lower(btrim(v_profile.email)))
     LIMIT 1;
  END IF;

  RETURN v_id;
END;
$fn$;

COMMENT ON FUNCTION public.fn_jkkn_id_of(text, uuid) IS
  'Returns ONLY the active JKKN ID for one person (kinds: learner | team_member | profile), or NULL. Granted to all authenticated users: the number is card-printed and non-secret, and the caller already passed the detail page''s own authorisation to know the row id. Rich person lookups remain behind users.jkkn_id.view. Retired identities return NULL.';

REVOKE EXECUTE ON FUNCTION public.fn_jkkn_id_of(text, uuid) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_jkkn_id_of(text, uuid) TO authenticated;


-- ============================================================================
-- fn_auto_allocate_candidates (CURRENT) — supersedes every earlier copy in this
-- file. Source: supabase/migrations/20260815070000_auto_allocate_candidates_roll_number.sql
--
-- Only change vs the previous copy: the Auto-Allocate preview now returns the
-- learner's roll_number, so the table, the Excel export and the PDF can identify
-- a candidate by the key wardens actually reconcile against. Every predicate,
-- verdict, stage and exclusion-reason branch is untouched.
--
-- Note the signature grew a column, so this is DROP + CREATE, not
-- CREATE OR REPLACE — and the grants are re-issued at the bottom because
-- DROP FUNCTION discards the ACL.
-- ============================================================================

-- Auto-Allocate preview: surface the learner's roll number.
--
-- The preview table identified a candidate by name + program + institution
-- only. Names collide (and are re-typed inconsistently across bulk uploads),
-- so a warden reconciling the preview against a printed nominal roll had no
-- stable key to match on. roll_number is the identifier every other Campus
-- Living surface already uses (waitlist, hostelite list, category upgrades),
-- and all 696 active hostel learners have one.
--
-- Adding a column to RETURNS TABLE means DROP + CREATE, not CREATE OR REPLACE.
-- DROP FUNCTION discards the ACL, so the grants are restored explicitly at the
-- bottom — without that, EXECUTE silently reverts to the PUBLIC default and
-- anon gains access to a SECURITY DEFINER function.
--
-- Only the roll_number plumbing changes. Every predicate, verdict, stage and
-- exclusion-reason branch is byte-identical to
-- 20260811150300_auto_allocate_candidates_reads_the_plan.sql.

DROP FUNCTION IF EXISTS public.fn_auto_allocate_candidates(text, boolean, uuid, uuid, uuid, boolean);

CREATE FUNCTION public.fn_auto_allocate_candidates(
  p_hostel_type text,
  p_strict boolean DEFAULT true,
  p_institution_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_allow_overflow boolean DEFAULT true
)
RETURNS TABLE(
  learner_id uuid, full_name text, roll_number text, email text,
  institution_name text, program_name text, semester_name text, gender text,
  has_profile boolean, gender_ok boolean, not_allocated boolean,
  physical_rule_ok boolean, overflow_room_ok boolean, placement_tier text,
  bed_available boolean, target_block_name text,
  academic_year_id uuid, academic_year_name text,
  admission_academic_year_id uuid, admission_academic_year_name text,
  band_academic_year_id uuid, band_academic_year_name text, band_fee numeric,
  academic_bill_count integer, current_year_bill_count integer,
  bill_other_year_name text, current_year_fee numeric,
  resolved_room_category_id uuid, resolved_room_category_name text,
  resolved_mess_category_id uuid, resolved_mess_category_name text,
  bill_state text, stage text, verdict text, exclusion_reason text
)
LANGUAGE sql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  WITH blocks AS MATERIALIZED (
    SELECT id, name FROM hostel_blocks WHERE hostel_type::text = p_hostel_type
  ),
  scope_rooms AS MATERIALIZED (
    SELECT r.id, r.block_id, b.name AS block_name, r.floor, r.room_number,
           r.category_id, hc.type AS cat_type
    FROM hostel_rooms r
    JOIN blocks b ON b.id = r.block_id
    LEFT JOIN hostel_categories hc ON hc.id = r.category_id
    WHERE r.room_purpose = 'student'
  ),
  raw_cohort AS MATERIALIZED (
    SELECT lp.id, lp.institution_id, lp.degree_id, lp.department_id,
           lp.program_id, lp.semester_id, lp.academic_year_id, lp.quota_id,
           lp.first_name, lp.last_name,
           -- '' is as good as absent for a display identifier; normalising here
           -- keeps the UI's `?? '—'` fallback from rendering an empty cell.
           NULLIF(btrim(lp.roll_number), '') AS roll_number,
           CASE WHEN lower(lp.gender) LIKE 'm%' THEN 'boys'
                WHEN lower(lp.gender) LIKE 'f%' THEN 'girls' END AS lp_gender_type,
           lower(btrim(COALESCE(NULLIF(btrim(gp.gender), ''), lp.gender))) AS eff_gender
    FROM learners_profiles lp
    LEFT JOIN profiles gp ON gp.learner_id = lp.id
    WHERE lp.accommodation_type_id IN (SELECT id FROM accommodation_types WHERE code = 'hostel')
      AND lp.lifecycle_status = 'active'
      AND (p_institution_id IS NULL OR lp.institution_id = p_institution_id)
      AND (p_program_id     IS NULL OR lp.program_id     = p_program_id)
      AND (p_semester_id    IS NULL OR lp.semester_id    = p_semester_id)
      AND (COALESCE(NULLIF(btrim(gp.gender), ''), NULLIF(btrim(lp.gender), '')) IS NULL
           OR (p_hostel_type = 'boys'
               AND lower(btrim(COALESCE(NULLIF(btrim(gp.gender), ''), lp.gender))) IN ('male','m'))
           OR (p_hostel_type = 'girls'
               AND lower(btrim(COALESCE(NULLIF(btrim(gp.gender), ''), lp.gender))) IN ('female','f')))
      AND NOT EXISTS (
        SELECT 1 FROM hostel_allocations ha2
        JOIN profiles pr2 ON pr2.learner_id = lp.id
        WHERE ha2.learner_id = pr2.id
          AND ha2.status IN ('active', 'pending_approval')
      )
  ),
  placement AS MATERIALIZED (
    SELECT pl.plan_lp_id, pl.plan_bed_id, pl.plan_block_name, pl.plan_tier
    FROM fn_auto_allocate_plan(
           p_hostel_type, p_strict, p_institution_id,
           p_program_id, p_semester_id, p_allow_overflow) pl
  ),
  unruled_rooms AS MATERIALIZED (
    SELECT sr.id AS room_id, sr.category_id, sr.cat_type,
           sr.block_name, sr.floor, sr.room_number
    FROM scope_rooms sr
    WHERE NOT EXISTS (
      SELECT 1 FROM hostel_room_eligibility_rules re
      WHERE re.is_active AND re.block_id = sr.block_id
        AND CASE
              WHEN EXISTS (SELECT 1 FROM hostel_room_eligibility_rule_rooms rr
                           WHERE rr.rule_id = re.id)
                THEN EXISTS (SELECT 1 FROM hostel_room_eligibility_rule_rooms rr
                             WHERE rr.rule_id = re.id AND rr.room_id = sr.id)
              ELSE (re.floor IS NULL OR re.floor = sr.floor)
            END
    )
  ),
  overflow_rooms AS MATERIALIZED (
    SELECT i.institution_id, ur.room_id, ur.category_id, ur.cat_type,
           ur.block_name, ur.floor, ur.room_number
    FROM (SELECT DISTINCT institution_id FROM raw_cohort) i
    CROSS JOIN unruled_rooms ur
    WHERE p_allow_overflow
      AND fn_room_serves_institution(ur.room_id, i.institution_id)
  ),
  sigs AS MATERIALIZED (
    SELECT rc.institution_id, rc.degree_id, rc.department_id, rc.program_id,
           rc.semester_id, (array_agg(rc.id))[1] AS rep
    FROM raw_cohort rc
    WHERE EXISTS (SELECT 1 FROM hostel_block_institutions bi
                  WHERE bi.institution_id = rc.institution_id
                    AND bi.block_id IN (SELECT id FROM blocks))
    GROUP BY 1,2,3,4,5
  ),
  sig_rooms AS MATERIALIZED (
    SELECT s.rep, sr.id AS room_id, sr.category_id, sr.cat_type,
           sr.block_name, sr.floor, sr.room_number
    FROM sigs s
    CROSS JOIN scope_rooms sr
    WHERE fn_room_serves_institution(sr.id, s.institution_id)
      AND fn_learner_strictly_eligible_for_room(s.rep, sr.id, p_strict)
  ),
  free_beds AS MATERIALIZED (
    SELECT bd.id, bd.room_id, bd.bed_number
    FROM hostel_beds bd
    JOIN scope_rooms sr ON sr.id = bd.room_id
    WHERE bd.status = 'available'
      AND NOT EXISTS (SELECT 1 FROM hostel_allocations a
                      WHERE a.bed_id = bd.id AND a.status IN ('active','pending_approval'))
  ),
  fee AS MATERIALIZED (
    SELECT c.id, adm.ay_id AS adm_ay,
           bf.academic_year_id AS band_ay, bf.academic_year_name AS band_ay_name, bf.fee
    FROM raw_cohort c
    LEFT JOIN LATERAL (SELECT fn_learner_admission_academic_year(c.id) AS ay_id) adm ON true
    LEFT JOIN LATERAL fn_learner_band_academic_fee(c.id) bf ON true
  ),
  cats AS MATERIALIZED (
    SELECT c.id,
      CASE WHEN c.institution_id IS NOT NULL AND c.program_id IS NOT NULL AND f.fee IS NOT NULL
           THEN (SELECT array_agg(category_id) FROM fn_hostel_effective_room_categories(
                   c.institution_id, c.program_id, c.quota_id, f.fee, c.lp_gender_type)) END AS room_cats,
      CASE WHEN c.institution_id IS NOT NULL AND c.program_id IS NOT NULL AND f.fee IS NOT NULL
           THEN (SELECT array_agg(category_id) FROM fn_hostel_effective_mess_categories(
                   c.institution_id, c.program_id, c.quota_id, f.fee, c.lp_gender_type)) END AS mess_cats
    FROM raw_cohort c JOIN fee f ON f.id = c.id
  ),
  base AS (
    SELECT
      c.id AS learner_id,
      COALESCE(p.full_name,
               NULLIF(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''),
               p.email, '—') AS full_name,
      c.roll_number,
      p.email, inst.name AS institution_name, prog.program_name, sem.semester_name,
      c.eff_gender AS gender,
      (p.id IS NOT NULL) AS has_profile,
      c.academic_year_id, ay.academic_year_name,
      ct.room_cats, ct.mess_cats,
      f.adm_ay AS admission_academic_year_id,
      aay.academic_year_name::text AS admission_academic_year_name,
      f.band_ay AS band_academic_year_id,
      f.band_ay_name AS band_academic_year_name,
      f.fee AS band_fee,
      ct.room_cats[1] AS resolved_room_category_id,
      rc.name AS resolved_room_category_name, rc.type AS resolved_room_category_type,
      ct.mess_cats[1] AS resolved_mess_category_id, mc.name AS resolved_mess_category_name,
      (SELECT count(*)::int FROM billing_student_bills b
         WHERE b.student_id = c.id AND b.fee_source = 'academic'
           AND b.status NOT IN ('cancelled','superseded')) AS academic_bill_count,
      (SELECT count(*)::int FROM billing_student_bills b
         WHERE b.student_id = c.id AND b.fee_source = 'academic'
           AND b.status NOT IN ('cancelled','superseded')
           AND b.academic_year_id = c.academic_year_id) AS current_year_bill_count,
      (SELECT ay2.academic_year_name
         FROM billing_student_bills b JOIN academic_years ay2 ON ay2.id = b.academic_year_id
        WHERE b.student_id = c.id AND b.fee_source = 'academic'
          AND b.status NOT IN ('cancelled','superseded')
          AND b.academic_year_id IS NOT NULL
          AND b.academic_year_id IS DISTINCT FROM c.academic_year_id
        ORDER BY b.created_at DESC LIMIT 1) AS bill_other_year_name,
      fn_learner_current_year_academic_fee(c.id) AS current_year_fee,
      true AS not_allocated,
      EXISTS (SELECT 1 FROM hostel_block_institutions bi
              WHERE bi.institution_id = c.institution_id
                AND bi.block_id IN (SELECT id FROM blocks)) AS block_access_ok,
      EXISTS (
        SELECT 1 FROM sig_rooms sr
        WHERE sr.rep = s.rep
          AND sr.category_id = ANY(ct.room_cats)
          AND (sr.cat_type IS NULL
               OR (sr.cat_type = 'boys'  AND c.eff_gender IN ('male','m'))
               OR (sr.cat_type = 'girls' AND c.eff_gender IN ('female','f')))
      ) AS physical_rule_ok,
      EXISTS (
        SELECT 1 FROM sig_rooms sr
        WHERE sr.rep = s.rep
          AND NOT (sr.category_id = ANY(ct.room_cats))
      ) AS physical_ok_other_category,
      (SELECT count(*)::int
         FROM free_beds bd2
         JOIN scope_rooms sr2 ON sr2.id = bd2.room_id
        WHERE sr2.category_id = ANY(ct.room_cats)
          AND (sr2.cat_type IS NULL
               OR (sr2.cat_type = 'boys'  AND c.eff_gender IN ('male','m'))
               OR (sr2.cat_type = 'girls' AND c.eff_gender IN ('female','f')))
      ) AS category_free_beds_anywhere,
      EXISTS (
        SELECT 1 FROM overflow_rooms orm
        WHERE orm.institution_id = c.institution_id
          AND orm.category_id = ANY(ct.room_cats)
          AND (orm.cat_type IS NULL
               OR (orm.cat_type = 'boys'  AND c.eff_gender IN ('male','m'))
               OR (orm.cat_type = 'girls' AND c.eff_gender IN ('female','f')))
      ) AS overflow_room_ok,
      (pl.plan_bed_id IS NOT NULL) AS bed_available,
      pl.plan_block_name AS target_block_name,
      CASE pl.plan_tier WHEN 1 THEN 'rule' WHEN 2 THEN 'overflow' END AS placement_tier
    FROM raw_cohort c
    JOIN cats ct ON ct.id = c.id
    JOIN fee  f  ON f.id  = c.id
    LEFT JOIN sigs s ON s.institution_id IS NOT DISTINCT FROM c.institution_id
                    AND s.degree_id      IS NOT DISTINCT FROM c.degree_id
                    AND s.department_id  IS NOT DISTINCT FROM c.department_id
                    AND s.program_id     IS NOT DISTINCT FROM c.program_id
                    AND s.semester_id    IS NOT DISTINCT FROM c.semester_id
    LEFT JOIN placement pl      ON pl.plan_lp_id = c.id
    LEFT JOIN profiles p        ON p.learner_id = c.id
    LEFT JOIN institutions inst ON inst.id = c.institution_id
    LEFT JOIN programs prog     ON prog.id = c.program_id
    LEFT JOIN semesters sem     ON sem.id = c.semester_id
    LEFT JOIN academic_years ay ON ay.id = c.academic_year_id
    LEFT JOIN academic_years aay ON aay.id = f.adm_ay
    LEFT JOIN hostel_categories rc ON rc.id = ct.room_cats[1]
    LEFT JOIN mess_categories   mc ON mc.id = ct.mess_cats[1]
  ),
  scored AS (
    SELECT b.*,
      (b.gender IS NOT NULL
        AND (b.resolved_room_category_type IS NULL
          OR (b.resolved_room_category_type = 'boys'  AND b.gender IN ('male','m'))
          OR (b.resolved_room_category_type = 'girls' AND b.gender IN ('female','f')))) AS gender_ok
    FROM base b
  )
  SELECT
    s.learner_id, s.full_name, s.roll_number, s.email,
    s.institution_name, s.program_name, s.semester_name,
    s.gender, s.has_profile, s.gender_ok, s.not_allocated, s.physical_rule_ok,
    s.overflow_room_ok, s.placement_tier,
    s.bed_available, s.target_block_name,
    s.academic_year_id, s.academic_year_name,
    s.admission_academic_year_id, s.admission_academic_year_name,
    s.band_academic_year_id, s.band_academic_year_name, s.band_fee,
    s.academic_bill_count, s.current_year_bill_count, s.bill_other_year_name, s.current_year_fee,
    s.resolved_room_category_id, s.resolved_room_category_name,
    s.resolved_mess_category_id, s.resolved_mess_category_name,
    CASE
      WHEN s.band_fee IS NOT NULL
       AND s.band_academic_year_id IS NOT DISTINCT FROM s.admission_academic_year_id THEN 'matched'
      WHEN s.band_fee IS NOT NULL          THEN 'different_year'
      WHEN s.academic_bill_count > 0       THEN 'untagged'
      ELSE 'none'
    END AS bill_state,
    CASE
      WHEN s.band_fee  IS NULL THEN 'prerequisite'
      WHEN s.room_cats IS NULL THEN 'prerequisite'
      WHEN NOT s.has_profile OR NOT s.gender_ok OR NOT s.block_access_ok
        OR NOT (s.physical_rule_ok OR s.overflow_room_ok) OR NOT s.bed_available
                               THEN 'eligibility'
      ELSE 'ok'
    END AS stage,
    CASE
      WHEN s.band_fee  IS NULL THEN 'out'
      WHEN s.room_cats IS NULL THEN 'out'
      WHEN NOT s.has_profile OR NOT s.gender_ok OR NOT s.block_access_ok
        OR NOT (s.physical_rule_ok OR s.overflow_room_ok) OR NOT s.bed_available
                               THEN 'out'
      ELSE 'in'
    END AS verdict,
    CASE
      WHEN s.band_fee IS NULL THEN
        CASE
          WHEN s.academic_bill_count = 0 THEN
            'No academic bill for this student — nothing to read a fee band from'
          ELSE
            'Academic bills exist but none is usable: either untagged to an academic year, or the tagged year totals ₹0'
        END
      WHEN s.room_cats IS NULL THEN
        'No Category-Eligibility band covers ₹'
        || to_char(s.band_fee, 'FM999,999,999')
        || ' (read from ' || COALESCE(s.band_academic_year_name, 'their admission year') || ')'
        || ' for this program / quota — add or widen a band'
      WHEN NOT s.has_profile   THEN 'No login profile'
      WHEN s.gender IS NULL    THEN
        'Gender is not set on this learner — set it on the learner profile, then re-run the preview'
      WHEN NOT s.gender_ok     THEN 'Gender does not match the resolved room category'
      WHEN NOT s.block_access_ok THEN
        COALESCE(s.institution_name, 'This learner''s institution')
        || ' is not linked to any ' || p_hostel_type || ' block — link it under'
        || ' Campus Living → Blocks → Institutions before this learner can be placed'
      WHEN NOT (s.physical_rule_ok OR s.overflow_room_ok) AND s.physical_ok_other_category THEN
        'Rooms they may occupy are a different room category than their eligible '
        || COALESCE(s.resolved_room_category_name, 'category')
        || ' — fix the reservation rooms or the Category-Eligibility band'
      WHEN NOT (s.physical_rule_ok OR s.overflow_room_ok) THEN
        CASE WHEN p_strict
          THEN 'No physical-room rule reserves a room for this cohort in any ' || p_hostel_type || ' block (strict mode)'
          ELSE 'No room they can occupy in their category — every room is reserved for other cohorts'
        END
      WHEN NOT s.bed_available THEN
        CASE
          WHEN s.category_free_beds_anywhere > 0 THEN
            COALESCE(s.resolved_room_category_name, 'Their category')
            || ': ' || s.category_free_beds_anywhere::text
            || ' free bed' || CASE WHEN s.category_free_beds_anywhere = 1 THEN '' ELSE 's' END
            || ' exist in the ' || p_hostel_type || ' blocks, but none is left for this learner'
            || ' — every one is either reserved for another cohort or already taken by an'
            || ' earlier learner in this same run'
            || CASE WHEN p_allow_overflow
                 THEN '. Add this cohort to a physical-room rule that covers free rooms,'
                      || ' or free more beds in the rooms they already reach'
                 ELSE ' (overflow is off, so unreserved rooms were not considered)'
               END
          ELSE
            COALESCE(s.resolved_room_category_name, 'Their category')
            || ' is exhausted in every ' || p_hostel_type
            || ' block — no free bed in any '
            || COALESCE(s.resolved_room_category_name, 'eligible')
            || ' room, reserved or unreserved'
        END
      ELSE NULL
    END AS exclusion_reason
  FROM scored s
  ORDER BY s.full_name;
$function$;

-- DROP discarded the ACL. Restore exactly what was there: authenticated +
-- service_role only. anon must NOT reach a SECURITY DEFINER function that
-- reads the whole learner cohort.
REVOKE ALL ON FUNCTION public.fn_auto_allocate_candidates(text, boolean, uuid, uuid, uuid, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_auto_allocate_candidates(text, boolean, uuid, uuid, uuid, boolean) TO authenticated, service_role;

-- =====================================================================
-- Approval trigger: insert entitled = NULL, not 0
-- =====================================================================
-- WHY: approving leave for someone with no balance row inserted
-- (entitled = 0, used = total_days) -- a permanently negative balance the
-- generator could never repair, because it was ON CONFLICT DO NOTHING and
-- would skip the row it needed to fix. NULL means "derive from the leave
-- type", so the row records the usage without pinning entitlement to zero.

CREATE OR REPLACE FUNCTION public.hr_trig_update_leave_balance()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_delta numeric;
  v_category text;
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.status = NEW.status THEN
    RETURN NEW;
  END IF;

  SELECT request_category INTO v_category
  FROM public.hr_leave_types WHERE id = NEW.leave_type_id;

  -- Comp off is credit-backed; short time off is minute-backed. Neither draws
  -- on a day entitlement.
  IF v_category IN ('compensatory_off', 'short_time_off') THEN
    NEW.updated_at := now();
    RETURN NEW;
  END IF;

  IF NEW.status = 'approved' AND OLD.status != 'approved' THEN
    v_delta := NEW.total_days;
    INSERT INTO hr_leave_balances (employee_id, leave_type_id, hr_academic_year_id, hr_organization_id, entitled, used, carried_forward)
    VALUES (NEW.employee_id, NEW.leave_type_id, NEW.hr_academic_year_id, NEW.hr_organization_id, NULL, v_delta, 0)
    ON CONFLICT (employee_id, leave_type_id, hr_academic_year_id)
    DO UPDATE SET
      used = hr_leave_balances.used + EXCLUDED.used,
      updated_at = now();

  ELSIF NEW.status IN ('cancelled', 'rejected', 'withdrawn') AND OLD.status = 'approved' THEN
    v_delta := NEW.total_days;
    UPDATE hr_leave_balances
       SET used = GREATEST(0, used - v_delta),
           updated_at = now()
     WHERE employee_id         = NEW.employee_id
       AND leave_type_id       = NEW.leave_type_id
       AND hr_academic_year_id = NEW.hr_academic_year_id;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END $function$;


-- ============================================================
-- 20260812062157_billing_coverage_admission_year_filter.sql
-- Bill Coverage: admission year (cohort) filter
-- ============================================================
-- ============================================================================
-- Bill Coverage: admission year (cohort) filter
-- ============================================================================
-- Adds p_admission_year to all three coverage RPCs so the page can be narrowed
-- to a single admission cohort ("the 2025 batch"), and surfaces that cohort as
-- a column on the learners list.
--
-- WHY AN INTEGER AND NOT AN admission_year_id UUID
-- admission_years holds one row per (institution, year) — cohort 2026 exists 11
-- times, once per college, each with its own id. A uuid parameter would
-- therefore only be meaningful once an institution had been picked, exactly the
-- limitation that already forces the Academic Year filter to disable itself in
-- "All accessible institutions" mode. admission_years.year is a plain integer
-- and is the same value in every institution, so filtering on it composes with
-- the default multi-institution scope. This matches how the group dashboard
-- already presents cohorts (hooks/admission/use-group-admission-years.ts dedupes
-- the rows by year).
--
-- DISTINCT FROM p_academic_year_id
-- p_academic_year_id is the year coverage is MEASURED against and never filters
-- which learners appear (see 20260808120000). p_admission_year is the opposite:
-- it is purely a population filter and has no bearing on which bills count.
--
-- WHY DROP AND RECREATE
-- CREATE OR REPLACE with a different argument count does not replace — it adds a
-- second overload, and PostgREST then fails every call with PGRST203. Dropping
-- discards the ACL (EXECUTE reverts to PUBLIC, which includes anon), so the
-- REVOKE/GRANT pairs at the end of each block are load-bearing, not decoration.
-- ============================================================================

DROP FUNCTION IF EXISTS public.get_billing_coverage_learners(
  uuid, uuid[], text[], uuid, text, boolean, text, integer, integer,
  uuid[], text, text, text, text, uuid, uuid, uuid, uuid, uuid);

DROP FUNCTION IF EXISTS public.get_billing_coverage_summary(
  uuid, uuid[], text[], uuid, boolean, uuid[], text, text,
  uuid, uuid, uuid, uuid, uuid);

DROP FUNCTION IF EXISTS public.get_billing_coverage_learner_bills(
  uuid, uuid[], text[], uuid, text, boolean, text, uuid[], text, text,
  uuid, uuid, uuid, uuid, uuid, integer);

-- ── Learners list ──────────────────────────────────────────────────────────
CREATE FUNCTION public.get_billing_coverage_learners(
  p_academic_year_id uuid DEFAULT NULL::uuid,
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_billing_category_id uuid DEFAULT NULL::uuid,
  p_coverage_state text DEFAULT 'not_generated'::text,
  p_include_non_billing_institutions boolean DEFAULT false,
  p_search text DEFAULT NULL::text,
  p_page integer DEFAULT 1,
  p_page_size integer DEFAULT 50,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_sort_by text DEFAULT NULL::text,
  p_sort_dir text DEFAULT 'asc'::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_admission_year integer DEFAULT NULL::integer
)
RETURNS TABLE(
  out_learner_id uuid, out_roll_number text, out_register_number text,
  out_full_name text, out_lifecycle_status text, out_gender text,
  out_institution_id uuid, out_institution_name text, out_program_name text,
  out_semester_section text, out_academic_year_id uuid,
  out_academic_year_name text, out_admission_year integer,
  out_accommodation_type text, out_uses_transport boolean,
  out_bill_count integer, out_total_billed numeric, out_total_paid numeric,
  out_coverage_state text, out_target_academic_year_name text,
  out_total_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst   uuid[];
  v_limit  integer := LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 200);
  v_offset integer := GREATEST(COALESCE(p_page, 1) - 1, 0)
                      * LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 200);
  v_asc    boolean := COALESCE(LOWER(p_sort_dir), 'asc') <> 'desc';
  -- Name of an explicitly picked year, so the reported target reflects the
  -- caller's choice rather than the institution's current year.
  v_picked_ay_name text;
  -- Every admission_years id, across ALL institutions, for the requested cohort.
  -- Resolved once here rather than as a correlated subquery per learner.
  v_adm_year_ids uuid[];
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN;
  END IF;

  SELECT ay.academic_year_name::text INTO v_picked_ay_name
  FROM public.academic_years ay WHERE ay.id = p_academic_year_id;

  -- Left NULL when no cohort is requested. When a cohort is requested but no
  -- admission_years row carries that year, the array stays NULL and
  -- `= ANY(NULL)` evaluates to NULL, which correctly matches no learner.
  IF p_admission_year IS NOT NULL THEN
    SELECT array_agg(ayr.id) INTO v_adm_year_ids
    FROM public.admission_years ayr
    WHERE ayr.year = p_admission_year;
  END IF;

  RETURN QUERY
  WITH target_year AS MATERIALIZED (
    SELECT t.institution_id, t.target_ay_id, t.target_ay_name
    FROM public.fn_billing_coverage_target_years() t
  ),
  billing_inst AS (
    -- ALL-TIME test, deliberately not scoped to p_academic_year_id. An
    -- institution that billed last year and has generated nothing this year is
    -- the case this report exists to catch; scoping here would hide it.
    SELECT DISTINCT b.institution_id AS inst_id
    FROM public.billing_student_bills b
  ),
  scope AS (
    -- NOTE: no lp.academic_year_id predicate. p_academic_year_id selects the
    -- year being MEASURED, never the learners being measured — see
    -- 20260808120000_billing_coverage_target_academic_year.sql.
    -- p_admission_year is the exception: a cohort IS a population.
    SELECT lp.id, lp.institution_id, lp.academic_year_id, lp.program_id,
           lp.semester_id, lp.section_id, lp.gender,
           lp.lifecycle_status, lp.first_name, lp.last_name,
           lp.roll_number, lp.register_number,
           lp.accommodation_type_id, lp.admission_year_id,
           (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL)
             AS uses_transport
    FROM public.learners_profiles lp
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_billing_institutions
           OR lp.institution_id IN (SELECT inst_id FROM billing_inst))
      AND (p_admission_year IS NULL
           OR lp.admission_year_id = ANY(v_adm_year_ids))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
      AND (
        p_search IS NULL OR p_search = ''
        OR lp.roll_number ILIKE '%' || p_search || '%'
        OR lp.register_number ILIKE '%' || p_search || '%'
        OR (COALESCE(lp.first_name,'') || ' ' || COALESCE(lp.last_name,''))
             ILIKE '%' || p_search || '%'
      )
  ),
  agg AS (
    SELECT s.id AS learner_id,
           ty.target_ay_id,
           ty.target_ay_name,
           COUNT(b.id)::integer AS bill_count,
           COALESCE(SUM(b.final_amount), 0)::numeric AS total_billed,
           -- Same expression as get_billing_coverage_learner_bills, over the
           -- same join — the XLS and the PDF must never disagree. A learner
           -- with no live bill sums to NULL and lands on 0, matching the 0 they
           -- already show for total_billed.
           COALESCE(
             SUM(b.final_amount - COALESCE(b.balance_amount, 0)), 0
           )::numeric AS total_paid
    FROM scope s
    LEFT JOIN target_year ty ON ty.institution_id = s.institution_id
    LEFT JOIN public.billing_student_bills b
           ON b.student_id = s.id
          -- A cancelled or superseded bill is not coverage: no live bill exists.
          AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
          -- The bill's OWN year against the target year. Was s.academic_year_id.
          AND b.academic_year_id = COALESCE(p_academic_year_id, ty.target_ay_id)
          AND (p_billing_category_id IS NULL
               OR b.item_category_id = p_billing_category_id)
    GROUP BY s.id, ty.target_ay_id, ty.target_ay_name
  ),
  final AS (
    SELECT s.id AS learner_id,
           s.roll_number::text        AS roll_number,
           s.register_number::text    AS register_number,
           TRIM(COALESCE(s.first_name,'') || ' ' || COALESCE(s.last_name,''))
                                      AS full_name,
           s.lifecycle_status::text   AS lifecycle_status,
           NULLIF(TRIM(s.gender), '')::text AS gender,
           s.institution_id           AS institution_id,
           i.name::text               AS institution_name,
           p.program_name             AS program_name,
           CASE
             WHEN sem.semester_name IS NULL AND sec.section_name IS NULL
               THEN NULL
             WHEN sec.section_name IS NULL THEN sem.semester_name::text
             WHEN sem.semester_name IS NULL THEN sec.section_name::text
             ELSE sem.semester_name::text || ' · ' || sec.section_name::text
           END                        AS semester_section,
           -- The learner's OWN year, shown for context. It is no longer what
           -- coverage is measured against; target_academic_year_name is.
           s.academic_year_id         AS academic_year_id,
           ay.academic_year_name::text AS academic_year_name,
           -- The cohort the learner was admitted in. Independent of both years
           -- above: it never rolls over, so it is the only stable way to read a
           -- row as "first-year intake" vs "continuing".
           adm.year                   AS admission_year,
           acc.name::text             AS accommodation_type,
           s.uses_transport           AS uses_transport,
           a.bill_count               AS bill_count,
           a.total_billed             AS total_billed,
           a.total_paid               AS total_paid,
           CASE
             -- Only when NO year can be resolved at all: an institution with no
             -- active year that has started yet. Never a mere mismatch.
             WHEN COALESCE(p_academic_year_id, a.target_ay_id) IS NULL
               THEN 'cannot_evaluate'
             WHEN a.bill_count > 0 THEN 'generated'
             ELSE 'not_generated'
           END                        AS coverage_state,
           COALESCE(v_picked_ay_name, a.target_ay_name)
                                      AS target_academic_year_name
    FROM scope s
    JOIN agg a                           ON a.learner_id = s.id
    LEFT JOIN public.institutions        i   ON i.id   = s.institution_id
    LEFT JOIN public.programs            p   ON p.id   = s.program_id
    LEFT JOIN public.semesters           sem ON sem.id = s.semester_id
    LEFT JOIN public.sections            sec ON sec.id = s.section_id
    LEFT JOIN public.academic_years      ay  ON ay.id  = s.academic_year_id
    LEFT JOIN public.admission_years     adm ON adm.id = s.admission_year_id
    LEFT JOIN public.accommodation_types acc ON acc.id = s.accommodation_type_id
  ),
  filtered AS (
    SELECT * FROM final f
    WHERE p_coverage_state = 'all' OR f.coverage_state = p_coverage_state
  )
  SELECT f.learner_id, f.roll_number, f.register_number, f.full_name,
         f.lifecycle_status, f.gender, f.institution_id, f.institution_name,
         f.program_name, f.semester_section,
         f.academic_year_id, f.academic_year_name, f.admission_year,
         f.accommodation_type, f.uses_transport,
         f.bill_count, f.total_billed, f.total_paid, f.coverage_state,
         f.target_academic_year_name,
         COUNT(*) OVER ()::bigint
  FROM filtered f
  ORDER BY
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'academic_year_name' THEN f.academic_year_name
         WHEN 'accommodation_type' THEN f.accommodation_type
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'gender'             THEN f.gender
         WHEN 'coverage_state'     THEN f.coverage_state
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'academic_year_name' THEN f.academic_year_name
         WHEN 'accommodation_type' THEN f.accommodation_type
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'gender'             THEN f.gender
         WHEN 'coverage_state'     THEN f.coverage_state
       END
     END) DESC NULLS LAST,
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'bill_count'     THEN f.bill_count::numeric
         WHEN 'total_billed'   THEN f.total_billed
         WHEN 'total_paid'     THEN f.total_paid
         WHEN 'admission_year' THEN f.admission_year::numeric
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'bill_count'     THEN f.bill_count::numeric
         WHEN 'total_billed'   THEN f.total_billed
         WHEN 'total_paid'     THEN f.total_paid
         WHEN 'admission_year' THEN f.admission_year::numeric
       END
     END) DESC NULLS LAST,
    f.institution_name NULLS LAST, f.roll_number NULLS LAST, f.full_name
  LIMIT v_limit OFFSET v_offset;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_billing_coverage_learners(
  uuid, uuid[], text[], uuid, text, boolean, text, integer, integer,
  uuid[], text, text, text, text, uuid, uuid, uuid, uuid, uuid, integer)
  FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_billing_coverage_learners(
  uuid, uuid[], text[], uuid, text, boolean, text, integer, integer,
  uuid[], text, text, text, text, uuid, uuid, uuid, uuid, uuid, integer)
  TO authenticated, service_role;

-- ── Summary (KPI cards) ────────────────────────────────────────────────────
-- The same predicate has to land here or the cards would count a wider
-- population than the table below them shows.
CREATE FUNCTION public.get_billing_coverage_summary(
  p_academic_year_id uuid DEFAULT NULL::uuid,
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_billing_category_id uuid DEFAULT NULL::uuid,
  p_include_non_billing_institutions boolean DEFAULT false,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_admission_year integer DEFAULT NULL::integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst         uuid[];
  v_adm_year_ids uuid[];
  v_result       jsonb;
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN jsonb_build_object(
      'in_scope', 0, 'generated', 0, 'not_generated', 0, 'cannot_evaluate', 0,
      'excluded_institutions', 0, 'excluded_learners', 0,
      'by_institution', '[]'::jsonb);
  END IF;

  IF p_admission_year IS NOT NULL THEN
    SELECT array_agg(ayr.id) INTO v_adm_year_ids
    FROM public.admission_years ayr
    WHERE ayr.year = p_admission_year;
  END IF;

  WITH target_year AS MATERIALIZED (
    SELECT t.institution_id, t.target_ay_id
    FROM public.fn_billing_coverage_target_years() t
  ),
  billing_inst AS (
    SELECT DISTINCT b.institution_id AS inst_id FROM public.billing_student_bills b
  ),
  all_scope AS (
    -- No lp.academic_year_id predicate — see get_billing_coverage_learners.
    SELECT lp.id, lp.institution_id,
           (lp.institution_id IN (SELECT inst_id FROM billing_inst)) AS is_billing_inst
    FROM public.learners_profiles lp
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_admission_year IS NULL
           OR lp.admission_year_id = ANY(v_adm_year_ids))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
  ),
  scope AS (
    SELECT * FROM all_scope
    WHERE p_include_non_billing_institutions OR is_billing_inst
  ),
  agg AS (
    SELECT s.id, s.institution_id, ty.target_ay_id,
           COUNT(b.id)::integer AS bill_count
    FROM scope s
    LEFT JOIN target_year ty ON ty.institution_id = s.institution_id
    LEFT JOIN public.billing_student_bills b
           ON b.student_id = s.id
          AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
          AND b.academic_year_id = COALESCE(p_academic_year_id, ty.target_ay_id)
          AND (p_billing_category_id IS NULL
               OR b.item_category_id = p_billing_category_id)
    GROUP BY s.id, s.institution_id, ty.target_ay_id
  ),
  stated AS (
    SELECT a.institution_id,
           CASE
             WHEN COALESCE(p_academic_year_id, a.target_ay_id) IS NULL
               THEN 'cannot_evaluate'
             WHEN a.bill_count > 0 THEN 'generated'
             ELSE 'not_generated'
           END AS coverage_state
    FROM agg a
  )
  SELECT jsonb_build_object(
    'in_scope',        (SELECT COUNT(*) FROM stated),
    'generated',       (SELECT COUNT(*) FROM stated WHERE coverage_state = 'generated'),
    'not_generated',   (SELECT COUNT(*) FROM stated WHERE coverage_state = 'not_generated'),
    'cannot_evaluate', (SELECT COUNT(*) FROM stated WHERE coverage_state = 'cannot_evaluate'),
    'excluded_institutions',
      (SELECT COUNT(DISTINCT institution_id) FROM all_scope WHERE NOT is_billing_inst),
    'excluded_learners',
      (SELECT COUNT(*) FROM all_scope WHERE NOT is_billing_inst),
    'by_institution', COALESCE((
      SELECT jsonb_agg(x ORDER BY x->>'institution_name')
      FROM (
        SELECT jsonb_build_object(
                 'institution_id',   st.institution_id,
                 'institution_name', COALESCE(i.name::text, 'Unknown'),
                 'in_scope',         COUNT(*),
                 'generated',        COUNT(*) FILTER (WHERE st.coverage_state = 'generated'),
                 'not_generated',    COUNT(*) FILTER (WHERE st.coverage_state = 'not_generated')
               ) AS x
        FROM stated st
        LEFT JOIN public.institutions i ON i.id = st.institution_id
        GROUP BY st.institution_id, i.name
      ) sub
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_billing_coverage_summary(
  uuid, uuid[], text[], uuid, boolean, uuid[], text, text,
  uuid, uuid, uuid, uuid, uuid, integer)
  FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_billing_coverage_summary(
  uuid, uuid[], text[], uuid, boolean, uuid[], text, text,
  uuid, uuid, uuid, uuid, uuid, integer)
  TO authenticated, service_role;

-- ── Per-learner bill detail (PDF export) ───────────────────────────────────
CREATE FUNCTION public.get_billing_coverage_learner_bills(
  p_academic_year_id uuid DEFAULT NULL::uuid,
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_billing_category_id uuid DEFAULT NULL::uuid,
  p_coverage_state text DEFAULT 'all'::text,
  p_include_non_billing_institutions boolean DEFAULT false,
  p_search text DEFAULT NULL::text,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_max_learners integer DEFAULT 1000,
  p_admission_year integer DEFAULT NULL::integer
)
RETURNS TABLE(
  out_learner_id uuid, out_roll_number text, out_register_number text,
  out_full_name text, out_institution_name text, out_program_name text,
  out_semester_section text, out_lifecycle_status text,
  out_learner_total numeric, out_learner_paid numeric,
  out_learner_pending numeric, out_bill_id uuid, out_bill_description text,
  out_category_name text, out_bill_academic_year text, out_due_date date,
  out_bill_status text, out_total_amount numeric, out_paid_amount numeric,
  out_pending_amount numeric, out_learner_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst         uuid[];
  v_adm_year_ids uuid[];
  v_cap          integer := LEAST(GREATEST(COALESCE(p_max_learners, 1000), 1), 5000);
BEGIN
  IF NOT public.user_has_permission('billing.coverage.export') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.export' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN;
  END IF;

  IF p_admission_year IS NOT NULL THEN
    SELECT array_agg(ayr.id) INTO v_adm_year_ids
    FROM public.admission_years ayr
    WHERE ayr.year = p_admission_year;
  END IF;

  RETURN QUERY
  WITH target_year AS MATERIALIZED (
    SELECT t.institution_id, t.target_ay_id
    FROM public.fn_billing_coverage_target_years() t
  ),
  billing_inst AS (
    SELECT DISTINCT b.institution_id AS inst_id FROM public.billing_student_bills b
  ),
  scope AS (
    -- No lp.academic_year_id predicate — see get_billing_coverage_learners.
    SELECT lp.id, lp.institution_id, lp.academic_year_id, lp.program_id,
           lp.semester_id, lp.section_id, lp.lifecycle_status,
           lp.first_name, lp.last_name, lp.roll_number, lp.register_number
    FROM public.learners_profiles lp
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_billing_institutions
           OR lp.institution_id IN (SELECT inst_id FROM billing_inst))
      AND (p_admission_year IS NULL
           OR lp.admission_year_id = ANY(v_adm_year_ids))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
      AND (
        p_search IS NULL OR p_search = ''
        OR lp.roll_number ILIKE '%' || p_search || '%'
        OR lp.register_number ILIKE '%' || p_search || '%'
        OR (COALESCE(lp.first_name,'') || ' ' || COALESCE(lp.last_name,''))
             ILIKE '%' || p_search || '%'
      )
  ),
  live_bills AS (
    -- Was `p_academic_year_id IS NULL OR ...`, i.e. any year — which made the
    -- PDF disagree with the table for the very learners this fix is about.
    SELECT b.*
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    LEFT JOIN target_year ty ON ty.institution_id = s.institution_id
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
      AND (p_billing_category_id IS NULL OR b.item_category_id = p_billing_category_id)
      AND b.academic_year_id = COALESCE(p_academic_year_id, ty.target_ay_id)
  ),
  learner_state AS (
    SELECT s.id,
           COUNT(lb.id)::integer AS bill_count,
           COALESCE(SUM(lb.final_amount), 0)::numeric   AS total_amount,
           COALESCE(SUM(lb.final_amount - lb.balance_amount), 0)::numeric AS paid_amount,
           COALESCE(SUM(lb.balance_amount), 0)::numeric AS pending_amount
    FROM scope s
    LEFT JOIN live_bills lb ON lb.student_id = s.id
    GROUP BY s.id
  ),
  eligible AS (
    SELECT s.*, ls.bill_count, ls.total_amount, ls.paid_amount, ls.pending_amount
    FROM scope s
    JOIN learner_state ls ON ls.id = s.id
    WHERE p_coverage_state = 'all'
       OR (p_coverage_state = 'generated'     AND ls.bill_count > 0)
       OR (p_coverage_state = 'not_generated' AND ls.bill_count = 0)
  ),
  capped AS (
    SELECT e.*, i.name::text AS institution_name, p.program_name,
           CASE
             WHEN sem.semester_name IS NULL AND sec.section_name IS NULL THEN NULL
             WHEN sec.section_name IS NULL THEN sem.semester_name::text
             WHEN sem.semester_name IS NULL THEN sec.section_name::text
             ELSE sem.semester_name::text || ' · ' || sec.section_name::text
           END AS semester_section,
           COUNT(*) OVER ()::bigint AS learner_count
    FROM eligible e
    LEFT JOIN public.institutions i   ON i.id   = e.institution_id
    LEFT JOIN public.programs     p   ON p.id   = e.program_id
    LEFT JOIN public.semesters    sem ON sem.id = e.semester_id
    LEFT JOIN public.sections     sec ON sec.id = e.section_id
    ORDER BY i.name NULLS LAST, e.roll_number NULLS LAST, e.last_name, e.first_name
    LIMIT v_cap
  )
  SELECT c.id,
         c.roll_number::text,
         c.register_number::text,
         TRIM(COALESCE(c.first_name,'') || ' ' || COALESCE(c.last_name,'')),
         c.institution_name,
         c.program_name,
         c.semester_section,
         c.lifecycle_status::text,
         c.total_amount,
         c.paid_amount,
         c.pending_amount,
         lb.id,
         lb.bill_description::text,
         cat.category_name::text,
         -- 59 live bills carry no academic year; label rather than drop the row.
         COALESCE(ay.academic_year_name::text, '—'),
         lb.due_date,
         lb.status::text,
         lb.final_amount,
         (lb.final_amount - lb.balance_amount),
         lb.balance_amount,
         c.learner_count
  FROM capped c
  LEFT JOIN live_bills lb              ON lb.student_id = c.id
  LEFT JOIN public.billing_categories cat ON cat.id = lb.item_category_id
  LEFT JOIN public.academic_years ay    ON ay.id  = lb.academic_year_id
  ORDER BY c.institution_name NULLS LAST, c.roll_number NULLS LAST,
           lb.due_date NULLS LAST, lb.bill_description;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_billing_coverage_learner_bills(
  uuid, uuid[], text[], uuid, text, boolean, text, uuid[], text, text,
  uuid, uuid, uuid, uuid, uuid, integer, integer)
  FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_billing_coverage_learner_bills(
  uuid, uuid[], text[], uuid, text, boolean, text, uuid[], text, text,
  uuid, uuid, uuid, uuid, uuid, integer, integer)
  TO authenticated, service_role;

-- No new indexes: learners_profiles.admission_year_id already carries
-- idx_learners_profiles_admission_year_id, and the cohort→ids lookup reads a
-- ~44-row table once per call.



-- ============================================================================
-- Bill Coverage: Audit tab — two data-integrity checks over tuition billing
-- ============================================================================
-- Adds four read-only RPCs behind the EXISTING billing.coverage.view key. No
-- new permission key is introduced: a key only "exists" for a role once it is
-- in that role's custom_roles.permissions JSONB, so a new key would need its
-- own grant migration and would render this tab empty until it ran.
--
-- AUDIT A — "missing year bills"
--   A learner admitted in cohort Y should carry one tuition bill for every
--   academic year from Y up to their institution's current year. Some learners
--   only ever got the CURRENT year's bill and never the ones for the years
--   between their admission and today.
--
-- AUDIT B — "duplicate year bills"
--   At most ONE tuition-kind bill may exist per learner per academic year.
--   A multi-year fee plan generated in one run stamps every instalment with the
--   academic year current AT GENERATION TIME, landing 2-3 years of tuition in
--   one academic year (audited 2026-08-11: 842 combos, since repaired to 19).
--   That also inflates fn_learner_band_academic_fee() and can grant a costlier
--   hostel room category, so this is not a cosmetic check.
--
-- ── THREE MODELLING DECISIONS THAT ARE LOAD-BEARING ────────────────────────
--
-- 1. YEARS ARE COMPARED AS THE INTEGER START YEAR, NEVER AS academic_year_id.
--    academic_years holds one row per (institution, year) AND institutions
--    carry duplicate rows on the same start_date — JKKN Dental has an active
--    '2025-2026' beside an inactive '2025-2026 Additional 1'. A bill stamped
--    against the "Additional" row covers the same session; keying on the uuid
--    would report it as a gap. EXTRACT(YEAR FROM start_date) folds them.
--
-- 2. A YEAR IS ONLY "EXPECTED" IF AN ACTIVE academic_years ROW EXISTS FOR IT.
--    Academic-year coverage is sparse and differs per college (Allied Health
--    begins at 2024-2025, Pharmacy at 2021-2022). Expecting a bill for a
--    session the institution never opened would manufacture gaps.
--
-- 3. THE INSTITUTION GUARD IS TUITION-SPECIFIC, NOT "HAS ANY BILL".
--    The coverage page's p_include_non_billing_institutions tests for a bill of
--    ANY kind. JKKN College of Arts and Science (Aided) has 24 transport bills
--    and has never raised a single tuition bill — it passes that test and would
--    inject 490 phantom gaps. Hence p_include_non_tuition_institutions.
--
-- The upper bound reuses fn_billing_coverage_target_years() rather than
-- re-deriving "the current year". That resolver is deliberately "greatest
-- start_date <= today among is_active rows" and NOT a BETWEEN on end_date,
-- because the Jun 1 -> Mar 31 convention leaves Apr-May covered by no row.
-- A second, subtly different notion of "now" on the same page would be a bug
-- generator. See 20260808120000_billing_coverage_target_academic_year.sql.
-- ============================================================================

-- ── A: summary (KPI cards + the Earliest Academic Year option list) ─────────
CREATE OR REPLACE FUNCTION public.get_billing_audit_missing_years_summary(
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_include_non_tuition_institutions boolean DEFAULT false,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_admission_year integer DEFAULT NULL::integer,
  p_earliest_academic_year integer DEFAULT NULL::integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst         uuid[];
  v_adm_year_ids uuid[];
  v_result       jsonb;
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN jsonb_build_object(
      'in_scope', 0, 'gap', 0, 'complete', 0, 'cannot_evaluate', 0,
      'missing_slots', 0, 'backlog_only', 0, 'no_tuition_at_all', 0,
      'excluded_institutions', 0, 'excluded_learners', 0,
      'by_institution', '[]'::jsonb, 'available_academic_years', '[]'::jsonb);
  END IF;

  IF p_admission_year IS NOT NULL THEN
    SELECT array_agg(ayr.id) INTO v_adm_year_ids
    FROM public.admission_years ayr WHERE ayr.year = p_admission_year;
  END IF;

  WITH tuition_inst AS MATERIALIZED (
    SELECT DISTINCT b.institution_id AS inst_id
    FROM public.billing_student_bills b
    JOIN public.billing_categories bc ON bc.id = b.item_category_id
    WHERE bc.kind = 'tuition'
      AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
  ),
  target AS MATERIALIZED (
    SELECT t.institution_id, EXTRACT(YEAR FROM ay.start_date)::int AS ceiling_yr
    FROM public.fn_billing_coverage_target_years() t
    JOIN public.academic_years ay ON ay.id = t.target_ay_id
  ),
  inst_years AS MATERIALIZED (
    SELECT DISTINCT ay.institution_id, EXTRACT(YEAR FROM ay.start_date)::int AS yr
    FROM public.academic_years ay WHERE ay.is_active IS TRUE
  ),
  all_scope AS MATERIALIZED (
    SELECT lp.id, lp.institution_id, adm.year AS cohort, t.ceiling_yr,
           (lp.institution_id IN (SELECT inst_id FROM tuition_inst)) AS is_tuition_inst
    FROM public.learners_profiles lp
    LEFT JOIN public.admission_years adm ON adm.id = lp.admission_year_id
    LEFT JOIN target t ON t.institution_id = lp.institution_id
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_admission_year IS NULL OR lp.admission_year_id = ANY(v_adm_year_ids))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
  ),
  scope AS MATERIALIZED (
    SELECT * FROM all_scope
    WHERE p_include_non_tuition_institutions OR is_tuition_inst
  ),
  covered AS MATERIALIZED (
    SELECT DISTINCT b.student_id,
           EXTRACT(YEAR FROM ay.start_date)::int AS yr
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    JOIN public.billing_categories bc ON bc.id = b.item_category_id AND bc.kind = 'tuition'
    JOIN public.academic_years ay ON ay.id = b.academic_year_id
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
  ),
  years AS (
    SELECT s.id AS learner_id, iy.yr, s.ceiling_yr,
           (c.student_id IS NOT NULL) AS is_covered
    FROM scope s
    JOIN inst_years iy ON iy.institution_id = s.institution_id
     AND iy.yr BETWEEN GREATEST(s.cohort, COALESCE(p_earliest_academic_year, s.cohort))
                   AND s.ceiling_yr
    LEFT JOIN covered c ON c.student_id = s.id AND c.yr = iy.yr
    WHERE s.cohort IS NOT NULL AND s.ceiling_yr IS NOT NULL
  ),
  per_learner AS (
    SELECT y.learner_id,
           COUNT(*) FILTER (WHERE y.is_covered)::int     AS billed_years,
           COUNT(*) FILTER (WHERE NOT y.is_covered)::int AS missing_years,
           bool_or(y.yr = y.ceiling_yr AND y.is_covered) AS has_current_year
    FROM years y GROUP BY y.learner_id
  ),
  stated AS (
    SELECT s.institution_id,
           COALESCE(pl.missing_years, 0)   AS missing_years,
           COALESCE(pl.billed_years, 0)    AS billed_years,
           COALESCE(pl.has_current_year, false) AS has_current_year,
           CASE
             WHEN s.cohort IS NULL OR s.ceiling_yr IS NULL THEN 'cannot_evaluate'
             WHEN COALESCE(pl.missing_years, 0) > 0        THEN 'gap'
             ELSE 'complete'
           END AS audit_state
    FROM scope s
    LEFT JOIN per_learner pl ON pl.learner_id = s.id
  )
  SELECT jsonb_build_object(
    'in_scope',        (SELECT COUNT(*) FROM stated),
    'gap',             (SELECT COUNT(*) FROM stated WHERE audit_state = 'gap'),
    'complete',        (SELECT COUNT(*) FROM stated WHERE audit_state = 'complete'),
    'cannot_evaluate', (SELECT COUNT(*) FROM stated WHERE audit_state = 'cannot_evaluate'),
    -- The unit of work: one missing (learner, academic year) pair = one bill to
    -- raise. Always larger than the learner count, so the two are labelled apart.
    'missing_slots',   (SELECT COALESCE(SUM(missing_years), 0) FROM stated),
    -- The reported symptom: this year's bill exists, an earlier one does not.
    'backlog_only',    (SELECT COUNT(*) FROM stated
                        WHERE audit_state = 'gap' AND has_current_year),
    'no_tuition_at_all', (SELECT COUNT(*) FROM stated
                          WHERE audit_state = 'gap' AND billed_years = 0),
    'excluded_institutions',
      (SELECT COUNT(DISTINCT institution_id) FROM all_scope WHERE NOT is_tuition_inst),
    'excluded_learners',
      (SELECT COUNT(*) FROM all_scope WHERE NOT is_tuition_inst),
    'by_institution', COALESCE((
      SELECT jsonb_agg(x ORDER BY x->>'institution_name')
      FROM (
        SELECT jsonb_build_object(
                 'institution_id',   st.institution_id,
                 'institution_name', COALESCE(i.name::text, 'Unknown'),
                 'in_scope',         COUNT(*),
                 'gap',              COUNT(*) FILTER (WHERE st.audit_state = 'gap'),
                 'missing_slots',    COALESCE(SUM(st.missing_years), 0)
               ) AS x
        FROM stated st
        LEFT JOIN public.institutions i ON i.id = st.institution_id
        GROUP BY st.institution_id, i.name
      ) sub
    ), '[]'::jsonb),
    -- Feeds the "Earliest Academic Year" dropdown. Computed UNFILTERED by
    -- p_earliest_academic_year on purpose: a control must not remove its own
    -- options once used. Integer years, so the list composes across colleges.
    'available_academic_years', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'year',  yr,
               'label', yr::text || '-' || (yr + 1)::text) ORDER BY yr DESC)
      FROM (
        SELECT DISTINCT EXTRACT(YEAR FROM ay.start_date)::int AS yr
        FROM public.academic_years ay
        WHERE ay.institution_id = ANY(v_inst)
          AND ay.is_active IS TRUE
          AND ay.start_date <= CURRENT_DATE
      ) ys
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_billing_audit_missing_years_summary(
  uuid[], text[], boolean, uuid[], text, text, uuid, uuid, uuid, uuid, uuid,
  integer, integer) FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_billing_audit_missing_years_summary(
  uuid[], text[], boolean, uuid[], text, text, uuid, uuid, uuid, uuid, uuid,
  integer, integer) TO authenticated, service_role;

-- ── A: learners list ───────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.get_billing_audit_missing_years(
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_include_non_tuition_institutions boolean DEFAULT false,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_admission_year integer DEFAULT NULL::integer,
  p_earliest_academic_year integer DEFAULT NULL::integer,
  p_audit_state text DEFAULT 'gap'::text,
  p_search text DEFAULT NULL::text,
  p_page integer DEFAULT 1,
  p_page_size integer DEFAULT 50,
  p_sort_by text DEFAULT NULL::text,
  p_sort_dir text DEFAULT 'asc'::text
)
RETURNS TABLE(
  out_learner_id uuid, out_roll_number text, out_register_number text,
  out_full_name text, out_lifecycle_status text, out_gender text,
  out_institution_id uuid, out_institution_name text, out_program_name text,
  out_semester_section text, out_admission_year integer,
  out_expected_years integer, out_billed_years integer, out_missing_years integer,
  out_missing_year_names text, out_first_missing_year text,
  out_has_current_year boolean, out_tuition_bill_count integer,
  out_total_billed numeric, out_total_paid numeric,
  out_unassigned_tuition_bills integer, out_audit_state text,
  out_total_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst   uuid[];
  -- Capped at 5000, not the coverage list's 200: the table's "Export all pages"
  -- fetches the whole filtered set in ONE call rather than paging 24 times.
  v_limit  integer := LEAST(GREATEST(COALESCE(NULLIF(p_page_size, 0), 50), 1), 5000);
  v_offset integer := GREATEST(COALESCE(p_page, 1) - 1, 0)
                      * LEAST(GREATEST(COALESCE(NULLIF(p_page_size, 0), 50), 1), 5000);
  v_asc    boolean := COALESCE(LOWER(p_sort_dir), 'asc') <> 'desc';
  v_adm_year_ids uuid[];
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN;
  END IF;

  IF p_admission_year IS NOT NULL THEN
    SELECT array_agg(ayr.id) INTO v_adm_year_ids
    FROM public.admission_years ayr WHERE ayr.year = p_admission_year;
  END IF;

  RETURN QUERY
  WITH tuition_inst AS MATERIALIZED (
    SELECT DISTINCT b.institution_id AS inst_id
    FROM public.billing_student_bills b
    JOIN public.billing_categories bc ON bc.id = b.item_category_id
    WHERE bc.kind = 'tuition'
      AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
  ),
  target AS MATERIALIZED (
    SELECT t.institution_id, EXTRACT(YEAR FROM ay.start_date)::int AS ceiling_yr
    FROM public.fn_billing_coverage_target_years() t
    JOIN public.academic_years ay ON ay.id = t.target_ay_id
  ),
  inst_years AS MATERIALIZED (
    SELECT DISTINCT ay.institution_id, EXTRACT(YEAR FROM ay.start_date)::int AS yr
    FROM public.academic_years ay WHERE ay.is_active IS TRUE
  ),
  scope AS MATERIALIZED (
    SELECT lp.id, lp.institution_id, lp.program_id, lp.semester_id, lp.section_id,
           lp.gender, lp.lifecycle_status, lp.first_name, lp.last_name,
           lp.roll_number, lp.register_number, lp.accommodation_type_id,
           adm.year AS cohort, t.ceiling_yr
    FROM public.learners_profiles lp
    LEFT JOIN public.admission_years adm ON adm.id = lp.admission_year_id
    LEFT JOIN target t ON t.institution_id = lp.institution_id
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_tuition_institutions
           OR lp.institution_id IN (SELECT inst_id FROM tuition_inst))
      AND (p_admission_year IS NULL OR lp.admission_year_id = ANY(v_adm_year_ids))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
      AND (
        p_search IS NULL OR p_search = ''
        OR lp.roll_number ILIKE '%' || p_search || '%'
        OR lp.register_number ILIKE '%' || p_search || '%'
        OR (COALESCE(lp.first_name,'') || ' ' || COALESCE(lp.last_name,''))
             ILIKE '%' || p_search || '%'
      )
  ),
  covered AS MATERIALIZED (
    SELECT DISTINCT b.student_id, EXTRACT(YEAR FROM ay.start_date)::int AS yr
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    JOIN public.billing_categories bc ON bc.id = b.item_category_id AND bc.kind = 'tuition'
    JOIN public.academic_years ay ON ay.id = b.academic_year_id
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
  ),
  bill_stats AS MATERIALIZED (
    -- Every live tuition bill the learner holds, across ALL years. Context for
    -- the row, deliberately not restricted to the audited window.
    SELECT b.student_id,
           COUNT(*)::integer AS tuition_bill_count,
           COALESCE(SUM(b.final_amount), 0)::numeric AS total_billed,
           COALESCE(SUM(b.final_amount - COALESCE(b.balance_amount, 0)), 0)::numeric
             AS total_paid,
           -- Tuition bills carrying no academic year at all. They can never
           -- satisfy a year check, so a learner could read as a clean gap while
           -- the bill exists — surfaced rather than silently ignored.
           COUNT(*) FILTER (WHERE b.academic_year_id IS NULL)::integer
             AS unassigned_tuition_bills
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    JOIN public.billing_categories bc ON bc.id = b.item_category_id AND bc.kind = 'tuition'
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
    GROUP BY b.student_id
  ),
  years AS (
    SELECT s.id AS learner_id, iy.yr, s.ceiling_yr,
           (c.student_id IS NOT NULL) AS is_covered
    FROM scope s
    JOIN inst_years iy ON iy.institution_id = s.institution_id
     AND iy.yr BETWEEN GREATEST(s.cohort, COALESCE(p_earliest_academic_year, s.cohort))
                   AND s.ceiling_yr
    LEFT JOIN covered c ON c.student_id = s.id AND c.yr = iy.yr
    WHERE s.cohort IS NOT NULL AND s.ceiling_yr IS NOT NULL
  ),
  per_learner AS (
    SELECT y.learner_id,
           COUNT(*)::integer                             AS expected_years,
           COUNT(*) FILTER (WHERE y.is_covered)::integer AS billed_years,
           COUNT(*) FILTER (WHERE NOT y.is_covered)::integer AS missing_years,
           string_agg(y.yr::text || '-' || (y.yr + 1)::text, ', ' ORDER BY y.yr)
             FILTER (WHERE NOT y.is_covered)             AS missing_year_names,
           MIN(y.yr) FILTER (WHERE NOT y.is_covered)     AS first_missing_yr,
           bool_or(y.yr = y.ceiling_yr AND y.is_covered) AS has_current_year
    FROM years y GROUP BY y.learner_id
  ),
  final AS (
    SELECT s.id AS learner_id,
           s.roll_number::text     AS roll_number,
           s.register_number::text AS register_number,
           TRIM(COALESCE(s.first_name,'') || ' ' || COALESCE(s.last_name,''))
                                   AS full_name,
           s.lifecycle_status::text AS lifecycle_status,
           NULLIF(TRIM(s.gender), '')::text AS gender,
           s.institution_id        AS institution_id,
           i.name::text            AS institution_name,
           p.program_name          AS program_name,
           CASE
             WHEN sem.semester_name IS NULL AND sec.section_name IS NULL THEN NULL
             WHEN sec.section_name IS NULL THEN sem.semester_name::text
             WHEN sem.semester_name IS NULL THEN sec.section_name::text
             ELSE sem.semester_name::text || ' · ' || sec.section_name::text
           END                     AS semester_section,
           s.cohort                AS admission_year,
           COALESCE(pl.expected_years, 0) AS expected_years,
           COALESCE(pl.billed_years, 0)   AS billed_years,
           COALESCE(pl.missing_years, 0)  AS missing_years,
           pl.missing_year_names   AS missing_year_names,
           CASE WHEN pl.first_missing_yr IS NULL THEN NULL
                ELSE pl.first_missing_yr::text || '-' || (pl.first_missing_yr + 1)::text
           END                     AS first_missing_year,
           COALESCE(pl.has_current_year, false) AS has_current_year,
           COALESCE(bs.tuition_bill_count, 0)   AS tuition_bill_count,
           COALESCE(bs.total_billed, 0)::numeric AS total_billed,
           COALESCE(bs.total_paid, 0)::numeric   AS total_paid,
           COALESCE(bs.unassigned_tuition_bills, 0) AS unassigned_tuition_bills,
           CASE
             -- No cohort on file, or an institution with no active academic
             -- year that has started: an unknown, never a confirmed gap.
             WHEN s.cohort IS NULL OR s.ceiling_yr IS NULL THEN 'cannot_evaluate'
             WHEN COALESCE(pl.missing_years, 0) > 0        THEN 'gap'
             ELSE 'complete'
           END                     AS audit_state
    FROM scope s
    LEFT JOIN per_learner pl              ON pl.learner_id = s.id
    LEFT JOIN bill_stats  bs              ON bs.student_id = s.id
    LEFT JOIN public.institutions i       ON i.id   = s.institution_id
    LEFT JOIN public.programs     p       ON p.id   = s.program_id
    LEFT JOIN public.semesters    sem     ON sem.id = s.semester_id
    LEFT JOIN public.sections     sec     ON sec.id = s.section_id
  ),
  filtered AS (
    SELECT * FROM final f
    WHERE COALESCE(p_audit_state, 'gap') = 'all'
       OR f.audit_state = COALESCE(p_audit_state, 'gap')
  )
  SELECT f.learner_id, f.roll_number, f.register_number, f.full_name,
         f.lifecycle_status, f.gender, f.institution_id, f.institution_name,
         f.program_name, f.semester_section, f.admission_year,
         f.expected_years, f.billed_years, f.missing_years,
         f.missing_year_names, f.first_missing_year, f.has_current_year,
         f.tuition_bill_count, f.total_billed, f.total_paid,
         f.unassigned_tuition_bills, f.audit_state,
         COUNT(*) OVER ()::bigint
  FROM filtered f
  ORDER BY
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'gender'             THEN f.gender
         WHEN 'first_missing_year' THEN f.first_missing_year
         WHEN 'audit_state'        THEN f.audit_state
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'gender'             THEN f.gender
         WHEN 'first_missing_year' THEN f.first_missing_year
         WHEN 'audit_state'        THEN f.audit_state
       END
     END) DESC NULLS LAST,
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'admission_year'      THEN f.admission_year::numeric
         WHEN 'expected_years'      THEN f.expected_years::numeric
         WHEN 'billed_years'        THEN f.billed_years::numeric
         WHEN 'missing_years'       THEN f.missing_years::numeric
         WHEN 'tuition_bill_count'  THEN f.tuition_bill_count::numeric
         WHEN 'total_billed'        THEN f.total_billed
         WHEN 'total_paid'          THEN f.total_paid
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'admission_year'      THEN f.admission_year::numeric
         WHEN 'expected_years'      THEN f.expected_years::numeric
         WHEN 'billed_years'        THEN f.billed_years::numeric
         WHEN 'missing_years'       THEN f.missing_years::numeric
         WHEN 'tuition_bill_count'  THEN f.tuition_bill_count::numeric
         WHEN 'total_billed'        THEN f.total_billed
         WHEN 'total_paid'          THEN f.total_paid
       END
     END) DESC NULLS LAST,
    -- Default order puts the worst backlogs first: this screen is a work queue.
    f.missing_years DESC, f.institution_name NULLS LAST,
    f.roll_number NULLS LAST, f.full_name
  LIMIT v_limit OFFSET v_offset;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_billing_audit_missing_years(
  uuid[], text[], boolean, uuid[], text, text, uuid, uuid, uuid, uuid, uuid,
  integer, integer, text, text, integer, integer, text, text)
  FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_billing_audit_missing_years(
  uuid[], text[], boolean, uuid[], text, text, uuid, uuid, uuid, uuid, uuid,
  integer, integer, text, text, integer, integer, text, text)
  TO authenticated, service_role;

-- ── B: summary ─────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.get_billing_audit_duplicate_years_summary(
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_include_non_tuition_institutions boolean DEFAULT false,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_admission_year integer DEFAULT NULL::integer,
  p_earliest_academic_year integer DEFAULT NULL::integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst         uuid[];
  v_adm_year_ids uuid[];
  v_result       jsonb;
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN jsonb_build_object(
      'combos', 0, 'learners', 0, 'bills', 0, 'extra_bills', 0,
      'total_billed', 0, 'outstanding', 0, 'generator_signature', 0,
      'unassigned_tuition_bills', 0, 'by_institution', '[]'::jsonb);
  END IF;

  IF p_admission_year IS NOT NULL THEN
    SELECT array_agg(ayr.id) INTO v_adm_year_ids
    FROM public.admission_years ayr WHERE ayr.year = p_admission_year;
  END IF;

  WITH tuition_inst AS MATERIALIZED (
    SELECT DISTINCT b.institution_id AS inst_id
    FROM public.billing_student_bills b
    JOIN public.billing_categories bc ON bc.id = b.item_category_id
    WHERE bc.kind = 'tuition'
      AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
  ),
  scope AS MATERIALIZED (
    SELECT lp.id, lp.institution_id
    FROM public.learners_profiles lp
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_tuition_institutions
           OR lp.institution_id IN (SELECT inst_id FROM tuition_inst))
      AND (p_admission_year IS NULL OR lp.admission_year_id = ANY(v_adm_year_ids))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
  ),
  dup AS (
    SELECT s.id AS learner_id, s.institution_id,
           COUNT(*)::integer AS bill_count,
           SUM(b.final_amount)::numeric AS total_billed,
           SUM(COALESCE(b.balance_amount, 0))::numeric AS outstanding,
           -- The 2026-08-11 generator signature: one run stamped every
           -- instalment with the year current at generation time, so the bills
           -- share a creation date while their due dates fall years apart.
           (COUNT(DISTINCT b.created_at::date) = 1
            AND COUNT(DISTINCT EXTRACT(YEAR FROM b.due_date)) > 1) AS is_generator_artefact
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    JOIN public.billing_categories bc ON bc.id = b.item_category_id AND bc.kind = 'tuition'
    JOIN public.academic_years ay ON ay.id = b.academic_year_id
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
      AND (p_earliest_academic_year IS NULL
           OR EXTRACT(YEAR FROM ay.start_date)::int >= p_earliest_academic_year)
    GROUP BY s.id, s.institution_id, EXTRACT(YEAR FROM ay.start_date)::int
    HAVING COUNT(*) > 1
  )
  SELECT jsonb_build_object(
    'combos',       (SELECT COUNT(*) FROM dup),
    'learners',     (SELECT COUNT(DISTINCT learner_id) FROM dup),
    'bills',        (SELECT COALESCE(SUM(bill_count), 0) FROM dup),
    -- What actually has to be removed: every bill past the first in each year.
    'extra_bills',  (SELECT COALESCE(SUM(bill_count - 1), 0) FROM dup),
    'total_billed', (SELECT COALESCE(SUM(total_billed), 0) FROM dup),
    'outstanding',  (SELECT COALESCE(SUM(outstanding), 0) FROM dup),
    'generator_signature',
      (SELECT COUNT(*) FROM dup WHERE is_generator_artefact),
    -- Not a duplicate, but the same blind spot: a tuition bill with no academic
    -- year belongs to no group and can never be caught by this check.
    'unassigned_tuition_bills', (
      SELECT COUNT(*)
      FROM public.billing_student_bills b
      JOIN scope s ON s.id = b.student_id
      JOIN public.billing_categories bc ON bc.id = b.item_category_id AND bc.kind = 'tuition'
      WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
        AND b.academic_year_id IS NULL
    ),
    'by_institution', COALESCE((
      SELECT jsonb_agg(x ORDER BY x->>'institution_name')
      FROM (
        SELECT jsonb_build_object(
                 'institution_id',   d.institution_id,
                 'institution_name', COALESCE(i.name::text, 'Unknown'),
                 'combos',           COUNT(*),
                 'learners',         COUNT(DISTINCT d.learner_id),
                 'extra_bills',      COALESCE(SUM(d.bill_count - 1), 0)
               ) AS x
        FROM dup d
        LEFT JOIN public.institutions i ON i.id = d.institution_id
        GROUP BY d.institution_id, i.name
      ) sub
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_billing_audit_duplicate_years_summary(
  uuid[], text[], boolean, uuid[], text, text, uuid, uuid, uuid, uuid, uuid,
  integer, integer) FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_billing_audit_duplicate_years_summary(
  uuid[], text[], boolean, uuid[], text, text, uuid, uuid, uuid, uuid, uuid,
  integer, integer) TO authenticated, service_role;

-- ── B: list, one row per (learner, academic year) ──────────────────────────
CREATE OR REPLACE FUNCTION public.get_billing_audit_duplicate_years(
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_include_non_tuition_institutions boolean DEFAULT false,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_admission_year integer DEFAULT NULL::integer,
  p_earliest_academic_year integer DEFAULT NULL::integer,
  p_search text DEFAULT NULL::text,
  p_page integer DEFAULT 1,
  p_page_size integer DEFAULT 50,
  p_sort_by text DEFAULT NULL::text,
  p_sort_dir text DEFAULT 'asc'::text
)
RETURNS TABLE(
  out_audit_row_id text, out_learner_id uuid, out_roll_number text,
  out_register_number text, out_full_name text, out_lifecycle_status text,
  out_institution_id uuid, out_institution_name text, out_program_name text,
  out_semester_section text, out_admission_year integer,
  out_academic_year_name text, out_bill_count integer, out_category_names text,
  out_total_billed numeric, out_total_paid numeric, out_outstanding numeric,
  out_created_same_day boolean, out_due_year_span integer,
  out_total_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst   uuid[];
  v_limit  integer := LEAST(GREATEST(COALESCE(NULLIF(p_page_size, 0), 50), 1), 5000);
  v_offset integer := GREATEST(COALESCE(p_page, 1) - 1, 0)
                      * LEAST(GREATEST(COALESCE(NULLIF(p_page_size, 0), 50), 1), 5000);
  v_asc    boolean := COALESCE(LOWER(p_sort_dir), 'asc') <> 'desc';
  v_adm_year_ids uuid[];
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN;
  END IF;

  IF p_admission_year IS NOT NULL THEN
    SELECT array_agg(ayr.id) INTO v_adm_year_ids
    FROM public.admission_years ayr WHERE ayr.year = p_admission_year;
  END IF;

  RETURN QUERY
  WITH tuition_inst AS MATERIALIZED (
    SELECT DISTINCT b.institution_id AS inst_id
    FROM public.billing_student_bills b
    JOIN public.billing_categories bc ON bc.id = b.item_category_id
    WHERE bc.kind = 'tuition'
      AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
  ),
  scope AS MATERIALIZED (
    SELECT lp.id, lp.institution_id, lp.program_id, lp.semester_id, lp.section_id,
           lp.lifecycle_status, lp.first_name, lp.last_name, lp.roll_number,
           lp.register_number, adm.year AS cohort
    FROM public.learners_profiles lp
    LEFT JOIN public.admission_years adm ON adm.id = lp.admission_year_id
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_tuition_institutions
           OR lp.institution_id IN (SELECT inst_id FROM tuition_inst))
      AND (p_admission_year IS NULL OR lp.admission_year_id = ANY(v_adm_year_ids))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
      AND (
        p_search IS NULL OR p_search = ''
        OR lp.roll_number ILIKE '%' || p_search || '%'
        OR lp.register_number ILIKE '%' || p_search || '%'
        OR (COALESCE(lp.first_name,'') || ' ' || COALESCE(lp.last_name,''))
             ILIKE '%' || p_search || '%'
      )
  ),
  dup AS (
    -- Grouped on the AY's START YEAR, not academic_year_id: two bills stamped
    -- '2025-2026' and '2025-2026 Additional 1' are two bills for one session.
    SELECT b.student_id AS learner_id,
           EXTRACT(YEAR FROM ay.start_date)::integer AS yr,
           COUNT(*)::integer AS bill_count,
           string_agg(DISTINCT bc.category_name::text, ', '
                      ORDER BY bc.category_name::text) AS category_names,
           SUM(b.final_amount)::numeric AS total_billed,
           SUM(b.final_amount - COALESCE(b.balance_amount, 0))::numeric AS total_paid,
           SUM(COALESCE(b.balance_amount, 0))::numeric AS outstanding,
           (COUNT(DISTINCT b.created_at::date) = 1) AS created_same_day,
           COUNT(DISTINCT EXTRACT(YEAR FROM b.due_date))::integer AS due_year_span
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    JOIN public.billing_categories bc ON bc.id = b.item_category_id AND bc.kind = 'tuition'
    JOIN public.academic_years ay ON ay.id = b.academic_year_id
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
      AND (p_earliest_academic_year IS NULL
           OR EXTRACT(YEAR FROM ay.start_date)::int >= p_earliest_academic_year)
    GROUP BY b.student_id, EXTRACT(YEAR FROM ay.start_date)::integer
    HAVING COUNT(*) > 1
  ),
  final AS (
    SELECT (s.id::text || ':' || d.yr::text) AS audit_row_id,
           s.id AS learner_id,
           s.roll_number::text     AS roll_number,
           s.register_number::text AS register_number,
           TRIM(COALESCE(s.first_name,'') || ' ' || COALESCE(s.last_name,''))
                                   AS full_name,
           s.lifecycle_status::text AS lifecycle_status,
           s.institution_id        AS institution_id,
           i.name::text            AS institution_name,
           p.program_name          AS program_name,
           CASE
             WHEN sem.semester_name IS NULL AND sec.section_name IS NULL THEN NULL
             WHEN sec.section_name IS NULL THEN sem.semester_name::text
             WHEN sem.semester_name IS NULL THEN sec.section_name::text
             ELSE sem.semester_name::text || ' · ' || sec.section_name::text
           END                     AS semester_section,
           s.cohort                AS admission_year,
           (d.yr::text || '-' || (d.yr + 1)::text) AS academic_year_name,
           d.bill_count, d.category_names, d.total_billed, d.total_paid,
           d.outstanding, d.created_same_day, d.due_year_span
    FROM dup d
    JOIN scope s ON s.id = d.learner_id
    LEFT JOIN public.institutions i   ON i.id   = s.institution_id
    LEFT JOIN public.programs     p   ON p.id   = s.program_id
    LEFT JOIN public.semesters    sem ON sem.id = s.semester_id
    LEFT JOIN public.sections     sec ON sec.id = s.section_id
  )
  SELECT f.audit_row_id, f.learner_id, f.roll_number, f.register_number,
         f.full_name, f.lifecycle_status, f.institution_id, f.institution_name,
         f.program_name, f.semester_section, f.admission_year,
         f.academic_year_name, f.bill_count, f.category_names,
         f.total_billed, f.total_paid, f.outstanding,
         f.created_same_day, f.due_year_span,
         COUNT(*) OVER ()::bigint
  FROM final f
  ORDER BY
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'academic_year_name' THEN f.academic_year_name
         WHEN 'category_names'     THEN f.category_names
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'academic_year_name' THEN f.academic_year_name
         WHEN 'category_names'     THEN f.category_names
       END
     END) DESC NULLS LAST,
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'admission_year' THEN f.admission_year::numeric
         WHEN 'bill_count'     THEN f.bill_count::numeric
         WHEN 'total_billed'   THEN f.total_billed
         WHEN 'total_paid'     THEN f.total_paid
         WHEN 'outstanding'    THEN f.outstanding
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'admission_year' THEN f.admission_year::numeric
         WHEN 'bill_count'     THEN f.bill_count::numeric
         WHEN 'total_billed'   THEN f.total_billed
         WHEN 'total_paid'     THEN f.total_paid
         WHEN 'outstanding'    THEN f.outstanding
       END
     END) DESC NULLS LAST,
    f.bill_count DESC, f.institution_name NULLS LAST,
    f.roll_number NULLS LAST, f.academic_year_name
  LIMIT v_limit OFFSET v_offset;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_billing_audit_duplicate_years(
  uuid[], text[], boolean, uuid[], text, text, uuid, uuid, uuid, uuid, uuid,
  integer, integer, text, integer, integer, text, text)
  FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_billing_audit_duplicate_years(
  uuid[], text[], boolean, uuid[], text, text, uuid, uuid, uuid, uuid, uuid,
  integer, integer, text, integer, integer, text, text)
  TO authenticated, service_role;

-- No new indexes. Both audits read the same columns the coverage RPCs already
-- drive off: billing_student_bills(student_id), (academic_year_id),
-- learners_profiles(institution_id, admission_year_id). billing_categories is a
-- 30-row lookup scanned once per call.


-- ============================================================================
-- Bill Coverage: bound the audited window by the PROGRAMME's duration
-- ============================================================================
-- Both the Coverage tab and the Audit tab assumed a learner should be billed for
-- every academic year from their admission cohort up to their institution's
-- current year. Nothing bounded that by how long the course actually runs, so a
-- cohort that has finished kept accruing expected years forever.
--
--   PHARMD cohort 2020 is a 6-year course running 2020-21 .. 2025-26, yet the
--   audit listed 2026-27 as a missing bill. Pointing the Coverage tab at
--   Pharmacy 2027-2028 reported 191 of the first 200 learners "Not generated",
--   including cohorts that finished two years earlier.
--
-- This migration covers the three COVERAGE RPCs. The four AUDIT RPCs follow in
-- 20260812170100.
--
-- ── THE RULE ───────────────────────────────────────────────────────────────
--   programme_end_year = cohort_year + CEIL(program_duration_yrs) - 1
--
-- CEIL, never a truncation. program_duration_yrs is NUMERIC and ten learners sit
-- in a 1.5-year programme; one starting in 2025 still spans 2025-26 AND 2026-27.
-- Truncating would end the programme a year early and HIDE a genuine missing
-- bill — a false negative, the worse direction of error on this screen.
--
-- ── WHY THE DURATION IS NOT DERIVED ────────────────────────────────────────
-- programs.program_duration_yrs is the only trustworthy source. Both plausible
-- fallbacks were tested and both fail in the dangerous direction:
--   * the `semesters` ladder disagrees with the configured value for 11
--     programmes (MDS reads 3 configured against 1 derived, because only a stub
--     semester row exists);
--   * deriving from billing history understates badly — BDS bills a modal 2
--     years but is a 5-year course.
-- A NULL duration therefore means "unbounded", exactly as before this change,
-- rather than a guess. 23 programmes covering 1,085 in-scope learners were still
-- blank when this shipped; the cap switches itself on per programme as those
-- are filled in.
--
-- ── WHY A NEW STATE RATHER THAN DROPPING THE LEARNER ───────────────────────
-- 'not_applicable' is assessed ONLY on rows that would otherwise be
-- 'not_generated':
--     has a live bill                              -> generated      (untouched)
--     no bill, measured year AFTER programme end   -> not_applicable (new)
--     no bill, measured year within the programme  -> not_generated
-- So in_scope is unchanged and `generated` never moves: the only figure that
-- shifts is not_generated, down by exactly the count that becomes
-- not_applicable (852 -> 742 group-wide at the time of writing). Anyone
-- reconciling the KPI cards can account for every learner. Silently shrinking
-- the population would make last month's report irreproducible, and this module
-- already keeps 'cannot_evaluate' visible rather than folding it into a gap.
--
-- ALL THREE RPCs MOVE TOGETHER. get_billing_coverage_learner_bills feeds the PDF
-- and once carried the opposite predicate to the table, so the same learner read
-- "Not generated" on screen and "generated" in the document (fixed 20260808120000).
-- A rule applied to two of the three would recreate that exact bug.
-- ============================================================================

-- ── Single source of truth for the window's upper bound ────────────────────
-- Deliberately IMMUTABLE with no search_path setting so Postgres can inline it
-- into the surrounding query rather than calling it per row.
CREATE OR REPLACE FUNCTION public.fn_programme_end_year(
  p_cohort_year integer,
  p_duration_yrs numeric
)
RETURNS integer
LANGUAGE sql
IMMUTABLE
AS $function$
  SELECT CASE
    -- NULL duration = not configured = unbounded, never a guessed default.
    -- A zero or negative duration is bad data; treat it the same way rather
    -- than producing an end year before the cohort started.
    WHEN p_cohort_year IS NULL OR p_duration_yrs IS NULL OR p_duration_yrs <= 0
      THEN NULL
    ELSE p_cohort_year + CEIL(p_duration_yrs)::integer - 1
  END;
$function$;

REVOKE ALL ON FUNCTION public.fn_programme_end_year(integer, numeric) FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_programme_end_year(integer, numeric)
  TO authenticated, service_role;

-- ── Learners list ──────────────────────────────────────────────────────────
-- DROP + CREATE, not CREATE OR REPLACE: the RETURNS TABLE gains two columns and
-- a return-type change cannot be replaced in place. Dropping discards the ACL
-- (EXECUTE reverts to PUBLIC, which includes anon), so the REVOKE/GRANT pair at
-- the end is load-bearing.
DROP FUNCTION IF EXISTS public.get_billing_coverage_learners(
  uuid, uuid[], text[], uuid, text, boolean, text, integer, integer,
  uuid[], text, text, text, text, uuid, uuid, uuid, uuid, uuid, integer);

CREATE FUNCTION public.get_billing_coverage_learners(
  p_academic_year_id uuid DEFAULT NULL::uuid,
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_billing_category_id uuid DEFAULT NULL::uuid,
  p_coverage_state text DEFAULT 'not_generated'::text,
  p_include_non_billing_institutions boolean DEFAULT false,
  p_search text DEFAULT NULL::text,
  p_page integer DEFAULT 1,
  p_page_size integer DEFAULT 50,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_sort_by text DEFAULT NULL::text,
  p_sort_dir text DEFAULT 'asc'::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_admission_year integer DEFAULT NULL::integer
)
RETURNS TABLE(
  out_learner_id uuid, out_roll_number text, out_register_number text,
  out_full_name text, out_lifecycle_status text, out_gender text,
  out_institution_id uuid, out_institution_name text, out_program_name text,
  out_semester_section text, out_academic_year_id uuid,
  out_academic_year_name text, out_admission_year integer,
  out_accommodation_type text, out_uses_transport boolean,
  out_bill_count integer, out_total_billed numeric, out_total_paid numeric,
  out_coverage_state text, out_target_academic_year_name text,
  out_program_duration_yrs numeric, out_programme_end_year text,
  out_total_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst   uuid[];
  v_limit  integer := LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 200);
  v_offset integer := GREATEST(COALESCE(p_page, 1) - 1, 0)
                      * LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 200);
  v_asc    boolean := COALESCE(LOWER(p_sort_dir), 'asc') <> 'desc';
  v_picked_ay_name     text;
  -- The START YEAR of an explicitly picked academic year. The programme window
  -- is expressed in integer years, so the measured year has to be compared as
  -- one — the uuid says nothing about ordering.
  v_picked_ay_start_yr integer;
  v_adm_year_ids uuid[];
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN;
  END IF;

  SELECT ay.academic_year_name::text, EXTRACT(YEAR FROM ay.start_date)::integer
    INTO v_picked_ay_name, v_picked_ay_start_yr
  FROM public.academic_years ay WHERE ay.id = p_academic_year_id;

  IF p_admission_year IS NOT NULL THEN
    SELECT array_agg(ayr.id) INTO v_adm_year_ids
    FROM public.admission_years ayr
    WHERE ayr.year = p_admission_year;
  END IF;

  RETURN QUERY
  WITH target_year AS MATERIALIZED (
    SELECT t.institution_id, t.target_ay_id, t.target_ay_name,
           EXTRACT(YEAR FROM ay.start_date)::integer AS target_start_yr
    FROM public.fn_billing_coverage_target_years() t
    JOIN public.academic_years ay ON ay.id = t.target_ay_id
  ),
  billing_inst AS (
    -- ALL-TIME test, deliberately not scoped to p_academic_year_id. An
    -- institution that billed last year and has generated nothing this year is
    -- the case this report exists to catch; scoping here would hide it.
    SELECT DISTINCT b.institution_id AS inst_id
    FROM public.billing_student_bills b
  ),
  scope AS (
    -- NOTE: no lp.academic_year_id predicate. p_academic_year_id selects the
    -- year being MEASURED, never the learners being measured — see
    -- 20260808120000_billing_coverage_target_academic_year.sql.
    SELECT lp.id, lp.institution_id, lp.academic_year_id, lp.program_id,
           lp.semester_id, lp.section_id, lp.gender,
           lp.lifecycle_status, lp.first_name, lp.last_name,
           lp.roll_number, lp.register_number,
           lp.accommodation_type_id, lp.admission_year_id,
           (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL)
             AS uses_transport
    FROM public.learners_profiles lp
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_billing_institutions
           OR lp.institution_id IN (SELECT inst_id FROM billing_inst))
      AND (p_admission_year IS NULL
           OR lp.admission_year_id = ANY(v_adm_year_ids))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
      AND (
        p_search IS NULL OR p_search = ''
        OR lp.roll_number ILIKE '%' || p_search || '%'
        OR lp.register_number ILIKE '%' || p_search || '%'
        OR (COALESCE(lp.first_name,'') || ' ' || COALESCE(lp.last_name,''))
             ILIKE '%' || p_search || '%'
      )
  ),
  agg AS (
    SELECT s.id AS learner_id,
           ty.target_ay_id,
           ty.target_ay_name,
           ty.target_start_yr,
           COUNT(b.id)::integer AS bill_count,
           COALESCE(SUM(b.final_amount), 0)::numeric AS total_billed,
           COALESCE(
             SUM(b.final_amount - COALESCE(b.balance_amount, 0)), 0
           )::numeric AS total_paid
    FROM scope s
    LEFT JOIN target_year ty ON ty.institution_id = s.institution_id
    LEFT JOIN public.billing_student_bills b
           ON b.student_id = s.id
          AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
          AND b.academic_year_id = COALESCE(p_academic_year_id, ty.target_ay_id)
          AND (p_billing_category_id IS NULL
               OR b.item_category_id = p_billing_category_id)
    GROUP BY s.id, ty.target_ay_id, ty.target_ay_name, ty.target_start_yr
  ),
  final AS (
    SELECT s.id AS learner_id,
           s.roll_number::text        AS roll_number,
           s.register_number::text    AS register_number,
           TRIM(COALESCE(s.first_name,'') || ' ' || COALESCE(s.last_name,''))
                                      AS full_name,
           s.lifecycle_status::text   AS lifecycle_status,
           NULLIF(TRIM(s.gender), '')::text AS gender,
           s.institution_id           AS institution_id,
           i.name::text               AS institution_name,
           p.program_name             AS program_name,
           CASE
             WHEN sem.semester_name IS NULL AND sec.section_name IS NULL
               THEN NULL
             WHEN sec.section_name IS NULL THEN sem.semester_name::text
             WHEN sem.semester_name IS NULL THEN sec.section_name::text
             ELSE sem.semester_name::text || ' · ' || sec.section_name::text
           END                        AS semester_section,
           s.academic_year_id         AS academic_year_id,
           ay.academic_year_name::text AS academic_year_name,
           adm.year                   AS admission_year,
           acc.name::text             AS accommodation_type,
           s.uses_transport           AS uses_transport,
           a.bill_count               AS bill_count,
           a.total_billed             AS total_billed,
           a.total_paid               AS total_paid,
           p.program_duration_yrs     AS program_duration_yrs,
           public.fn_programme_end_year(adm.year, p.program_duration_yrs)
                                      AS programme_end_yr,
           CASE
             WHEN COALESCE(p_academic_year_id, a.target_ay_id) IS NULL
               THEN 'cannot_evaluate'
             -- Ordered before the not_applicable test on purpose: a live bill
             -- is a live bill. Reclassifying a billed learner would move the
             -- `generated` count, and this change is deliberately confined to
             -- rows that would otherwise read 'not_generated'.
             WHEN a.bill_count > 0 THEN 'generated'
             WHEN public.fn_programme_end_year(adm.year, p.program_duration_yrs)
                    IS NOT NULL
              AND COALESCE(v_picked_ay_start_yr, a.target_start_yr)
                    > public.fn_programme_end_year(adm.year, p.program_duration_yrs)
               THEN 'not_applicable'
             ELSE 'not_generated'
           END                        AS coverage_state,
           COALESCE(v_picked_ay_name, a.target_ay_name)
                                      AS target_academic_year_name
    FROM scope s
    JOIN agg a                           ON a.learner_id = s.id
    LEFT JOIN public.institutions        i   ON i.id   = s.institution_id
    LEFT JOIN public.programs            p   ON p.id   = s.program_id
    LEFT JOIN public.semesters           sem ON sem.id = s.semester_id
    LEFT JOIN public.sections            sec ON sec.id = s.section_id
    LEFT JOIN public.academic_years      ay  ON ay.id  = s.academic_year_id
    LEFT JOIN public.admission_years     adm ON adm.id = s.admission_year_id
    LEFT JOIN public.accommodation_types acc ON acc.id = s.accommodation_type_id
  ),
  filtered AS (
    SELECT * FROM final f
    WHERE p_coverage_state = 'all' OR f.coverage_state = p_coverage_state
  )
  SELECT f.learner_id, f.roll_number, f.register_number, f.full_name,
         f.lifecycle_status, f.gender, f.institution_id, f.institution_name,
         f.program_name, f.semester_section,
         f.academic_year_id, f.academic_year_name, f.admission_year,
         f.accommodation_type, f.uses_transport,
         f.bill_count, f.total_billed, f.total_paid, f.coverage_state,
         f.target_academic_year_name,
         f.program_duration_yrs,
         -- Rendered as the session label ("2025-2026") rather than the bare
         -- integer, so it reads next to the academic-year columns beside it.
         CASE WHEN f.programme_end_yr IS NULL THEN NULL
              ELSE f.programme_end_yr::text || '-' || (f.programme_end_yr + 1)::text
         END,
         COUNT(*) OVER ()::bigint
  FROM filtered f
  ORDER BY
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'academic_year_name' THEN f.academic_year_name
         WHEN 'accommodation_type' THEN f.accommodation_type
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'gender'             THEN f.gender
         WHEN 'coverage_state'     THEN f.coverage_state
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'academic_year_name' THEN f.academic_year_name
         WHEN 'accommodation_type' THEN f.accommodation_type
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'gender'             THEN f.gender
         WHEN 'coverage_state'     THEN f.coverage_state
       END
     END) DESC NULLS LAST,
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'bill_count'     THEN f.bill_count::numeric
         WHEN 'total_billed'   THEN f.total_billed
         WHEN 'total_paid'     THEN f.total_paid
         WHEN 'admission_year' THEN f.admission_year::numeric
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'bill_count'     THEN f.bill_count::numeric
         WHEN 'total_billed'   THEN f.total_billed
         WHEN 'total_paid'     THEN f.total_paid
         WHEN 'admission_year' THEN f.admission_year::numeric
       END
     END) DESC NULLS LAST,
    f.institution_name NULLS LAST, f.roll_number NULLS LAST, f.full_name
  LIMIT v_limit OFFSET v_offset;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_billing_coverage_learners(
  uuid, uuid[], text[], uuid, text, boolean, text, integer, integer,
  uuid[], text, text, text, text, uuid, uuid, uuid, uuid, uuid, integer)
  FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_billing_coverage_learners(
  uuid, uuid[], text[], uuid, text, boolean, text, integer, integer,
  uuid[], text, text, text, text, uuid, uuid, uuid, uuid, uuid, integer)
  TO authenticated, service_role;

-- ── Summary (KPI cards) ────────────────────────────────────────────────────
-- Signature unchanged, so CREATE OR REPLACE is enough and the ACL survives.
CREATE OR REPLACE FUNCTION public.get_billing_coverage_summary(
  p_academic_year_id uuid DEFAULT NULL::uuid,
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_billing_category_id uuid DEFAULT NULL::uuid,
  p_include_non_billing_institutions boolean DEFAULT false,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_admission_year integer DEFAULT NULL::integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst               uuid[];
  v_adm_year_ids       uuid[];
  v_picked_ay_start_yr integer;
  v_result             jsonb;
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN jsonb_build_object(
      'in_scope', 0, 'generated', 0, 'not_generated', 0, 'cannot_evaluate', 0,
      'not_applicable', 0, 'duration_not_set', 0,
      'excluded_institutions', 0, 'excluded_learners', 0,
      'by_institution', '[]'::jsonb);
  END IF;

  SELECT EXTRACT(YEAR FROM ay.start_date)::integer INTO v_picked_ay_start_yr
  FROM public.academic_years ay WHERE ay.id = p_academic_year_id;

  IF p_admission_year IS NOT NULL THEN
    SELECT array_agg(ayr.id) INTO v_adm_year_ids
    FROM public.admission_years ayr
    WHERE ayr.year = p_admission_year;
  END IF;

  WITH target_year AS MATERIALIZED (
    SELECT t.institution_id, t.target_ay_id,
           EXTRACT(YEAR FROM ay.start_date)::integer AS target_start_yr
    FROM public.fn_billing_coverage_target_years() t
    JOIN public.academic_years ay ON ay.id = t.target_ay_id
  ),
  billing_inst AS (
    SELECT DISTINCT b.institution_id AS inst_id FROM public.billing_student_bills b
  ),
  all_scope AS (
    -- No lp.academic_year_id predicate — see get_billing_coverage_learners.
    SELECT lp.id, lp.institution_id,
           adm.year AS cohort,
           p.program_duration_yrs AS dur,
           (lp.institution_id IN (SELECT inst_id FROM billing_inst)) AS is_billing_inst
    FROM public.learners_profiles lp
    LEFT JOIN public.admission_years adm ON adm.id = lp.admission_year_id
    LEFT JOIN public.programs p ON p.id = lp.program_id
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_admission_year IS NULL
           OR lp.admission_year_id = ANY(v_adm_year_ids))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
  ),
  scope AS (
    SELECT * FROM all_scope
    WHERE p_include_non_billing_institutions OR is_billing_inst
  ),
  agg AS (
    SELECT s.id, s.institution_id, s.cohort, s.dur, ty.target_ay_id,
           ty.target_start_yr,
           COUNT(b.id)::integer AS bill_count
    FROM scope s
    LEFT JOIN target_year ty ON ty.institution_id = s.institution_id
    LEFT JOIN public.billing_student_bills b
           ON b.student_id = s.id
          AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
          AND b.academic_year_id = COALESCE(p_academic_year_id, ty.target_ay_id)
          AND (p_billing_category_id IS NULL
               OR b.item_category_id = p_billing_category_id)
    GROUP BY s.id, s.institution_id, s.cohort, s.dur, ty.target_ay_id, ty.target_start_yr
  ),
  stated AS (
    SELECT a.institution_id,
           (a.dur IS NULL) AS duration_not_set,
           CASE
             WHEN COALESCE(p_academic_year_id, a.target_ay_id) IS NULL
               THEN 'cannot_evaluate'
             WHEN a.bill_count > 0 THEN 'generated'
             WHEN public.fn_programme_end_year(a.cohort, a.dur) IS NOT NULL
              AND COALESCE(v_picked_ay_start_yr, a.target_start_yr)
                    > public.fn_programme_end_year(a.cohort, a.dur)
               THEN 'not_applicable'
             ELSE 'not_generated'
           END AS coverage_state
    FROM agg a
  )
  SELECT jsonb_build_object(
    'in_scope',        (SELECT COUNT(*) FROM stated),
    'generated',       (SELECT COUNT(*) FROM stated WHERE coverage_state = 'generated'),
    'not_generated',   (SELECT COUNT(*) FROM stated WHERE coverage_state = 'not_generated'),
    'cannot_evaluate', (SELECT COUNT(*) FROM stated WHERE coverage_state = 'cannot_evaluate'),
    -- Learners whose programme had already finished by the measured year.
    'not_applicable',  (SELECT COUNT(*) FROM stated WHERE coverage_state = 'not_applicable'),
    -- Data hygiene, not a verdict: how many of the population sit in a
    -- programme with no duration on file, and therefore cannot be bounded.
    'duration_not_set',(SELECT COUNT(*) FROM stated WHERE duration_not_set),
    'excluded_institutions',
      (SELECT COUNT(DISTINCT institution_id) FROM all_scope WHERE NOT is_billing_inst),
    'excluded_learners',
      (SELECT COUNT(*) FROM all_scope WHERE NOT is_billing_inst),
    'by_institution', COALESCE((
      SELECT jsonb_agg(x ORDER BY x->>'institution_name')
      FROM (
        SELECT jsonb_build_object(
                 'institution_id',   st.institution_id,
                 'institution_name', COALESCE(i.name::text, 'Unknown'),
                 'in_scope',         COUNT(*),
                 'generated',        COUNT(*) FILTER (WHERE st.coverage_state = 'generated'),
                 'not_generated',    COUNT(*) FILTER (WHERE st.coverage_state = 'not_generated'),
                 'not_applicable',   COUNT(*) FILTER (WHERE st.coverage_state = 'not_applicable')
               ) AS x
        FROM stated st
        LEFT JOIN public.institutions i ON i.id = st.institution_id
        GROUP BY st.institution_id, i.name
      ) sub
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$function$;

-- ── Per-learner bill detail (PDF export) ───────────────────────────────────
-- The same rule has to land here or the PDF and the table disagree about the
-- same learner — the exact failure 20260808120000 was written to fix.
CREATE OR REPLACE FUNCTION public.get_billing_coverage_learner_bills(
  p_academic_year_id uuid DEFAULT NULL::uuid,
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_billing_category_id uuid DEFAULT NULL::uuid,
  p_coverage_state text DEFAULT 'all'::text,
  p_include_non_billing_institutions boolean DEFAULT false,
  p_search text DEFAULT NULL::text,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_max_learners integer DEFAULT 1000,
  p_admission_year integer DEFAULT NULL::integer
)
RETURNS TABLE(
  out_learner_id uuid, out_roll_number text, out_register_number text,
  out_full_name text, out_institution_name text, out_program_name text,
  out_semester_section text, out_lifecycle_status text,
  out_learner_total numeric, out_learner_paid numeric,
  out_learner_pending numeric, out_bill_id uuid, out_bill_description text,
  out_category_name text, out_bill_academic_year text, out_due_date date,
  out_bill_status text, out_total_amount numeric, out_paid_amount numeric,
  out_pending_amount numeric, out_learner_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst               uuid[];
  v_adm_year_ids       uuid[];
  v_picked_ay_start_yr integer;
  v_cap                integer := LEAST(GREATEST(COALESCE(p_max_learners, 1000), 1), 5000);
BEGIN
  IF NOT public.user_has_permission('billing.coverage.export') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.export' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN;
  END IF;

  SELECT EXTRACT(YEAR FROM ay.start_date)::integer INTO v_picked_ay_start_yr
  FROM public.academic_years ay WHERE ay.id = p_academic_year_id;

  IF p_admission_year IS NOT NULL THEN
    SELECT array_agg(ayr.id) INTO v_adm_year_ids
    FROM public.admission_years ayr
    WHERE ayr.year = p_admission_year;
  END IF;

  RETURN QUERY
  WITH target_year AS MATERIALIZED (
    SELECT t.institution_id, t.target_ay_id,
           EXTRACT(YEAR FROM ay.start_date)::integer AS target_start_yr
    FROM public.fn_billing_coverage_target_years() t
    JOIN public.academic_years ay ON ay.id = t.target_ay_id
  ),
  billing_inst AS (
    SELECT DISTINCT b.institution_id AS inst_id FROM public.billing_student_bills b
  ),
  scope AS (
    SELECT lp.id, lp.institution_id, lp.academic_year_id, lp.program_id,
           lp.semester_id, lp.section_id, lp.lifecycle_status,
           lp.first_name, lp.last_name, lp.roll_number, lp.register_number,
           adm.year AS cohort, p.program_duration_yrs AS dur
    FROM public.learners_profiles lp
    LEFT JOIN public.admission_years adm ON adm.id = lp.admission_year_id
    LEFT JOIN public.programs p ON p.id = lp.program_id
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_billing_institutions
           OR lp.institution_id IN (SELECT inst_id FROM billing_inst))
      AND (p_admission_year IS NULL
           OR lp.admission_year_id = ANY(v_adm_year_ids))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
      AND (
        p_search IS NULL OR p_search = ''
        OR lp.roll_number ILIKE '%' || p_search || '%'
        OR lp.register_number ILIKE '%' || p_search || '%'
        OR (COALESCE(lp.first_name,'') || ' ' || COALESCE(lp.last_name,''))
             ILIKE '%' || p_search || '%'
      )
  ),
  live_bills AS (
    SELECT b.*
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    LEFT JOIN target_year ty ON ty.institution_id = s.institution_id
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
      AND (p_billing_category_id IS NULL OR b.item_category_id = p_billing_category_id)
      AND b.academic_year_id = COALESCE(p_academic_year_id, ty.target_ay_id)
  ),
  learner_state AS (
    SELECT s.id,
           COUNT(lb.id)::integer AS bill_count,
           COALESCE(SUM(lb.final_amount), 0)::numeric   AS total_amount,
           COALESCE(SUM(lb.final_amount - lb.balance_amount), 0)::numeric AS paid_amount,
           COALESCE(SUM(lb.balance_amount), 0)::numeric AS pending_amount
    FROM scope s
    LEFT JOIN live_bills lb ON lb.student_id = s.id
    GROUP BY s.id
  ),
  eligible AS (
    SELECT s.*, ls.bill_count, ls.total_amount, ls.paid_amount, ls.pending_amount,
           CASE
             WHEN ls.bill_count > 0 THEN 'generated'
             WHEN public.fn_programme_end_year(s.cohort, s.dur) IS NOT NULL
              AND COALESCE(v_picked_ay_start_yr, ty.target_start_yr)
                    > public.fn_programme_end_year(s.cohort, s.dur)
               THEN 'not_applicable'
             ELSE 'not_generated'
           END AS cov_state
    FROM scope s
    JOIN learner_state ls ON ls.id = s.id
    LEFT JOIN target_year ty ON ty.institution_id = s.institution_id
  ),
  picked AS (
    SELECT * FROM eligible e
    WHERE p_coverage_state = 'all' OR e.cov_state = p_coverage_state
  ),
  capped AS (
    SELECT e.*, i.name::text AS institution_name, p.program_name,
           CASE
             WHEN sem.semester_name IS NULL AND sec.section_name IS NULL THEN NULL
             WHEN sec.section_name IS NULL THEN sem.semester_name::text
             WHEN sem.semester_name IS NULL THEN sec.section_name::text
             ELSE sem.semester_name::text || ' · ' || sec.section_name::text
           END AS semester_section,
           COUNT(*) OVER ()::bigint AS learner_count
    FROM picked e
    LEFT JOIN public.institutions i   ON i.id   = e.institution_id
    LEFT JOIN public.programs     p   ON p.id   = e.program_id
    LEFT JOIN public.semesters    sem ON sem.id = e.semester_id
    LEFT JOIN public.sections     sec ON sec.id = e.section_id
    ORDER BY i.name NULLS LAST, e.roll_number NULLS LAST, e.last_name, e.first_name
    LIMIT v_cap
  )
  SELECT c.id,
         c.roll_number::text,
         c.register_number::text,
         TRIM(COALESCE(c.first_name,'') || ' ' || COALESCE(c.last_name,'')),
         c.institution_name,
         c.program_name,
         c.semester_section,
         c.lifecycle_status::text,
         c.total_amount,
         c.paid_amount,
         c.pending_amount,
         lb.id,
         lb.bill_description::text,
         cat.category_name::text,
         COALESCE(ay.academic_year_name::text, '—'),
         lb.due_date,
         lb.status::text,
         lb.final_amount,
         (lb.final_amount - lb.balance_amount),
         lb.balance_amount,
         c.learner_count
  FROM capped c
  LEFT JOIN live_bills lb              ON lb.student_id = c.id
  LEFT JOIN public.billing_categories cat ON cat.id = lb.item_category_id
  LEFT JOIN public.academic_years ay    ON ay.id  = lb.academic_year_id
  ORDER BY c.institution_name NULLS LAST, c.roll_number NULLS LAST,
           lb.due_date NULLS LAST, lb.bill_description;
END;
$function$;


-- ============================================================================
-- Bill Coverage Audit: bound the audited window by the PROGRAMME's duration
-- ============================================================================
-- Companion to 20260812170000, which did the same for the three Coverage RPCs.
-- The rule and its rationale live in that file's header; in short:
--
--   programme_end_year = cohort_year + CEIL(program_duration_yrs) - 1
--   expected years     = active AY start years
--                        BETWEEN GREATEST(cohort, p_earliest_academic_year)
--                        AND     LEAST(institution_current_year,
--                                      programme_end_year)
--
-- PHARMD cohort 2020 is a 6-year course running 2020-21 .. 2025-26, so 2026-27
-- must stop being listed as a bill that was never raised. A NULL duration keeps
-- today's uncapped behaviour rather than guessing — but the learner is now
-- FLAGGED so the phantom tail is attributable instead of mysterious.
--
-- Two knock-on changes worth stating:
--
-- 1. has_current_year now means "the learner's LAST EXPECTED year is billed",
--    not "the institution's current year is billed". For a cohort that has
--    finished, the institution's current year is no longer part of their
--    window, so the old reading would have marked every completed cohort as
--    lacking a current bill. The KPI it drives keeps its meaning — currently
--    billed, historically short — under the corrected window.
--
-- 2. The duplicates check gains the INVERSE finding: live tuition bills stamped
--    for a year AFTER the programme ends. Scoped to tuition-kind only and
--    deliberately so — counting every kind returns 62 learners, but a CRRI
--    intern legitimately still has hostel and mess bills after the taught years
--    end. Tuition-only returns the real anomaly.
-- ============================================================================

-- ── A: summary ─────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.get_billing_audit_missing_years_summary(
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_include_non_tuition_institutions boolean DEFAULT false,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_admission_year integer DEFAULT NULL::integer,
  p_earliest_academic_year integer DEFAULT NULL::integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst         uuid[];
  v_adm_year_ids uuid[];
  v_result       jsonb;
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN jsonb_build_object(
      'in_scope', 0, 'gap', 0, 'complete', 0, 'cannot_evaluate', 0,
      'missing_slots', 0, 'backlog_only', 0, 'no_tuition_at_all', 0,
      'duration_not_set', 0,
      'excluded_institutions', 0, 'excluded_learners', 0,
      'by_institution', '[]'::jsonb, 'available_academic_years', '[]'::jsonb);
  END IF;

  IF p_admission_year IS NOT NULL THEN
    SELECT array_agg(ayr.id) INTO v_adm_year_ids
    FROM public.admission_years ayr WHERE ayr.year = p_admission_year;
  END IF;

  WITH tuition_inst AS MATERIALIZED (
    SELECT DISTINCT b.institution_id AS inst_id
    FROM public.billing_student_bills b
    JOIN public.billing_categories bc ON bc.id = b.item_category_id
    WHERE bc.kind = 'tuition'
      AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
  ),
  target AS MATERIALIZED (
    SELECT t.institution_id, EXTRACT(YEAR FROM ay.start_date)::int AS ceiling_yr
    FROM public.fn_billing_coverage_target_years() t
    JOIN public.academic_years ay ON ay.id = t.target_ay_id
  ),
  inst_years AS MATERIALIZED (
    SELECT DISTINCT ay.institution_id, EXTRACT(YEAR FROM ay.start_date)::int AS yr
    FROM public.academic_years ay WHERE ay.is_active IS TRUE
  ),
  all_scope AS MATERIALIZED (
    SELECT lp.id, lp.institution_id, adm.year AS cohort, t.ceiling_yr,
           p.program_duration_yrs AS dur,
           -- The window's upper bound: whichever comes first, the institution's
           -- current year or the end of this learner's programme.
           LEAST(t.ceiling_yr,
                 COALESCE(public.fn_programme_end_year(adm.year, p.program_duration_yrs),
                          t.ceiling_yr)) AS window_end_yr,
           (lp.institution_id IN (SELECT inst_id FROM tuition_inst)) AS is_tuition_inst
    FROM public.learners_profiles lp
    LEFT JOIN public.admission_years adm ON adm.id = lp.admission_year_id
    LEFT JOIN public.programs p ON p.id = lp.program_id
    LEFT JOIN target t ON t.institution_id = lp.institution_id
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_admission_year IS NULL OR lp.admission_year_id = ANY(v_adm_year_ids))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
  ),
  scope AS MATERIALIZED (
    SELECT * FROM all_scope
    WHERE p_include_non_tuition_institutions OR is_tuition_inst
  ),
  covered AS MATERIALIZED (
    SELECT DISTINCT b.student_id,
           EXTRACT(YEAR FROM ay.start_date)::int AS yr
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    JOIN public.billing_categories bc ON bc.id = b.item_category_id AND bc.kind = 'tuition'
    JOIN public.academic_years ay ON ay.id = b.academic_year_id
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
  ),
  years AS (
    SELECT s.id AS learner_id, iy.yr, s.window_end_yr,
           (c.student_id IS NOT NULL) AS is_covered
    FROM scope s
    JOIN inst_years iy ON iy.institution_id = s.institution_id
     AND iy.yr BETWEEN GREATEST(s.cohort, COALESCE(p_earliest_academic_year, s.cohort))
                   AND s.window_end_yr
    LEFT JOIN covered c ON c.student_id = s.id AND c.yr = iy.yr
    WHERE s.cohort IS NOT NULL AND s.ceiling_yr IS NOT NULL
  ),
  per_learner AS (
    SELECT y.learner_id,
           COUNT(*) FILTER (WHERE y.is_covered)::int     AS billed_years,
           COUNT(*) FILTER (WHERE NOT y.is_covered)::int AS missing_years,
           -- The learner's LAST EXPECTED year, not the institution's current
           -- one — for a finished cohort those are different years.
           bool_or(y.yr = y.window_end_yr AND y.is_covered) AS has_current_year
    FROM years y GROUP BY y.learner_id
  ),
  stated AS (
    SELECT s.institution_id,
           (s.dur IS NULL) AS duration_not_set,
           COALESCE(pl.missing_years, 0)   AS missing_years,
           COALESCE(pl.billed_years, 0)    AS billed_years,
           COALESCE(pl.has_current_year, false) AS has_current_year,
           CASE
             WHEN s.cohort IS NULL OR s.ceiling_yr IS NULL THEN 'cannot_evaluate'
             WHEN COALESCE(pl.missing_years, 0) > 0        THEN 'gap'
             ELSE 'complete'
           END AS audit_state
    FROM scope s
    LEFT JOIN per_learner pl ON pl.learner_id = s.id
  )
  SELECT jsonb_build_object(
    'in_scope',        (SELECT COUNT(*) FROM stated),
    'gap',             (SELECT COUNT(*) FROM stated WHERE audit_state = 'gap'),
    'complete',        (SELECT COUNT(*) FROM stated WHERE audit_state = 'complete'),
    'cannot_evaluate', (SELECT COUNT(*) FROM stated WHERE audit_state = 'cannot_evaluate'),
    'missing_slots',   (SELECT COALESCE(SUM(missing_years), 0) FROM stated),
    'backlog_only',    (SELECT COUNT(*) FROM stated
                        WHERE audit_state = 'gap' AND has_current_year),
    'no_tuition_at_all', (SELECT COUNT(*) FROM stated
                          WHERE audit_state = 'gap' AND billed_years = 0),
    -- Data hygiene, not a verdict: these learners' windows run to the current
    -- year because their programme has no duration on file, so any tail years
    -- they show are unproven rather than confirmed gaps.
    'duration_not_set',(SELECT COUNT(*) FROM stated WHERE duration_not_set),
    'excluded_institutions',
      (SELECT COUNT(DISTINCT institution_id) FROM all_scope WHERE NOT is_tuition_inst),
    'excluded_learners',
      (SELECT COUNT(*) FROM all_scope WHERE NOT is_tuition_inst),
    'by_institution', COALESCE((
      SELECT jsonb_agg(x ORDER BY x->>'institution_name')
      FROM (
        SELECT jsonb_build_object(
                 'institution_id',   st.institution_id,
                 'institution_name', COALESCE(i.name::text, 'Unknown'),
                 'in_scope',         COUNT(*),
                 'gap',              COUNT(*) FILTER (WHERE st.audit_state = 'gap'),
                 'missing_slots',    COALESCE(SUM(st.missing_years), 0)
               ) AS x
        FROM stated st
        LEFT JOIN public.institutions i ON i.id = st.institution_id
        GROUP BY st.institution_id, i.name
      ) sub
    ), '[]'::jsonb),
    'available_academic_years', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'year',  yr,
               'label', yr::text || '-' || (yr + 1)::text) ORDER BY yr DESC)
      FROM (
        SELECT DISTINCT EXTRACT(YEAR FROM ay.start_date)::int AS yr
        FROM public.academic_years ay
        WHERE ay.institution_id = ANY(v_inst)
          AND ay.is_active IS TRUE
          AND ay.start_date <= CURRENT_DATE
      ) ys
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$function$;

-- ── A: learners list ───────────────────────────────────────────────────────
-- DROP + CREATE: the RETURNS TABLE gains three columns. Dropping discards the
-- ACL, so the REVOKE/GRANT pair below is load-bearing.
DROP FUNCTION IF EXISTS public.get_billing_audit_missing_years(
  uuid[], text[], boolean, uuid[], text, text, uuid, uuid, uuid, uuid, uuid,
  integer, integer, text, text, integer, integer, text, text);

CREATE FUNCTION public.get_billing_audit_missing_years(
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_include_non_tuition_institutions boolean DEFAULT false,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_admission_year integer DEFAULT NULL::integer,
  p_earliest_academic_year integer DEFAULT NULL::integer,
  p_audit_state text DEFAULT 'gap'::text,
  p_search text DEFAULT NULL::text,
  p_page integer DEFAULT 1,
  p_page_size integer DEFAULT 50,
  p_sort_by text DEFAULT NULL::text,
  p_sort_dir text DEFAULT 'asc'::text
)
RETURNS TABLE(
  out_learner_id uuid, out_roll_number text, out_register_number text,
  out_full_name text, out_lifecycle_status text, out_gender text,
  out_institution_id uuid, out_institution_name text, out_program_name text,
  out_semester_section text, out_admission_year integer,
  out_expected_years integer, out_billed_years integer, out_missing_years integer,
  out_missing_year_names text, out_first_missing_year text,
  out_has_current_year boolean, out_tuition_bill_count integer,
  out_total_billed numeric, out_total_paid numeric,
  out_unassigned_tuition_bills integer, out_audit_state text,
  out_program_duration_yrs numeric, out_programme_end_year text,
  out_duration_configured boolean,
  out_total_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst   uuid[];
  v_limit  integer := LEAST(GREATEST(COALESCE(NULLIF(p_page_size, 0), 50), 1), 5000);
  v_offset integer := GREATEST(COALESCE(p_page, 1) - 1, 0)
                      * LEAST(GREATEST(COALESCE(NULLIF(p_page_size, 0), 50), 1), 5000);
  v_asc    boolean := COALESCE(LOWER(p_sort_dir), 'asc') <> 'desc';
  v_adm_year_ids uuid[];
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN;
  END IF;

  IF p_admission_year IS NOT NULL THEN
    SELECT array_agg(ayr.id) INTO v_adm_year_ids
    FROM public.admission_years ayr WHERE ayr.year = p_admission_year;
  END IF;

  RETURN QUERY
  WITH tuition_inst AS MATERIALIZED (
    SELECT DISTINCT b.institution_id AS inst_id
    FROM public.billing_student_bills b
    JOIN public.billing_categories bc ON bc.id = b.item_category_id
    WHERE bc.kind = 'tuition'
      AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
  ),
  target AS MATERIALIZED (
    SELECT t.institution_id, EXTRACT(YEAR FROM ay.start_date)::int AS ceiling_yr
    FROM public.fn_billing_coverage_target_years() t
    JOIN public.academic_years ay ON ay.id = t.target_ay_id
  ),
  inst_years AS MATERIALIZED (
    SELECT DISTINCT ay.institution_id, EXTRACT(YEAR FROM ay.start_date)::int AS yr
    FROM public.academic_years ay WHERE ay.is_active IS TRUE
  ),
  scope AS MATERIALIZED (
    SELECT lp.id, lp.institution_id, lp.program_id, lp.semester_id, lp.section_id,
           lp.gender, lp.lifecycle_status, lp.first_name, lp.last_name,
           lp.roll_number, lp.register_number, lp.accommodation_type_id,
           adm.year AS cohort, t.ceiling_yr,
           p.program_duration_yrs AS dur,
           LEAST(t.ceiling_yr,
                 COALESCE(public.fn_programme_end_year(adm.year, p.program_duration_yrs),
                          t.ceiling_yr)) AS window_end_yr
    FROM public.learners_profiles lp
    LEFT JOIN public.admission_years adm ON adm.id = lp.admission_year_id
    LEFT JOIN public.programs p ON p.id = lp.program_id
    LEFT JOIN target t ON t.institution_id = lp.institution_id
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_tuition_institutions
           OR lp.institution_id IN (SELECT inst_id FROM tuition_inst))
      AND (p_admission_year IS NULL OR lp.admission_year_id = ANY(v_adm_year_ids))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
      AND (
        p_search IS NULL OR p_search = ''
        OR lp.roll_number ILIKE '%' || p_search || '%'
        OR lp.register_number ILIKE '%' || p_search || '%'
        OR (COALESCE(lp.first_name,'') || ' ' || COALESCE(lp.last_name,''))
             ILIKE '%' || p_search || '%'
      )
  ),
  covered AS MATERIALIZED (
    SELECT DISTINCT b.student_id, EXTRACT(YEAR FROM ay.start_date)::int AS yr
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    JOIN public.billing_categories bc ON bc.id = b.item_category_id AND bc.kind = 'tuition'
    JOIN public.academic_years ay ON ay.id = b.academic_year_id
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
  ),
  bill_stats AS MATERIALIZED (
    SELECT b.student_id,
           COUNT(*)::integer AS tuition_bill_count,
           COALESCE(SUM(b.final_amount), 0)::numeric AS total_billed,
           COALESCE(SUM(b.final_amount - COALESCE(b.balance_amount, 0)), 0)::numeric
             AS total_paid,
           COUNT(*) FILTER (WHERE b.academic_year_id IS NULL)::integer
             AS unassigned_tuition_bills
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    JOIN public.billing_categories bc ON bc.id = b.item_category_id AND bc.kind = 'tuition'
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
    GROUP BY b.student_id
  ),
  years AS (
    SELECT s.id AS learner_id, iy.yr, s.window_end_yr,
           (c.student_id IS NOT NULL) AS is_covered
    FROM scope s
    JOIN inst_years iy ON iy.institution_id = s.institution_id
     AND iy.yr BETWEEN GREATEST(s.cohort, COALESCE(p_earliest_academic_year, s.cohort))
                   AND s.window_end_yr
    LEFT JOIN covered c ON c.student_id = s.id AND c.yr = iy.yr
    WHERE s.cohort IS NOT NULL AND s.ceiling_yr IS NOT NULL
  ),
  per_learner AS (
    SELECT y.learner_id,
           COUNT(*)::integer                             AS expected_years,
           COUNT(*) FILTER (WHERE y.is_covered)::integer AS billed_years,
           COUNT(*) FILTER (WHERE NOT y.is_covered)::integer AS missing_years,
           string_agg(y.yr::text || '-' || (y.yr + 1)::text, ', ' ORDER BY y.yr)
             FILTER (WHERE NOT y.is_covered)             AS missing_year_names,
           MIN(y.yr) FILTER (WHERE NOT y.is_covered)     AS first_missing_yr,
           bool_or(y.yr = y.window_end_yr AND y.is_covered) AS has_current_year
    FROM years y GROUP BY y.learner_id
  ),
  final AS (
    SELECT s.id AS learner_id,
           s.roll_number::text     AS roll_number,
           s.register_number::text AS register_number,
           TRIM(COALESCE(s.first_name,'') || ' ' || COALESCE(s.last_name,''))
                                   AS full_name,
           s.lifecycle_status::text AS lifecycle_status,
           NULLIF(TRIM(s.gender), '')::text AS gender,
           s.institution_id        AS institution_id,
           i.name::text            AS institution_name,
           p.program_name          AS program_name,
           CASE
             WHEN sem.semester_name IS NULL AND sec.section_name IS NULL THEN NULL
             WHEN sec.section_name IS NULL THEN sem.semester_name::text
             WHEN sem.semester_name IS NULL THEN sec.section_name::text
             ELSE sem.semester_name::text || ' · ' || sec.section_name::text
           END                     AS semester_section,
           s.cohort                AS admission_year,
           COALESCE(pl.expected_years, 0) AS expected_years,
           COALESCE(pl.billed_years, 0)   AS billed_years,
           COALESCE(pl.missing_years, 0)  AS missing_years,
           pl.missing_year_names   AS missing_year_names,
           CASE WHEN pl.first_missing_yr IS NULL THEN NULL
                ELSE pl.first_missing_yr::text || '-' || (pl.first_missing_yr + 1)::text
           END                     AS first_missing_year,
           COALESCE(pl.has_current_year, false) AS has_current_year,
           COALESCE(bs.tuition_bill_count, 0)   AS tuition_bill_count,
           COALESCE(bs.total_billed, 0)::numeric AS total_billed,
           COALESCE(bs.total_paid, 0)::numeric   AS total_paid,
           COALESCE(bs.unassigned_tuition_bills, 0) AS unassigned_tuition_bills,
           s.dur                   AS program_duration_yrs,
           public.fn_programme_end_year(s.cohort, s.dur) AS programme_end_yr,
           (s.dur IS NOT NULL)     AS duration_configured,
           CASE
             WHEN s.cohort IS NULL OR s.ceiling_yr IS NULL THEN 'cannot_evaluate'
             WHEN COALESCE(pl.missing_years, 0) > 0        THEN 'gap'
             ELSE 'complete'
           END                     AS audit_state
    FROM scope s
    LEFT JOIN per_learner pl              ON pl.learner_id = s.id
    LEFT JOIN bill_stats  bs              ON bs.student_id = s.id
    LEFT JOIN public.institutions i       ON i.id   = s.institution_id
    LEFT JOIN public.programs     p       ON p.id   = s.program_id
    LEFT JOIN public.semesters    sem     ON sem.id = s.semester_id
    LEFT JOIN public.sections     sec     ON sec.id = s.section_id
  ),
  filtered AS (
    SELECT * FROM final f
    WHERE COALESCE(p_audit_state, 'gap') = 'all'
       OR f.audit_state = COALESCE(p_audit_state, 'gap')
  )
  SELECT f.learner_id, f.roll_number, f.register_number, f.full_name,
         f.lifecycle_status, f.gender, f.institution_id, f.institution_name,
         f.program_name, f.semester_section, f.admission_year,
         f.expected_years, f.billed_years, f.missing_years,
         f.missing_year_names, f.first_missing_year, f.has_current_year,
         f.tuition_bill_count, f.total_billed, f.total_paid,
         f.unassigned_tuition_bills, f.audit_state,
         f.program_duration_yrs,
         CASE WHEN f.programme_end_yr IS NULL THEN NULL
              ELSE f.programme_end_yr::text || '-' || (f.programme_end_yr + 1)::text
         END,
         f.duration_configured,
         COUNT(*) OVER ()::bigint
  FROM filtered f
  ORDER BY
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'gender'             THEN f.gender
         WHEN 'first_missing_year' THEN f.first_missing_year
         WHEN 'programme_end_year' THEN f.programme_end_yr::text
         WHEN 'audit_state'        THEN f.audit_state
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'gender'             THEN f.gender
         WHEN 'first_missing_year' THEN f.first_missing_year
         WHEN 'programme_end_year' THEN f.programme_end_yr::text
         WHEN 'audit_state'        THEN f.audit_state
       END
     END) DESC NULLS LAST,
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'admission_year'        THEN f.admission_year::numeric
         WHEN 'expected_years'        THEN f.expected_years::numeric
         WHEN 'billed_years'          THEN f.billed_years::numeric
         WHEN 'missing_years'         THEN f.missing_years::numeric
         WHEN 'tuition_bill_count'    THEN f.tuition_bill_count::numeric
         WHEN 'total_billed'          THEN f.total_billed
         WHEN 'total_paid'            THEN f.total_paid
         WHEN 'program_duration_yrs'  THEN f.program_duration_yrs
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'admission_year'        THEN f.admission_year::numeric
         WHEN 'expected_years'        THEN f.expected_years::numeric
         WHEN 'billed_years'          THEN f.billed_years::numeric
         WHEN 'missing_years'         THEN f.missing_years::numeric
         WHEN 'tuition_bill_count'    THEN f.tuition_bill_count::numeric
         WHEN 'total_billed'          THEN f.total_billed
         WHEN 'total_paid'            THEN f.total_paid
         WHEN 'program_duration_yrs'  THEN f.program_duration_yrs
       END
     END) DESC NULLS LAST,
    f.missing_years DESC, f.institution_name NULLS LAST,
    f.roll_number NULLS LAST, f.full_name
  LIMIT v_limit OFFSET v_offset;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_billing_audit_missing_years(
  uuid[], text[], boolean, uuid[], text, text, uuid, uuid, uuid, uuid, uuid,
  integer, integer, text, text, integer, integer, text, text)
  FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_billing_audit_missing_years(
  uuid[], text[], boolean, uuid[], text, text, uuid, uuid, uuid, uuid, uuid,
  integer, integer, text, text, integer, integer, text, text)
  TO authenticated, service_role;

-- ── B: summary ─────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.get_billing_audit_duplicate_years_summary(
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_include_non_tuition_institutions boolean DEFAULT false,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_admission_year integer DEFAULT NULL::integer,
  p_earliest_academic_year integer DEFAULT NULL::integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst         uuid[];
  v_adm_year_ids uuid[];
  v_result       jsonb;
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN jsonb_build_object(
      'combos', 0, 'learners', 0, 'bills', 0, 'extra_bills', 0,
      'total_billed', 0, 'outstanding', 0, 'generator_signature', 0,
      'unassigned_tuition_bills', 0,
      'past_end_bills', 0, 'past_end_learners', 0, 'past_end_outstanding', 0,
      'by_institution', '[]'::jsonb);
  END IF;

  IF p_admission_year IS NOT NULL THEN
    SELECT array_agg(ayr.id) INTO v_adm_year_ids
    FROM public.admission_years ayr WHERE ayr.year = p_admission_year;
  END IF;

  WITH tuition_inst AS MATERIALIZED (
    SELECT DISTINCT b.institution_id AS inst_id
    FROM public.billing_student_bills b
    JOIN public.billing_categories bc ON bc.id = b.item_category_id
    WHERE bc.kind = 'tuition'
      AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
  ),
  scope AS MATERIALIZED (
    SELECT lp.id, lp.institution_id, adm.year AS cohort,
           public.fn_programme_end_year(adm.year, p.program_duration_yrs) AS end_yr
    FROM public.learners_profiles lp
    LEFT JOIN public.admission_years adm ON adm.id = lp.admission_year_id
    LEFT JOIN public.programs p ON p.id = lp.program_id
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_tuition_institutions
           OR lp.institution_id IN (SELECT inst_id FROM tuition_inst))
      AND (p_admission_year IS NULL OR lp.admission_year_id = ANY(v_adm_year_ids))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
  ),
  tuition_bills AS MATERIALIZED (
    SELECT b.id, b.student_id, s.institution_id, s.end_yr,
           EXTRACT(YEAR FROM ay.start_date)::int AS yr,
           b.final_amount, COALESCE(b.balance_amount, 0) AS balance_amount,
           b.created_at, b.due_date
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    JOIN public.billing_categories bc ON bc.id = b.item_category_id AND bc.kind = 'tuition'
    JOIN public.academic_years ay ON ay.id = b.academic_year_id
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
      AND (p_earliest_academic_year IS NULL
           OR EXTRACT(YEAR FROM ay.start_date)::int >= p_earliest_academic_year)
  ),
  dup AS (
    SELECT tb.student_id AS learner_id, tb.institution_id,
           COUNT(*)::integer AS bill_count,
           SUM(tb.final_amount)::numeric AS total_billed,
           SUM(tb.balance_amount)::numeric AS outstanding,
           (COUNT(DISTINCT tb.created_at::date) = 1
            AND COUNT(DISTINCT EXTRACT(YEAR FROM tb.due_date)) > 1) AS is_generator_artefact
    FROM tuition_bills tb
    GROUP BY tb.student_id, tb.institution_id, tb.yr
    HAVING COUNT(*) > 1
  ),
  -- The INVERSE finding: a live tuition bill for a year after the programme
  -- ends. Tuition-kind only — a CRRI intern legitimately still has hostel and
  -- mess bills once the taught years finish, so widening this to every kind
  -- would report normal operation as an anomaly.
  past_end AS (
    SELECT tb.id, tb.student_id, tb.balance_amount
    FROM tuition_bills tb
    WHERE tb.end_yr IS NOT NULL AND tb.yr > tb.end_yr
  )
  SELECT jsonb_build_object(
    'combos',       (SELECT COUNT(*) FROM dup),
    'learners',     (SELECT COUNT(DISTINCT learner_id) FROM dup),
    'bills',        (SELECT COALESCE(SUM(bill_count), 0) FROM dup),
    'extra_bills',  (SELECT COALESCE(SUM(bill_count - 1), 0) FROM dup),
    'total_billed', (SELECT COALESCE(SUM(total_billed), 0) FROM dup),
    'outstanding',  (SELECT COALESCE(SUM(outstanding), 0) FROM dup),
    'generator_signature',
      (SELECT COUNT(*) FROM dup WHERE is_generator_artefact),
    'unassigned_tuition_bills', (
      SELECT COUNT(*)
      FROM public.billing_student_bills b
      JOIN scope s ON s.id = b.student_id
      JOIN public.billing_categories bc ON bc.id = b.item_category_id AND bc.kind = 'tuition'
      WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
        AND b.academic_year_id IS NULL
    ),
    'past_end_bills',       (SELECT COUNT(*) FROM past_end),
    'past_end_learners',    (SELECT COUNT(DISTINCT student_id) FROM past_end),
    'past_end_outstanding', (SELECT COALESCE(SUM(balance_amount), 0) FROM past_end),
    'by_institution', COALESCE((
      SELECT jsonb_agg(x ORDER BY x->>'institution_name')
      FROM (
        SELECT jsonb_build_object(
                 'institution_id',   d.institution_id,
                 'institution_name', COALESCE(i.name::text, 'Unknown'),
                 'combos',           COUNT(*),
                 'learners',         COUNT(DISTINCT d.learner_id),
                 'extra_bills',      COALESCE(SUM(d.bill_count - 1), 0)
               ) AS x
        FROM dup d
        LEFT JOIN public.institutions i ON i.id = d.institution_id
        GROUP BY d.institution_id, i.name
      ) sub
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$function$;

-- ── B: list ────────────────────────────────────────────────────────────────
DROP FUNCTION IF EXISTS public.get_billing_audit_duplicate_years(
  uuid[], text[], boolean, uuid[], text, text, uuid, uuid, uuid, uuid, uuid,
  integer, integer, text, integer, integer, text, text);

CREATE FUNCTION public.get_billing_audit_duplicate_years(
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_include_non_tuition_institutions boolean DEFAULT false,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_admission_year integer DEFAULT NULL::integer,
  p_earliest_academic_year integer DEFAULT NULL::integer,
  p_search text DEFAULT NULL::text,
  p_page integer DEFAULT 1,
  p_page_size integer DEFAULT 50,
  p_sort_by text DEFAULT NULL::text,
  p_sort_dir text DEFAULT 'asc'::text
)
RETURNS TABLE(
  out_audit_row_id text, out_learner_id uuid, out_roll_number text,
  out_register_number text, out_full_name text, out_lifecycle_status text,
  out_institution_id uuid, out_institution_name text, out_program_name text,
  out_semester_section text, out_admission_year integer,
  out_academic_year_name text, out_bill_count integer, out_category_names text,
  out_total_billed numeric, out_total_paid numeric, out_outstanding numeric,
  out_created_same_day boolean, out_due_year_span integer,
  out_programme_end_year text, out_is_past_programme_end boolean,
  out_total_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst   uuid[];
  v_limit  integer := LEAST(GREATEST(COALESCE(NULLIF(p_page_size, 0), 50), 1), 5000);
  v_offset integer := GREATEST(COALESCE(p_page, 1) - 1, 0)
                      * LEAST(GREATEST(COALESCE(NULLIF(p_page_size, 0), 50), 1), 5000);
  v_asc    boolean := COALESCE(LOWER(p_sort_dir), 'asc') <> 'desc';
  v_adm_year_ids uuid[];
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN;
  END IF;

  IF p_admission_year IS NOT NULL THEN
    SELECT array_agg(ayr.id) INTO v_adm_year_ids
    FROM public.admission_years ayr WHERE ayr.year = p_admission_year;
  END IF;

  RETURN QUERY
  WITH tuition_inst AS MATERIALIZED (
    SELECT DISTINCT b.institution_id AS inst_id
    FROM public.billing_student_bills b
    JOIN public.billing_categories bc ON bc.id = b.item_category_id
    WHERE bc.kind = 'tuition'
      AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
  ),
  scope AS MATERIALIZED (
    SELECT lp.id, lp.institution_id, lp.program_id, lp.semester_id, lp.section_id,
           lp.lifecycle_status, lp.first_name, lp.last_name, lp.roll_number,
           lp.register_number, adm.year AS cohort,
           public.fn_programme_end_year(adm.year, p.program_duration_yrs) AS end_yr
    FROM public.learners_profiles lp
    LEFT JOIN public.admission_years adm ON adm.id = lp.admission_year_id
    LEFT JOIN public.programs p ON p.id = lp.program_id
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_tuition_institutions
           OR lp.institution_id IN (SELECT inst_id FROM tuition_inst))
      AND (p_admission_year IS NULL OR lp.admission_year_id = ANY(v_adm_year_ids))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
      AND (
        p_search IS NULL OR p_search = ''
        OR lp.roll_number ILIKE '%' || p_search || '%'
        OR lp.register_number ILIKE '%' || p_search || '%'
        OR (COALESCE(lp.first_name,'') || ' ' || COALESCE(lp.last_name,''))
             ILIKE '%' || p_search || '%'
      )
  ),
  dup AS (
    SELECT b.student_id AS learner_id,
           EXTRACT(YEAR FROM ay.start_date)::integer AS yr,
           COUNT(*)::integer AS bill_count,
           string_agg(DISTINCT bc.category_name::text, ', '
                      ORDER BY bc.category_name::text) AS category_names,
           SUM(b.final_amount)::numeric AS total_billed,
           SUM(b.final_amount - COALESCE(b.balance_amount, 0))::numeric AS total_paid,
           SUM(COALESCE(b.balance_amount, 0))::numeric AS outstanding,
           (COUNT(DISTINCT b.created_at::date) = 1) AS created_same_day,
           COUNT(DISTINCT EXTRACT(YEAR FROM b.due_date))::integer AS due_year_span
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    JOIN public.billing_categories bc ON bc.id = b.item_category_id AND bc.kind = 'tuition'
    JOIN public.academic_years ay ON ay.id = b.academic_year_id
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
      AND (p_earliest_academic_year IS NULL
           OR EXTRACT(YEAR FROM ay.start_date)::int >= p_earliest_academic_year)
    GROUP BY b.student_id, EXTRACT(YEAR FROM ay.start_date)::integer
    HAVING COUNT(*) > 1
  ),
  final AS (
    SELECT (s.id::text || ':' || d.yr::text) AS audit_row_id,
           s.id AS learner_id,
           s.roll_number::text     AS roll_number,
           s.register_number::text AS register_number,
           TRIM(COALESCE(s.first_name,'') || ' ' || COALESCE(s.last_name,''))
                                   AS full_name,
           s.lifecycle_status::text AS lifecycle_status,
           s.institution_id        AS institution_id,
           i.name::text            AS institution_name,
           p.program_name          AS program_name,
           CASE
             WHEN sem.semester_name IS NULL AND sec.section_name IS NULL THEN NULL
             WHEN sec.section_name IS NULL THEN sem.semester_name::text
             WHEN sem.semester_name IS NULL THEN sec.section_name::text
             ELSE sem.semester_name::text || ' · ' || sec.section_name::text
           END                     AS semester_section,
           s.cohort                AS admission_year,
           (d.yr::text || '-' || (d.yr + 1)::text) AS academic_year_name,
           d.bill_count, d.category_names, d.total_billed, d.total_paid,
           d.outstanding, d.created_same_day, d.due_year_span,
           s.end_yr                AS programme_end_yr,
           (s.end_yr IS NOT NULL AND d.yr > s.end_yr) AS is_past_programme_end
    FROM dup d
    JOIN scope s ON s.id = d.learner_id
    LEFT JOIN public.institutions i   ON i.id   = s.institution_id
    LEFT JOIN public.programs     p   ON p.id   = s.program_id
    LEFT JOIN public.semesters    sem ON sem.id = s.semester_id
    LEFT JOIN public.sections     sec ON sec.id = s.section_id
  )
  SELECT f.audit_row_id, f.learner_id, f.roll_number, f.register_number,
         f.full_name, f.lifecycle_status, f.institution_id, f.institution_name,
         f.program_name, f.semester_section, f.admission_year,
         f.academic_year_name, f.bill_count, f.category_names,
         f.total_billed, f.total_paid, f.outstanding,
         f.created_same_day, f.due_year_span,
         CASE WHEN f.programme_end_yr IS NULL THEN NULL
              ELSE f.programme_end_yr::text || '-' || (f.programme_end_yr + 1)::text
         END,
         f.is_past_programme_end,
         COUNT(*) OVER ()::bigint
  FROM final f
  ORDER BY
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'academic_year_name' THEN f.academic_year_name
         WHEN 'category_names'     THEN f.category_names
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'academic_year_name' THEN f.academic_year_name
         WHEN 'category_names'     THEN f.category_names
       END
     END) DESC NULLS LAST,
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'admission_year' THEN f.admission_year::numeric
         WHEN 'bill_count'     THEN f.bill_count::numeric
         WHEN 'total_billed'   THEN f.total_billed
         WHEN 'total_paid'     THEN f.total_paid
         WHEN 'outstanding'    THEN f.outstanding
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'admission_year' THEN f.admission_year::numeric
         WHEN 'bill_count'     THEN f.bill_count::numeric
         WHEN 'total_billed'   THEN f.total_billed
         WHEN 'total_paid'     THEN f.total_paid
         WHEN 'outstanding'    THEN f.outstanding
       END
     END) DESC NULLS LAST,
    -- Bills sitting past the programme end float to the top: they are the
    -- least explicable rows on the screen.
    f.is_past_programme_end DESC, f.bill_count DESC,
    f.institution_name NULLS LAST, f.roll_number NULLS LAST, f.academic_year_name
  LIMIT v_limit OFFSET v_offset;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_billing_audit_duplicate_years(
  uuid[], text[], boolean, uuid[], text, text, uuid, uuid, uuid, uuid, uuid,
  integer, integer, text, integer, integer, text, text)
  FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_billing_audit_duplicate_years(
  uuid[], text[], boolean, uuid[], text, text, uuid, uuid, uuid, uuid, uuid,
  integer, integer, text, integer, integer, text, text)
  TO authenticated, service_role;

-- =====================================================================
-- Added: 2026-08-13 - Course Events core: package amount integrity +
-- updated_at maintenance
-- Mirror of migration 20260813100000_course_events_core.sql
-- Tables -> setup/01_tables.sql. Triggers -> setup/04_triggers.sql.
-- =====================================================================

-- A package whose parts do not add up to its price is the single most
-- damaging thing that can silently ship here: bills would be generated
-- that can never reach a zero balance, so the participant could never
-- become 'confirmed' and could never attend.
--
-- DEFERRABLE INITIALLY DEFERRED so a multi-row edit may pass through an
-- inconsistent state inside a transaction but can never COMMIT one.
--
-- A package with ZERO installments is allowed — it is a draft being
-- built. Bill generation (Phase 4) refuses such a package separately.
-- Rejecting it here would force every package insert to carry its whole
-- schedule in the same statement.
-- Corrected 2026-08-13: INVOKER -> SECURITY DEFINER. RLS otherwise
-- filters the cross-table SELECT/UPDATEs silently for a caller who
-- lacks the target table's permission (see fn_course_recompute_balances
-- below for the full reasoning). Mirrors migration 20260813100450.
CREATE OR REPLACE FUNCTION public.fn_course_package_amounts_chk()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_package_id uuid;
  v_total      numeric(12,2);
  v_sum        numeric(12,2);
  v_count      int;
BEGIN
  -- One function, two triggers: the installments table exposes
  -- package_id, the packages table exposes id.
  IF TG_TABLE_NAME = 'course_packages' THEN
    v_package_id := COALESCE(NEW.id, OLD.id);
  ELSE
    v_package_id := COALESCE(NEW.package_id, OLD.package_id);
  END IF;

  SELECT total_amount INTO v_total
    FROM public.course_packages
   WHERE id = v_package_id;

  -- The package itself was deleted in this transaction (ON DELETE
  -- CASCADE removed its installments). Nothing left to reconcile.
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(sum(amount), 0), count(*)
    INTO v_sum, v_count
    FROM public.course_package_installments
   WHERE package_id = v_package_id;

  IF v_count > 0 AND v_sum <> v_total THEN
    RAISE EXCEPTION
      'Course package % has % installments totalling % but its price is %. The schedule must add up to the price.',
      v_package_id, v_count, v_sum, v_total
      USING ERRCODE = '23514';
  END IF;

  RETURN NULL;
END;
$fn$;

COMMENT ON FUNCTION public.fn_course_package_amounts_chk() IS
  'Constraint-trigger body shared by course_packages and course_package_installments: the installment schedule must sum to the package price at COMMIT. Zero installments is permitted (draft package).';

CREATE OR REPLACE FUNCTION public.fn_courses_touch_updated_at()
RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$fn$;

-- ---------------------------------------------------------------------
-- Mirror of migration 20260813100400_course_billing.sql
-- ---------------------------------------------------------------------
-- Sole writer of course_bills.paid_amount/balance_amount/status and
-- course_enrollments.total_paid/balance/status. Two rules easy to get
-- wrong and expensive to get wrong:
--   * VOIDED bills are excluded from every total. A withdrawal voids the
--     unpaid future installments; if they still counted, the enrollment
--     would hold a permanent non-zero balance and could never leave
--     payment_overdue.
--   * withdrawn / cancelled / completed are TERMINAL. The money columns
--     still refresh, but the status is not recomputed over the top.
--
-- Corrected 2026-08-13: INVOKER -> SECURITY DEFINER. A trigger function
-- runs with the caller's privileges and RLS applies; a role holding
-- courses.billing.manage but not courses.enrollments.manage had the
-- UPDATE on course_enrollments silently filtered to zero rows with no
-- error. Mirrors migration 20260813100450.
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_course_recompute_balances()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_bill_id       uuid;
  v_enrollment_id uuid;
  v_paid          numeric(12,2);
  v_total         numeric(12,2);
  v_due           date;
  v_status        text;
  v_e_payable     numeric(12,2);
  v_e_paid        numeric(12,2);
  v_overdue       boolean;
  v_e_status      text;
BEGIN
  v_bill_id := COALESCE(NEW.bill_id, OLD.bill_id);

  SELECT COALESCE(sum(amount_paid), 0)
    INTO v_paid
    FROM public.course_bill_payments
   WHERE bill_id = v_bill_id
     AND status = 'success';

  SELECT total_amount, due_date, status, enrollment_id
    INTO v_total, v_due, v_status, v_enrollment_id
    FROM public.course_bills
   WHERE id = v_bill_id;

  IF NOT FOUND THEN
    RETURN NULL;   -- bill removed in this transaction
  END IF;

  UPDATE public.course_bills
     SET paid_amount    = v_paid,
         balance_amount = v_total - v_paid,
         status = CASE
                    WHEN v_status = 'voided'   THEN 'voided'
                    WHEN v_total - v_paid <= 0 THEN 'paid'
                    WHEN v_due < CURRENT_DATE  THEN 'overdue'
                    WHEN v_paid > 0            THEN 'partially_paid'
                    ELSE 'pending'
                  END,
         updated_at = now()
   WHERE id = v_bill_id;

  -- Roll up to the enrollment, excluding voided bills entirely.
  SELECT COALESCE(sum(total_amount), 0),
         COALESCE(sum(paid_amount), 0),
         bool_or(balance_amount > 0 AND due_date < CURRENT_DATE)
    INTO v_e_payable, v_e_paid, v_overdue
    FROM public.course_bills
   WHERE enrollment_id = v_enrollment_id
     AND status <> 'voided';

  SELECT status INTO v_e_status
    FROM public.course_enrollments
   WHERE id = v_enrollment_id;

  UPDATE public.course_enrollments
     SET total_paid = v_e_paid,
         balance    = v_e_payable - v_e_paid,
         status = CASE
                    -- terminal states are never recomputed over
                    WHEN v_e_status IN ('withdrawn','cancelled','completed')
                      THEN v_e_status
                    WHEN v_e_payable - v_e_paid <= 0 THEN 'confirmed'
                    WHEN COALESCE(v_overdue, false) THEN 'payment_overdue'
                    ELSE 'active'
                  END,
         updated_at = now()
   WHERE id = v_enrollment_id;

  RETURN NULL;
END;
$fn$;

COMMENT ON FUNCTION public.fn_course_recompute_balances() IS
  'Sole writer of course_bills.paid_amount/balance_amount/status and course_enrollments.total_paid/balance/status. Voided bills are excluded from rollups; withdrawn/cancelled/completed are terminal.';


-- ----------------------------------------------------------------------------
-- Added: 2026-08-19 - Course Events Phase 2b: atomic package + schedule save
-- ----------------------------------------------------------------------------
-- fn_course_package_amounts_chk (above) is DEFERRABLE INITIALLY DEFERRED on BOTH
-- package tables, so it evaluates at COMMIT. PostgREST wraps each request in its
-- own transaction, which makes repricing a package impossible in two calls --
-- whichever half commits first trips 23514 against the other half's stale value.
-- This RPC is the single save path for both create and edit.
--
-- SECURITY INVOKER is load-bearing, not an oversight: course_packages_manage and
-- course_package_installments_manage already gate on courses.packages.manage AND
-- role_has_institution_access(), so running as the caller inherits the predicate
-- and it cannot drift. A DEFINER rewrite would bypass RLS and have to re-copy it.
-- The cost is that a blocked UPDATE/DELETE affects zero rows SILENTLY under RLS,
-- so the body verifies its own writes and raises 42501 rather than assuming.
-- Full rationale: supabase/migrations/20260819010000_course_package_save_rpc.sql

CREATE OR REPLACE FUNCTION public.fn_save_course_package(
  p_package      jsonb,
  p_installments jsonb
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $function$
DECLARE
  v_package_id      uuid;
  v_course_event_id uuid;
  v_institution_id  uuid;
  v_rows            int;
  v_remaining       int;
  v_installments    jsonb;
  v_inst            jsonb;
  v_no              smallint := 0;
BEGIN
  v_package_id      := NULLIF(btrim(COALESCE(p_package->>'id', '')), '')::uuid;
  v_course_event_id := NULLIF(btrim(COALESCE(p_package->>'course_event_id', '')), '')::uuid;

  IF v_course_event_id IS NULL THEN
    RAISE EXCEPTION 'course_event_id is required to save a package'
      USING ERRCODE = '22023';
  END IF;

  -- The tenant is resolved from the course, NEVER trusted from the payload.
  SELECT institution_id INTO v_institution_id
    FROM course_events
   WHERE id = v_course_event_id;

  IF v_institution_id IS NULL THEN
    RAISE EXCEPTION 'Course % was not found, or you do not have access to it', v_course_event_id
      USING ERRCODE = '42501';
  END IF;

  IF v_package_id IS NULL THEN
    INSERT INTO course_packages (
      course_event_id, institution_id, name, description, total_amount, currency,
      seat_cap, sale_opens_at, sale_closes_at, is_active, display_order
    ) VALUES (
      v_course_event_id,
      v_institution_id,
      btrim(p_package->>'name'),
      NULLIF(btrim(COALESCE(p_package->>'description', '')), ''),
      (p_package->>'total_amount')::numeric,
      COALESCE(NULLIF(btrim(COALESCE(p_package->>'currency', '')), ''), 'INR'),
      NULLIF(btrim(COALESCE(p_package->>'seat_cap', '')), '')::int,
      NULLIF(btrim(COALESCE(p_package->>'sale_opens_at', '')), '')::timestamptz,
      NULLIF(btrim(COALESCE(p_package->>'sale_closes_at', '')), '')::timestamptz,
      COALESCE((p_package->>'is_active')::boolean, true),
      COALESCE(NULLIF(btrim(COALESCE(p_package->>'display_order', '')), '')::int, 0)
    )
    RETURNING id INTO v_package_id;
    -- No row-count check needed: an RLS WITH CHECK failure on INSERT raises 42501.
  ELSE
    -- course_event_id is in the WHERE, not the SET: a package must never move
    -- between courses, and this also stops a caller from editing some other
    -- course's package by pairing its id with a course they can reach.
    UPDATE course_packages SET
      name           = btrim(p_package->>'name'),
      description    = NULLIF(btrim(COALESCE(p_package->>'description', '')), ''),
      total_amount   = (p_package->>'total_amount')::numeric,
      currency       = COALESCE(NULLIF(btrim(COALESCE(p_package->>'currency', '')), ''), 'INR'),
      seat_cap       = NULLIF(btrim(COALESCE(p_package->>'seat_cap', '')), '')::int,
      sale_opens_at  = NULLIF(btrim(COALESCE(p_package->>'sale_opens_at', '')), '')::timestamptz,
      sale_closes_at = NULLIF(btrim(COALESCE(p_package->>'sale_closes_at', '')), '')::timestamptz,
      is_active      = COALESCE((p_package->>'is_active')::boolean, true),
      display_order  = COALESCE(NULLIF(btrim(COALESCE(p_package->>'display_order', '')), '')::int, 0)
    WHERE id = v_package_id
      AND course_event_id = v_course_event_id;

    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows = 0 THEN
      RAISE EXCEPTION
        'Package % could not be updated — it does not belong to course %, or you lack courses.packages.manage on it',
        v_package_id, v_course_event_id
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Full replace, never a diff: the deferred trigger validates the end state.
  DELETE FROM course_package_installments WHERE package_id = v_package_id;

  -- Zero deleted rows is legitimate (a package that had no schedule), so the
  -- check is "is anything still there?" -- what an RLS-blocked DELETE leaves.
  SELECT count(*) INTO v_remaining
    FROM course_package_installments
   WHERE package_id = v_package_id;

  IF v_remaining > 0 THEN
    RAISE EXCEPTION
      'Could not clear the existing schedule for package % — % row(s) remain; you lack courses.packages.manage on them',
      v_package_id, v_remaining
      USING ERRCODE = '42501';
  END IF;

  -- A JSON null, a missing key or a non-array all mean "no schedule". COALESCE
  -- would not catch a JSON null, and jsonb_array_elements raises on a scalar.
  v_installments := CASE
    WHEN jsonb_typeof(p_installments) = 'array' THEN p_installments
    ELSE '[]'::jsonb
  END;

  FOR v_inst IN SELECT * FROM jsonb_array_elements(v_installments)
  LOOP
    -- Renumbered from 1 in array order rather than taken from the client, so a
    -- reordered UI can never violate UNIQUE (package_id, installment_no).
    v_no := v_no + 1;

    INSERT INTO course_package_installments (package_id, installment_no, label, amount, due_date)
    VALUES (
      v_package_id,
      v_no,
      NULLIF(btrim(COALESCE(v_inst->>'label', '')), ''),
      (v_inst->>'amount')::numeric,
      NULLIF(btrim(COALESCE(v_inst->>'due_date', '')), '')::date
    );
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'package_id', v_package_id,
    'installment_count', v_no
  );
END;
$function$;

-- Supabase's default privileges grant EXECUTE to anon DIRECTLY, so revoking from
-- PUBLIC alone leaves anon holding it. Revoke from both, explicitly.
REVOKE ALL ON FUNCTION public.fn_save_course_package(jsonb, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fn_save_course_package(jsonb, jsonb) FROM anon;
GRANT EXECUTE ON FUNCTION public.fn_save_course_package(jsonb, jsonb) TO authenticated;

COMMENT ON FUNCTION public.fn_save_course_package(jsonb, jsonb) IS
  'Saves a course package and replaces its installment schedule in ONE transaction. '
  'Required because fn_course_package_amounts_chk is a DEFERRABLE INITIALLY DEFERRED '
  'constraint trigger evaluated at COMMIT, so a reprice cannot be split across two '
  'PostgREST calls. SECURITY INVOKER: the caller''s own RLS (courses.packages.manage) '
  'applies inside the body. Because a blocked UPDATE/DELETE affects zero rows silently '
  'under RLS, the function verifies its writes and raises 42501 rather than assuming.';


-- ----------------------------------------------------------------------------
-- Added: 2026-08-20 - Course Events Phase 3: atomic registration-form save
-- ----------------------------------------------------------------------------
-- A form save is a parent plus two levels of children and REPLACES rather than
-- merges. Split across REST calls, a failure between "delete the old structure"
-- and "insert the new one" leaves a live PUBLIC form with no fields — worse than
-- not saving, because it stays reachable and collects nothing.
--
-- SECURITY INVOKER is load-bearing: course_registration_forms_manage already
-- gates on courses.forms.manage AND role_has_institution_access(), so the caller
-- inherits the predicate and it cannot drift. The cost is that a blocked
-- UPDATE/DELETE affects zero rows SILENTLY under RLS, so the body verifies its
-- own writes and raises 42501.
--
-- Every field is written with an EXPLICIT form_id rather than relying on its
-- section link. The Events builder hung fields off sections only while callers
-- filtered by event_id, and the moment a second form existed every form rendered
-- every other form's fields.
-- Full rationale: supabase/migrations/20260820010000_course_form_save_rpc.sql

CREATE OR REPLACE FUNCTION public.fn_save_course_registration_form(
  p_form     jsonb,
  p_sections jsonb
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $function$
DECLARE
  v_form_id         uuid;
  v_course_event_id uuid;
  v_institution_id  uuid;
  v_rows            int;
  v_remaining       int;
  v_sections        jsonb;
  v_section         jsonb;
  v_section_id      uuid;
  v_field           jsonb;
  v_section_no      int := 0;
  v_field_no        int := 0;
  v_field_count     int := 0;
BEGIN
  v_form_id         := NULLIF(btrim(COALESCE(p_form->>'id', '')), '')::uuid;
  v_course_event_id := NULLIF(btrim(COALESCE(p_form->>'course_event_id', '')), '')::uuid;

  IF v_course_event_id IS NULL THEN
    RAISE EXCEPTION 'course_event_id is required to save a registration form'
      USING ERRCODE = '22023';
  END IF;

  -- The tenant is resolved from the course, NEVER trusted from the payload.
  SELECT institution_id INTO v_institution_id
    FROM course_events
   WHERE id = v_course_event_id;

  IF v_institution_id IS NULL THEN
    RAISE EXCEPTION 'Course % was not found, or you do not have access to it', v_course_event_id
      USING ERRCODE = '42501';
  END IF;

  IF v_form_id IS NULL THEN
    INSERT INTO course_registration_forms (
      course_event_id, institution_id, name, slug, description, display_order, is_enabled
    ) VALUES (
      v_course_event_id,
      v_institution_id,
      btrim(p_form->>'name'),
      btrim(p_form->>'slug'),
      NULLIF(btrim(COALESCE(p_form->>'description', '')), ''),
      COALESCE(NULLIF(btrim(COALESCE(p_form->>'display_order', '')), '')::int, 0),
      -- A form is born CLOSED. Enabling it opens public intake and must be
      -- deliberate — never a side effect of saving a draft.
      COALESCE((p_form->>'is_enabled')::boolean, false)
    )
    RETURNING id INTO v_form_id;
  ELSE
    -- course_event_id is in the WHERE, not the SET: a form must never move
    -- between courses.
    UPDATE course_registration_forms SET
      name          = btrim(p_form->>'name'),
      slug          = btrim(p_form->>'slug'),
      description   = NULLIF(btrim(COALESCE(p_form->>'description', '')), ''),
      display_order = COALESCE(NULLIF(btrim(COALESCE(p_form->>'display_order', '')), '')::int, 0),
      is_enabled    = COALESCE((p_form->>'is_enabled')::boolean, false)
    WHERE id = v_form_id
      AND course_event_id = v_course_event_id;

    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows = 0 THEN
      RAISE EXCEPTION
        'Form % could not be updated — it does not belong to course %, or you lack courses.forms.manage on it',
        v_form_id, v_course_event_id
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Fields are deleted BY FORM, not left to cascade off sections: a field may
  -- legitimately have section_id NULL, and those would survive a sections-only
  -- delete then collide on UNIQUE (form_id, field_key).
  DELETE FROM course_registration_form_fields WHERE form_id = v_form_id;
  DELETE FROM course_registration_form_sections WHERE form_id = v_form_id;

  SELECT (SELECT count(*) FROM course_registration_form_fields WHERE form_id = v_form_id)
       + (SELECT count(*) FROM course_registration_form_sections WHERE form_id = v_form_id)
    INTO v_remaining;

  IF v_remaining > 0 THEN
    RAISE EXCEPTION
      'Could not clear the existing structure of form % — % row(s) remain; you lack courses.forms.manage on them',
      v_form_id, v_remaining
      USING ERRCODE = '42501';
  END IF;

  v_sections := CASE
    WHEN jsonb_typeof(p_sections) = 'array' THEN p_sections
    ELSE '[]'::jsonb
  END;

  FOR v_section IN SELECT * FROM jsonb_array_elements(v_sections)
  LOOP
    INSERT INTO course_registration_form_sections (form_id, title, description, display_order)
    VALUES (
      v_form_id,
      COALESCE(NULLIF(btrim(COALESCE(v_section->>'title', '')), ''), 'Section'),
      NULLIF(btrim(COALESCE(v_section->>'description', '')), ''),
      v_section_no
    )
    RETURNING id INTO v_section_id;
    v_section_no := v_section_no + 1;

    FOR v_field IN
      SELECT * FROM jsonb_array_elements(
        CASE WHEN jsonb_typeof(v_section->'fields') = 'array'
             THEN v_section->'fields' ELSE '[]'::jsonb END)
    LOOP
      INSERT INTO course_registration_form_fields (
        -- form_id EXPLICIT, not inferred from the section. This is the whole
        -- point: a reader filtering by form_id cannot pick up another form's
        -- fields, which is the bug the Events builder shipped.
        form_id, section_id, field_key, label, field_type, is_required,
        options, placeholder, help_text, validation, display_order
      ) VALUES (
        v_form_id,
        v_section_id,
        btrim(v_field->>'field_key'),
        btrim(v_field->>'label'),
        v_field->>'field_type',
        COALESCE((v_field->>'is_required')::boolean, false),
        -- options/validation are NOT NULL jsonb — a missing key, JSON null or
        -- wrong type must become the empty default, not a 23502.
        CASE WHEN jsonb_typeof(v_field->'options') = 'array'
             THEN v_field->'options' ELSE '[]'::jsonb END,
        NULLIF(btrim(COALESCE(v_field->>'placeholder', '')), ''),
        NULLIF(btrim(COALESCE(v_field->>'help_text', '')), ''),
        CASE WHEN jsonb_typeof(v_field->'validation') = 'object'
             THEN v_field->'validation' ELSE '{}'::jsonb END,
        v_field_no
      );
      v_field_no    := v_field_no + 1;
      v_field_count := v_field_count + 1;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'form_id', v_form_id,
    'section_count', v_section_no,
    'field_count', v_field_count
  );
END;
$function$;

-- Supabase's default privileges grant EXECUTE to anon DIRECTLY, so revoking from
-- PUBLIC alone leaves anon holding it. Revoke from both, explicitly.
REVOKE ALL ON FUNCTION public.fn_save_course_registration_form(jsonb, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fn_save_course_registration_form(jsonb, jsonb) FROM anon;
GRANT EXECUTE ON FUNCTION public.fn_save_course_registration_form(jsonb, jsonb) TO authenticated;

COMMENT ON FUNCTION public.fn_save_course_registration_form(jsonb, jsonb) IS
  'Saves a course registration form and REPLACES its sections and fields in ONE '
  'transaction — a half-replaced form would stay publicly reachable while '
  'collecting nothing. SECURITY INVOKER: the caller''s own RLS '
  '(courses.forms.manage) applies inside the body, and because a blocked '
  'UPDATE/DELETE affects zero rows silently under RLS the function verifies its '
  'writes and raises 42501. Every field is written with an explicit form_id so a '
  'reader filtering by form_id can never pick up another form''s fields.';


-- ============================================================================
-- Bill Coverage Audit: count TUITION-EQUIVALENT categories as year coverage
-- ============================================================================
-- Supersedes the bodies written by 20260812170100 (which bounded the window by
-- programme duration — that rule is unchanged and carried forward verbatim).
--
-- THE BUG. Both audits asked "does this learner hold a bill of kind = 'tuition'
-- for this academic year?". Three fee categories are tuition in everything but
-- their `kind` column, and for the learners who carry them they are the ONLY
-- fee raised for that year — so the audit reported a bill that had in fact been
-- raised as one that was never generated:
--
--   Government 7-5 quota   70 bills  Dental + Engineering  2023-24 .. 2026-27
--   CRRI - INTERNSHIP FEE  77 bills  Dental                2026-27
--   AHS - INTERNSHIP FEE   36 bills  Allied Health         2026-27
--
-- Measured before/after on 2026-08-13, all 14 institutions, default lifecycle:
-- missing slots 2,160 -> 2,014 (146 resolved), gap learners 914 -> 891, of
-- which 23 become complete outright and 80 shed some but not all of their gap.
-- Every one of the 183 bills is the SOLE coverage for its learner-year — not
-- one sits beside a tuition-kind bill — so nothing here is double-counting.
--
-- WHY NOT RE-KIND THEM. `billing_categories.kind` is an enum consumed by fee
-- structures, Razorpay fee-head routing and the analytics RPCs. Moving these
-- three to 'tuition' would silently change all of that to fix one screen. The
-- audit's own predicate is the contained place to widen.
--
-- THREE THINGS DELIBERATELY NOT WIDENED
--
-- 1. `past_end` / `is_past_programme_end` stay STRICTLY kind = 'tuition'.
--    program_duration_yrs counts TAUGHT years, so an internship fee belongs to
--    the year AFTER the course ends by design: all 8 Allied Health BSc
--    programmes are dur = 4.0 and bill their internship in cohort+4. Widening
--    here would manufacture 37 anomalies (36 AHS + 1 BDS cohort 2020) out of
--    entirely correct billing — the same trap 20260812170100's header called
--    out when it kept this check narrow.
--
-- 2. The Coverage tab's RPCs are untouched. They take p_billing_category_id and
--    measure one named category against one year, so they never had a
--    hardcoded tuition predicate to widen.
--
-- 3. `kind` itself. See above.
--
-- WHAT DOES CHANGE BUT MEASURES AS ZERO. The duplicate check widens too, for
-- consistency: a category that counts as coverage must also count toward "more
-- than one bill in a year". Today that adds 0 combos — these three never
-- co-occur with a tuition bill — but leaving it narrow would mean a learner
-- could be double-billed on Government 7-5 quota and the check would not see
-- it. The institution guard (`tuition_inst`) widens for the same reason; also
-- a measured no-op, since all three institutions already raise tuition bills.
-- ============================================================================

-- ── The category set, defined once ─────────────────────────────────────────
-- Ten predicates across four RPCs resolve "counts as a year's tuition" through
-- this function, so the definition cannot drift between the summary card and
-- the table under it.
--
-- Matched by ID, not by name: `category_name` is editable from
-- /billing/categories, and a rename would silently narrow the audit back to
-- kind-only — reinstating the false gaps with no error anywhere. Bills carry an
-- FK to these rows, so the ids cannot be deleted out from under it.
--
-- SECURITY DEFINER because billing_categories has RLS enabled: a caller who
-- cannot read every category must still get the whole set, or the audit's
-- verdict would vary by who is looking at it.
CREATE OR REPLACE FUNCTION public.fn_billing_tuition_equivalent_category_ids()
RETURNS uuid[]
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  SELECT COALESCE(array_agg(bc.id), ARRAY[]::uuid[])
  FROM public.billing_categories bc
  WHERE bc.kind = 'tuition'
     OR bc.id IN (
          '1035e234-c52c-4b46-9194-392931a3469d',  -- Government 7-5 quota
          '50603f99-65f6-4a18-9599-71ba32fe3e35',  -- CRRI - INTERNSHIP FEE
          'ff4a43f7-65ee-4ed8-89e1-1948051df432'   -- AHS - INTERNSHIP FEE
        );
$function$;

REVOKE ALL ON FUNCTION public.fn_billing_tuition_equivalent_category_ids()
  FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_billing_tuition_equivalent_category_ids()
  TO authenticated, service_role;

COMMENT ON FUNCTION public.fn_billing_tuition_equivalent_category_ids() IS
  'Billing categories that satisfy a learner''s tuition obligation for an academic year: every kind = ''tuition'' category, plus Government 7-5 quota and the CRRI / AHS internship fees, which are tuition-equivalent but carry kind = ''other''. Used by the /billing/coverage Audit tab. NOT used by the past-programme-end check, which is strictly kind = ''tuition''.';

-- ── A: summary ─────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.get_billing_audit_missing_years_summary(
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_include_non_tuition_institutions boolean DEFAULT false,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_admission_year integer DEFAULT NULL::integer,
  p_earliest_academic_year integer DEFAULT NULL::integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst         uuid[];
  v_adm_year_ids uuid[];
  v_cov_cats     uuid[];
  v_result       jsonb;
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  -- Resolved once per call, not per predicate: ten sites read it below, and a
  -- STABLE function re-evaluated inside every join would be re-planned each time.
  v_cov_cats := public.fn_billing_tuition_equivalent_category_ids();

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN jsonb_build_object(
      'in_scope', 0, 'gap', 0, 'complete', 0, 'cannot_evaluate', 0,
      'missing_slots', 0, 'backlog_only', 0, 'no_tuition_at_all', 0,
      'duration_not_set', 0,
      'excluded_institutions', 0, 'excluded_learners', 0,
      'by_institution', '[]'::jsonb, 'available_academic_years', '[]'::jsonb);
  END IF;

  IF p_admission_year IS NOT NULL THEN
    SELECT array_agg(ayr.id) INTO v_adm_year_ids
    FROM public.admission_years ayr WHERE ayr.year = p_admission_year;
  END IF;

  WITH tuition_inst AS MATERIALIZED (
    SELECT DISTINCT b.institution_id AS inst_id
    FROM public.billing_student_bills b
    JOIN public.billing_categories bc ON bc.id = b.item_category_id
    WHERE bc.id = ANY(v_cov_cats)
      AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
  ),
  target AS MATERIALIZED (
    SELECT t.institution_id, EXTRACT(YEAR FROM ay.start_date)::int AS ceiling_yr
    FROM public.fn_billing_coverage_target_years() t
    JOIN public.academic_years ay ON ay.id = t.target_ay_id
  ),
  inst_years AS MATERIALIZED (
    SELECT DISTINCT ay.institution_id, EXTRACT(YEAR FROM ay.start_date)::int AS yr
    FROM public.academic_years ay WHERE ay.is_active IS TRUE
  ),
  all_scope AS MATERIALIZED (
    SELECT lp.id, lp.institution_id, adm.year AS cohort, t.ceiling_yr,
           p.program_duration_yrs AS dur,
           -- The window's upper bound: whichever comes first, the institution's
           -- current year or the end of this learner's programme.
           LEAST(t.ceiling_yr,
                 COALESCE(public.fn_programme_end_year(adm.year, p.program_duration_yrs),
                          t.ceiling_yr)) AS window_end_yr,
           (lp.institution_id IN (SELECT inst_id FROM tuition_inst)) AS is_tuition_inst
    FROM public.learners_profiles lp
    LEFT JOIN public.admission_years adm ON adm.id = lp.admission_year_id
    LEFT JOIN public.programs p ON p.id = lp.program_id
    LEFT JOIN target t ON t.institution_id = lp.institution_id
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_admission_year IS NULL OR lp.admission_year_id = ANY(v_adm_year_ids))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
  ),
  scope AS MATERIALIZED (
    SELECT * FROM all_scope
    WHERE p_include_non_tuition_institutions OR is_tuition_inst
  ),
  covered AS MATERIALIZED (
    SELECT DISTINCT b.student_id,
           EXTRACT(YEAR FROM ay.start_date)::int AS yr
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    JOIN public.billing_categories bc ON bc.id = b.item_category_id AND bc.id = ANY(v_cov_cats)
    JOIN public.academic_years ay ON ay.id = b.academic_year_id
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
  ),
  years AS (
    SELECT s.id AS learner_id, iy.yr, s.window_end_yr,
           (c.student_id IS NOT NULL) AS is_covered
    FROM scope s
    JOIN inst_years iy ON iy.institution_id = s.institution_id
     AND iy.yr BETWEEN GREATEST(s.cohort, COALESCE(p_earliest_academic_year, s.cohort))
                   AND s.window_end_yr
    LEFT JOIN covered c ON c.student_id = s.id AND c.yr = iy.yr
    WHERE s.cohort IS NOT NULL AND s.ceiling_yr IS NOT NULL
  ),
  per_learner AS (
    SELECT y.learner_id,
           COUNT(*) FILTER (WHERE y.is_covered)::int     AS billed_years,
           COUNT(*) FILTER (WHERE NOT y.is_covered)::int AS missing_years,
           -- The learner's LAST EXPECTED year, not the institution's current
           -- one — for a finished cohort those are different years.
           bool_or(y.yr = y.window_end_yr AND y.is_covered) AS has_current_year
    FROM years y GROUP BY y.learner_id
  ),
  stated AS (
    SELECT s.institution_id,
           (s.dur IS NULL) AS duration_not_set,
           COALESCE(pl.missing_years, 0)   AS missing_years,
           COALESCE(pl.billed_years, 0)    AS billed_years,
           COALESCE(pl.has_current_year, false) AS has_current_year,
           CASE
             WHEN s.cohort IS NULL OR s.ceiling_yr IS NULL THEN 'cannot_evaluate'
             WHEN COALESCE(pl.missing_years, 0) > 0        THEN 'gap'
             ELSE 'complete'
           END AS audit_state
    FROM scope s
    LEFT JOIN per_learner pl ON pl.learner_id = s.id
  )
  SELECT jsonb_build_object(
    'in_scope',        (SELECT COUNT(*) FROM stated),
    'gap',             (SELECT COUNT(*) FROM stated WHERE audit_state = 'gap'),
    'complete',        (SELECT COUNT(*) FROM stated WHERE audit_state = 'complete'),
    'cannot_evaluate', (SELECT COUNT(*) FROM stated WHERE audit_state = 'cannot_evaluate'),
    'missing_slots',   (SELECT COALESCE(SUM(missing_years), 0) FROM stated),
    'backlog_only',    (SELECT COUNT(*) FROM stated
                        WHERE audit_state = 'gap' AND has_current_year),
    'no_tuition_at_all', (SELECT COUNT(*) FROM stated
                          WHERE audit_state = 'gap' AND billed_years = 0),
    -- Data hygiene, not a verdict: these learners' windows run to the current
    -- year because their programme has no duration on file, so any tail years
    -- they show are unproven rather than confirmed gaps.
    'duration_not_set',(SELECT COUNT(*) FROM stated WHERE duration_not_set),
    'excluded_institutions',
      (SELECT COUNT(DISTINCT institution_id) FROM all_scope WHERE NOT is_tuition_inst),
    'excluded_learners',
      (SELECT COUNT(*) FROM all_scope WHERE NOT is_tuition_inst),
    'by_institution', COALESCE((
      SELECT jsonb_agg(x ORDER BY x->>'institution_name')
      FROM (
        SELECT jsonb_build_object(
                 'institution_id',   st.institution_id,
                 'institution_name', COALESCE(i.name::text, 'Unknown'),
                 'in_scope',         COUNT(*),
                 'gap',              COUNT(*) FILTER (WHERE st.audit_state = 'gap'),
                 'missing_slots',    COALESCE(SUM(st.missing_years), 0)
               ) AS x
        FROM stated st
        LEFT JOIN public.institutions i ON i.id = st.institution_id
        GROUP BY st.institution_id, i.name
      ) sub
    ), '[]'::jsonb),
    'available_academic_years', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'year',  yr,
               'label', yr::text || '-' || (yr + 1)::text) ORDER BY yr DESC)
      FROM (
        SELECT DISTINCT EXTRACT(YEAR FROM ay.start_date)::int AS yr
        FROM public.academic_years ay
        WHERE ay.institution_id = ANY(v_inst)
          AND ay.is_active IS TRUE
          AND ay.start_date <= CURRENT_DATE
      ) ys
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$function$;

-- ── A: learners list ───────────────────────────────────────────────────────
-- CREATE OR REPLACE, not DROP + CREATE: only the body changes here — the
-- parameters and every RETURNS TABLE column are identical to 20260812170100.
-- Replacing in place keeps the existing ACL rather than discarding it and
-- relying on the re-GRANT below to put it back.
CREATE OR REPLACE FUNCTION public.get_billing_audit_missing_years(
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_include_non_tuition_institutions boolean DEFAULT false,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_admission_year integer DEFAULT NULL::integer,
  p_earliest_academic_year integer DEFAULT NULL::integer,
  p_audit_state text DEFAULT 'gap'::text,
  p_search text DEFAULT NULL::text,
  p_page integer DEFAULT 1,
  p_page_size integer DEFAULT 50,
  p_sort_by text DEFAULT NULL::text,
  p_sort_dir text DEFAULT 'asc'::text
)
RETURNS TABLE(
  out_learner_id uuid, out_roll_number text, out_register_number text,
  out_full_name text, out_lifecycle_status text, out_gender text,
  out_institution_id uuid, out_institution_name text, out_program_name text,
  out_semester_section text, out_admission_year integer,
  out_expected_years integer, out_billed_years integer, out_missing_years integer,
  out_missing_year_names text, out_first_missing_year text,
  out_has_current_year boolean, out_tuition_bill_count integer,
  out_total_billed numeric, out_total_paid numeric,
  out_unassigned_tuition_bills integer, out_audit_state text,
  out_program_duration_yrs numeric, out_programme_end_year text,
  out_duration_configured boolean,
  out_total_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst   uuid[];
  v_limit  integer := LEAST(GREATEST(COALESCE(NULLIF(p_page_size, 0), 50), 1), 5000);
  v_offset integer := GREATEST(COALESCE(p_page, 1) - 1, 0)
                      * LEAST(GREATEST(COALESCE(NULLIF(p_page_size, 0), 50), 1), 5000);
  v_asc    boolean := COALESCE(LOWER(p_sort_dir), 'asc') <> 'desc';
  v_adm_year_ids uuid[];
  v_cov_cats     uuid[];
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  -- Resolved once per call, not per predicate: ten sites read it below, and a
  -- STABLE function re-evaluated inside every join would be re-planned each time.
  v_cov_cats := public.fn_billing_tuition_equivalent_category_ids();

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN;
  END IF;

  IF p_admission_year IS NOT NULL THEN
    SELECT array_agg(ayr.id) INTO v_adm_year_ids
    FROM public.admission_years ayr WHERE ayr.year = p_admission_year;
  END IF;

  RETURN QUERY
  WITH tuition_inst AS MATERIALIZED (
    SELECT DISTINCT b.institution_id AS inst_id
    FROM public.billing_student_bills b
    JOIN public.billing_categories bc ON bc.id = b.item_category_id
    WHERE bc.id = ANY(v_cov_cats)
      AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
  ),
  target AS MATERIALIZED (
    SELECT t.institution_id, EXTRACT(YEAR FROM ay.start_date)::int AS ceiling_yr
    FROM public.fn_billing_coverage_target_years() t
    JOIN public.academic_years ay ON ay.id = t.target_ay_id
  ),
  inst_years AS MATERIALIZED (
    SELECT DISTINCT ay.institution_id, EXTRACT(YEAR FROM ay.start_date)::int AS yr
    FROM public.academic_years ay WHERE ay.is_active IS TRUE
  ),
  scope AS MATERIALIZED (
    SELECT lp.id, lp.institution_id, lp.program_id, lp.semester_id, lp.section_id,
           lp.gender, lp.lifecycle_status, lp.first_name, lp.last_name,
           lp.roll_number, lp.register_number, lp.accommodation_type_id,
           adm.year AS cohort, t.ceiling_yr,
           p.program_duration_yrs AS dur,
           LEAST(t.ceiling_yr,
                 COALESCE(public.fn_programme_end_year(adm.year, p.program_duration_yrs),
                          t.ceiling_yr)) AS window_end_yr
    FROM public.learners_profiles lp
    LEFT JOIN public.admission_years adm ON adm.id = lp.admission_year_id
    LEFT JOIN public.programs p ON p.id = lp.program_id
    LEFT JOIN target t ON t.institution_id = lp.institution_id
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_tuition_institutions
           OR lp.institution_id IN (SELECT inst_id FROM tuition_inst))
      AND (p_admission_year IS NULL OR lp.admission_year_id = ANY(v_adm_year_ids))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
      AND (
        p_search IS NULL OR p_search = ''
        OR lp.roll_number ILIKE '%' || p_search || '%'
        OR lp.register_number ILIKE '%' || p_search || '%'
        OR (COALESCE(lp.first_name,'') || ' ' || COALESCE(lp.last_name,''))
             ILIKE '%' || p_search || '%'
      )
  ),
  covered AS MATERIALIZED (
    SELECT DISTINCT b.student_id, EXTRACT(YEAR FROM ay.start_date)::int AS yr
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    JOIN public.billing_categories bc ON bc.id = b.item_category_id AND bc.id = ANY(v_cov_cats)
    JOIN public.academic_years ay ON ay.id = b.academic_year_id
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
  ),
  bill_stats AS MATERIALIZED (
    SELECT b.student_id,
           COUNT(*)::integer AS tuition_bill_count,
           COALESCE(SUM(b.final_amount), 0)::numeric AS total_billed,
           COALESCE(SUM(b.final_amount - COALESCE(b.balance_amount, 0)), 0)::numeric
             AS total_paid,
           COUNT(*) FILTER (WHERE b.academic_year_id IS NULL)::integer
             AS unassigned_tuition_bills
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    JOIN public.billing_categories bc ON bc.id = b.item_category_id AND bc.id = ANY(v_cov_cats)
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
    GROUP BY b.student_id
  ),
  years AS (
    SELECT s.id AS learner_id, iy.yr, s.window_end_yr,
           (c.student_id IS NOT NULL) AS is_covered
    FROM scope s
    JOIN inst_years iy ON iy.institution_id = s.institution_id
     AND iy.yr BETWEEN GREATEST(s.cohort, COALESCE(p_earliest_academic_year, s.cohort))
                   AND s.window_end_yr
    LEFT JOIN covered c ON c.student_id = s.id AND c.yr = iy.yr
    WHERE s.cohort IS NOT NULL AND s.ceiling_yr IS NOT NULL
  ),
  per_learner AS (
    SELECT y.learner_id,
           COUNT(*)::integer                             AS expected_years,
           COUNT(*) FILTER (WHERE y.is_covered)::integer AS billed_years,
           COUNT(*) FILTER (WHERE NOT y.is_covered)::integer AS missing_years,
           string_agg(y.yr::text || '-' || (y.yr + 1)::text, ', ' ORDER BY y.yr)
             FILTER (WHERE NOT y.is_covered)             AS missing_year_names,
           MIN(y.yr) FILTER (WHERE NOT y.is_covered)     AS first_missing_yr,
           bool_or(y.yr = y.window_end_yr AND y.is_covered) AS has_current_year
    FROM years y GROUP BY y.learner_id
  ),
  final AS (
    SELECT s.id AS learner_id,
           s.roll_number::text     AS roll_number,
           s.register_number::text AS register_number,
           TRIM(COALESCE(s.first_name,'') || ' ' || COALESCE(s.last_name,''))
                                   AS full_name,
           s.lifecycle_status::text AS lifecycle_status,
           NULLIF(TRIM(s.gender), '')::text AS gender,
           s.institution_id        AS institution_id,
           i.name::text            AS institution_name,
           p.program_name          AS program_name,
           CASE
             WHEN sem.semester_name IS NULL AND sec.section_name IS NULL THEN NULL
             WHEN sec.section_name IS NULL THEN sem.semester_name::text
             WHEN sem.semester_name IS NULL THEN sec.section_name::text
             ELSE sem.semester_name::text || ' · ' || sec.section_name::text
           END                     AS semester_section,
           s.cohort                AS admission_year,
           COALESCE(pl.expected_years, 0) AS expected_years,
           COALESCE(pl.billed_years, 0)   AS billed_years,
           COALESCE(pl.missing_years, 0)  AS missing_years,
           pl.missing_year_names   AS missing_year_names,
           CASE WHEN pl.first_missing_yr IS NULL THEN NULL
                ELSE pl.first_missing_yr::text || '-' || (pl.first_missing_yr + 1)::text
           END                     AS first_missing_year,
           COALESCE(pl.has_current_year, false) AS has_current_year,
           COALESCE(bs.tuition_bill_count, 0)   AS tuition_bill_count,
           COALESCE(bs.total_billed, 0)::numeric AS total_billed,
           COALESCE(bs.total_paid, 0)::numeric   AS total_paid,
           COALESCE(bs.unassigned_tuition_bills, 0) AS unassigned_tuition_bills,
           s.dur                   AS program_duration_yrs,
           public.fn_programme_end_year(s.cohort, s.dur) AS programme_end_yr,
           (s.dur IS NOT NULL)     AS duration_configured,
           CASE
             WHEN s.cohort IS NULL OR s.ceiling_yr IS NULL THEN 'cannot_evaluate'
             WHEN COALESCE(pl.missing_years, 0) > 0        THEN 'gap'
             ELSE 'complete'
           END                     AS audit_state
    FROM scope s
    LEFT JOIN per_learner pl              ON pl.learner_id = s.id
    LEFT JOIN bill_stats  bs              ON bs.student_id = s.id
    LEFT JOIN public.institutions i       ON i.id   = s.institution_id
    LEFT JOIN public.programs     p       ON p.id   = s.program_id
    LEFT JOIN public.semesters    sem     ON sem.id = s.semester_id
    LEFT JOIN public.sections     sec     ON sec.id = s.section_id
  ),
  filtered AS (
    SELECT * FROM final f
    WHERE COALESCE(p_audit_state, 'gap') = 'all'
       OR f.audit_state = COALESCE(p_audit_state, 'gap')
  )
  SELECT f.learner_id, f.roll_number, f.register_number, f.full_name,
         f.lifecycle_status, f.gender, f.institution_id, f.institution_name,
         f.program_name, f.semester_section, f.admission_year,
         f.expected_years, f.billed_years, f.missing_years,
         f.missing_year_names, f.first_missing_year, f.has_current_year,
         f.tuition_bill_count, f.total_billed, f.total_paid,
         f.unassigned_tuition_bills, f.audit_state,
         f.program_duration_yrs,
         CASE WHEN f.programme_end_yr IS NULL THEN NULL
              ELSE f.programme_end_yr::text || '-' || (f.programme_end_yr + 1)::text
         END,
         f.duration_configured,
         COUNT(*) OVER ()::bigint
  FROM filtered f
  ORDER BY
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'gender'             THEN f.gender
         WHEN 'first_missing_year' THEN f.first_missing_year
         WHEN 'programme_end_year' THEN f.programme_end_yr::text
         WHEN 'audit_state'        THEN f.audit_state
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'gender'             THEN f.gender
         WHEN 'first_missing_year' THEN f.first_missing_year
         WHEN 'programme_end_year' THEN f.programme_end_yr::text
         WHEN 'audit_state'        THEN f.audit_state
       END
     END) DESC NULLS LAST,
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'admission_year'        THEN f.admission_year::numeric
         WHEN 'expected_years'        THEN f.expected_years::numeric
         WHEN 'billed_years'          THEN f.billed_years::numeric
         WHEN 'missing_years'         THEN f.missing_years::numeric
         WHEN 'tuition_bill_count'    THEN f.tuition_bill_count::numeric
         WHEN 'total_billed'          THEN f.total_billed
         WHEN 'total_paid'            THEN f.total_paid
         WHEN 'program_duration_yrs'  THEN f.program_duration_yrs
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'admission_year'        THEN f.admission_year::numeric
         WHEN 'expected_years'        THEN f.expected_years::numeric
         WHEN 'billed_years'          THEN f.billed_years::numeric
         WHEN 'missing_years'         THEN f.missing_years::numeric
         WHEN 'tuition_bill_count'    THEN f.tuition_bill_count::numeric
         WHEN 'total_billed'          THEN f.total_billed
         WHEN 'total_paid'            THEN f.total_paid
         WHEN 'program_duration_yrs'  THEN f.program_duration_yrs
       END
     END) DESC NULLS LAST,
    f.missing_years DESC, f.institution_name NULLS LAST,
    f.roll_number NULLS LAST, f.full_name
  LIMIT v_limit OFFSET v_offset;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_billing_audit_missing_years(
  uuid[], text[], boolean, uuid[], text, text, uuid, uuid, uuid, uuid, uuid,
  integer, integer, text, text, integer, integer, text, text)
  FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_billing_audit_missing_years(
  uuid[], text[], boolean, uuid[], text, text, uuid, uuid, uuid, uuid, uuid,
  integer, integer, text, text, integer, integer, text, text)
  TO authenticated, service_role;

-- ── B: summary ─────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.get_billing_audit_duplicate_years_summary(
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_include_non_tuition_institutions boolean DEFAULT false,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_admission_year integer DEFAULT NULL::integer,
  p_earliest_academic_year integer DEFAULT NULL::integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst         uuid[];
  v_adm_year_ids uuid[];
  v_cov_cats     uuid[];
  v_result       jsonb;
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  -- Resolved once per call, not per predicate: ten sites read it below, and a
  -- STABLE function re-evaluated inside every join would be re-planned each time.
  v_cov_cats := public.fn_billing_tuition_equivalent_category_ids();

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN jsonb_build_object(
      'combos', 0, 'learners', 0, 'bills', 0, 'extra_bills', 0,
      'total_billed', 0, 'outstanding', 0, 'generator_signature', 0,
      'unassigned_tuition_bills', 0,
      'past_end_bills', 0, 'past_end_learners', 0, 'past_end_outstanding', 0,
      'by_institution', '[]'::jsonb);
  END IF;

  IF p_admission_year IS NOT NULL THEN
    SELECT array_agg(ayr.id) INTO v_adm_year_ids
    FROM public.admission_years ayr WHERE ayr.year = p_admission_year;
  END IF;

  WITH tuition_inst AS MATERIALIZED (
    SELECT DISTINCT b.institution_id AS inst_id
    FROM public.billing_student_bills b
    JOIN public.billing_categories bc ON bc.id = b.item_category_id
    WHERE bc.id = ANY(v_cov_cats)
      AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
  ),
  scope AS MATERIALIZED (
    SELECT lp.id, lp.institution_id, adm.year AS cohort,
           public.fn_programme_end_year(adm.year, p.program_duration_yrs) AS end_yr
    FROM public.learners_profiles lp
    LEFT JOIN public.admission_years adm ON adm.id = lp.admission_year_id
    LEFT JOIN public.programs p ON p.id = lp.program_id
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_tuition_institutions
           OR lp.institution_id IN (SELECT inst_id FROM tuition_inst))
      AND (p_admission_year IS NULL OR lp.admission_year_id = ANY(v_adm_year_ids))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
  ),
  -- Every bill that satisfies a year's tuition obligation. `is_core_tuition`
  -- rides along so the two findings below can disagree about what counts:
  -- duplicates read the whole set, past-end reads only the tuition-kind rows.
  coverage_bills AS MATERIALIZED (
    SELECT b.id, b.student_id, s.institution_id, s.end_yr,
           EXTRACT(YEAR FROM ay.start_date)::int AS yr,
           b.final_amount, COALESCE(b.balance_amount, 0) AS balance_amount,
           b.created_at, b.due_date,
           (bc.kind = 'tuition') AS is_core_tuition
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    JOIN public.billing_categories bc ON bc.id = b.item_category_id AND bc.id = ANY(v_cov_cats)
    JOIN public.academic_years ay ON ay.id = b.academic_year_id
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
      AND (p_earliest_academic_year IS NULL
           OR EXTRACT(YEAR FROM ay.start_date)::int >= p_earliest_academic_year)
  ),
  dup AS (
    SELECT tb.student_id AS learner_id, tb.institution_id,
           COUNT(*)::integer AS bill_count,
           SUM(tb.final_amount)::numeric AS total_billed,
           SUM(tb.balance_amount)::numeric AS outstanding,
           (COUNT(DISTINCT tb.created_at::date) = 1
            AND COUNT(DISTINCT EXTRACT(YEAR FROM tb.due_date)) > 1) AS is_generator_artefact
    FROM coverage_bills tb
    GROUP BY tb.student_id, tb.institution_id, tb.yr
    HAVING COUNT(*) > 1
  ),
  -- The INVERSE finding: a live tuition bill for a year after the programme
  -- ends. STRICTLY kind = 'tuition', and the one predicate on this page that
  -- did NOT widen with the rest. program_duration_yrs counts TAUGHT years, so
  -- an internship fee falls the year after the course ends by design — all
  -- eight Allied Health BSc programmes are dur = 4.0 and bill AHS - INTERNSHIP
  -- FEE in cohort+4. Reading is_core_tuition here instead of the widened set
  -- is what keeps those 37 correct bills from being reported as anomalies.
  past_end AS (
    SELECT tb.id, tb.student_id, tb.balance_amount
    FROM coverage_bills tb
    WHERE tb.is_core_tuition
      AND tb.end_yr IS NOT NULL AND tb.yr > tb.end_yr
  )
  SELECT jsonb_build_object(
    'combos',       (SELECT COUNT(*) FROM dup),
    'learners',     (SELECT COUNT(DISTINCT learner_id) FROM dup),
    'bills',        (SELECT COALESCE(SUM(bill_count), 0) FROM dup),
    'extra_bills',  (SELECT COALESCE(SUM(bill_count - 1), 0) FROM dup),
    'total_billed', (SELECT COALESCE(SUM(total_billed), 0) FROM dup),
    'outstanding',  (SELECT COALESCE(SUM(outstanding), 0) FROM dup),
    'generator_signature',
      (SELECT COUNT(*) FROM dup WHERE is_generator_artefact),
    'unassigned_tuition_bills', (
      SELECT COUNT(*)
      FROM public.billing_student_bills b
      JOIN scope s ON s.id = b.student_id
      JOIN public.billing_categories bc ON bc.id = b.item_category_id AND bc.id = ANY(v_cov_cats)
      WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
        AND b.academic_year_id IS NULL
    ),
    'past_end_bills',       (SELECT COUNT(*) FROM past_end),
    'past_end_learners',    (SELECT COUNT(DISTINCT student_id) FROM past_end),
    'past_end_outstanding', (SELECT COALESCE(SUM(balance_amount), 0) FROM past_end),
    'by_institution', COALESCE((
      SELECT jsonb_agg(x ORDER BY x->>'institution_name')
      FROM (
        SELECT jsonb_build_object(
                 'institution_id',   d.institution_id,
                 'institution_name', COALESCE(i.name::text, 'Unknown'),
                 'combos',           COUNT(*),
                 'learners',         COUNT(DISTINCT d.learner_id),
                 'extra_bills',      COALESCE(SUM(d.bill_count - 1), 0)
               ) AS x
        FROM dup d
        LEFT JOIN public.institutions i ON i.id = d.institution_id
        GROUP BY d.institution_id, i.name
      ) sub
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$function$;

-- ── B: list ────────────────────────────────────────────────────────────────
-- Body-only change; same reasoning as A above.
CREATE OR REPLACE FUNCTION public.get_billing_audit_duplicate_years(
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_lifecycle_statuses text[] DEFAULT ARRAY['active'::text, 'reserved'::text, 'admitted'::text, 'account'::text],
  p_include_non_tuition_institutions boolean DEFAULT false,
  p_accommodation_type_ids uuid[] DEFAULT NULL::uuid[],
  p_transport text DEFAULT 'any'::text,
  p_gender text DEFAULT NULL::text,
  p_degree_id uuid DEFAULT NULL::uuid,
  p_department_id uuid DEFAULT NULL::uuid,
  p_program_id uuid DEFAULT NULL::uuid,
  p_semester_id uuid DEFAULT NULL::uuid,
  p_section_id uuid DEFAULT NULL::uuid,
  p_admission_year integer DEFAULT NULL::integer,
  p_earliest_academic_year integer DEFAULT NULL::integer,
  p_search text DEFAULT NULL::text,
  p_page integer DEFAULT 1,
  p_page_size integer DEFAULT 50,
  p_sort_by text DEFAULT NULL::text,
  p_sort_dir text DEFAULT 'asc'::text
)
RETURNS TABLE(
  out_audit_row_id text, out_learner_id uuid, out_roll_number text,
  out_register_number text, out_full_name text, out_lifecycle_status text,
  out_institution_id uuid, out_institution_name text, out_program_name text,
  out_semester_section text, out_admission_year integer,
  out_academic_year_name text, out_bill_count integer, out_category_names text,
  out_total_billed numeric, out_total_paid numeric, out_outstanding numeric,
  out_created_same_day boolean, out_due_year_span integer,
  out_programme_end_year text, out_is_past_programme_end boolean,
  out_total_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_inst   uuid[];
  v_limit  integer := LEAST(GREATEST(COALESCE(NULLIF(p_page_size, 0), 50), 1), 5000);
  v_offset integer := GREATEST(COALESCE(p_page, 1) - 1, 0)
                      * LEAST(GREATEST(COALESCE(NULLIF(p_page_size, 0), 50), 1), 5000);
  v_asc    boolean := COALESCE(LOWER(p_sort_dir), 'asc') <> 'desc';
  v_adm_year_ids uuid[];
  v_cov_cats     uuid[];
BEGIN
  IF NOT public.user_has_permission('billing.coverage.view') THEN
    RAISE EXCEPTION 'permission denied: billing.coverage.view' USING ERRCODE = '42501';
  END IF;

  -- Resolved once per call, not per predicate: ten sites read it below, and a
  -- STABLE function re-evaluated inside every join would be re-planned each time.
  v_cov_cats := public.fn_billing_tuition_equivalent_category_ids();

  SELECT array_agg(institution_id) INTO v_inst
  FROM public.get_user_accessible_institutions(auth.uid())
  WHERE (p_institution_ids IS NULL OR institution_id = ANY(p_institution_ids));

  IF v_inst IS NULL THEN
    RETURN;
  END IF;

  IF p_admission_year IS NOT NULL THEN
    SELECT array_agg(ayr.id) INTO v_adm_year_ids
    FROM public.admission_years ayr WHERE ayr.year = p_admission_year;
  END IF;

  RETURN QUERY
  WITH tuition_inst AS MATERIALIZED (
    SELECT DISTINCT b.institution_id AS inst_id
    FROM public.billing_student_bills b
    JOIN public.billing_categories bc ON bc.id = b.item_category_id
    WHERE bc.id = ANY(v_cov_cats)
      AND COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
  ),
  scope AS MATERIALIZED (
    SELECT lp.id, lp.institution_id, lp.program_id, lp.semester_id, lp.section_id,
           lp.lifecycle_status, lp.first_name, lp.last_name, lp.roll_number,
           lp.register_number, adm.year AS cohort,
           public.fn_programme_end_year(adm.year, p.program_duration_yrs) AS end_yr
    FROM public.learners_profiles lp
    LEFT JOIN public.admission_years adm ON adm.id = lp.admission_year_id
    LEFT JOIN public.programs p ON p.id = lp.program_id
    WHERE lp.institution_id = ANY(v_inst)
      AND lp.lifecycle_status::text = ANY(p_lifecycle_statuses)
      AND (p_include_non_tuition_institutions
           OR lp.institution_id IN (SELECT inst_id FROM tuition_inst))
      AND (p_admission_year IS NULL OR lp.admission_year_id = ANY(v_adm_year_ids))
      AND (p_degree_id     IS NULL OR lp.degree_id     = p_degree_id)
      AND (p_department_id IS NULL OR lp.department_id = p_department_id)
      AND (p_program_id    IS NULL OR lp.program_id    = p_program_id)
      AND (p_semester_id   IS NULL OR lp.semester_id   = p_semester_id)
      AND (p_section_id    IS NULL OR lp.section_id    = p_section_id)
      AND (p_accommodation_type_ids IS NULL
           OR lp.accommodation_type_id = ANY(p_accommodation_type_ids))
      AND (
        p_gender IS NULL
        OR (p_gender = '__unset__' AND NULLIF(TRIM(lp.gender), '') IS NULL)
        OR (p_gender <> '__unset__'
            AND UPPER(TRIM(lp.gender)) = UPPER(TRIM(p_gender)))
      )
      AND (
        COALESCE(p_transport, 'any') = 'any'
        OR (p_transport = 'bus'
            AND (lp.bus_required IS TRUE OR lp.transport_route_id IS NOT NULL))
        OR (p_transport = 'no_bus'
            AND lp.bus_required IS NOT TRUE AND lp.transport_route_id IS NULL)
      )
      AND (
        p_search IS NULL OR p_search = ''
        OR lp.roll_number ILIKE '%' || p_search || '%'
        OR lp.register_number ILIKE '%' || p_search || '%'
        OR (COALESCE(lp.first_name,'') || ' ' || COALESCE(lp.last_name,''))
             ILIKE '%' || p_search || '%'
      )
  ),
  dup AS (
    SELECT b.student_id AS learner_id,
           EXTRACT(YEAR FROM ay.start_date)::integer AS yr,
           COUNT(*)::integer AS bill_count,
           string_agg(DISTINCT bc.category_name::text, ', '
                      ORDER BY bc.category_name::text) AS category_names,
           SUM(b.final_amount)::numeric AS total_billed,
           SUM(b.final_amount - COALESCE(b.balance_amount, 0))::numeric AS total_paid,
           SUM(COALESCE(b.balance_amount, 0))::numeric AS outstanding,
           (COUNT(DISTINCT b.created_at::date) = 1) AS created_same_day,
           COUNT(DISTINCT EXTRACT(YEAR FROM b.due_date))::integer AS due_year_span,
           -- Gates the past-programme-end badge below to match the summary
           -- KPI, which counts tuition-kind bills only. Without it a combo made
           -- purely of internship fees could be badged for a year that, for an
           -- internship, is exactly where it belongs.
           bool_or(bc.kind = 'tuition') AS has_core_tuition
    FROM public.billing_student_bills b
    JOIN scope s ON s.id = b.student_id
    JOIN public.billing_categories bc ON bc.id = b.item_category_id AND bc.id = ANY(v_cov_cats)
    JOIN public.academic_years ay ON ay.id = b.academic_year_id
    WHERE COALESCE(b.status, '') NOT IN ('cancelled', 'superseded')
      AND (p_earliest_academic_year IS NULL
           OR EXTRACT(YEAR FROM ay.start_date)::int >= p_earliest_academic_year)
    GROUP BY b.student_id, EXTRACT(YEAR FROM ay.start_date)::integer
    HAVING COUNT(*) > 1
  ),
  final AS (
    SELECT (s.id::text || ':' || d.yr::text) AS audit_row_id,
           s.id AS learner_id,
           s.roll_number::text     AS roll_number,
           s.register_number::text AS register_number,
           TRIM(COALESCE(s.first_name,'') || ' ' || COALESCE(s.last_name,''))
                                   AS full_name,
           s.lifecycle_status::text AS lifecycle_status,
           s.institution_id        AS institution_id,
           i.name::text            AS institution_name,
           p.program_name          AS program_name,
           CASE
             WHEN sem.semester_name IS NULL AND sec.section_name IS NULL THEN NULL
             WHEN sec.section_name IS NULL THEN sem.semester_name::text
             WHEN sem.semester_name IS NULL THEN sec.section_name::text
             ELSE sem.semester_name::text || ' · ' || sec.section_name::text
           END                     AS semester_section,
           s.cohort                AS admission_year,
           (d.yr::text || '-' || (d.yr + 1)::text) AS academic_year_name,
           d.bill_count, d.category_names, d.total_billed, d.total_paid,
           d.outstanding, d.created_same_day, d.due_year_span,
           s.end_yr                AS programme_end_yr,
           (d.has_core_tuition AND s.end_yr IS NOT NULL AND d.yr > s.end_yr)
                                   AS is_past_programme_end
    FROM dup d
    JOIN scope s ON s.id = d.learner_id
    LEFT JOIN public.institutions i   ON i.id   = s.institution_id
    LEFT JOIN public.programs     p   ON p.id   = s.program_id
    LEFT JOIN public.semesters    sem ON sem.id = s.semester_id
    LEFT JOIN public.sections     sec ON sec.id = s.section_id
  )
  SELECT f.audit_row_id, f.learner_id, f.roll_number, f.register_number,
         f.full_name, f.lifecycle_status, f.institution_id, f.institution_name,
         f.program_name, f.semester_section, f.admission_year,
         f.academic_year_name, f.bill_count, f.category_names,
         f.total_billed, f.total_paid, f.outstanding,
         f.created_same_day, f.due_year_span,
         CASE WHEN f.programme_end_yr IS NULL THEN NULL
              ELSE f.programme_end_yr::text || '-' || (f.programme_end_yr + 1)::text
         END,
         f.is_past_programme_end,
         COUNT(*) OVER ()::bigint
  FROM final f
  ORDER BY
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'academic_year_name' THEN f.academic_year_name
         WHEN 'category_names'     THEN f.category_names
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'full_name'          THEN f.full_name
         WHEN 'roll_number'        THEN f.roll_number
         WHEN 'register_number'    THEN f.register_number
         WHEN 'institution_name'   THEN f.institution_name
         WHEN 'program_name'       THEN f.program_name
         WHEN 'semester_section'   THEN f.semester_section
         WHEN 'lifecycle_status'   THEN f.lifecycle_status
         WHEN 'academic_year_name' THEN f.academic_year_name
         WHEN 'category_names'     THEN f.category_names
       END
     END) DESC NULLS LAST,
    (CASE WHEN v_asc THEN
       CASE p_sort_by
         WHEN 'admission_year' THEN f.admission_year::numeric
         WHEN 'bill_count'     THEN f.bill_count::numeric
         WHEN 'total_billed'   THEN f.total_billed
         WHEN 'total_paid'     THEN f.total_paid
         WHEN 'outstanding'    THEN f.outstanding
       END
     END) ASC NULLS LAST,
    (CASE WHEN NOT v_asc THEN
       CASE p_sort_by
         WHEN 'admission_year' THEN f.admission_year::numeric
         WHEN 'bill_count'     THEN f.bill_count::numeric
         WHEN 'total_billed'   THEN f.total_billed
         WHEN 'total_paid'     THEN f.total_paid
         WHEN 'outstanding'    THEN f.outstanding
       END
     END) DESC NULLS LAST,
    -- Bills sitting past the programme end float to the top: they are the
    -- least explicable rows on the screen.
    f.is_past_programme_end DESC, f.bill_count DESC,
    f.institution_name NULLS LAST, f.roll_number NULLS LAST, f.academic_year_name
  LIMIT v_limit OFFSET v_offset;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_billing_audit_duplicate_years(
  uuid[], text[], boolean, uuid[], text, text, uuid, uuid, uuid, uuid, uuid,
  integer, integer, text, integer, integer, text, text)
  FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_billing_audit_duplicate_years(
  uuid[], text[], boolean, uuid[], text, text, uuid, uuid, uuid, uuid, uuid,
  integer, integer, text, integer, integer, text, text)
  TO authenticated, service_role;


-- ============================================================================
-- Empty-bed settlement + room buyout (2026-08-13)
-- Source: supabase/migrations/2026081903*.sql
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_settle_billing_category()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT bc.id
  FROM billing_categories bc
  WHERE bc.category_name = 'Hostel Empty Bed Settlement'
    AND bc.is_active
  ORDER BY bc.created_at
  LIMIT 1;
$function$;

CREATE OR REPLACE FUNCTION public._enforce_room_buyout_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_buyout uuid;
BEGIN
  -- Only an ACTIVE occupancy takes a bed. A row being checked out frees one, so
  -- a resident may always leave a bought-out room.
  IF NEW.check_out_date IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT b.id INTO v_buyout
  FROM hostel_room_buyouts b
  WHERE b.room_id = NEW.room_id
    AND b.status = 'active'
  LIMIT 1;

  IF v_buyout IS NULL THEN
    RETURN NEW;
  END IF;

  -- The residents who bought the room may still be edited in place — a bed swap
  -- within the room, a status change, a correction. Only a NEW body is refused.
  IF EXISTS (
    SELECT 1 FROM hostel_room_buyout_consents c
    WHERE c.buyout_id = v_buyout
      AND c.allocation_id = NEW.id
  ) THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION
    'This room is held under an active empty-bed buyout — its residents have paid for the empty beds. Release the buyout before allocating anyone into it.'
    USING ERRCODE = '23514',
          DETAIL  = format('room_id=%s buyout_id=%s allocation_id=%s', NEW.room_id, v_buyout, NEW.id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.fn_room_buyout_quote(p_room_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_year_id   uuid;
  v_cost      jsonb;
  v_capacity  int;
  v_occupants int;
  v_per_bed   numeric;
  v_settled   numeric;
  v_amount    numeric;
  v_live      record;
BEGIN
  -- Own-room scope. fn_user_allocated_room is deliberately NOT reused here: it
  -- ignores check_out_date, so a learner who has since moved out would still be
  -- able to price — and later act on — the room she used to live in.
  IF NOT EXISTS (
        SELECT 1 FROM hostel_allocations a
        WHERE a.room_id = p_room_id
          AND a.check_out_date IS NULL
          AND a.learner_id = auth.uid())
     AND NOT fn_settle_can_manage(p_room_id, 'campus_living.fees.view') THEN
    RAISE EXCEPTION 'permission denied: you are not a resident of this room'
      USING ERRCODE = '42501';
  END IF;

  IF NOT fn_get_policy_bool('hostel.settle_bill.enabled', false) THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'mechanism_disabled',
                              'room_id', p_room_id);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM hostel_rooms r
    JOIN hostel_categories hc ON hc.id = r.category_id
    WHERE r.id = p_room_id AND hc.settle_billing_enabled
  ) THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'category_not_in_scope',
                              'room_id', p_room_id);
  END IF;

  v_year_id := fn_settle_current_hostel_year();
  IF v_year_id IS NULL THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'no_hostel_year',
                              'room_id', p_room_id);
  END IF;

  v_cost := fn_settle_room_annual_cost(p_room_id, v_year_id);
  IF NOT (v_cost->>'found')::boolean THEN
    RETURN jsonb_build_object('eligible', false, 'reason', v_cost->>'reason',
                              'room_id', p_room_id);
  END IF;

  v_capacity := (v_cost->>'capacity')::int;
  v_per_bed  := (v_cost->>'per_bed_annual_rate')::numeric;

  SELECT COUNT(*)::int INTO v_occupants
  FROM hostel_allocations a
  WHERE a.room_id = p_room_id AND a.check_out_date IS NULL;

  IF v_occupants = 0 THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'no_occupants',
                              'room_id', p_room_id);
  END IF;

  v_settled := round((v_cost->>'base_room_annual')::numeric / v_occupants)
             + round((v_cost->>'ac_room_annual')::numeric   / v_occupants);
  v_amount  := GREATEST(0, v_settled - v_per_bed);

  SELECT b.id, b.status INTO v_live
  FROM hostel_room_buyouts b
  WHERE b.room_id = p_room_id
    AND b.status IN ('pending_consent','active')
  LIMIT 1;

  RETURN jsonb_build_object(
    'eligible',            v_amount > 0 AND v_live.id IS NULL,
    'reason',              CASE
                             WHEN v_live.id IS NOT NULL THEN 'buyout_already_live'
                             WHEN v_amount <= 0         THEN 'room_full'
                             ELSE NULL
                           END,
    'room_id',             p_room_id,
    'hostel_year_id',      v_year_id,
    'capacity',            v_capacity,
    'occupants',           v_occupants,
    'empty_beds',          GREATEST(0, v_capacity - v_occupants),
    'per_bed_annual_rate', v_per_bed,
    'settled_share',       v_settled,
    'amount_per_resident', v_amount,
    -- More than one body in the room means everyone must agree: activation
    -- bills them all and removes their chance of the price falling later.
    'consent_required',    v_occupants > 1,
    'existing_buyout_id',  v_live.id,
    'existing_status',     v_live.status);
END;
$function$;

CREATE OR REPLACE FUNCTION public._room_buyout_activate(p_buyout_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_b         public.hostel_room_buyouts%ROWTYPE;
  v_cost      jsonb;
  v_occupants int;
  v_per_bed   numeric;
  v_settled   numeric;
  v_amount    numeric;
  v_bill_cat  uuid;
  v_due_days  int;
  v_lp_id     uuid;
  v_inst_id   uuid;
  v_bill_id   uuid;
  v_billed    int := 0;
  c           record;
BEGIN
  SELECT * INTO v_b FROM hostel_room_buyouts WHERE id = p_buyout_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not_found', 'buyout_id', p_buyout_id);
  END IF;
  IF v_b.status <> 'pending_consent' THEN
    RETURN jsonb_build_object('status', v_b.status, 'buyout_id', p_buyout_id);
  END IF;

  v_bill_cat := fn_settle_billing_category();
  IF v_bill_cat IS NULL THEN
    RETURN jsonb_build_object('status', 'no_billing_category', 'buyout_id', p_buyout_id);
  END IF;

  -- RE-DERIVE. The request's figure is a quote, not an authority: residents may
  -- have arrived or left while consent was being collected. Billing a number
  -- nobody agreed to is worse than making them ask again.
  v_cost := fn_settle_room_annual_cost(v_b.room_id, v_b.hostel_year_id);
  IF NOT (v_cost->>'found')::boolean THEN
    UPDATE hostel_room_buyouts
       SET status = 'cancelled', cancelled_reason = COALESCE(v_cost->>'reason','no_rate')
     WHERE id = p_buyout_id;
    RETURN jsonb_build_object('status', 'cancelled', 'buyout_id', p_buyout_id,
                              'reason', v_cost->>'reason');
  END IF;

  v_per_bed := (v_cost->>'per_bed_annual_rate')::numeric;

  SELECT COUNT(*)::int INTO v_occupants
  FROM hostel_allocations a
  WHERE a.room_id = v_b.room_id AND a.check_out_date IS NULL;

  IF v_occupants = 0 THEN
    UPDATE hostel_room_buyouts
       SET status = 'cancelled', cancelled_reason = 'no_occupants'
     WHERE id = p_buyout_id;
    RETURN jsonb_build_object('status', 'cancelled', 'buyout_id', p_buyout_id,
                              'reason', 'no_occupants');
  END IF;

  v_settled := round((v_cost->>'base_room_annual')::numeric / v_occupants)
             + round((v_cost->>'ac_room_annual')::numeric   / v_occupants);
  v_amount  := GREATEST(0, v_settled - v_per_bed);

  IF v_amount <= 0 THEN
    -- The room filled while they were deciding. There is nothing left to buy,
    -- and that is the outcome they wanted anyway.
    UPDATE hostel_room_buyouts
       SET status = 'cancelled', cancelled_reason = 'room_filled'
     WHERE id = p_buyout_id;
    RETURN jsonb_build_object('status', 'cancelled', 'buyout_id', p_buyout_id,
                              'reason', 'room_filled');
  END IF;

  IF v_amount <> v_b.amount_per_resident THEN
    UPDATE hostel_room_buyouts
       SET status = 'cancelled', cancelled_reason = 'occupancy_changed'
     WHERE id = p_buyout_id;
    RETURN jsonb_build_object('status', 'cancelled', 'buyout_id', p_buyout_id,
                              'reason', 'occupancy_changed',
                              'quoted', v_b.amount_per_resident, 'now', v_amount);
  END IF;

  v_due_days := GREATEST(0, fn_get_policy_int('hostel.settle_bill.bill_due_days', 5));

  FOR c IN
    SELECT k.id AS consent_id, k.allocation_id, k.learner_id
    FROM hostel_room_buyout_consents k
    JOIN hostel_allocations a ON a.id = k.allocation_id
    WHERE k.buyout_id = p_buyout_id
      AND k.decision = 'agreed'
      AND a.check_out_date IS NULL
    ORDER BY k.created_at
  LOOP
    SELECT p.learner_id INTO v_lp_id FROM profiles p WHERE p.id = c.learner_id;
    CONTINUE WHEN v_lp_id IS NULL;   -- not a learner: cannot be billed

    -- A flat hostel package does not divide by occupancy, so its holder has
    -- nothing to settle. Same exclusion the sweep biller applies.
    CONTINUE WHEN EXISTS (
      SELECT 1 FROM jsonb_array_elements(
        COALESCE(campus_living_resolve_hostel_fee(v_lp_id, v_b.hostel_year_id), '[]'::jsonb)
      ) itm WHERE itm->>'fee_source' = 'hostel_package'
    );

    -- Same dedup key the sweep uses, so the two paths cannot both bill her.
    CONTINUE WHEN EXISTS (
      SELECT 1 FROM billing_student_bills b
      WHERE b.student_id       = v_lp_id
        AND b.hostel_year_id   = v_b.hostel_year_id
        AND b.item_category_id = v_bill_cat
        AND b.fee_source       = 'hostel_category'
        AND b.status NOT IN ('cancelled','superseded')
    );

    SELECT lp.institution_id INTO v_inst_id
    FROM learners_profiles lp WHERE lp.id = v_lp_id;

    INSERT INTO billing_student_bills
      (student_id, institution_id, item_category_id, hostel_year_id, fee_source,
       bill_description, due_date, quantity, unit_amount, total_amount,
       final_amount, balance_amount, status)
    VALUES
      (v_lp_id, v_inst_id, v_bill_cat, v_b.hostel_year_id, 'hostel_category',
       'Room buyout: ' || (v_b.capacity_at_request - v_occupants)
         || ' empty bed' || CASE WHEN (v_b.capacity_at_request - v_occupants) = 1 THEN '' ELSE 's' END
         || ' held for exclusive use',
       (now() + make_interval(days => v_due_days))::date,
       1, v_amount, v_amount, v_amount, v_amount, 'unpaid')
    RETURNING id INTO v_bill_id;

    UPDATE hostel_room_buyout_consents SET bill_id = v_bill_id WHERE id = c.consent_id;
    v_billed := v_billed + 1;
  END LOOP;

  UPDATE hostel_room_buyouts
     SET status = 'active', activated_at = now(), occupants_at_request = v_occupants
   WHERE id = p_buyout_id;

  -- Close any open settle window on this room: it has just been settled by
  -- hand, and leaving the window open would put the room back in the sweep's
  -- due list where the dedup guard would have to catch it a second time.
  UPDATE hostel_room_settle_windows
     SET status = 'billed', billed_at = now(), occupants_at_billing = v_occupants
   WHERE room_id = v_b.room_id
     AND hostel_year_id = v_b.hostel_year_id
     AND status = 'open';

  RETURN jsonb_build_object('status', 'active', 'buyout_id', p_buyout_id,
                            'room_id', v_b.room_id,
                            'amount_per_resident', v_amount,
                            'bills_raised', v_billed);
END;
$function$;

CREATE OR REPLACE FUNCTION public.fn_room_buyout_request(p_room_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_q        jsonb;
  v_me       uuid := auth.uid();
  v_alloc    uuid;
  v_hours    int;
  v_buyout   uuid;
  v_inst     uuid;
  v_others   int;
  a          record;
BEGIN
  IF v_me IS NULL THEN
    RAISE EXCEPTION 'permission denied: no signed-in learner' USING ERRCODE = '42501';
  END IF;

  SELECT a2.id INTO v_alloc
  FROM hostel_allocations a2
  WHERE a2.room_id = p_room_id AND a2.check_out_date IS NULL AND a2.learner_id = v_me
  LIMIT 1;

  IF v_alloc IS NULL THEN
    RAISE EXCEPTION 'permission denied: you are not a resident of this room'
      USING ERRCODE = '42501';
  END IF;

  v_q := fn_room_buyout_quote(p_room_id);
  IF NOT (v_q->>'eligible')::boolean THEN
    RETURN jsonb_build_object('status', 'refused', 'reason', v_q->>'reason', 'quote', v_q);
  END IF;

  v_hours := GREATEST(1, fn_get_policy_int('hostel.settle_bill.buyout_consent_hours', 48));

  SELECT lp.institution_id INTO v_inst
  FROM profiles p JOIN learners_profiles lp ON lp.id = p.learner_id
  WHERE p.id = v_me;

  INSERT INTO hostel_room_buyouts
    (room_id, hostel_year_id, institution_id, requested_by_learner_id,
     capacity_at_request, occupants_at_request, empty_beds,
     amount_per_resident, status, consent_deadline)
  VALUES
    (p_room_id, (v_q->>'hostel_year_id')::uuid, v_inst, v_me,
     (v_q->>'capacity')::int, (v_q->>'occupants')::int, (v_q->>'empty_beds')::int,
     (v_q->>'amount_per_resident')::numeric, 'pending_consent',
     now() + make_interval(hours => v_hours))
  RETURNING id INTO v_buyout;

  -- One consent row per CURRENT resident. The requester's is already agreed —
  -- asking her to confirm what she just asked for is noise.
  FOR a IN
    SELECT a2.id AS allocation_id, a2.learner_id
    FROM hostel_allocations a2
    WHERE a2.room_id = p_room_id AND a2.check_out_date IS NULL
  LOOP
    INSERT INTO hostel_room_buyout_consents
      (buyout_id, allocation_id, learner_id, decision, decided_at)
    VALUES
      (v_buyout, a.allocation_id, a.learner_id,
       CASE WHEN a.learner_id = v_me THEN 'agreed' ELSE 'pending' END,
       CASE WHEN a.learner_id = v_me THEN now() ELSE NULL END);
  END LOOP;

  SELECT COUNT(*)::int INTO v_others
  FROM hostel_room_buyout_consents
  WHERE buyout_id = v_buyout AND decision = 'pending';

  -- Sole occupant: nobody else to ask, so it takes effect at once.
  IF v_others = 0 THEN
    RETURN _room_buyout_activate(v_buyout) || jsonb_build_object('quote', v_q);
  END IF;

  RETURN jsonb_build_object('status', 'pending_consent', 'buyout_id', v_buyout,
                            'awaiting', v_others, 'quote', v_q);
END;
$function$;

CREATE OR REPLACE FUNCTION public.fn_room_buyout_respond(p_buyout_id uuid, p_agree boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_me      uuid := auth.uid();
  v_b       public.hostel_room_buyouts%ROWTYPE;
  v_consent uuid;
  v_pending int;
BEGIN
  SELECT * INTO v_b FROM hostel_room_buyouts WHERE id = p_buyout_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not_found', 'buyout_id', p_buyout_id);
  END IF;

  IF v_b.status <> 'pending_consent' THEN
    RETURN jsonb_build_object('status', v_b.status, 'buyout_id', p_buyout_id);
  END IF;

  IF now() > v_b.consent_deadline THEN
    UPDATE hostel_room_buyouts SET status = 'expired' WHERE id = p_buyout_id;
    RETURN jsonb_build_object('status', 'expired', 'buyout_id', p_buyout_id);
  END IF;

  SELECT k.id INTO v_consent
  FROM hostel_room_buyout_consents k
  WHERE k.buyout_id = p_buyout_id AND k.learner_id = v_me;

  IF v_consent IS NULL THEN
    RAISE EXCEPTION 'permission denied: you were not asked to agree to this buyout'
      USING ERRCODE = '42501';
  END IF;

  UPDATE hostel_room_buyout_consents
     SET decision = CASE WHEN p_agree THEN 'agreed' ELSE 'declined' END,
         decided_at = now()
   WHERE id = v_consent;

  -- One refusal ends it. The others are not billed, and the room stays open.
  IF NOT p_agree THEN
    UPDATE hostel_room_buyouts
       SET status = 'declined', cancelled_reason = 'roommate_declined'
     WHERE id = p_buyout_id;
    RETURN jsonb_build_object('status', 'declined', 'buyout_id', p_buyout_id);
  END IF;

  SELECT COUNT(*)::int INTO v_pending
  FROM hostel_room_buyout_consents
  WHERE buyout_id = p_buyout_id AND decision = 'pending';

  IF v_pending > 0 THEN
    RETURN jsonb_build_object('status', 'pending_consent', 'buyout_id', p_buyout_id,
                              'awaiting', v_pending);
  END IF;

  RETURN _room_buyout_activate(p_buyout_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.fn_room_buyout_release(p_buyout_id uuid, p_reason text DEFAULT NULL)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_b public.hostel_room_buyouts%ROWTYPE;
BEGIN
  SELECT * INTO v_b FROM hostel_room_buyouts WHERE id = p_buyout_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not_found', 'buyout_id', p_buyout_id);
  END IF;

  IF NOT fn_settle_can_manage(v_b.room_id, 'campus_living.fees.config') THEN
    RAISE EXCEPTION 'permission denied: campus_living.fees.config on this room'
      USING ERRCODE = '42501';
  END IF;

  IF v_b.status NOT IN ('pending_consent','active') THEN
    RETURN jsonb_build_object('status', v_b.status, 'buyout_id', p_buyout_id);
  END IF;

  UPDATE hostel_room_buyouts
     SET status = 'released', released_at = now(), released_by = auth.uid(),
         release_reason = p_reason
   WHERE id = p_buyout_id;

  RETURN jsonb_build_object('status', 'released', 'buyout_id', p_buyout_id,
                            'room_id', v_b.room_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.fn_my_room_settle_window()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
           'window_id',        w.id,
           'room_id',          w.room_id,
           'opened_at',        w.opened_at,
           'current_deadline', w.current_deadline,
           'hard_deadline',    w.hard_deadline,
           'restart_count',    w.restart_count,
           'status',           w.status)
  FROM hostel_room_settle_windows w
  JOIN hostel_allocations a
    ON a.room_id = w.room_id
   AND a.check_out_date IS NULL
   AND a.learner_id = auth.uid()
  WHERE w.status = 'open'
  ORDER BY w.current_deadline
  LIMIT 1;
$function$;


-- ============================================================
-- Premium roommate invite repair + candidate list (2026-08-14)
-- Source: supabase/migrations/20260905043700_*.sql
-- ============================================================

CREATE OR REPLACE FUNCTION public.fn_premium_create_invite(p_allocation_id uuid, p_inviter_learner_id uuid, p_invited_learner_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_allocation record;
  v_inviter_lp uuid;
  v_invited_lp uuid;
  v_inviter_gender TEXT;
  v_invited_gender TEXT;
  v_invited_institution UUID;
  v_invited_already_allocated INTEGER;
  v_invited_cat UUID;
  v_invite_window_hours INTEGER;
  v_invite_max_retries INTEGER;
  v_existing_retry_count INTEGER;
  v_invite_id UUID;
  v_invite_token TEXT;
BEGIN
  -- You may only send invites as yourself. Without this, a signed-in learner
  -- can pass another learner's id and forge an invite in her name.
  IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_inviter_learner_id THEN
    RAISE EXCEPTION 'permission denied: you may only send invites as yourself'
      USING ERRCODE = '42501';
  END IF;

  IF p_inviter_learner_id = p_invited_learner_id THEN
    RETURN jsonb_build_object('success', false, 'reason', 'self_invite',
      'detail', 'You cannot invite yourself.');
  END IF;

  -- Step 1: the allocation belongs to the inviter, is active, and its ROOM sits
  -- in a category opted into room sharing.
  SELECT ha.institution_id, ha.tier_id, ha.status, ha.room_id,
         r.category_id AS room_category_id,
         COALESCE(hc.settle_billing_enabled, false) AS sharing_enabled
    INTO v_allocation
    FROM public.hostel_allocations ha
    LEFT JOIN public.hostel_rooms r      ON r.id = ha.room_id
    LEFT JOIN public.hostel_categories hc ON hc.id = r.category_id
   WHERE ha.id = p_allocation_id
     AND ha.learner_id = p_inviter_learner_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'allocation_not_found',
      'detail', 'Allocation not found or you are not the inviter.');
  END IF;

  IF v_allocation.status <> 'active' THEN
    RETURN jsonb_build_object('success', false, 'reason', 'allocation_inactive',
      'detail', 'Your allocation is not active. Cannot invite roommate.');
  END IF;

  IF NOT v_allocation.sharing_enabled THEN
    RETURN jsonb_build_object('success', false, 'reason', 'category_not_shareable',
      'detail', 'Roommate invites are not available for your room category.');
  END IF;

  -- Step 2: BOTH parameters are profiles.id. Resolve each to its learner
  -- record through profiles.learner_id. Reading learners_profiles by these ids
  -- directly is what made every invite fail — the two id spaces are disjoint.
  SELECT learner_id INTO v_inviter_lp FROM public.profiles WHERE id = p_inviter_learner_id;
  SELECT learner_id INTO v_invited_lp FROM public.profiles WHERE id = p_invited_learner_id;

  IF v_invited_lp IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'invited_not_a_learner',
      'detail', 'That person does not have a learner record.');
  END IF;

  SELECT upper(trim(lp.gender)), lp.institution_id
    INTO v_invited_gender, v_invited_institution
    FROM public.learners_profiles lp
   WHERE lp.id = v_invited_lp;

  IF v_invited_gender IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'invited_not_found',
      'detail', 'Invited learner not found.');
  END IF;

  SELECT upper(trim(gender)) INTO v_inviter_gender
    FROM public.learners_profiles WHERE id = v_inviter_lp;

  IF v_inviter_gender IS DISTINCT FROM v_invited_gender THEN
    RETURN jsonb_build_object('success', false, 'reason', 'gender_mismatch',
      'detail', 'Roommate must be of the same gender.');
  END IF;

  IF v_invited_institution IS DISTINCT FROM v_allocation.institution_id THEN
    RETURN jsonb_build_object('success', false, 'reason', 'institution_mismatch',
      'detail', 'Roommate must be from the same institution.');
  END IF;

  -- Step 3a: SAME ROOM CATEGORY ONLY. A Premium resident invites Premium
  -- residents; a Deluxe resident is not a candidate. Accepting would move her
  -- into this category's room AND its price band, and a fee change of that size
  -- belongs in the upgrade path she chooses deliberately, not in an invite she
  -- taps accept on. Her CURRENT room decides it; an unallocated hostelite falls
  -- back to the category recorded on her profile.
  SELECT COALESCE(r2.category_id, lp2.hostel_category_id) INTO v_invited_cat
    FROM public.learners_profiles lp2
    LEFT JOIN public.hostel_allocations a2
           ON a2.learner_id = p_invited_learner_id AND a2.check_out_date IS NULL
    LEFT JOIN public.hostel_rooms r2 ON r2.id = a2.room_id
   WHERE lp2.id = v_invited_lp
   LIMIT 1;

  IF v_invited_cat IS DISTINCT FROM v_allocation.room_category_id THEN
    RETURN jsonb_build_object('success', false, 'reason', 'category_mismatch',
      'detail', 'You can only invite learners in the same room category as yours.');
  END IF;

  -- Step 3b: she is not already living in this very room. Anyone else in the
  -- category is fair game — accepting vacates her old bed properly, so no room
  -- is left double-counted.
  SELECT count(*) INTO v_invited_already_allocated
    FROM public.hostel_allocations ha
   WHERE ha.learner_id = p_invited_learner_id
     AND ha.check_out_date IS NULL
     AND ha.room_id = v_allocation.room_id;

  IF v_invited_already_allocated > 0 THEN
    RETURN jsonb_build_object('success', false, 'reason', 'already_your_roommate',
      'detail', 'That learner already lives in your room.');
  END IF;

  -- Step 4: retry cap.
  v_invite_max_retries := COALESCE(
    public.fn_get_policy_int('hostel.premium.invite_max_retries', 2, NULL), 2);

  SELECT count(*) INTO v_existing_retry_count
    FROM public.hostel_premium_invites
   WHERE inviter_learner_id = p_inviter_learner_id
     AND invited_learner_id = p_invited_learner_id
     AND status IN ('declined', 'expired', 'cancelled');

  IF v_existing_retry_count >= v_invite_max_retries THEN
    RETURN jsonb_build_object('success', false, 'reason', 'retry_cap_reached',
      'detail', 'You have reached the maximum retries for inviting this learner.');
  END IF;

  -- Step 5: no pending invite already.
  IF EXISTS (
    SELECT 1 FROM public.hostel_premium_invites
     WHERE inviter_learner_id = p_inviter_learner_id
       AND invited_learner_id = p_invited_learner_id
       AND status = 'pending'
  ) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'invite_already_pending',
      'detail', 'You already have a pending invite for this learner.');
  END IF;

  v_invite_window_hours := COALESCE(
    public.fn_get_policy_int('hostel.premium.invite_window_hours', 48, NULL), 48);

  INSERT INTO public.hostel_premium_invites (
    allocation_id, inviter_learner_id, invited_learner_id, institution_id,
    tier_id, status, expires_at, retry_count
  ) VALUES (
    p_allocation_id, p_inviter_learner_id, p_invited_learner_id,
    v_allocation.institution_id, v_allocation.tier_id, 'pending',
    now() + (v_invite_window_hours || ' hours')::interval, v_existing_retry_count
  )
  RETURNING id, invite_token INTO v_invite_id, v_invite_token;

  RETURN jsonb_build_object('success', true, 'invite_id', v_invite_id,
    'invite_token', v_invite_token, 'expires_in_hours', v_invite_window_hours,
    'reason', 'ok');

EXCEPTION
  -- Never swallow the identity gate into a soft {success:false}: a refusal that
  -- looks like a business outcome is a refusal nobody notices.
  WHEN insufficient_privilege THEN RAISE;
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'reason', 'unknown', 'detail', SQLERRM);
END;
$function$;

CREATE OR REPLACE FUNCTION public.fn_premium_confirm_invite(p_invite_token text, p_acting_learner_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_invite    record;
  v_host      record;   -- the inviter's allocation: the room being joined
  v_room      record;
  v_bed_id    uuid;
  v_capacity  int;
  v_occupants int;
  v_old       record;
  v_new_alloc uuid;
  v_acting_lp uuid;
  v_host_lp   uuid;
  v_acting_g  text;
  v_host_g    text;
  v_acting_inst uuid;
  v_ec_name   text;
  v_ec_phone  text;
  v_ec_rel    text;
BEGIN
  -- Accepting now ALLOCATES A BED, so the acting identity cannot be a
  -- client-supplied claim. Without this, one learner could accept an invite
  -- addressed to another and move her between rooms.
  IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_acting_learner_id THEN
    RAISE EXCEPTION 'permission denied: you may only answer your own invites'
      USING ERRCODE = '42501';
  END IF;

  SELECT id, invited_learner_id, inviter_learner_id, allocation_id, status, expires_at
    INTO v_invite
    FROM public.hostel_premium_invites
   WHERE invite_token = p_invite_token;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'invite_not_found');
  END IF;

  IF v_invite.invited_learner_id <> p_acting_learner_id THEN
    RETURN jsonb_build_object('success', false, 'reason', 'not_the_invited_party');
  END IF;

  IF v_invite.status <> 'pending' THEN
    RETURN jsonb_build_object('success', false, 'reason', 'invite_not_pending',
      'detail', 'Invite status is ' || v_invite.status);
  END IF;

  IF v_invite.expires_at < now() THEN
    UPDATE public.hostel_premium_invites
       SET status = 'expired', updated_at = now()
     WHERE id = v_invite.id;
    RETURN jsonb_build_object('success', false, 'reason', 'invite_expired');
  END IF;

  -- The room she is joining. Re-read rather than trust the invite: it may have
  -- been sent days ago and the inviter may since have moved or left.
  SELECT ha.id, ha.room_id, ha.block_id, ha.institution_id, ha.tier_id,
         ha.academic_year_id, ha.semester_id, ha.batch_id, ha.status
    INTO v_host
    FROM public.hostel_allocations ha
   WHERE ha.id = v_invite.allocation_id;

  IF v_host.id IS NULL OR v_host.status <> 'active' OR v_host.room_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'host_allocation_inactive',
      'detail', 'The room you were invited to is no longer available.');
  END IF;

  -- Re-check gender and institution at acceptance. These were true when the
  -- invite was sent; an accept can land 48 hours later.
  SELECT learner_id INTO v_acting_lp FROM public.profiles WHERE id = p_acting_learner_id;
  SELECT learner_id INTO v_host_lp   FROM public.profiles WHERE id = v_invite.inviter_learner_id;

  SELECT upper(trim(gender)), institution_id INTO v_acting_g, v_acting_inst
    FROM public.learners_profiles WHERE id = v_acting_lp;
  SELECT upper(trim(gender)) INTO v_host_g
    FROM public.learners_profiles WHERE id = v_host_lp;

  IF v_acting_g IS NULL OR v_acting_g IS DISTINCT FROM v_host_g THEN
    RETURN jsonb_build_object('success', false, 'reason', 'gender_mismatch',
      'detail', 'Roommate must be of the same gender.');
  END IF;

  IF v_acting_inst IS DISTINCT FROM v_host.institution_id THEN
    RETURN jsonb_build_object('success', false, 'reason', 'institution_mismatch',
      'detail', 'Roommate must be from the same institution.');
  END IF;

  SELECT r.id, r.room_number, r.capacity, r.block_id INTO v_room
    FROM public.hostel_rooms r WHERE r.id = v_host.room_id;

  v_capacity := GREATEST(1, COALESCE(v_room.capacity, 1));
  SELECT count(*) INTO v_occupants
    FROM public.hostel_allocations ha
   WHERE ha.room_id = v_host.room_id AND ha.check_out_date IS NULL;

  IF v_occupants >= v_capacity THEN
    RETURN jsonb_build_object('success', false, 'reason', 'room_full',
      'detail', 'That room filled up before you accepted.');
  END IF;

  -- Lowest-numbered free bed, claimed under the same advisory lock
  -- fn_self_change_room uses, so two accepts cannot take one bed.
  SELECT b.id INTO v_bed_id
    FROM public.hostel_beds b
   WHERE b.room_id = v_host.room_id
     AND b.status = 'available'
     AND NOT EXISTS (SELECT 1 FROM public.hostel_allocations ha
                      WHERE ha.bed_id = b.id AND ha.check_out_date IS NULL)
   ORDER BY b.bed_number
   LIMIT 1;

  IF v_bed_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_free_bed',
      'detail', 'There is no free bed in that room any more.');
  END IF;

  IF NOT pg_try_advisory_xact_lock(hashtext(v_bed_id::text)) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'bed_contended',
      'detail', 'Someone is claiming that bed right now. Try again.');
  END IF;

  -- Her current place, if any. Moving in means leaving it — same vacate shape
  -- fn_self_change_room uses, so occupancy and the bed index stay consistent.
  SELECT ha.id, ha.bed_id, ha.room_id,
         ha.emergency_contact_name, ha.emergency_contact_phone, ha.emergency_contact_relation
    INTO v_old
    FROM public.hostel_allocations ha
   WHERE ha.learner_id = p_acting_learner_id AND ha.status = 'active'
   ORDER BY ha.allocation_date DESC LIMIT 1;

  IF v_old.id IS NOT NULL AND v_old.room_id = v_host.room_id THEN
    RETURN jsonb_build_object('success', false, 'reason', 'already_in_room',
      'detail', 'You already live in that room.');
  END IF;

  -- Emergency contact is NOT NULL on hostel_allocations, and rightly so: it is a
  -- safety record. Carry hers forward from the room she is leaving; failing
  -- that, fall back to a parent on her learner profile. If neither exists,
  -- REFUSE — a placeholder like 'Not provided' in this column is worse than a
  -- blocked move, because it reads as a real contact in an emergency.
  IF v_old.id IS NOT NULL THEN
    v_ec_name  := NULLIF(TRIM(v_old.emergency_contact_name), '');
    v_ec_phone := NULLIF(TRIM(v_old.emergency_contact_phone), '');
    v_ec_rel   := NULLIF(TRIM(v_old.emergency_contact_relation), '');
  END IF;

  IF v_ec_name IS NULL OR v_ec_phone IS NULL THEN
    SELECT NULLIF(TRIM(lp.father_name),''), NULLIF(TRIM(lp.father_mobile),''), 'Father'
      INTO v_ec_name, v_ec_phone, v_ec_rel
      FROM public.learners_profiles lp
     WHERE lp.id = v_acting_lp
       AND NULLIF(TRIM(lp.father_name),'')   IS NOT NULL
       AND NULLIF(TRIM(lp.father_mobile),'') IS NOT NULL;
  END IF;

  IF v_ec_name IS NULL OR v_ec_phone IS NULL THEN
    SELECT NULLIF(TRIM(lp.mother_name),''), NULLIF(TRIM(lp.mother_mobile),''), 'Mother'
      INTO v_ec_name, v_ec_phone, v_ec_rel
      FROM public.learners_profiles lp
     WHERE lp.id = v_acting_lp
       AND NULLIF(TRIM(lp.mother_name),'')   IS NOT NULL
       AND NULLIF(TRIM(lp.mother_mobile),'') IS NOT NULL;
  END IF;

  IF v_ec_name IS NULL OR v_ec_phone IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_emergency_contact',
      'detail', 'Your profile has no emergency contact. Add one before joining a room.');
  END IF;

  IF v_old.id IS NOT NULL THEN
    UPDATE public.hostel_allocations
       SET status='vacated', actual_vacate_date=CURRENT_DATE,
           check_out_date=CURRENT_DATE, updated_at=now()
     WHERE id = v_old.id;
    UPDATE public.hostel_beds
       SET status='available', current_occupant_id=NULL
     WHERE id = v_old.bed_id;
  END IF;

  -- The room-buyout lock is enforced by a BEFORE trigger on this INSERT. A room
  -- whose residents have paid for its empty beds refuses a new body, and that
  -- refusal surfaces through the handler below rather than being bypassed here.
  INSERT INTO public.hostel_allocations (
    institution_id, learner_id, block_id, room_id, bed_id,
    academic_year_id, semester_id, allocation_type, allocation_date, status,
    emergency_contact_name, emergency_contact_phone, emergency_contact_relation,
    tier_id, allocated_by, batch_id, metadata
  ) VALUES (
    v_host.institution_id, p_acting_learner_id, COALESCE(v_room.block_id, v_host.block_id),
    v_host.room_id, v_bed_id, v_host.academic_year_id, v_host.semester_id,
    'transfer', CURRENT_DATE, 'active',
    v_ec_name, v_ec_phone, COALESCE(v_ec_rel, 'Guardian'),
    v_host.tier_id, p_acting_learner_id, v_host.batch_id,
    jsonb_build_object('premium_invite', true,
                       'invite_id', v_invite.id,
                       'inviter_learner_id', v_invite.inviter_learner_id,
                       'from_room_id', v_old.room_id,
                       'joined_at', to_jsonb(now()))
  ) RETURNING id INTO v_new_alloc;

  UPDATE public.hostel_beds
     SET status='occupied', current_occupant_id=p_acting_learner_id
   WHERE id = v_bed_id;

  UPDATE public.hostel_premium_invites
     SET status = 'accepted', accepted_at = now(), updated_at = now()
   WHERE id = v_invite.id;

  RETURN jsonb_build_object('success', true, 'invite_id', v_invite.id,
    'reason', 'ok', 'allocation_id', v_new_alloc,
    'room_id', v_host.room_id, 'room_number', v_room.room_number,
    'bed_id', v_bed_id, 'vacated_allocation_id', v_old.id);

EXCEPTION
  -- Never swallow the identity gate into a soft {success:false}: a refusal that
  -- looks like a business outcome is a refusal nobody notices.
  WHEN insufficient_privilege THEN RAISE;
  WHEN OTHERS THEN
  -- Everything above rolls back with this, including the status flip — an
  -- 'accepted' invite that moved nobody is the one outcome worth avoiding.
  RETURN jsonb_build_object('success', false, 'reason', 'unknown', 'detail', SQLERRM);
END;
$function$;

CREATE OR REPLACE FUNCTION public.fn_premium_invite_candidates(p_allocation_id uuid)
 RETURNS TABLE(
   profile_id uuid,
   full_name text,
   register_number text,
   department_name text,
   semester_name text,
   program_name text,
   institution_name text,
   current_room_category text,
   current_block_name text,
   current_room_number text,
   current_room_id uuid,
   same_category boolean,
   already_invited boolean
 )
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_me       uuid := auth.uid();
  v_host     record;
  v_my_cat   uuid;
  v_my_g     text;
  v_my_lp    uuid;
  v_retries  int;
BEGIN
  -- No caller, no list. Tested BEFORE the ownership comparison because
  -- `learner_id <> NULL` evaluates to NULL, not TRUE — an IF on it never fires,
  -- so a sessionless caller would slip past the ownership gate and safety would
  -- rest on a later IF happening to RETURN. Caught by a test that expected a
  -- refusal and got an empty list instead.
  IF v_me IS NULL THEN
    RAISE EXCEPTION 'permission denied: no signed-in learner' USING ERRCODE = '42501';
  END IF;

  SELECT ha.id, ha.learner_id, ha.institution_id, ha.room_id, ha.status,
         r.category_id, COALESCE(hc.settle_billing_enabled, false) AS sharing_enabled
    INTO v_host
    FROM hostel_allocations ha
    LEFT JOIN hostel_rooms r       ON r.id = ha.room_id
    LEFT JOIN hostel_categories hc ON hc.id = r.category_id
   WHERE ha.id = p_allocation_id;

  -- Own-allocation scope. SECURITY DEFINER bypasses RLS, so without this any
  -- signed-in learner could enumerate another institution's roll.
  -- IS DISTINCT FROM, not <>: a NULL learner_id must FAIL the check, not skip it.
  IF v_host.id IS NULL OR v_host.learner_id IS DISTINCT FROM v_me THEN
    RAISE EXCEPTION 'permission denied: that is not your allocation'
      USING ERRCODE = '42501';
  END IF;

  -- A room with no category cannot be matched against, so there is nobody to
  -- offer rather than everybody.
  IF v_host.status <> 'active' OR NOT v_host.sharing_enabled OR v_host.category_id IS NULL THEN
    RETURN;  -- no candidates: the invite would refuse every one of them
  END IF;

  v_my_cat := v_host.category_id;
  SELECT learner_id INTO v_my_lp FROM profiles WHERE id = v_me;
  SELECT upper(trim(gender)) INTO v_my_g FROM learners_profiles WHERE id = v_my_lp;

  IF v_my_g IS NULL THEN
    RETURN;  -- gender unknown: every invite would fail the gender check
  END IF;

  v_retries := COALESCE(fn_get_policy_int('hostel.premium.invite_max_retries', 2, NULL), 2);

  RETURN QUERY
  SELECT
    p2.id,
    COALESCE(p2.full_name, '(no name)')::text,
    lp.register_number::text,
    d.department_name::text,
    s.semester_name::text,
    pr.program_name::text,
    i.name::text,
    hc2.name::text,
    hb.name::text,
    r2.room_number::text,
    r2.id,
    (r2.category_id IS NOT DISTINCT FROM v_my_cat),
    EXISTS (SELECT 1 FROM hostel_premium_invites hpi
             WHERE hpi.inviter_learner_id = v_me
               AND hpi.invited_learner_id = p2.id
               AND hpi.status = 'pending')
  FROM learners_profiles lp
  JOIN profiles p2                   ON p2.learner_id = lp.id
  JOIN accommodation_types acc       ON acc.id = lp.accommodation_type_id AND acc.code = 'hostel'
  LEFT JOIN departments d            ON d.id = lp.department_id
  LEFT JOIN semesters s              ON s.id = lp.semester_id
  LEFT JOIN programs pr              ON pr.id = lp.program_id
  LEFT JOIN institutions i           ON i.id = lp.institution_id
  LEFT JOIN hostel_allocations a2    ON a2.learner_id = p2.id AND a2.check_out_date IS NULL
  LEFT JOIN hostel_rooms r2          ON r2.id = a2.room_id
  LEFT JOIN hostel_categories hc2    ON hc2.id = r2.category_id
  LEFT JOIN hostel_blocks hb         ON hb.id = a2.block_id
  WHERE lp.institution_id = v_host.institution_id
    AND upper(trim(lp.gender)) = v_my_g
    AND p2.id <> v_me
    -- SAME ROOM CATEGORY ONLY — the identical rule fn_premium_create_invite
    -- enforces, so the list can never offer a learner the invite would refuse.
    -- A Premium resident sees Premium residents; Deluxe never appears.
    AND COALESCE(r2.category_id, lp.hostel_category_id) IS NOT DISTINCT FROM v_my_cat
    -- already in this very room: she is a roommate, not a candidate
    AND NOT EXISTS (
      SELECT 1 FROM hostel_allocations ha2
      WHERE ha2.learner_id = p2.id AND ha2.check_out_date IS NULL
        AND ha2.room_id = v_host.room_id)
    -- retry cap already spent on this pair
    AND (SELECT count(*) FROM hostel_premium_invites hpi2
          WHERE hpi2.inviter_learner_id = v_me
            AND hpi2.invited_learner_id = p2.id
            AND hpi2.status IN ('declined','expired','cancelled')) < v_retries
  ORDER BY (r2.category_id IS NOT DISTINCT FROM v_my_cat) DESC,
           d.department_name NULLS LAST,
           s.semester_name NULLS LAST,
           COALESCE(p2.full_name, '');
END;
$function$;


CREATE OR REPLACE FUNCTION public.fn_premium_decline_invite(p_invite_token text, p_acting_learner_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_invite record;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_acting_learner_id THEN
    RAISE EXCEPTION 'permission denied: you may only answer your own invites'
      USING ERRCODE = '42501';
  END IF;

  SELECT id, invited_learner_id, status INTO v_invite
    FROM public.hostel_premium_invites WHERE invite_token = p_invite_token;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'invite_not_found');
  END IF;
  IF v_invite.invited_learner_id IS DISTINCT FROM p_acting_learner_id THEN
    RETURN jsonb_build_object('success', false, 'reason', 'not_the_invited_party');
  END IF;
  IF v_invite.status <> 'pending' THEN
    RETURN jsonb_build_object('success', false, 'reason', 'invite_not_pending');
  END IF;

  UPDATE public.hostel_premium_invites
     SET status = 'declined', declined_at = now(), updated_at = now()
   WHERE id = v_invite.id;

  RETURN jsonb_build_object('success', true, 'invite_id', v_invite.id, 'reason', 'ok');
END;
$function$;




-- ============================================================================
-- fn_hostel_allocation_audit — read-only allocation conformance audit powering
-- /campus-living/allocations/audit and the audit panel on the allocation detail
-- page. Mirrored from migration 20260816120000_hostel_allocation_audit_rpc.sql.
-- Grants are part of the definition: SECURITY DEFINER over billing + PII, so
-- anon must stay revoked.
-- ============================================================================
-- ============================================================================
-- Allocation Audit — /campus-living/allocations/audit
--
-- One row per hostel allocation, answering "was this learner placed correctly?"
-- against the TWO gates the auto-allocator actually applies:
--
--   GATE 1  fee band   hostel_program_eligibility, resolved from the academic
--                      bill total of the learner's ANCHOR academic year.
--                      fn_learner_band_academic_fee() picks the ADMISSION
--                      academic year if a bill exists for it, otherwise the
--                      EARLIEST billed year — that fallback is invisible in
--                      every other screen and it silently changes which band
--                      applies, so band_year_source is returned explicitly.
--
--   GATE 2  physical   hostel_room_eligibility_rules covering the room the
--                      learner ACTUALLY occupies (block + floor, or the
--                      explicit room list when the rule has one).
--
-- A category ABOVE the band is not automatically a defect: the upgrade path
-- legitimises it. Upgrade legitimacy comes from billing_student_bills with
-- fee_source = 'hostel_category' -- NOT from hostel_waitlist, whose upgrade
-- trail is 305/334 expired|cancelled|declined and disagrees with the bills.
-- So "above band" is split by whether a bill exists and whether it was
-- collected: paid / partial / unpaid / cancelled-only / never billed.
--
-- Read-only: no writes, no repair, no side effects.
--
-- Access: gated on the catalog key campus_living.allocations.audit, which is
-- deliberately granted to NO role. user_has_permission() super-admin-bypasses,
-- so this is super-admin-only today and grantable from Role Management later
-- without a code change. Never gate on a role name.
-- ============================================================================

-- Both signatures dropped: the 5-arg form shipped first, and leaving it behind
-- would give PostgREST two overloads to choose between (PGRST203) rather than
-- replacing it.
DROP FUNCTION IF EXISTS public.fn_hostel_allocation_audit(text, uuid, uuid, uuid, text);
DROP FUNCTION IF EXISTS public.fn_hostel_allocation_audit(text, uuid, uuid, uuid, text, uuid);

CREATE FUNCTION public.fn_hostel_allocation_audit(
  p_hostel_type    text DEFAULT NULL,
  p_institution_id uuid DEFAULT NULL,
  p_program_id     uuid DEFAULT NULL,
  p_semester_id    uuid DEFAULT NULL,
  p_status         text DEFAULT 'active',
  -- Single-allocation lookup for the allocation detail page. Callers passing
  -- this should also pass p_status => 'all': a superseded ('vacated') row is
  -- still a row someone can open, and the 'active' default would return
  -- nothing for it.
  p_allocation_id  uuid DEFAULT NULL
)
RETURNS TABLE (
  -- identity
  allocation_id                 uuid,
  learner_profile_id            uuid,
  learner_id                    uuid,
  full_name                     text,
  roll_number                   text,
  email                         text,
  gender                        text,
  institution_id                uuid,
  institution_name              text,
  degree_name                   text,
  department_name               text,
  program_id                    uuid,
  program_name                  text,
  semester_id                   uuid,
  semester_name                 text,
  quota_name                    text,
  -- years: admitted vs the year the fee band was read from
  admission_year                integer,
  admission_academic_year_name  text,
  band_academic_year_name       text,
  band_year_source              text,   -- admission_year | earliest_billed | no_admission_anchor | none
  -- the bills of that academic year (what the band was computed from)
  band_fee                      numeric,
  band_year_bill_count          integer,
  band_year_bill_paid           numeric,
  band_year_bill_balance        numeric,
  academic_bill_count           integer,
  -- fee band resolution
  matched_fee_min               numeric,
  matched_fee_max               numeric,
  entitled_room_category_name   text,
  entitled_mess_category_name   text,
  band_verdict                  text,   -- in_band | above_band | below_band | no_band | unranked
  -- the placement
  hostel_type                   text,
  block_name                    text,
  room_number                   text,
  floor                         integer,
  bed_number                    text,
  allocation_type               text,
  allocation_status             text,
  allocation_date               date,
  -- room_id is returned purely so the audit page can reuse the Allocations
  -- module's Advanced Filters verbatim -- its Room dropdown keys on it.
  room_id                       uuid,
  occupied_room_category_id     uuid,
  occupied_room_category_name   text,
  current_mess_category_name    text,
  mess_in_band                  boolean,
  -- first placement vs now (the upgrade story)
  first_room_category_name      text,
  first_allocation_date         date,
  is_upgraded                   boolean,
  upgrade_bill_state            text,   -- paid | partial | unpaid | cancelled_only | none
  upgrade_bill_count            integer,
  upgrade_bill_total            numeric,
  upgrade_bill_paid             numeric,
  upgrade_bill_balance          numeric,
  upgrade_bill_descriptions     text,
  -- physical room rules
  room_rule_verdict             text,   -- rule_matched | open_room | violation
  matched_rule_name             text,
  pinned_blocks                 text,
  serves_institution            boolean,
  -- overall
  verdict                       text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.user_has_permission('campus_living.allocations.audit') THEN
    RAISE EXCEPTION 'Not authorised to read the allocation audit'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH cur_year AS MATERIALIZED (
    SELECT id FROM hostel_years WHERE is_current LIMIT 1
  ),
  -- Per-bed annual rate for the current hostel year. This is what ranks
  -- categories -- NOT hostel_categories.sort_order, which has Deluxe Plus at 0
  -- (below Classic) while it is priced above Deluxe. Ranking on sort_order
  -- inverts above/below band for that tier.
  price AS MATERIALIZED (
    SELECT hf.hostel_category_id AS cid, hf.amount
    FROM hostel_fees hf, cur_year y
    WHERE hf.hostel_year_id = y.id
      AND hf.mess_category_id IS NULL
      AND hf.is_active
  ),
  alloc AS MATERIALIZED (
    SELECT
      a.id                AS alloc_id,
      a.learner_id        AS profile_id,
      a.room_id, a.block_id, a.bed_id,
      a.allocation_type::text  AS alloc_type,
      a.status::text           AS alloc_status,
      a.allocation_date        AS alloc_date,
      r.room_number::text      AS room_number,
      r.floor                  AS floor,
      r.category_id            AS room_cat_id,
      hb.name::text            AS block_name,
      hb.hostel_type::text     AS hostel_type,
      bd.bed_number::text      AS bed_number,
      lp.id                    AS lp_id,
      lp.institution_id, lp.degree_id, lp.department_id,
      lp.program_id, lp.semester_id, lp.quota_id,
      lp.mess_category_id,
      NULLIF(btrim(lp.roll_number), '')::text AS roll_number,
      -- Category resolution keys on learners_profiles.gender, matching both
      -- fn_hostel_learner_room_categories and the allocator's own cats CTE.
      -- profiles.gender is shown to the operator but never used to resolve.
      CASE WHEN lower(lp.gender) LIKE 'm%' THEN 'boys'
           WHEN lower(lp.gender) LIKE 'f%' THEN 'girls' END AS gt,
      lower(btrim(COALESCE(NULLIF(btrim(p.gender), ''), lp.gender)))::text AS eff_gender,
      COALESCE(p.full_name,
               NULLIF(btrim(concat_ws(' ', lp.first_name, lp.last_name)), ''),
               p.email, '—')::text AS full_name,
      p.email::text AS email
    FROM hostel_allocations a
    JOIN profiles p           ON p.id = a.learner_id
    JOIN learners_profiles lp ON lp.id = p.learner_id
    LEFT JOIN hostel_rooms r  ON r.id = a.room_id
    LEFT JOIN hostel_blocks hb ON hb.id = a.block_id
    LEFT JOIN hostel_beds bd  ON bd.id = a.bed_id
    WHERE (p_allocation_id IS NULL OR a.id = p_allocation_id)
      AND (p_status IS NULL OR p_status = 'all' OR a.status::text = p_status)
      AND (p_hostel_type    IS NULL OR hb.hostel_type::text = p_hostel_type)
      AND (p_institution_id IS NULL OR lp.institution_id = p_institution_id)
      AND (p_program_id     IS NULL OR lp.program_id     = p_program_id)
      AND (p_semester_id    IS NULL OR lp.semester_id    = p_semester_id)
  ),
  fee AS MATERIALIZED (
    SELECT al.*,
           fn_learner_admission_academic_year(al.lp_id) AS adm_ay,
           bf.academic_year_id AS band_ay,
           bf.academic_year_name::text AS band_ay_name,
           bf.fee
    FROM alloc al
    LEFT JOIN LATERAL fn_learner_band_academic_fee(al.lp_id) bf ON true
  ),
  cats AS MATERIALIZED (
    SELECT f.*,
      (SELECT array_agg(category_id)
         FROM fn_hostel_effective_room_categories(
                f.institution_id, f.program_id, f.quota_id, f.fee, f.gt)) AS room_cats,
      (SELECT array_agg(category_id)
         FROM fn_hostel_effective_mess_categories(
                f.institution_id, f.program_id, f.quota_id, f.fee, f.gt)) AS mess_cats
    FROM fee f
  ),
  enriched AS (
    SELECT c.*,
      w.fee_min AS w_fee_min, w.fee_max AS w_fee_max,
      fa.first_cat_name, fa.first_date,
      ub.cnt AS ub_cnt, ub.active_cnt AS ub_active, ub.total AS ub_total,
      ub.paid AS ub_paid, ub.balance AS ub_balance, ub.descriptions AS ub_desc,
      bb.cnt AS bb_cnt, bb.paid AS bb_paid, bb.balance AS bb_balance,
      ab.cnt AS ab_cnt,
      mr.nm AS matched_rule, pb.bl AS pinned_bl,
      fn_learner_strictly_eligible_for_room(c.lp_id, c.room_id, true)  AS rule_matched,
      fn_learner_strictly_eligible_for_room(c.lp_id, c.room_id, false) AS access_ok,
      fn_room_serves_institution(c.room_id, c.institution_id)          AS serves_inst,
      (SELECT amount FROM price WHERE cid = c.room_cat_id)             AS occupied_price,
      (SELECT max(amount) FROM price WHERE cid = ANY(c.room_cats))     AS band_price_max,
      (SELECT min(amount) FROM price WHERE cid = ANY(c.room_cats))     AS band_price_min
    FROM cats c
    -- The winning eligibility row, for display. Replicates the specificity
    -- ordering inside fn_hostel_effective_room_categories exactly: program x4 +
    -- quota x2 + fee x1, tie-broken by the NARROWEST fee window.
    LEFT JOIN LATERAL (
      SELECT e.fee_min, e.fee_max
      FROM hostel_program_eligibility e
      WHERE e.institution_id = c.institution_id
        AND e.is_active
        AND e.room_category_id IS NOT NULL
        AND (c.gt IS NULL OR e.hostel_type = 'both' OR e.hostel_type = c.gt)
        AND (e.program_id = c.program_id OR e.program_id IS NULL)
        AND (e.quota_ids IS NULL OR c.quota_id = ANY(e.quota_ids))
        AND (e.fee_min IS NULL OR c.fee >= e.fee_min)
        AND (e.fee_max IS NULL OR c.fee <= e.fee_max)
      ORDER BY ( (e.program_id IS NOT NULL)::int * 4
               + (e.quota_ids  IS NOT NULL)::int * 2
               + ((e.fee_min IS NOT NULL OR e.fee_max IS NOT NULL))::int ) DESC,
               (COALESCE(e.fee_max, 9.9e14::numeric) - COALESCE(e.fee_min, 0)) ASC
      LIMIT 1
    ) w ON true
    -- hostel_allocations is append-only: a room change vacates the old row and
    -- writes a new one, so the EARLIEST row is the category the learner was
    -- originally placed in.
    LEFT JOIN LATERAL (
      SELECT hc0.name::text AS first_cat_name, a0.allocation_date AS first_date
      FROM hostel_allocations a0
      JOIN hostel_rooms r0      ON r0.id = a0.room_id
      JOIN hostel_categories hc0 ON hc0.id = r0.category_id
      WHERE a0.learner_id = c.profile_id
      ORDER BY a0.created_at ASC
      LIMIT 1
    ) fa ON true
    LEFT JOIN LATERAL (
      SELECT count(*)::int AS cnt,
             count(*) FILTER (WHERE b.status <> 'cancelled')::int AS active_cnt,
             COALESCE(sum(b.final_amount)    FILTER (WHERE b.status <> 'cancelled'), 0) AS total,
             COALESCE(sum(COALESCE(b.final_amount,0) - COALESCE(b.balance_amount,0))
                                             FILTER (WHERE b.status <> 'cancelled'), 0) AS paid,
             COALESCE(sum(b.balance_amount)  FILTER (WHERE b.status <> 'cancelled'), 0) AS balance,
             string_agg(b.bill_description || ' (' || b.status || ')', ' · '
                        ORDER BY b.created_at)::text AS descriptions
      FROM billing_student_bills b
      WHERE b.student_id = c.lp_id AND b.fee_source = 'hostel_category'
    ) ub ON true
    -- The bills of the band year specifically -- what band_fee was summed from.
    LEFT JOIN LATERAL (
      SELECT count(*)::int AS cnt,
             COALESCE(sum(COALESCE(b.final_amount,0) - COALESCE(b.balance_amount,0)), 0) AS paid,
             COALESCE(sum(b.balance_amount), 0) AS balance
      FROM billing_student_bills b
      WHERE b.student_id = c.lp_id AND b.fee_source = 'academic'
        AND b.status NOT IN ('cancelled','superseded')
        AND b.academic_year_id IS NOT DISTINCT FROM c.band_ay
    ) bb ON true
    LEFT JOIN LATERAL (
      SELECT count(*)::int AS cnt
      FROM billing_student_bills b
      WHERE b.student_id = c.lp_id AND b.fee_source = 'academic'
        AND b.status NOT IN ('cancelled','superseded')
    ) ab ON true
    LEFT JOIN LATERAL (
      SELECT COALESCE(NULLIF(btrim(r.rule_name), ''), '(unnamed rule)')::text AS nm
      FROM hostel_room_eligibility_rules r
      WHERE r.is_active AND r.block_id = c.block_id
        AND CASE
              WHEN EXISTS (SELECT 1 FROM hostel_room_eligibility_rule_rooms rr WHERE rr.rule_id = r.id)
                THEN EXISTS (SELECT 1 FROM hostel_room_eligibility_rule_rooms rr
                             WHERE rr.rule_id = r.id AND rr.room_id = c.room_id)
              ELSE (r.floor IS NULL OR r.floor = c.floor)
            END
        AND r.institution_id = c.institution_id
        AND (r.degree_id     IS NULL OR r.degree_id     = c.degree_id)
        AND (r.department_id IS NULL OR r.department_id = c.department_id)
        AND (r.program_id    IS NULL OR r.program_id    = c.program_id)
        AND (cardinality(r.semester_ids) = 0 OR c.semester_id = ANY(r.semester_ids))
      ORDER BY r.rule_name
      LIMIT 1
    ) mr ON true
    -- Where this cohort's OWN rules do reserve rooms. On a violation this names
    -- the blocks the learner should have been placed in.
    LEFT JOIN LATERAL (
      SELECT string_agg(DISTINCT hb2.name, ', ')::text AS bl
      FROM hostel_room_eligibility_rules r
      JOIN hostel_blocks hb2 ON hb2.id = r.block_id
      WHERE r.is_active AND r.institution_id = c.institution_id
        AND (r.degree_id     IS NULL OR r.degree_id     = c.degree_id)
        AND (r.department_id IS NULL OR r.department_id = c.department_id)
        AND (r.program_id    IS NULL OR r.program_id    = c.program_id)
        AND (cardinality(r.semester_ids) = 0 OR c.semester_id = ANY(r.semester_ids))
    ) pb ON true
  ),
  scored AS (
    SELECT e.*,
      -- array_agg over a zero-row SRF yields NULL, not '{}'. cardinality(NULL)
      -- is NULL, so a bare cardinality(x)=0 test silently matches nothing --
      -- that hid every no-band row on the first pass of the 2026-08-11 audit.
      (COALESCE(cardinality(e.room_cats), 0) = 0) AS no_band,
      -- Deluxe Plus owns no rooms and sells from Deluxe stock via
      -- room_source_category_id. Occupying the source category IS conformance,
      -- not drift -- 58 of 67 apparent mismatches were exactly this.
      (e.room_cat_id = ANY(COALESCE(e.room_cats, '{}'::uuid[]))
       OR EXISTS (SELECT 1 FROM hostel_categories x
                  WHERE x.id = ANY(COALESCE(e.room_cats, '{}'::uuid[]))
                    AND x.room_source_category_id = e.room_cat_id)) AS in_band,
      CASE
        WHEN e.ub_cnt = 0        THEN 'none'
        WHEN e.ub_active = 0     THEN 'cancelled_only'
        WHEN e.ub_balance <= 0   THEN 'paid'
        WHEN e.ub_paid > 0       THEN 'partial'
        ELSE 'unpaid'
      END AS bill_state
    FROM enriched e
  ),
  final AS (
    SELECT s.*,
      CASE
        WHEN s.no_band  THEN 'no_band'
        WHEN s.in_band  THEN 'in_band'
        WHEN s.occupied_price IS NULL OR s.band_price_max IS NULL THEN 'unranked'
        WHEN s.occupied_price > s.band_price_max THEN 'above_band'
        WHEN s.occupied_price < s.band_price_min THEN 'below_band'
        ELSE 'unranked'
      END AS band_v,
      CASE
        WHEN NOT s.access_ok  THEN 'violation'
        WHEN s.rule_matched   THEN 'rule_matched'
        ELSE 'open_room'
      END AS rule_v
    FROM scored s
  )
  SELECT
    f.alloc_id, f.lp_id, f.profile_id, f.full_name, f.roll_number, f.email,
    f.eff_gender,
    f.institution_id, i.name::text, dg.degree_name::text, dp.department_name::text,
    f.program_id, pr.program_name::text, f.semester_id, sm.semester_name::text,
    q.name::text,
    ady.year,
    aay.academic_year_name::text,
    f.band_ay_name,
    CASE
      WHEN f.band_ay IS NULL                    THEN 'none'
      WHEN f.adm_ay  IS NULL                    THEN 'no_admission_anchor'
      WHEN f.band_ay IS NOT DISTINCT FROM f.adm_ay THEN 'admission_year'
      ELSE 'earliest_billed'
    END,
    f.fee, f.bb_cnt, f.bb_paid, f.bb_balance, f.ab_cnt,
    f.w_fee_min, f.w_fee_max,
    erc.name::text, emc.name::text,
    f.band_v,
    f.hostel_type, f.block_name, f.room_number, f.floor, f.bed_number,
    f.alloc_type, f.alloc_status, f.alloc_date,
    f.room_id,
    f.room_cat_id, orc.name::text, cmc.name::text,
    (f.mess_category_id IS NOT NULL
     AND f.mess_category_id = ANY(COALESCE(f.mess_cats, '{}'::uuid[]))),
    f.first_cat_name, f.first_date,
    (f.first_cat_name IS DISTINCT FROM orc.name::text),
    f.bill_state, f.ub_cnt, f.ub_total, f.ub_paid, f.ub_balance, f.ub_desc,
    f.rule_v, f.matched_rule, f.pinned_bl, f.serves_inst,
    CASE
      WHEN f.band_v = 'no_band'                              THEN 'no_band'
      WHEN f.band_v <> 'in_band' AND f.rule_v = 'violation'  THEN 'band_and_rule_violation'
      WHEN f.rule_v = 'violation'                            THEN 'room_rule_violation'
      WHEN f.band_v = 'below_band'                           THEN 'below_band'
      WHEN f.band_v = 'unranked'                             THEN 'unranked'
      WHEN f.band_v = 'above_band' THEN
        CASE f.bill_state
          WHEN 'paid'           THEN 'upgrade_paid'
          WHEN 'partial'        THEN 'upgrade_partial'
          WHEN 'unpaid'         THEN 'upgrade_unpaid'
          WHEN 'cancelled_only' THEN 'upgrade_bill_cancelled'
          ELSE 'upgrade_unbilled'
        END
      ELSE 'clean'
    END
  FROM final f
  LEFT JOIN institutions i    ON i.id  = f.institution_id
  LEFT JOIN degrees dg        ON dg.id = f.degree_id
  LEFT JOIN departments dp    ON dp.id = f.department_id
  LEFT JOIN programs pr       ON pr.id = f.program_id
  LEFT JOIN semesters sm      ON sm.id = f.semester_id
  LEFT JOIN quotas q          ON q.id  = f.quota_id
  LEFT JOIN admission_years ady  ON ady.id = (SELECT lp2.admission_year_id
                                              FROM learners_profiles lp2 WHERE lp2.id = f.lp_id)
  LEFT JOIN academic_years aay   ON aay.id = f.adm_ay
  LEFT JOIN hostel_categories orc ON orc.id = f.room_cat_id
  LEFT JOIN hostel_categories erc ON erc.id = f.room_cats[1]
  LEFT JOIN mess_categories   emc ON emc.id = f.mess_cats[1]
  LEFT JOIN mess_categories   cmc ON cmc.id = f.mess_category_id
  ORDER BY f.full_name;
END;
$$;

COMMENT ON FUNCTION public.fn_hostel_allocation_audit(text, uuid, uuid, uuid, text, uuid) IS
  'Read-only allocation audit: per-allocation fee-band conformance (anchored on '
  'the admission academic year, falling back to the earliest billed year), '
  'physical room-rule conformance, and the upgrade bill trail that legitimises '
  'an above-band category. Gated on campus_living.allocations.audit.';

-- SECURITY DEFINER over billing + PII. Supabase grants EXECUTE directly to the
-- anon role, so REVOKE ... FROM PUBLIC alone is a no-op -- anon=X survives it.
REVOKE ALL ON FUNCTION public.fn_hostel_allocation_audit(text, uuid, uuid, uuid, text, uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fn_hostel_allocation_audit(text, uuid, uuid, uuid, text, uuid) FROM anon;
GRANT EXECUTE ON FUNCTION public.fn_hostel_allocation_audit(text, uuid, uuid, uuid, text, uuid) TO authenticated;


-- ================================================================================
-- fn_onboarding_payment_progress (2026-08-18)
-- ================================================================================
-- Per-learner fee position against the reserved -> admitted threshold, for the
-- Awaiting Payment tier of /learners/onboarding.
--
-- SECURITY DEFINER for two reasons, in order of weight:
--   (a) it resolves target status / threshold / basis ONCE, from the same
--       admission_statuses rows evaluate_learner_status_after_payment reads, so
--       the number on screen and the number in the gate cannot drift;
--   (b) it decouples this queue from billing permissions. The view it reads is
--       security_invoker, so bills_select_scoped would demand billing.bills.view
--       or billing.schedule.view. Measured 2026-08-18: 0 of 7,204 non-super-admin
--       users lack those, so RLS works TODAY -- but if that grant is ever
--       tightened, RLS returns zero rows rather than erroring and every learner
--       silently renders as "0 billed, 0% paid".
--
-- The learner-visibility predicate is re-applied by hand, copied from
-- learners_profiles_select_policy, so DEFINER never widens who can see a learner.
-- Aggregates only; never bill rows.
CREATE OR REPLACE FUNCTION public.fn_onboarding_payment_progress(p_learner_ids uuid[])
RETURNS TABLE (
  learner_id          uuid,
  target_code         text,
  target_label        text,
  threshold_pct       numeric,
  threshold_basis     text,
  achieved_pct        numeric,
  basis_billed        numeric,
  basis_paid          numeric,
  basis_balance       numeric,
  total_billed        numeric,
  total_paid          numeric,
  total_balance       numeric,
  amount_to_threshold numeric,
  meets_threshold     boolean,
  has_basis_due       boolean
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_target_code   text;
  v_target_label  text;
  v_threshold     numeric;
  v_basis         text;
  v_is_super      boolean := COALESCE(public.is_super_admin(), false);
  v_perm          boolean;
BEGIN
  IF p_learner_ids IS NULL OR array_length(p_learner_ids, 1) IS NULL THEN
    RETURN;
  END IF;

  -- The promotion target for a 'reserved' learner. Resolved with the SAME
  -- predicate evaluate_learner_status_after_payment uses to find a Stage B
  -- target: a threshold-bearing status that neither gates a login ('active',
  -- 60% — never automatic) nor is the universal-paid target ('reserved' itself).
  -- ORDER BY ASC, not DESC: the engine picks the highest threshold ALREADY MET,
  -- but this screen answers "which bar is next?", which is the lowest one.
  SELECT s.code, s.label, s.fee_paid_threshold_percent, s.threshold_basis
    INTO v_target_code, v_target_label, v_threshold, v_basis
  FROM public.admission_statuses s
  WHERE s.scope = 'learner'
    AND s.is_active = true
    AND s.fee_paid_threshold_percent IS NOT NULL
    AND s.gates_login = false
    AND s.auto_promote_when_universal_paid = false
  ORDER BY s.fee_paid_threshold_percent ASC
  LIMIT 1;

  v_basis := COALESCE(v_basis, 'due_to_date');

  -- One permission probe for the whole batch rather than one per learner:
  -- user_has_permission() is the hot path in every RLS policy on this database
  -- and calling it 200x per page render is the shape that produces 57014.
  -- Institution access still varies per row and is checked per row below.
  v_perm := (
    COALESCE(public.user_has_permission('learners.admissions.view'::text), false)
    OR COALESCE(public.user_has_permission('learners.profiles.view'::text), false)
    OR COALESCE(public.user_has_permission('learners.view'::text), false)
  );

  RETURN QUERY
  WITH visible AS (
    -- Byte-for-byte the predicate in learners_profiles_select_policy. DEFINER
    -- bypassed that policy, so it is re-applied here by hand. The self-service
    -- branches are kept so this function is never STRICTER than the policy —
    -- a learner who can see their own row gets their own figures, nobody else's.
    SELECT lp.id, lp.institution_id
    FROM public.learners_profiles lp
    WHERE lp.id = ANY (p_learner_ids)
      AND (
        v_is_super
        OR (v_perm AND public.role_has_institution_access(lp.institution_id))
        OR lp.student_email = (SELECT p.email FROM public.profiles p WHERE p.id = auth.uid())
        OR lp.college_email = (SELECT p.email FROM public.profiles p WHERE p.id = auth.uid())
      )
  ),
  progress AS (
    SELECT
      vis.id AS lid,
      -- Basis-aligned pair. The percent is taken from the view rather than
      -- recomputed from the amounts: a 0.01 rounding difference between this
      -- screen and the promotion engine would read as a bug in the gate.
      CASE v_basis
        WHEN 'billed_to_date'           THEN v.pct_billed_to_date
        WHEN 'due_to_date_current_year' THEN v.pct_due_current_year
        ELSE                                 v.pct_due_to_date
      END AS pct,
      CASE v_basis
        WHEN 'billed_to_date'           THEN v.countable_billed
        WHEN 'due_to_date_current_year' THEN v.due_cy_billed
        ELSE                                 v.due_billed
      END AS b_billed,
      CASE v_basis
        WHEN 'billed_to_date'           THEN v.countable_paid
        WHEN 'due_to_date_current_year' THEN v.due_cy_paid
        ELSE                                 v.due_paid
      END AS b_paid,
      v.countable_billed AS t_billed,
      v.countable_paid   AS t_paid
    FROM visible vis
    JOIN public.vw_learner_payment_progress v ON v.learner_id = vis.id
  )
  SELECT
    p.lid,
    v_target_code,
    v_target_label,
    v_threshold,
    v_basis,
    COALESCE(p.pct, 0),
    COALESCE(p.b_billed, 0),
    COALESCE(p.b_paid, 0),
    COALESCE(p.b_billed, 0) - COALESCE(p.b_paid, 0),
    COALESCE(p.t_billed, 0),
    COALESCE(p.t_paid, 0),
    COALESCE(p.t_billed, 0) - COALESCE(p.t_paid, 0),
    -- NULL, not 0, when nothing is due yet or no threshold is configured.
    -- Rendering "0 to admit" for a learner whose first instalment has not come
    -- due would read as "pay nothing and they are in", which is false — they
    -- are waiting on a due date, not on money.
    CASE
      WHEN v_threshold IS NULL OR COALESCE(p.b_billed, 0) <= 0 THEN NULL
      ELSE GREATEST(0, CEIL(p.b_billed * v_threshold / 100.0) - COALESCE(p.b_paid, 0))
    END,
    (v_threshold IS NOT NULL AND COALESCE(p.b_billed, 0) > 0 AND COALESCE(p.pct, 0) >= v_threshold),
    (COALESCE(p.b_billed, 0) > 0)
  FROM progress p;
END;
$function$;

COMMENT ON FUNCTION public.fn_onboarding_payment_progress(uuid[]) IS
  'Per-learner payment position against the configured reserved->admitted fee threshold, for the Awaiting Payment tier of /learners/onboarding. Basis-aware (admission_statuses.threshold_basis). SECURITY DEFINER so bill totals are readable without billing.bills.view, which working this queue does not require; re-applies learners_profiles_select_policy per row so it never widens who can see a learner.';

-- Supabase grants EXECUTE directly to anon, so REVOKE FROM PUBLIC alone is a
-- no-op — this reads billing aggregates and must not be anon-callable.
REVOKE ALL ON FUNCTION public.fn_onboarding_payment_progress(uuid[]) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fn_onboarding_payment_progress(uuid[]) FROM anon;
GRANT EXECUTE ON FUNCTION public.fn_onboarding_payment_progress(uuid[]) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_onboarding_payment_progress(uuid[]) TO service_role;


-- ===========================================================================
-- Course Events — super-admin-only cascade delete
-- Source: supabase/migrations/20260820020000_course_delete_cascade_super_admin.sql
--
-- The money half of the course FK graph (enrollments, bills, payments, and
-- enrollments.package_id) is ON DELETE RESTRICT on purpose. These two functions
-- are the only sanctioned way past it: the first reports what a delete would
-- destroy, the second clears the children in dependency order so RESTRICT is
-- SATISFIED rather than bypassed. Do not "simplify" this by flipping those FKs
-- to ON DELETE CASCADE — that would make every future delete path silently
-- destroy payment receipts.
-- ===========================================================================

CREATE OR REPLACE FUNCTION public.fn_course_delete_blockers(p_course_event_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $fn$
DECLARE
  v_title text;
  v_out   jsonb;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Only a super admin may delete a course'
      USING ERRCODE = '42501';
  END IF;

  SELECT title INTO v_title FROM public.course_events WHERE id = p_course_event_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Course not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT jsonb_build_object(
    'course_title', v_title,
    'applications', (SELECT count(*) FROM public.course_applications
                      WHERE course_event_id = p_course_event_id),
    'enrollments',  (SELECT count(*) FROM public.course_enrollments
                      WHERE course_event_id = p_course_event_id),
    'packages',     (SELECT count(*) FROM public.course_packages
                      WHERE course_event_id = p_course_event_id),
    'forms',        (SELECT count(*) FROM public.course_registration_forms
                      WHERE course_event_id = p_course_event_id),
    'sessions',     (SELECT count(*) FROM public.course_sessions
                      WHERE course_event_id = p_course_event_id),
    'venue_holds',  (SELECT count(*) FROM public.resource_reservations r
                      WHERE r.course_session_id IN (
                        SELECT id FROM public.course_sessions
                         WHERE course_event_id = p_course_event_id)),
    'bills',        (SELECT count(*) FROM public.course_bills
                      WHERE course_event_id = p_course_event_id),
    'payments',     (SELECT count(*) FROM public.course_bill_payments p
                      WHERE p.bill_id IN (SELECT id FROM public.course_bills
                                           WHERE course_event_id = p_course_event_id)),
    -- Only 'success' rows represent money actually received; 'initiated' rows are
    -- abandoned Razorpay attempts and carry no financial weight.
    'successful_payments', (SELECT count(*) FROM public.course_bill_payments p
                             WHERE p.status = 'success'
                               AND p.bill_id IN (SELECT id FROM public.course_bills
                                                  WHERE course_event_id = p_course_event_id)),
    'amount_received', (SELECT COALESCE(sum(p.amount_paid), 0)
                          FROM public.course_bill_payments p
                         WHERE p.status = 'success'
                           AND p.bill_id IN (SELECT id FROM public.course_bills
                                              WHERE course_event_id = p_course_event_id))
  ) INTO v_out;

  RETURN v_out;
END;
$fn$;

-- ---------------------------------------------------------------------------
-- 2. The cascade itself.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_course_delete_cascade(p_course_event_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $fn$
DECLARE
  v_title       text;
  v_payments    bigint := 0;
  v_bills       bigint := 0;
  v_enrollments bigint := 0;
  v_apps        bigint := 0;
  v_packages    bigint := 0;
  v_forms       bigint := 0;
  v_sessions    bigint := 0;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Only a super admin may delete a course'
      USING ERRCODE = '42501';
  END IF;

  SELECT title INTO v_title FROM public.course_events WHERE id = p_course_event_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Course not found' USING ERRCODE = 'P0002';
  END IF;

  -- Counted before the deletes so the caller gets a truthful receipt of what went.
  SELECT count(*) INTO v_apps     FROM public.course_applications
   WHERE course_event_id = p_course_event_id;
  SELECT count(*) INTO v_packages FROM public.course_packages
   WHERE course_event_id = p_course_event_id;
  SELECT count(*) INTO v_forms    FROM public.course_registration_forms
   WHERE course_event_id = p_course_event_id;
  SELECT count(*) INTO v_sessions FROM public.course_sessions
   WHERE course_event_id = p_course_event_id;

  -- Order matters; each step clears a RESTRICT that would block the next.
  --
  -- (a) Payments first. Matched on bill_id OR enrollment_id because both columns
  --     carry a RESTRICT of their own — a payment reachable by only one of the two
  --     would survive (a) and then block (b) or (c).
  --     trg_course_bill_payments_recompute fires per row here and rewrites the
  --     parent bill/enrollment totals. That is wasted work on rows about to be
  --     deleted, but it is harmless: fn_course_recompute_balances already returns
  --     early on "bill removed in this transaction".
  WITH del AS (
    DELETE FROM public.course_bill_payments p
     WHERE p.bill_id IN (SELECT id FROM public.course_bills
                          WHERE course_event_id = p_course_event_id)
        OR p.enrollment_id IN (SELECT id FROM public.course_enrollments
                                WHERE course_event_id = p_course_event_id)
    RETURNING 1
  ) SELECT count(*) INTO v_payments FROM del;

  -- (b) Bills. Same two-predicate reasoning as (a).
  WITH del AS (
    DELETE FROM public.course_bills b
     WHERE b.course_event_id = p_course_event_id
        OR b.enrollment_id IN (SELECT id FROM public.course_enrollments
                                WHERE course_event_id = p_course_event_id)
    RETURNING 1
  ) SELECT count(*) INTO v_bills FROM del;

  -- (c) Enrollments. Clears BOTH the course_event_id RESTRICT and the
  --     package_id RESTRICT that would otherwise block course_packages' CASCADE.
  WITH del AS (
    DELETE FROM public.course_enrollments
     WHERE course_event_id = p_course_event_id
    RETURNING 1
  ) SELECT count(*) INTO v_enrollments FROM del;

  -- (d) The course. Everything still hanging off it is CASCADE or SET NULL now:
  --     applications, packages (+installments), forms (+sections/fields), sessions
  --     go; resource_reservations.course_session_id and any successor course's
  --     previous_course_event_id are nulled.
  DELETE FROM public.course_events WHERE id = p_course_event_id;

  RETURN jsonb_build_object(
    'course_title', v_title,
    'deleted', jsonb_build_object(
      'payments',     v_payments,
      'bills',        v_bills,
      'enrollments',  v_enrollments,
      'applications', v_apps,
      'packages',     v_packages,
      'forms',        v_forms,
      'sessions',     v_sessions
    )
  );
END;
$fn$;

-- CREATE OR REPLACE resets EXECUTE to PUBLIC, so re-state the grants explicitly
-- every time rather than assuming the previous ones carried over.
REVOKE ALL ON FUNCTION public.fn_course_delete_blockers(uuid) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.fn_course_delete_cascade(uuid)  FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fn_course_delete_blockers(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_course_delete_cascade(uuid)  TO authenticated;

COMMENT ON FUNCTION public.fn_course_delete_blockers(uuid) IS
  'Super-admin only. Counts everything a course delete would destroy, including money received. Read before confirming.';
COMMENT ON FUNCTION public.fn_course_delete_cascade(uuid) IS
  'Super-admin only. Deletes a course and its entire subtree in dependency order (payments -> bills -> enrollments -> course). Returns a receipt of what was removed.';


-- ---------------------------------------------------------------------------
-- fn_induction_session_feedback_detail — flat (learner x session) induction
-- feedback with full learner identity. Powers the "Session feedback" browser and
-- its XLSX export. Coordinator scope ONLY: deliberately narrower than
-- fn_induction_session_feedback_summary (which admits session speakers to the
-- averages), because these rows carry college email and mobile.
-- Added by 20260820103000_induction_session_feedback_detail.sql
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_induction_session_feedback_detail(
  p_event_id   UUID,
  p_session_id UUID DEFAULT NULL   -- NULL = every session in the induction
)
RETURNS TABLE (
  feedback_id       UUID,
  session_id        UUID,
  session_title     TEXT,
  day_number        INTEGER,
  session_start     TIMESTAMPTZ,
  learner_id        UUID,
  register_number   TEXT,
  roll_number       TEXT,
  learner_name      TEXT,
  gender            TEXT,
  student_email     TEXT,
  college_email     TEXT,
  student_mobile    TEXT,
  institution_name  TEXT,
  degree_name       TEXT,
  program_name      TEXT,
  department_name   TEXT,
  rating            INTEGER,
  comment           TEXT,
  capture_method    TEXT,
  is_self           BOOLEAN,
  submitted_by_name TEXT,
  submitted_at      TIMESTAMPTZ,
  updated_at        TIMESTAMPTZ
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE v_inst UUID;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'fn_induction_session_feedback_detail: not authenticated';
  END IF;

  SELECT ip.institution_id INTO v_inst
  FROM public.induction_programs ip WHERE ip.event_id = p_event_id;
  IF v_inst IS NULL THEN
    RAISE EXCEPTION 'fn_induction_session_feedback_detail: not an induction event';
  END IF;

  IF NOT (is_super_admin() OR is_admin()
          OR (user_has_permission('induction.view') AND role_has_institution_access(v_inst))
          OR public.fn_induction_is_event_coordinator(p_event_id)) THEN
    RAISE EXCEPTION 'fn_induction_session_feedback_detail: not authorized';
  END IF;

  RETURN QUERY
  SELECT
    f.id::uuid,
    f.session_id::uuid,
    s.title::text,
    s.day_number::integer,
    s.start_at::timestamptz,
    f.learner_id::uuid,
    lp.register_number::text,
    lp.roll_number::text,
    NULLIF(btrim(coalesce(lp.first_name,'') || ' ' || coalesce(lp.last_name,'')), '')::text,
    lp.gender::text,
    lp.student_email::text,
    lp.college_email::text,
    lp.student_mobile::text,
    i.name::text,
    d.degree_name::text,
    pr.program_name::text,
    dep.department_name::text,
    f.rating::integer,
    f.comment::text,
    f.capture_method::text,
    (f.submitted_by IS NULL)::boolean,
    sb.full_name::text,
    f.created_at::timestamptz,
    f.updated_at::timestamptz
  FROM public.event_session_feedback f
  LEFT JOIN public.event_sessions    s   ON s.id   = f.session_id
  LEFT JOIN public.learners_profiles lp  ON lp.id  = f.learner_id
  LEFT JOIN public.institutions      i   ON i.id   = lp.institution_id
  LEFT JOIN public.degrees           d   ON d.id   = lp.degree_id
  LEFT JOIN public.programs          pr  ON pr.id  = lp.program_id
  LEFT JOIN public.departments       dep ON dep.id = lp.department_id
  LEFT JOIN public.profiles          sb  ON sb.id  = f.submitted_by
  WHERE f.event_id = p_event_id
    AND (p_session_id IS NULL OR f.session_id = p_session_id)
  -- Freshers frequently have no register/roll number yet (they are assigned after
  -- admission closes), so name is a real tiebreaker here, not decoration.
  ORDER BY s.day_number NULLS LAST, s.session_order NULLS LAST, s.start_at NULLS LAST,
           lp.register_number NULLS LAST, lp.roll_number NULLS LAST,
           lp.first_name NULLS LAST, lp.last_name NULLS LAST;
END $$;

REVOKE EXECUTE ON FUNCTION public.fn_induction_session_feedback_detail(UUID, UUID) FROM anon, PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_induction_session_feedback_detail(UUID, UUID) TO authenticated;

COMMENT ON FUNCTION public.fn_induction_session_feedback_detail(UUID, UUID) IS
  'Flat (learner x session) induction feedback rows with full learner identity — powers the '
  '"Session feedback" browser and its XLSX export. Coordinator scope only (narrower than '
  'fn_induction_session_feedback_summary, which admits session speakers to the averages).';


-- ---------------------------------------------------------------------------
-- Learner gender -> profiles.gender (20260820140000)
-- Gender is captured on learners_profiles but was dropped at all three
-- learner->profile hand-offs (handle_new_user, auto_link_profile_to_approved_learner,
-- sync_learner_email_to_profile), leaving profiles.gender NULL for 940 learners.
-- Staff never had the hole: sync_staff_to_profiles writes gender = NEW.gender.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.sync_profile_gender_from_learner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_gender text;
BEGIN
  SELECT NULLIF(btrim(lp.gender), '') INTO v_gender
    FROM learners_profiles lp
   WHERE lp.id = NEW.learner_id;

  IF v_gender IS NULL THEN
    RETURN NULL;
  END IF;

  -- Sets gender only; the trigger is AFTER UPDATE **OF learner_id**, so this write
  -- cannot re-enter it. The WHEN clause (NEW.gender IS NULL) is a second guard.
  UPDATE profiles
     SET gender = v_gender
   WHERE id = NEW.id
     AND gender IS NULL;

  RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.sync_learner_gender_to_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_gender text := NULLIF(btrim(NEW.gender), '');
BEGIN
  IF v_gender IS NULL THEN
    RETURN NULL;
  END IF;

  -- Case-insensitive compare: a pure case difference is not a change, and would
  -- otherwise fire trigger_sync_user_update_webhook for nothing.
  UPDATE profiles p
     SET gender = v_gender
   WHERE p.learner_id = NEW.id
     AND lower(btrim(COALESCE(p.gender, ''))) IS DISTINCT FROM lower(v_gender);

  RETURN NULL;
END $function$;


-- ---------------------------------------------------------------------------
-- Gender canonicalisation for learners_profiles + profiles (20260820160000)
-- Canonical domain: Male | Female | Other. Every other gender column in the
-- schema keeps its own domain (staff male/female/bigender, admission_leads
-- male/female/other, admission_packages MALE/FEMALE, hostel/mess boys/girls).
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.normalize_gender(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 PARALLEL SAFE
AS $function$
  SELECT CASE lower(btrim(COALESCE(p_value, '')))
           WHEN 'male'    THEN 'Male'
           WHEN 'm'       THEN 'Male'
           WHEN 'female'  THEN 'Female'
           WHEN 'f'       THEN 'Female'
           WHEN 'other'   THEN 'Other'
           WHEN 'others'  THEN 'Other'
           WHEN 'o'       THEN 'Other'
           ELSE NULL
         END;
$function$;

CREATE OR REPLACE FUNCTION public.tg_normalize_learner_gender()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- '' stays '' (the NOT NULL "not captured" sentinel); recognised values become canonical.
  -- Unrecognised input passes through so learners_profiles_gender_check rejects it loudly.
  NEW.gender := COALESCE(public.normalize_gender(NEW.gender), NEW.gender);
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.tg_normalize_profile_gender()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- profiles.gender is nullable, so blank collapses to NULL rather than ''.
  NEW.gender := COALESCE(public.normalize_gender(NEW.gender), NULLIF(btrim(NEW.gender), ''));
  RETURN NEW;
END $function$;

-- ===========================================================================
-- HR Biometric import purge (super admin only)
-- Mirrored from supabase/migrations/20260820150000_biometric_import_purge_super_admin.sql
-- ===========================================================================
-- HR Attendance — super-admin-only purge of one imported biometric month.
--
-- WHY THIS EXISTS
-- ---------------
-- Re-importing the same month overwrites cleanly (the upsert is keyed on
-- employee_id,work_date), but there is no way to UNDO an import: a file loaded
-- against the wrong machine, or a month imported before the shift timings were
-- configured, leaves rows that no subsequent import touches, because the next
-- file simply does not contain those (employee, date) pairs.
--
-- THE DELETION UNIT IS (MACHINE, MONTH), NOT (STAFF INSTITUTION, MONTH)
-- ---------------------------------------------------------------------
-- Keyed on biometric_institution_id — the institution whose MACHINE produced
-- the file — never on institution_id, which is the staff member's own college.
-- The two genuinely differ: as of 2026-08-20 the Main Office machine's July
-- 2026 import holds 1,255 rows for 41 staff spread across SIX institutions.
-- Keying on institution_id would leave five colleges' rows behind on an "undo
-- Main Office July" and would delete Main Office staff whose punches came off a
-- different machine. The file is the unit of import, so the file is the unit of
-- undo.
--
-- source = 'biometric' is checked on every statement. Attendance entered by a
-- human, or arriving from any future source, is never in scope no matter what
-- biometric_institution_id happens to be set on the row.
--
-- CHILDREN: DETACHED, NOT DESTROYED
-- ----------------------------------
-- Two FKs point at hr_attendance_records(id), both ON DELETE NO ACTION, so a
-- plain DELETE raises 23503 the moment either table has a row:
--   hr_attendance_regularizations.attendance_record_id
--   hr_attendance_audit_log.attendance_record_id
-- Both columns are NULLABLE and both tables carry their own employee_id and
-- date, so the purge NULLs the pointer instead of deleting the child. That is
-- deliberate and is not laziness about the FK:
--   * a regularization is a STAFF MEMBER's request to correct a day. Undoing an
--     administrator's bad import must not silently destroy someone else's
--     pending request; it survives, unlinked, and a re-import gives it an
--     anchor again.
--   * an audit log that disappears when the audited row is deleted is not an
--     audit log.
-- Both tables are empty today (0 rows), which is exactly why this is worth
-- getting right now rather than after the first 23503 in production.
--
-- Exceptions ARE deleted. hr_attendance_exceptions has no source column and no
-- biometric_institution_id; the import stamps the machine into
-- raw_payload->>'machine_institution_id', which is the only handle there is.
-- Rows are matched on that plus exception_type='biometric_unresolved', so an
-- exception raised by anything else is out of scope.
--
-- NOT CHECKED (yet): hr_payroll_periods. It has institution_id, period_month,
-- status and locked_at, but zero rows and no FK to attendance, so any "is
-- payroll locked for this month" guard written today would be a guess about
-- semantics that do not exist yet. Add it here when payroll goes live.
--
-- ACCESS: super admin only, enforced INSIDE each function. SECURITY DEFINER
-- bypasses RLS, so the in-function guard is the real gate. Note that the
-- existing hr_attendance_records_delete policy is deliberately left alone: it
-- already permits is_admin() + hr.attendance.override for single-row
-- corrections, which is a different and legitimate act from wiping a month.

-- ---------------------------------------------------------------------------
-- 1. What has been imported. Drives the picker.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_biometric_import_batches()
RETURNS TABLE (
  machine_institution_id  uuid,
  machine_name            text,
  machine_code            text,
  month_start             date,
  record_count            bigint,
  staff_count             bigint,
  staff_institution_count bigint,
  reconciled_count        bigint,
  regularization_count    bigint,
  exception_count         bigint,
  open_exception_count    bigint,
  first_work_date         date,
  last_work_date          date,
  last_imported_at        timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $fn$
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Only a super admin may manage biometric imports'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH recs AS (
    SELECT r.biometric_institution_id                          AS mid,
           date_trunc('month', r.work_date)::date              AS m,
           count(*)::bigint                                    AS n,
           count(DISTINCT r.employee_id)::bigint               AS staff,
           count(DISTINCT r.institution_id)::bigint            AS insts,
           count(*) FILTER (WHERE r.reconciled_by IS NOT NULL)::bigint AS reconciled,
           min(r.work_date)                                    AS d0,
           max(r.work_date)                                    AS d1,
           max(r.updated_at)                                   AS imported
      FROM public.hr_attendance_records r
     WHERE r.source = 'biometric'
       AND r.biometric_institution_id IS NOT NULL
     GROUP BY 1, 2
  ),
  regs AS (
    SELECT r.biometric_institution_id             AS mid,
           date_trunc('month', r.work_date)::date AS m,
           count(*)::bigint                       AS n
      FROM public.hr_attendance_regularizations g
      JOIN public.hr_attendance_records r ON r.id = g.attendance_record_id
     WHERE r.source = 'biometric'
       AND r.biometric_institution_id IS NOT NULL
     GROUP BY 1, 2
  ),
  excs AS (
    -- The uuid cast is guarded: one malformed payload would otherwise take the
    -- whole listing down with 22P02.
    SELECT (e.raw_payload ->> 'machine_institution_id')::uuid   AS mid,
           date_trunc('month', e.exception_date)::date          AS m,
           count(*)::bigint                                     AS n,
           count(*) FILTER (WHERE e.resolution_status = 'open')::bigint AS open_n
      FROM public.hr_attendance_exceptions e
     WHERE e.exception_type = 'biometric_unresolved'
       AND e.raw_payload ->> 'machine_institution_id'
           ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     GROUP BY 1, 2
  )
  SELECT recs.mid,
         i.name::text,
         i.counselling_code::text,
         recs.m,
         recs.n,
         recs.staff,
         recs.insts,
         recs.reconciled,
         COALESCE(regs.n, 0)::bigint,
         COALESCE(excs.n, 0)::bigint,
         COALESCE(excs.open_n, 0)::bigint,
         recs.d0,
         recs.d1,
         recs.imported
    FROM recs
    LEFT JOIN regs ON regs.mid = recs.mid AND regs.m = recs.m
    LEFT JOIN excs ON excs.mid = recs.mid AND excs.m = recs.m
    LEFT JOIN public.institutions i ON i.id = recs.mid
   ORDER BY recs.m DESC, i.name;
END;
$fn$;

-- ---------------------------------------------------------------------------
-- 2. Blast-radius preview. Read this before offering the confirm.
-- ---------------------------------------------------------------------------
-- Counted inside a SECURITY DEFINER function for the same reason as the course
-- cascade: the child tables are RLS-gated, so a client-side count would report
-- "nothing will be lost" to anyone who cannot see the rows.
CREATE OR REPLACE FUNCTION public.fn_biometric_import_purge_preview(
  p_machine_id uuid,
  p_month      date
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $fn$
DECLARE
  v_from date;
  v_to   date;
  v_name text;
  v_out  jsonb;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Only a super admin may delete an imported biometric month'
      USING ERRCODE = '42501';
  END IF;

  IF p_machine_id IS NULL OR p_month IS NULL THEN
    RAISE EXCEPTION 'Machine institution and month are both required'
      USING ERRCODE = '22023';
  END IF;

  v_from := date_trunc('month', p_month)::date;
  v_to   := (v_from + interval '1 month')::date;  -- exclusive

  SELECT i.name::text INTO v_name FROM public.institutions i WHERE i.id = p_machine_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Institution not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT jsonb_build_object(
    'machine_name', v_name,
    'month_start',  v_from,
    'month_label',  to_char(v_from, 'FMMonth YYYY'),

    'records', (SELECT count(*) FROM public.hr_attendance_records r
                 WHERE r.source = 'biometric'
                   AND r.biometric_institution_id = p_machine_id
                   AND r.work_date >= v_from AND r.work_date < v_to),

    'staff', (SELECT count(DISTINCT r.employee_id) FROM public.hr_attendance_records r
               WHERE r.source = 'biometric'
                 AND r.biometric_institution_id = p_machine_id
                 AND r.work_date >= v_from AND r.work_date < v_to),

    -- One machine routinely serves several colleges; say how many are affected
    -- so "delete Main Office July" is not mistaken for a Main-Office-only act.
    'staff_institutions', (SELECT count(DISTINCT r.institution_id)
                             FROM public.hr_attendance_records r
                            WHERE r.source = 'biometric'
                              AND r.biometric_institution_id = p_machine_id
                              AND r.work_date >= v_from AND r.work_date < v_to),

    'by_status', (SELECT COALESCE(jsonb_object_agg(t.code, x.n), '{}'::jsonb)
                    FROM (SELECT r.status_type_id AS sid, count(*) AS n
                            FROM public.hr_attendance_records r
                           WHERE r.source = 'biometric'
                             AND r.biometric_institution_id = p_machine_id
                             AND r.work_date >= v_from AND r.work_date < v_to
                           GROUP BY 1) x
                    JOIN public.hr_attendance_status_types t ON t.id = x.sid),

    -- Human work. Not a blocker, but the confirm should say it out loud.
    'reconciled_records', (SELECT count(*) FROM public.hr_attendance_records r
                            WHERE r.source = 'biometric'
                              AND r.biometric_institution_id = p_machine_id
                              AND r.work_date >= v_from AND r.work_date < v_to
                              AND r.reconciled_by IS NOT NULL),

    'regularizations_unlinked', (SELECT count(*)
                                   FROM public.hr_attendance_regularizations g
                                   JOIN public.hr_attendance_records r ON r.id = g.attendance_record_id
                                  WHERE r.source = 'biometric'
                                    AND r.biometric_institution_id = p_machine_id
                                    AND r.work_date >= v_from AND r.work_date < v_to),

    'audit_rows_unlinked', (SELECT count(*)
                              FROM public.hr_attendance_audit_log a
                              JOIN public.hr_attendance_records r ON r.id = a.attendance_record_id
                             WHERE r.source = 'biometric'
                               AND r.biometric_institution_id = p_machine_id
                               AND r.work_date >= v_from AND r.work_date < v_to),

    'exceptions', (SELECT count(*) FROM public.hr_attendance_exceptions e
                    WHERE e.exception_type = 'biometric_unresolved'
                      AND e.exception_date >= v_from AND e.exception_date < v_to
                      AND e.raw_payload ->> 'machine_institution_id' = p_machine_id::text),

    'resolved_exceptions', (SELECT count(*) FROM public.hr_attendance_exceptions e
                             WHERE e.exception_type = 'biometric_unresolved'
                               AND e.exception_date >= v_from AND e.exception_date < v_to
                               AND e.raw_payload ->> 'machine_institution_id' = p_machine_id::text
                               AND e.resolution_status IS DISTINCT FROM 'open')
  ) INTO v_out;

  RETURN v_out;
END;
$fn$;

-- ---------------------------------------------------------------------------
-- 3. The purge itself.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_biometric_import_purge(
  p_machine_id uuid,
  p_month      date
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $fn$
DECLARE
  v_from    date;
  v_to      date;
  v_name    text;
  v_records bigint := 0;
  v_regs    bigint := 0;
  v_audit   bigint := 0;
  v_excs    bigint := 0;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Only a super admin may delete an imported biometric month'
      USING ERRCODE = '42501';
  END IF;

  IF p_machine_id IS NULL OR p_month IS NULL THEN
    RAISE EXCEPTION 'Machine institution and month are both required'
      USING ERRCODE = '22023';
  END IF;

  v_from := date_trunc('month', p_month)::date;
  v_to   := (v_from + interval '1 month')::date;

  SELECT i.name::text INTO v_name FROM public.institutions i WHERE i.id = p_machine_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Institution not found' USING ERRCODE = 'P0002';
  END IF;

  -- Order matters. (a) and (b) clear the two NO ACTION FKs that would otherwise
  -- make (c) raise 23503; both run BEFORE the delete, so the subquery still
  -- resolves the rows about to go.

  -- (a) A staff member's correction request outlives the import it was filed
  --     against. Detach, never delete.
  WITH upd AS (
    UPDATE public.hr_attendance_regularizations g
       SET attendance_record_id = NULL,
           updated_at = now()
     WHERE g.attendance_record_id IN (
             SELECT r.id FROM public.hr_attendance_records r
              WHERE r.source = 'biometric'
                AND r.biometric_institution_id = p_machine_id
                AND r.work_date >= v_from AND r.work_date < v_to)
    RETURNING 1
  ) SELECT count(*) INTO v_regs FROM upd;

  -- (b) Same for the audit trail — it keeps its own employee_id, actor and
  --     before/after states, so it stays readable without the row it describes.
  WITH upd AS (
    UPDATE public.hr_attendance_audit_log a
       SET attendance_record_id = NULL
     WHERE a.attendance_record_id IN (
             SELECT r.id FROM public.hr_attendance_records r
              WHERE r.source = 'biometric'
                AND r.biometric_institution_id = p_machine_id
                AND r.work_date >= v_from AND r.work_date < v_to)
    RETURNING 1
  ) SELECT count(*) INTO v_audit FROM upd;

  -- (c) The attendance itself.
  WITH del AS (
    DELETE FROM public.hr_attendance_records r
     WHERE r.source = 'biometric'
       AND r.biometric_institution_id = p_machine_id
       AND r.work_date >= v_from AND r.work_date < v_to
    RETURNING 1
  ) SELECT count(*) INTO v_records FROM del;

  -- (d) The unresolved-day exceptions raised by the same import.
  WITH del AS (
    DELETE FROM public.hr_attendance_exceptions e
     WHERE e.exception_type = 'biometric_unresolved'
       AND e.exception_date >= v_from AND e.exception_date < v_to
       AND e.raw_payload ->> 'machine_institution_id' = p_machine_id::text
    RETURNING 1
  ) SELECT count(*) INTO v_excs FROM del;

  RETURN jsonb_build_object(
    'machine_name', v_name,
    'month_start',  v_from,
    'month_label',  to_char(v_from, 'FMMonth YYYY'),
    'deleted', jsonb_build_object(
      'records',    v_records,
      'exceptions', v_excs
    ),
    'unlinked', jsonb_build_object(
      'regularizations', v_regs,
      'audit_rows',      v_audit
    )
  );
END;
$fn$;

-- CREATE OR REPLACE resets EXECUTE to PUBLIC, so re-state every grant rather
-- than assuming the previous ones carried over.
REVOKE ALL ON FUNCTION public.fn_biometric_import_batches()                        FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.fn_biometric_import_purge_preview(uuid, date)        FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.fn_biometric_import_purge(uuid, date)                FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fn_biometric_import_batches()                     TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_biometric_import_purge_preview(uuid, date)     TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_biometric_import_purge(uuid, date)             TO authenticated;

COMMENT ON FUNCTION public.fn_biometric_import_batches() IS
  'Super-admin only. Every imported biometric month, grouped by the MACHINE institution that produced the file.';
COMMENT ON FUNCTION public.fn_biometric_import_purge_preview(uuid, date) IS
  'Super-admin only. Counts everything purging one (machine, month) import would remove or detach. Read before confirming.';
COMMENT ON FUNCTION public.fn_biometric_import_purge(uuid, date) IS
  'Super-admin only. Deletes one imported biometric month for one machine, detaching regularizations and audit rows first. Returns a receipt.';

-- ---------------------------------------------------------------------------
-- Staff name canonicalisation (migration 20260910120000)
-- ---------------------------------------------------------------------------
-- Canonical form: trim ends, collapse internal whitespace runs to one space,
-- uppercase. IMMUTABLE so the staff_*_name_canonical CHECK constraints can
-- call it.
CREATE OR REPLACE FUNCTION public.fn_canonical_staff_name(p_name text)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path TO 'public'
AS $$
  SELECT CASE
           WHEN p_name IS NULL THEN NULL
           ELSE upper(regexp_replace(btrim(p_name), '\s+', ' ', 'g'))
         END;
$$;

COMMENT ON FUNCTION public.fn_canonical_staff_name(text) IS
  'Canonical staff-name form: trim ends, collapse internal whitespace runs to a single space, uppercase. IMMUTABLE so CHECK constraints may call it.';

CREATE OR REPLACE FUNCTION public.fn_normalize_staff_names()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  NEW.first_name := public.fn_canonical_staff_name(NEW.first_name);
  NEW.last_name  := public.fn_canonical_staff_name(NEW.last_name);
  RETURN NEW;
END
$$;

-- ===========================================================================
-- HR Leave approval queue (identity + institution + cross-org scope)
-- Mirrored from supabase/migrations/20260820160000_hr_leave_approval_queue.sql
-- ===========================================================================
-- HR Leave — one approval queue carrying WHO is asking.
--
-- WHY THIS EXISTS
-- ---------------
-- The Approvals tab read /api/hr/leave/applications, which embeds only
-- hr_leave_types. Three consequences, all visible on the screen:
--
-- 1. NO IDENTITY. The table showed leave type, dates, days and status — never
--    the staff member. An approver decided on anonymous rows. Adding a staff
--    embed on the client does not fix it: staff_select_scope_aware requires
--    is_super_admin() OR staff.view within a module scope, and hr.leave.approve
--    grants neither, so the embed returns NULL for exactly the approvers who
--    need the name. Blank instead of missing is worse than either. Resolving it
--    in a SECURITY DEFINER function that mirrors the hla_select predicate is
--    the only way the name is there for every legitimate approver.
--
-- 2. NO INSTITUTION. hr_leave_applications has no institution_id at all; the
--    college comes from staff.institution_id, one join further out — and staff
--    is the table the approver cannot read.
--
-- 3. SUPER ADMINS SAW NOTHING, OR ONE ORG. The page passed the caller's own
--    hr_organization_id and the hook was enabled: !!hrOrgId, so a super admin
--    with no HR employee record never issued the query, and one with a record
--    saw a single organisation. The database was never the constraint —
--    hla_select, hla_update, hr_can_approve_leave() and
--    hr_trig_leave_enforce_approver all short-circuit TRUE on is_super_admin().
--    The gap was entirely client-side scoping, and it is fixed here by scoping
--    in one place that copies the RLS predicate rather than guessing at it.
--
-- Also returns request_category, so the tab can separate Leave from Short Time
-- Off. They share hr_leave_applications and differ only by the type's category,
-- and the old queue filtered on neither — so 240 pending short-time-off requests
-- were being rendered in the "Leave Requests" table with a day count and no
-- times, against 206 real leave requests.
--
-- And it returns EVERY pending row. The REST route defaults to pageSize 50 and
-- the page never overrode it, so the queue silently stopped at 50 of 446.
--
-- SCOPE PREDICATE — copied from hla_select, deliberately, not invented:
--     is_super_admin()
--  OR (hr.leave.approve AND hr_organization_id IN fn_my_hr_organization_ids())
--  OR fn_is_designated_leave_approver(id)
-- A DEFINER function bypasses RLS, so drifting from the policy here would hand
-- out rows the table itself refuses. The hr.leave.approve test is already made
-- by the hr_can_approve_leave() gate at the top.

CREATE OR REPLACE FUNCTION public.hr_leave_approval_queue()
RETURNS TABLE (
  id                   uuid,
  employee_id          uuid,
  staff_name           text,
  staff_code           text,
  institution_id       uuid,
  institution_name     text,
  hr_organization_id   uuid,
  hr_organization_name text,
  leave_type_id        uuid,
  leave_type_name      text,
  leave_type_code      text,
  request_category     text,
  start_date           date,
  end_date             date,
  start_time           time without time zone,
  end_time             time without time zone,
  duration_type        text,
  duration_minutes     integer,
  total_days           numeric,
  reason               text,
  is_emergency         boolean,
  status               text,
  created_at           timestamptz,
  is_own               boolean,
  waiting_on_me        boolean
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $fn$
DECLARE
  v_uid  uuid := auth.uid();
  v_sa   boolean;
  v_orgs uuid[];
  v_mine uuid[];
BEGIN
  IF v_uid IS NULL THEN
    RETURN;
  END IF;

  IF NOT public.hr_can_approve_leave() THEN
    RAISE EXCEPTION 'You do not have permission to approve leave'
      USING ERRCODE = '42501';
  END IF;

  v_sa   := public.is_super_admin();
  -- COALESCE to an empty array so `= ANY(...)` stays false rather than NULL for
  -- an approver with no HR organisation mapping.
  v_orgs := COALESCE(public.fn_my_hr_organization_ids(), ARRAY[]::uuid[]);
  v_mine := COALESCE(public.fn_my_staff_ids(), ARRAY[]::uuid[]);

  RETURN QUERY
  SELECT
    a.id,
    a.employee_id,
    NULLIF(btrim(concat_ws(' ', s.first_name, s.last_name)), '')::text,
    NULLIF(btrim(s.staff_id), '')::text,
    s.institution_id,
    i.name::text,
    a.hr_organization_id,
    o.name::text,
    a.leave_type_id,
    lt.leave_type_name::text,
    lt.leave_type_code::text,
    -- A missing type is treated as 'leave' rather than dropped: matching no
    -- category would make the row vanish from EVERY tab, which is the silent
    -- hiding the service layer's LEFT joins exist to prevent.
    COALESCE(lt.request_category, 'leave')::text,
    a.start_date,
    a.end_date,
    a.start_time,
    a.end_time,
    a.duration_type::text,
    a.duration_minutes,
    a.total_days,
    a.reason,
    a.is_emergency,
    a.status::text,
    a.created_at,
    (a.employee_id = ANY (v_mine)),
    (
      -- Waiting on ME: the same three tests as hr_trig_leave_enforce_approver,
      -- so the badge cannot promise a decision the trigger will refuse.
      --
      -- Unlike hr_leave_my_approval_queue this does NOT return true for every
      -- row just because the caller is a super admin. A super admin CAN decide
      -- anything — the trigger says so — but a filter that selects the entire
      -- queue tells them nothing, and this one is a filter, not a permission.
      a.employee_id <> ALL (v_mine)
      AND (
        st.step IS NULL
        OR CASE
             WHEN NULLIF(st.step ->> 'approver_user_id', '') IS NOT NULL
               THEN (st.step ->> 'approver_user_id')::uuid = v_uid
             WHEN NULLIF(st.step ->> 'approver_role', '') IS NOT NULL
               THEN NOT EXISTS (
                      SELECT 1 FROM public.custom_roles cr
                       WHERE cr.role_key = st.step ->> 'approver_role' AND cr.is_active
                    )
                    OR EXISTS (
                      SELECT 1
                        FROM public.user_roles ur
                        JOIN public.custom_roles cr2 ON cr2.id = ur.role_id
                       WHERE ur.user_id = v_uid
                         AND cr2.role_key = st.step ->> 'approver_role'
                    )
             ELSE true
           END
      )
    )
  FROM public.hr_leave_applications a
  LEFT JOIN public.hr_leave_types   lt ON lt.id = a.leave_type_id
  LEFT JOIN public.staff            s  ON s.id  = a.employee_id
  LEFT JOIN public.institutions     i  ON i.id  = s.institution_id
  LEFT JOIN public.hr_organizations o  ON o.id  = a.hr_organization_id
  CROSS JOIN LATERAL (SELECT a.approval_chain -> a.current_step AS step) st
  WHERE a.status IN ('pending', 'escalated')
    AND (
      v_sa
      OR a.hr_organization_id = ANY (v_orgs)
      OR public.fn_is_designated_leave_approver(a.id)
    )
  ORDER BY a.created_at DESC;
END;
$fn$;

-- CREATE OR REPLACE resets EXECUTE to PUBLIC, so re-state the grants every time.
REVOKE ALL ON FUNCTION public.hr_leave_approval_queue() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.hr_leave_approval_queue() TO authenticated;

COMMENT ON FUNCTION public.hr_leave_approval_queue() IS
  'Leave + short-time-off awaiting a decision, with the requester''s name, staff code and institution. Scope copies hla_select; super admins see every organisation.';

-- ===========================================================================
-- HR Leave approval queue — super-admin self-approval (adds can_decide)
-- Mirrored from supabase/migrations/20260820170000_hr_leave_queue_super_admin_self_approval.sql
-- Replays AFTER the 20260820160000 body above; it DROPs and recreates.
-- ===========================================================================
-- HR Leave — a super admin may decide their OWN request.
--
-- The database already allowed it. hr_trig_leave_enforce_approver returns NEW
-- on is_super_admin() BEFORE it reaches the self-approval check, and hla_update
-- permits is_super_admin() outright. Two layers above the database disagreed:
--
--   * LeaveService.assertCanDecide() threw 'You cannot decide on your own leave
--     application.' for everyone, unconditionally (fixed in the service);
--   * hr_leave_approval_queue() reported is_own and a waiting_on_me that
--     excluded own rows, so the tab hid the buttons before the click.
--
-- This adds can_decide, which is what the UI should gate on: is_own stays as a
-- display fact ("this is yours"), can_decide answers "will the trigger let me".
-- Keeping them separate matters — a super admin's own row is BOTH.
--
-- RETURNS TABLE gains a column, and CREATE OR REPLACE cannot change a return
-- type, so this DROPs first. DROP discards EXECUTE grants (they revert to
-- PUBLIC on recreate), which is why every grant is re-stated below rather than
-- assumed to have carried over.

DROP FUNCTION IF EXISTS public.hr_leave_approval_queue();

CREATE FUNCTION public.hr_leave_approval_queue()
RETURNS TABLE (
  id                   uuid,
  employee_id          uuid,
  staff_name           text,
  staff_code           text,
  institution_id       uuid,
  institution_name     text,
  hr_organization_id   uuid,
  hr_organization_name text,
  leave_type_id        uuid,
  leave_type_name      text,
  leave_type_code      text,
  request_category     text,
  start_date           date,
  end_date             date,
  start_time           time without time zone,
  end_time             time without time zone,
  duration_type        text,
  duration_minutes     integer,
  total_days           numeric,
  reason               text,
  is_emergency         boolean,
  status               text,
  created_at           timestamptz,
  is_own               boolean,
  can_decide           boolean,
  waiting_on_me        boolean
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $fn$
DECLARE
  v_uid  uuid := auth.uid();
  v_sa   boolean;
  v_orgs uuid[];
  v_mine uuid[];
BEGIN
  IF v_uid IS NULL THEN
    RETURN;
  END IF;

  IF NOT public.hr_can_approve_leave() THEN
    RAISE EXCEPTION 'You do not have permission to approve leave'
      USING ERRCODE = '42501';
  END IF;

  v_sa   := public.is_super_admin();
  -- COALESCE to an empty array so `= ANY(...)` stays false rather than NULL for
  -- an approver with no HR organisation mapping.
  v_orgs := COALESCE(public.fn_my_hr_organization_ids(), ARRAY[]::uuid[]);
  v_mine := COALESCE(public.fn_my_staff_ids(), ARRAY[]::uuid[]);

  RETURN QUERY
  SELECT
    a.id,
    a.employee_id,
    NULLIF(btrim(concat_ws(' ', s.first_name, s.last_name)), '')::text,
    NULLIF(btrim(s.staff_id), '')::text,
    s.institution_id,
    i.name::text,
    a.hr_organization_id,
    o.name::text,
    a.leave_type_id,
    lt.leave_type_name::text,
    lt.leave_type_code::text,
    -- A missing type is treated as 'leave' rather than dropped: matching no
    -- category would make the row vanish from EVERY tab.
    COALESCE(lt.request_category, 'leave')::text,
    a.start_date,
    a.end_date,
    a.start_time,
    a.end_time,
    a.duration_type::text,
    a.duration_minutes,
    a.total_days,
    a.reason,
    a.is_emergency,
    a.status::text,
    a.created_at,
    (a.employee_id = ANY (v_mine))               AS is_own,
    -- Exactly what hr_trig_leave_enforce_approver enforces: super admins are
    -- exempt from the self-approval bar, everyone else is not.
    (v_sa OR a.employee_id <> ALL (v_mine))      AS can_decide,
    (
      -- Waiting on ME: the same three tests as the trigger, so the badge cannot
      -- promise a decision the trigger will refuse.
      --
      -- Unlike hr_leave_my_approval_queue this does NOT return true for every
      -- row just because the caller is a super admin. A super admin CAN decide
      -- anything, but a filter that selects the entire queue tells them nothing
      -- — this is a filter, not a permission.
      (v_sa OR a.employee_id <> ALL (v_mine))
      AND (
        st.step IS NULL
        OR CASE
             WHEN NULLIF(st.step ->> 'approver_user_id', '') IS NOT NULL
               THEN (st.step ->> 'approver_user_id')::uuid = v_uid
             WHEN NULLIF(st.step ->> 'approver_role', '') IS NOT NULL
               THEN NOT EXISTS (
                      SELECT 1 FROM public.custom_roles cr
                       WHERE cr.role_key = st.step ->> 'approver_role' AND cr.is_active
                    )
                    OR EXISTS (
                      SELECT 1
                        FROM public.user_roles ur
                        JOIN public.custom_roles cr2 ON cr2.id = ur.role_id
                       WHERE ur.user_id = v_uid
                         AND cr2.role_key = st.step ->> 'approver_role'
                    )
             ELSE true
           END
      )
    )                                            AS waiting_on_me
  FROM public.hr_leave_applications a
  LEFT JOIN public.hr_leave_types   lt ON lt.id = a.leave_type_id
  LEFT JOIN public.staff            s  ON s.id  = a.employee_id
  LEFT JOIN public.institutions     i  ON i.id  = s.institution_id
  LEFT JOIN public.hr_organizations o  ON o.id  = a.hr_organization_id
  CROSS JOIN LATERAL (SELECT a.approval_chain -> a.current_step AS step) st
  WHERE a.status IN ('pending', 'escalated')
    -- Scope copied from hla_select. A DEFINER function bypasses RLS, so drifting
    -- from the policy here would hand out rows the table itself refuses.
    AND (
      v_sa
      OR a.hr_organization_id = ANY (v_orgs)
      OR public.fn_is_designated_leave_approver(a.id)
    )
  ORDER BY a.created_at DESC;
END;
$fn$;

REVOKE ALL ON FUNCTION public.hr_leave_approval_queue() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.hr_leave_approval_queue() TO authenticated;

COMMENT ON FUNCTION public.hr_leave_approval_queue() IS
  'Leave + short-time-off awaiting a decision, with the requester''s name, staff code and institution. Scope copies hla_select; super admins see every organisation and may decide their own requests (can_decide).';

-- ===========================================================================
-- HR Leave day calculation — weekends from hr_shift_timings, not ISODOW 6/7
-- Mirrored from supabase/migrations/20260820180000_hr_leave_days_respect_shift_timings.sql
-- ===========================================================================
-- HR Leave — stop charging a two-day request as one.
--
-- THE BUG
-- -------
-- Casual Leave 17/07/2026 -> 18/07/2026 stored total_days = 1. 17 Jul is a
-- Friday, 18 Jul is a Saturday, and hr_calc_leave_days skipped it:
--
--     IF p_skip_weekends AND EXTRACT(ISODOW FROM cur) IN (6, 7) THEN NULL;
--
-- ISODOW 6 is Saturday. The rule was hardcoded to a Mon-Fri week that this
-- organisation does not work. hr_shift_timings — the table the attendance
-- engine has always used — says otherwise for every one of the 14 configured
-- institutions:
--
--     day_of_week 1..5  is_working_day = true
--     day_of_week 6     is_working_day = true   (Saturday IS a working day)
--                       second_saturday_holiday = true for 4 institutions only
--     day_of_week 7     is_working_day = false
--
-- So leave and attendance disagreed about what a non-working day is. Biometric
-- attendance marks a plain Saturday PRESENT/ABSENT off the configured timing,
-- while leave silently refused to charge for it. Measured on the current data:
-- 39 of 174 full-day applications were under-counted, 39 leave days in total.
-- All 39 were still pending, so no balance had consumed the wrong number — see
-- the backfill note at the bottom.
--
-- THE FIX
-- -------
-- Ask the same configuration the attendance engine asks, per staff member per
-- date, instead of guessing from the day number. That also makes the four
-- institutions with second_saturday_holiday correct for free — previously every
-- Saturday was skipped everywhere, so the distinction could not be expressed.
--
-- WHY NOT CALL fn_resolve_shift_timing DIRECTLY
-- ----------------------------------------------
-- It raises 42501 unless the caller is a super admin, an admin, the staff
-- member themselves, or holds hr.shift_timings.view. Calling it from a BEFORE
-- INSERT trigger would make leave submission depend on a shift-timing
-- permission — an HR officer applying on behalf of someone else would be
-- refused outright, and a service-role context (auth.uid() IS NULL) would fail
-- every time. hr_is_working_day below carries the same resolution with no
-- authorisation gate, which is safe because it returns a single boolean about
-- an institution's working calendar and nothing about the staff member.

-- ---------------------------------------------------------------------------
-- 1. Is this a working day for this staff member?
-- ---------------------------------------------------------------------------
-- Resolution copied from fn_resolve_shift_timing: same institution + ISO
-- day_of_week + effective window + staff_scope precedence (category beats
-- teaching/non_teaching), same second-Saturday rule (ISODOW 6 falling on day
-- 8..14 of the month).
--
-- Returns NULL — not false — when nothing is configured, so the caller can tell
-- "no rule" apart from "rest day" and pick its own fallback.
CREATE OR REPLACE FUNCTION public.hr_is_working_day(p_staff_id uuid, p_date date)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_institution_id uuid;
  v_category_id    uuid;
  v_is_teaching    boolean;
  v_gender         text;
  v_pattern_id     uuid;
  v_dow            smallint;
  v_second_sat     boolean;
  v_working        boolean;
BEGIN
  IF p_staff_id IS NULL OR p_date IS NULL THEN RETURN NULL; END IF;

  SELECT s.institution_id, s.category_id, ec.is_teaching, s.gender
    INTO v_institution_id, v_category_id, v_is_teaching, v_gender
  FROM public.staff s
  JOIN public.employment_categories ec ON ec.id = s.category_id
  WHERE s.id = p_staff_id;

  IF v_institution_id IS NULL THEN RETURN NULL; END IF;

  v_pattern_id := public.fn_staff_work_pattern_id(p_staff_id, p_date);
  v_dow        := EXTRACT(ISODOW FROM p_date)::smallint;
  v_second_sat := (v_dow = 6 AND EXTRACT(DAY FROM p_date) BETWEEN 8 AND 14);

  SELECT CASE WHEN (v_second_sat AND t.second_saturday_holiday) THEN false
              ELSE t.is_working_day END
    INTO v_working
  FROM public.fn_shift_timing_pick(
         v_institution_id, v_category_id, v_is_teaching, v_gender, v_dow, p_date, v_pattern_id) t;

  RETURN v_working;
END;
$function$;

REVOKE ALL ON FUNCTION public.hr_is_working_day(uuid, date) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.hr_is_working_day(uuid, date) TO authenticated, service_role;

COMMENT ON FUNCTION public.hr_is_working_day(uuid, date) IS
  'Working-day lookup from hr_shift_timings for one staff member on one date, second-Saturday rule included. NULL when no timing is configured. Ungated on purpose — it returns a calendar boolean, not staff data — so leave calculation never depends on hr.shift_timings.view.';

-- ---------------------------------------------------------------------------
-- 2. hr_calc_leave_days learns who the leave is for.
-- ---------------------------------------------------------------------------
-- The signature gains p_employee_id. A defaulted 7th argument cannot simply be
-- added, because the existing 6-argument function would still match every
-- existing call and Postgres would report the pair as ambiguous — so the old
-- one is dropped first. DROP discards EXECUTE grants, hence the explicit
-- re-grant below.
DROP FUNCTION IF EXISTS public.hr_calc_leave_days(date, date, character varying, boolean, boolean, uuid);

CREATE FUNCTION public.hr_calc_leave_days(
  p_start          date,
  p_end            date,
  p_duration       character varying,
  p_skip_weekends  boolean,
  p_skip_holidays  boolean,
  p_hr_org         uuid,
  p_employee_id    uuid DEFAULT NULL
)
RETURNS numeric
LANGUAGE plpgsql
STABLE
AS $fn$
DECLARE
  days_count numeric := 0;
  cur        date := p_start;
  inst_id    uuid;
  v_working  boolean;
BEGIN
  -- Resolve institution for holiday lookup
  SELECT institution_id INTO inst_id FROM hr_organizations WHERE id = p_hr_org;

  -- Fractional types return immediately (decision #5)
  IF p_duration = 'hourly' THEN RETURN 0.125; END IF;
  IF p_duration IN ('first_half', 'second_half') THEN RETURN 0.5; END IF;

  -- Full-day loop: iterate date range
  WHILE cur <= p_end LOOP
    v_working := NULL;
    IF p_skip_weekends THEN
      v_working := public.hr_is_working_day(p_employee_id, cur);
      IF v_working IS NULL THEN
        -- No configured timing, or no employee passed. Fall back to SUNDAY
        -- ONLY, not Sat+Sun: every institution that has been configured marks
        -- day_of_week 6 as a working day, so treating Saturday as rest would
        -- reintroduce the very bug this migration fixes for anyone whose
        -- timings are not set up yet.
        v_working := EXTRACT(ISODOW FROM cur) <> 7;
      END IF;
    END IF;

    IF p_skip_weekends AND NOT v_working THEN
      NULL;
    -- Skip institutional holidays (institution_leaves) OR global calendar holidays
    ELSIF p_skip_holidays AND (
      (inst_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM institution_leaves
        WHERE institution_id = inst_id
          AND cur BETWEEN start_date AND end_date
      ))
      OR EXISTS (
        SELECT 1 FROM calendar_entries ce
        WHERE ce.kind = 'holiday' AND ce.is_active = true AND ce.blocks_attendance = true
          AND cur BETWEEN ce.start_at::date AND ce.end_at::date
          AND (ce.scope_institution_ids IS NULL OR (inst_id IS NOT NULL AND inst_id = ANY(ce.scope_institution_ids)))
      )
    ) THEN
      NULL;
    ELSE
      days_count := days_count + 1;
    END IF;
    cur := cur + 1;
  END LOOP;

  RETURN days_count;
END;
$fn$;

REVOKE ALL ON FUNCTION public.hr_calc_leave_days(date, date, character varying, boolean, boolean, uuid, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.hr_calc_leave_days(date, date, character varying, boolean, boolean, uuid, uuid) TO authenticated, service_role;

COMMENT ON FUNCTION public.hr_calc_leave_days(date, date, character varying, boolean, boolean, uuid, uuid) IS
  'Chargeable days for a leave request. Weekends come from hr_shift_timings via hr_is_working_day when p_employee_id is given, so Saturday counts wherever the institution works it; Sunday-only fallback otherwise.';

-- ---------------------------------------------------------------------------
-- 3. Every caller now passes the employee. Without this the new parameter
--    defaults to NULL and the fallback silently applies to everyone.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.hr_trig_populate_total_days()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_skip_weekends bool;
  v_skip_holidays bool;
BEGIN
  SELECT skip_weekends, skip_holidays
    INTO v_skip_weekends, v_skip_holidays
    FROM public.hr_leave_types
   WHERE id = NEW.leave_type_id;

  NEW.total_days := public.hr_calc_leave_days(
    NEW.start_date,
    NEW.end_date,
    NEW.duration_type,
    COALESCE(v_skip_weekends, true),
    COALESCE(v_skip_holidays, true),
    NEW.hr_organization_id,
    NEW.employee_id
  );

  -- Minutes only mean something for an hourly request with both bounds.
  IF NEW.duration_type = 'hourly'
     AND NEW.start_time IS NOT NULL
     AND NEW.end_time IS NOT NULL THEN
    NEW.duration_minutes :=
      GREATEST(0, EXTRACT(EPOCH FROM (NEW.end_time - NEW.start_time))::integer / 60);
  ELSE
    NEW.duration_minutes := NULL;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.hr_trig_leave_enforce_period_cap()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  t record;
  w record;
  v_this numeric;
  v_used numeric := 0;
BEGIN
  IF NEW.status NOT IN ('pending','approved','escalated') THEN
    RETURN NEW;
  END IF;

  SELECT request_category, leave_type_name, leave_limit_period,
         leave_max_days_per_period, skip_weekends, skip_holidays
    INTO t
  FROM public.hr_leave_types
  WHERE id = NEW.leave_type_id;

  IF t.request_category IS DISTINCT FROM 'leave'
     OR t.leave_limit_period IS NULL THEN
    RETURN NEW;
  END IF;

  v_this := public.hr_calc_leave_days(
    NEW.start_date, NEW.end_date, NEW.duration_type,
    COALESCE(t.skip_weekends, true), COALESCE(t.skip_holidays, true),
    NEW.hr_organization_id, NEW.employee_id
  );

  IF v_this > t.leave_max_days_per_period THEN
    RAISE EXCEPTION
      'This request is % day(s); the maximum per % for % is % day(s).',
      v_this, t.leave_limit_period, t.leave_type_name, t.leave_max_days_per_period;
  END IF;

  SELECT * INTO w FROM public.hr_leave_period_window(
    t.leave_limit_period, NEW.hr_academic_year_id, NEW.start_date);

  IF w.period_start IS NULL OR w.period_end IS NULL THEN
    RAISE EXCEPTION 'Cannot determine the % period for this request; contact HR.',
      t.leave_limit_period;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(NEW.employee_id::text || ':' || NEW.leave_type_id::text, 0)
  );

  SELECT COALESCE(sum(
           public.hr_calc_leave_days(
             a.start_date, a.end_date, a.duration_type,
             COALESCE(t.skip_weekends, true), COALESCE(t.skip_holidays, true),
             a.hr_organization_id, a.employee_id)
         ), 0)
    INTO v_used
  FROM public.hr_leave_applications a
  WHERE a.employee_id   = NEW.employee_id
    AND a.leave_type_id = NEW.leave_type_id
    AND a.id IS DISTINCT FROM NEW.id
    AND a.status IN ('pending','approved','escalated')
    AND a.start_date BETWEEN w.period_start AND w.period_end;

  IF v_used + v_this > t.leave_max_days_per_period THEN
    RAISE EXCEPTION
      'Limit reached: % of % day(s) of % already used between % and %; this request needs %.',
      v_used, t.leave_max_days_per_period, t.leave_type_name,
      w.period_start, w.period_end, v_this;
  END IF;

  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.hr_leave_period_usage(
  p_staff_id uuid,
  p_leave_type_id uuid,
  p_hr_academic_year_id uuid DEFAULT NULL::uuid,
  p_on date DEFAULT CURRENT_DATE
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  t record;
  w record;
  v_used numeric := 0;
BEGIN
  IF NOT public.is_super_admin()
     AND NOT (p_staff_id IN (SELECT unnest(public.fn_my_staff_ids())))
     AND NOT public.user_has_permission('hr.leave.approve') THEN
    RAISE EXCEPTION 'Not authorized to read this usage';
  END IF;

  SELECT request_category, leave_limit_period, leave_max_days_per_period,
         skip_weekends, skip_holidays
    INTO t
  FROM public.hr_leave_types
  WHERE id = p_leave_type_id;

  IF t.request_category IS DISTINCT FROM 'leave'
     OR t.leave_limit_period IS NULL THEN
    RETURN jsonb_build_object('limited', false);
  END IF;

  SELECT * INTO w FROM public.hr_leave_period_window(
    t.leave_limit_period, p_hr_academic_year_id, p_on);

  IF w.period_start IS NULL THEN
    RETURN jsonb_build_object(
      'limited', true, 'window_unresolved', true,
      'limit_period', t.leave_limit_period,
      'max_days', t.leave_max_days_per_period);
  END IF;

  SELECT COALESCE(sum(
           public.hr_calc_leave_days(
             a.start_date, a.end_date, a.duration_type,
             COALESCE(t.skip_weekends, true), COALESCE(t.skip_holidays, true),
             a.hr_organization_id, a.employee_id)
         ), 0)
    INTO v_used
  FROM public.hr_leave_applications a
  WHERE a.employee_id   = p_staff_id
    AND a.leave_type_id = p_leave_type_id
    AND a.status IN ('pending','approved','escalated')
    AND a.start_date BETWEEN w.period_start AND w.period_end;

  RETURN jsonb_build_object(
    'limited',      true,
    'limit_period', t.leave_limit_period,
    'period_start', w.period_start,
    'period_end',   w.period_end,
    'max_days',     t.leave_max_days_per_period,
    'days_used',    v_used,
    'days_left',    GREATEST(0, t.leave_max_days_per_period - v_used)
  );
END $function$;

CREATE OR REPLACE FUNCTION public.hr_trig_recompute_on_holiday_change()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
  v_affected_start  date;
  v_affected_end    date;
  v_inst_id         uuid;
  v_app             RECORD;
  v_new_days        numeric;
  v_delta           numeric;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_affected_start := OLD.start_date;
    v_affected_end   := OLD.end_date;
    v_inst_id        := OLD.institution_id;
  ELSE
    v_affected_start := LEAST(NEW.start_date, COALESCE(OLD.start_date, NEW.start_date));
    v_affected_end   := GREATEST(NEW.end_date, COALESCE(OLD.end_date, NEW.end_date));
    v_inst_id        := NEW.institution_id;
  END IF;

  FOR v_app IN
    SELECT hla.id, hla.employee_id, hla.leave_type_id, hla.hr_academic_year_id,
           hla.hr_organization_id, hla.start_date, hla.end_date,
           hla.duration_type, hla.total_days,
           hlt.skip_weekends, hlt.skip_holidays
      FROM hr_leave_applications hla
      JOIN hr_leave_types hlt ON hlt.id = hla.leave_type_id
      JOIN hr_organizations hro ON hro.id = hla.hr_organization_id
     WHERE hla.status = 'approved'
       AND hro.institution_id = v_inst_id
       AND hla.start_date <= v_affected_end
       AND hla.end_date   >= v_affected_start
       AND hlt.skip_holidays = true  -- only re-calc if type respects holidays
  LOOP
    v_new_days := hr_calc_leave_days(
      v_app.start_date, v_app.end_date, v_app.duration_type,
      v_app.skip_weekends, v_app.skip_holidays, v_app.hr_organization_id,
      v_app.employee_id
    );

    v_delta := v_new_days - v_app.total_days;

    IF v_delta != 0 THEN
      UPDATE hr_leave_applications
         SET total_days  = v_new_days,
             updated_at  = now()
       WHERE id = v_app.id;

      UPDATE hr_leave_balances
         SET used       = GREATEST(0, used + v_delta),
             updated_at = now()
       WHERE employee_id         = v_app.employee_id
         AND leave_type_id       = v_app.leave_type_id
         AND hr_academic_year_id = v_app.hr_academic_year_id;
    END IF;
  END LOOP;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END $function$;

-- ---------------------------------------------------------------------------
-- 4. Existing rows: backfilled 2026-08-20, outside this migration.
-- ---------------------------------------------------------------------------
-- 39 pending applications carried an under-counted total_days, 39 days in
-- total, two of them stored as 0.00 (a leave taken entirely on a Saturday was
-- charged nothing at all). None were approved, so no hr_leave_balances row had
-- consumed the wrong number.
--
-- THE COLUMN NAMED IN SET MATTERS. Both triggers are UPDATE OF <columns>:
--
--   trg_hla_populate_total_days  BEFORE INSERT OR UPDATE OF start_date,
--       end_date, duration_type, leave_type_id, start_time, end_time
--   trg_hla_leave_period_cap     BEFORE INSERT OR UPDATE OF start_date,
--       end_date, duration_type, leave_type_id, status
--
-- updated_at is in neither list, so `SET updated_at = now()` bumps the column
-- and fires nothing — the first backfill attempt touched all 39 rows and
-- recomputed none of them. `SET start_date = start_date` does fire both, since
-- UPDATE OF triggers on a column being MENTIONED, not on its value changing.
--
-- Run row by row with the exception captured per row, so that a corrected total
-- breaking a per-period cap is reported rather than aborting the batch. All 39
-- succeeded with no cap violations; zero rows now disagree with the function.

-- ===========================================================================
-- Leave approval -> attendance: respect request_category and duration_type
-- Mirrored from supabase/migrations/20260820200000_leave_approval_attendance_respects_category.sql
-- ===========================================================================
-- HR Attendance — an hourly permission must not erase a worked day.
--
-- THE BUG
-- -------
-- 09/07/2026 showed LEAVE against punches of 09:24-17:48 — a full day worked.
-- Two approved "Permission (Hourly)" requests covered 09:05-09:35 that morning,
-- 30 minutes each, total_days 0.13.
--
-- fn_recompute_attendance_on_leave_approval fires whenever ANY leave
-- application reaches 'approved' and then does this:
--
--     UPDATE hr_attendance_records SET status_type_id = <LEAVE>
--      WHERE employee_id = NEW.employee_id
--        AND work_date BETWEEN NEW.start_date AND NEW.end_date
--
-- No request_category test. No duration_type test. LEAVE is the only status it
-- can write. So a 30-minute permission overwrote the whole day, and a half-day
-- leave would overwrite a half-worked day just as completely.
--
-- THE TRIGGER NEXT DOOR ALREADY KNEW BETTER
-- ------------------------------------------
-- hr_trig_update_leave_balance, on the same table, guards exactly this:
--
--     IF v_category IN ('compensatory_off', 'short_time_off') THEN
--       -- "Comp off is credit-backed; short time off is minute-backed.
--       --  Neither draws on a day entitlement."
--
-- The balance side knew a permission is not a day. The attendance side never
-- learned. Two triggers on one table, one of them carrying the rule.
--
-- THE FIX
-- -------
--   short_time_off, or duration_type 'hourly'  -> touch nothing. A permission
--       is minute-backed; the day keeps whatever the biometric engine decided.
--   first_half / second_half                   -> write HALF_DAY, not LEAVE.
--       The person worked the other half; erasing it as full LEAVE loses that.
--   everything else (full-day leave, comp off)  -> LEAVE, unchanged.
--
-- compensatory_off is deliberately NOT skipped here even though the balance
-- trigger skips it: booking comp off IS a day away from work, so LEAVE is the
-- right attendance status. It is skipped for BALANCE because it draws on a
-- credit rather than an entitlement. Different question, different answer.
--
-- The audit-log INSERT is kept in step with the UPDATE — it previously recorded
-- 'previous status -> LEAVE' for rows that are now becoming HALF_DAY.

CREATE OR REPLACE FUNCTION public.fn_recompute_attendance_on_leave_approval()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_target_status_id UUID;
  v_target_code      TEXT;
  v_category         TEXT;
  v_event_id         UUID := gen_random_uuid();
BEGIN
  IF NOT (TG_OP = 'UPDATE'
          AND NEW.status = 'approved'
          AND COALESCE(OLD.status, '') <> 'approved') THEN
    RETURN NEW;
  END IF;

  SELECT request_category INTO v_category
  FROM hr_leave_types WHERE id = NEW.leave_type_id;

  -- A permission is measured in minutes, not days. It leaves the day's verdict
  -- exactly as the biometric engine computed it.
  IF v_category = 'short_time_off' OR NEW.duration_type = 'hourly' THEN
    RETURN NEW;
  END IF;

  v_target_code := CASE
    WHEN NEW.duration_type IN ('first_half', 'second_half') THEN 'HALF_DAY'
    ELSE 'LEAVE'
  END;

  SELECT id INTO v_target_status_id
  FROM hr_attendance_status_types
  WHERE code = v_target_code AND institution_id IS NULL
  LIMIT 1;

  IF v_target_status_id IS NULL THEN RETURN NEW; END IF;

  INSERT INTO hr_attendance_audit_log (
    attendance_record_id, employee_id, institution_id, actor_id, action,
    before_state, after_state, reason, created_at
  )
  SELECT
    r.id, r.employee_id, r.institution_id, NEW.final_approver_id, 'recompute',
    jsonb_build_object('status_type_id', r.status_type_id),
    jsonb_build_object('status_type_id', v_target_status_id,
                       'status_code', v_target_code,
                       'event_id', v_event_id,
                       'leave_application_id', NEW.id),
    format('Leave application approved; previous status -> %s', v_target_code),
    NOW()
  FROM hr_attendance_records r
  WHERE r.employee_id = NEW.employee_id
    AND r.work_date BETWEEN NEW.start_date AND NEW.end_date
    AND r.status_type_id <> v_target_status_id;

  UPDATE hr_attendance_records r
    SET status_type_id = v_target_status_id,
        recomputed_from_event_id = v_event_id,
        updated_at = NOW()
  WHERE r.employee_id = NEW.employee_id
    AND r.work_date BETWEEN NEW.start_date AND NEW.end_date
    AND r.status_type_id <> v_target_status_id;

  RETURN NEW;
END;
$function$;

COMMENT ON FUNCTION public.fn_recompute_attendance_on_leave_approval() IS
  'On leave approval, stamps the covered days LEAVE (or HALF_DAY for a half-day request). Short time off and hourly requests are skipped entirely — a permission is minute-backed and does not change the day''s attendance verdict.';

-- ---------------------------------------------------------------------------
-- Repair the days already overwritten.
-- ---------------------------------------------------------------------------
-- One row today: 09/07/2026 for staff NOT148, punched 09:24-17:48 and stamped
-- LEAVE by a 30-minute permission. The correct verdict comes from evaluateDay,
-- which is TypeScript and cannot be re-run from SQL — so this only UNDOES the
-- bad stamp where the audit log recorded what the status was before. Rows with
-- no audit trail are left alone rather than guessed at; re-importing the month
-- recomputes them from the punches.
UPDATE public.hr_attendance_records r
   SET status_type_id = (l.before_state ->> 'status_type_id')::uuid,
       recomputed_from_event_id = NULL,
       updated_at = NOW()
  FROM (
    SELECT DISTINCT ON (a.attendance_record_id)
           a.attendance_record_id, a.before_state
      FROM public.hr_attendance_audit_log a
      JOIN public.hr_leave_applications la
        ON la.id = (a.after_state ->> 'leave_application_id')::uuid
      JOIN public.hr_leave_types t ON t.id = la.leave_type_id
     WHERE a.action = 'recompute'
       AND a.after_state ->> 'status_code' = 'LEAVE'
       AND (t.request_category = 'short_time_off' OR la.duration_type = 'hourly')
       AND a.before_state ->> 'status_type_id' IS NOT NULL
     ORDER BY a.attendance_record_id, a.created_at ASC
  ) l
 WHERE r.id = l.attendance_record_id
   AND r.status_type_id = (SELECT id FROM public.hr_attendance_status_types
                            WHERE code = 'LEAVE' AND institution_id IS NULL LIMIT 1);

-- ===========================================================================
-- Short Time Off — overlap guard (one permission per time slot)
-- Mirrored from supabase/migrations/20260821090000_short_time_off_overlap_guard.sql
-- ===========================================================================
-- HR Short Time Off — one permission per time slot.
--
-- THE GAP
-- -------
-- 09/07/2026 carried TWO approved "Permission (Hourly)" requests for the same
-- staff member, same date, both 09:05-09:35. 0.26 days deducted for one
-- 30-minute absence, and the day was stamped LEAVE twice.
--
-- hr_trig_sto_enforce_limits already governs short time off, but it counts and
-- sums; it has no concept of two requests occupying the same minutes. For
-- Permission (Hourly) the limits are total_duration 120 min/month, min 30,
-- max 60 — so two 30-minute requests are 60 of 120 and both passed cleanly.
--
-- WHY THIS SITS BEFORE THE LIMITS RESOLUTION
-- -------------------------------------------
-- The existing function returns early when a type has no limits configured:
--
--     IF lim.limit_mode IS NULL OR lim.limit_mode = 'none' THEN RETURN NEW;
--
-- Everything after that line is unreachable for such a type — including, today,
-- the `end_time <= start_time` sanity check. An overlap guard placed after it
-- would protect only the types that happen to have limits set. Both the window
-- sanity check and the overlap check are therefore moved ahead of it: they are
-- statements about whether the request is COHERENT, not about how much of an
-- allowance it consumes.
--
-- OVERLAP TEST: half-open intervals, `a.start < NEW.end AND NEW.start < a.end`.
-- Back-to-back slots (09:00-09:30 then 09:30-10:00) do NOT clash, which is the
-- intended reading — the second begins as the first ends.
--
-- The advisory lock is keyed on (employee, date) rather than the limits block's
-- (employee, leave_type): two concurrent inserts of DIFFERENT permission types
-- on the same morning must still serialise against each other. Both locks are
-- taken in the same order by every caller, so they cannot deadlock.
--
-- EXISTING ROWS ARE NOT TOUCHED. Two overlapping pairs exist today across two
-- staff members, both exact duplicates. A trigger cannot retro-reject them and
-- cancelling someone's approved request is not a migration's decision.

CREATE OR REPLACE FUNCTION public.hr_trig_sto_enforce_limits()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_category text;
  lim  record;
  w    record;
  v_requests integer := 0;
  v_minutes  integer := 0;
  v_this     integer;
  v_name     text;
  v_needs_duration boolean;
  v_clash    record;
BEGIN
  IF NEW.status NOT IN ('pending','approved','escalated') THEN
    RETURN NEW;
  END IF;

  SELECT request_category, leave_type_name INTO v_category, v_name
  FROM public.hr_leave_types WHERE id = NEW.leave_type_id;
  IF v_category IS DISTINCT FROM 'short_time_off' THEN
    RETURN NEW;
  END IF;

  -- ---- Coherence checks: every short-time-off request, limits or not -------
  IF NEW.duration_type = 'hourly'
     AND NEW.start_time IS NOT NULL AND NEW.end_time IS NOT NULL THEN

    IF NEW.end_time <= NEW.start_time THEN
      RAISE EXCEPTION 'End time must be after start time.';
    END IF;

    PERFORM pg_advisory_xact_lock(
      hashtextextended(NEW.employee_id::text || ':sto:' || NEW.start_date::text, 0)
    );

    SELECT t2.leave_type_name AS type_name, a.start_time, a.end_time, a.status
      INTO v_clash
    FROM public.hr_leave_applications a
    JOIN public.hr_leave_types t2 ON t2.id = a.leave_type_id
    WHERE a.employee_id = NEW.employee_id
      AND a.id IS DISTINCT FROM NEW.id
      AND a.status IN ('pending','approved','escalated')
      AND t2.request_category = 'short_time_off'
      AND a.duration_type = 'hourly'
      AND a.start_date = NEW.start_date
      AND a.start_time IS NOT NULL
      AND a.end_time   IS NOT NULL
      AND a.start_time < NEW.end_time
      AND NEW.start_time < a.end_time
    ORDER BY a.start_time
    LIMIT 1;

    IF v_clash.type_name IS NOT NULL THEN
      RAISE EXCEPTION
        'This overlaps an existing % request on % — % to % (%). Cancel that one first, or pick a different slot.',
        v_clash.type_name,
        to_char(NEW.start_date, 'DD/MM/YYYY'),
        to_char(v_clash.start_time, 'HH24:MI'),
        to_char(v_clash.end_time, 'HH24:MI'),
        v_clash.status
        USING ERRCODE = '23505';
    END IF;
  END IF;

  -- ---- Allowance checks ----------------------------------------------------
  SELECT * INTO lim FROM public.hr_resolve_sto_limits(NEW.leave_type_id, NEW.employee_id);
  IF lim.limit_mode IS NULL OR lim.limit_mode = 'none' THEN
    RETURN NEW;
  END IF;

  v_needs_duration := lim.limit_mode = 'total_duration'
                      OR lim.min_minutes IS NOT NULL
                      OR lim.max_minutes IS NOT NULL;

  IF NEW.duration_type = 'hourly'
     AND NEW.start_time IS NOT NULL AND NEW.end_time IS NOT NULL THEN
    -- end > start is already guaranteed above; not re-raised here so there is
    -- one source of truth for that message.
    v_this := ROUND(EXTRACT(EPOCH FROM (NEW.end_time - NEW.start_time)) / 60.0)::integer;
  ELSIF v_needs_duration THEN
    IF lim.limit_mode = 'total_duration' THEN
      RAISE EXCEPTION
        '% is limited by total duration, so a request needs a start and end time.',
        v_name;
    ELSE
      RAISE EXCEPTION
        '% sets a minimum or maximum length per request, so a request needs a start and end time.',
        v_name;
    END IF;
  ELSE
    v_this := 0;
  END IF;

  IF lim.min_minutes IS NOT NULL AND v_this < lim.min_minutes THEN
    RAISE EXCEPTION 'This request is % minute(s); the minimum for % is % minute(s).',
      v_this, v_name, lim.min_minutes;
  END IF;

  IF lim.max_minutes IS NOT NULL AND v_this > lim.max_minutes THEN
    RAISE EXCEPTION 'This request is % minute(s); the maximum per request for % is % minute(s).',
      v_this, v_name, lim.max_minutes;
  END IF;

  SELECT * INTO w FROM public.hr_leave_period_window(
    lim.limit_period, NEW.hr_academic_year_id, NEW.start_date);
  IF w.period_start IS NULL OR w.period_end IS NULL THEN
    RAISE EXCEPTION
      'Cannot determine the % period for this request; contact HR.', lim.limit_period;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(NEW.employee_id::text || ':' || NEW.leave_type_id::text, 0)
  );

  SELECT count(*),
         COALESCE(sum(
           CASE
             WHEN a.duration_type = 'hourly'
              AND a.start_time IS NOT NULL AND a.end_time IS NOT NULL
              AND a.end_time > a.start_time
             THEN ROUND(EXTRACT(EPOCH FROM (a.end_time - a.start_time)) / 60.0)::integer
             ELSE 0
           END
         ), 0)
    INTO v_requests, v_minutes
  FROM public.hr_leave_applications a
  WHERE a.employee_id   = NEW.employee_id
    AND a.leave_type_id = NEW.leave_type_id
    AND a.id IS DISTINCT FROM NEW.id
    AND a.status IN ('pending','approved','escalated')
    AND a.start_date BETWEEN w.period_start AND w.period_end;

  IF lim.limit_mode = 'request_count' AND v_requests + 1 > lim.max_requests THEN
    RAISE EXCEPTION 'Limit reached: % of % request(s) already used between % and %.',
      v_requests, lim.max_requests, w.period_start, w.period_end;
  END IF;

  IF lim.limit_mode = 'total_duration' AND v_minutes + v_this > lim.total_minutes THEN
    RAISE EXCEPTION 'Limit reached: % of % minute(s) already used between % and %; this request needs %.',
      v_minutes, lim.total_minutes, w.period_start, w.period_end, v_this;
  END IF;

  RETURN NEW;
END $function$;

COMMENT ON FUNCTION public.hr_trig_sto_enforce_limits() IS
  'Short time off gate. Coherence first (end > start, and no overlap with another live permission on the same date) so it applies even to types with no limits configured; then the per-period request-count / total-duration allowance.';

-- ===========================================================================
-- Attendance excused-minutes columns + fn_shift_window (service-role safe)
-- Mirrored from supabase/migrations/20260821110000_attendance_excused_minutes.sql
-- ===========================================================================
-- HR Attendance — record WHY a late day counts as present.
--
-- evaluateDay() can now reinstate a half whose missing minutes are fully
-- covered by an approved short-time-off window (see lib/hr/biometric/
-- evaluate-day.ts). Without somewhere to put that, HR would see a 09:24 arrival
-- against an 09:05 deadline reading PRESENT with nothing on screen explaining
-- it — indistinguishable from the bug we spent 2026-08-20 fixing.
--
-- late_minutes deliberately stays RAW. It answers "how late was this person";
-- excused_minutes answers "how much of the shortfall was covered". Collapsing
-- them would lose the first question, which is the one attendance reports ask.

ALTER TABLE public.hr_attendance_records
  ADD COLUMN IF NOT EXISTS excused_minutes integer,
  ADD COLUMN IF NOT EXISTS excused_by_application_ids uuid[];

COMMENT ON COLUMN public.hr_attendance_records.excused_minutes IS
  'Minutes of a required half-window reinstated by an approved short-time-off permission. NULL = never evaluated for excusal; 0 = evaluated, nothing excused.';
COMMENT ON COLUMN public.hr_attendance_records.excused_by_application_ids IS
  'hr_leave_applications ids of the permissions that did the reinstating. No FK: these rows outlive an application that is later purged, and an orphaned id is better than losing the audit of why a day counted.';

-- ---------------------------------------------------------------------------
-- A shift window lookup that a service-role context can actually call.
-- ---------------------------------------------------------------------------
-- fn_resolve_shift_timing and fn_resolve_shift_timings_bulk both guard on
-- is_super_admin / is_admin / hr.shift_timings.view / hr.attendance.override.
-- All four are false when auth.uid() is NULL, so neither can be used from a
-- service-role client — which is exactly what recomputing a day on leave
-- approval needs, because an HR Manager holding hr.leave.approve holds none of
-- those four and cannot write hr_attendance_records either.
--
-- This variant carries the identical resolution — institution + ISO day_of_week
-- + effective window + staff_scope precedence (category beats teaching /
-- non_teaching) + the second-Saturday override — with no authorisation gate,
-- for the same reason hr_is_working_day has none: it returns an institution's
-- working-hours calendar for one date. No punches, no verdicts, nothing about
-- the person beyond which shift pattern applies to them.
CREATE OR REPLACE FUNCTION public.fn_shift_window(p_staff_id uuid, p_date date)
 RETURNS TABLE(timing_id uuid, is_working_day boolean, first_half_start time without time zone, first_half_end time without time zone, second_half_start time without time zone, second_half_end time without time zone, grace_minutes integer, matched_by text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_institution_id uuid;
  v_category_id    uuid;
  v_is_teaching    boolean;
  v_gender         text;
  v_pattern_id     uuid;
  v_dow            smallint;
  v_second_sat     boolean;
BEGIN
  IF p_staff_id IS NULL OR p_date IS NULL THEN RETURN; END IF;

  SELECT s.institution_id, s.category_id, ec.is_teaching, s.gender
    INTO v_institution_id, v_category_id, v_is_teaching, v_gender
  FROM public.staff s
  JOIN public.employment_categories ec ON ec.id = s.category_id
  WHERE s.id = p_staff_id;

  IF v_institution_id IS NULL THEN RETURN; END IF;

  v_pattern_id := public.fn_staff_work_pattern_id(p_staff_id, p_date);
  v_dow        := EXTRACT(ISODOW FROM p_date)::smallint;
  v_second_sat := (v_dow = 6 AND EXTRACT(DAY FROM p_date) BETWEEN 8 AND 14);

  RETURN QUERY
  SELECT
    t.id,
    CASE WHEN (v_second_sat AND t.second_saturday_holiday) THEN false ELSE t.is_working_day END,
    CASE WHEN (v_second_sat AND t.second_saturday_holiday) THEN NULL ELSE t.first_half_start  END,
    CASE WHEN (v_second_sat AND t.second_saturday_holiday) THEN NULL ELSE t.first_half_end    END,
    CASE WHEN (v_second_sat AND t.second_saturday_holiday) THEN NULL ELSE t.second_half_start END,
    CASE WHEN (v_second_sat AND t.second_saturday_holiday) THEN NULL ELSE t.second_half_end   END,
    t.grace_minutes,
    CASE WHEN (v_second_sat AND t.second_saturday_holiday) THEN 'second_saturday_holiday'
         ELSE t.staff_scope END
  FROM public.fn_shift_timing_pick(
         v_institution_id, v_category_id, v_is_teaching, v_gender, v_dow, p_date, v_pattern_id) t;
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_shift_window(uuid, date) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fn_shift_window(uuid, date) TO authenticated, service_role;

COMMENT ON FUNCTION public.fn_shift_window(uuid, date) IS
  'Shift window for one staff member on one date, second-Saturday rule included. Ungated on purpose — it returns a working-hours calendar, not staff data — so a service-role recompute after a leave decision can resolve it.';


-- ===========================================================================
-- Migration: supabase/migrations/20260821120000_induction_live_gate_writes.sql
-- Migration: supabase/migrations/20260821130000_induction_live_gate_reads.sql
-- Induction Draft/Live lifecycle gate. Supersedes any earlier definition of
-- the five learner-facing RPCs below (this snapshot appends; last one wins).
-- ===========================================================================

-- Induction lifecycle gate, part 1 of 2: WRITES.
--
-- Why this exists. The Draft <-> Live model shipped 2026-08-18 (types/events.ts
-- INDUCTION_STATUS_TRANSITIONS + InductionEventService) as a DISPLAY and
-- TRANSITION layer only. INDUCTION_ACTIVE_STATUS was referenced in exactly two
-- places -- the constant itself and a badge colour -- and not one of the ~130
-- fn_induction_* RPCs ever compared events.status to 'live'. So a Draft
-- induction behaved identically to a Live one: freshers saw it, coordinators
-- marked attendance on it, volunteers captured feedback for it.
--
-- Measured on production 2026-08-21, BEFORE this migration:
--   3 Draft inductions holding 317 enrolled learners,
--   83 attendance rows and 19 feedback rows already recorded against them.
-- Those rows are left in place -- this guard is about new writes, and deleting
-- captured feedback is not a migration's call.
--
-- WHY A TRIGGER AND NOT A CHECK IN EACH RPC. Seven SECURITY DEFINER functions
-- write these four tables:
--   event_session_attendance  <- mark_attendance, mark_day_attendance,
--                                volunteer_mark_attendance
--   event_session_feedback    <- submit_feedback, submit_feedback_proxy,
--                                volunteer_submit_feedback
--   event_day_feedback        <- submit_day_feedback
--   event_program_feedback    <- submit_program_feedback
-- Editing seven bodies means seven chances for the predicate to drift, and the
-- eighth writer added next month would arrive ungated. The table is the real
-- boundary, so the guard belongs on the table.
--
-- WHAT IS DELIBERATELY *NOT* GATED. Draft is the build phase and must stay
-- usable: fn_induction_auto_enroll (enrolling the cohort),
-- fn_induction_upsert_session (writing the schedule), mentor/volunteer
-- appointment, and fn_induction_training_mark_attended (peer mentors are
-- trained BEFORE the programme opens). Gating those would block legitimate
-- preparation. The line drawn here is: Draft = build it, Live = run it.

-- ---------------------------------------------------------------------------
-- The predicate, in one place.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_induction_assert_live(p_event_id uuid)
RETURNS void
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_status text;
BEGIN
  -- SECURITY DEFINER is load-bearing: this runs inside a learner's INSERT, and
  -- a learner cannot necessarily SELECT the events row. Reading it as the
  -- caller would return NOT FOUND and the guard would fail OPEN -- the exact
  -- failure mode it exists to prevent.
  --
  -- The join to induction_programs scopes the guard to INDUCTIONS. These four
  -- tables are named event_* and today carry induction rows only (verified
  -- 2026-08-21: 5,162 attendance / 12,419 feedback rows, all induction), but a
  -- marathon or tournament writing them later must not inherit this rule.
  SELECT e.status
    INTO v_status
    FROM public.events e
    JOIN public.induction_programs ip ON ip.event_id = e.id
   WHERE e.id = p_event_id;

  IF NOT FOUND THEN
    RETURN;  -- not an induction; not this guard's business
  END IF;

  -- IS DISTINCT FROM, never <>: `v_status <> 'live'` is NULL when the status is
  -- NULL, and a NULL condition in plpgsql takes the ELSE branch -- the guard
  -- would pass silently on exactly the rows most likely to be malformed.
  IF v_status IS DISTINCT FROM 'live' THEN
    RAISE EXCEPTION
      'This induction is %. Attendance and feedback can only be recorded while it is Live -- change its status to Live first.',
      COALESCE(initcap(v_status), 'not yet activated')
      USING ERRCODE = 'check_violation';
  END IF;
END
$function$;

COMMENT ON FUNCTION public.fn_induction_assert_live(uuid) IS
  'Raises unless the given induction event is Live. No-op for non-induction events. Guards attendance/feedback writes.';

-- ---------------------------------------------------------------------------
-- Two trigger adapters: one resolves the event via session_id, one reads it
-- straight off the row.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.trg_induction_require_live_by_session()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_event uuid;
BEGIN
  SELECT s.event_id INTO v_event
    FROM public.event_sessions s
   WHERE s.id = NEW.session_id;

  IF v_event IS NOT NULL THEN
    PERFORM public.fn_induction_assert_live(v_event);
  END IF;

  RETURN NEW;
END
$function$;

CREATE OR REPLACE FUNCTION public.trg_induction_require_live_by_event()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.fn_induction_assert_live(NEW.event_id);
  RETURN NEW;
END
$function$;

-- ---------------------------------------------------------------------------
-- Induction lifecycle gate, part 2 of 2: READS (learner visibility).
--
-- A trigger cannot filter a SELECT, so the read side is patched in the five
-- learner-facing RPCs. CREATE OR REPLACE throughout -- never DROP + CREATE:
-- DROP FUNCTION discards the function's grants and EXECUTE silently reverts to
-- PUBLIC. Signatures are unchanged, so REPLACE is sufficient.
--
-- fn_induction_my_enrollments is the master switch. /learners/my-induction
-- takes rows[0] and renders its empty state when that is null, so filtering
-- here makes the whole page go dark for a Draft induction; the other four are
-- defence in depth for the banners and the peer-mentor lane, which fetch
-- independently of the enrollment call.
--
-- FUTURE STATUSES. The predicate is `= 'live'` because Draft <-> Live are the
-- only two states this module has (verified 2026-08-21: 8 inductions, 3 draft,
-- 5 live, none in a legacy status). If inductions ever gain a post-completion
-- state such as 'archived', THIS READ PREDICATE MUST WIDEN -- otherwise a
-- fresher loses their own induction history the moment it is closed out. The
-- WRITE guard in the companion migration must stay `= 'live'` regardless.

-- ---------------------------------------------------------------------------
-- 1. The master switch: a learner's own enrollments.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_induction_my_enrollments()
 RETURNS TABLE(event_id uuid, event_name text, institution_id uuid, institution_name text, start_date date, end_date date, status text, batch_id uuid, batch_label text, sessions_total integer, sessions_attended integer, attendance_pct numeric, participation_complete boolean, value_score_avg numeric, advocacy_score numeric, is_profile_complete boolean, profile_fields_total integer, profile_fields_filled integer, feedback_day_enabled boolean, feedback_program_enabled boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_learner UUID;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'fn_induction_my_enrollments: not authenticated';
  END IF;
  v_learner := get_my_learner_id();
  IF v_learner IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    e.id::uuid,
    e.name::text,
    e.institution_id::uuid,
    i.name::text,
    e.start_date::date,
    e.end_date::date,
    e.status::text,
    ie.batch_id::uuid,
    b.label::text,
    COALESCE(c.sessions_total, 0)::integer,
    COALESCE(c.sessions_attended, 0)::integer,
    COALESCE(c.attendance_pct, 0)::numeric,
    COALESCE(c.participation_complete, false)::boolean,
    c.value_score_avg::numeric,
    c.advocacy_score::numeric,
    COALESCE(lp.is_profile_complete, false)::boolean,
    4::integer,
    (
      (lp.college_email   IS NOT NULL AND btrim(lp.college_email) <> '')::int +
      (lp.academic_year_id IS NOT NULL)::int +
      (lp.semester_id      IS NOT NULL)::int +
      (lp.section_id       IS NOT NULL)::int
    )::integer,
    COALESCE(ip.feedback_day_enabled, false)::boolean,
    COALESCE(ip.feedback_program_enabled, false)::boolean
  FROM public.induction_enrollment ie
  JOIN public.events             e  ON e.id = ie.event_id
  JOIN public.institutions       i  ON i.id = e.institution_id
  LEFT JOIN public.induction_batches    b  ON b.id = ie.batch_id
  LEFT JOIN public.induction_completion c  ON c.event_id = ie.event_id AND c.learner_id = ie.learner_id
  LEFT JOIN public.learners_profiles    lp ON lp.id = ie.learner_id
  LEFT JOIN public.induction_programs   ip ON ip.event_id = ie.event_id
  WHERE ie.learner_id = v_learner
    -- Lifecycle gate. Enrollment happens during Draft (fn_induction_auto_enroll
    -- is prep work), so being enrolled must NOT by itself reveal the programme.
    AND e.status = 'live'
  ORDER BY e.start_date DESC NULLS LAST;
END $function$;

-- ---------------------------------------------------------------------------
-- 2. The day-by-day schedule.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_induction_list_sessions(p_event_id uuid)
 RETURNS TABLE(id uuid, day_number integer, session_order integer, batch_id uuid, batch_label text, start_at timestamp with time zone, end_at timestamp with time zone, title text, description text, venue_text text, venue_resource_id uuid, speaker_text text, outcome_text text, resource_links jsonb, status text, kind text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inst UUID;
  v_is_coordinator BOOLEAN;
  v_is_speaker BOOLEAN;
  v_my_learner UUID;
  v_my_batch UUID;
  v_enrolled BOOLEAN;
  v_event_status TEXT;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'fn_induction_list_sessions: not authenticated'; END IF;
  SELECT ip.institution_id INTO v_inst FROM public.induction_programs ip WHERE ip.event_id = p_event_id;
  IF v_inst IS NULL THEN RAISE EXCEPTION 'fn_induction_list_sessions: not an induction event'; END IF;

  v_is_coordinator := is_super_admin() OR is_admin()
    OR (user_has_permission('induction.view') AND role_has_institution_access(v_inst))
    OR public.fn_induction_is_event_coordinator(p_event_id);

  v_is_speaker := public.fn_induction_is_event_speaker(p_event_id);

  v_my_learner := get_my_learner_id();
  SELECT true, ie.batch_id INTO v_enrolled, v_my_batch
  FROM public.induction_enrollment ie
  WHERE ie.event_id = p_event_id AND ie.learner_id = v_my_learner;

  IF NOT v_is_coordinator AND NOT v_is_speaker AND NOT COALESCE(v_enrolled, false) THEN
    RAISE EXCEPTION 'fn_induction_list_sessions: not authorized';
  END IF;

  -- Lifecycle gate, learners only. Coordinators and resource persons keep full
  -- Draft access -- Draft is precisely where the schedule is built and
  -- previewed, so gating them would break the authoring flow this module needs.
  IF NOT v_is_coordinator AND NOT v_is_speaker THEN
    SELECT e.status INTO v_event_status FROM public.events e WHERE e.id = p_event_id;
    IF v_event_status IS DISTINCT FROM 'live' THEN
      RAISE EXCEPTION 'fn_induction_list_sessions: this induction is not live yet';
    END IF;
  END IF;

  RETURN QUERY
  SELECT s.id::uuid, s.day_number::integer, s.session_order::integer,
         s.batch_id::uuid, b.label::text,
         s.start_at, s.end_at,
         s.title::text, s.description::text, s.venue_text::text,
         s.venue_resource_id::uuid,
         s.speaker_text::text, s.outcome_text::text,
         COALESCE(s.resource_links, '[]'::jsonb), s.status::text,
         s.kind::text
  FROM public.event_sessions s
  LEFT JOIN public.induction_batches b ON b.id = s.batch_id
  WHERE s.event_id = p_event_id
    AND (v_is_coordinator OR v_is_speaker OR v_my_batch IS NULL OR s.batch_id IS NULL OR s.batch_id = v_my_batch)
  ORDER BY s.day_number NULLS LAST, s.start_at NULLS LAST, s.session_order;
END $function$;

-- ---------------------------------------------------------------------------
-- 3 & 4. The two learner banners. Both already join events, so the gate is one
-- predicate each.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_induction_session_poll_for_learner()
 RETURNS TABLE(poll_id uuid, session_id uuid, event_id uuid, event_name text, title text, day_number integer, auto_close_at timestamp with time zone, already_answered boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_learner uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'fn_induction_session_poll_for_learner: not authenticated'; END IF;
  v_learner := get_my_learner_id();
  IF v_learner IS NULL THEN RETURN; END IF;
  RETURN QUERY
  SELECT p.id, p.session_id, p.event_id, ev.name, es.title, es.day_number, p.auto_close_at,
         EXISTS (SELECT 1 FROM public.induction_session_poll_vote v WHERE v.poll_id = p.id AND v.learner_id = v_learner)
  FROM public.induction_session_poll p
  JOIN public.event_sessions es ON es.id = p.session_id
  JOIN public.events ev         ON ev.id = p.event_id
  JOIN public.induction_enrollment ie ON ie.event_id = p.event_id AND ie.learner_id = v_learner
  WHERE p.status = 'open' AND (p.auto_close_at IS NULL OR p.auto_close_at > now())
    AND (es.batch_id IS NULL OR es.batch_id = ie.batch_id)
    AND ev.status = 'live'   -- lifecycle gate
  ORDER BY p.issued_at DESC;
END $function$;

CREATE OR REPLACE FUNCTION public.fn_induction_session_pulse_for_learner()
 RETURNS TABLE(pulse_id uuid, session_id uuid, event_id uuid, event_name text, title text, day_number integer, auto_close_at timestamp with time zone, already_answered boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_learner uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'fn_induction_session_pulse_for_learner: not authenticated'; END IF;
  v_learner := get_my_learner_id();
  IF v_learner IS NULL THEN RETURN; END IF;  -- not a learner -> no pulses

  RETURN QUERY
  SELECT p.id, p.session_id, p.event_id, ev.name, es.title, es.day_number, p.auto_close_at,
         EXISTS (
           SELECT 1 FROM public.event_session_feedback f
           WHERE f.session_id = p.session_id AND f.learner_id = v_learner
         ) AS already_answered
  FROM public.induction_session_pulse p
  JOIN public.event_sessions es ON es.id = p.session_id
  JOIN public.events ev         ON ev.id = p.event_id
  JOIN public.induction_enrollment ie
    ON ie.event_id = p.event_id AND ie.learner_id = v_learner          -- I am enrolled
  WHERE p.is_open = true
    AND p.auto_close_at > now()
    AND (es.batch_id IS NULL OR es.batch_id = ie.batch_id)             -- session is for my batch
    AND ev.status = 'live'                                             -- lifecycle gate
  ORDER BY p.issued_at DESC;
END $function$;

-- ---------------------------------------------------------------------------
-- 5. The peer-mentor / feedback-volunteer lane (/my-induction-feedback).
-- Without this a Senior Peer Mentor still sees a Draft programme's sessions and
-- opens the check-in and group-capture dialogs on them -- the writes would now
-- be refused by the trigger, but the lane should not offer them at all.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_induction_my_volunteer_sessions()
 RETURNS TABLE(event_id uuid, event_name text, institution_name text, session_id uuid, session_title text, day_number integer, start_at timestamp with time zone, end_at timestamp with time zone, group_size integer, captured integer, kind text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_my_learner UUID;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'fn_induction_my_volunteer_sessions: not authenticated'; END IF;
  v_my_learner := get_my_learner_id();
  IF v_my_learner IS NULL THEN RETURN; END IF;  -- not a learner -> empty

  RETURN QUERY
  SELECT v.event_id,
         ev.name::text,
         inst.name::text,
         s.id,
         s.title::text,
         s.day_number,
         s.start_at,
         s.end_at,
         -- my group size for THIS session (respect batch-specific sessions)
         (SELECT count(*)::int
            FROM public.induction_feedback_volunteer_group g
            JOIN public.induction_enrollment ie
              ON ie.event_id = v.event_id AND ie.learner_id = g.learner_id
            WHERE g.volunteer_id = v.id
              AND (s.batch_id IS NULL OR ie.batch_id = s.batch_id)),
         -- of those (within the session's batch), how many already have a rating --
         -- same batch guard as group_size so captured can never exceed it (review #1694 r2)
         (SELECT count(*)::int
            FROM public.induction_feedback_volunteer_group g
            JOIN public.induction_enrollment ie
              ON ie.event_id = v.event_id AND ie.learner_id = g.learner_id
            JOIN public.event_session_feedback f
              ON f.session_id = s.id AND f.learner_id = g.learner_id
            WHERE g.volunteer_id = v.id
              AND (s.batch_id IS NULL OR ie.batch_id = s.batch_id)),
         s.kind::text
  FROM public.induction_feedback_volunteers v
  JOIN public.events ev ON ev.id = v.event_id
  LEFT JOIN public.institutions inst ON inst.id = v.institution_id
  JOIN public.event_sessions s ON s.event_id = v.event_id
  WHERE v.learner_id = v_my_learner AND v.is_active
    AND ev.status = 'live'   -- lifecycle gate
  ORDER BY ev.name, s.day_number NULLS LAST, s.start_at;
END $function$;


-- ===========================================================================
-- Migration: supabase/migrations/20260821150000_induction_create_permission_split.sql
-- induction.create split out of induction.manage; creation is Induction Lead
-- + super admin only. Supersedes the earlier fn_induction_create_program.
-- ===========================================================================

CREATE OR REPLACE FUNCTION public.fn_induction_create_program(
  p_institution_id uuid, p_academic_year_id uuid, p_name text,
  p_start_date timestamp with time zone, p_end_date timestamp with time zone,
  p_venue_text text DEFAULT 'Campus'::text, p_description text DEFAULT NULL::text,
  p_admission_year integer DEFAULT NULL::integer,
  p_enroll_scope text DEFAULT 'institution'::text,
  p_venue_resource_id uuid DEFAULT NULL::uuid,
  p_degree_type_filter text DEFAULT NULL::text,
  p_institution_ids uuid[] DEFAULT NULL::uuid[],
  p_degree_ids uuid[] DEFAULT NULL::uuid[],
  p_department_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_id uuid; v_slug text;
  v_scope text := COALESCE(NULLIF(p_enroll_scope,''),'institution');
  v_degree text := NULLIF(p_degree_type_filter,'');
  v_multi boolean := (p_institution_ids IS NOT NULL AND cardinality(p_institution_ids) > 0);
  v_owning uuid := CASE WHEN v_multi THEN p_institution_ids[1] ELSE p_institution_id END;
BEGIN
  -- Gate 1 — may this caller create an induction at all?
  IF NOT (is_super_admin() OR is_admin() OR user_has_permission('induction.create')) THEN
    RAISE EXCEPTION 'fn_induction_create_program: not authorized to create inductions';
  END IF;

  -- Gate 2 — scope only. Institution reach is a separate question from the right
  -- to create, so this leg carries no permission key of its own.
  IF NOT (is_super_admin() OR is_admin()) THEN
    IF v_multi THEN
      IF EXISTS (SELECT 1 FROM unnest(p_institution_ids) x(iid)
                  WHERE NOT role_has_institution_access(x.iid)) THEN
        RAISE EXCEPTION 'fn_induction_create_program: not authorized for one or more selected institutions';
      END IF;
    ELSE
      IF NOT role_has_institution_access(p_institution_id) THEN
        RAISE EXCEPTION 'fn_induction_create_program: not authorized';
      END IF;
    END IF;
  END IF;

  IF v_owning IS NULL OR p_name IS NULL THEN
    RAISE EXCEPTION 'fn_induction_create_program: institution and name are required'; END IF;
  IF v_scope NOT IN ('institution','group') THEN
    RAISE EXCEPTION 'fn_induction_create_program: enroll_scope must be institution or group'; END IF;
  IF v_degree IS NOT NULL AND v_degree NOT IN ('ug','pg') THEN
    RAISE EXCEPTION 'fn_induction_create_program: degree_type_filter must be ug, pg, or null'; END IF;

  v_slug := lower(regexp_replace(coalesce(p_name,'induction'), '[^a-zA-Z0-9]+', '-', 'g'))
            || '-' || left(replace(gen_random_uuid()::text, '-', ''), 8);

  INSERT INTO public.events (institution_id, event_type, name, slug, venue_text, venue_resource_id,
                             start_date, end_date, description, status, created_by)
  VALUES (v_owning, 'induction', p_name, v_slug,
          CASE WHEN p_venue_resource_id IS NOT NULL THEN NULLIF(p_venue_text,'Campus') ELSE coalesce(p_venue_text,'Campus') END,
          p_venue_resource_id, p_start_date, p_end_date, p_description, 'draft', auth.uid())
  RETURNING id INTO v_event_id;

  INSERT INTO public.induction_programs (event_id, institution_id, academic_year_id, admission_year,
    enroll_scope, degree_type_filter, target_institution_ids, target_degree_ids, target_department_ids)
  VALUES (v_event_id, v_owning, p_academic_year_id, p_admission_year, v_scope, v_degree,
          CASE WHEN v_multi THEN p_institution_ids ELSE NULL END,
          NULLIF(p_degree_ids, '{}'::uuid[]),
          NULLIF(p_department_ids, '{}'::uuid[]));

  RETURN v_event_id;
END $function$;

-- ===========================================================================
-- HR Leave approval queue — adds applied_by / applied_by_name / applied_on_behalf
-- Mirrored from supabase/migrations/20260821160000_hr_leave_approval_queue_applied_by.sql
-- Replays AFTER the 20260820170000 body above; it DROPs and recreates.
-- ===========================================================================
-- Approval queue also reports WHO SUBMITTED the request.
--
-- employee_id is who the leave is FOR; applied_by is who filed it. They are the
-- same person on all 455 applications today, but the module has always allowed
-- them to differ (LeaveService.applyLeave sets applied_by from the session, not
-- from the payload) and an approver reading "on behalf of" needs to see it.
--
-- Resolved here rather than in the sheet: applied_by is a profiles id, and a
-- staff member cannot read another profile under RLS, so a client-side lookup
-- would come back blank for exactly the rows where it differs. This function is
-- already SECURITY DEFINER.
--
-- RETURNS TABLE gains columns, so DROP first. DROP discards EXECUTE; re-granted.
--
-- The body is identical to 20260820170000 apart from the three new columns
-- (applied_by, applied_by_name, applied_on_behalf) and the profiles LEFT JOIN.
-- See that migration's header for the scope predicate and the can_decide rule.

DROP FUNCTION IF EXISTS public.hr_leave_approval_queue();

CREATE FUNCTION public.hr_leave_approval_queue()
RETURNS TABLE (
  id                   uuid,
  employee_id          uuid,
  staff_name           text,
  staff_code           text,
  institution_id       uuid,
  institution_name     text,
  hr_organization_id   uuid,
  hr_organization_name text,
  leave_type_id        uuid,
  leave_type_name      text,
  leave_type_code      text,
  request_category     text,
  start_date           date,
  end_date             date,
  start_time           time without time zone,
  end_time             time without time zone,
  duration_type        text,
  duration_minutes     integer,
  total_days           numeric,
  reason               text,
  is_emergency         boolean,
  status               text,
  created_at           timestamptz,
  applied_by           uuid,
  applied_by_name      text,
  applied_on_behalf    boolean,
  is_own               boolean,
  can_decide           boolean,
  waiting_on_me        boolean
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $fn$
DECLARE
  v_uid  uuid := auth.uid();
  v_sa   boolean;
  v_orgs uuid[];
  v_mine uuid[];
BEGIN
  IF v_uid IS NULL THEN
    RETURN;
  END IF;

  IF NOT public.hr_can_approve_leave() THEN
    RAISE EXCEPTION 'You do not have permission to approve leave'
      USING ERRCODE = '42501';
  END IF;

  v_sa   := public.is_super_admin();
  -- COALESCE to an empty array so `= ANY(...)` stays false rather than NULL for
  -- an approver with no HR organisation mapping.
  v_orgs := COALESCE(public.fn_my_hr_organization_ids(), ARRAY[]::uuid[]);
  v_mine := COALESCE(public.fn_my_staff_ids(), ARRAY[]::uuid[]);

  RETURN QUERY
  SELECT
    a.id,
    a.employee_id,
    NULLIF(btrim(concat_ws(' ', s.first_name, s.last_name)), '')::text,
    NULLIF(btrim(s.staff_id), '')::text,
    s.institution_id,
    i.name::text,
    a.hr_organization_id,
    o.name::text,
    a.leave_type_id,
    lt.leave_type_name::text,
    lt.leave_type_code::text,
    -- A missing type is treated as 'leave' rather than dropped: matching no
    -- category would make the row vanish from EVERY tab.
    COALESCE(lt.request_category, 'leave')::text,
    a.start_date,
    a.end_date,
    a.start_time,
    a.end_time,
    a.duration_type::text,
    a.duration_minutes,
    a.total_days,
    a.reason,
    a.is_emergency,
    a.status::text,
    a.created_at,
    a.applied_by,
    COALESCE(NULLIF(btrim(p.full_name), ''), p.email)::text AS applied_by_name,
    (a.applied_by IS DISTINCT FROM s.profile_id)            AS applied_on_behalf,
    (a.employee_id = ANY (v_mine))               AS is_own,
    -- Exactly what hr_trig_leave_enforce_approver enforces: super admins are
    -- exempt from the self-approval bar, everyone else is not.
    (v_sa OR a.employee_id <> ALL (v_mine))      AS can_decide,
    (
      -- Waiting on ME: the same three tests as the trigger, so the badge cannot
      -- promise a decision the trigger will refuse.
      --
      -- Unlike hr_leave_my_approval_queue this does NOT return true for every
      -- row just because the caller is a super admin. A super admin CAN decide
      -- anything, but a filter that selects the entire queue tells them nothing
      -- — this is a filter, not a permission.
      (v_sa OR a.employee_id <> ALL (v_mine))
      AND (
        st.step IS NULL
        OR CASE
             WHEN NULLIF(st.step ->> 'approver_user_id', '') IS NOT NULL
               THEN (st.step ->> 'approver_user_id')::uuid = v_uid
             WHEN NULLIF(st.step ->> 'approver_role', '') IS NOT NULL
               THEN NOT EXISTS (
                      SELECT 1 FROM public.custom_roles cr
                       WHERE cr.role_key = st.step ->> 'approver_role' AND cr.is_active
                    )
                    OR EXISTS (
                      SELECT 1
                        FROM public.user_roles ur
                        JOIN public.custom_roles cr2 ON cr2.id = ur.role_id
                       WHERE ur.user_id = v_uid
                         AND cr2.role_key = st.step ->> 'approver_role'
                    )
             ELSE true
           END
      )
    )                                            AS waiting_on_me
  FROM public.hr_leave_applications a
  LEFT JOIN public.hr_leave_types   lt ON lt.id = a.leave_type_id
  LEFT JOIN public.staff            s  ON s.id  = a.employee_id
  LEFT JOIN public.institutions     i  ON i.id  = s.institution_id
  LEFT JOIN public.hr_organizations o  ON o.id  = a.hr_organization_id
  LEFT JOIN public.profiles         p  ON p.id  = a.applied_by
  CROSS JOIN LATERAL (SELECT a.approval_chain -> a.current_step AS step) st
  WHERE a.status IN ('pending', 'escalated')
    -- Scope copied from hla_select. A DEFINER function bypasses RLS, so drifting
    -- from the policy here would hand out rows the table itself refuses.
    AND (
      v_sa
      OR a.hr_organization_id = ANY (v_orgs)
      OR public.fn_is_designated_leave_approver(a.id)
    )
  ORDER BY a.created_at DESC;
END;
$fn$;

REVOKE ALL ON FUNCTION public.hr_leave_approval_queue() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.hr_leave_approval_queue() TO authenticated;

COMMENT ON FUNCTION public.hr_leave_approval_queue() IS
  'Leave + short-time-off awaiting a decision, with the requester''s name, staff code, institution and who submitted it. Scope copies hla_select; super admins see every organisation and may decide their own requests (can_decide).';

-- ===========================================================================
-- HR Leave — no-overlap guard
-- Mirrored from supabase/migrations/20260821170000_leave_overlap_guard.sql
-- ===========================================================================
-- HR Leave — one leave request per day.
--
-- Short time off got an overlap guard on 2026-08-21; day leave never had one.
-- Nothing stopped two live requests covering the same dates, and 3 such pairs
-- existed across 3 staff when this was written. Both draw down the balance on
-- approval, so the same day is paid for twice.
--
-- FIRES ON INSERT AND ON THE DATE/TYPE COLUMNS ONLY — deliberately NOT on
-- status. The pre-existing overlaps must still be approvable and rejectable; a
-- trigger that also fired on a status change would look at the sibling row,
-- find the overlap and refuse the decision, leaving them permanently stuck.
-- This guard is about CREATING an overlap, not about deciding one that exists.
--
-- Leave vs leave only. A permission on a day already covered by full-day leave
-- is also contradictory, but that is a different comparison (minutes against a
-- day) and is left alone rather than guessed at here.

CREATE OR REPLACE FUNCTION public.hr_trig_leave_enforce_no_overlap()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_category text;
  v_clash    record;
BEGIN
  IF NEW.status NOT IN ('pending','approved','escalated') THEN
    RETURN NEW;
  END IF;

  SELECT request_category INTO v_category
  FROM public.hr_leave_types WHERE id = NEW.leave_type_id;

  IF v_category IS DISTINCT FROM 'leave' THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(NEW.employee_id::text || ':leave-overlap', 0)
  );

  SELECT t2.leave_type_name AS type_name, a.start_date, a.end_date, a.status
    INTO v_clash
  FROM public.hr_leave_applications a
  JOIN public.hr_leave_types t2 ON t2.id = a.leave_type_id
  WHERE a.employee_id = NEW.employee_id
    AND a.id IS DISTINCT FROM NEW.id
    AND a.status IN ('pending','approved','escalated')
    AND t2.request_category = 'leave'
    AND a.start_date <= NEW.end_date
    AND NEW.start_date <= a.end_date
  ORDER BY a.start_date
  LIMIT 1;

  IF v_clash.type_name IS NOT NULL THEN
    RAISE EXCEPTION
      'This overlaps an existing % request from % to % (%). Cancel that one first, or pick different dates.',
      v_clash.type_name,
      to_char(v_clash.start_date, 'DD/MM/YYYY'),
      to_char(v_clash.end_date, 'DD/MM/YYYY'),
      v_clash.status
      USING ERRCODE = '23505';
  END IF;

  RETURN NEW;
END $function$;

DROP TRIGGER IF EXISTS trg_hla_leave_overlap ON public.hr_leave_applications;
CREATE TRIGGER trg_hla_leave_overlap
  BEFORE INSERT OR UPDATE OF start_date, end_date, leave_type_id
  ON public.hr_leave_applications
  FOR EACH ROW EXECUTE FUNCTION public.hr_trig_leave_enforce_no_overlap();

COMMENT ON FUNCTION public.hr_trig_leave_enforce_no_overlap() IS
  'Refuses a day-leave request whose dates overlap another live request for the same employee. Not fired on status changes, so pre-existing overlaps stay decidable.';

-- ===========================================================================
-- fn_hr_set_staff_salary (2026-08-21, EPF/ESI added 2026-09-01)
-- Source: 20260821201000_fn_hr_set_staff_salary.sql
--         20260901120000_hr_salary_epf_esi_values.sql
--
-- The 2026-09-01 revision DROPPED the 13-argument signature before recreating
-- it at 16. `CREATE OR REPLACE` with a changed parameter list creates an
-- OVERLOAD rather than replacing, and PostgREST then answers PGRST203 on every
-- call. A rebuild from this file starts clean, so only the final shape is
-- recorded here — but the drop is why the grants below are restated.
-- ===========================================================================
CREATE OR REPLACE FUNCTION public.fn_hr_set_staff_salary(
  p_staff_id               uuid,
  p_hr_organization_id     uuid,
  p_monthly_gross          numeric,
  p_effective_from         date,
  p_salary_structure       text    DEFAULT 'Monthly',
  p_overtime_level         text    DEFAULT 'No overtime',
  p_overtime_amount        numeric DEFAULT 0,
  p_eligible_for_pf        boolean DEFAULT false,
  p_exempt_edli            boolean DEFAULT false,
  p_eligible_for_insurance boolean DEFAULT false,
  p_eligible_for_gratuity  boolean DEFAULT false,
  p_eligible_for_etf       boolean DEFAULT false,
  p_notes                  text    DEFAULT NULL,
  p_epf_amount             numeric DEFAULT 0,
  p_eligible_for_esi       boolean DEFAULT false,
  p_esi_amount             numeric DEFAULT 0,
  p_allowance_amount       numeric DEFAULT 0,
  p_allowance_label        text    DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  v_new_id  uuid := gen_random_uuid();
  v_current record;
  v_epf       numeric;
  v_esi       numeric;
  v_allowance numeric;
  v_alw_label text;
BEGIN
  IF p_staff_id IS NULL OR p_hr_organization_id IS NULL THEN
    RAISE EXCEPTION 'Staff and payroll organisation are both required'
      USING ERRCODE = '22023';
  END IF;
  IF p_monthly_gross IS NULL OR p_monthly_gross <= 0 THEN
    RAISE EXCEPTION 'Monthly salary must be greater than zero' USING ERRCODE = '22023';
  END IF;
  IF p_effective_from IS NULL THEN
    RAISE EXCEPTION 'Effective date is required' USING ERRCODE = '22023';
  END IF;
  IF COALESCE(p_epf_amount, 0) < 0 OR COALESCE(p_esi_amount, 0) < 0 THEN
    RAISE EXCEPTION 'EPF and ESI amounts cannot be negative' USING ERRCODE = '22023';
  END IF;

  -- An amount against a flag that is OFF is zeroed, not rejected. The bulk
  -- importer feeds this from a spreadsheet where a leftover figure beside a "No"
  -- is a formatting slip, and a hard failure there would abort a 754-row import.
  IF COALESCE(p_allowance_amount, 0) < 0 THEN
    RAISE EXCEPTION 'Allowance cannot be negative' USING ERRCODE = '22023';
  END IF;

  v_epf := CASE WHEN p_eligible_for_pf  THEN COALESCE(p_epf_amount, 0) ELSE 0 END;
  v_esi := CASE WHEN p_eligible_for_esi THEN COALESCE(p_esi_amount, 0) ELSE 0 END;

  v_allowance := COALESCE(p_allowance_amount, 0);
  -- A label with no money behind it is noise on every screen that renders it.
  v_alw_label := CASE WHEN v_allowance > 0
                      THEN NULLIF(TRIM(COALESCE(p_allowance_label, '')), '')
                      ELSE NULL END;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_staff_id::text || ':salary', 0));

  SELECT * INTO v_current
    FROM public.hr_staff_salaries
   WHERE staff_id = p_staff_id AND superseded_by IS NULL;

  -- Re-writing an IDENTICAL record would bury the real history under duplicates,
  -- so the incumbent is returned untouched instead.
  --
  -- COMPARES THE WHOLE PAYLOAD (widened 2026-09-01). It used to test only
  -- monthly_gross and effective_from, which meant changing a flag, the overtime
  -- or the notes saved NOTHING and still reported success. Adding EPF/ESI made
  -- that the common case: tick ESI, type 165, save, nothing happens.
  --
  -- IS DISTINCT FROM throughout, not <>. p_notes is nullable and `x <> NULL` is
  -- NULL rather than false — a plain <> chain would evaluate to NULL, be read as
  -- "not different", and silently restore the exact bug this widening fixes.
  IF FOUND
     AND v_current.monthly_gross          IS NOT DISTINCT FROM p_monthly_gross
     AND v_current.effective_from         IS NOT DISTINCT FROM p_effective_from
     AND v_current.hr_organization_id     IS NOT DISTINCT FROM p_hr_organization_id
     AND v_current.salary_structure       IS NOT DISTINCT FROM p_salary_structure
     AND v_current.overtime_level         IS NOT DISTINCT FROM p_overtime_level
     AND v_current.overtime_amount        IS NOT DISTINCT FROM COALESCE(p_overtime_amount, 0)
     AND v_current.eligible_for_pf        IS NOT DISTINCT FROM p_eligible_for_pf
     AND v_current.exempt_edli            IS NOT DISTINCT FROM p_exempt_edli
     AND v_current.eligible_for_insurance IS NOT DISTINCT FROM p_eligible_for_insurance
     AND v_current.eligible_for_gratuity  IS NOT DISTINCT FROM p_eligible_for_gratuity
     AND v_current.eligible_for_etf       IS NOT DISTINCT FROM p_eligible_for_etf
     AND v_current.epf_amount             IS NOT DISTINCT FROM v_epf
     AND v_current.eligible_for_esi       IS NOT DISTINCT FROM p_eligible_for_esi
     AND v_current.esi_amount             IS NOT DISTINCT FROM v_esi
     AND v_current.allowance_amount       IS NOT DISTINCT FROM v_allowance
     AND v_current.allowance_label        IS NOT DISTINCT FROM v_alw_label
     AND v_current.notes                  IS NOT DISTINCT FROM p_notes THEN
    RETURN v_current.id;
  END IF;

  IF FOUND THEN
    UPDATE public.hr_staff_salaries
       SET superseded_by = v_new_id, updated_at = now(), updated_by = auth.uid()
     WHERE id = v_current.id;
  END IF;

  INSERT INTO public.hr_staff_salaries (
    id, staff_id, hr_organization_id, salary_structure, monthly_gross,
    overtime_level, overtime_amount, eligible_for_pf, exempt_edli,
    eligible_for_insurance, eligible_for_gratuity, eligible_for_etf,
    epf_amount, eligible_for_esi, esi_amount,
    allowance_amount, allowance_label,
    effective_from, notes, created_by, updated_by
  ) VALUES (
    v_new_id, p_staff_id, p_hr_organization_id, p_salary_structure, p_monthly_gross,
    p_overtime_level, p_overtime_amount, p_eligible_for_pf, p_exempt_edli,
    p_eligible_for_insurance, p_eligible_for_gratuity, p_eligible_for_etf,
    v_epf, p_eligible_for_esi, v_esi,
    v_allowance, v_alw_label,
    p_effective_from, p_notes, auth.uid(), auth.uid()
  );

  RETURN v_new_id;
END;
$function$;

-- CREATE OR REPLACE keeps existing grants, but a DROP FUNCTION discards them and
-- reverts EXECUTE to PUBLIC — which is exactly what the 2026-09-01 signature
-- change did, and had to be undone. Restated so a rebuild from these files lands
-- in the same place. PUBLIC is revoked as well as anon: a grant to PUBLIC is not
-- removed by revoking from anon.
REVOKE ALL ON FUNCTION public.fn_hr_set_staff_salary(uuid, uuid, numeric, date, text, text, numeric, boolean, boolean, boolean, boolean, boolean, text, numeric, boolean, numeric, numeric, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fn_hr_set_staff_salary(uuid, uuid, numeric, date, text, text, numeric, boolean, boolean, boolean, boolean, boolean, text, numeric, boolean, numeric, numeric, text) TO authenticated, service_role;

COMMENT ON FUNCTION public.fn_hr_set_staff_salary(uuid, uuid, numeric, date, text, text, numeric, boolean, boolean, boolean, boolean, boolean, text, numeric, boolean, numeric, numeric, text) IS
  'Supersede-and-insert a staff salary in one transaction. SECURITY INVOKER: hr_staff_salaries_write enforces hr.payroll.salary.manage. Returns the incumbent unchanged when the whole payload matches.';

-- ===========================================================================
-- hr_staff_salary_directory (2026-08-21, EPF/ESI added 2026-09-01)
-- Source: 20260821220000_hr_staff_salary_directory_rpc.sql
--         20260901120000_hr_salary_epf_esi_values.sql
--
-- The 2026-09-01 revision had to DROP this one too: its RETURNS TABLE gained
-- three columns, and Postgres refuses CREATE OR REPLACE on a changed return
-- type outright.
-- ===========================================================================
CREATE OR REPLACE FUNCTION public.hr_staff_salary_directory()
RETURNS TABLE(
  staff_uuid             uuid,
  staff_code             text,
  person_name            text,
  role_title             text,
  is_active              boolean,
  works_at_id            uuid,
  works_at_name          text,
  payer_org_id           uuid,
  payer_org_name         text,
  salary_id              uuid,
  salary_structure       text,
  monthly_gross          numeric,
  annual_gross           numeric,
  overtime_level         text,
  overtime_amount        numeric,
  eligible_for_pf        boolean,
  exempt_edli            boolean,
  eligible_for_insurance boolean,
  eligible_for_gratuity  boolean,
  eligible_for_etf       boolean,
  epf_amount             numeric,
  eligible_for_esi       boolean,
  esi_amount             numeric,
  allowance_amount       numeric,
  allowance_label        text,
  effective_from         date,
  notes                  text
)
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  -- RAISES rather than returning zero rows, so an empty list from this function
  -- always means "no staff in scope" and never "you are not allowed".
  IF NOT public.user_has_permission('hr.payroll.salary.view') THEN
    RAISE EXCEPTION 'hr.payroll.salary.view is required to see employee salaries.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  SELECT s.id,
         s.staff_id::text,
         TRIM(BOTH FROM COALESCE(s.first_name, '') || ' ' || COALESCE(s.last_name, ''))::text,
         s.designation::text,
         COALESCE(s.is_active, false),
         i.id,
         i.name::text,
         o.id,
         o.name::text,
         sal.id,
         sal.salary_structure::text,
         sal.monthly_gross,
         sal.annual_gross,
         sal.overtime_level::text,
         sal.overtime_amount,
         sal.eligible_for_pf,
         sal.exempt_edli,
         sal.eligible_for_insurance,
         sal.eligible_for_gratuity,
         sal.eligible_for_etf,
         sal.epf_amount,
         sal.eligible_for_esi,
         sal.esi_amount,
         sal.allowance_amount,
         sal.allowance_label,
         sal.effective_from,
         sal.notes
    -- v_hr_staff, never the base staff table: employment_categories.included_in_hr
    -- gates the whole HR module and payroll is no exception.
    FROM public.v_hr_staff s
    JOIN public.institutions i ON i.id = s.institution_id
    LEFT JOIN public.hr_staff_payroll p ON p.staff_id = s.id
    LEFT JOIN public.hr_organizations o ON o.id = p.hr_organization_id
    LEFT JOIN public.hr_staff_salaries sal
           ON sal.staff_id = s.id AND sal.superseded_by IS NULL
   WHERE (COALESCE(s.is_active, false) OR sal.id IS NOT NULL)
     AND public.role_has_institution_access(s.institution_id)
   -- Unset first: this is a work queue before it is a report.
   ORDER BY (sal.id IS NOT NULL), i.name, 3;
END;
$function$;

REVOKE ALL ON FUNCTION public.hr_staff_salary_directory() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.hr_staff_salary_directory() TO authenticated, service_role;


COMMENT ON FUNCTION public.hr_staff_salary_directory() IS
  'Every active staff member with their salary in force, or NULL where none is recorded. Gated on hr.payroll.salary.view; raises rather than returning [] so an empty list never means "denied".';

-- ===========================================================================
-- bank account RPCs (2026-08-21)
-- Source: 20260821250000_fn_hr_set_staff_bank_account_and_directory.sql
-- ===========================================================================
-- Record a staff member's bank account, superseding whatever was in use.
--
-- Same ordering problem, and the same solution, as fn_hr_set_staff_salary: the
-- partial unique index forbids two current rows, so the new id is minted first,
-- the incumbent is pointed at it, and the insert follows -- which is why
-- superseded_by has to be DEFERRABLE.
--
-- SECURITY INVOKER on purpose: hr_staff_bank_accounts_write enforces
-- hr.payroll.bank.manage, so a caller without it writes nothing.
--
-- CHANGING THE ACCOUNT CLEARS THE VERIFICATION. A row that was verified against
-- a passbook says nothing about the number that replaced it, and carrying the
-- tick forward would let an edit inherit trust it never earned. Verification is
-- re-asserted through fn_hr_verify_staff_bank_account, never as a side effect.

CREATE OR REPLACE FUNCTION public.fn_hr_set_staff_bank_account(
  p_staff_id            uuid,
  p_account_holder_name text,
  p_account_number      text,
  p_ifsc_code           text,
  p_bank_name           text,
  p_branch_name         text DEFAULT NULL,
  p_account_type        text DEFAULT 'savings',
  p_effective_from      date DEFAULT CURRENT_DATE,
  p_notes               text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  v_new_id  uuid := gen_random_uuid();
  v_current record;
  -- nullif(...,'') is what makes "absent" a single value rather than two.
  v_ifsc    text := nullif(upper(trim(coalesce(p_ifsc_code, ''))), '');
  v_bank    text := nullif(trim(coalesce(p_bank_name, '')), '');
  v_acct    text := trim(coalesce(p_account_number, ''));
BEGIN
  IF p_staff_id IS NULL THEN
    RAISE EXCEPTION 'Staff is required' USING ERRCODE = '22023';
  END IF;
  IF length(trim(coalesce(p_account_holder_name, ''))) = 0 THEN
    RAISE EXCEPTION 'Account holder name is required' USING ERRCODE = '22023';
  END IF;
  -- Re-checked here as well as by the CHECK constraint so the message names the
  -- field. A raw 23514 tells the user only that "a constraint failed".
  IF v_acct !~ '^[0-9]{6,20}$' THEN
    RAISE EXCEPTION 'Account number must be 6 to 20 digits' USING ERRCODE = '22023';
  END IF;
  -- Absent is fine (optional since 2026-09-02). Present and malformed is not.
  IF v_ifsc IS NOT NULL AND v_ifsc !~ '^[A-Z]{4}0[A-Z0-9]{6}$' THEN
    RAISE EXCEPTION 'IFSC must be 4 letters, then 0, then 6 letters or digits'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_staff_id::text || ':bank', 0));

  SELECT id, account_number, ifsc_code INTO v_current
    FROM public.hr_staff_bank_accounts
   WHERE staff_id = p_staff_id AND superseded_by IS NULL;

  -- Re-saving the identical destination would bury the real history under
  -- duplicates, so the incumbent is returned untouched instead. IS NOT DISTINCT
  -- FROM, not =: under NULL = NULL the test yields NULL rather than true, so an
  -- IFSC-less account would supersede itself on every re-save.
  IF FOUND
     AND v_current.account_number IS NOT DISTINCT FROM v_acct
     AND v_current.ifsc_code      IS NOT DISTINCT FROM v_ifsc THEN
    RETURN v_current.id;
  END IF;

  IF FOUND THEN
    UPDATE public.hr_staff_bank_accounts
       SET superseded_by = v_new_id, updated_at = now(), updated_by = auth.uid()
     WHERE id = v_current.id;
  END IF;

  INSERT INTO public.hr_staff_bank_accounts (
    id, staff_id, account_holder_name, account_number, ifsc_code, bank_name,
    branch_name, account_type, effective_from, notes, created_by, updated_by
  ) VALUES (
    v_new_id, p_staff_id, trim(p_account_holder_name), v_acct, v_ifsc,
    v_bank, nullif(trim(coalesce(p_branch_name, '')), ''),
    coalesce(p_account_type, 'savings'), coalesce(p_effective_from, CURRENT_DATE),
    p_notes, auth.uid(), auth.uid()
  );

  RETURN v_new_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_hr_set_staff_bank_account(uuid, text, text, text, text, text, text, date, text) FROM anon;
GRANT EXECUTE ON FUNCTION public.fn_hr_set_staff_bank_account(uuid, text, text, text, text, text, text, date, text) TO authenticated, service_role;


-- Mark the account in use as checked against a passbook or cancelled cheque.
--
-- A SEPARATE ACT FROM RECORDING IT, deliberately. If saving also verified, the
-- flag would only ever mean "somebody typed this", which is precisely what it
-- exists to distinguish from "somebody checked it".
CREATE OR REPLACE FUNCTION public.fn_hr_verify_staff_bank_account(
  p_account_id uuid,
  p_verified   boolean DEFAULT true
)
RETURNS void
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.hr_staff_bank_accounts
     SET verified_at = CASE WHEN p_verified THEN now() ELSE NULL END,
         verified_by = CASE WHEN p_verified THEN auth.uid() ELSE NULL END,
         updated_at  = now(),
         updated_by  = auth.uid()
   -- Superseded rows are history and stay exactly as they were.
   WHERE id = p_account_id AND superseded_by IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'That bank account is not the one currently in use'
      USING ERRCODE = '22023';
  END IF;
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_hr_verify_staff_bank_account(uuid, boolean) FROM anon;
GRANT EXECUTE ON FUNCTION public.fn_hr_verify_staff_bank_account(uuid, boolean) TO authenticated, service_role;


-- Every payable person and where their money goes, INCLUDING those with no
-- account on file -- the same roster-driven shape as hr_staff_salary_directory,
-- and for the same reason: the gap is the work.
--
-- THE ACCOUNT NUMBER IS RETURNED IN FULL. The audience is two roles, and the
-- edit form needs it; the list masks it in the client. Masking in SQL instead
-- would mean a second privileged path just to populate the edit dialog.
CREATE OR REPLACE FUNCTION public.hr_staff_bank_directory()
RETURNS TABLE(
  staff_uuid          uuid,
  staff_code          text,
  person_name         text,
  role_title          text,
  is_active           boolean,
  works_at_id         uuid,
  works_at_name       text,
  payer_org_id        uuid,
  payer_org_name      text,
  account_id          uuid,
  account_holder_name text,
  account_number      text,
  ifsc_code           text,
  bank_name           text,
  branch_name         text,
  account_type        text,
  verified_at         timestamptz,
  effective_from      date,
  notes               text
)
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.user_has_permission('hr.payroll.bank.view') THEN
    RAISE EXCEPTION 'hr.payroll.bank.view is required to see employee bank accounts.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  SELECT s.id,
         s.staff_id::text,
         TRIM(BOTH FROM COALESCE(s.first_name, '') || ' ' || COALESCE(s.last_name, ''))::text,
         s.designation::text,
         COALESCE(s.is_active, false),
         i.id,
         i.name::text,
         o.id,
         o.name::text,
         b.id,
         b.account_holder_name,
         b.account_number,
         b.ifsc_code,
         b.bank_name,
         b.branch_name,
         b.account_type,
         b.verified_at,
         b.effective_from,
         b.notes
    FROM public.staff s
    JOIN public.institutions i ON i.id = s.institution_id
    LEFT JOIN public.hr_staff_payroll p ON p.staff_id = s.id
    LEFT JOIN public.hr_organizations o ON o.id = p.hr_organization_id
    LEFT JOIN public.hr_staff_bank_accounts b
           ON b.staff_id = s.id AND b.superseded_by IS NULL
   -- Active staff, plus anyone inactive who still has an account on file --
   -- a final settlement is paid to someone who has already left.
   WHERE (COALESCE(s.is_active, false) OR b.id IS NOT NULL)
     AND public.role_has_institution_access(s.institution_id)
   -- Unrecorded first, then recorded-but-unverified, then done.
   ORDER BY (b.id IS NOT NULL), (b.verified_at IS NOT NULL), i.name, 3;
END;
$function$;

REVOKE ALL ON FUNCTION public.hr_staff_bank_directory() FROM anon;
GRANT EXECUTE ON FUNCTION public.hr_staff_bank_directory() TO authenticated, service_role;

-- ===========================================================================
-- attendance month close RPCs (2026-08-22)
-- Source: 20260822020000 + 20260822030000
-- ===========================================================================
-- Freeze one institution-month: compute every staff member's day counts, then
-- close it.
--
-- THE COUNTS COME FROM hr_attendance_records, not from a calendar rule. The
-- evaluator already wrote WEEKLY_OFF from hr_shift_timings, so working days are
-- "days that are neither a weekly off nor a holiday" and cannot disagree with
-- what the attendance log shows. fn_prepare_payroll_period computes them a
-- different way (calendar minus Sundays minus holidays) and is wrong for this
-- organisation, where Saturday is a working day at all 14 institutions.

CREATE OR REPLACE FUNCTION public.fn_hr_compute_attendance_period_summary(p_period_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_period public.hr_attendance_periods;
  v_start  date;
  v_end    date;
  v_rows   integer;
BEGIN
  SELECT * INTO v_period FROM public.hr_attendance_periods WHERE id = p_period_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Attendance period not found: %', p_period_id USING ERRCODE = 'P0002';
  END IF;

  v_start := make_date(v_period.period_year, v_period.period_month, 1);
  v_end   := (v_start + interval '1 month - 1 day')::date;

  DELETE FROM public.hr_attendance_period_summaries WHERE period_id = p_period_id;

  WITH rec AS (
    SELECT r.employee_id,
           st.code,
           COALESCE(r.late_minutes, 0)    AS late_minutes,
           COALESCE(r.excused_minutes, 0) AS excused_minutes
      FROM public.hr_attendance_records r
      JOIN public.hr_attendance_status_types st ON st.id = r.status_type_id
     WHERE r.institution_id = v_period.institution_id
       AND r.work_date BETWEEN v_start AND v_end
  ),
  agg AS (
    SELECT employee_id,
           count(*)                                                   AS total_days,
           count(*) FILTER (WHERE code = 'WEEKLY_OFF')                AS weekly_off,
           count(*) FILTER (WHERE code = 'HOLIDAY')                   AS holiday,
           count(*) FILTER (WHERE code IN ('PRESENT','REGULARIZED'))  AS full_present,
           count(*) FILTER (WHERE code = 'HALF_DAY')                  AS half_day,
           count(*) FILTER (WHERE code = 'ABSENT')                    AS absent,
           count(*) FILTER (WHERE code IN ('ON_DUTY','on_clinical_posting')) AS on_duty,
           -- A day the evaluator could not judge. A payslip built on top of
           -- these should say so rather than quietly treat them as absent.
           count(*) FILTER (WHERE code NOT IN (
             'PRESENT','REGULARIZED','HALF_DAY','ABSENT','WEEKLY_OFF',
             'HOLIDAY','LEAVE','ON_DUTY','on_clinical_posting'))      AS unprocessed,
           sum(late_minutes)                                          AS late_minutes,
           sum(excused_minutes)                                       AS excused_minutes
      FROM rec
     GROUP BY employee_id
  ),
  -- Approved requests expanded to individual dates, then INTERSECTED with the
  -- attendance records: a leave that falls on a Sunday is not a leave day, and
  -- counting it from the application alone would inflate the total.
  req AS (
    SELECT la.employee_id,
           lt.leave_type_code,
           lt.is_paid,
           lt.request_category,
           g.d::date AS dt,
           CASE WHEN la.duration_type ILIKE '%half%' THEN 0.5 ELSE 1.0 END AS wt,
           la.start_time, la.end_time
      FROM public.hr_leave_applications la
      JOIN public.hr_leave_types lt ON lt.id = la.leave_type_id
      CROSS JOIN LATERAL generate_series(la.start_date, la.end_date, interval '1 day') g(d)
     WHERE la.status = 'approved'
       AND g.d::date BETWEEN v_start AND v_end
  ),
  req_effective AS (
    SELECT q.*
      FROM req q
      JOIN public.hr_attendance_records r
        ON r.employee_id = q.employee_id AND r.work_date = q.dt
      JOIN public.hr_attendance_status_types st ON st.id = r.status_type_id
     WHERE r.institution_id = v_period.institution_id
       AND st.code NOT IN ('WEEKLY_OFF', 'HOLIDAY')
  ),
  req_agg AS (
    SELECT employee_id,
           COALESCE(sum(wt) FILTER (WHERE request_category = 'leave' AND is_paid), 0)         AS paid_leave,
           COALESCE(sum(wt) FILTER (WHERE request_category = 'leave' AND NOT is_paid), 0)     AS unpaid_leave,
           COALESCE(sum(wt) FILTER (WHERE request_category = 'compensatory_off'), 0)          AS comp_off,
           COALESCE(sum(
             GREATEST(0, EXTRACT(EPOCH FROM (end_time - start_time)) / 60)
           ) FILTER (WHERE request_category = 'short_time_off'), 0)::int                      AS sto_minutes,
           COALESCE(
             jsonb_object_agg(leave_type_code, days)
               FILTER (WHERE request_category = 'leave' AND leave_type_code IS NOT NULL),
             '{}'::jsonb)                                                                     AS leave_by_type
      FROM (
        SELECT employee_id, request_category, is_paid, leave_type_code,
               start_time, end_time, wt,
               sum(wt) OVER (PARTITION BY employee_id, leave_type_code) AS days
          FROM req_effective
      ) x
     GROUP BY employee_id
  )
  INSERT INTO public.hr_attendance_period_summaries (
    period_id, staff_id, working_days, present_days, half_days, absent_days,
    weekly_off_days, holiday_days, leave_days, on_duty_days, comp_off_days,
    lop_days, payable_days, leave_by_type, short_time_off_minutes,
    late_minutes, excused_minutes, unprocessed_days
  )
  SELECT
    p_period_id,
    a.employee_id,
    (a.total_days - a.weekly_off - a.holiday)::numeric(5,1)                  AS working_days,
    (a.full_present + a.half_day * 0.5)::numeric(5,1)                        AS present_days,
    a.half_day,
    (a.absent + a.half_day * 0.5)::numeric(5,1)                              AS absent_days,
    a.weekly_off,
    a.holiday,
    (COALESCE(r.paid_leave, 0) + COALESCE(r.unpaid_leave, 0))::numeric(5,1)  AS leave_days,
    a.on_duty::numeric(5,1),
    COALESCE(r.comp_off, 0)::numeric(5,1),
    -- LOP: working days neither attended nor covered by a PAID absence.
    -- Unpaid leave is deliberately not subtracted -- that is what makes it
    -- unpaid.
    GREATEST(0, (a.total_days - a.weekly_off - a.holiday)
                - LEAST((a.total_days - a.weekly_off - a.holiday),
                        (a.full_present + a.half_day * 0.5)
                        + COALESCE(r.paid_leave, 0) + a.on_duty
                        + COALESCE(r.comp_off, 0)))::numeric(5,1)            AS lop_days,
    LEAST((a.total_days - a.weekly_off - a.holiday),
          (a.full_present + a.half_day * 0.5)
          + COALESCE(r.paid_leave, 0) + a.on_duty
          + COALESCE(r.comp_off, 0))::numeric(5,1)                           AS payable_days,
    COALESCE(r.leave_by_type, '{}'::jsonb),
    COALESCE(r.sto_minutes, 0),
    COALESCE(a.late_minutes, 0),
    COALESCE(a.excused_minutes, 0),
    a.unprocessed
  FROM agg a
  LEFT JOIN req_agg r ON r.employee_id = a.employee_id;

  GET DIAGNOSTICS v_rows = ROW_COUNT;

  -- Scheduled days and the pattern held, per person. See the section header.
  WITH staff_in AS (
    SELECT ps.staff_id, s.institution_id, s.category_id, ec.is_teaching, s.gender
      FROM public.hr_attendance_period_summaries ps
      JOIN public.staff s ON s.id = ps.staff_id
      JOIN public.employment_categories ec ON ec.id = s.category_id
     WHERE ps.period_id = p_period_id
  ),
  hol AS (
    SELECT h.holiday_date
      FROM public.fn_hr_calendar_holiday_dates(v_period.institution_id, v_start, v_end) h
  ),
  days AS (
    SELECT gs::date AS d FROM generate_series(v_start, v_end, interval '1 day') gs
  ),
  sched AS (
    SELECT si.staff_id,
           count(*) FILTER (
             WHERE COALESCE(
                     CASE WHEN (EXTRACT(ISODOW FROM dd.d) = 6
                                AND EXTRACT(DAY FROM dd.d) BETWEEN 8 AND 14
                                AND t.second_saturday_holiday) THEN false
                          ELSE t.is_working_day END,
                     false)
               AND NOT EXISTS (SELECT 1 FROM hol h WHERE h.holiday_date = dd.d)
           ) AS scheduled
      FROM staff_in si
      CROSS JOIN days dd
      LEFT JOIN LATERAL public.fn_shift_timing_pick(
        si.institution_id, si.category_id, si.is_teaching, si.gender,
        EXTRACT(ISODOW FROM dd.d)::smallint, dd.d,
        public.fn_staff_work_pattern_id(si.staff_id, dd.d)) t ON true
     GROUP BY si.staff_id
  ),
  pat AS (
    SELECT DISTINCT ON (a.staff_id) a.staff_id, a.work_pattern_id
      FROM public.hr_staff_work_pattern_assignments a
     WHERE a.effective_from <= v_end
       AND (a.effective_until IS NULL OR a.effective_until > v_start)
     ORDER BY a.staff_id, a.effective_from DESC
  )
  UPDATE public.hr_attendance_period_summaries ps
     SET scheduled_days  = sc.scheduled::numeric(5,1),
         work_pattern_id = pat.work_pattern_id
    FROM sched sc
    LEFT JOIN pat ON pat.staff_id = sc.staff_id
   WHERE ps.period_id = p_period_id
     AND ps.staff_id  = sc.staff_id;

  UPDATE public.hr_attendance_periods
     SET staff_count = v_rows,
         working_days_count = (
           SELECT max(working_days)::int
             FROM public.hr_attendance_period_summaries
            WHERE period_id = p_period_id
         ),
         updated_at = now()
   WHERE id = p_period_id;

  RETURN v_rows;
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_hr_compute_attendance_period_summary(uuid) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_hr_compute_attendance_period_summary(uuid) TO service_role;


-- Close an institution-month.
--
-- PENDING REQUESTS BLOCK THE LOCK. Locking a month with an undecided short
-- time off silently denies it: the employee applied, nobody answered, and the
-- day is counted absent forever. Refusing names the count so HR can go and
-- clear them.
--
-- THE FORCE PATH REJECTS, IT DOES NOT IGNORE. A month can otherwise be held
-- open indefinitely by one forgotten application. Forcing is super-admin-only,
-- demands a reason, and REJECTS the outstanding requests with that reason
-- stamped on them -- so the employee sees a decision instead of a request that
-- quietly stopped mattering. hr_trig_leave_enforce_approver returns early for a
-- super admin, so those rejections pass the approver gate, and
-- trg_hla_balance_update restores the balances on the way through.

CREATE OR REPLACE FUNCTION public.fn_hr_lock_attendance_period(
  p_institution_id uuid,
  p_year           integer,
  p_month          integer,
  p_force          boolean DEFAULT false,
  p_force_reason   text    DEFAULT NULL
)
RETURNS public.hr_attendance_periods
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_period   public.hr_attendance_periods;
  v_start    date;
  v_end      date;
  v_pending  integer;
  v_records  integer;
  v_is_sa    boolean := public.is_super_admin();
BEGIN
  IF NOT (v_is_sa OR public.user_has_permission('hr.attendance.period.manage')) THEN
    RAISE EXCEPTION 'hr.attendance.period.manage is required to close an attendance month.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_month < 1 OR p_month > 12 THEN
    RAISE EXCEPTION 'Month must be 1-12, got %', p_month USING ERRCODE = '22023';
  END IF;

  v_start := make_date(p_year, p_month, 1);
  v_end   := (v_start + interval '1 month - 1 day')::date;

  -- Refuse to close a month that has nothing in it. An empty close would
  -- freeze a set of zeroes and read as "everyone was absent".
  SELECT count(*) INTO v_records
    FROM public.hr_attendance_records
   WHERE institution_id = p_institution_id
     AND work_date BETWEEN v_start AND v_end;

  IF v_records = 0 THEN
    RAISE EXCEPTION 'No attendance records for that institution in %-%. Import the biometric data first.',
      p_year, lpad(p_month::text, 2, '0')
      USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.hr_attendance_periods (
    institution_id, period_year, period_month, status, created_by, updated_by
  ) VALUES (p_institution_id, p_year, p_month, 'open', auth.uid(), auth.uid())
  ON CONFLICT (institution_id, period_year, period_month) DO NOTHING;

  SELECT * INTO v_period
    FROM public.hr_attendance_periods
   WHERE institution_id = p_institution_id
     AND period_year = p_year AND period_month = p_month
   FOR UPDATE;

  IF v_period.status = 'locked' THEN
    RAISE EXCEPTION 'That attendance month is already closed (locked %).',
      to_char(v_period.locked_at, 'DD Mon YYYY') USING ERRCODE = 'P0001';
  END IF;

  -- Undecided requests overlapping the month, for staff of this institution.
  SELECT count(*) INTO v_pending
    FROM public.hr_leave_applications la
    JOIN public.staff s ON s.id = la.employee_id
   WHERE s.institution_id = p_institution_id
     AND la.status = 'pending'
     AND la.start_date <= v_end AND la.end_date >= v_start;

  IF v_pending > 0 AND NOT p_force THEN
    RAISE EXCEPTION
      '% request(s) for this month are still awaiting a decision. Clear them in Leave Approvals, or close with an override.',
      v_pending
      USING ERRCODE = 'P0001';
  END IF;

  IF v_pending > 0 AND p_force THEN
    IF NOT v_is_sa THEN
      RAISE EXCEPTION 'Only a Super Administrator may close a month over % outstanding request(s).', v_pending
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF p_force_reason IS NULL OR length(trim(p_force_reason)) = 0 THEN
      RAISE EXCEPTION 'A reason is required to close a month over outstanding requests.'
        USING ERRCODE = '22023';
    END IF;

    UPDATE public.hr_leave_applications la
       SET status = 'rejected',
           final_approver_id = auth.uid(),
           final_decided_at = now(),
           updated_at = now()
      FROM public.staff s
     WHERE s.id = la.employee_id
       AND s.institution_id = p_institution_id
       AND la.status = 'pending'
       AND la.start_date <= v_end AND la.end_date >= v_start;
  END IF;

  PERFORM public.fn_hr_compute_attendance_period_summary(v_period.id);

  UPDATE public.hr_attendance_periods
     SET status = 'locked',
         locked_at = now(),
         locked_by = auth.uid(),
         forced = (v_pending > 0 AND p_force),
         force_reason = CASE WHEN v_pending > 0 AND p_force THEN trim(p_force_reason) END,
         updated_by = auth.uid()
   WHERE id = v_period.id
  RETURNING * INTO v_period;

  RETURN v_period;
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_hr_lock_attendance_period(uuid, integer, integer, boolean, text) FROM anon;
GRANT EXECUTE ON FUNCTION public.fn_hr_lock_attendance_period(uuid, integer, integer, boolean, text) TO authenticated, service_role;


-- Reopen a closed month. SUPER ADMIN ONLY, reason required.
--
-- Deliberately narrower than closing it. Reopening lets the day counts move
-- again underneath anything already generated from them, so it is not an HR
-- Head action -- and the frozen summaries are DELETED rather than kept, because
-- a stale summary beside a reopened month is worse than none.
CREATE OR REPLACE FUNCTION public.fn_hr_reopen_attendance_period(
  p_period_id uuid,
  p_reason    text
)
RETURNS public.hr_attendance_periods
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_period public.hr_attendance_periods;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Only a Super Administrator may reopen a closed attendance month.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_reason IS NULL OR length(trim(p_reason)) = 0 THEN
    RAISE EXCEPTION 'A reason is required to reopen a closed month.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_period FROM public.hr_attendance_periods WHERE id = p_period_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Attendance period not found.' USING ERRCODE = 'P0002';
  END IF;
  IF v_period.status <> 'locked' THEN
    RAISE EXCEPTION 'That month is not closed.' USING ERRCODE = 'P0001';
  END IF;

  DELETE FROM public.hr_attendance_period_summaries WHERE period_id = p_period_id;

  UPDATE public.hr_attendance_periods
     SET status = 'open',
         locked_at = NULL,
         locked_by = NULL,
         reopened_at = now(),
         reopened_by = auth.uid(),
         reopen_reason = trim(p_reason),
         staff_count = NULL,
         working_days_count = NULL,
         updated_by = auth.uid()
   WHERE id = p_period_id
  RETURNING * INTO v_period;

  RETURN v_period;
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_hr_reopen_attendance_period(uuid, text) FROM anon;
GRANT EXECUTE ON FUNCTION public.fn_hr_reopen_attendance_period(uuid, text) TO authenticated, service_role;


-- Every institution's state for one month -- what the HR Head console lists.
--
-- Institutions with NO attendance data still appear, with zeroes. A month that
-- silently omits an institution reads as "done" when it means "never imported",
-- which is the failure this console exists to make visible.
CREATE OR REPLACE FUNCTION public.hr_attendance_period_console(
  p_year  integer,
  p_month integer
)
RETURNS TABLE(
  institution_id   uuid,
  institution_name text,
  period_id        uuid,
  status           text,
  locked_at        timestamptz,
  forced           boolean,
  staff_with_records integer,
  record_count       integer,
  pending_requests   integer,
  approved_requests  integer,
  unprocessed_days   integer
)
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_start date := make_date(p_year, p_month, 1);
  v_end   date := (make_date(p_year, p_month, 1) + interval '1 month - 1 day')::date;
BEGIN
  IF NOT (public.is_super_admin()
          OR public.user_has_permission('hr.attendance.period.view')) THEN
    RAISE EXCEPTION 'hr.attendance.period.view is required to see the attendance close console.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  SELECT i.id,
         i.name::text,
         ap.id,
         COALESCE(ap.status, 'open')::text,
         ap.locked_at,
         COALESCE(ap.forced, false),
         COALESCE(r.staff_ct, 0)::int,
         COALESCE(r.rec_ct, 0)::int,
         COALESCE(q.pending_ct, 0)::int,
         COALESCE(q.approved_ct, 0)::int,
         COALESCE(r.unprocessed_ct, 0)::int
    FROM public.institutions i
    LEFT JOIN public.hr_attendance_periods ap
           ON ap.institution_id = i.id
          AND ap.period_year = p_year AND ap.period_month = p_month
    LEFT JOIN LATERAL (
      SELECT count(DISTINCT rr.employee_id) AS staff_ct,
             count(*)                       AS rec_ct,
             count(*) FILTER (WHERE st.code NOT IN (
               'PRESENT','REGULARIZED','HALF_DAY','ABSENT','WEEKLY_OFF',
               'HOLIDAY','LEAVE','ON_DUTY','on_clinical_posting')) AS unprocessed_ct
        FROM public.hr_attendance_records rr
        JOIN public.hr_attendance_status_types st ON st.id = rr.status_type_id
       WHERE rr.institution_id = i.id
         AND rr.work_date BETWEEN v_start AND v_end
    ) r ON true
    LEFT JOIN LATERAL (
      SELECT count(*) FILTER (WHERE la.status = 'pending')  AS pending_ct,
             count(*) FILTER (WHERE la.status = 'approved') AS approved_ct
        FROM public.hr_leave_applications la
        JOIN public.staff s ON s.id = la.employee_id
       WHERE s.institution_id = i.id
         AND la.start_date <= v_end AND la.end_date >= v_start
    ) q ON true
   WHERE public.role_has_institution_access(i.id)
   ORDER BY (COALESCE(r.rec_ct, 0) = 0), i.name;
END;
$function$;

REVOKE ALL ON FUNCTION public.hr_attendance_period_console(integer, integer) FROM anon;
GRANT EXECUTE ON FUNCTION public.hr_attendance_period_console(integer, integer) TO authenticated, service_role;

-- ===========================================================================
-- attendance close: count 'escalated' as outstanding (2026-08-22)
-- Source: 20260822060000_hr_attendance_period_console_count_escalated.sql
-- ===========================================================================
-- Count ESCALATED requests as outstanding, not just 'pending'.
--
-- hr_leave_approval_queue selects status IN ('pending','escalated') -- an
-- escalated request has been pushed up a level and is still waiting on somebody.
-- This console counted only 'pending', so an escalated request would have been
-- invisible here AND would not have blocked the close: the month would freeze
-- with a live request inside it, and the trigger would then refuse the very
-- decision the approver had been escalated to make.
--
-- There are no escalated rows in the data today, which is exactly why this was
-- worth fixing before there are.
--
-- fn_hr_lock_attendance_period is restated with the same predicate. The button
-- and the server must refuse on the same set, or one enables what the other
-- rejects.
--
-- The remaining difference from the approvals SCREEN is deliberate and is not a
-- bug: that screen is not date-filtered, because an approver must see a request
-- dated next month, while a close only counts requests overlapping the month
-- being closed. Following an unscoped link showed 141 outstanding for Dental
-- where the close screen said 67. The console links now carry
-- ?institution=&from=&to= so the two agree.

DROP FUNCTION IF EXISTS public.hr_attendance_period_console(integer, integer);

CREATE OR REPLACE FUNCTION public.hr_attendance_period_console(
  p_year  integer,
  p_month integer
)
RETURNS TABLE(
  institution_id      uuid,
  institution_name    text,
  period_id           uuid,
  status              text,
  locked_at           timestamptz,
  forced              boolean,
  staff_with_records  integer,
  record_count        integer,
  pending_total       integer,
  pending_leave       integer,
  pending_short_time_off integer,
  pending_comp_off    integer,
  approved_leave      integer,
  approved_short_time_off integer,
  approved_comp_off   integer,
  unprocessed_days    integer
)
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_start date := make_date(p_year, p_month, 1);
  v_end   date := (make_date(p_year, p_month, 1) + interval '1 month - 1 day')::date;
BEGIN
  IF NOT (public.is_super_admin()
          OR public.user_has_permission('hr.attendance.period.view')) THEN
    RAISE EXCEPTION 'hr.attendance.period.view is required to see the attendance close console.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  SELECT i.id,
         i.name::text,
         ap.id,
         COALESCE(ap.status, 'open')::text,
         ap.locked_at,
         COALESCE(ap.forced, false),
         COALESCE(r.staff_ct, 0)::int,
         COALESCE(r.rec_ct, 0)::int,
         COALESCE(q.p_total, 0)::int,
         COALESCE(q.p_leave, 0)::int,
         COALESCE(q.p_sto, 0)::int,
         COALESCE(q.p_comp, 0)::int,
         COALESCE(q.a_leave, 0)::int,
         COALESCE(q.a_sto, 0)::int,
         COALESCE(q.a_comp, 0)::int,
         COALESCE(r.unprocessed_ct, 0)::int
    FROM public.institutions i
    LEFT JOIN public.hr_attendance_periods ap
           ON ap.institution_id = i.id
          AND ap.period_year = p_year AND ap.period_month = p_month
    LEFT JOIN LATERAL (
      SELECT count(DISTINCT rr.employee_id) AS staff_ct,
             count(*)                       AS rec_ct,
             count(*) FILTER (WHERE st.code NOT IN (
               'PRESENT','REGULARIZED','HALF_DAY','ABSENT','WEEKLY_OFF',
               'HOLIDAY','LEAVE','ON_DUTY','on_clinical_posting')) AS unprocessed_ct
        FROM public.hr_attendance_records rr
        JOIN public.hr_attendance_status_types st ON st.id = rr.status_type_id
       WHERE rr.institution_id = i.id
         AND rr.work_date BETWEEN v_start AND v_end
    ) r ON true
    LEFT JOIN LATERAL (
      SELECT
        count(*) FILTER (WHERE la.status IN ('pending','escalated'))  AS p_total,
        count(*) FILTER (WHERE la.status IN ('pending','escalated') AND lt.request_category = 'leave')             AS p_leave,
        count(*) FILTER (WHERE la.status IN ('pending','escalated') AND lt.request_category = 'short_time_off')    AS p_sto,
        count(*) FILTER (WHERE la.status IN ('pending','escalated') AND lt.request_category = 'compensatory_off')  AS p_comp,
        count(*) FILTER (WHERE la.status = 'approved' AND lt.request_category = 'leave')             AS a_leave,
        count(*) FILTER (WHERE la.status = 'approved' AND lt.request_category = 'short_time_off')    AS a_sto,
        count(*) FILTER (WHERE la.status = 'approved' AND lt.request_category = 'compensatory_off')  AS a_comp
        FROM public.hr_leave_applications la
        JOIN public.hr_leave_types lt ON lt.id = la.leave_type_id
        JOIN public.staff s ON s.id = la.employee_id
       WHERE s.institution_id = i.id
         AND la.start_date <= v_end AND la.end_date >= v_start
    ) q ON true
   WHERE public.role_has_institution_access(i.id)
   -- Institutions with no data first (they need importing), then the ones still
   -- blocked by outstanding requests, then the ones ready to close.
   ORDER BY (COALESCE(r.rec_ct, 0) = 0) DESC,
            (COALESCE(q.p_total, 0) > 0) DESC,
            i.name;
END;
$function$;

